const HEROD_NPC_SCARLET_TRAINEE: u32 = 6575;
const HEROD_TEMPSUMMON_DEAD_DESPAWN: u32 = 7;
const HEROD_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN: u32 = 1;

/// `boss_herodAI` state (fork member order).
#[allow(clippy::struct_excessive_bools)] // fork member-for-member
pub(crate) struct HerodAi {
    enrage: bool,
    trainee_say: bool,
    whirlwind: bool,
    myrmidons_spawned: bool,
    nb_trainee: u8,
    rushing_charge_timer_ms: u32,
    cleave_timer_ms: u32,
    whirlwind_timer_ms: u32,
    root_timer_ms: u32,
    room_check_ms: u32,
    myrmidon_guids: Vec<ObjectGuid>,
}

impl HerodAi {
    fn new() -> Self {
        Self {
            enrage: false,
            trainee_say: false,
            whirlwind: false,
            myrmidons_spawned: false,
            nb_trainee: 0,
            rushing_charge_timer_ms: 1500,
            cleave_timer_ms: 12_000,
            whirlwind_timer_ms: 0, // rolled by `herod_reset` (needs RNG)
            root_timer_ms: 0,
            room_check_ms: 500,
            myrmidon_guids: Vec::new(),
        }
    }

    /// `Reset()` fields (the `urand` roll runs in the caller).
    fn reset_fields(&mut self) {
        self.enrage = false;
        self.trainee_say = false;
        self.whirlwind = false;
        self.nb_trainee = 0;
        self.rushing_charge_timer_ms = 1500;
        self.cleave_timer_ms = 12_000;
        self.root_timer_ms = 0;
        self.room_check_ms = 500;
        self.myrmidons_spawned = false;
    }
}

/// `mob_scarlet_traineeAI` state. The ctor `urand(1000, 6000)`
/// start roll runs in the first `reset` dispatch (fork `Reset`
/// itself never re-rolls).
#[allow(clippy::struct_excessive_bools)] // fork member-for-member
pub(crate) struct ScarletTraineeAi {
    has_fled: bool,
    start_timer_ms: u32,
    start_rolled: bool,
    group1: bool,
    group2: bool,
}

impl ScarletTraineeAi {
    fn new() -> Self {
        Self {
            has_fled: false,
            start_timer_ms: 0,
            start_rolled: false,
            group1: false,
            group2: false,
        }
    }
}

