// ===== lane cai_bwl (consts + state) =====
#[allow(dead_code)] // used by undispatched hooks (step-3 remainder)
pub(crate) const BWL_NOT_STARTED: u32 = 0;
#[allow(dead_code)] // used by undispatched hooks (step-3 remainder)
const VAEL_SAY_LINE_1: i32 = 9886;
// Scratch transcription: Blackwing Lair CreatureAI scripts -> Rust (Tier 3).
// Fork files: vmangos/src/scripts/eastern_kingdoms/burning_steppes/
//   blackwing_lair/{boss_broodlord_lashlayer, boss_chromaggus, boss_ebonroc,
//   boss_firemaw, boss_flamegor, boss_nefarian, boss_razorgore,
//   boss_vaelastrasz, boss_victor_nefarius}.cpp (+ blackwing_lair.h).
// Mirror: content.rs CreatureScriptAi/for_script, HerodAi/ScarletTrainee
//   patterns, script_combat_drive, do_cast_spell_if_can, instance_* accessors.
//
// Per script: {script_name, suggested CreatureScriptAi variant, state struct, hooks}
// - boss_broodlord        -> Broodlord          -> BroodlordAi          -> reset, aggro, just_died, just_reached_home(*), move_in_line_of_sight(*), spell_hit(*), update
// - boss_chromaggus       -> Chromaggus         -> ChromaggusAi         -> reset, aggro, just_died, just_reached_home(*), movement_inform, update (SpellHitTarget fork body is empty)
// - boss_ebonroc          -> Ebonroc            -> EbonrocAi            -> reset, aggro, just_died, just_reached_home(*), spell_hit(*), update
// - boss_firemaw          -> Firemaw            -> FiremawAi            -> reset, aggro, just_died, just_reached_home(*), spell_hit(*), update
// - boss_flamegor         -> Flamegor           -> FlamegorAi           -> reset, aggro, just_died, just_reached_home(*), spell_hit(*), update
// - boss_nefarian         -> Nefarian           -> NefarianAi           -> reset, killed_unit, just_died, enter_evade, just_summoned, movement_inform, update
// - npc_corrupted_totem   -> CorruptedTotem     -> CorruptedTotemAi     -> reset, aggro, just_died, update
// - boss_razorgore        -> Razorgore          -> RazorgoreAi          -> reset, enter_combat(*), just_died, just_reached_home(*), spell_hit(*), attack_start(*), update
// - trigger_orb_of_command -> TriggerOrbOfCommand -> TriggerOrbAi       -> reset, update
// - boss_vaelastrasz      -> Vaelastrasz        -> VaelastraszAi        -> reset, killed_unit, aggro, just_died, just_reached_home(*), update (+ begin_speech helper, gossip-driven)
// - npc_death_talon_Captain -> DeathTalonCaptain -> DeathTalonCaptainAi -> reset, aggro, just_died, move_in_line_of_sight(*), update
// - npc_death_talon_Seether -> DeathTalonSeether -> DeathTalonSeetherAi -> reset, update
// - boss_victor_nefarius  -> VictorNefarius     -> VictorNefariusAi     -> reset, aggro, just_reached_home(*), just_summoned, summoned_creature_just_died(*), update
// (*) = transcribed in the naming shape but has NO-DISPATCHER-YET (integrator adds dispatch).
//
// Reused from content.rs (NOT redefined): DONE, IN_PROGRESS, GO_STATE_ACTIVE,
//   BWL_TYPE_* (all 10), BWL_DATA_* guid/door consts, BWL_NPC_* (entries that
//   exist), BWL_FAIL, BWL_MOVE_PATHFINDING, BWL_UNIT_FLAG_SPAWNING,
//   BWL_UNIT_FLAG_IMMUNE_TO_NPC, BWL_UNIT_FLAG_NOT_SELECTABLE, BWL_EGGS_COUNT,
//   STAND_STATE_STAND, CastTarget, CastOptions, CastOutcome, Position, offsets,
//   script_combat_drive, do_cast_spell_if_can, do_script_text, summon_creature,
//   instance_set_data, instance_get_data, instance_get_data64, set_in_combat_with_zone,
//   attack_start, add_threat, modify_threat_percent_of, threat_on,
//   unit_victim, unit_is_alive, unit_position, object_position, object_get_field,
//   object_set_field, unit_set_byte, unit_base_mut, object_entry, bot_has_aura,
//   bot_casting_spell, apply_aura_by_id, cancel_aura, cast_spell,
//   set_walk, stop_moving, creature_move_point, creature_move_chase,
//   creature_move_home, can_reach_melee, handle_emote_command,
//   teleport_unit_within_map, enter_evade_mode, ai_in_combat, blackwing_lair(),
//   go_state.

// Shared EncounterState values with no BWL const in content.rs (BWL_FAIL
// precedent: shared BWL_ const, not per-script).
