/// invader scripts; the `m_uiEventIndex` ctor arg becomes one ctor per script.
pub(crate) struct InvaderAi {
    event_index: u32,
    chilled_timer_ms: u32,
    shock_timer_ms: u32,
    knockdown_timer_ms: u32,
    whirlwind_timer_ms: u32,
    blast_wave_timer_ms: u32,
    shield_timer_ms: u32,
}

impl InvaderAi {
    fn new_water() -> Self {
        Self::with_index(INVADER_EVENT_WATER)
    }
    fn new_air() -> Self {
        Self::with_index(INVADER_EVENT_AIR)
    }
    fn new_fire() -> Self {
        Self::with_index(INVADER_EVENT_FIRE)
    }
    fn new_earth() -> Self {
        Self::with_index(INVADER_EVENT_EARTH)
    }
    fn with_index(index: u32) -> Self {
        Self {
            event_index: index,
            chilled_timer_ms: 0,
            shock_timer_ms: 0,
            knockdown_timer_ms: 0,
            whirlwind_timer_ms: 0,
            blast_wave_timer_ms: 0,
            shield_timer_ms: 0,
        }
    }
}

