/// `npc_infantrymanAI` + subclass state (`world_event_wareffort.cpp` 836-858,
/// 1062-1151), shared by the four infantry scripts; `kind` selects the origin
/// and emote (0 ironforge, 1 orgrimmar, 2 rifleman, 3 priestess).
/// `m_ReadyEmoteState` values need the emote-state table (NOTE-7). The priestess
/// shadow `m_movedIntoPosition` is write-only in the fork (dropped).
pub(crate) struct InfantrymanAi {
    kind: u32,
    moved_into_position: bool,
    clockwise: bool,
    ready_emote: u32,
    saurfang_dist: f32,
    saurfang_angle: f32,
    following_saurfang: bool,
    saurfang_guid: Option<ObjectGuid>,
    priest_index: u8,
}

impl InfantrymanAi {
    fn new_ironforge() -> Self {
        Self::with_kind(0, true)
    }
    fn new_orgrimmar() -> Self {
        Self::with_kind(1, false)
    }
    fn new_rifleman() -> Self {
        Self::with_kind(2, false)
    }
    fn new_priestess() -> Self {
        Self::with_kind(3, true)
    }
    fn with_kind(kind: u32, clockwise: bool) -> Self {
        Self {
            kind,
            moved_into_position: false,
            clockwise,
            // NEEDS-MAP-HELPER: `EMOTE_STATE_READY1H/READY2H/READYRIFLE/AT_EASE`
            // values for the per-kind `m_ReadyEmoteState`.
            ready_emote: 0,
            saurfang_dist: 0.0,
            saurfang_angle: 0.0,
            following_saurfang: false,
            saurfang_guid: None,
            priest_index: 0,
        }
    }
    /// Home-march origin per kind (`world_event_wareffort.cpp` 1065/1076/1088):
    /// ironforge (-6969.21, 962.33, 11.88), orgrimmar/rifleman
    /// (-6975.30, 940.14, 13.14); priestess has none (follows its own index).
    fn origin(kind: u32) -> (f32, f32, f32) {
        match kind {
            0 => (-6_969.21, 962.33, 11.88),
            1 | 2 => (-6_975.30, 940.14, 13.14),
            _ => (0.0, 0.0, 0.0),
        }
    }
}

