/// `instance_dire_maul` state (`m_auiEncounter` + GUID registry +
/// `strInstData`, cpp 17-40 + header 126-170).
/// `m_uiTendrisGUID` / `m_uiOldIronbarkGUID` /
/// `m_uiCaptainKromcrushGUID` / `m_lTendrisProtectorsMobGUIDList`
/// are cached by the fork but never read back (cpp only writes
/// them); `m_uiBrokenTrapGUID` is only read by `OnPlayerEnter`,
/// which has no Rust dispatcher. All five are dropped so no
/// never-read field trips `clippy -D warnings`.
pub(crate) struct DireMaulState {
    encounter: [u32; DM_MAX_ENCOUNTER],
    cristals: [ObjectGuid; DM_MAX_CRISTALS],
    cristals_sorted: [Vec<ObjectGuid>; DM_MAX_CRISTALS],
    cristal_mobs: Vec<ObjectGuid>,
    immol_thar_gardiens: Vec<ObjectGuid>,
    door_alzzin_in: ObjectGuid,
    crumble_wall: ObjectGuid,
    corrupt_vine: ObjectGuid,
    felvine_shards: Vec<ObjectGuid>,
    magic_vortex: ObjectGuid,
    force_field: ObjectGuid,
    immol_thar: ObjectGuid,
    tortheldrin: ObjectGuid,
    ritual_candle_aura: ObjectGuid,
    ritual_player: ObjectGuid,
    slipkik: ObjectGuid,
    king_gordok: ObjectGuid,
    chorush: ObjectGuid,
    tribute: [ObjectGuid; 7],
    guard_alive_count: u32,
    tribute_respawned: bool,
    tannin_looted: bool,
    broken_trap: ObjectGuid,
    save_string: String,
}

impl DireMaulState {
    pub(crate) fn new() -> Self {
        Self {
            // `Initialize` (cpp 35-40) + ctor defaults (cpp 17-31).
            encounter: [0; DM_MAX_ENCOUNTER],
            cristals: [ObjectGuid::EMPTY; DM_MAX_CRISTALS],
            cristals_sorted: [Vec::new(), Vec::new(), Vec::new(), Vec::new(), Vec::new()],
            cristal_mobs: Vec::new(),
            immol_thar_gardiens: Vec::new(),
            door_alzzin_in: ObjectGuid::EMPTY,
            crumble_wall: ObjectGuid::EMPTY,
            corrupt_vine: ObjectGuid::EMPTY,
            felvine_shards: Vec::new(),
            magic_vortex: ObjectGuid::EMPTY,
            force_field: ObjectGuid::EMPTY,
            immol_thar: ObjectGuid::EMPTY,
            tortheldrin: ObjectGuid::EMPTY,
            ritual_candle_aura: ObjectGuid::EMPTY,
            ritual_player: ObjectGuid::EMPTY,
            slipkik: ObjectGuid::EMPTY,
            king_gordok: ObjectGuid::EMPTY,
            chorush: ObjectGuid::EMPTY,
            tribute: [ObjectGuid::EMPTY; 7],
            guard_alive_count: 6,
            tribute_respawned: false,
            tannin_looted: false,
            broken_trap: ObjectGuid::EMPTY,
            save_string: String::new(),
        }
    }
}

