/// registry + `m_lVaelGobs` + `strInstData`). `m_uiWyrmPackComposition`
/// (write-only) and `m_hBlackwingTechnicians` (threat-list helper, no `Map`
/// equivalent) are not mirrored. Has `save_string` because the C++ overrides
/// `Save()` (cached string, recomputed in `bwl_set_data`).
pub(crate) struct BlackwingLairState {
    encounter: [u32; BWL_MAX_ENCOUNTER],
    razorgore: ObjectGuid,
    vaelastrasz: ObjectGuid,
    lashlayer: ObjectGuid,
    firemaw: ObjectGuid,
    ebonroc: ObjectGuid,
    flamegor: ObjectGuid,
    chromaggus: ObjectGuid,
    nefarian: ObjectGuid,
    nefarius: ObjectGuid,
    gretok: ObjectGuid,
    trigger: ObjectGuid,
    orb_of_domination: ObjectGuid,
    door_razorgore_enter: ObjectGuid,
    door_razorgore_exit: ObjectGuid,
    door_vaelastrasz: ObjectGuid,
    door_lashlayer: ObjectGuid,
    door_chromaggus_enter: ObjectGuid,
    door_chromaggus_exit: ObjectGuid,
    door_chromaggus_side: ObjectGuid,
    door_nefarian: ObjectGuid,
    scepter_champion: ObjectGuid,
    // No `DATA_EGG` state field: the fork slot is only ever read through
    // `GetData64(DATA_EGG)`, which cannot ride `Option<ObjectGuid>` (see
    // unresolved), and it is not part of the save stream.
    how_egg: u32,
    chrom_breath: u32,
    nef_color: u32,
    colors_rolled: bool,
    scepter_run_time: u32,
    vael_gobs: Vec<ObjectGuid>,
    save_string: String,
}

impl BlackwingLairState {
    pub(crate) fn new() -> Self {
        Self {
            encounter: [0; BWL_MAX_ENCOUNTER],
            razorgore: ObjectGuid::EMPTY,
            vaelastrasz: ObjectGuid::EMPTY,
            lashlayer: ObjectGuid::EMPTY,
            firemaw: ObjectGuid::EMPTY,
            ebonroc: ObjectGuid::EMPTY,
            flamegor: ObjectGuid::EMPTY,
            chromaggus: ObjectGuid::EMPTY,
            nefarian: ObjectGuid::EMPTY,
            nefarius: ObjectGuid::EMPTY,
            gretok: ObjectGuid::EMPTY,
            trigger: ObjectGuid::EMPTY,
            orb_of_domination: ObjectGuid::EMPTY,
            door_razorgore_enter: ObjectGuid::EMPTY,
            door_razorgore_exit: ObjectGuid::EMPTY,
            door_vaelastrasz: ObjectGuid::EMPTY,
            door_lashlayer: ObjectGuid::EMPTY,
            door_chromaggus_enter: ObjectGuid::EMPTY,
            door_chromaggus_exit: ObjectGuid::EMPTY,
            door_chromaggus_side: ObjectGuid::EMPTY,
            door_nefarian: ObjectGuid::EMPTY,
            scepter_champion: ObjectGuid::EMPTY,
            how_egg: 0,
            // Fork `Initialize` rolls `urand(0, 19)` for both (cpp 190-191);
            // `new()` has no RNG, so the roll is lazy (first
            // creature create; skipped after `Load`).
            chrom_breath: 0,
            nef_color: 0,
            colors_rolled: false,
            scepter_run_time: 0,
            vael_gobs: Vec::new(),
            save_string: String::new(),
        }
    }
}

