    /// `InstanceData::OnCreatureCreate` dispatch.
    pub(crate) fn instance_on_creature_create(&mut self, guid: ObjectGuid) {
        match self.instance_kind() {
            Some(InstanceKind::Deadmines) => self.deadmines_on_creature_create(guid),
            Some(InstanceKind::ShadowfangKeep) => self.sfk_on_creature_create(guid),
            Some(InstanceKind::WailingCaverns) => self.wc_on_creature_create(guid),
            Some(InstanceKind::RazorfenKraul) => self.rfk_on_creature_create(guid),
            Some(InstanceKind::Maraudon) => self.mar_on_creature_create(guid),
            Some(InstanceKind::Scholomance) => self.sch_on_creature_create(guid),
            Some(InstanceKind::Gnomeregan) => self.gno_on_creature_create(guid),
            Some(InstanceKind::ZulFarrak) => self.zf_on_creature_create(guid),
            Some(InstanceKind::BlackfathomDeeps) => self.bfd_on_creature_create(guid),
            Some(InstanceKind::ScarletMonastery) => self.sm_on_creature_create(guid),
            Some(InstanceKind::ZulGurub) => self.zg_on_creature_create(guid),
            Some(InstanceKind::Uldaman) => self.uld_on_creature_create(guid),
            Some(InstanceKind::SunkenTemple) => self.st_on_creature_create(guid),
            Some(InstanceKind::RuinsOfAhnqiraj) => self.aq20_on_creature_create(guid),
            Some(InstanceKind::MoltenCore) => self.mc_on_creature_create(guid),
            Some(InstanceKind::BlackrockSpire) => self.brs_on_creature_create(guid),
            Some(InstanceKind::TempleOfAhnqiraj) => self.aq40_on_creature_create(guid),
            Some(InstanceKind::Stratholme) => self.strat_on_creature_create(guid),
            Some(InstanceKind::BlackrockDepths) => self.brd_on_creature_create(guid),
            Some(InstanceKind::DireMaul) => self.dm_on_creature_create(guid),
            Some(InstanceKind::BlackwingLair) => self.bwl_on_creature_create(guid),
            Some(InstanceKind::Naxxramas) => self.naxx_on_creature_create(guid),
            Some(InstanceKind::RazorfenDowns | InstanceKind::OnyxiaLair) | None => {}
        }
    }

