    /// `InstanceData::CustomSpellCasted` dispatch; the
    /// fork's only call site is the hardcoded spell 27517
    /// dummy arm (`SpellEffects.cpp:567`).
    pub(crate) fn instance_custom_spell_casted(&mut self, spell_id: u32, caster: ObjectGuid) {
        if self.instance_kind() != Some(InstanceKind::BlackrockDepths) || spell_id != 27_517 {
            return;
        }
        if !caster.is_player() {
            return;
        }
        let fresh = match self.blackrock_depths_mut() {
            Some(s) if !s.is_theldren_invocated => {
                s.is_theldren_invocated = true;
                true
            }
            _ => false,
        };
        if fresh {
            self.brd_begin_theldren_event(caster);
        }
    }

    /// `Player::DestroyItemCount(item, count, true)` over
    /// the saved inventory rows (fork walk order from
    /// `quest_destroy_candidates`); persists through
    /// `SetItemCount` like cast-item consumption.
    fn destroy_player_item_count(&mut self, player: ObjectGuid, item_id: u32, mut count: u32) {
        let events = {
            let Some(entry) = self.players.get_mut(&player) else {
                return;
            };
            let mut events = Vec::new();
            for (item_guid, stack) in entry.player.quest_destroy_candidates(item_id) {
                if count == 0 {
                    break;
                }
                let take = stack.min(count);
                let new_count = stack - take;
                count -= take;
                if let Some(inv) = entry
                    .player
                    .saved
                    .inventory
                    .iter_mut()
                    .find(|inv| inv.item.item_guid == item_guid)
                {
                    inv.item.count = new_count;
                }
                events.push(crate::map::MapEvent::SetItemCount {
                    item_guid,
                    count: new_count,
                });
            }
            entry
                .player
                .saved
                .inventory
                .retain(|inv| inv.item.count != 0);
            events
        };
        self.events.extend(events);
    }

    // ------------------------------------------------ instance: deadmines

    /// `instance_deadmines::OnCreatureCreate`.
    fn deadmines_on_creature_create(&mut self, guid: ObjectGuid) {
        if self.deadmines().is_none() {
            return;
        }
        let delay = self
            .creatures
            .get(&guid)
            .and_then(|c| c.data.as_ref())
            .map_or(0, |d| d.spawntimesecsmin);
        if delay == 43199 || delay == 43201 {
            self.hidden_objects.insert(guid);
            let _ = self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE), 35);
        }
    }

    /// `instance_deadmines::OnObjectCreate`.
    fn deadmines_on_object_create(&mut self, guid: ObjectGuid) {
        if self.deadmines().is_none() {
            return;
        }
        if self.object_entry(guid) == Some(GO_DMF_CHEST) {
            self.hidden_objects.insert(guid);
        }
    }

    /// `instance_deadmines::OnCreatureDeath`.
    fn deadmines_on_creature_death(&mut self, victim: ObjectGuid) {
        if self.deadmines().is_none() {
            return;
        }
        let (entry, pos) = match self.creatures.get(&victim) {
            Some(c) => (c.info.entry, c.unit.world.position()),
            None => return,
        };
        let door = match entry {
            NPC_RHAHKZOR => {
                if let Some(dm) = self.deadmines_mut() {
                    dm.rhahk_dead = true;
                    dm.rhahk_patrol_ms = 60_000;
                    dm.rhahk_death_pos = pos;
                }
                self.find_gameobject(GO_DOOR1, None)
            }
            NPC_SNEED => self.find_gameobject(GO_DOOR2, Some((-291.0, -290.0))),
            NPC_GILDNID => {
                if let Some(dm) = self.deadmines_mut() {
                    dm.gilnid_dead = true;
                    dm.gilnid_patrol_ms = 30_000;
                    dm.gilnid_death_pos = pos;
                }
                self.find_gameobject(GO_DOOR3, Some((-169.0, -168.0)))
            }
            _ => None,
        };
        if let Some(door) = door
            && self.go_state(door) != GO_STATE_ACTIVE
        {
            self.use_door(door);
        }
    }

    /// `instance_deadmines::SetData` reactions. Returns
    /// true when the instance script owns the field.
    fn deadmines_set_data(&mut self, field: u32, data: u32) -> bool {
        if self.deadmines().is_none() {
            return false;
        }
        match field {
            TYPE_DEFIAS_ENDDOOR => {
                if data == IN_PROGRESS
                    && let Some(iron) = self.find_gameobject(GO_IRON_CLAD, None)
                {
                    if self.go_state(iron) != GO_STATE_ACTIVE {
                        self.use_door(iron);
                    }
                    if let Some(dm) = self.deadmines_mut() {
                        dm.iron_door_timer_ms = 3000;
                    }
                }
                if let Some(dm) = self.deadmines_mut() {
                    dm.encounter_enddoor = data;
                }
                true
            }
            GUN_POWDER_EVENT => {
                if let Some(dm) = self.deadmines_mut() {
                    dm.gunpowder_done = data;
                }
                true
            }
            _ => false,
        }
    }

    /// `instance_deadmines::GetData`.
    fn deadmines_get_data(&self, field: u32) -> Option<u32> {
        let dm = self.deadmines()?;
        match field {
            TYPE_DEFIAS_ENDDOOR => Some(dm.encounter_enddoor),
            GUN_POWDER_EVENT => Some(dm.gunpowder_done),
            _ => None,
        }
    }

    /// `instance_deadmines::GetData64`.
    fn deadmines_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        if self.deadmines().is_none() || field != DATA_DEFIAS_DOOR {
            return None;
        }
        self.find_gameobject(GO_IRON_CLAD, None)
    }

    /// `instance_deadmines::Update`.
    fn deadmines_update(&mut self, diff_ms: u32) {
        let Some(dm) = self.deadmines_mut() else {
            return;
        };
        let rhahk_fire = dm.rhahk_dead && dm.rhahk_patrol_ms > 0 && {
            if dm.rhahk_patrol_ms <= diff_ms {
                dm.rhahk_patrol_ms = 0;
                true
            } else {
                dm.rhahk_patrol_ms -= diff_ms;
                false
            }
        };
        let gilnid_fire = dm.gilnid_dead && dm.gilnid_patrol_ms > 0 && {
            if dm.gilnid_patrol_ms <= diff_ms {
                dm.gilnid_patrol_ms = 0;
                true
            } else {
                dm.gilnid_patrol_ms -= diff_ms;
                false
            }
        };
        let iron_fire = dm.iron_door_timer_ms > 0 && {
            if dm.iron_door_timer_ms <= diff_ms {
                true
            } else {
                dm.iron_door_timer_ms -= diff_ms;
                false
            }
        };
        let rhahk_pos = dm.rhahk_death_pos;
        let gilnid_pos = dm.gilnid_death_pos;
        if rhahk_fire {
            self.activate_patrol(rhahk_pos, &[634, 1729], 43199);
        }
        if gilnid_fire {
            self.activate_patrol(gilnid_pos, &[4417, 4418], 43201);
        }
        if iron_fire {
            self.iron_door_step();
        }
    }

    fn activate_patrol(&mut self, center: Position, entries: &[u32], delay_marker: u32) {
        let guids: Vec<ObjectGuid> = self
            .creatures
            .values()
            .filter(|c| {
                entries.contains(&c.info.entry)
                    && c.data.as_ref().map_or(0, |d| d.spawntimesecsmin) == delay_marker
                    && crate::visibility::dist2d(center, c.unit.world.position()) <= 400.0
            })
            .map(|c| c.unit.guid())
            .collect();
        for guid in guids {
            self.hidden_objects.remove(&guid);
            let _ = self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE), 17);
        }
    }

    fn iron_door_step(&mut self) {
        let step = self.deadmines().map_or(0, |dm| dm.iron_door_step);
        let Some(smite) = self.find_creature_by_entry(NPC_MR_SMITE) else {
            if let Some(dm) = self.deadmines_mut() {
                dm.iron_door_timer_ms = 0;
            }
            return;
        };
        if step == 0 {
            self.do_script_text(INST_SAY_ALARM1, smite, None, -1);
            let pirates: Vec<ObjectGuid> = self
                .creatures
                .values()
                .filter(|c| {
                    c.info.entry == 657
                        && c.data.as_ref().map_or(0, |d| d.spawntimesecsmin) == 43202
                })
                .map(|c| c.unit.guid())
                .collect();
            let dest = Position::new(-99.661_1, -671.071_66, 7.422_41, 0.0);
            for pirate in pirates {
                self.creature_move_point(pirate, 0, dest, 0, 0.0, -10.0);
            }
            if let Some(dm) = self.deadmines_mut() {
                dm.iron_door_step = 1;
                dm.iron_door_timer_ms = 15_000;
            }
        } else {
            self.do_script_text(INST_SAY_ALARM2, smite, None, -1);
            if let Some(dm) = self.deadmines_mut() {
                dm.iron_door_step = 0;
                dm.iron_door_timer_ms = 0;
            }
        }
    }

    // ------------------------------------------------ instance: shadowfang keep

    fn sfk_encounter(&self, index: usize) -> u32 {
        self.shadowfang_keep().map_or(0, |s| s.encounter[index])
    }

    /// `instance_shadowfang_keep::OnCreatureCreate`.
    fn sfk_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            SFK_NPC_ASH => {
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.ash = guid;
                }
            }
            SFK_NPC_ADA => {
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.ada = guid;
                }
            }
            SFK_NPC_FENRUS => {
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.fenrus = guid;
                }
            }
            SFK_NPC_ARUGAL => {
                if self.sfk_encounter(4) == DONE {
                    self.hidden_objects.insert(guid);
                }
            }
            SFK_NPC_VINCENT => {
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.vincent = guid;
                }
                if self.sfk_encounter(4) == DONE {
                    // SetStandState(UNIT_STAND_STATE_DEAD)
                    self.unit_set_byte(guid, offsets::UNIT_FIELD_BYTES_1, 0, 7);
                }
            }
            SFK_NPC_BARON_SILVERLAINE => {
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.baron_silverlaine = guid;
                }
            }
            SFK_NPC_NANDOS => {
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.nandos = guid;
                }
            }
            SFK_NPC_CMD_SPRINGVALE => {
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.cmd_springvale = guid;
                }
            }
            SFK_NPC_WOLF_GUARD => {
                self.hidden_objects.insert(guid);
                let _ =
                    self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE), 35);
            }
            _ => {}
        }
    }

    /// `instance_shadowfang_keep::OnCreatureDeath`.
    fn sfk_on_creature_death(&mut self, victim: ObjectGuid) {
        let Some(entry) = self.object_entry(victim) else {
            return;
        };
        match entry {
            SFK_NPC_BARON_SILVERLAINE => {
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.show_silverlaine_patrol = true;
                }
            }
            SFK_NPC_CMD_SPRINGVALE => {
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.show_springvale_patrol = true;
                }
            }
            _ => {}
        }
    }

    /// `instance_shadowfang_keep::
    /// OnCreatureEnterCombat` (Fenrus howl).
    fn sfk_on_creature_enter_combat(&mut self, creature: ObjectGuid) {
        if self.object_entry(creature) == Some(SFK_NPC_FENRUS) {
            self.play_direct_sound(creature, SFK_SOUND_FENRUS_AGGRO, None);
        }
    }

    /// `instance_shadowfang_keep::OnObjectCreate`.
    fn sfk_on_object_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        let (slot, encounter_idx) = match entry {
            SFK_GO_COURTYARD_DOOR => (0, 0),
            SFK_GO_SORCERER_DOOR => (1, 2),
            SFK_GO_ARUGAL_DOOR => (2, 3),
            _ => return,
        };
        if let Some(s) = self.shadowfang_keep_mut() {
            match slot {
                0 => s.door_courtyard = guid,
                1 => s.door_sorcerer = guid,
                _ => s.door_arugal = guid,
            }
        }
        if self.sfk_encounter(encounter_idx) == DONE {
            let _ =
                self.object_set_field(guid, u32::from(offsets::GAMEOBJECT_STATE), GO_STATE_ACTIVE);
        }
    }

    /// One patrol-reveal branch of
    /// `instance_shadowfang_keep::Update` (the
    /// fork repeats the block for Baron/Cmd; the
    /// timer stalls while the boss object is
    /// gone, fork quirk preserved).
    fn sfk_patrol_update(&mut self, diff_ms: u32, baron: bool) {
        let (show, boss, timer) = match self.shadowfang_keep() {
            Some(s) if baron => (
                s.show_silverlaine_patrol,
                s.baron_silverlaine,
                s.patrol_on_baron_death_ms,
            ),
            Some(s) => (
                s.show_springvale_patrol,
                s.cmd_springvale,
                s.patrol_on_cmd_death_ms,
            ),
            None => return,
        };
        if !show {
            return;
        }
        let Some(boss_pos) = self.object_position(boss) else {
            return;
        };
        if timer > diff_ms {
            if let Some(s) = self.shadowfang_keep_mut() {
                if baron {
                    s.patrol_on_baron_death_ms -= diff_ms;
                } else {
                    s.patrol_on_cmd_death_ms -= diff_ms;
                }
            }
            return;
        }
        let marker: u32 = if baron { 7201 } else { 7202 };
        let guards: Vec<ObjectGuid> = self
            .creatures
            .values()
            .filter(|c| {
                c.info.entry == SFK_NPC_WOLF_GUARD
                    && c.data.as_ref().map_or(0, |d| d.spawntimesecsmin) == marker
                    && crate::visibility::dist3d(c.unit.world.position(), boss_pos) <= 400.0
            })
            .map(|c| c.unit.guid())
            .collect();
        for guard in guards {
            self.hidden_objects.remove(&guard);
            let _ =
                self.object_set_field(guard, u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE), 17);
            if let Some(s) = self.shadowfang_keep_mut() {
                if baron {
                    s.show_silverlaine_patrol = false;
                } else {
                    s.show_springvale_patrol = false;
                }
            }
        }
    }

    /// `instance_shadowfang_keep::Update`.
    fn sfk_update(&mut self, diff_ms: u32) {
        self.sfk_patrol_update(diff_ms, true);
        self.sfk_patrol_update(diff_ms, false);
    }

    /// `instance_shadowfang_keep::SetData`.
    fn sfk_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            SFK_TYPE_FREE_NPC => {
                if data == DONE {
                    let door = self
                        .shadowfang_keep()
                        .map_or(ObjectGuid::EMPTY, |s| s.door_courtyard);
                    if door != ObjectGuid::EMPTY {
                        self.use_door(door);
                    }
                }
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.encounter[0] = data;
                }
            }
            SFK_TYPE_RETHILGORE => {
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.encounter[1] = data;
                }
            }
            SFK_TYPE_FENRUS => {
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.encounter[2] = data;
                }
            }
            SFK_TYPE_NANDOS => {
                if data == DONE {
                    let door = self
                        .shadowfang_keep()
                        .map_or(ObjectGuid::EMPTY, |s| s.door_arugal);
                    if door != ObjectGuid::EMPTY {
                        self.use_door(door);
                    }
                }
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.encounter[3] = data;
                }
            }
            SFK_TYPE_INTRO => {
                if let Some(s) = self.shadowfang_keep_mut() {
                    s.encounter[4] = data;
                }
            }
            SFK_TYPE_VOIDWALKER => {
                if data == DONE {
                    let count = if let Some(s) = self.shadowfang_keep_mut() {
                        s.encounter[5] += 1;
                        s.encounter[5]
                    } else {
                        0
                    };
                    if count > 3 {
                        let door = self
                            .shadowfang_keep()
                            .map_or(ObjectGuid::EMPTY, |s| s.door_sorcerer);
                        if door != ObjectGuid::EMPTY {
                            self.use_door(door);
                        }
                    }
                }
            }
            _ => return false,
        }
        if data == DONE
            && let Some(s) = self.shadowfang_keep_mut()
        {
            let e = s.encounter;
            s.save_string = format!("{} {} {} {} {} {}", e[0], e[1], e[2], e[3], e[4], e[5]);
        }
        true
    }

    /// `instance_shadowfang_keep::GetData`.
    fn sfk_get_data(&self, field: u32) -> Option<u32> {
        let s = self.shadowfang_keep()?;
        match field {
            SFK_TYPE_FREE_NPC => Some(s.encounter[0]),
            SFK_TYPE_RETHILGORE => Some(s.encounter[1]),
            SFK_TYPE_FENRUS => Some(s.encounter[2]),
            SFK_TYPE_NANDOS => Some(s.encounter[3]),
            SFK_TYPE_INTRO => Some(s.encounter[4]),
            _ => None,
        }
    }

    /// `instance_shadowfang_keep::Save`.
    fn sfk_save(&self) -> Option<String> {
        self.shadowfang_keep().map(|s| s.save_string.clone())
    }

    /// `instance_shadowfang_keep::Load`.
    fn sfk_load(&mut self, data: &str) {
        let mut loaded = [0u32; 6];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = 0; // NOT_STARTED
            }
        }
        if let Some(s) = self.shadowfang_keep_mut() {
            s.encounter = loaded;
        }
    }

    // ------------------------------------------------ instance: wailing caverns

    /// `instance_wailing_caverns::OnCreatureCreate`.
    fn wc_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            WC_NPC_DISCIPLE => {
                if let Some(s) = self.wailing_caverns_mut() {
                    s.disciple = guid;
                }
            }
            WC_NPC_NARALEX => {
                if let Some(s) = self.wailing_caverns_mut() {
                    s.naralex = guid;
                }
            }
            WC_NPC_SERPENTIS => {
                if let Some(s) = self.wailing_caverns_mut() {
                    s.serpentis = guid;
                }
            }
            WC_NPC_ANACONDRA => {
                if let Some(s) = self.wailing_caverns_mut() {
                    s.anacondra = guid;
                }
            }
            _ => {}
        }
        // `GetCreatureType() != CREATURE_TYPE_CRITTER &&
        // GetFactionTemplateId() != 35 && entry != Kresh(3653)`.
        let faction = self.object_get_field(guid, offsets::UNIT_FIELD_FACTIONTEMPLATE);
        let is_critter = self
            .creatures
            .get(&guid)
            .is_some_and(|c| c.info.creature_type == WC_CREATURE_TYPE_CRITTER);
        if !is_critter && faction != 35 && entry != WC_NPC_KRESH {
            if let Some(s) = self.wailing_caverns_mut() {
                s.nightmare_monsters.push(guid);
            }
        }
    }

    /// `instance_wailing_caverns::OnObjectCreate`.
    fn wc_on_object_create(&mut self, guid: ObjectGuid) {
        if self.wailing_caverns().is_none() {
            return;
        }
        if self.object_entry(guid) == Some(WC_GO_DMF_CHEST) {
            self.hidden_objects.insert(guid);
        }
    }

    /// `instance_wailing_caverns::SetData`.
    fn wc_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            WC_TYPE_ANACONDRA => {
                if let Some(s) = self.wailing_caverns_mut() {
                    s.encounter[WC_TYPE_ANACONDRA as usize] = data;
                }
                self.wc_serpentis_first_yell(data);
                if data == WC_SPECIAL {
                    self.wc_anacondra_special();
                }
            }
            WC_TYPE_COBRAHN => {
                if let Some(s) = self.wailing_caverns_mut() {
                    s.encounter[WC_TYPE_COBRAHN as usize] = data;
                }
                self.wc_serpentis_first_yell(data);
            }
            WC_TYPE_PYTHAS => {
                if let Some(s) = self.wailing_caverns_mut() {
                    s.encounter[WC_TYPE_PYTHAS as usize] = data;
                }
                self.wc_serpentis_first_yell(data);
            }
            WC_TYPE_MUTANUS => {
                if let Some(s) = self.wailing_caverns_mut() {
                    s.encounter[field as usize] = data;
                }
                if data == DONE {
                    // Despawn every hostile creature. The fork
                    // also despawns dead-but-unlooted corpses
                    // (`loot.empty()`); Rust Map holds no loot
                    // state, so corpses remain (recorded).
                    let guids: Vec<ObjectGuid> = self
                        .wailing_caverns()
                        .map_or(Vec::new(), |s| s.nightmare_monsters.clone());
                    for guid in guids {
                        if self.creatures.get(&guid).is_some_and(|c| c.unit.is_alive()) {
                            self.despawn_creature_now(guid, 0);
                        }
                        if let Some(s) = self.wailing_caverns_mut() {
                            s.nightmare_monsters.retain(|g| *g != guid);
                        }
                    }
                }
            }
            WC_TYPE_SERPENTIS | WC_TYPE_DISCIPLE => {
                if let Some(s) = self.wailing_caverns_mut() {
                    s.encounter[field as usize] = data;
                }
            }
            _ => return false,
        }
        // All four fanglords DONE and disciple not started:
        // disciple becomes SPECIAL (gossip + yell).
        let all_done = self.wailing_caverns().is_some_and(|s| {
            s.encounter[0] == DONE
                && s.encounter[1] == DONE
                && s.encounter[2] == DONE
                && s.encounter[3] == DONE
                && s.encounter[4] == WC_NOT_STARTED
        });
        if all_done {
            self.wc_set_data(WC_TYPE_DISCIPLE, WC_SPECIAL);
            let disciple = self
                .wailing_caverns()
                .map_or(ObjectGuid::EMPTY, |s| s.disciple);
            // `SetDefaultGossipMenuId(202)`: gossip menu state
            // lands with the Slice 2 gossip framework.
            self.do_script_text(WC_YELL_AFTER_GOSSIP, disciple, None, -1);
        }
        if data == DONE
            && let Some(s) = self.wailing_caverns_mut()
        {
            let e = s.encounter;
            s.save_string = format!("{} {} {} {} {} {}", e[0], e[1], e[2], e[3], e[4], e[5]);
        }
        true
    }

    /// Serpentis' one-time yell on the first fanglord
    /// death (`!Assaulted` arm shared by
    /// ANACONDRA/COBRAHN/PYTHAS).
    fn wc_serpentis_first_yell(&mut self, data: u32) {
        if data != DONE || self.wailing_caverns().is_some_and(|s| s.assaulted) {
            return;
        }
        let serpentis = self
            .wailing_caverns()
            .map_or(ObjectGuid::EMPTY, |s| s.serpentis);
        if self
            .creatures
            .get(&serpentis)
            .is_some_and(|c| c.unit.is_alive())
        {
            self.do_script_text(WC_SERPENTIS_YELL, serpentis, None, -1);
        }
        if let Some(s) = self.wailing_caverns_mut() {
            s.assaulted = true;
        }
    }

    /// `TYPE_ANACONDRA` SPECIAL: the closest living
    /// druid (3840) within `INTERACTION_DISTANCE` of
    /// Anacondra `DisappearAndDie`s.
    fn wc_anacondra_special(&mut self) {
        let ana_pos = self
            .wailing_caverns()
            .and_then(|s| self.object_position(s.anacondra));
        let Some(ana_pos) = ana_pos else {
            return;
        };
        let druid: Option<ObjectGuid> = self
            .creatures
            .values()
            .filter(|c| c.info.entry == WC_NPC_DRUID)
            .map(|c| {
                (
                    c.unit.guid(),
                    crate::visibility::dist3d(c.unit.world.position(), ana_pos),
                )
            })
            .filter(|(_, d)| *d <= WC_INTERACTION_DISTANCE)
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .map(|(g, _)| g);
        if let Some(druid) = druid
            && self
                .creatures
                .get(&druid)
                .is_some_and(|c| c.unit.is_alive())
        {
            self.despawn_creature_now(druid, 0);
        }
    }

    /// `instance_wailing_caverns::GetData`.
    fn wc_get_data(&self, field: u32) -> Option<u32> {
        let s = self.wailing_caverns()?;
        match field {
            WC_TYPE_ANACONDRA | WC_TYPE_COBRAHN | WC_TYPE_PYTHAS | WC_TYPE_SERPENTIS
            | WC_TYPE_DISCIPLE | WC_TYPE_MUTANUS => Some(s.encounter[field as usize]),
            _ => None,
        }
    }

    /// `instance_wailing_caverns::GetData64`.
    fn wc_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        let s = self.wailing_caverns()?;
        match field {
            WC_DATA_NARALEX => (!s.naralex.is_empty()).then_some(s.naralex),
            _ => None,
        }
    }

    /// `instance_wailing_caverns::Save`.
    fn wc_save(&self) -> Option<String> {
        self.wailing_caverns().map(|s| s.save_string.clone())
    }

    /// `instance_wailing_caverns::Load`.
    fn wc_load(&mut self, data: &str) {
        let mut loaded = [0u32; 6];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = WC_NOT_STARTED;
            }
        }
        if let Some(s) = self.wailing_caverns_mut() {
            s.encounter = loaded;
        }
    }

    // ------------------------------------------------ instance: razorfen kraul

    /// `instance_razorfen_kraul::OnObjectCreate`.
    fn rfk_on_object_create(&mut self, guid: ObjectGuid) {
        if self.object_entry(guid) != Some(RFK_GO_AGATHELOS_WARD) {
            return;
        }
        if let Some(s) = self.razorfen_kraul_mut() {
            s.agathelos_ward = guid;
        }
        if self.razorfen_kraul().map_or(0, |s| s.encounter[0]) == DONE {
            let _ =
                self.object_set_field(guid, u32::from(offsets::GAMEOBJECT_STATE), GO_STATE_ACTIVE);
        }
    }

    /// `instance_razorfen_kraul::OnCreatureCreate`.
    fn rfk_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            RFK_NPC_WARD_KEEPER => {
                if let Some(s) = self.razorfen_kraul_mut() {
                    s.ward_keepers_remaining += 1;
                }
            }
            RFK_NPC_AGATHELOS => {
                if let Some(s) = self.razorfen_kraul_mut() {
                    s.agathelos = guid;
                }
            }
            _ => {}
        }
    }

    /// `instance_razorfen_kraul::SetData`.
    fn rfk_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            RFK_TYPE_AGATHELOS => {
                let open = if let Some(s) = self.razorfen_kraul_mut() {
                    s.ward_keepers_remaining = s.ward_keepers_remaining.wrapping_sub(1);
                    s.ward_keepers_remaining == 0
                } else {
                    return false;
                };
                if open {
                    if let Some(s) = self.razorfen_kraul_mut() {
                        s.encounter[0] = data;
                    }
                    let ward = self
                        .razorfen_kraul()
                        .map_or(ObjectGuid::EMPTY, |s| s.agathelos_ward);
                    if ward != ObjectGuid::EMPTY {
                        self.use_door(ward);
                    }
                    // SetWalk(false) + MoveWaypoint
                    // (SetDefaultMovementType has no Rust
                    // motion-default equivalent).
                    let agathelos = self
                        .razorfen_kraul()
                        .map_or(ObjectGuid::EMPTY, |s| s.agathelos);
                    if agathelos != ObjectGuid::EMPTY && self.creatures.contains_key(&agathelos) {
                        self.set_walk(agathelos, false);
                        self.creature_move_waypoint(agathelos, 0, true);
                    }
                }
            }
            _ => return false,
        }
        // Fork refreshes `m_strInstData` on DONE, but never
        // overrides `Save()` (base returns ""), so nothing
        // observable persists.
        true
    }

    /// `instance_razorfen_kraul::GetData`.
    fn rfk_get_data(&self, field: u32) -> Option<u32> {
        let s = self.razorfen_kraul()?;
        match field {
            RFK_TYPE_AGATHELOS => Some(s.encounter[0]),
            _ => None,
        }
    }

    /// `instance_razorfen_kraul::Load`.
    fn rfk_load(&mut self, data: &str) {
        let mut loaded = [0u32; 1];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = 0; // NOT_STARTED
            }
        }
        if let Some(s) = self.razorfen_kraul_mut() {
            s.encounter = loaded;
        }
    }

    // ------------------------------------------------ instance: razorfen downs

    /// `instance_razorfen_downs::OnObjectCreate` (cpp 73-91).
    fn rfd_on_object_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            RFD_GO_GONG => {
                if let Some(s) = self.razorfen_downs_mut() {
                    s.gong = guid;
                }
                if self.razorfen_downs().map_or(0, |s| s.encounter[0]) == DONE {
                    // `SetFlag(GAMEOBJECT_FLAGS, GO_FLAG_NO_INTERACT)`.
                    let flags = self.object_get_field(guid, offsets::GAMEOBJECT_FLAGS);
                    let _ = self.object_set_field(
                        guid,
                        u32::from(offsets::GAMEOBJECT_FLAGS),
                        flags | RFD_GO_FLAG_NO_INTERACT,
                    );
                }
            }
            RFD_GO_IDOL_CUP_FIRE => {
                if let Some(s) = self.razorfen_downs_mut() {
                    if s.cup_fire_1.is_empty() {
                        s.cup_fire_1 = guid;
                    } else {
                        s.cup_fire_2 = guid;
                    }
                }
            }
            _ => {}
        }
    }

    /// `instance_razorfen_downs::SetData` (cpp 93-200). Returns true
    /// when the instance script owns the field (exemplar convention;
    /// the C++ itself returns void).
    #[allow(clippy::cast_possible_truncation, clippy::cast_precision_loss)]
    fn rfd_set_data(&mut self, field: u32, data: u32) -> bool {
        if field == RFD_DATA_GONG_WAVES {
            // C++ assigns the u32 straight into a `uint8`.
            if let Some(s) = self.razorfen_downs_mut() {
                s.gong_waves = data as u8;
            }
            let waves = self.razorfen_downs().map_or(0, |s| s.gong_waves);
            match waves {
                9 | 14 => {
                    // `RemoveFlag(GAMEOBJECT_FLAGS, GO_FLAG_NO_INTERACT)`
                    // (cpp 102-104; guarded by the null check there).
                    let gong = self.razorfen_downs().map_or(ObjectGuid::EMPTY, |s| s.gong);
                    if gong != ObjectGuid::EMPTY {
                        let flags = self.object_get_field(gong, offsets::GAMEOBJECT_FLAGS);
                        let _ = self.object_set_field(
                            gong,
                            u32::from(offsets::GAMEOBJECT_FLAGS),
                            flags & !RFD_GO_FLAG_NO_INTERACT,
                        );
                    }
                }
                1 | 10 | 15 => self.rfd_gong_wave_spawn(waves),
                _ => {}
            }
            return true;
        }

        if field == RFD_BOSS_TUTEN_KASH {
            if let Some(s) = self.razorfen_downs_mut() {
                s.encounter[0] = data;
            }
            // C++ `if (uiData == DONE) SaveToDB();` (cpp 176-177):
            // with no `Save()` override the base persists `""`, so
            // there is nothing to refresh here (see unresolved).
            return true;
        }

        if field == RFD_EXTINGUISH_FIRES {
            // C++ `SetLootState(GO_JUST_DEACTIVATED)` on both cup
            // fires (cpp 182-185): Rust has no gameobject loot
            // state yet; the field stays owned, effect recorded
            // in TIER3-PROGRESS.
            return true;
        }

        false
    }

    /// Gong wave spawn (`DATA_GONG_WAVES` 1/10/15 arm):
    /// lock the gong, summon the wave at the two
    /// spawn points with irand jitter, send them to
    /// the muster point.
    #[allow(clippy::cast_precision_loss)]
    fn rfd_gong_wave_spawn(&mut self, waves: u8) {
        // Wave spawn (cpp 105-166). The C++ `if (!pGo)
        // return;` exits all of `SetData`.
        let gong = self.razorfen_downs().map_or(ObjectGuid::EMPTY, |s| s.gong);
        if self.gameobject(gong).is_none() {
            return;
        }
        let flags = self.object_get_field(gong, offsets::GAMEOBJECT_FLAGS);
        let _ = self.object_set_field(
            gong,
            u32::from(offsets::GAMEOBJECT_FLAGS),
            flags | RFD_GO_FLAG_NO_INTERACT,
        );
        let (entry, extra) = match waves {
            1 => (RFD_CREATURE_TOMB_FIEND, 7),
            10 => (RFD_CREATURE_TOMB_REAVER, 3),
            _ => (RFD_CREATURE_TUTEN_KASH, 0),
        };
        let spawn = Position::new(2502.635, 844.140, 46.896, 0.633);
        if let Some(leader) =
            self.summon_creature(entry, spawn, gong, RFD_TEMPSUMMON_DEAD_DESPAWN, 25_000)
        {
            self.set_walk(leader, false);
            if waves == 1 || waves == 10 {
                for i in 0..extra {
                    let (x, y, z) = if i % 2 == 1 {
                        (2502.635, 844.140, 46.896)
                    } else {
                        (2546.33, 887.455, 47.69)
                    };
                    // `float(irand(-5, 5))` jitter.
                    let at = Position::new(
                        x + self.spell_rng().irand(-5, 5) as f32,
                        y + self.spell_rng().irand(-5, 5) as f32,
                        z,
                        0.633,
                    );
                    if let Some(summon) =
                        self.summon_creature(entry, at, gong, RFD_TEMPSUMMON_DEAD_DESPAWN, 25_000)
                    {
                        self.set_walk(summon, false);
                        // `MovePoint(0, 2533.479, 870.020,
                        // 47.678, MOVE_PATHFINDING)` with
                        // jitter; `-10.0` keeps facing
                        // (`motion.rs`: only `> -7.0`
                        // applies a facing).
                        let dest = Position::new(
                            2533.479 + self.spell_rng().irand(-5, 5) as f32,
                            870.020 + self.spell_rng().irand(-5, 5) as f32,
                            47.678,
                            0.0,
                        );
                        self.creature_move_point(summon, 0, dest, RFD_MOVE_PATHFINDING, 0.0, -10.0);
                    }
                }
            }
            // Leader `MovePoint` (cpp 163), same muster point.
            let dest = Position::new(
                2533.479 + self.spell_rng().irand(-5, 5) as f32,
                870.020 + self.spell_rng().irand(-5, 5) as f32,
                47.678,
                0.0,
            );
            self.creature_move_point(leader, 0, dest, RFD_MOVE_PATHFINDING, 0.0, -10.0);
        }
    }

    /// `instance_razorfen_downs::GetData` (cpp 202-211).
    fn rfd_get_data(&self, field: u32) -> Option<u32> {
        let s = self.razorfen_downs()?;
        match field {
            RFD_DATA_GONG_WAVES => Some(u32::from(s.gong_waves)),
            _ => None,
        }
    }

    /// `instance_razorfen_downs::GetData64` (cpp 213-222).
    fn rfd_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        if field != RFD_DATA_GONG {
            return None;
        }
        let guid = self.razorfen_downs().map_or(ObjectGuid::EMPTY, |s| s.gong);
        (!guid.is_empty()).then_some(guid)
    }

    /// `instance_razorfen_downs::Load` (cpp 52-71). The C++ null
    /// `chrIn` check has no Rust equivalent (`&str` is never null).
    fn rfd_load(&mut self, data: &str) {
        let mut loaded = [0u32; 1];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = 0; // NOT_STARTED
            }
        }
        if let Some(s) = self.razorfen_downs_mut() {
            s.encounter = loaded;
        }
    }

