    // ------------------------------------------------ instance: maraudon

    /// `instance_maraudon::OnCreatureCreate` (cpp 34-51).
    fn mar_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            MAR_NPC_CELEBRAS_REDEEMED => {
                if let Some(s) = self.maraudon_mut() {
                    s.celebras_redeemed = guid;
                }
                // `SetVisibility(VISIBILITY_OFF)`.
                if self
                    .maraudon()
                    .map_or(0, |s| s.encounter[MAR_TYPE_CELEBRAS as usize])
                    != DONE
                {
                    self.hidden_objects.insert(guid);
                }
            }
            MAR_NPC_SPEWED_LARVA => {
                if let Some(s) = self.maraudon_mut() {
                    s.spewed_larva = guid;
                }
                // `DisappearAndDie` (no direct helper; cf. `wc_anacondra_special`).
                if self
                    .maraudon()
                    .map_or(0, |s| s.encounter[MAR_TYPE_LARVA_SPEWER as usize])
                    == DONE
                {
                    self.despawn_creature_now(guid, 0);
                }
            }
            _ => {}
        }
    }

    /// `instance_maraudon::OnGameObjectCreate` (cpp 53-68).
    fn mar_on_object_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            MAR_GO_HEALED_CELEBRIAN_VINE => {
                // The healed vine is summoned by the corrupted one.
                if let Some(s) = self.maraudon_mut() {
                    s.vine = guid;
                }
            }
            MAR_GO_LARVA_SPEWER => {
                if let Some(s) = self.maraudon_mut() {
                    s.larva_spewer = guid;
                }
                // Alternative state = destroyed.
                if self
                    .maraudon()
                    .map_or(0, |s| s.encounter[MAR_TYPE_LARVA_SPEWER as usize])
                    == DONE
                {
                    let _ = self.object_set_field(
                        guid,
                        u32::from(offsets::GAMEOBJECT_STATE),
                        MAR_GO_STATE_ACTIVE_ALTERNATIVE,
                    );
                }
            }
            _ => {}
        }
    }

    // `OnCreatureRespawn` (cpp 70-80) needs no separate
    // body: respawns re-enter through
    // `instance_on_creature_create`, whose larva arm is
    // identical.

    /// `instance_maraudon::SetData` (cpp 112-149). Returns true when the
    /// instance script owns the field (exemplar convention; C++ returns void).
    fn mar_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            MAR_TYPE_LARVA_SPEWER => {
                if data == IN_PROGRESS {
                    // First kill our larva.
                    if let Some(larva) = self
                        .maraudon()
                        .map(|s| s.spewed_larva)
                        .filter(|g| self.creatures.contains_key(g))
                    {
                        // The 4s-delayed `Respawn()` in `mar_update`
                        // rides `respawns_due` (`update_respawns` is the
                        // `Creature::Respawn` re-materialization subset).
                        self.despawn_creature_now(larva, 4);
                    }
                    self.mar_spew_larva();
                } else if let Some(s) = self.maraudon_mut() {
                    s.encounter[MAR_TYPE_LARVA_SPEWER as usize] = data;
                }
            }
            MAR_TYPE_CELEBRAS => {
                if data == DONE {
                    // `SetVisibility(VISIBILITY_ON)`.
                    let celebras = self
                        .maraudon()
                        .map_or(ObjectGuid::EMPTY, |s| s.celebras_redeemed);
                    if celebras != ObjectGuid::EMPTY {
                        self.hidden_objects.remove(&celebras);
                    }
                }
                if let Some(s) = self.maraudon_mut() {
                    s.encounter[MAR_TYPE_CELEBRAS as usize] = data;
                }
            }
            _ => return false,
        }
        if data == DONE
            && let Some(s) = self.maraudon_mut()
        {
            let e = s.encounter;
            s.save_string = format!("{} {} ", e[0], e[1]);
        }
        true
    }

    /// `instance_maraudon::GetData` (cpp 97-110).
    fn mar_get_data(&self, field: u32) -> Option<u32> {
        let s = self.maraudon()?;
        match field {
            MAR_TYPE_LARVA_SPEWER => Some(s.encounter[MAR_TYPE_LARVA_SPEWER as usize]),
            MAR_TYPE_CELEBRAS => Some(s.encounter[MAR_TYPE_CELEBRAS as usize]),
            _ => None,
        }
    }

    /// `instance_maraudon::GetData64` (cpp 151-160).
    fn mar_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        if field != MAR_NPC_CELEBRAS_REDEEMED {
            return None;
        }
        let guid = self
            .maraudon()
            .map_or(ObjectGuid::EMPTY, |s| s.celebras_redeemed);
        (!guid.is_empty()).then_some(guid)
    }

    /// `instance_maraudon::SpewLarva` (cpp 162-172).
    /// `SendGameObjectCustomAnim` has no Rust equivalent (unresolved);
    /// the spew timer/flag (the reachable part) is kept.
    fn mar_spew_larva(&mut self) {
        let spewer = self
            .maraudon()
            .map_or(ObjectGuid::EMPTY, |s| s.larva_spewer);
        if self.gameobject(spewer).is_none() || self.go_state(spewer) != GO_STATE_READY {
            return;
        }
        if let Some(s) = self.maraudon_mut() {
            s.respawn_spewed_larva = true;
            s.spewed_larva_timer_ms = 4000;
        }
    }

    /// `instance_maraudon::Update` (cpp 174-197).
    fn mar_update(&mut self, diff_ms: u32) {
        // Remove a corrupted vine when a healed one was summoned over it.
        let vine = self.maraudon().map_or(ObjectGuid::EMPTY, |s| s.vine);
        if !vine.is_empty() {
            // `GetClosestGameObjectWithEntry` has no helper; open-coded.
            if let Some(vine_pos) = self.object_position(vine) {
                let corrupted: Option<ObjectGuid> = self
                    .gameobjects
                    .iter()
                    .filter(|(_, go)| {
                        go.world
                            .object
                            .values()
                            .get_u32(offsets::OBJECT_FIELD_ENTRY)
                            == MAR_GO_VYLESTEM_VINE
                    })
                    .map(|(g, go)| (*g, crate::visibility::dist3d(go.world.position(), vine_pos)))
                    .filter(|(_, d)| *d <= MAR_INTERACTION_DISTANCE)
                    .min_by(|a, b| a.1.total_cmp(&b.1))
                    .map(|(g, _)| g);
                // `AddObjectToRemoveList` (immediate here, not end-of-tick).
                if let Some(corrupted) = corrupted {
                    self.despawn_gameobject_now(corrupted);
                }
            }
            if let Some(s) = self.maraudon_mut() {
                s.vine = ObjectGuid::EMPTY;
            }
        }

        // Respawn a larva 4 seconds after the spewer animation start.
        // The respawn itself rides `respawns_due` (see `mar_set_data`);
        // here only the C++ timer/flag is retired.
        let elapse = self
            .maraudon()
            .is_some_and(|s| s.respawn_spewed_larva && s.spewed_larva_timer_ms <= diff_ms);
        if elapse {
            if let Some(s) = self.maraudon_mut() {
                s.respawn_spewed_larva = false;
            }
        } else if let Some(s) = self.maraudon_mut()
            && s.respawn_spewed_larva
        {
            s.spewed_larva_timer_ms -= diff_ms;
        }
    }

    /// `instance_maraudon::Save` (cpp 82).
    fn mar_save(&self) -> Option<String> {
        self.maraudon().map(|s| s.save_string.clone())
    }

    /// `instance_maraudon::Load` (cpp 84-95). The C++ null `chrIn`
    /// check has no Rust equivalent (`&str` is never null).
    fn mar_load(&mut self, data: &str) {
        let mut loaded = [0u32; 2];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = 0; // NOT_STARTED
            }
        }
        if let Some(s) = self.maraudon_mut() {
            s.encounter = loaded;
        }
    }

