    /// `instance_scholomance::OnCreatureDeath` (C++ lines 134-144):
    /// Kirtonos' death opens his gate.
    fn sch_on_creature_death(&mut self, victim: ObjectGuid) {
        if self.object_entry(victim) != Some(SCH_NPC_KIRTONOS) {
            return;
        }
        let gate = self
            .scholomance()
            .map_or(ObjectGuid::EMPTY, |s| s.gate_kirtonos);
        if gate != ObjectGuid::EMPTY && self.go_state(gate) != GO_STATE_ACTIVE {
            self.use_door(gate);
        }
    }

    /// `instance_scholomance::SetData` (C++ lines 146-216). Returns
    /// true when the instance script owns the field.
    fn sch_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            SCH_TYPE_GANDLING => {
                if let Some(s) = self.scholomance_mut() {
                    s.encounter[SCH_TYPE_GANDLING as usize] = data;
                }
                if data == SCH_FAIL || data == DONE {
                    let gates = self.scholomance().map_or([ObjectGuid::EMPTY; 6], |s| {
                        [
                            s.gate_malicia,
                            s.gate_theolen,
                            s.gate_polkelt,
                            s.gate_ravenian,
                            s.gate_barov,
                            s.gate_illucia,
                        ]
                    });
                    for gate in gates {
                        if gate != ObjectGuid::EMPTY && self.go_state(gate) != GO_STATE_ACTIVE {
                            self.use_door(gate);
                        }
                    }
                }
            }
            SCH_TYPE_KIRTONOS => {
                if let Some(s) = self.scholomance_mut() {
                    s.encounter[SCH_TYPE_KIRTONOS as usize] = data;
                }
                let gate = self
                    .scholomance()
                    .map_or(ObjectGuid::EMPTY, |s| s.gate_kirtonos);
                if data == IN_PROGRESS {
                    // DoUseDoorOrButton closes an ACTIVE gate;
                    // `use_door` only opens, so write READY.
                    if gate != ObjectGuid::EMPTY && self.go_state(gate) == GO_STATE_ACTIVE {
                        let _ = self.object_set_field(
                            gate,
                            u32::from(offsets::GAMEOBJECT_STATE),
                            GO_STATE_READY,
                        );
                    }
                } else if data == SCH_FAIL
                    && gate != ObjectGuid::EMPTY
                    && self.go_state(gate) != GO_STATE_ACTIVE
                {
                    self.use_door(gate);
                    // `pGo->ResetDoorOrButton()` on the Kirtonos
                    // brazier: no `Map` helper exists yet
                    // (recorded in TIER3-PROGRESS).
                }
            }
            SCH_TYPE_ALEXEIBAROV
            | SCH_TYPE_THEOLEN
            | SCH_TYPE_RAVENIAN
            | SCH_TYPE_POLKELT
            | SCH_TYPE_MALICIA
            | SCH_TYPE_ILLUCIABAROV
            | SCH_TYPE_VIEWING_ROOM_DOOR
            | SCH_TYPE_DARKREAVER => {
                if let Some(s) = self.scholomance_mut() {
                    s.encounter[field as usize] = data;
                }
            }
            _ => return false,
        }
        if data == DONE
            && let Some(s) = self.scholomance_mut()
        {
            let e = s.encounter;
            s.save_string = e.iter().fold(String::new(), |acc, v| format!("{acc}{v} "));
        }
        self.sch_summon_gandling_if_possible();
        true
    }

    /// `instance_scholomance::GetData` (C++ lines 111-122). The C++
    /// mutates `encounter[TYPE_GANDLING]` to `SPECIAL` inside the
    /// getter; `&self` cannot do that here, so the derivation is
    /// computed read-only (same observable value) and the store
    /// happens via `sch_set_data` in
    /// `sch_summon_gandling_if_possible`.
    fn sch_get_data(&self, field: u32) -> Option<u32> {
        let s = self.scholomance()?;
        if field == SCH_TYPE_GANDLING {
            let ready = s.encounter[SCH_TYPE_GANDLING as usize] == SCH_NOT_STARTED
                && s.encounter[SCH_TYPE_ALEXEIBAROV as usize] == DONE
                && s.encounter[SCH_TYPE_THEOLEN as usize] == DONE
                && s.encounter[SCH_TYPE_RAVENIAN as usize] == DONE
                && s.encounter[SCH_TYPE_POLKELT as usize] == DONE
                && s.encounter[SCH_TYPE_MALICIA as usize] == DONE
                && s.encounter[SCH_TYPE_ILLUCIABAROV as usize] == DONE;
            if ready {
                return Some(SCH_SPECIAL);
            }
            return Some(s.encounter[SCH_TYPE_GANDLING as usize]);
        }
        if (field as usize) < SCH_MAX_ENCOUNTER {
            return Some(s.encounter[field as usize]);
        }
        None
    }

    /// `instance_scholomance::GetData64` (C++ lines 123-133).
    fn sch_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        let s = self.scholomance()?;
        match field {
            SCH_DATA_VECTUS => (!s.vectus.is_empty()).then_some(s.vectus),
            SCH_DATA_MARDUKE => (!s.marduke.is_empty()).then_some(s.marduke),
            _ => None,
        }
    }

    /// `instance_scholomance::Save` (C++ line 218).
    fn sch_save(&self) -> Option<String> {
        self.scholomance().map(|s| s.save_string.clone())
    }

    /// `instance_scholomance::Load` (C++ lines 220-234).
    fn sch_load(&mut self, data: &str) {
        let mut loaded = [0u32; SCH_MAX_ENCOUNTER];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = SCH_NOT_STARTED;
            }
        }
        if let Some(s) = self.scholomance_mut() {
            s.encounter = loaded;
        }
        self.sch_summon_gandling_if_possible();
    }

    /// `instance_scholomance::SummonGandlingIfPossible` (C++ lines
    /// 235-242): summon Gandling at the headmaster's study and flip
    /// `TYPE_GANDLING` to `IN_PROGRESS` once all six mini-bosses are
    /// `DONE`.
    fn sch_summon_gandling_if_possible(&mut self) {
        if self.sch_get_data(SCH_TYPE_GANDLING) != Some(SCH_SPECIAL) {
            return;
        }
        let spawn = Position::new(180.771, -5.428_6, 75.570_2, 1.291_54);
        self.summon_creature(
            SCH_NPC_GANDLING,
            spawn,
            ObjectGuid::EMPTY,
            SCH_TEMPSUMMON_DEAD_DESPAWN,
            0,
        );
        self.sch_set_data(SCH_TYPE_GANDLING, IN_PROGRESS);
    }

