    /// `instance_gnomeregan::DoActivateBombFace` (also called by
    /// `boss_thermaplugg`).
    pub(crate) fn gno_activate_bomb_face(&mut self, index: u8) {
        if index as usize >= GNO_MAX_GNOME_FACES {
            return;
        }
        let face = self
            .gnomeregan()
            .map_or(ObjectGuid::EMPTY, |s| s.bomb_faces[index as usize].face);
        let active = self
            .gnomeregan()
            .is_some_and(|s| s.bomb_faces[index as usize].activated);
        if !active {
            if face != ObjectGuid::EMPTY {
                self.use_door(face);
            }
            if let Some(s) = self.gnomeregan_mut() {
                s.bomb_faces[index as usize].activated = true;
                s.bomb_faces[index as usize].bomb_timer_ms = 3000;
            }
        }
    }

    /// `instance_gnomeregan::DoDeactivateBombFace` (also called by
    /// `boss_thermaplugg`).
    fn gno_deactivate_bomb_face(&mut self, index: u8) {
        if index as usize >= GNO_MAX_GNOME_FACES {
            return;
        }
        let face = self
            .gnomeregan()
            .map_or(ObjectGuid::EMPTY, |s| s.bomb_faces[index as usize].face);
        let active = self
            .gnomeregan()
            .is_some_and(|s| s.bomb_faces[index as usize].activated);
        if active {
            // DoUseDoorOrButton closes an activated face;
            // `use_door` only opens, so write READY.
            if face != ObjectGuid::EMPTY {
                let _ = self.object_set_field(
                    face,
                    u32::from(offsets::GAMEOBJECT_STATE),
                    GO_STATE_READY,
                );
            }
            if let Some(s) = self.gnomeregan_mut() {
                s.bomb_faces[index as usize].activated = false;
                s.bomb_faces[index as usize].bomb_timer_ms = 0;
            }
        }
    }

    /// `instance_gnomeregan::SetData`. Returns true when the instance
    /// script owns the field.
    fn gno_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            GNO_TYPE_GRUBBIS => {
                if let Some(s) = self.gnomeregan_mut() {
                    s.encounter[GNO_TYPE_GRUBBIS as usize] = data;
                }
                if data == IN_PROGRESS {
                    self.gno_sort_explosive_charges();
                }
                if data == GNO_FAIL {
                    // Despawn possible spawned explosive charges
                    // (cpp 130-134): recurse like the C++ `SetData` call.
                    self.gno_set_data(GNO_TYPE_EXPLOSIVE_CHARGE, GNO_DATA_EXPLOSIVE_CHARGE_USE);
                }
                if data == DONE {
                    // `DoRespawnGameObject(guid, HOUR)` (cpp 136-139):
                    // NEEDS-MAP-HELPER, no gameobject-respawn helper on
                    // `Map` (`HOUR` = 3600s, `Common.h:128`). Reachable
                    // part (the registered guid set) transcribed.
                    // (Registered set kept in `red_rockets`.)
                }
            }
            GNO_TYPE_EXPLOSIVE_CHARGE => {
                match data {
                    GNO_DATA_EXPLOSIVE_CHARGE_1
                    | GNO_DATA_EXPLOSIVE_CHARGE_2
                    | GNO_DATA_EXPLOSIVE_CHARGE_3
                    | GNO_DATA_EXPLOSIVE_CHARGE_4 => {
                        // `DoRespawnGameObject(sorted, HOUR)` (cpp 144-159):
                        // NEEDS-MAP-HELPER (see above). The tracking push
                        // is the reachable part.
                        let slot = (data - 1) as usize;
                        let guid = self.gnomeregan().map_or(ObjectGuid::EMPTY, |s| {
                            s.explosive_sorted[slot / GNO_MAX_EXPLOSIVES_PER_SIDE]
                                [slot % GNO_MAX_EXPLOSIVES_PER_SIDE]
                        });
                        if guid != ObjectGuid::EMPTY {
                            // NEEDS-MAP-HELPER: respawn_gameobject(guid, 3600).
                            if let Some(s) = self.gnomeregan_mut() {
                                s.spawned_explosive_charges.push(guid);
                            }
                        }
                    }
                    GNO_DATA_EXPLOSIVE_CHARGE_USE => {
                        // `pExplosive->Use(pBlastmaster)` (cpp 160-169):
                        // NEEDS-MAP-HELPER, `gameobject_use` takes a player
                        // guid; no creature-as-user `GameObject::Use` path.
                        let blastmaster = self
                            .gnomeregan()
                            .map_or(ObjectGuid::EMPTY, |s| s.blastmaster_shortfuse);
                        if blastmaster == ObjectGuid::EMPTY {
                            return true;
                        }
                        // NEEDS-MAP-HELPER: creature-as-user
                        // `GameObject::Use` for each spawned charge.
                        if let Some(s) = self.gnomeregan_mut() {
                            s.spawned_explosive_charges.clear();
                        }
                    }
                    _ => {}
                }
                // C++ `return`s here: no save refresh on this field, even
                // though `DATA_EXPLOSIVE_CHARGE_3 == DONE (3)`.
                return true;
            }
            GNO_TYPE_THERMAPLUGG => {
                if let Some(s) = self.gnomeregan_mut() {
                    s.encounter[GNO_TYPE_THERMAPLUGG as usize] = data;
                }
                if data == IN_PROGRESS {
                    // Make door locked (cpp 175-185): `ResetDoorOrButton`
                    // gated on `getLootState() == GO_ACTIVATED` has no
                    // equivalent (no loot-state accessor, no door-reset
                    // helper on `Map`) -- unresolved. The flag set is the
                    // reachable part. Note the fork comment that the flag
                    // write races `GO::Update` there.
                    let door = self
                        .gnomeregan()
                        .map_or(ObjectGuid::EMPTY, |s| s.door_final_chamber);
                    if door != ObjectGuid::EMPTY {
                        let flags = self.object_get_field(door, offsets::GAMEOBJECT_FLAGS);
                        let _ = self.object_set_field(
                            door,
                            u32::from(offsets::GAMEOBJECT_FLAGS),
                            flags | GNO_GO_FLAG_LOCKED,
                        );
                    }
                    // Always directly activates this bomb-face (cpp 188).
                    self.gno_activate_bomb_face(2);
                } else if data == DONE || data == GNO_FAIL {
                    // Make door unlocked again (cpp 190-198): `UseDoorOrButton`
                    // gated on `getLootState() == GO_READY` transcribed as
                    // `use_door` (loot-state check dropped, no accessor).
                    let door = self
                        .gnomeregan()
                        .map_or(ObjectGuid::EMPTY, |s| s.door_final_chamber);
                    if door != ObjectGuid::EMPTY {
                        self.use_door(door);
                        let flags = self.object_get_field(door, offsets::GAMEOBJECT_FLAGS);
                        let _ = self.object_set_field(
                            door,
                            u32::from(offsets::GAMEOBJECT_FLAGS),
                            flags & !GNO_GO_FLAG_LOCKED,
                        );
                    }
                    // Deactivate all remaining bomb faces.
                    for i in 0..GNO_MAX_GNOME_FACES as u8 {
                        self.gno_deactivate_bomb_face(i);
                    }
                }
            }
            _ => return false,
        }
        // Save refresh (cpp 207-218): space-joined encounters. Guarded to
        // the two encounter fields only -- `DATA_EXPLOSIVE_CHARGE_3 == DONE`
        // must not trigger a save (that arm returns above regardless).
        if data == DONE
            && (field == GNO_TYPE_GRUBBIS || field == GNO_TYPE_THERMAPLUGG)
            && let Some(s) = self.gnomeregan_mut()
        {
            let e = s.encounter;
            s.save_string = format!("{} {}", e[0], e[1]);
        }
        true
    }

    /// East-to-west sort + south/north partition of the pending explosive
    /// charges (cpp 99-128). `sortFromEastToWest` orders by ascending Y;
    /// `GetDistanceOrder(south, north)` is true when the charge is 3D-
    /// closer to the south cave-in (`Object.cpp:1646`).
    fn gno_sort_explosive_charges(&mut self) {
        let mut charges: Vec<(ObjectGuid, Position)> = Vec::new();
        let pending = self
            .gnomeregan()
            .map_or(Vec::new(), |s| s.explosive_charges.clone());
        for guid in pending {
            if let Some(pos) = self.object_position(guid) {
                charges.push((guid, pos));
            }
        }
        if charges.is_empty() {
            return;
        }
        charges.sort_by(|a, b| a.1.y.total_cmp(&b.1.y));
        let south = self
            .gnomeregan()
            .map_or(ObjectGuid::EMPTY, |s| s.cave_in_south);
        let north = self
            .gnomeregan()
            .map_or(ObjectGuid::EMPTY, |s| s.cave_in_north);
        let (Some(south_pos), Some(north_pos)) =
            (self.object_position(south), self.object_position(north))
        else {
            return;
        };
        let mut south_count = 0usize;
        let mut north_count = 0usize;
        let mut sorted =
            [[ObjectGuid::EMPTY; GNO_MAX_EXPLOSIVES_PER_SIDE]; GNO_MAX_EXPLOSIVES_PER_SIDE];
        for (guid, pos) in charges {
            if crate::visibility::dist3d(pos, south_pos) < crate::visibility::dist3d(pos, north_pos)
                && south_count < GNO_MAX_EXPLOSIVES_PER_SIDE
            {
                sorted[0][south_count] = guid;
                south_count += 1;
            } else if north_count < GNO_MAX_EXPLOSIVES_PER_SIDE {
                sorted[1][north_count] = guid;
                north_count += 1;
            }
        }
        if let Some(s) = self.gnomeregan_mut() {
            s.explosive_sorted = sorted;
            s.explosive_charges.clear();
        }
    }

    /// `instance_gnomeregan::GetData`.
    pub(crate) fn gno_get_data(&self, field: u32) -> Option<u32> {
        let s = self.gnomeregan()?;
        match field {
            GNO_TYPE_GRUBBIS => Some(s.encounter[GNO_TYPE_GRUBBIS as usize]),
            GNO_TYPE_THERMAPLUGG => Some(s.encounter[GNO_TYPE_THERMAPLUGG as usize]),
            _ => None,
        }
    }

    /// `instance_gnomeregan::GetData64` (selectors are entry ids here).
    fn gno_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        let s = self.gnomeregan()?;
        let guid = match field {
            GNO_GO_CAVE_IN_NORTH => s.cave_in_north,
            GNO_GO_CAVE_IN_SOUTH => s.cave_in_south,
            GNO_NPC_ALARM_A_BOMB_2600 => s.alarm_a_bomb,
            _ => return None,
        };
        if guid.is_empty() { None } else { Some(guid) }
    }

    /// `instance_gnomeregan::Save`.
    fn gno_save(&self) -> Option<String> {
        self.gnomeregan().map(|s| s.save_string.clone())
    }

    /// `instance_gnomeregan::Load`.
    fn gno_load(&mut self, data: &str) {
        let mut loaded = [0u32; 2];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = 0; // NOT_STARTED
            }
        }
        if let Some(s) = self.gnomeregan_mut() {
            s.encounter = loaded;
        }
    }

    // ------------------------------------------------ instance: zulfarrak

    /// `instance_zulfarrak::OnCreatureCreate` (cpp 80-117). The
    /// `SetReactState(REACT_PASSIVE)` arms are commented out in the fork.
    fn zf_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            ZF_ENTRY_ZUMRAH => {
                if let Some(s) = self.zul_farrak_mut() {
                    s.zumrah = guid;
                }
            }
            ZF_ENTRY_BLY => {
                if let Some(s) = self.zul_farrak_mut() {
                    s.bly = guid;
                }
            }
            ZF_ENTRY_RAVEN => {
                if let Some(s) = self.zul_farrak_mut() {
                    s.raven = guid;
                }
            }
            ZF_ENTRY_ORO => {
                if let Some(s) = self.zul_farrak_mut() {
                    s.oro = guid;
                }
            }
            ZF_ENTRY_WEEGLI => {
                if let Some(s) = self.zul_farrak_mut() {
                    s.weegli = guid;
                }
            }
            ZF_ENTRY_MURTA => {
                if let Some(s) = self.zul_farrak_mut() {
                    s.murta = guid;
                }
            }
            ZF_ENTRY_UKORZ => {
                if let Some(s) = self.zul_farrak_mut() {
                    s.ukorz = guid;
                }
            }
            ZF_NPC_GAHZRILLA => {
                // Respawned Gahz'rilla despawns when the encounter already
                // started; the first sighting opens it (`IN_PROGRESS`).
                if self.zul_farrak().map_or(0, |s| s.gahzrilla_encounter) >= IN_PROGRESS {
                    self.despawn_creature_now(guid, 0);
                } else if let Some(s) = self.zul_farrak_mut() {
                    s.gahzrilla_encounter = IN_PROGRESS;
                }
            }
            _ => {}
        }
    }

    /// `instance_zulfarrak::OnObjectCreate` (cpp 119-129).
    fn zf_on_object_create(&mut self, guid: ObjectGuid) {
        if self.object_entry(guid) != Some(ZF_GO_END_DOOR) {
            return;
        }
        if let Some(s) = self.zul_farrak_mut() {
            s.end_door = guid;
        }
        // `pGo->UseDoorOrButton(0, true)`: the door was left open.
        if self.zul_farrak().map_or(0, |s| s.end_door_encounter) == DONE
            && guid != ObjectGuid::EMPTY
        {
            self.use_door(guid);
        }
    }

    /// `instance_zulfarrak::GetData` (cpp 131-143). Note: the fork has no
    /// `EVENT_END_DOOR` / `EVENT_GAHZRILLA` arms (they read 0).
    pub(crate) fn zf_get_data(&self, field: u32) -> Option<u32> {
        let s = self.zul_farrak()?;
        match field {
            ZF_EVENT_PYRAMID => Some(s.pyramid_phase),
            ZF_EVENT_ZUMRAH => Some(s.zumrah_encounter),
            ZF_EVENT_ANTUSUL => Some(s.antusul_encounter),
            _ => None,
        }
    }

    /// `instance_zulfarrak::GetData64` (cpp 145-167). The fork keys GUIDs
    /// by creature/GO entry and returns 0 when unset; Rust returns `None`.
    fn zf_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        let s = self.zul_farrak()?;
        let guid = match field {
            ZF_ENTRY_ZUMRAH => s.zumrah,
            ZF_ENTRY_BLY => s.bly,
            ZF_ENTRY_RAVEN => s.raven,
            ZF_ENTRY_ORO => s.oro,
            ZF_ENTRY_WEEGLI => s.weegli,
            ZF_ENTRY_MURTA => s.murta,
            ZF_ENTRY_UKORZ => s.ukorz,
            ZF_GO_END_DOOR => s.end_door,
            _ => return None,
        };
        (!guid.is_empty()).then_some(guid)
    }

    /// `instance_zulfarrak::SetData` (cpp 169-196). Returns true when the
    /// instance script owns the field (exemplar convention; the C++
    /// itself returns void). No `EVENT_GAHZRILLA` arm in the fork.
    pub(crate) fn zf_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            ZF_EVENT_PYRAMID => {
                if let Some(s) = self.zul_farrak_mut() {
                    s.pyramid_phase = data;
                }
            }
            ZF_EVENT_END_DOOR => {
                if let Some(s) = self.zul_farrak_mut() {
                    s.end_door_encounter = data;
                }
            }
            ZF_EVENT_ZUMRAH => {
                if let Some(s) = self.zul_farrak_mut() {
                    s.zumrah_encounter = data;
                }
            }
            ZF_EVENT_ANTUSUL => {
                if let Some(s) = self.zul_farrak_mut() {
                    s.antusul_encounter = data;
                }
            }
            _ => return false,
        }
        // Fork `SaveToDB` (cpp 187-195) has no Rust equivalent; only the
        // stream refresh is kept. It fires on ANY field set to DONE
        // (including EVENT_PYRAMID reaching WAVE_1 == 3). Shape is a
        // single value with NO trailing space.
        if data == DONE
            && let Some(s) = self.zul_farrak_mut()
        {
            s.save_string = format!("{}", s.end_door_encounter);
        }
        true
    }

    /// `instance_zulfarrak::MoveNPCIfAlive` (cpp 283-294). The `o`
    /// parameter is unused in the fork body (`MovePoint` takes x/y/z
    /// only; `SetHomePosition` reuses the NPC's own orientation), so it
    /// is dropped here.
    fn zf_move_npc_if_alive(&mut self, entry: u32, x: f32, y: f32, z: f32) {
        let Some(npc) = self.zf_get_data64(entry) else {
            return;
        };
        if !self.creatures.get(&npc).is_some_and(|c| c.unit.is_alive()) {
            return;
        }
        // `MovePoint(1, x, y, z, MOVE_PATHFINDING | MOVE_WALK_MODE)`;
        // `-10.0` keeps facing (`motion.rs`: only `> -7.0` applies one).
        let dest = Position::new(x, y, z, 0.0);
        self.creature_move_point(
            npc,
            1,
            dest,
            ZF_MOVE_PATHFINDING | ZF_MOVE_WALK_MODE,
            0.0,
            -10.0,
        );
        // `SetCombatStartPosition` / `SetHomePosition` have no `Map`
        // helper (recorded in TIER3-PROGRESS).
    }

    /// `instance_zulfarrak::SpawnPyramidWave` (cpp 296-307). The fork's
    /// commented-out `MoveRandom(10)` stays out.
    #[allow(clippy::cast_possible_truncation)]
    fn zf_spawn_pyramid_wave(&mut self, wave: u32) {
        // `instance->SummonCreature`: no summoner object; the fork default
        // kind/despawn (`TEMPSUMMON_DEAD_DESPAWN`, 25000 ms) applies.
        for row in ZF_PYRAMID_SPAWNS {
            if row[0] as u32 != wave {
                continue;
            }
            let at = Position::new(row[2], row[3], 8.87, 0.0);
            if let Some(summon) = self.summon_creature(
                row[1] as u32,
                at,
                ObjectGuid::EMPTY,
                ZF_TEMPSUMMON_DEAD_DESPAWN,
                25_000,
            ) && let Some(s) = self.zul_farrak_mut()
            {
                s.adds_at_base.push(summon);
            }
        }
    }

    /// `instance_zulfarrak::IsWaveAllDead` (cpp 309-328). Missing GUIDs
    /// count as dead (fork `GetCreature` returns null and skips them).
    fn zf_is_wave_all_dead(&self) -> bool {
        let Some(s) = self.zul_farrak() else {
            return true;
        };
        for guid in s.adds_at_base.iter().chain(s.movedadds.iter()) {
            if self.creatures.get(guid).is_some_and(|c| c.unit.is_alive()) {
                return false;
            }
        }
        true
    }

    /// `instance_zulfarrak::SendAddsUpStairs` (cpp 330-346). The fork
    /// pushes the add onto `movedadds` whenever the creature object
    /// exists (even dead); only the move itself needs it alive.
    #[allow(clippy::cast_possible_truncation, clippy::cast_precision_loss)]
    fn zf_send_adds_up_stairs(&mut self, count: u32) {
        for _ in 0..count {
            let next = self
                .zul_farrak()
                .and_then(|s| s.adds_at_base.first().copied());
            let Some(add) = next else {
                break;
            };
            // `addsAtBase.erase(addsAtBase.begin())` (pop front).
            if let Some(s) = self.zul_farrak_mut() {
                s.adds_at_base.remove(0);
            }
            if !self.creatures.contains_key(&add) {
                continue;
            }
            if self.creatures.get(&add).is_some_and(|c| c.unit.is_alive()) {
                // `MovePoint(0, 1880 + urand(0, 10), 1274, 42,
                // MOVE_PATHFINDING | MOVE_RUN_MODE)` then `SetWalk(false)`.
                let dest = Position::new(
                    1880.0 + self.spell_rng().irand(0, 10) as f32,
                    1274.0,
                    42.0,
                    0.0,
                );
                self.creature_move_point(
                    add,
                    0,
                    dest,
                    ZF_MOVE_PATHFINDING | ZF_MOVE_RUN_MODE,
                    0.0,
                    -10.0,
                );
                self.set_walk(add, false);
            }
            if let Some(s) = self.zul_farrak_mut() {
                s.movedadds.push(add);
            }
        }
    }

    /// `instance_zulfarrak::Update` (cpp 198-279). Timer `else` arms only
    /// subtract when the timer covers `diff_ms`, so plain `-=` cannot
    /// underflow (same guard shape as `deadmines`/`sfk`).
    fn zf_update(&mut self, diff_ms: u32) {
        let phase = self.zul_farrak().map_or(0, |s| s.pyramid_phase);
        match phase {
            ZF_PYRAMID_ARRIVED_AT_STAIR => {
                self.zf_spawn_pyramid_wave(1);
                self.zf_set_data(ZF_EVENT_PYRAMID, ZF_PYRAMID_WAVE_1);
                if let Some(s) = self.zul_farrak_mut() {
                    s.major_wave_timer_ms = 120_000;
                    s.minor_wave_timer_ms = 0;
                    s.add_group_size = 2;
                }
            }
            ZF_PYRAMID_WAVE_1 => {
                if self.zf_is_wave_all_dead() {
                    // Give players a few seconds before wave 2 to rebuff.
                    self.zf_set_data(ZF_EVENT_PYRAMID, ZF_PYRAMID_PRE_WAVE_2);
                    if let Some(s) = self.zul_farrak_mut() {
                        s.major_wave_timer_ms = 10_000;
                    }
                } else {
                    let minor = self.zul_farrak().map_or(0, |s| s.minor_wave_timer_ms);
                    if minor < diff_ms {
                        let n = self.zul_farrak().map_or(0, |s| s.add_group_size);
                        self.zf_send_adds_up_stairs(n);
                        if let Some(s) = self.zul_farrak_mut() {
                            s.add_group_size = s.add_group_size.wrapping_add(1);
                            s.minor_wave_timer_ms = 10_000;
                        }
                    } else if let Some(s) = self.zul_farrak_mut() {
                        s.minor_wave_timer_ms -= diff_ms;
                    }
                }
            }
            ZF_PYRAMID_PRE_WAVE_2 => {
                let major = self.zul_farrak().map_or(0, |s| s.major_wave_timer_ms);
                if major < diff_ms {
                    // Beginning 2nd wave!
                    self.zf_spawn_pyramid_wave(2);
                    self.zf_set_data(ZF_EVENT_PYRAMID, ZF_PYRAMID_WAVE_2);
                    if let Some(s) = self.zul_farrak_mut() {
                        s.minor_wave_timer_ms = 0;
                        s.add_group_size = 2;
                    }
                } else if let Some(s) = self.zul_farrak_mut() {
                    s.major_wave_timer_ms -= diff_ms;
                }
            }
            ZF_PYRAMID_WAVE_2 => {
                if self.zf_is_wave_all_dead() {
                    self.zf_spawn_pyramid_wave(3);
                    self.zf_set_data(ZF_EVENT_PYRAMID, ZF_PYRAMID_PRE_WAVE_3);
                    // Give NPCs time to return to their home spots.
                    if let Some(s) = self.zul_farrak_mut() {
                        s.major_wave_timer_ms = 5000;
                    }
                } else {
                    let minor = self.zul_farrak().map_or(0, |s| s.minor_wave_timer_ms);
                    if minor < diff_ms {
                        let n = self.zul_farrak().map_or(0, |s| s.add_group_size);
                        self.zf_send_adds_up_stairs(n);
                        if let Some(s) = self.zul_farrak_mut() {
                            s.add_group_size = s.add_group_size.wrapping_add(1);
                            s.minor_wave_timer_ms = 10_000;
                        }
                    } else if let Some(s) = self.zul_farrak_mut() {
                        s.minor_wave_timer_ms -= diff_ms;
                    }
                }
            }
            ZF_PYRAMID_PRE_WAVE_3 => {
                let major = self.zul_farrak().map_or(0, |s| s.major_wave_timer_ms);
                if major < diff_ms {
                    // Move NPCs to bottom of stair.
                    self.zf_move_npc_if_alive(ZF_ENTRY_BLY, 1887.92, 1228.179, 9.98);
                    self.zf_move_npc_if_alive(ZF_ENTRY_MURTA, 1891.57, 1228.68, 9.69);
                    self.zf_move_npc_if_alive(ZF_ENTRY_ORO, 1897.23, 1228.34, 9.43);
                    self.zf_move_npc_if_alive(ZF_ENTRY_RAVEN, 1883.68, 1227.95, 9.543);
                    self.zf_move_npc_if_alive(ZF_ENTRY_WEEGLI, 1878.02, 1227.65, 9.485);
                    self.zf_set_data(ZF_EVENT_PYRAMID, ZF_PYRAMID_WAVE_3);
                } else if let Some(s) = self.zul_farrak_mut() {
                    s.major_wave_timer_ms -= diff_ms;
                }
            }
            ZF_PYRAMID_WAVE_3 if self.zf_is_wave_all_dead() => {
                self.zf_set_data(ZF_EVENT_PYRAMID, ZF_PYRAMID_KILLED_ALL_TROLLS);
                // Move NPCs to their final positions.
                self.zf_move_npc_if_alive(ZF_ENTRY_BLY, 1883.82, 1200.83, 8.87);
                self.zf_move_npc_if_alive(ZF_ENTRY_MURTA, 1891.83, 1201.45, 8.87);
                self.zf_move_npc_if_alive(ZF_ENTRY_ORO, 1894.50, 1204.40, 8.87);
                self.zf_move_npc_if_alive(ZF_ENTRY_RAVEN, 1874.11, 1206.17, 8.87);
                self.zf_move_npc_if_alive(ZF_ENTRY_WEEGLI, 1877.52, 1199.63, 8.87);
            }
            _ => {}
        }
    }

    /// `instance_zulfarrak::Save` (cpp 348).
    fn zf_save(&self) -> Option<String> {
        self.zul_farrak().map(|s| s.save_string.clone())
    }

    /// `instance_zulfarrak::Load` (cpp 350-364). The C++ null-`chrIn`
    /// check has no Rust equivalent (`&str` is never null). Only `DONE`
    /// persists; anything else resets to `NOT_STARTED`.
    fn zf_load(&mut self, data: &str) {
        let mut value: u32 = data
            .split_whitespace()
            .next()
            .and_then(|tok| tok.parse().ok())
            .unwrap_or(0);
        if value != DONE {
            value = ZF_NOT_STARTED;
        }
        if let Some(s) = self.zul_farrak_mut() {
            s.end_door_encounter = value;
        }
    }

    // ------------------------------------------------ instance: blackfathom deeps

    /// `instance_blackfathom_deeps::OnCreatureCreate` (cpp 115-119).
    fn bfd_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        if entry == BFD_NPC_TWILIGHT_LORD_KELRIS
            && let Some(s) = self.blackfathom_deeps_mut()
        {
            s.twilight_lord_kelris = guid;
        }
    }

    /// `instance_blackfathom_deeps::OnObjectCreate` (cpp 122-149).
    fn bfd_on_object_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            BFD_GO_SHRINE_1 => {
                if let Some(s) = self.blackfathom_deeps_mut() {
                    s.shrine_1 = guid;
                }
            }
            BFD_GO_SHRINE_2 => {
                if let Some(s) = self.blackfathom_deeps_mut() {
                    s.shrine_2 = guid;
                }
            }
            BFD_GO_SHRINE_3 => {
                if let Some(s) = self.blackfathom_deeps_mut() {
                    s.shrine_3 = guid;
                }
            }
            BFD_GO_SHRINE_4 => {
                if let Some(s) = self.blackfathom_deeps_mut() {
                    s.shrine_4 = guid;
                }
            }
            BFD_GO_SHRINE_OF_GELIHAST => {
                if let Some(s) = self.blackfathom_deeps_mut() {
                    s.shrine_of_gelihast = guid;
                }
            }
            BFD_GO_ALTAR_OF_THE_DEEPS => {
                if let Some(s) = self.blackfathom_deeps_mut() {
                    s.altar_of_the_deeps = guid;
                }
            }
            BFD_GO_PORTAL_DOOR => {
                if let Some(s) = self.blackfathom_deeps_mut() {
                    s.main_door = guid;
                }
                let both_done = self.blackfathom_deeps().is_some_and(|s| {
                    s.encounter[BFD_ENCOUNTER_SHRINE as usize] == DONE
                        && s.encounter[BFD_ENCOUNTER_KELRIS as usize] == DONE
                });
                if both_done {
                    let _ = self.object_set_field(
                        guid,
                        u32::from(offsets::GAMEOBJECT_STATE),
                        GO_STATE_ACTIVE,
                    );
                }
            }
            _ => {}
        }
    }

    /// `instance_blackfathom_deeps::SetData` (cpp 151-193). Returns true
    /// when the instance script owns the field (exemplar convention;
    /// the C++ itself returns void).
    fn bfd_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            BFD_TYPE_KELRIS => {
                if data == DONE
                    && self
                        .blackfathom_deeps()
                        .is_some_and(|s| s.encounter[BFD_ENCOUNTER_SHRINE as usize] == DONE)
                {
                    let door = self
                        .blackfathom_deeps()
                        .map_or(ObjectGuid::EMPTY, |s| s.main_door);
                    if door != ObjectGuid::EMPTY {
                        self.use_door(door);
                    }
                }
                if let Some(s) = self.blackfathom_deeps_mut() {
                    s.encounter[BFD_ENCOUNTER_KELRIS as usize] = data;
                }
            }
            BFD_TYPE_SHRINE => {
                if data == IN_PROGRESS {
                    // Fork `ASSERT(m_uiShrinesLit < 4)` (cpp 164): the four
                    // fires each set `IN_PROGRESS` once (re-use blocked by
                    // `GO_FLAG_NO_INTERACT` in `go_fire_of_akumaiAI`), so the
                    // index below cannot overflow in practice.
                    if let Some(s) = self.blackfathom_deeps_mut() {
                        // Guarded index: a 5th IN_PROGRESS (fork
                        // ASSERT/UB) is a no-op here instead of a panic.
                        if s.shrines_lit < 4 {
                            let lit = s.shrines_lit;
                            s.spawn_mobs_timer_ms[lit as usize] = 3000;
                            s.check_event_end_ms = 5000;
                            s.shrines_lit += 1;
                        }
                    }
                // Fork commented-out `if (m_uiShrinesLit > 3) uiData = DONE;`
                // (cpp 169-170) is dead code; not transcribed.
                } else if data == DONE
                    && self
                        .blackfathom_deeps()
                        .is_some_and(|s| s.encounter[BFD_ENCOUNTER_KELRIS as usize] == DONE)
                {
                    let door = self
                        .blackfathom_deeps()
                        .map_or(ObjectGuid::EMPTY, |s| s.main_door);
                    if door != ObjectGuid::EMPTY {
                        self.use_door(door);
                    }
                }
                if let Some(s) = self.blackfathom_deeps_mut() {
                    s.encounter[BFD_ENCOUNTER_SHRINE as usize] = data;
                }
            }
            BFD_TYPE_AQUANIS => {
                if let Some(s) = self.blackfathom_deeps_mut() {
                    s.encounter[BFD_ENCOUNTER_AQUANIS as usize] = data;
                }
            }
            _ => return false,
        }
        // Fork `if (uiData == DONE)` save shape (cpp 181-192): separator
        // form, so no trailing space (unlike the `<< i << ' '` loop form).
        if data == DONE
            && let Some(s) = self.blackfathom_deeps_mut()
        {
            let e = s.encounter;
            s.save_string = format!("{} {} {}", e[0], e[1], e[2]);
        }
        true
    }

    /// `instance_blackfathom_deeps::GetData` (cpp 197-210).
    fn bfd_get_data(&self, field: u32) -> Option<u32> {
        let s = self.blackfathom_deeps()?;
        match field {
            BFD_TYPE_KELRIS => Some(s.encounter[BFD_ENCOUNTER_KELRIS as usize]),
            BFD_TYPE_SHRINE => Some(s.encounter[BFD_ENCOUNTER_SHRINE as usize]),
            BFD_TYPE_AQUANIS => Some(s.encounter[BFD_ENCOUNTER_AQUANIS as usize]),
            _ => None,
        }
    }

    /// `instance_blackfathom_deeps::GetData64` (cpp 212-233).
    /// `DATA_ALTAR_OF_THE_DEEPS` is cached by `OnObjectCreate` but has no
    /// `GetData64` case in the fork; mirrored by omission here.
    fn bfd_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        let s = self.blackfathom_deeps()?;
        let guid = match field {
            BFD_DATA_TWILIGHT_LORD_KELRIS => s.twilight_lord_kelris,
            BFD_DATA_SHRINE1 => s.shrine_1,
            BFD_DATA_SHRINE2 => s.shrine_2,
            BFD_DATA_SHRINE3 => s.shrine_3,
            BFD_DATA_SHRINE4 => s.shrine_4,
            BFD_DATA_SHRINE_OF_GELIHAST => s.shrine_of_gelihast,
            BFD_DATA_MAINDOOR => s.main_door,
            _ => return None,
        };
        (!guid.is_empty()).then_some(guid)
    }

    /// `instance_blackfathom_deeps::Save` (cpp 195).
    fn bfd_save(&self) -> Option<String> {
        self.blackfathom_deeps().map(|s| s.save_string.clone())
    }

    /// `instance_blackfathom_deeps::Load` (cpp 235-253). The C++ null
    /// `chrIn` check has no Rust equivalent (`&str` is never null).
    fn bfd_load(&mut self, data: &str) {
        let mut loaded = [0u32; BFD_MAX_ENCOUNTER];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = 0; // NOT_STARTED
            }
        }
        if let Some(s) = self.blackfathom_deeps_mut() {
            s.encounter = loaded;
        }
    }

    /// `instance_blackfathom_deeps::OnCreatureDeath` (cpp 254-258).
    fn bfd_on_creature_death(&mut self, victim: ObjectGuid) {
        if self.object_entry(victim) == Some(BFD_NPC_BARON_AQUANIS) {
            self.bfd_set_data(BFD_TYPE_AQUANIS, DONE);
        }
    }

    /// `instance_blackfathom_deeps::DoSpawnMobs` (cpp 261-302).
    fn bfd_spawn_mobs(&mut self, wave_index: u8) {
        let kelris = self
            .blackfathom_deeps()
            .map_or(ObjectGuid::EMPTY, |s| s.twilight_lord_kelris);
        if !self.creatures.contains_key(&kelris) {
            return;
        }
        // `pKelris->GetRespawnCoord` (cpp 268) is his spawn
        // position; `SetHomePosition(x, y, z, 0)` zeroes facing.
        let home = self.creatures.get(&kelris).map_or_else(
            || self.object_position(kelris).unwrap_or_default(),
            |c| {
                let h = c.home_position;
                Position::new(h.x, h.y, h.z, 0.0)
            },
        );
        for info in BFD_WAVE_SUMMON_INFORMATION {
            if info.wave_index != wave_index {
                continue;
            }
            for slot in info.slots {
                for k in 0..slot.count {
                    let loc = BFD_SPAWN_LOCATIONS[slot.summon_position as usize];
                    // `fPosY` spread for multi-count slots (cpp 287-288).
                    let mut y = loc.y;
                    if slot.count > 1 {
                        y = loc.y - BFD_INTERACTION_DISTANCE / 2.0
                            + f32::from(k) * BFD_INTERACTION_DISTANCE / f32::from(slot.count);
                    }
                    let at = Position::new(loc.x, y, loc.z, loc.o);
                    if let Some(summoned) = self.summon_creature(
                        info.npc_entry,
                        at,
                        kelris,
                        BFD_TEMPSUMMON_DEAD_DESPAWN,
                        0,
                    ) {
                        self.set_walk(summoned, true);
                        // `pSummoned->CastSpell(pSummoned, 7741, true)` (cpp 293).
                        let _ = self.cast_spell(
                            summoned,
                            BFD_SPELL_SUMMONED_DEMON_VISUAL,
                            CastTarget::SelfCast,
                            CastOptions {
                                triggered: true,
                                skip_known: true,
                                ..Default::default()
                            },
                        );
                        // `SetHomePosition` (cpp 294): direct field write,
                        // same as the `home_position` precedent in content.rs.
                        if let Some(c) = self.creatures.get_mut(&summoned) {
                            c.home_position = home;
                        }
                        // `SetInCombatWithZone()` (cpp 295).
                        self.set_in_combat_with_zone(summoned);
                        // Fork commented-out `MovePoint` (cpp 296) is dead
                        // code; not transcribed.
                        if let Some(s) = self.blackfathom_deeps_mut() {
                            s.wave_mobs.push(summoned);
                        }
                    }
                }
            }
        }
    }

    /// `instance_blackfathom_deeps::IsWaveEventFinished` (cpp 305-319).
    fn bfd_is_wave_event_finished(&self) -> bool {
        // If not all fires are lighted return.
        if self.blackfathom_deeps().map_or(0, |s| s.shrines_lit) < 4 {
            return false;
        }
        // Missing GUIDs (despawned/gone) read as dead, as in the fork's
        // `GetCreature` null path.
        let guids = self
            .blackfathom_deeps()
            .map_or(Vec::new(), |s| s.wave_mobs.clone());
        for guid in guids {
            if self.creatures.get(&guid).is_some_and(|c| c.unit.is_alive()) {
                return false;
            }
        }
        true
    }

    /// `instance_blackfathom_deeps::Update` (cpp 321-350).
    fn bfd_update(&mut self, diff_ms: u32) {
        // Only use this function if shrine event is in progress.
        if self
            .blackfathom_deeps()
            .map_or(0, |s| s.encounter[BFD_ENCOUNTER_SHRINE as usize])
            != IN_PROGRESS
        {
            return;
        }
        let check_due = self
            .blackfathom_deeps()
            .is_some_and(|s| s.check_event_end_ms <= diff_ms);
        if check_due {
            if self.bfd_is_wave_event_finished() {
                self.bfd_set_data(BFD_TYPE_SHRINE, DONE);
            } else if let Some(s) = self.blackfathom_deeps_mut() {
                s.check_event_end_ms = 1000;
            }
        } else if let Some(s) = self.blackfathom_deeps_mut() {
            s.check_event_end_ms -= diff_ms;
        }
        for i in 0..4u8 {
            let idx = i as usize;
            let timer = self
                .blackfathom_deeps()
                .map_or(0, |s| s.spawn_mobs_timer_ms[idx]);
            if timer == 0 {
                continue;
            }
            if timer <= diff_ms {
                if let Some(s) = self.blackfathom_deeps_mut() {
                    s.spawn_mobs_timer_ms[idx] = 0;
                }
                self.bfd_spawn_mobs(i);
            } else if let Some(s) = self.blackfathom_deeps_mut() {
                s.spawn_mobs_timer_ms[idx] -= diff_ms;
            }
        }
    }

    // ------------------------------------------------ instance: scarlet monastery

    /// `instance_scarlet_monastery::IsMograineOrWhitemaneDead` (cpp 200-210):
    /// a missing (despawned/unknown) boss counts as dead.
    fn sm_mograine_or_whitemane_dead(&self) -> bool {
        let (mograine, whitemane) = self
            .scarlet_monastery()
            .map_or((ObjectGuid::EMPTY, ObjectGuid::EMPTY), |s| {
                (s.mograine, s.whitemane)
            });
        for boss in [mograine, whitemane] {
            let dead = self.creatures.get(&boss).is_none_or(|c| !c.unit.is_alive());
            if dead {
                return true;
            }
        }
        false
    }

    /// One `m_events.ScheduleEvent` entry.
    fn sm_schedule_event(&mut self, event: u32, delay_ms: u32) {
        if let Some(s) = self.scarlet_monastery_mut() {
            s.ashbringer_events.push((event, delay_ms));
        }
    }

    /// `instance_scarlet_monastery::OnCreatureCreate` (cpp 122-149).
    fn sm_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            SM_NPC_SCARLET_SORCERER
            | SM_NPC_SCARLET_MYRIDON
            | SM_NPC_SCARLET_DEFENDER
            | SM_NPC_SCARLET_CHAPLAIN
            | SM_NPC_SCARLET_WIZARD
            | SM_NPC_SCARLET_CENTURION
            | SM_NPC_SCARLET_CHAMPION
            | SM_NPC_SCARLET_ABBOT
            | SM_NPC_SCARLET_MONK
            | SM_NPC_FAIRBANKS => {
                // `m_ashbringerReactedNpcs.emplace` (set semantics).
                if let Some(s) = self.scarlet_monastery_mut()
                    && !s.ashbringer_reacted_npcs.contains(&guid)
                {
                    s.ashbringer_reacted_npcs.push(guid);
                }
            }
            SM_NPC_COMMANDER_MOGRAINE => {
                if let Some(s) = self.scarlet_monastery_mut() {
                    s.mograine = guid;
                    if !s.ashbringer_reacted_npcs.contains(&guid) {
                        s.ashbringer_reacted_npcs.push(guid);
                    }
                }
            }
            SM_NPC_INQUISITOR_WHITEMANE => {
                if let Some(s) = self.scarlet_monastery_mut() {
                    s.whitemane = guid;
                }
            }
            SM_NPC_VORREL_SENGUTZ => {
                if let Some(s) = self.scarlet_monastery_mut() {
                    s.vorrel = guid;
                }
            }
            _ => {}
        }
    }

    /// `instance_scarlet_monastery::OnObjectCreate` (cpp 151-162).
    fn sm_on_object_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            SM_GO_HIGH_INQUISITOR_DOOR => {
                if let Some(s) = self.scarlet_monastery_mut() {
                    s.door_high_inquisitor = guid;
                }
            }
            SM_GO_CHAPEL_DOOR => {
                if let Some(s) = self.scarlet_monastery_mut() {
                    s.chapel_door = guid;
                }
            }
            _ => {}
        }
    }

    /// `instance_scarlet_monastery::OnCreatureDeath` (cpp 164-179): when one
    /// of the pair dies while the other is already dead, the encounter is
    /// done. A missing other boss reads as "not dead" here, matching the
    /// fork's null-`GetCreature` no-op.
    fn sm_on_creature_death(&mut self, victim: ObjectGuid) {
        let Some(entry) = self.object_entry(victim) else {
            return;
        };
        let other = match entry {
            SM_NPC_COMMANDER_MOGRAINE => self
                .scarlet_monastery()
                .map_or(ObjectGuid::EMPTY, |s| s.whitemane),
            SM_NPC_INQUISITOR_WHITEMANE => self
                .scarlet_monastery()
                .map_or(ObjectGuid::EMPTY, |s| s.mograine),
            _ => return,
        };
        if self
            .creatures
            .get(&other)
            .is_some_and(|c| !c.unit.is_alive())
        {
            self.sm_set_data(SM_TYPE_MOGRAINE_AND_WHITE_EVENT, SM_STAGE_MOGRAINE_DONE);
        }
    }

    /// `instance_scarlet_monastery::SetData` (cpp 212-331). Returns true when
    /// the instance script owns the field (exemplar convention; C++ returns
    /// void). Save refresh copies the fork exactly: the Mograine arm saves on
    /// `STAGE_MOGRAINE_DONE` (4), the Ashbringer arm on `DONE` (3).
    #[allow(clippy::too_many_lines)] // one SetData/Update port
    pub(crate) fn sm_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            SM_TYPE_MOGRAINE_AND_WHITE_EVENT => {
                let mut data = data;
                let current = self.scarlet_monastery().map_or(0, |s| s.encounter[0]);
                if data == SM_STAGE_MOGRAINE_NOT_STARTED && self.sm_mograine_or_whitemane_dead() {
                    // Dead bosses must not re-run the encounter (cpp 219-228):
                    // `AddObjectToRemoveList` both, then force DONE.
                    let (mograine, whitemane) = self
                        .scarlet_monastery()
                        .map_or((ObjectGuid::EMPTY, ObjectGuid::EMPTY), |s| {
                            (s.mograine, s.whitemane)
                        });
                    if mograine != ObjectGuid::EMPTY {
                        self.despawn_creature_now(mograine, 0);
                    }
                    if whitemane != ObjectGuid::EMPTY {
                        self.despawn_creature_now(whitemane, 0);
                    }
                    data = SM_STAGE_MOGRAINE_DONE;
                } else if data == SM_STAGE_MOGRAINE_NOT_STARTED
                    || data == SM_STAGE_MOGRAINE_IN_PROGRESS
                {
                    // Closing the High Inquisitor door writes `GO_STATE_READY`
                    // (`use_door` only opens; cpp 231-232).
                    let door = self
                        .scarlet_monastery()
                        .map_or(ObjectGuid::EMPTY, |s| s.door_high_inquisitor);
                    if door != ObjectGuid::EMPTY {
                        let _ = self.object_set_field(
                            door,
                            u32::from(offsets::GAMEOBJECT_STATE),
                            GO_STATE_READY,
                        );
                    }
                    if data == SM_STAGE_MOGRAINE_NOT_STARTED
                        && current == SM_STAGE_MOGRAINE_DIED_ONCE
                    {
                        // `SetDeathState(JUST_DIED)` + `Respawn()` on Whitemane
                        // (cpp 237-241) have no `Map` equivalent (unresolved).
                    }
                    if data == SM_STAGE_MOGRAINE_IN_PROGRESS {
                        // Mograine's nearby Scarlet adds join the fight
                        // (cpp 244-265).
                        let mograine = self
                            .scarlet_monastery()
                            .map_or(ObjectGuid::EMPTY, |s| s.mograine);
                        if let Some(mograine_pos) = self.object_position(mograine)
                            && let Some(victim) = self.unit_victim(mograine)
                        {
                            let assist: Vec<ObjectGuid> = self
                                .creatures
                                .values()
                                .filter(|c| {
                                    matches!(
                                        c.info.entry,
                                        SM_NPC_SCARLET_CHAPLAIN
                                            | SM_NPC_SCARLET_WIZARD
                                            | SM_NPC_SCARLET_CENTURION
                                            | SM_NPC_SCARLET_CHAMPION
                                            | SM_NPC_SCARLET_ABBOT
                                            | SM_NPC_SCARLET_MONK
                                    ) && crate::visibility::dist3d(
                                        c.unit.world.position(),
                                        mograine_pos,
                                    ) <= 82.0
                                })
                                .map(|c| c.unit.guid())
                                .collect();
                            for add in assist {
                                if self.creatures.get(&add).is_some_and(|c| c.unit.is_alive()) {
                                    self.attack_start(add, victim);
                                }
                            }
                        }
                    }
                } else if data == SM_STAGE_MOGRAINE_DIED_ONCE {
                    // Open the door; Whitemane yells and runs to Mograine
                    // (cpp 267-279).
                    let (door, whitemane, mograine) = self.scarlet_monastery().map_or(
                        (ObjectGuid::EMPTY, ObjectGuid::EMPTY, ObjectGuid::EMPTY),
                        |s| (s.door_high_inquisitor, s.whitemane, s.mograine),
                    );
                    if door != ObjectGuid::EMPTY {
                        // Fork `SetGoState(GO_STATE_ACTIVE)`.
                        let _ = self.object_set_field(
                            door,
                            u32::from(offsets::GAMEOBJECT_STATE),
                            GO_STATE_ACTIVE,
                        );
                    }
                    if whitemane != ObjectGuid::EMPTY {
                        self.do_script_text(SM_YELL_WHITEMANE, whitemane, None, -1);
                        if let Some(mograine_pos) = self.object_position(mograine) {
                            self.creature_move_point(
                                whitemane,
                                100,
                                mograine_pos,
                                SM_MOVE_PATHFINDING | SM_MOVE_RUN_MODE,
                                0.0,
                                -10.0,
                            );
                        }
                    }
                } else if data == SM_STAGE_MOGRAINE_REVIVED {
                    // `SetInCombatWithZone` on both bosses (cpp 280-289).
                    let (mograine, whitemane) = self
                        .scarlet_monastery()
                        .map_or((ObjectGuid::EMPTY, ObjectGuid::EMPTY), |s| {
                            (s.mograine, s.whitemane)
                        });
                    for boss in [mograine, whitemane] {
                        if self.creatures.get(&boss).is_some_and(|c| c.unit.is_alive())
                            && !self.ai_in_combat(boss)
                        {
                            self.set_in_combat_with_zone(boss);
                        }
                    }
                }
                if let Some(s) = self.scarlet_monastery_mut() {
                    s.encounter[0] = data;
                }
                // `OUT_SAVE_INST_DATA` + `SaveToDB` on DONE
                // (cpp 293-297) has no Rust persistence; `Save()`
                // recomputes live (see `sm_save`).
            }
            SM_TYPE_ASHBRINGER_EVENT => {
                if data == IN_PROGRESS {
                    // `LoadGrid` (cpp 304-305) is a no-op here: map grids are
                    // always resident.
                    let (chapel_door, whitemane) = self
                        .scarlet_monastery()
                        .map_or((ObjectGuid::EMPTY, ObjectGuid::EMPTY), |s| {
                            (s.chapel_door, s.whitemane)
                        });
                    if chapel_door != ObjectGuid::EMPTY {
                        // Fork `SetGoState(GO_STATE_ACTIVE)`; the
                        // `SetLootState(GO_ACTIVATED)` + `GO_FLAG_IN_USE`
                        // writes (cpp 309-310) have no equivalent.
                        let _ = self.object_set_field(
                            chapel_door,
                            u32::from(offsets::GAMEOBJECT_STATE),
                            GO_STATE_ACTIVE,
                        );
                    }
                    if self
                        .creatures
                        .get(&whitemane)
                        .is_some_and(|c| c.unit.is_alive())
                        && !self.ai_in_combat(whitemane)
                    {
                        // `DespawnOrUnsummon` (cpp 315).
                        self.despawn_creature_now(whitemane, 0);
                    }
                    // Scarlet Cathedral NPCs stand down (cpp 317-320).
                    let reacted: Vec<ObjectGuid> = self
                        .scarlet_monastery()
                        .map_or(Vec::new(), |s| s.ashbringer_reacted_npcs.clone());
                    for npc in reacted {
                        if self.creatures.get(&npc).is_some_and(|c| c.unit.is_alive())
                            && !self.ai_in_combat(npc)
                        {
                            // `SetFactionTemplateId(35)`.
                            let _ = self.object_set_field(
                                npc,
                                u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                                35,
                            );
                        }
                    }
                }
                if let Some(s) = self.scarlet_monastery_mut() {
                    s.encounter[1] = data;
                }
                // `OUT_SAVE_INST_DATA` + `SaveToDB` on DONE
                // (cpp 324-328): no Rust persistence.
            }
            _ => return false,
        }
        true
    }

    /// `instance_scarlet_monastery::GetData` (cpp 333-340).
    pub(crate) fn sm_get_data(&self, field: u32) -> Option<u32> {
        let s = self.scarlet_monastery()?;
        match field {
            SM_TYPE_MOGRAINE_AND_WHITE_EVENT => Some(s.encounter[0]),
            SM_TYPE_ASHBRINGER_EVENT => Some(s.encounter[1]),
            _ => None,
        }
    }

    /// `instance_scarlet_monastery::GetData64` (cpp 181-198): stored GUIDs;
    /// `EMPTY` reads as `None` (fork returns 0).
    pub(crate) fn sm_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        let s = self.scarlet_monastery()?;
        let guid = match field {
            SM_DATA_MOGRAINE => s.mograine,
            SM_DATA_WHITEMANE => s.whitemane,
            SM_DATA_VORREL => s.vorrel,
            SM_DATA_DOOR_WHITEMANE => s.door_high_inquisitor,
            SM_DATA_DOOR_CHAPEL => s.chapel_door,
            _ => return None,
        };
        (!guid.is_empty()).then_some(guid)
    }

    /// `instance_scarlet_monastery::Save` (cpp 362-368): streams the
    /// live encounter pair every call (no cached string in the fork).
    fn sm_save(&self) -> Option<String> {
        self.scarlet_monastery()
            .map(|s| format!("{} {}", s.encounter[0], s.encounter[1]))
    }

    /// `instance_scarlet_monastery::Load` (cpp 342-360): `IN_PROGRESS`
    /// resets to 0 (`NOT_STARTED`); other stages persist.
    fn sm_load(&mut self, data: &str) {
        let mut loaded = [0u32; SM_MAX_ENCOUNTER];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = 0; // NOT_STARTED
            }
        }
        if let Some(s) = self.scarlet_monastery_mut() {
            s.encounter = loaded;
        }
    }

    /// One due Ashbringer `EventMap` step of
    /// `instance_scarlet_monastery::Update` (cpp 407-491). A missing Mograine
    /// skips the step (the fork's `continue`).
    #[allow(clippy::too_many_lines)] // one SetData/Update port
    fn sm_ashbringer_event(&mut self, event: u32) {
        let mograine = self
            .scarlet_monastery()
            .map_or(ObjectGuid::EMPTY, |s| s.mograine);
        if !self.creatures.contains_key(&mograine) {
            return;
        }
        // `GetClosestCreatureWithEntry(pMograine, HIGHLORD, 100.0)` (open-coded).
        let highlord: Option<ObjectGuid> =
            self.object_position(mograine).and_then(|mograine_pos| {
                self.creatures
                    .values()
                    .filter(|c| c.info.entry == SM_NPC_HIGHLORD_MOGRAINE)
                    .map(|c| {
                        (
                            c.unit.guid(),
                            crate::visibility::dist3d(c.unit.world.position(), mograine_pos),
                        )
                    })
                    .filter(|(_, d)| *d <= 100.0)
                    .min_by(|a, b| a.1.total_cmp(&b.1))
                    .map(|(g, _)| g)
            });
        match event {
            SM_EVENT_KNEEL => {
                // `SetSheath(SHEATH_STATE_UNARMED)` + kneel (cpp 409-413).
                self.unit_set_byte(mograine, offsets::UNIT_FIELD_BYTES_2, 0, SHEATH_UNARMED);
                self.unit_set_byte(mograine, offsets::UNIT_FIELD_BYTES_1, 0, STAND_STATE_KNEEL);
                self.sm_schedule_event(SM_EVENT_TALK1, 2000);
            }
            SM_EVENT_TALK1 => {
                // Text targets the Ashbringer wielder when on the map
                // (cpp 414-418).
                let wielder = self
                    .scarlet_monastery()
                    .map_or(ObjectGuid::EMPTY, |s| s.ashbringer_wielder);
                if wielder != ObjectGuid::EMPTY && self.players.contains_key(&wielder) {
                    self.do_script_text(SM_SAY_COMMANDER1, mograine, Some(wielder), -1);
                }
            }
            SM_EVENT_SUMMON => {
                // The Highlord apparition walks to the cathedral (cpp 419-430).
                let at = Position::new(1_034.925_2, 1_399.065_3, 27.393_204, 6.257_957);
                if let Some(summoned) = self.summon_creature(
                    SM_NPC_HIGHLORD_MOGRAINE,
                    at,
                    mograine,
                    SM_TEMPSUMMON_TIMED_DESPAWN,
                    400_000,
                ) {
                    // `SetFactionTemporary`, `SetDisplayId`,
                    // `SetObjectScale(2.0)` have no equivalent (unresolved).
                    self.set_virtual_item_by_id(summoned, 0, 0);
                    let _ = self.cast_spell(
                        summoned,
                        SM_SPELL_MOGRAINE_COMETH_DND,
                        CastTarget::SelfCast,
                        CastOptions {
                            triggered: false,
                            skip_known: true,
                            ..Default::default()
                        },
                    );
                    let dest = Position::new(1_150.391_1, 1398.723, 32.546_13, 0.0);
                    self.creature_move_point(summoned, 0, dest, 0, 0.0, -10.0);
                }
                self.sm_schedule_event(SM_EVENT_TALK2, 48_500);
            }
            SM_EVENT_TALK2 => {
                if let Some(highlord) = highlord {
                    self.stop_moving(highlord);
                    // `SetFacingToObject` has no equivalent (unresolved).
                    self.do_script_text(SM_SAY_ASHBRINGER1, highlord, None, -1);
                }
                self.sm_schedule_event(SM_EVENT_STAND, 4000);
            }
            SM_EVENT_STAND => {
                // Mograine rises (cpp 440-446); `SetFacingToObject` unresolved.
                self.unit_set_byte(mograine, offsets::UNIT_FIELD_BYTES_2, 0, SHEATH_MELEE);
                self.handle_emote_command(mograine, SM_EMOTE_STATE_STAND);
                self.unit_set_byte(mograine, offsets::UNIT_FIELD_BYTES_1, 0, STAND_STATE_STAND);
                self.sm_schedule_event(SM_EVENT_TALK3, 2000);
            }
            SM_EVENT_TALK3 => {
                self.do_script_text(SM_SAY_COMMANDER2, mograine, None, -1);
                self.sm_schedule_event(SM_EVENT_TALK4, 4000);
            }
            SM_EVENT_TALK4 => {
                if let Some(highlord) = highlord {
                    self.do_script_text(SM_SAY_ASHBRINGER2, highlord, None, -1);
                }
                self.sm_schedule_event(SM_EVENT_SECOND_DOUBT, 4000);
            }
            SM_EVENT_SECOND_DOUBT => {
                // `HandleEmote(EMOTE_ONESHOT_QUESTION)` (cpp 456-459) has no
                // equivalent (unresolved).
                self.sm_schedule_event(SM_EVENT_POINT, 4000);
            }
            SM_EVENT_POINT => {
                // `HandleEmote(EMOTE_ONESHOT_POINT)` (cpp 461-464) unresolved.
                self.sm_schedule_event(SM_EVENT_ROAR, 3000);
            }
            SM_EVENT_ROAR => {
                // `HandleEmote(EMOTE_ONESHOT_BATTLEROAR)` (cpp 466-470)
                // unresolved.
                self.sm_schedule_event(SM_EVENT_TALK5, 4000);
            }
            SM_EVENT_TALK5 => {
                self.do_script_text(SM_SAY_COMMANDER3, mograine, None, -1);
                self.sm_schedule_event(SM_EVENT_SPELL, 4000);
            }
            SM_EVENT_SPELL => {
                // TODO comment in fork kept: the lightning visual on the
                // target is unmodeled (cpp 477).
                if let Some(highlord) = highlord {
                    let _ = self.cast_spell(
                        highlord,
                        SM_SPELL_FORGIVENESS,
                        CastTarget::Unit(mograine),
                        CastOptions {
                            triggered: false,
                            skip_known: true,
                            ..Default::default()
                        },
                    );
                }
                self.sm_schedule_event(SM_EVENT_FORGIVEN, 4000);
            }
            SM_EVENT_FORGIVEN => {
                if let Some(highlord) = highlord {
                    self.do_script_text(SM_SAY_ASHBRINGER3, highlord, None, -1);
                }
                self.sm_schedule_event(SM_EVENT_DESPAWN, 4000);
            }
            SM_EVENT_DESPAWN => {
                // `((TemporarySummon*)pHighlord)->UnSummon()` (cpp 486-490).
                if let Some(highlord) = highlord {
                    self.despawn_creature_now(highlord, 0);
                }
                if let Some(s) = self.scarlet_monastery_mut() {
                    s.ashbringer_wielder = ObjectGuid::EMPTY;
                }
            }
            _ => {}
        }
    }

    /// `instance_scarlet_monastery::OnCreatureSpellHit` (cpp 370-393):
    /// a player hitting Mograine with the Ashbringer proc starts the
    /// apparition (`SetFacingToObject` has no equivalent).
    #[allow(clippy::cast_sign_loss)]
    fn sm_on_creature_spell_hit(
        &mut self,
        caster: ObjectGuid,
        receiver: ObjectGuid,
        spell_id: u32,
    ) {
        if self
            .scarlet_monastery()
            .is_some_and(|s| s.ashbringer_active)
        {
            return;
        }
        if !caster.is_player() || spell_id != SM_SPELL_AB_EFFECT {
            return;
        }
        if self.object_entry(receiver) != Some(SM_NPC_COMMANDER_MOGRAINE)
            || !self
                .creatures
                .get(&receiver)
                .is_some_and(|c| c.unit.is_alive())
        {
            return;
        }
        if let Some(s) = self.scarlet_monastery_mut() {
            s.ashbringer_wielder = caster;
            s.ashbringer_active = true;
        }
        let kneel_ms = self.spell_rng().irand(1000, 2000) as u32;
        self.sm_schedule_event(SM_EVENT_KNEEL, kneel_ms);
        self.sm_schedule_event(SM_EVENT_SUMMON, 20);
    }

    /// `instance_scarlet_monastery::Update` (cpp 395-495): only the Ashbringer
    /// apparition runs here. Due `EventMap` entries fire in schedule order;
    /// entries scheduled mid-tick wait for the next update, as in the fork.
    fn sm_update(&mut self, diff_ms: u32) {
        if !self
            .scarlet_monastery()
            .is_some_and(|s| s.ashbringer_active)
        {
            return;
        }
        let due: Vec<u32> = self.scarlet_monastery_mut().map_or(Vec::new(), |s| {
            for (_, remaining) in &mut s.ashbringer_events {
                *remaining = remaining.saturating_sub(diff_ms);
            }
            let mut due = Vec::new();
            s.ashbringer_events.retain(|(id, remaining)| {
                if *remaining == 0 {
                    due.push(*id);
                    false
                } else {
                    true
                }
            });
            due
        });
        for event in due {
            self.sm_ashbringer_event(event);
        }
    }

    // ------------------------------------------------ instance: zulgurub

    /// `instance_zulgurub::Create` (cpp 339-346) + `GenerateRandomBoss`
    /// (cpp 361-369): `GetGameDay()` is `(gameTime + tzOffset) / DAY`
    /// with the fork's default zero offset. Run lazily on the first
    /// instance update (the fork runs it at instance creation; the
    /// Rust map has no clock until its first tick). `SpawnRandomBoss`
    /// is deactivated in the fork (early return, cpp 371-374) beyond
    /// setting the spawned flag.
    #[allow(clippy::cast_possible_truncation)]
    fn zg_create(&mut self) {
        let day = (self.now_unix / 86_400) as u32;
        let weekmod = ((day - (day % 14)) / 14) % 3;
        if let Some(s) = self.zul_gurub_mut() {
            s.encounter[9] = 15_082 + weekmod;
            // `GenSaveData(m_auiEncounter, 11)` streams slots 0..=11,
            // separator form, no trailing space (`ScriptedInstance.cpp:98`).
            let e = s.encounter;
            s.save_string = format!(
                "{} {} {} {} {} {} {} {} {} {} {} {}",
                e[0], e[1], e[2], e[3], e[4], e[5], e[6], e[7], e[8], e[9], e[10], e[11]
            );
            s.random_boss_spawned = true;
        }
    }

    /// Lazy `Create()` carrier: the fork has no `Update` override,
    /// so the dispatcher arm exists only to run `zg_create` once
    /// (skipped after `Load`, which sets the spawned flag itself).
    fn zg_update(&mut self, _diff_ms: u32) {
        if self.now_unix != 0 && !self.zul_gurub().is_some_and(|s| s.random_boss_spawned) {
            self.zg_create();
        }
    }

    /// `instance_zulgurub::IsEncounterInProgress` (cpp 86-92).
    fn zg_is_encounter_in_progress(&self) -> bool {
        self.zul_gurub().is_some_and(|s| {
            s.encounter
                .iter()
                .any(|&v| v == IN_PROGRESS || v == ZG_SPECIAL)
        })
    }

    /// `instance_zulgurub::HandleLoadCreature` (cpp 144-153): a DONE
    /// encounter drops the just-spawned creature. Returns whether the
    /// encounter was DONE. `u32::MAX` = no respawn: DONE bosses stay
    /// gone (the fork re-removes them on every respawn; steady state
    /// is identical).
    fn zg_handle_load_creature(&mut self, field: u32, guid: ObjectGuid) -> bool {
        let done = self.zg_get_data(field) == Some(DONE);
        if done {
            // `AddObjectToRemoveList` (cpp 149).
            self.despawn_creature_now(guid, u32::MAX);
        }
        done
    }

    /// `UpdateHakkarPowerStacks` (cpp 46-84).
    fn zg_update_hakkar_power_stacks(&mut self) {
        let hakkar = self.zul_gurub().map_or(ObjectGuid::EMPTY, |s| s.hakkar);
        if hakkar == ObjectGuid::EMPTY || !self.unit_is_alive(hakkar) {
            return;
        }
        // High priests still standing: encounter slots 0..5 (cpp 53-57).
        let needed = self.zul_gurub().map_or(0, |s| {
            s.encounter[0..5].iter().filter(|&&v| v != DONE).count() as u32
        });
        let current = self
            .aura_holders(hakkar)
            .iter()
            .find(|h| h.spell_id == ZG_SPELL_HAKKAR_POWER)
            .map_or(0, |h| h.stack);
        if needed == current {
            return;
        }
        if needed == 0 {
            self.remove_auras_due_to_spell(hakkar, ZG_SPELL_HAKKAR_POWER);
            return;
        }
        if current == 0 {
            for _ in 0..needed {
                let _ = self.cast_spell(
                    hakkar,
                    ZG_SPELL_HAKKAR_POWER,
                    CastTarget::SelfCast,
                    CastOptions {
                        triggered: true,
                        skip_known: true,
                        ..Default::default()
                    },
                );
            }
        }
        // Fork `SetStackAmount` (and the landing stack of the
        // cast loop above, which the Rust refresh path does
        // not increment).
        self.set_aura_stack_amount(hakkar, ZG_SPELL_HAKKAR_POWER, needed);
    }

    /// `Thekal_GetUnitThatCanRez` (cpp 386-398): alive and not
    /// fake-dead. Stand state is byte 0 of `UNIT_FIELD_BYTES_1`
    /// (`UNIT_STAND_STATE_DEAD` = 7).
    fn zg_thekal_unit_that_can_rez(&self) -> Option<ObjectGuid> {
        let (lorkhan, zath, thekal) = self.zul_gurub().map(|s| (s.lorkhan, s.zath, s.thekal))?;
        [lorkhan, zath, thekal].into_iter().find(|&guid| {
            guid != ObjectGuid::EMPTY
                && self.unit_is_alive(guid)
                && (self.unit_value_u32(guid, offsets::UNIT_FIELD_BYTES_1) & 0xFF) != 7
        })
    }

    /// `Thekal_GetUnitThatNeedsRez` (cpp 400-412): alive but
    /// fake-dead.
    fn zg_thekal_unit_that_needs_rez(&self) -> Option<ObjectGuid> {
        let (lorkhan, zath, thekal) = self.zul_gurub().map(|s| (s.lorkhan, s.zath, s.thekal))?;
        [lorkhan, zath, thekal].into_iter().find(|&guid| {
            guid != ObjectGuid::EMPTY
                && self.unit_is_alive(guid)
                && (self.unit_value_u32(guid, offsets::UNIT_FIELD_BYTES_1) & 0xFF) == 7
        })
    }

    /// `Thekal_GetUnitCastingRez` (cpp 414-429):
    /// `GetCurrentSpell(CURRENT_GENERIC_SPELL)` reduced to the single
    /// active-cast store.
    fn zg_thekal_unit_casting_rez(&self) -> Option<ObjectGuid> {
        let (lorkhan, zath, thekal) = self.zul_gurub().map(|s| (s.lorkhan, s.zath, s.thekal))?;
        [lorkhan, zath, thekal]
            .into_iter()
            .find(|&guid| self.bot_casting_spell(guid) == Some(ZG_SPELL_THEKAL_RESURRECTION))
    }

    /// `instance_zulgurub::OnCreatureCreate` (cpp 94-142).
    fn zg_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            ZG_NPC_LORKHAN => {
                let done = self.zg_handle_load_creature(ZG_TYPE_THEKAL, guid);
                if let Some(s) = self.zul_gurub_mut() {
                    s.lorkhan = if done { ObjectGuid::EMPTY } else { guid };
                }
            }
            ZG_NPC_ZATH => {
                let done = self.zg_handle_load_creature(ZG_TYPE_THEKAL, guid);
                if let Some(s) = self.zul_gurub_mut() {
                    s.zath = if done { ObjectGuid::EMPTY } else { guid };
                }
            }
            ZG_NPC_THEKAL => {
                let done = self.zg_handle_load_creature(ZG_TYPE_THEKAL, guid);
                if let Some(s) = self.zul_gurub_mut() {
                    s.thekal = if done { ObjectGuid::EMPTY } else { guid };
                }
                self.zg_update_hakkar_power_stacks();
            }
            ZG_NPC_JINDO => {
                if let Some(s) = self.zul_gurub_mut() {
                    s.jindo = guid;
                }
            }
            ZG_NPC_HAKKAR => {
                let done = self.zg_handle_load_creature(ZG_TYPE_HAKKAR, guid);
                if let Some(s) = self.zul_gurub_mut() {
                    s.hakkar = if done { ObjectGuid::EMPTY } else { guid };
                }
                self.zg_update_hakkar_power_stacks();
            }
            ZG_NPC_VENOXIS => {
                let _ = self.zg_handle_load_creature(ZG_TYPE_VENOXIS, guid);
                self.zg_update_hakkar_power_stacks();
            }
            ZG_NPC_ARLOKK => {
                let _ = self.zg_handle_load_creature(ZG_TYPE_ARLOKK, guid);
                self.zg_update_hakkar_power_stacks();
            }
            ZG_NPC_MARLI => {
                let _ = self.zg_handle_load_creature(ZG_TYPE_MARLI, guid);
                // Fork stores Marli unconditionally (cpp 126), even
                // when the DONE check just despawned her.
                if let Some(s) = self.zul_gurub_mut() {
                    s.marli = guid;
                }
                self.zg_update_hakkar_power_stacks();
            }
            ZG_NPC_JEKLIK => {
                self.zg_update_hakkar_power_stacks();
            }
            ZG_NPC_RAZZASHI_SKITTERER
            | ZG_NPC_RAZZASHI_VENOMBROOD
            | ZG_NPC_HAKARI_SHADOWCASTER
            | ZG_NPC_RAZZASHI_BROODWIDOW => {
                if let Some(s) = self.zul_gurub_mut() {
                    s.marli_trash.push(guid);
                }
            }
            ZG_NPC_GAHZRANKA => {
                if let Some(s) = self.zul_gurub_mut() {
                    s.gahzranka = guid;
                }
            }
            _ => {}
        }
    }

    /// `instance_zulgurub::OnCreatureDeath` (cpp 348-359).
    fn zg_on_creature_death(&mut self, victim: ObjectGuid) {
        let Some(entry) = self.object_entry(victim) else {
            return;
        };
        // `BOSS_GRILEK..BOSS_WUSHOOLAY` (cpp 351).
        if (15_082..=15_085).contains(&entry) {
            self.zg_set_data(ZG_TYPE_RANDOM_BOSS, DONE);
        }
        if entry == ZG_NPC_NIGHTMARE_ILLUSION {
            // Fork `ForcedDespawn(3000)` delay has no helper;
            // `SetRespawnTime(345600000)` (cpp 357) ~= never, hence
            // `u32::MAX`.
            self.despawn_creature_now(victim, u32::MAX);
        }
    }

    /// `instance_zulgurub::SetData` (cpp 155-238).
    #[allow(clippy::too_many_lines)] // one SetData/Update port
    fn zg_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            ZG_TYPE_HAKKAR_POWER => {
                self.zg_update_hakkar_power_stacks();
            }
            ZG_TYPE_ARLOKK => {
                if let Some(s) = self.zul_gurub_mut() {
                    s.encounter[0] = data;
                }
            }
            ZG_TYPE_JEKLIK => {
                if let Some(s) = self.zul_gurub_mut() {
                    s.encounter[1] = data;
                }
            }
            ZG_TYPE_VENOXIS => {
                if let Some(s) = self.zul_gurub_mut() {
                    s.encounter[2] = data;
                }
            }
            ZG_TYPE_MARLI => {
                if let Some(s) = self.zul_gurub_mut() {
                    s.encounter[3] = data;
                }
                if data == IN_PROGRESS {
                    let marli = self.zul_gurub().map_or(ObjectGuid::EMPTY, |s| s.marli);
                    let Some(victim) = self.unit_victim(marli) else {
                        return true;
                    };
                    let trash: Vec<ObjectGuid> = self
                        .zul_gurub()
                        .map_or(Vec::new(), |s| s.marli_trash.clone());
                    for guid in trash {
                        // Fork also requires map 309 / zone 1977 /
                        // area 3379 (cpp 181); no zone/area helper
                        // (unresolved).
                        if self.unit_is_alive(guid) && !self.ai_in_combat(guid) {
                            self.enter_combat(guid, victim);
                        }
                    }
                }
            }
            ZG_TYPE_THEKAL => {
                if let Some(s) = self.zul_gurub_mut() {
                    s.encounter[4] = data;
                }
            }
            ZG_TYPE_THEKAL_DEATH_TIME => {
                // `data == SPECIAL` stores `sWorld.GetGameTime()`
                // (cpp 189-194), truncated into the u32 slot as in
                // the fork; `now_unix` is the same epoch-second clock.
                let value = if data == ZG_SPECIAL {
                    self.now_unix as u32
                } else {
                    data
                };
                if let Some(s) = self.zul_gurub_mut() {
                    s.encounter[5] = value;
                }
            }
            ZG_TYPE_THEKAL_REZ_TIME => {
                let value = if data == ZG_SPECIAL {
                    self.now_unix as u32
                } else {
                    data
                };
                if let Some(s) = self.zul_gurub_mut() {
                    s.encounter[6] = value;
                }
            }
            ZG_TYPE_OHGAN => {
                if let Some(s) = self.zul_gurub_mut() {
                    s.encounter[7] = data;
                }
            }
            ZG_TYPE_HAKKAR => {
                if let Some(s) = self.zul_gurub_mut() {
                    s.encounter[8] = data;
                }
            }
            ZG_TYPE_RANDOM_BOSS => {
                // `data == 0` re-rolls from
                // `sGameEventMgr.IsActiveEvent(29..32)` (cpp 207-219);
                // game events have no `Map` equivalent (unresolved).
                if data != 0 {
                    if let Some(s) = self.zul_gurub_mut() {
                        s.encounter[9] = data;
                    }
                }
            }
            ZG_TYPE_JINDO => {
                if let Some(s) = self.zul_gurub_mut() {
                    s.encounter[10] = data;
                }
            }
            ZG_TYPE_GAHZRANKA => {
                if let Some(s) = self.zul_gurub_mut() {
                    s.encounter[11] = data;
                }
            }
            _ => return false,
        }
        if data == DONE
            && let Some(s) = self.zul_gurub_mut()
        {
            let e = s.encounter;
            s.save_string = format!(
                "{} {} {} {} {} {} {} {} {} {} {} {}",
                e[0], e[1], e[2], e[3], e[4], e[5], e[6], e[7], e[8], e[9], e[10], e[11]
            );
        }
        true
    }

    /// `instance_zulgurub::GetData` (cpp 265-297).
    fn zg_get_data(&self, field: u32) -> Option<u32> {
        let s = self.zul_gurub()?;
        match field {
            ZG_TYPE_ARLOKK => Some(s.encounter[0]),
            ZG_TYPE_JEKLIK => Some(s.encounter[1]),
            ZG_TYPE_VENOXIS => Some(s.encounter[2]),
            ZG_TYPE_MARLI => Some(s.encounter[3]),
            ZG_TYPE_THEKAL => Some(s.encounter[4]),
            ZG_TYPE_THEKAL_DEATH_TIME => Some(s.encounter[5]),
            ZG_TYPE_THEKAL_REZ_TIME => Some(s.encounter[6]),
            ZG_TYPE_OHGAN => Some(s.encounter[7]),
            ZG_TYPE_HAKKAR => Some(s.encounter[8]),
            ZG_TYPE_RANDOM_BOSS => {
                let v = s.encounter[9];
                // Fork range `15080..=15085` (cpp 288); the boss
                // entries proper are `15082..=15085`.
                if (15_080..=15_085).contains(&v) {
                    Some(v)
                } else {
                    Some(0)
                }
            }
            ZG_TYPE_JINDO => Some(s.encounter[10]),
            ZG_TYPE_GAHZRANKA => Some(s.encounter[11]),
            _ => None,
        }
    }

    /// `instance_zulgurub::GetData64` (cpp 299-321).
    fn zg_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        // `DATA_THEKAL_NEED_REZ` resolves a unit, not a stored GUID.
        if field == ZG_DATA_THEKAL_NEED_REZ {
            return self.zg_thekal_unit_that_needs_rez();
        }
        let guid = match field {
            ZG_DATA_LORKHAN => self.zul_gurub().map_or(ObjectGuid::EMPTY, |s| s.lorkhan),
            ZG_DATA_ZATH => self.zul_gurub().map_or(ObjectGuid::EMPTY, |s| s.zath),
            ZG_DATA_THEKAL => self.zul_gurub().map_or(ObjectGuid::EMPTY, |s| s.thekal),
            ZG_DATA_JINDO => self.zul_gurub().map_or(ObjectGuid::EMPTY, |s| s.jindo),
            ZG_DATA_HAKKAR => self.zul_gurub().map_or(ObjectGuid::EMPTY, |s| s.hakkar),
            ZG_DATA_GAHZRANKA => self.zul_gurub().map_or(ObjectGuid::EMPTY, |s| s.gahzranka),
            _ => return None,
        };
        if guid.is_empty() { None } else { Some(guid) }
    }

    /// `instance_zulgurub::CheckConditionCriteriaMeet` (cpp 323-337).
    /// `player`/`source` are unused by the fork body.
    fn zg_check_condition(&self, map_id: u32, condition_id: u32) -> bool {
        // `MAP_ZUL_GURUB` (cpp 325).
        if map_id != 309 {
            return false;
        }
        match condition_id {
            // Thekal encounter: a unit that can rez exists.
            1 => self.zg_thekal_unit_that_can_rez().is_some(),
            // Thekal encounter: a unit needs rez, none is casting
            // it, and both stored times are 10s past (cpp 333).
            2 => {
                let (death, rez) = self
                    .zul_gurub()
                    .map_or((0, 0), |s| (s.encounter[5], s.encounter[6]));
                self.zg_thekal_unit_that_needs_rez().is_some()
                    && self.zg_thekal_unit_casting_rez().is_none()
                    && u64::from(death) + 10 < self.now_unix
                    && u64::from(rez) + 10 < self.now_unix
            }
            _ => false,
        }
    }

    /// `instance_zulgurub::Save` (cpp 240).
    fn zg_save(&self) -> Option<String> {
        self.zul_gurub().map(|s| s.save_string.clone())
    }

    /// `instance_zulgurub::Load` (cpp 242-263). `LoadSaveData` streams
    /// slots 0..=11 and leaves slot 12 untouched; the `IN_PROGRESS`
    /// sweep covers all 13 slots.
    fn zg_load(&mut self, data: &str) {
        let mut loaded = [0u32; 12];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        if let Some(s) = self.zul_gurub_mut() {
            s.encounter[0..12].copy_from_slice(&loaded);
            for value in &mut s.encounter {
                if *value == IN_PROGRESS {
                    *value = 0; // NOT_STARTED
                }
            }
            // `SpawnRandomBoss` is deactivated (early return, cpp 371).
            s.random_boss_spawned = true;
        }
    }

    // ------------------------------------------------ instance: uldaman

    /// `instance_uldaman::OnCreatureCreate` (cpp 89-135).
    fn uld_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            ULD_NPC_STONE_KEEPER => {
                if let Some(s) = self.uldaman_mut() {
                    if !s.stone_keeper.contains(&guid) {
                        s.stone_keeper.push(guid);
                    }
                }
                if self.uldaman().map_or(0, |s| {
                    s.encounter[ULD_ULDAMAN_ENCOUNTER_STONE_KEEPERS as usize]
                }) != DONE
                {
                    self.uld_apply_refreeze(guid);
                    self.uld_respawn_minion(guid);
                }
            }
            ULD_NPC_EARTHEN_CUSTODIAN | ULD_NPC_EARTHEN_HALLSHAPER => {
                if let Some(s) = self.uldaman_mut() {
                    if !s.archaedas_wall_minions.contains(&guid) {
                        s.archaedas_wall_minions.push(guid);
                    }
                }
                if self
                    .uldaman()
                    .map_or(0, |s| s.encounter[ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS as usize])
                    != DONE
                {
                    self.uld_apply_refreeze(guid);
                    self.uld_respawn_minion(guid);
                }
            }
            ULD_NPC_EARTHEN_GUARDIAN => {
                if let Some(s) = self.uldaman_mut() {
                    if !s.earthen_guardian.contains(&guid) {
                        s.earthen_guardian.push(guid);
                    }
                }
                if self
                    .uldaman()
                    .map_or(0, |s| s.encounter[ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS as usize])
                    != DONE
                {
                    self.uld_apply_refreeze(guid);
                    self.uld_respawn_minion(guid);
                }
            }
            ULD_NPC_IRONAYA => {
                if let Some(s) = self.uldaman_mut() {
                    s.ironaya = guid;
                }
                if self.uldaman().map_or(0, |s| {
                    s.encounter[ULD_ULDAMAN_ENCOUNTER_IRONAYA_DOOR as usize]
                }) != DONE
                {
                    self.uld_set_frozen_state(guid);
                }
            }
            ULD_NPC_VAULT_WARDER => {
                // Only take the ones inside the Archaedas room (cpp 122).
                let near_room = self.object_position(guid).is_some_and(|p| {
                    crate::visibility::dist2d(p, Position::new(104.0, 272.0, 0.0, 0.0)) <= 35.0
                });
                if near_room {
                    if let Some(s) = self.uldaman_mut() {
                        if !s.vault_warder.contains(&guid) {
                            s.vault_warder.push(guid);
                        }
                    }
                    if self
                        .uldaman()
                        .map_or(0, |s| s.encounter[ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS as usize])
                        != DONE
                    {
                        self.uld_apply_refreeze(guid);
                        self.uld_respawn_minion(guid);
                    }
                } else if let Some(s) = self.uldaman_mut() {
                    if !s.vault_warder_furniture.contains(&guid) {
                        s.vault_warder_furniture.push(guid);
                    }
                }
            }
            ULD_NPC_ARCHAEDAS => {
                if let Some(s) = self.uldaman_mut() {
                    s.archaedas = guid;
                }
            }
            _ => {}
        }
    }

    /// `instance_uldaman::OnObjectCreate` (cpp 137-176).
    fn uld_on_object_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            ULD_GO_ALTAR_ARCHAEDAS => {
                if let Some(s) = self.uldaman_mut() {
                    s.altar_of_archaedas = guid;
                }
            }
            ULD_GO_ALTAR_KEEPERS => {
                if let Some(s) = self.uldaman_mut() {
                    s.altar_of_the_keeper = guid;
                }
            }
            ULD_GO_ALTAR_OF_THE_KEEPER_TEMPLE_DOOR => {
                if let Some(s) = self.uldaman_mut() {
                    s.altar_of_the_keeper_temple_door = guid;
                }
                if self.uldaman().map_or(0, |s| {
                    s.encounter[ULD_ULDAMAN_ENCOUNTER_STONE_KEEPERS as usize]
                }) == DONE
                {
                    self.use_door(guid);
                }
            }
            ULD_GO_ARCHAEDAS_TEMPLE_DOOR => {
                if let Some(s) = self.uldaman_mut() {
                    s.archaedas_temple_door = guid;
                }
                if self
                    .uldaman()
                    .map_or(0, |s| s.encounter[ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS as usize])
                    == DONE
                {
                    self.use_door(guid);
                }
            }
            ULD_GO_ANCIENT_VAULT_DOOR => {
                // Fork `SetGoState(GO_STATE_READY)` + `SetUInt32Value(flags, 33)`
                // (cpp 159-160): direct writes, then a DONE-gated open.
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::GAMEOBJECT_STATE),
                    GO_STATE_READY,
                );
                let _ = self.object_set_field(guid, u32::from(offsets::GAMEOBJECT_FLAGS), 33);
                if let Some(s) = self.uldaman_mut() {
                    s.ancient_vault_door = guid;
                }
                if self
                    .uldaman()
                    .map_or(0, |s| s.encounter[ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS as usize])
                    == DONE
                {
                    self.use_door(guid);
                }
            }
            ULD_GO_IRONAYA_SEAL_DOOR => {
                if let Some(s) = self.uldaman_mut() {
                    s.ironaya_seal_door = guid;
                }
                if self.uldaman().map_or(0, |s| {
                    s.encounter[ULD_ULDAMAN_ENCOUNTER_IRONAYA_DOOR as usize]
                }) == DONE
                {
                    self.use_door(guid);
                }
            }
            // Fork stores the keystone guid but never reads it; not
            // mirrored. `SetUInt32Value(GAMEOBJECT_FLAGS,
            // GO_FLAG_INTERACT_COND)` (cpp 173) overwrites the flags
            // word when the Ironaya door encounter is DONE.
            ULD_GO_KEYSTONE
                if self.uldaman().map_or(0, |s| {
                    s.encounter[ULD_ULDAMAN_ENCOUNTER_IRONAYA_DOOR as usize]
                }) == DONE =>
            {
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::GAMEOBJECT_FLAGS),
                    ULD_GO_FLAG_INTERACT_COND,
                );
            }
            _ => {}
        }
    }

    /// `instance_uldaman::SetFrozenState` (cpp 178-186).
    fn uld_set_frozen_state(&mut self, guid: ObjectGuid) {
        if !self.creatures.contains_key(&guid) {
            return;
        }
        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_FLAGS),
            flags | ULD_UNIT_FLAG_FROZEN,
        );
        self.remove_all_auras(guid);
        if self
            .aura_holders(guid)
            .iter()
            .any(|h| h.spell_id == ULD_SPELL_STONED)
        {
            return;
        }
        let _ = self.cast_spell(
            guid,
            ULD_SPELL_STONED,
            CastTarget::SelfCast,
            CastOptions {
                triggered: false,
                triggered_by_aura: false,
                skip_known: true,
                cast_item: None,
                custom_base_points: [None; 3],
                triggered_by_aura_spell: 0,
                triggered_by_spell: 0,
            },
        );
    }

    /// `instance_uldaman::SetUnFrozenState` (cpp 189-195).
    fn uld_set_unfrozen_state(&mut self, guid: ObjectGuid) {
        if !self.creatures.contains_key(&guid) {
            return;
        }
        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_FLAGS),
            flags & !ULD_UNIT_FLAG_FROZEN,
        );
        if self
            .aura_holders(guid)
            .iter()
            .any(|h| h.spell_id == ULD_SPELL_STONED)
        {
            self.remove_auras_due_to_spell(guid, ULD_SPELL_STONED);
        }
    }

    /// `instance_uldaman::RespawnMinion` (cpp 198-209).
    fn uld_respawn_minion(&mut self, guid: ObjectGuid) {
        let Some(c) = self.creatures.get(&guid) else {
            return;
        };
        // Fork `HasFlag(IMMUNE_TO_PLAYER | IMMUNE_TO_NPC)` (cpp 200):
        // nonzero when either immune bit is set (`Object::HasFlag`).
        if c.unit.is_alive()
            && self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS)
                & (ULD_UNIT_FLAG_IMMUNE_TO_PLAYER | ULD_UNIT_FLAG_IMMUNE_TO_NPC)
                != 0
        {
            return;
        }
        // Kill + immediate respawn through the normal spawn path; the
        // immune bits go back on at re-create via the refreeze mark
        // (fork `Respawn()` + `SetFlag` is synchronous; the Rust return
        // lands on a later tick — recorded in TIER3-PROGRESS).
        if let Some(s) = self.uldaman_mut() {
            s.minions_to_refreeze.push((guid, false));
        }
        self.despawn_creature_now(guid, 0);
    }

    /// Re-apply the frozen flags a force-respawned minion lost in
    /// materialization (see `uld_respawn_minion`).
    fn uld_apply_refreeze(&mut self, guid: ObjectGuid) {
        let full = self.uldaman_mut().and_then(|s| {
            s.minions_to_refreeze
                .iter()
                .position(|(g, _)| *g == guid)
                .map(|i| s.minions_to_refreeze.remove(i).1)
        });
        match full {
            Some(true) => self.uld_set_frozen_state(guid),
            Some(false) => {
                let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::UNIT_FIELD_FLAGS),
                    flags | ULD_UNIT_FLAG_IMMUNE_TO_PLAYER | ULD_UNIT_FLAG_IMMUNE_TO_NPC,
                );
            }
            None => {}
        }
    }

    /// `instance_uldaman::DespawnMinion` (cpp 212-218).
    fn uld_despawn_minion(&mut self, guid: ObjectGuid) {
        // Fork `SetDeathState(JUST_DIED)` + `RemoveCorpse()` collapses into
        // `despawn_creature_now` (zf precedent); the dead/missing gate is kept.
        if self.creatures.get(&guid).is_some_and(|c| c.unit.is_alive()) {
            self.despawn_creature_now(guid, 0);
        }
    }

    /// `instance_uldaman::SetData64` (cpp 221-243). Type ids are fork-magic
    /// (no header names): 0 = Ironaya's waker (`uldaman.cpp:43` stores the
    /// player guid), 1 = unfreeze this creature (`boss_archaedas.cpp:304`),
    /// 2 = freeze this creature. No `instance_set_data64` dispatcher exists
    /// yet; the integrator wires this method to one.
    fn uld_set_data64(&mut self, field: u32, data: ObjectGuid) -> bool {
        match field {
            0 => {
                if let Some(s) = self.uldaman_mut() {
                    s.who_woke_ironaya = data;
                }
            }
            1 => {
                if self.creatures.contains_key(&data) {
                    self.uld_set_unfrozen_state(data);
                }
            }
            2 => {
                if self.creatures.contains_key(&data) {
                    self.uld_set_frozen_state(data);
                }
            }
            _ => return false,
        }
        true
    }

    /// `instance_uldaman::GetData64` (cpp 245-273). Fork vector indexing
    /// (cpp 250-269) is bounds-guarded here (no panics); fork `return 0`
    /// for unset becomes `None`.
    fn uld_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        let s = self.uldaman()?;
        let guid = match field {
            // `uiWhoWokeIronayaGUID`.
            0 => s.who_woke_ironaya,
            // `vVaultWarder[0]` / `[1]`.
            1 => s.vault_warder.first().copied().unwrap_or(ObjectGuid::EMPTY),
            2 => s.vault_warder.get(1).copied().unwrap_or(ObjectGuid::EMPTY),
            // `vEarthenGuardian[0..5]`.
            5 => s
                .earthen_guardian
                .first()
                .copied()
                .unwrap_or(ObjectGuid::EMPTY),
            6 => s
                .earthen_guardian
                .get(1)
                .copied()
                .unwrap_or(ObjectGuid::EMPTY),
            7 => s
                .earthen_guardian
                .get(2)
                .copied()
                .unwrap_or(ObjectGuid::EMPTY),
            8 => s
                .earthen_guardian
                .get(3)
                .copied()
                .unwrap_or(ObjectGuid::EMPTY),
            9 => s
                .earthen_guardian
                .get(4)
                .copied()
                .unwrap_or(ObjectGuid::EMPTY),
            10 => s
                .earthen_guardian
                .get(5)
                .copied()
                .unwrap_or(ObjectGuid::EMPTY),
            // `uiArchaedasGUID`.
            11 => s.archaedas,
            // `vVaultWarderFurniture[0]` / `[1]`.
            12 => s
                .vault_warder_furniture
                .first()
                .copied()
                .unwrap_or(ObjectGuid::EMPTY),
            13 => s
                .vault_warder_furniture
                .get(1)
                .copied()
                .unwrap_or(ObjectGuid::EMPTY),
            _ => return None,
        };
        (!guid.is_empty()).then_some(guid)
    }

    /// `instance_uldaman::SetData` (cpp 275-512). Returns true when the
    /// instance script owns the field (exemplar convention; the C++ itself
    /// returns void).
    #[allow(clippy::too_many_lines)] // one SetData/Update port
    fn uld_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            ULD_ULDAMAN_ENCOUNTER_IRONAYA_DOOR => {
                if data == DONE {
                    if let Some(s) = self.uldaman_mut() {
                        s.keystone_check = true;
                        s.encounter[ULD_ULDAMAN_ENCOUNTER_IRONAYA_DOOR as usize] = data;
                    }
                }
            }
            ULD_DATA_KEEPERS_ALTAR => {
                if data == IN_PROGRESS {
                    let altar = self
                        .uldaman()
                        .map_or(ObjectGuid::EMPTY, |s| s.altar_of_the_keeper);
                    if altar != ObjectGuid::EMPTY {
                        let _ = self.object_set_field(
                            altar,
                            u32::from(offsets::GAMEOBJECT_STATE),
                            GO_STATE_ACTIVE,
                        );
                    }
                } else if data == ULD_NOT_STARTED {
                    let altar = self
                        .uldaman()
                        .map_or(ObjectGuid::EMPTY, |s| s.altar_of_the_keeper);
                    if altar != ObjectGuid::EMPTY {
                        let _ = self.object_set_field(
                            altar,
                            u32::from(offsets::GAMEOBJECT_STATE),
                            GO_STATE_READY,
                        );
                    }
                }
            }
            ULD_ULDAMAN_ENCOUNTER_STONE_KEEPERS => match data {
                DONE => {
                    if let Some(s) = self.uldaman_mut() {
                        s.encounter[ULD_ULDAMAN_ENCOUNTER_STONE_KEEPERS as usize] = data;
                    }
                    let door = self
                        .uldaman()
                        .map_or(ObjectGuid::EMPTY, |s| s.altar_of_the_keeper_temple_door);
                    if door != ObjectGuid::EMPTY {
                        self.use_door(door);
                    }
                }
                IN_PROGRESS => {
                    if let Some(s) = self.uldaman_mut() {
                        s.encounter[ULD_ULDAMAN_ENCOUNTER_STONE_KEEPERS as usize] = data;
                    }
                    // Check the list of Stone Keepers created at instance
                    // creation (cpp 308-327).
                    let keepers = self
                        .uldaman()
                        .map_or(Vec::new(), |s| s.stone_keeper.clone());
                    let mut target = ObjectGuid::EMPTY;
                    let mut encounter_done = true;
                    for guid in keepers {
                        let Some(c) = self.creatures.get(&guid) else {
                            continue;
                        };
                        if !c.unit.is_alive() {
                            continue;
                        }
                        // Do nothing if one is already alive and awaken.
                        if self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS)
                            & (ULD_UNIT_FLAG_IMMUNE_TO_PLAYER | ULD_UNIT_FLAG_IMMUNE_TO_NPC)
                            == 0
                        {
                            target = ObjectGuid::EMPTY;
                            encounter_done = false;
                            break;
                        }
                        // Save a creature that can be awaken for later.
                        if target.is_empty() {
                            target = guid;
                        }
                    }
                    if !target.is_empty() {
                        encounter_done = false;
                        // Creature becomes alive.
                        self.uld_set_unfrozen_state(target);
                        // `SetFactionTemporary(470, TEMPFACTION_RESTORE_RESPAWN |
                        // TEMPFACTION_RESTORE_COMBAT_STOP)` (cpp 333): no
                        // temporary-faction helper; the sticky write is the
                        // reachable part (restore semantics unresolved).
                        let _ = self.object_set_field(
                            target,
                            u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                            470,
                        );
                        // `SelectNearestTarget(80.0f)` (cpp 334) reduced
                        // to the nearest living player (hostile pets/NPCs
                        // not considered); no victim means FAIL (cpp 339).
                        let target_pos = self.object_position(target);
                        let victim = target_pos.and_then(|pos| {
                            self.players
                                .keys()
                                .copied()
                                .filter(|p| self.unit_is_alive(*p))
                                .filter_map(|p| {
                                    self.object_position(p)
                                        .map(|pp| (p, crate::visibility::dist3d(pp, pos)))
                                })
                                .filter(|(_, d)| *d <= 80.0)
                                .min_by(|a, b| a.1.total_cmp(&b.1))
                                .map(|(p, _)| p)
                        });
                        match victim {
                            Some(v) => self.enter_combat(target, v),
                            None => {
                                self.uld_set_data(ULD_ULDAMAN_ENCOUNTER_STONE_KEEPERS, ULD_FAIL);
                            }
                        }
                    }
                    if encounter_done {
                        self.uld_set_data(ULD_ULDAMAN_ENCOUNTER_STONE_KEEPERS, DONE);
                    }
                }
                ULD_FAIL => {
                    if let Some(s) = self.uldaman_mut() {
                        s.encounter[ULD_ULDAMAN_ENCOUNTER_STONE_KEEPERS as usize] = data;
                    }
                    let keepers = self
                        .uldaman()
                        .map_or(Vec::new(), |s| s.stone_keeper.clone());
                    for guid in keepers {
                        let Some(c) = self.creatures.get(&guid) else {
                            continue;
                        };
                        let refreeze = !c.unit.is_alive()
                            || self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS)
                                & (ULD_UNIT_FLAG_IMMUNE_TO_PLAYER | ULD_UNIT_FLAG_IMMUNE_TO_NPC)
                                == 0;
                        if refreeze {
                            // `Respawn()` + `SetFrozenState` (cpp
                            // 355-366), via the refreeze mark.
                            if let Some(s) = self.uldaman_mut() {
                                s.minions_to_refreeze.push((guid, true));
                            }
                            self.despawn_creature_now(guid, 0);
                        }
                    }
                }
                _ => {
                    if let Some(s) = self.uldaman_mut() {
                        s.encounter[ULD_ULDAMAN_ENCOUNTER_STONE_KEEPERS as usize] = data;
                    }
                }
            },
            ULD_DATA_ANCIENT_DOOR => {
                if data == DONE {
                    // Archaedas defeated: re-open the entrance, open the vault.
                    let temple = self
                        .uldaman()
                        .map_or(ObjectGuid::EMPTY, |s| s.archaedas_temple_door);
                    if temple != ObjectGuid::EMPTY {
                        self.use_door(temple);
                    }
                    let vault = self
                        .uldaman()
                        .map_or(ObjectGuid::EMPTY, |s| s.ancient_vault_door);
                    if vault != ObjectGuid::EMPTY {
                        self.use_door(vault);
                    }
                } else if data == ULD_FAIL {
                    let temple = self
                        .uldaman()
                        .map_or(ObjectGuid::EMPTY, |s| s.archaedas_temple_door);
                    if temple != ObjectGuid::EMPTY {
                        self.use_door(temple);
                    }
                    // `RemoveFlag(GAMEOBJECT_FLAGS, GO_FLAG_NO_INTERACT)`.
                    if temple != ObjectGuid::EMPTY {
                        let flags = self.object_get_field(temple, offsets::GAMEOBJECT_FLAGS);
                        let _ = self.object_set_field(
                            temple,
                            u32::from(offsets::GAMEOBJECT_FLAGS),
                            flags & !ULD_GO_FLAG_NO_INTERACT,
                        );
                    }
                } else if data == IN_PROGRESS {
                    // `DoResetDoor` (cpp 389) closes; `use_door` only opens,
                    // so write READY when ACTIVE (sch precedent).
                    let temple = self
                        .uldaman()
                        .map_or(ObjectGuid::EMPTY, |s| s.archaedas_temple_door);
                    if temple != ObjectGuid::EMPTY && self.go_state(temple) == GO_STATE_ACTIVE {
                        let _ = self.object_set_field(
                            temple,
                            u32::from(offsets::GAMEOBJECT_STATE),
                            GO_STATE_READY,
                        );
                    }
                    // `SetFlag(GAMEOBJECT_FLAGS, GO_FLAG_NO_INTERACT)`.
                    if temple != ObjectGuid::EMPTY {
                        let flags = self.object_get_field(temple, offsets::GAMEOBJECT_FLAGS);
                        let _ = self.object_set_field(
                            temple,
                            u32::from(offsets::GAMEOBJECT_FLAGS),
                            flags | ULD_GO_FLAG_NO_INTERACT,
                        );
                    }
                }
            }
            ULD_DATA_ARCHAEDAS_ALTAR => {
                if data == IN_PROGRESS {
                    let altar = self
                        .uldaman()
                        .map_or(ObjectGuid::EMPTY, |s| s.altar_of_archaedas);
                    if altar != ObjectGuid::EMPTY {
                        let _ = self.object_set_field(
                            altar,
                            u32::from(offsets::GAMEOBJECT_STATE),
                            GO_STATE_ACTIVE,
                        );
                    }
                } else if data == ULD_NOT_STARTED {
                    let altar = self
                        .uldaman()
                        .map_or(ObjectGuid::EMPTY, |s| s.altar_of_archaedas);
                    if altar != ObjectGuid::EMPTY {
                        let _ = self.object_set_field(
                            altar,
                            u32::from(offsets::GAMEOBJECT_STATE),
                            GO_STATE_READY,
                        );
                    }
                }
            }
            ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS => {
                match data {
                    IN_PROGRESS => {
                        // Event is started.
                        let current = self
                            .uldaman()
                            .map_or(0, |s| s.encounter[ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS as usize]);
                        if current == IN_PROGRESS {
                            // Wake a wall minion (only the first one found).
                            let archaedas =
                                self.uldaman().map_or(ObjectGuid::EMPTY, |s| s.archaedas);
                            if !archaedas.is_empty() {
                                let minions = self
                                    .uldaman()
                                    .map_or(Vec::new(), |s| s.archaedas_wall_minions.clone());
                                for guid in minions {
                                    let frozen_awakeable = self
                                        .creatures
                                        .get(&guid)
                                        .is_some_and(|c| c.unit.is_alive())
                                        && self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS)
                                            & (ULD_UNIT_FLAG_IMMUNE_TO_PLAYER
                                                | ULD_UNIT_FLAG_IMMUNE_TO_NPC)
                                            != 0;
                                    if !frozen_awakeable {
                                        continue;
                                    }
                                    let _ = self.cast_spell(
                                        archaedas,
                                        ULD_SPELL_AWAKEN_EARTHEN_DWARF,
                                        CastTarget::Unit(guid),
                                        CastOptions {
                                            triggered: false,
                                            triggered_by_aura: false,
                                            skip_known: true,
                                            cast_item: None,
                                            custom_base_points: [None; 3],
                                            triggered_by_aura_spell: 0,
                                            triggered_by_spell: 0,
                                        },
                                    );
                                    // Fork `RemoveFlag(IMMUNE_TO_PLAYER |
                                    // IMMUNE_TO_NPC | NOT_SELECTABLE)` (cpp 440).
                                    let flags =
                                        self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
                                    let _ = self.object_set_field(
                                        guid,
                                        u32::from(offsets::UNIT_FIELD_FLAGS),
                                        flags & !ULD_UNIT_FLAG_FROZEN,
                                    );
                                    break;
                                }
                            }
                        } else {
                            if self.uldaman().map_or(0, |s| {
                                s.encounter[ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS as usize]
                            }) != DONE
                            {
                                self.uld_set_data(ULD_DATA_ANCIENT_DOOR, IN_PROGRESS);
                            }
                            let archaedas =
                                self.uldaman().map_or(ObjectGuid::EMPTY, |s| s.archaedas);
                            if self
                                .creatures
                                .get(&archaedas)
                                .is_some_and(|c| c.unit.is_alive())
                                && self.object_get_field(archaedas, offsets::UNIT_FIELD_FLAGS)
                                    & (ULD_UNIT_FLAG_IMMUNE_TO_PLAYER | ULD_UNIT_FLAG_IMMUNE_TO_NPC)
                                    != 0
                            {
                                let _ = self.cast_spell(
                                    archaedas,
                                    ULD_SPELL_ARCHAEDAS_AWAKEN,
                                    CastTarget::SelfCast,
                                    CastOptions {
                                        triggered: false,
                                        triggered_by_aura: false,
                                        skip_known: true,
                                        cast_item: None,
                                        custom_base_points: [None; 3],
                                        triggered_by_aura_spell: 0,
                                        triggered_by_spell: 0,
                                    },
                                );
                                self.uld_set_unfrozen_state(archaedas);
                            }
                        }
                        if let Some(s) = self.uldaman_mut() {
                            s.encounter[ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS as usize] = data;
                        }
                    }
                    ULD_NOT_STARTED => {
                        // Archaedas reaches his spawn point: respawn any
                        // aggroed wall minions (cpp 448-456; kill/respawn
                        // subset NEEDS-MAP-HELPER, see `uld_respawn_minion`).
                        let minions = self
                            .uldaman()
                            .map_or(Vec::new(), |s| s.archaedas_wall_minions.clone());
                        for guid in minions {
                            self.uld_respawn_minion(guid);
                        }
                        let warders = self
                            .uldaman()
                            .map_or(Vec::new(), |s| s.vault_warder.clone());
                        for guid in warders {
                            self.uld_respawn_minion(guid);
                        }
                        let guardians = self
                            .uldaman()
                            .map_or(Vec::new(), |s| s.earthen_guardian.clone());
                        for guid in guardians {
                            self.uld_respawn_minion(guid);
                        }
                        // Furniture: respawn when despawned (cpp 458-463).
                        let furniture = self
                            .uldaman()
                            .map_or(Vec::new(), |s| s.vault_warder_furniture.clone());
                        for guid in furniture {
                            // `Respawn()` when `IsDespawned()`: a dead
                            // furniture warder re-materializes fresh; a
                            // guid absent entirely is already on the
                            // normal respawn path.
                            if self
                                .creatures
                                .get(&guid)
                                .is_some_and(|c| !c.unit.is_alive())
                            {
                                self.despawn_creature_now(guid, 0);
                            }
                        }
                        let archaedas = self.uldaman().map_or(ObjectGuid::EMPTY, |s| s.archaedas);
                        if !archaedas.is_empty() {
                            self.uld_set_frozen_state(archaedas);
                        }
                        if let Some(s) = self.uldaman_mut() {
                            s.encounter[ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS as usize] = data;
                        }
                    }
                    ULD_FAIL => {
                        if let Some(s) = self.uldaman_mut() {
                            s.encounter[ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS as usize] = data;
                        }
                        // Open the temple door (cpp 470).
                        self.uld_set_data(ULD_DATA_ANCIENT_DOOR, ULD_FAIL);
                    }
                    DONE => {
                        if let Some(s) = self.uldaman_mut() {
                            s.encounter[ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS as usize] = data;
                        }
                        // Remove anything that isn't dead (cpp 475-483).
                        let minions = self
                            .uldaman()
                            .map_or(Vec::new(), |s| s.archaedas_wall_minions.clone());
                        for guid in minions {
                            self.uld_despawn_minion(guid);
                        }
                        let warders = self
                            .uldaman()
                            .map_or(Vec::new(), |s| s.vault_warder.clone());
                        for guid in warders {
                            self.uld_despawn_minion(guid);
                        }
                        let guardians = self
                            .uldaman()
                            .map_or(Vec::new(), |s| s.earthen_guardian.clone());
                        for guid in guardians {
                            self.uld_despawn_minion(guid);
                        }
                        // Furniture: respawn when despawned (cpp 485-490).
                        let furniture = self
                            .uldaman()
                            .map_or(Vec::new(), |s| s.vault_warder_furniture.clone());
                        for guid in furniture {
                            if self
                                .creatures
                                .get(&guid)
                                .is_some_and(|c| !c.unit.is_alive())
                            {
                                self.despawn_creature_now(guid, 0);
                            }
                        }
                        // Open the Vault door.
                        self.uld_set_data(ULD_DATA_ANCIENT_DOOR, DONE);
                        // `SummonGameObject(141979, 153.39, 289.091,
                        // -52.226_2, 2.687_81, ...)` (cpp 494): no temp
                        // gameobject summon helper on `Map` yet
                        // (recorded in TIER3-PROGRESS).
                    }
                    _ => {
                        if let Some(s) = self.uldaman_mut() {
                            s.encounter[ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS as usize] = data;
                        }
                    }
                }
            }
            _ => return false,
        }
        // Fork save shape (cpp 503-511): refresh only for encounter fields
        // set DONE, separator form (no trailing space, like bfd).
        if field < ULD_ULDAMAN_MAX_ENCOUNTER
            && data == DONE
            && let Some(s) = self.uldaman_mut()
        {
            let e = s.encounter;
            s.save_string = format!("{} {} {}", e[0], e[1], e[2]);
        }
        true
    }

    /// `instance_uldaman::IsEncounterInProgress` (cpp 75-87).
    fn uld_is_encounter_in_progress(&self) -> bool {
        self.uldaman()
            .is_some_and(|s| s.encounter.contains(&IN_PROGRESS))
    }

    /// `instance_uldaman::GetData` (cpp 533-543).
    fn uld_get_data(&self, field: u32) -> Option<u32> {
        let s = self.uldaman()?;
        match field {
            ULD_ULDAMAN_ENCOUNTER_IRONAYA_DOOR => {
                Some(s.encounter[ULD_ULDAMAN_ENCOUNTER_IRONAYA_DOOR as usize])
            }
            ULD_ULDAMAN_ENCOUNTER_STONE_KEEPERS => {
                Some(s.encounter[ULD_ULDAMAN_ENCOUNTER_STONE_KEEPERS as usize])
            }
            ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS => {
                Some(s.encounter[ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS as usize])
            }
            _ => None,
        }
    }

    /// `instance_uldaman::Save` (cpp 514).
    fn uld_save(&self) -> Option<String> {
        self.uldaman().map(|s| s.save_string.clone())
    }

    /// `instance_uldaman::Load` (cpp 516-531). The C++ null `chrIn`
    /// check has no Rust equivalent (`&str` is never null). Any stored
    /// value that is not DONE loads as `NOT_STARTED`.
    fn uld_load(&mut self, data: &str) {
        let mut loaded = [0u32; ULD_ULDAMAN_MAX_ENCOUNTER as usize];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value != DONE {
                *value = ULD_NOT_STARTED;
            }
        }
        if let Some(s) = self.uldaman_mut() {
            s.encounter = loaded;
        }
    }

    /// `instance_uldaman::Update` (cpp 545-565).
    fn uld_update(&mut self, diff_ms: u32) {
        if !self.uldaman().is_some_and(|s| s.keystone_check) {
            return;
        }
        let timer = self.uldaman().map_or(0, |s| s.ironaya_seal_door_timer_ms);
        if timer <= diff_ms {
            let ironaya = self.uldaman().map_or(ObjectGuid::EMPTY, |s| s.ironaya);
            if !self.creatures.contains_key(&ironaya) {
                return;
            }
            self.uld_set_unfrozen_state(ironaya);
            // Fork `SetFactionTemplateId(415)` (cpp 557): Ironaya's combat
            // faction (literal in the fork, not a header enum).
            let _ =
                self.object_set_field(ironaya, u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE), 415);
            let door = self
                .uldaman()
                .map_or(ObjectGuid::EMPTY, |s| s.ironaya_seal_door);
            if door != ObjectGuid::EMPTY {
                self.use_door(door);
            }
            if let Some(s) = self.uldaman_mut() {
                s.keystone_check = false;
            }
        } else if let Some(s) = self.uldaman_mut() {
            s.ironaya_seal_door_timer_ms -= diff_ms;
        }
    }

