    /// `instance_sunken_temple::OnCreatureEnterCombat` (C++ lines 318-340).
    fn st_on_creature_enter_combat(&mut self, creature: ObjectGuid) {
        let Some(entry) = self.object_entry(creature) else {
            return;
        };
        match entry {
            ST_NPC_DREAMSCYTH => {
                self.do_script_text(ST_SAY_DREAMSCYTHE_AGGRO, creature, None, -1);
            }
            ST_NPC_ATALARION => {
                // Hidden (fork `GetVisibility() != VISIBILITY_ON`):
                // evade and re-freeze instead of the aggro yell.
                if self.hidden_objects.contains(&creature) {
                    self.enter_evade_mode(creature);
                    self.st_set_unit_flag(creature, ST_UNIT_FLAG_NOT_SELECTABLE);
                    self.st_set_unit_flag(creature, ST_UNIT_FLAG_SPAWNING);
                    self.st_set_unit_flag(creature, ST_UNIT_FLAG_IMMUNE_TO_NPC);
                } else {
                    self.do_script_text(ST_SAY_ATALALARION_AGGRO, creature, None, -1);
                }
            }
            ST_NPC_SHADE_OF_ERANIKUS => {
                // `SetStandState(UNIT_STAND_STATE_STAND)`.
                self.unit_set_byte(creature, offsets::UNIT_FIELD_BYTES_1, 0, STAND_STATE_STAND);
            }
            _ => {}
        }
    }

    /// `instance_sunken_temple::OnCreatureDeath` (C++ lines 342-353).
    fn st_on_creature_death(&mut self, victim: ObjectGuid) {
        if self.object_entry(victim) != Some(ST_NPC_ATALARION) {
            return;
        }
        let idol = self
            .sunken_temple()
            .map_or(ObjectGuid::EMPTY, |s| s.idol_hakkar);
        if idol == ObjectGuid::EMPTY || self.gameobject(idol).is_none() {
            return;
        }
        // `RemoveFlag(GAMEOBJECT_FLAGS, GO_FLAG_NO_INTERACT)`.
        let flags = self.object_get_field(idol, offsets::GAMEOBJECT_FLAGS);
        let _ = self.object_set_field(
            idol,
            u32::from(offsets::GAMEOBJECT_FLAGS),
            flags & !ST_GO_FLAG_NO_INTERACT,
        );
    }

    /// `instance_sunken_temple::SetData` (C++ lines 355-512). Returns
    /// true when the instance script owns the field.
    #[allow(clippy::too_many_lines)] // one SetData/Update port
    fn st_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            ST_TYPE_SECRET_CIRCLE => {
                if let Some(s) = self.sunken_temple_mut() {
                    s.encounter[0] = data;
                }
                if data == DONE {
                    self.st_statue_event_done();
                    self.st_spawn_atalarion_if_can();
                }
            }
            ST_TYPE_PROTECTORS => {
                if let Some(s) = self.sunken_temple_mut() {
                    s.encounter[1] = data;
                }
                if data == DONE {
                    // All six protectors dead (a missing creature counts
                    // as dead, as in the fork null check, cpp 372-382).
                    let all_dead = self.sunken_temple().is_none_or(|s| {
                        s.protectors
                            .iter()
                            .all(|g| self.creatures.get(g).is_none_or(|c| !c.unit.is_alive()))
                    });
                    if all_dead {
                        let barrier = self
                            .sunken_temple()
                            .map_or(ObjectGuid::EMPTY, |s| s.jammalan_barrier);
                        // `GetGoState() != GO_STATE_ACTIVE` then
                        // `DoUseDoorOrButton` (cpp 386-388).
                        if barrier != ObjectGuid::EMPTY && self.go_state(barrier) != GO_STATE_ACTIVE
                        {
                            self.use_door(barrier);
                        }
                        let jam = self
                            .sunken_temple()
                            .map_or(ObjectGuid::EMPTY, |s| s.jammalan);
                        if self.creatures.contains_key(&jam) {
                            self.do_script_text(ST_SAY_JAMMALAN_INTRO, jam, None, -1);
                        }
                    }
                }
            }
            ST_TYPE_JAMMALAN => {
                if let Some(s) = self.sunken_temple_mut() {
                    s.encounter[2] = data;
                }
                if data == DONE {
                    let eranikus = self
                        .sunken_temple()
                        .map_or(ObjectGuid::EMPTY, |s| s.shade_eranikus);
                    if self.creatures.contains_key(&eranikus) {
                        self.st_remove_unit_flag(eranikus, ST_UNIT_FLAG_NOT_SELECTABLE);
                        self.st_remove_unit_flag(eranikus, ST_UNIT_FLAG_SPAWNING);
                        self.st_remove_unit_flag(eranikus, ST_UNIT_FLAG_IMMUNE_TO_NPC);
                    }
                    let dream = self
                        .sunken_temple()
                        .map_or(ObjectGuid::EMPTY, |s| s.dreamscyth);
                    if self.creatures.contains_key(&dream) {
                        // `SetVisibility(VISIBILITY_ON)`.
                        self.hidden_objects.remove(&dream);
                        self.st_remove_unit_flag(dream, ST_UNIT_FLAG_NOT_SELECTABLE);
                        self.st_remove_unit_flag(dream, ST_UNIT_FLAG_SPAWNING);
                        self.st_remove_unit_flag(dream, ST_UNIT_FLAG_IMMUNE_TO_NPC);
                        // `MoveWaypoint()` (defaults: start 0, repeat).
                        self.creature_move_waypoint(dream, 0, true);
                        self.do_script_text(ST_SAY_DREAMSCYTHE_INTRO, dream, None, -1);
                    }
                    let weaver = self.sunken_temple().map_or(ObjectGuid::EMPTY, |s| s.weaver);
                    if self.creatures.contains_key(&weaver) {
                        // `SetVisibility(VISIBILITY_ON)`.
                        self.hidden_objects.remove(&weaver);
                        self.st_remove_unit_flag(weaver, ST_UNIT_FLAG_NOT_SELECTABLE);
                        self.st_remove_unit_flag(weaver, ST_UNIT_FLAG_SPAWNING);
                        self.st_remove_unit_flag(weaver, ST_UNIT_FLAG_IMMUNE_TO_NPC);
                        // `MoveWaypoint()` (defaults: start 0, repeat).
                        self.creature_move_waypoint(weaver, 0, true);
                    }
                } else if data == IN_PROGRESS {
                    // Pull the Jammalain-hall guards into the fight
                    // (cpp 424-453).
                    let jam = self
                        .sunken_temple()
                        .map_or(ObjectGuid::EMPTY, |s| s.jammalan);
                    if !jam.is_empty() {
                        for entry in [
                            ST_NPC_MUMMIFIED_ATALAI,
                            ST_NPC_ATALAI_DEATHWALKER,
                            ST_NPC_ATALAI_HIGH_PRIEST,
                        ] {
                            for mob in self.st_grid_mob_guids(jam, entry, 150.0) {
                                // `curr->SetInCombatWithZone()`.
                                self.set_in_combat_with_zone(mob);
                            }
                        }
                    }
                }
            }
            ST_TYPE_MALFURION => {
                if let Some(s) = self.sunken_temple_mut() {
                    s.encounter[3] = data;
                }
            }
            ST_TYPE_AVATAR => {
                if let Some(s) = self.sunken_temple_mut() {
                    s.encounter[4] = data;
                }
            }
            ST_TYPE_ERANIKUS => {
                if let Some(s) = self.sunken_temple_mut() {
                    s.encounter[5] = data;
                }
                if data == IN_PROGRESS {
                    // Pull the Eranikus-hall nightmares into the fight
                    // (cpp 463-493).
                    let eranikus = self
                        .sunken_temple()
                        .map_or(ObjectGuid::EMPTY, |s| s.shade_eranikus);
                    if !eranikus.is_empty() {
                        for entry in [
                            ST_NPC_NIGHTMARE_SCALEBANE,
                            ST_NPC_NIGHTMARE_WYRMKIN,
                            ST_NPC_NIGHTMARE_WHELP,
                            ST_NPC_NIGHTMARE_WANDERER,
                        ] {
                            for mob in self.st_grid_mob_guids(eranikus, entry, 300.0) {
                                self.set_in_combat_with_zone(mob);
                            }
                        }
                    }
                }
            }
            ST_TYPE_ETERNAL_FLAME => {
                if let Some(s) = self.sunken_temple_mut() {
                    s.flame_counter = data;
                }
            }
            _ => return false,
        }
        // Fork shape copied exactly (cpp 500-511): ANY field set DONE
        // refreshes the save string over the fixed six encounter values.
        if data == DONE
            && let Some(s) = self.sunken_temple_mut()
        {
            let e = s.encounter;
            s.save_string = format!("{} {} {} {} {} {}", e[0], e[1], e[2], e[3], e[4], e[5]);
        }
        true
    }

    /// `instance_sunken_temple::SetData64` (C++ lines 514-536). No
    /// `instance_set_data64` dispatcher exists in `content.rs` yet; the
    /// integrator adds it alongside the other dispatch arms.
    fn st_set_data64(&mut self, field: u32, data: ObjectGuid) -> bool {
        match field {
            ST_NPC_SHADE_OF_HAKKAR => {
                if let Some(s) = self.sunken_temple_mut() {
                    s.shade_hakkar = data;
                }
            }
            ST_NPC_ATALARION => {
                if let Some(s) = self.sunken_temple_mut() {
                    s.atalarion = data;
                }
            }
            ST_NPC_AVATAR_OF_HAKKAR => {
                if let Some(s) = self.sunken_temple_mut() {
                    s.avatar_hakkar = data;
                }
            }
            ST_GO_ATALAI_STATUE_1
            | ST_GO_ATALAI_STATUE_2
            | ST_GO_ATALAI_STATUE_3
            | ST_GO_ATALAI_STATUE_4
            | ST_GO_ATALAI_STATUE_5
            | ST_GO_ATALAI_STATUE_6 => {
                self.st_process_statue_used(field);
            }
            _ => return false,
        }
        true
    }

    /// `instance_sunken_temple::GetData` (C++ lines 540-561).
    fn st_get_data(&self, field: u32) -> Option<u32> {
        let s = self.sunken_temple()?;
        match field {
            ST_TYPE_SECRET_CIRCLE => Some(s.encounter[0]),
            ST_TYPE_PROTECTORS => Some(s.encounter[1]),
            ST_TYPE_JAMMALAN => Some(s.encounter[2]),
            ST_TYPE_MALFURION => Some(s.encounter[3]),
            ST_TYPE_AVATAR => Some(s.encounter[4]),
            ST_TYPE_ERANIKUS => Some(s.encounter[5]),
            ST_TYPE_ETERNAL_FLAME => Some(s.flame_counter),
            _ => None,
        }
    }

    /// `instance_sunken_temple::GetData64` (C++ lines 563-575). The fork
    /// returns 0 when unset; Rust returns `None`.
    fn st_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        let s = self.sunken_temple()?;
        match field {
            ST_NPC_SHADE_OF_HAKKAR => (!s.shade_hakkar.is_empty()).then_some(s.shade_hakkar),
            ST_NPC_ATALARION => (!s.atalarion.is_empty()).then_some(s.atalarion),
            ST_NPC_AVATAR_OF_HAKKAR => (!s.avatar_hakkar.is_empty()).then_some(s.avatar_hakkar),
            _ => None,
        }
    }

    /// `instance_sunken_temple::Save` (C++ line 538).
    fn st_save(&self) -> Option<String> {
        self.sunken_temple().map(|s| s.save_string.clone())
    }

    /// `instance_sunken_temple::Load` (C++ lines 609-629). The fork
    /// null-`chrIn` check has no Rust equivalent (`&str` is never null).
    fn st_load(&mut self, data: &str) {
        let mut loaded = [0u32; ST_MAX_ENCOUNTER];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = ST_NOT_STARTED;
            }
        }
        if let Some(s) = self.sunken_temple_mut() {
            s.encounter = loaded;
        }
    }

    /// `instance_sunken_temple::Update` (C++ lines 577-607).
    fn st_update(&mut self, diff_ms: u32) {
        let elapsed = self
            .sunken_temple()
            .is_some_and(|s| s.remove_timer_ms < diff_ms);
        if elapsed {
            // NEEDS-MAP-HELPER: `instance->RemoveAllObjectsInRemoveList()`
            // (no remove-list helper on `Map`). The 5s re-arm below is
            // the reachable part.
            if let Some(s) = self.sunken_temple_mut() {
                s.remove_timer_ms = 5000;
            }
        } else if let Some(s) = self.sunken_temple_mut() {
            s.remove_timer_ms -= diff_ms;
        }

        // One-shot post-crash circle-state restore (cpp 587-606).
        let restore = self.sunken_temple().is_some_and(|s| s.restore_circle_state);
        if !restore {
            return;
        }
        if let Some(s) = self.sunken_temple_mut() {
            s.restore_circle_state = false;
        }
        if self.st_get_data(ST_TYPE_SECRET_CIRCLE) == Some(DONE) {
            self.st_statue_event_done();
            // The idol is interactable once a dead Atalarion is found
            // (cpp 594-604).
            let atalarion = self
                .sunken_temple()
                .map_or(ObjectGuid::EMPTY, |s| s.atalarion);
            if self
                .creatures
                .get(&atalarion)
                .is_some_and(|c| !c.unit.is_alive())
            {
                let idol = self
                    .sunken_temple()
                    .map_or(ObjectGuid::EMPTY, |s| s.idol_hakkar);
                if idol != ObjectGuid::EMPTY && self.gameobject(idol).is_some() {
                    // `RemoveFlag(GAMEOBJECT_FLAGS, GO_FLAG_NO_INTERACT)`.
                    let flags = self.object_get_field(idol, offsets::GAMEOBJECT_FLAGS);
                    let _ = self.object_set_field(
                        idol,
                        u32::from(offsets::GAMEOBJECT_FLAGS),
                        flags & !ST_GO_FLAG_NO_INTERACT,
                    );
                }
            }
        }
    }

    /// `DoSpawnAtalarionIfCan` (C++ lines 95-107). The fork comment
    /// says "return if already summoned" but the code returns when
    /// Atalarion is *missing*; mirrored as written.
    fn st_spawn_atalarion_if_can(&mut self) {
        let Some(atalarion) = self.st_get_data64(ST_NPC_ATALARION) else {
            return;
        };
        if !self.creatures.contains_key(&atalarion) {
            return;
        }
        self.do_script_text(ST_SAY_ATALALARION_SPAWN, atalarion, None, -1);
        // `SetVisibility(VISIBILITY_ON)`.
        self.hidden_objects.remove(&atalarion);
        self.st_remove_unit_flag(atalarion, ST_UNIT_FLAG_NOT_SELECTABLE);
        self.st_remove_unit_flag(atalarion, ST_UNIT_FLAG_SPAWNING);
        self.st_remove_unit_flag(atalarion, ST_UNIT_FLAG_IMMUNE_TO_NPC);
    }

    /// `HandleStatueEventDone` (C++ lines 109-124).
    fn st_statue_event_done(&mut self) {
        // NEEDS-MAP-HELPER: `DoRespawnGameObject(m_uiIdolHakkarGUID,
        // HOUR * IN_MILLISECONDS)` (no gameobject-respawn helper on
        // `Map`; GNO precedent). The guid read is the reachable part.
        let _ = self
            .sunken_temple()
            .map_or(ObjectGuid::EMPTY, |s| s.idol_hakkar);
        // Disable interacting with the circle stones.
        let statues = self
            .sunken_temple()
            .map_or([ObjectGuid::EMPTY; 6], |s| s.statue_guids);
        for statue in statues {
            if statue.is_empty() || self.gameobject(statue).is_none() {
                continue;
            }
            // `SetFlag(GAMEOBJECT_FLAGS, GO_FLAG_NO_INTERACT)`.
            let flags = self.object_get_field(statue, offsets::GAMEOBJECT_FLAGS);
            let _ = self.object_set_field(
                statue,
                u32::from(offsets::GAMEOBJECT_FLAGS),
                flags | ST_GO_FLAG_NO_INTERACT,
            );
        }
        // NEEDS-MAP-HELPER: `DoRespawnGameObject` for each big light
        // (same missing helper). The guid-set read is the reachable
        // part (also keeps `big_light_guids` a live field).
        let _ = self
            .sunken_temple()
            .map_or([ObjectGuid::EMPTY; 6], |s| s.big_light_guids);
    }

    /// `ProcessStatueUsed` (C++ lines 126-201).
    fn st_process_statue_used(&mut self, statue_entry: u32) {
        if self.st_get_data(ST_TYPE_SECRET_CIRCLE) == Some(DONE) {
            return;
        }
        if self.st_get_data(ST_TYPE_SECRET_CIRCLE) != Some(IN_PROGRESS) {
            self.st_set_data(ST_TYPE_SECRET_CIRCLE, IN_PROGRESS);
        }
        let statue_guid = match statue_entry {
            ST_GO_ATALAI_STATUE_1 => self
                .sunken_temple()
                .map_or(ObjectGuid::EMPTY, |s| s.statue_guids[0]),
            ST_GO_ATALAI_STATUE_2 => self
                .sunken_temple()
                .map_or(ObjectGuid::EMPTY, |s| s.statue_guids[1]),
            ST_GO_ATALAI_STATUE_3 => self
                .sunken_temple()
                .map_or(ObjectGuid::EMPTY, |s| s.statue_guids[2]),
            ST_GO_ATALAI_STATUE_4 => self
                .sunken_temple()
                .map_or(ObjectGuid::EMPTY, |s| s.statue_guids[3]),
            ST_GO_ATALAI_STATUE_5 => self
                .sunken_temple()
                .map_or(ObjectGuid::EMPTY, |s| s.statue_guids[4]),
            ST_GO_ATALAI_STATUE_6 => self
                .sunken_temple()
                .map_or(ObjectGuid::EMPTY, |s| s.statue_guids[5]),
            _ => ObjectGuid::EMPTY,
        };
        if statue_guid.is_empty() || self.gameobject(statue_guid).is_none() {
            return;
        }
        let mut activation_success = false;
        // Correct-order check (cpp 166-181): the counter must equal the
        // statue's position in the required order.
        let counter = self.sunken_temple().map_or(0, |s| s.statue_counter);
        for i in 0..ST_MAX_STATUES {
            if statue_entry == ST_ATALAI_STATUE_ORDER[i as usize] && counter == i {
                if let Some(s) = self.sunken_temple_mut() {
                    s.statue_counter += 1;
                }
                activation_success = true;
                // `SetFlag(GAMEOBJECT_FLAGS, GO_FLAG_NO_INTERACT)`.
                let flags = self.object_get_field(statue_guid, offsets::GAMEOBJECT_FLAGS);
                let _ = self.object_set_field(
                    statue_guid,
                    u32::from(offsets::GAMEOBJECT_FLAGS),
                    flags | ST_GO_FLAG_NO_INTERACT,
                );
                // Show the green light: respawn the closest
                // `GO_ATALAI_LIGHT` within interaction distance.
                if self
                    .st_closest_gameobject(statue_guid, ST_GO_ATALAI_LIGHT, ST_INTERACTION_DISTANCE)
                    .is_some()
                {
                    // NEEDS-MAP-HELPER: `DoRespawnGameObject(light,
                    // HOUR * IN_MILLISECONDS)` (same missing helper).
                }
                break;
            }
        }
        if self.sunken_temple().map_or(0, |s| s.statue_counter) == ST_MAX_STATUES {
            self.st_set_data(ST_TYPE_SECRET_CIRCLE, DONE);
            return;
        }
        if activation_success {
            return;
        }
        // Wrong statue: trigger a random nearby trap (cpp 193-200).
        // `PickRandomValue` over the three trap entries.
        let Some(atalarion) = self.st_get_data64(ST_NPC_ATALARION) else {
            return;
        };
        if !self.creatures.contains_key(&atalarion) {
            return;
        }
        let roll = self.spell_rng().irand(0, 2);
        let trap_entry = match roll {
            0 => ST_GO_ATALAI_TRAP_1,
            1 => ST_GO_ATALAI_TRAP_2,
            _ => ST_GO_ATALAI_TRAP_3,
        };
        if self
            .st_closest_gameobject(statue_guid, trap_entry, ST_INTERACTION_DISTANCE)
            .is_some()
        {
            // NEEDS-MAP-HELPER: `pTrap->Use(pAtalarion)`; `gameobject_use`
            // takes a player guid, so there is no creature-as-user
            // `GameObject::Use` path (GNO precedent).
        }
    }

    /// `SetFlag(UNIT_FIELD_FLAGS, ...)` via the existing field helpers
    /// (`object_set_field` covers units; no flag helper exists on `Map`).
    fn st_set_unit_flag(&mut self, guid: ObjectGuid, flag: u32) {
        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
        let _ = self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_FLAGS), flags | flag);
    }

    /// `RemoveFlag(UNIT_FIELD_FLAGS, ...)` via the existing field helpers.
    fn st_remove_unit_flag(&mut self, guid: ObjectGuid, flag: u32) {
        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
        let _ = self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_FLAGS), flags & !flag);
    }

    /// `GetCreatureListWithEntryInGrid` + the loop-body filters
    /// (DB-spawned and alive, cpp 439-450 / 479-490): living
    /// DB-spawned mobs of `entry` within `range` of `origin`.
    fn st_grid_mob_guids(&self, origin: ObjectGuid, entry: u32, range: f32) -> Vec<ObjectGuid> {
        let Some(center) = self.object_position(origin) else {
            return Vec::new();
        };
        self.creatures
            .values()
            .filter(|c| {
                c.info.entry == entry
                    // `!curr->GetDBTableGUIDLow()`: skip summons.
                    && c.data.is_some()
                    && c.unit.is_alive()
                    && crate::visibility::dist3d(c.unit.world.position(), center) <= range
            })
            .map(|c| c.unit.guid())
            .collect()
    }

    /// `GetClosestGameObjectWithEntry` (no helper; open-coded like the
    /// MAR vine lookup): closest gameobject of `entry` within `range`
    /// of `origin`.
    fn st_closest_gameobject(
        &self,
        origin: ObjectGuid,
        entry: u32,
        range: f32,
    ) -> Option<ObjectGuid> {
        let center = self.object_position(origin)?;
        self.gameobjects
            .keys()
            .copied()
            .filter(|g| self.object_entry(*g) == Some(entry))
            .filter_map(|g| {
                self.object_position(g)
                    .map(|p| (g, crate::visibility::dist3d(p, center)))
            })
            .filter(|(_, d)| *d <= range)
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .map(|(g, _)| g)
    }

