    /// `instance_ruins_of_ahnqiraj::OnCreatureEnterCombat` (cpp 124-164).
    fn aq20_on_creature_enter_combat(&mut self, creature: ObjectGuid) {
        let Some(entry) = self.object_entry(creature) else {
            return;
        };
        match entry {
            AQ20_NPC_CAPTAIN_QEEZ
            | AQ20_NPC_CAPTAIN_TUUBID
            | AQ20_NPC_CAPTAIN_DRENN
            | AQ20_NPC_CAPTAIN_XURREM
            | AQ20_NPC_MAJOR_YEGGETH
            | AQ20_NPC_MAJOR_PAKKON
            | AQ20_NPC_COLONEL_ZERRAN
            | AQ20_NPC_SWARMGUARD_NEEDLER
            | AQ20_NPC_QIRAJI_WARRIOR => {
                // Yeggeth shield-list push (cpp 138-140): the
                // `CreatureGroup`-leader check has no `Map` helper
                // (unresolved), so the list stays empty.
                // `sWorld.GetWowPatch() >= WOW_PATCH_110` (cpp 150) is
                // statically true: this build is patch 1.12
                // (progression 10 > fork `WOW_PATCH_110` 8).
                let trigger = self.ruins_of_ahnqiraj().is_some_and(|s| {
                    s.encounter[AQ20_TYPE_RAJAXX as usize] != DONE
                        && (s.encounter[AQ20_TYPE_GENERAL_ANDOROV as usize] == AQ20_NOT_STARTED
                            || s.encounter[AQ20_TYPE_GENERAL_ANDOROV as usize] == AQ20_FAIL)
                });
                if trigger {
                    let andorov = self
                        .ruins_of_ahnqiraj()
                        .map_or(ObjectGuid::EMPTY, |s| s.andorov);
                    if self.creatures.contains_key(&andorov) {
                        // `pAndorov->Respawn()` (cpp 154): no helper
                        // (unresolved); the script still starts.
                        self.scripts_start_generic(
                            AQ20_ANDOROV_START_SCRIPT,
                            Some(andorov),
                            Some(andorov),
                        );
                        self.aq20_set_data(AQ20_TYPE_GENERAL_ANDOROV, IN_PROGRESS);
                    }
                }
                if let Some(s) = self.ruins_of_ahnqiraj_mut() {
                    s.rajaxx_reset_pending = false;
                }
            }
            _ => {}
        }
    }

    /// `instance_ruins_of_ahnqiraj::OnCreatureDeath` (cpp 275-310).
    fn aq20_on_creature_death(&mut self, victim: ObjectGuid) {
        let Some(entry) = self.object_entry(victim) else {
            return;
        };
        match entry {
            AQ20_NPC_CAPTAIN_QEEZ
            | AQ20_NPC_CAPTAIN_TUUBID
            | AQ20_NPC_CAPTAIN_DRENN
            | AQ20_NPC_CAPTAIN_XURREM
            | AQ20_NPC_MAJOR_YEGGETH
            | AQ20_NPC_MAJOR_PAKKON
            | AQ20_NPC_COLONEL_ZERRAN
            | AQ20_NPC_SWARMGUARD_NEEDLER
            | AQ20_NPC_QIRAJI_WARRIOR => {
                if entry == AQ20_NPC_SWARMGUARD_NEEDLER || entry == AQ20_NPC_QIRAJI_WARRIOR {
                    // Fork `ForcedDespawn(3000)` delay has no helper
                    // (cf. `zg_on_creature_death`); `SetRespawnTime`
                    // rides `despawn_creature_now` here (4 real days,
                    // not the ZG never-respawn).
                    self.despawn_creature_now(victim, AQ20_RESPAWN_FOUR_DAYS);
                }
            }
            // `RemoveFlag(UNIT_NPC_FLAGS, UNIT_NPC_FLAG_GOSSIP)`
            // (cpp 298); the fork then falls through to the elite
            // respawn timing (`SetRespawnTime`, no helper).
            AQ20_NPC_GENERAL_ANDOROV if self.creatures.contains_key(&victim) => {
                let flags = self.object_get_field(victim, offsets::UNIT_NPC_FLAGS);
                let _ = self.object_set_field(
                    victim,
                    u32::from(offsets::UNIT_NPC_FLAGS),
                    flags & !AQ20_UNIT_NPC_FLAG_GOSSIP,
                );
            }
            AQ20_NPC_GENERAL_ANDOROV => {
                let _ = victim;
            }
            // `NPC_RAJAXX`: `GiveRepAfterRajaxxDeath` (cpp 575-644)
            // needs player reputation/group helpers (unresolved).
            // `NPC_KALDOREI_ELITE`: respawn timing only (cpp
            // 301-305), `SetRespawnTime` has no helper (unresolved).
            _ => {}
        }
    }

    /// `instance_ruins_of_ahnqiraj::OnCreatureEvade` (cpp 166-196).
    /// The elite arm's `AddThreatsOf` (full threat-list copy) is
    /// reduced to re-engaging Andorov's current victim.
    fn aq20_on_creature_evade(&mut self, creature: ObjectGuid) {
        let Some(entry) = self.object_entry(creature) else {
            return;
        };
        match entry {
            AQ20_NPC_CAPTAIN_QEEZ
            | AQ20_NPC_CAPTAIN_TUUBID
            | AQ20_NPC_CAPTAIN_DRENN
            | AQ20_NPC_CAPTAIN_XURREM
            | AQ20_NPC_MAJOR_YEGGETH
            | AQ20_NPC_MAJOR_PAKKON
            | AQ20_NPC_COLONEL_ZERRAN
            | AQ20_NPC_SWARMGUARD_NEEDLER
            | AQ20_NPC_QIRAJI_WARRIOR => {
                if let Some(s) = self.ruins_of_ahnqiraj_mut() {
                    s.rajaxx_reset_timer_ms = 2000;
                    s.rajaxx_reset_pending = true;
                }
            }
            AQ20_NPC_KALDOREI_ELITE => {
                let andorov = self
                    .ruins_of_ahnqiraj()
                    .map_or(ObjectGuid::EMPTY, |s| s.andorov);
                if self.ai_in_combat(andorov)
                    && let Some(victim) = self.unit_victim(andorov)
                {
                    self.enter_combat(creature, victim);
                }
            }
            _ => {}
        }
    }

    /// `instance_ruins_of_ahnqiraj::SetData` (cpp 332-424).
    fn aq20_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            AQ20_TYPE_QIRAJI_GLADIATOR => {
                if let Some(s) = self.ruins_of_ahnqiraj_mut() {
                    if data > 0 {
                        s.gladiator_deaths = s.gladiator_deaths.wrapping_add(data);
                    } else {
                        s.gladiator_deaths = 0;
                    }
                }
                // Fork early-returns (cpp 341), skipping the save
                // refresh below.
                return true;
            }
            AQ20_TYPE_KURINNAXX => {
                if let Some(s) = self.ruins_of_ahnqiraj_mut() {
                    s.encounter[AQ20_TYPE_KURINNAXX as usize] = data;
                }
            }
            AQ20_TYPE_GENERAL_ANDOROV => {
                if data == AQ20_NOT_STARTED || data == AQ20_FAIL {
                    // `SetDefaultGossipMenuId(ANDOROV_GOSSIP_NOT_STARTED)`
                    // (cpp 349): no gossip helper (unresolved).
                }
                if data == IN_PROGRESS {
                    self.aq20_set_andorov_squad_immunity(false);
                    // `SetDefaultGossipMenuId(ANDOROV_GOSSIP_IN_PROGRESS)`
                    // (cpp 356): no gossip helper (unresolved).
                    let andorov = self
                        .ruins_of_ahnqiraj()
                        .map_or(ObjectGuid::EMPTY, |s| s.andorov);
                    if self.creatures.contains_key(&andorov) {
                        // `RemoveFlag(UNIT_NPC_FLAGS, UNIT_NPC_FLAG_VENDOR)`
                        // (cpp 357).
                        let flags = self.object_get_field(andorov, offsets::UNIT_NPC_FLAGS);
                        let _ = self.object_set_field(
                            andorov,
                            u32::from(offsets::UNIT_NPC_FLAGS),
                            flags & !AQ20_UNIT_NPC_FLAG_VENDOR,
                        );
                    }
                }
                if let Some(s) = self.ruins_of_ahnqiraj_mut() {
                    s.encounter[AQ20_TYPE_GENERAL_ANDOROV as usize] = data;
                }
            }
            AQ20_TYPE_RAJAXX => {
                if data == AQ20_NOT_STARTED
                    && self
                        .ruins_of_ahnqiraj()
                        .is_some_and(|s| s.encounter[AQ20_TYPE_KURINNAXX as usize] == DONE)
                {
                    // `SetAndorovSquadRespawnTime(AQ_RESPAWN_15_MINUTES)`
                    // (cpp 367): `SetRespawnTime` has no helper
                    // (unresolved).
                }
                if data == DONE {
                    // Patch gate `>= WOW_PATCH_110` (cpp 376) is
                    // statically true (see enter-combat).
                    let andorov = self
                        .ruins_of_ahnqiraj()
                        .map_or(ObjectGuid::EMPTY, |s| s.andorov);
                    if self.creatures.contains_key(&andorov) {
                        // `SetFlag(UNIT_NPC_FLAGS, UNIT_NPC_FLAG_VENDOR)`
                        // (cpp 377).
                        let flags = self.object_get_field(andorov, offsets::UNIT_NPC_FLAGS);
                        let _ = self.object_set_field(
                            andorov,
                            u32::from(offsets::UNIT_NPC_FLAGS),
                            flags | AQ20_UNIT_NPC_FLAG_VENDOR,
                        );
                        // `SetDefaultGossipMenuId(ANDOROV_GOSSIP_DONE)` +
                        // `SetRespawnTime(AQ_RESPAWN_FOUR_DAYS)` (cpp
                        // 379-380): no gossip/respawn helpers
                        // (unresolved).
                    }
                    self.aq20_set_andorov_squad_immunity(true);
                }
                if let Some(s) = self.ruins_of_ahnqiraj_mut() {
                    s.rajaxx_reset_pending = false;
                    s.encounter[AQ20_TYPE_RAJAXX as usize] = data;
                }
            }
            AQ20_TYPE_OSSIRIAN => {
                if data == AQ20_FAIL || data == DONE {
                    // Crystal cleanup (cpp 389-398):
                    // `AddObjectToRemoveList` over live crystals.
                    let crystals = self
                        .ruins_of_ahnqiraj()
                        .map_or(Vec::new(), |s| s.crystal_guids.clone());
                    for guid in crystals {
                        self.despawn_gameobject_now(guid);
                    }
                    if let Some(s) = self.ruins_of_ahnqiraj_mut() {
                        s.crystal_guids.clear();
                        s.crystal_indexes.clear();
                    }
                }
                if let Some(s) = self.ruins_of_ahnqiraj_mut() {
                    s.encounter[AQ20_TYPE_OSSIRIAN as usize] = data;
                }
            }
            AQ20_TYPE_BURU | AQ20_TYPE_MOAM | AQ20_TYPE_AYAMISS => {
                if let Some(s) = self.ruins_of_ahnqiraj_mut() {
                    s.encounter[field as usize] = data;
                }
            }
            _ => return false,
        }
        // Fork condition copied exactly (cpp 412): ANY field below
        // `MAX_ENCOUNTER` set `DONE` refreshes the cached string over
        // the fixed 7-slot stream (separator form, no trailing space,
        // cpp 417); the early `return`s above skip it like the fork.
        if field < AQ20_MAX_ENCOUNTER as u32
            && data == DONE
            && let Some(s) = self.ruins_of_ahnqiraj_mut()
        {
            let e = s.encounter;
            s.save_string = format!(
                "{} {} {} {} {} {} {}",
                e[0], e[1], e[2], e[3], e[4], e[5], e[6]
            );
        }
        true
    }

    /// `instance_ruins_of_ahnqiraj::GetData` (cpp 312-330). The fork
    /// returns 0 for unknown fields; content.rs convention is `None`.
    fn aq20_get_data(&self, field: u32) -> Option<u32> {
        let s = self.ruins_of_ahnqiraj()?;
        match field {
            AQ20_TYPE_QIRAJI_GLADIATOR => Some(s.gladiator_deaths),
            AQ20_TYPE_KURINNAXX
            | AQ20_TYPE_GENERAL_ANDOROV
            | AQ20_TYPE_RAJAXX
            | AQ20_TYPE_BURU
            | AQ20_TYPE_MOAM
            | AQ20_TYPE_AYAMISS
            | AQ20_TYPE_OSSIRIAN => Some(s.encounter[field as usize]),
            _ => None,
        }
    }

    /// `instance_ruins_of_ahnqiraj::GetData64` (cpp 68-122).
    fn aq20_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        if field == AQ20_DATA_YEGGETH_SHIELD {
            // Fork intent (cpp 106-117): random shield-list entry (the
            // fork loop as written is buggy: `||` runs `itr` past
            // `end()`). Unreachable in practice: the enter-combat push
            // needs a `CreatureGroup`-leader check with no `Map`
            // helper, and the pick itself needs `&mut` rng while
            // `GetData64` is `&self` (both unresolved). The read keeps
            // the fork's slot shape without inventing a `&self` pick.
            let shield = self
                .ruins_of_ahnqiraj()
                .map_or(Vec::new(), |s| s.yeggeth_shield.clone());
            if shield.is_empty() {
                return None;
            }
            return shield.first().copied();
        }
        let guid = match field {
            AQ20_DATA_OSSIRIAN => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.ossirian),
            AQ20_DATA_BURU => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.buru),
            AQ20_DATA_AYAMISS => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.ayamiss),
            AQ20_DATA_MOAM => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.moam),
            AQ20_DATA_ANDOROV => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.andorov),
            AQ20_DATA_KURINNAXX => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.kurinnaxx),
            AQ20_DATA_QEEZ => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.qeez),
            AQ20_DATA_TUUBID => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.tuubid),
            AQ20_DATA_DRENN => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.drenn),
            AQ20_DATA_XURREM => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.xurrem),
            AQ20_DATA_YEGGETH => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.yeggeth),
            AQ20_DATA_PAKKON => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.pakkon),
            AQ20_DATA_ZERRAN => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.zerran),
            AQ20_DATA_RAJAXX => self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.rajaxx),
            _ => return None,
        };
        if guid.is_empty() { None } else { Some(guid) }
    }

    /// `instance_ruins_of_ahnqiraj::IsEncounterInProgress` (cpp 60-66).
    fn aq20_is_encounter_in_progress(&self) -> bool {
        self.ruins_of_ahnqiraj().is_some_and(|s| {
            s.encounter
                .iter()
                .any(|&v| v == IN_PROGRESS || v == AQ20_SPECIAL)
        })
    }

    /// `instance_ruins_of_ahnqiraj::Save` (cpp 426): cached string
    /// (the fork never recomputes from encounters here).
    fn aq20_save(&self) -> Option<String> {
        self.ruins_of_ahnqiraj().map(|s| s.save_string.clone())
    }

    /// `instance_ruins_of_ahnqiraj::Load` (cpp 428-450). Streams 7
    /// slots; `IN_PROGRESS` or above `SPECIAL` resets to
    /// `NOT_STARTED`, plus the extra Andorov `DONE` reset (cpp 446).
    fn aq20_load(&mut self, data: &str) {
        let mut loaded = [0u32; AQ20_MAX_ENCOUNTER];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS || *value > AQ20_SPECIAL {
                *value = AQ20_NOT_STARTED;
            }
        }
        if loaded[AQ20_TYPE_GENERAL_ANDOROV as usize] == DONE {
            loaded[AQ20_TYPE_GENERAL_ANDOROV as usize] = AQ20_NOT_STARTED;
        }
        if let Some(s) = self.ruins_of_ahnqiraj_mut() {
            s.encounter = loaded;
        }
    }

    /// `instance_ruins_of_ahnqiraj::Update` (cpp 452-515).
    fn aq20_update(&mut self, diff_ms: u32) {
        // Fork patch gate `sWorld.GetWowPatch() > WOW_PATCH_109`
        // (cpp 463) is statically true (see enter-combat).
        if self.aq20_is_any_boss_in_combat() {
            // `SummonGameObject(176149, ...)` AQ door (cpp 469-470): no
            // free-position gameobject-summon helper (unresolved), so
            // `door` stays empty and the removal half below is vacuous.
        } else {
            let door = self
                .ruins_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.door);
            if !door.is_empty() {
                // `AddObjectToRemoveList` (cpp 477).
                self.despawn_gameobject_now(door);
                if let Some(s) = self.ruins_of_ahnqiraj_mut() {
                    s.door = ObjectGuid::EMPTY;
                }
            }
        }
        // Kurinnaxx-DONE Andorov auto-spawn (cpp 485-491):
        // `LoadCreatureSpawnWithGroup(ANDOROV_DB_GUID)` has no
        // spawn-by-guid helper and `MoveWaypoint` has no waypoint-path
        // helper (unresolved).
        if self
            .ruins_of_ahnqiraj()
            .is_some_and(|s| s.rajaxx_reset_pending)
        {
            // Fork comparison copied exactly (`<`, cpp 497).
            let fire = if let Some(s) = self.ruins_of_ahnqiraj_mut() {
                if s.rajaxx_reset_timer_ms < diff_ms {
                    true
                } else {
                    s.rajaxx_reset_timer_ms -= diff_ms;
                    false
                }
            } else {
                false
            };
            if fire {
                let rajaxx = self
                    .ruins_of_ahnqiraj()
                    .map_or(ObjectGuid::EMPTY, |s| s.rajaxx);
                if !rajaxx.is_empty() {
                    // `pRajaxx->AI()->EnterEvadeMode()` (cpp 498).
                    self.enter_evade_mode(rajaxx);
                }
                if let Some(s) = self.ruins_of_ahnqiraj_mut() {
                    s.rajaxx_reset_pending = false;
                }
            }
        }
        // Prune despawned crystals (cpp 505-514).
        let stale: Vec<ObjectGuid> = self.ruins_of_ahnqiraj().map_or(Vec::new(), |s| {
            s.crystal_indexes
                .iter()
                .map(|(g, _)| *g)
                .filter(|g| !self.gameobjects.contains_key(g))
                .collect()
        });
        for guid in stale {
            if let Some(s) = self.ruins_of_ahnqiraj_mut() {
                s.crystal_indexes.retain(|(g, _)| *g != guid);
            }
        }
    }

    /// `SetAndorovSquadImmunity` (cpp 553-572).
    fn aq20_set_andorov_squad_immunity(&mut self, immune: bool) {
        let (andorov, elites) = self
            .ruins_of_ahnqiraj()
            .map_or((ObjectGuid::EMPTY, Vec::new()), |s| {
                (s.andorov, s.kaldorei_elites.clone())
            });
        let mut squad = Vec::with_capacity(elites.len() + 1);
        squad.push(andorov);
        squad.extend(elites);
        for guid in squad {
            if !self.creatures.contains_key(&guid) {
                continue;
            }
            let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
            let _ = self.object_set_field(
                guid,
                u32::from(offsets::UNIT_FIELD_FLAGS),
                if immune {
                    flags | AQ20_UNIT_FLAG_IMMUNE_TO_NPC
                } else {
                    flags & !AQ20_UNIT_FLAG_IMMUNE_TO_NPC
                },
            );
        }
    }

    /// `IsAnyBossInCombat` (cpp 519-534).
    fn aq20_is_any_boss_in_combat(&self) -> bool {
        if self.aq20_get_data(AQ20_TYPE_GENERAL_ANDOROV) == Some(IN_PROGRESS) {
            return true;
        }
        for field in AQ20_DATA_KURINNAXX..=AQ20_DATA_ZERRAN {
            let guid = self.aq20_get_data64(field).unwrap_or(ObjectGuid::EMPTY);
            if guid != ObjectGuid::EMPTY
                && self
                    .creatures
                    .get(&guid)
                    .is_some_and(|c| c.unit.is_alive() && self.unit_victim(guid).is_some())
            {
                return true;
            }
        }
        false
    }

    // ------------------------------------------------ instance: molten core

    /// Shared rune-GO arm of `instance_molten_core::OnObjectCreate`
    /// (cpp 90-152): when the rune's state is already DONE, queue the
    /// GO for the fire-anim cleanup pass in `mc_update`.
    fn mc_note_rune_go(&mut self, guid: ObjectGuid, slot: usize) {
        if self.molten_core().map_or(0, |s| s.rune_states[slot]) == DONE
            && let Some(s) = self.molten_core_mut()
        {
            s.go_use_guids[slot] = guid;
        }
    }

    /// `instance_molten_core::IsEncounterInProgress` (cpp 73-84).
    fn mc_is_encounter_in_progress(&self) -> bool {
        self.molten_core().is_some_and(|s| {
            s.encounter
                .iter()
                .any(|e| *e == IN_PROGRESS || *e == MC_SPECIAL)
        })
    }

    /// `instance_molten_core::OnObjectCreate` (cpp 86-165).
    fn mc_on_object_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            MC_RUNE_SULFURON => self.mc_note_rune_go(guid, 0),
            MC_RUNE_GEDDON => self.mc_note_rune_go(guid, 1),
            MC_RUNE_SHAZZRAH => self.mc_note_rune_go(guid, 2),
            MC_RUNE_GOLEMAGG => self.mc_note_rune_go(guid, 3),
            MC_RUNE_GARR => self.mc_note_rune_go(guid, 4),
            MC_RUNE_MAGMADAR => self.mc_note_rune_go(guid, 5),
            MC_RUNE_GEHENNAS => self.mc_note_rune_go(guid, 6),
            MC_GO_HOT_COALS => {
                // Fork `SetFlag(GAMEOBJECT_FLAGS, GO_FLAG_IN_USE)`
                // (cpp 156): read-modify-write through
                // `GAMEOBJECT_FLAGS` (no flag helper on `Map`).
                // The stored HotCoals GUID is never read; dropped.
                let flags = self.object_get_field(guid, offsets::GAMEOBJECT_FLAGS);
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::GAMEOBJECT_FLAGS),
                    flags | MC_GO_FLAG_IN_USE,
                );
            }
            MC_RUNE_MAJORDOMO => {
                if let Some(s) = self.molten_core_mut() {
                    s.firelord_cache = guid;
                }
            }
            _ => {}
        }
    }

    /// `instance_molten_core::OnCreatureCreate` (cpp 285-423).
    /// `OnCreatureRespawn` DONE-gated removals (cpp 167-233) re-enter
    /// through this hook (maraudon precedent).
    fn mc_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            MC_NPC_SULFURON => {
                if let Some(s) = self.molten_core_mut() {
                    s.sulfuron = guid;
                }
            }
            MC_NPC_GOLEMAGG => {
                if let Some(s) = self.molten_core_mut() {
                    s.golemagg = guid;
                }
            }
            MC_NPC_GARR => {
                if let Some(s) = self.molten_core_mut() {
                    s.garr = guid;
                }
                // `m_mNpcEntryGuidStore[entry] = guid` (cpp 399) is
                // base-class state with no Rust equivalent
                // (unresolved); the `m_uiGarrGUID` store above covers
                // `GetData64(DATA_GARR)`.
            }
            MC_NPC_MAJORDOMO => {
                if let Some(s) = self.molten_core_mut() {
                    s.majordomo = guid;
                }
            }
            MC_NPC_FLAMEWAKER_PRIEST => {
                // Stored GUID never read; only the DONE-gated removal
                // (cpp 335-342, shared with `OnCreatureRespawn`
                // cpp 171-178) is transcribed.
                if self
                    .molten_core()
                    .map_or(0, |s| s.encounter[MC_TYPE_SULFURON as usize])
                    == DONE
                {
                    // `AddObjectToRemoveList` (cpp 339).
                    self.despawn_creature_now(guid, u32::MAX);
                }
            }
            MC_NPC_CORE_RAGER => {
                if self
                    .molten_core()
                    .map_or(0, |s| s.encounter[MC_TYPE_GOLEMAGG as usize])
                    == DONE
                {
                    // `AddObjectToRemoveList` (cpp 347).
                    self.despawn_creature_now(guid, u32::MAX);
                }
            }
            MC_NPC_FLAMEWAKER => {
                if self
                    .molten_core()
                    .map_or(0, |s| s.encounter[MC_TYPE_GEHENNAS as usize])
                    == DONE
                {
                    // `AddObjectToRemoveList` (cpp 355).
                    self.despawn_creature_now(guid, u32::MAX);
                }
            }
            MC_NPC_FLAMEWAKER_PROTECTOR => {
                if self
                    .molten_core()
                    .map_or(0, |s| s.encounter[MC_TYPE_LUCIFRON as usize])
                    == DONE
                {
                    // `AddObjectToRemoveList` (cpp 363).
                    self.despawn_creature_now(guid, u32::MAX);
                }
            }
            MC_NPC_CORE_HOUND | MC_NPC_ANCIENT_CORE_HOUND => {
                if self
                    .molten_core()
                    .map_or(0, |s| s.encounter[MC_TYPE_MAGMADAR as usize])
                    == DONE
                {
                    // `AddObjectToRemoveList` (cpp 208).
                    self.despawn_creature_now(guid, u32::MAX);
                }
            }
            MC_NPC_FIRESWORN | MC_NPC_LAVA_SURGER => {
                if self
                    .molten_core()
                    .map_or(0, |s| s.encounter[MC_TYPE_GARR as usize])
                    == DONE
                {
                    // `AddObjectToRemoveList` (cpp 407).
                    self.despawn_creature_now(guid, u32::MAX);
                }
            }
            MC_NPC_LAVA_SPAWN => {
                // Prevent exponential lava spawn creation in case of
                // evade bug (cpp 413-421).
                let Some(src_pos) = self.object_position(guid) else {
                    return;
                };
                let nearby = self
                    .creatures
                    .values()
                    .filter(|c| {
                        c.info.entry == MC_NPC_LAVA_SPAWN
                            && crate::visibility::dist3d(c.unit.world.position(), src_pos) <= 100.0
                    })
                    .count();
                if nearby > MC_MAX_LAVA_SPAWNS {
                    // `ForcedDespawn()` (cpp 418).
                    self.despawn_creature_now(guid, u32::MAX);
                }
            }
            // `LAVA_ANNIHILATOR`/`FIRELORD`: fork swaps each entry
            // for the other (`UpdateEntry` + `SetEntry` +
            // `AIM_Initialize`, cpp 367-386, respawn twins cpp
            // 234-253): no entry-swap/AI-reset helper (unresolved).
            _ => {}
        }
    }

    /// `instance_molten_core::OnCreatureEnterCombat` (cpp 257-283):
    /// Majordomo mob linking (can't be done in DB since Majordomo is
    /// summoned). Fork `SetInCombatWith(pVictim)` rides
    /// `attack_start`; the alive/not-in-combat gate is kept.
    fn mc_on_creature_enter_combat(&mut self, creature: ObjectGuid) {
        let entry = self.object_entry(creature);
        if entry != Some(MC_NPC_MAJORDOMO)
            && entry != Some(MC_NPC_FLAMEWAKER_HEALER)
            && entry != Some(MC_NPC_FLAMEWAKER_ELITE)
        {
            return;
        }
        // `GetVictim()` (cpp 264-266).
        let Some(victim) = self.unit_victim(creature) else {
            return;
        };
        let Some(src_pos) = self.object_position(creature) else {
            return;
        };
        // `GetCreatureListWithEntryInGrid` x3, 150 ft (cpp 270-272).
        let mut linked: Vec<ObjectGuid> = Vec::new();
        for want in [
            MC_NPC_FLAMEWAKER_HEALER,
            MC_NPC_FLAMEWAKER_ELITE,
            MC_NPC_MAJORDOMO,
        ] {
            for guid in self
                .creatures
                .values()
                .filter(|c| {
                    c.info.entry == want
                        && crate::visibility::dist3d(c.unit.world.position(), src_pos) <= 150.0
                })
                .map(|c| c.unit.guid())
            {
                linked.push(guid);
            }
        }
        if linked.is_empty() {
            return;
        }
        for add in linked {
            if self
                .creatures
                .get(&add)
                .is_some_and(|c| c.unit.is_alive() && !c.unit.is_in_combat())
            {
                self.attack_start(add, victim);
            }
        }
    }

    /// `instance_molten_core::SetData` (cpp 425-503). Returns true
    /// when the instance script owns the field (exemplar convention;
    /// C++ returns void).
    fn mc_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            MC_TYPE_SULFURON | MC_TYPE_GEDDON | MC_TYPE_SHAZZRAH | MC_TYPE_GOLEMAGG
            | MC_TYPE_GARR | MC_TYPE_MAGMADAR | MC_TYPE_GEHENNAS | MC_TYPE_LUCIFRON => {
                if let Some(s) = self.molten_core_mut() {
                    s.encounter[field as usize] = data;
                }
            }
            MC_TYPE_MAJORDOMO => {
                if let Some(s) = self.molten_core_mut() {
                    s.encounter[MC_TYPE_MAJORDOMO as usize] = data;
                }
                if data == DONE {
                    // NEEDS-MAP-HELPER:
                    // `DoRespawnGameObject(m_uiFirelordCacheGUID, HOUR)`
                    // (cpp 446): `respawn_gameobject(guid, 3600)`.
                    // The cache read below keeps the stored GUID live.
                    let _cache = self
                        .molten_core()
                        .map_or(ObjectGuid::EMPTY, |s| s.firelord_cache);
                }
            }
            MC_TYPE_RAGNAROS => {
                // Fork writes index 9 literally (cpp 452).
                if let Some(s) = self.molten_core_mut() {
                    s.encounter[MC_TYPE_RAGNAROS as usize] = data;
                }
            }
            MC_DATA_RUNE_ACTIVE_0
            | MC_DATA_RUNE_ACTIVE_1
            | MC_DATA_RUNE_ACTIVE_2
            | MC_DATA_RUNE_ACTIVE_3
            | MC_DATA_RUNE_ACTIVE_4
            | MC_DATA_RUNE_ACTIVE_5
            | MC_DATA_RUNE_ACTIVE_6 => {
                if let Some(s) = self.molten_core_mut() {
                    s.rune_states[(field - MC_DATA_RUNE_ACTIVE_0) as usize] = data;
                }
            }
            MC_DATA_DOMO_SPAWNED => {
                if let Some(s) = self.molten_core_mut() {
                    s.domo_spawned = data;
                }
            }
            _ => return false,
        }
        // Fork `SaveToDB()` runs on every DONE write (cpp 497-502);
        // no Rust persistence, and `Save()` recomputes live.
        true
    }

    /// `instance_molten_core::GetData` (cpp 513-565).
    fn mc_get_data(&self, field: u32) -> Option<u32> {
        let s = self.molten_core()?;
        match field {
            MC_TYPE_SULFURON | MC_TYPE_GEDDON | MC_TYPE_SHAZZRAH | MC_TYPE_GOLEMAGG
            | MC_TYPE_GARR | MC_TYPE_MAGMADAR | MC_TYPE_GEHENNAS | MC_TYPE_LUCIFRON
            | MC_TYPE_MAJORDOMO | MC_TYPE_RAGNAROS => Some(s.encounter[field as usize]),
            MC_DATA_RUNE_ACTIVE_0
            | MC_DATA_RUNE_ACTIVE_1
            | MC_DATA_RUNE_ACTIVE_2
            | MC_DATA_RUNE_ACTIVE_3
            | MC_DATA_RUNE_ACTIVE_4
            | MC_DATA_RUNE_ACTIVE_5
            | MC_DATA_RUNE_ACTIVE_6 => {
                Some(s.rune_states[(field - MC_DATA_RUNE_ACTIVE_0) as usize])
            }
            MC_DATA_DOMO_SPAWNED => Some(s.domo_spawned),
            _ => None,
        }
    }

    /// `instance_molten_core::GetData64` (cpp 567-590): stored GUID,
    /// or `None` when empty (fork returns 0).
    fn mc_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        let guid = match field {
            MC_DATA_SULFURON => self.molten_core().map_or(ObjectGuid::EMPTY, |s| s.sulfuron),
            MC_DATA_GOLEMAGG => self.molten_core().map_or(ObjectGuid::EMPTY, |s| s.golemagg),
            MC_DATA_GARR => self.molten_core().map_or(ObjectGuid::EMPTY, |s| s.garr),
            MC_DATA_MAJORDOMO => self
                .molten_core()
                .map_or(ObjectGuid::EMPTY, |s| s.majordomo),
            _ => return None,
        };
        (!guid.is_empty()).then_some(guid)
    }

    /// `instance_molten_core::Save` (cpp 505-511): streams the live
    /// encounters + runes every call (no cached string in the fork).
    fn mc_save(&self) -> Option<String> {
        self.molten_core().map(|s| {
            let e = s.encounter;
            let r = s.rune_states;
            format!(
                "{} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {}",
                e[0],
                e[1],
                e[2],
                e[3],
                e[4],
                e[5],
                e[6],
                e[7],
                e[8],
                e[9],
                r[0],
                r[1],
                r[2],
                r[3],
                r[4],
                r[5],
                r[6]
            )
        })
    }

    /// `instance_molten_core::Load` (cpp 670-701).
    fn mc_load(&mut self, data: &str) {
        let mut encounter = [0u32; MC_INSTANCE_MC_MAX_ENCOUNTER];
        let mut runes = [0u32; 7];
        let mut tokens = data.split_whitespace();
        for slot in encounter.iter_mut().chain(runes.iter_mut()) {
            *slot = tokens.next().and_then(|t| t.parse().ok()).unwrap_or(0);
        }
        // Fork resets IN_PROGRESS encounters only, not runes
        // (cpp 684-690).
        for value in &mut encounter {
            if *value == IN_PROGRESS {
                *value = MC_NOT_STARTED;
            }
        }
        if let Some(s) = self.molten_core_mut() {
            s.encounter = encounter;
            s.rune_states = runes;
        }
        // Fork re-applies encounters through `SetData` (cpp 692-695).
        for (i, value) in encounter.iter().enumerate() {
            self.mc_set_data(i as u32, *value);
        }
        // Fork quirk (cpp 697-700): the rune re-apply loop passes the
        // constant field `DATA_RUNE_ACTIVE_0 + 16` (32), which matches
        // no `SetData` arm, so every iteration is a no-op; mirrored
        // literally.
        for value in runes {
            self.mc_set_data(MC_DATA_RUNE_ACTIVE_0 + 16, value);
        }
    }

    /// `instance_molten_core::Update` (cpp 602-668).
    fn mc_update(&mut self, diff_ms: u32) {
        // `m_ObjectRemoveTimer` (cpp 604-612); fork uses strict `<`.
        let flush = if let Some(s) = self.molten_core_mut() {
            if s.object_remove_timer_ms < diff_ms {
                s.object_remove_timer_ms = 5000;
                true
            } else {
                s.object_remove_timer_ms -= diff_ms;
                false
            }
        } else {
            false
        };
        if flush {
            // NEEDS-MAP-HELPER:
            // `instance->RemoveAllObjectsInRemoveList()` (cpp 606).
        }
        // No players: no rune use pass (cpp 614-616).
        if self.player_count() == 0 {
            return;
        }
        // Rune fire-anim cleanup (cpp 617-667): for each queued rune
        // GO, delete the nearest fire anim within 20 ft and mark the
        // rune DONE (`pRune->Use(pUser)` re-enters the `go_rune_MC`
        // hello, whose reachable instance effect is exactly this
        // `SetData`; the hello/summon remainder is unresolved).
        let queued = self
            .molten_core()
            .map_or([ObjectGuid::EMPTY; 7], |s| s.go_use_guids);
        for (slot, rune) in queued.iter().enumerate() {
            if *rune == ObjectGuid::EMPTY || self.gameobject(*rune).is_none() {
                continue;
            }
            let Some(fire) =
                self.nearest_gameobject_with_entry(*rune, MC_GO_RUNE_FIRE_ANIM[slot], 20.0)
            else {
                continue;
            };
            self.despawn_gameobject_now(fire);
            self.mc_set_data(MC_DATA_RUNE_ACTIVE_0 + slot as u32, DONE);
            if let Some(s) = self.molten_core_mut() {
                s.go_use_guids[slot] = ObjectGuid::EMPTY;
            }
        }
    }

    // ------------------------------------------------ instance: blackrock spire

    pub(crate) fn brs_encounter(&self, index: usize) -> u32 {
        self.blackrock_spire().map_or(0, |s| s.encounter[index])
    }

    /// `instance_blackrock_spire::OnCreatureCreate` (cpp 249-295).
    fn brs_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            BRS_NPC_LORD_VICTOR_NEFARIUS => {
                if let Some(s) = self.blackrock_spire_mut() {
                    s.nefarius = guid;
                }
            }
            BRS_NPC_REND_BLACKHAND => {
                // Only the original Rend is saved (cpp 257-259).
                let empty = self.blackrock_spire().is_none_or(|s| s.rend.is_empty());
                if empty {
                    if let Some(s) = self.blackrock_spire_mut() {
                        s.rend = guid;
                    }
                }
            }
            BRS_NPC_GYTH => {
                if let Some(s) = self.blackrock_spire_mut() {
                    s.gyth = guid;
                }
            }
            BRS_NPC_SCARSHIELD_INFILTRATOR => {
                if let Some(s) = self.blackrock_spire_mut() {
                    s.infiltrator = guid;
                }
            }
            BRS_NPC_DRAKKISATH => {
                if let Some(s) = self.blackrock_spire_mut() {
                    s.drakkisath = guid;
                }
            }
            BRS_NPC_THE_BEAST => {
                if let Some(s) = self.blackrock_spire_mut() {
                    s.beast = guid;
                }
            }
            BRS_NPC_BLACKHAND_SUMMONER | BRS_NPC_BLACKHAND_VETERAN => {
                if let Some(s) = self.blackrock_spire_mut() {
                    if !s.room_event_mobs.contains(&guid) {
                        s.room_event_mobs.push(guid);
                    }
                }
            }
            BRS_NPC_FIREBRAND_GRUNT => {
                // 14.26% chance to spawn Bannok Grimaxe (entry 9596)
                // instead of one of his 3 placeholders (cpp 281-293).
                // `UpdateEntry` has no `Map` equivalent (unresolved); the
                // roll and flag are kept so the integrator sees where the
                // swap belongs.
                let low = guid.counter();
                if low == 44_020 || low == 43_764 || low == 44_327 {
                    let already = self.blackrock_spire().is_none_or(|s| s.bannok_spawned);
                    if !already && self.spell_rng().irand(0, 99) < 5 {
                        if let Some(s) = self.blackrock_spire_mut() {
                            s.bannok_spawned = true;
                        }
                    }
                }
            }
            _ => {}
        }
    }

