    /// `instance_blackrock_spire::SetData` (cpp 297-386).
    #[allow(clippy::too_many_lines)] // one fork override port
    pub(crate) fn brs_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            BRS_TYPE_ROOM_EVENT => {
                if data == DONE {
                    let door = self
                        .blackrock_spire()
                        .map_or(ObjectGuid::EMPTY, |s| s.emberseer_in_door);
                    if door != ObjectGuid::EMPTY {
                        self.use_door(door);
                    }
                }
                if let Some(s) = self.blackrock_spire_mut() {
                    s.encounter[BRS_TYPE_ROOM_EVENT as usize] = data;
                }
            }
            BRS_TYPE_EMBERSEER => {
                if let Some(s) = self.blackrock_spire_mut() {
                    s.encounter[BRS_TYPE_EMBERSEER as usize] = data;
                }
            }
            BRS_TYPE_FLAMEWREATH => {
                if let Some(s) = self.blackrock_spire_mut() {
                    s.encounter[BRS_TYPE_FLAMEWREATH as usize] = data;
                }
            }
            BRS_TYPE_STADIUM => {
                // Don't set the same data twice (cpp 314-315). The fork
                // `break` still falls through to the save block below.
                if self.brs_encounter(BRS_TYPE_STADIUM as usize) != data {
                    let entry_door = self
                        .blackrock_spire()
                        .map_or(ObjectGuid::EMPTY, |s| s.gyth_entry_door);
                    if entry_door != ObjectGuid::EMPTY {
                        self.use_door(entry_door);
                    }
                    if data == IN_PROGRESS {
                        // `StartNextDialogueText(SAY_NEFARIUS_INTRO_1)`
                        // (cpp 320): no dialogue helper on `Map`
                        // (unresolved).
                    } else if data == DONE {
                        self.brs_despawn_stadium_spectators();
                        let exit_door = self
                            .blackrock_spire()
                            .map_or(ObjectGuid::EMPTY, |s| s.gyth_exit_door);
                        if exit_door != ObjectGuid::EMPTY {
                            self.use_door(exit_door);
                        }
                    } else if data == BRS_FAIL {
                        // Despawn Nefarius, Rend and the spectators on fail
                        // (the others are despawned OnCreatureEvade, cpp 329).
                        let (nefarius, rend, gyth) = self.blackrock_spire().map_or(
                            (ObjectGuid::EMPTY, ObjectGuid::EMPTY, ObjectGuid::EMPTY),
                            |s| (s.nefarius, s.rend, s.gyth),
                        );
                        for guid in [nefarius, rend, gyth] {
                            if guid != ObjectGuid::EMPTY {
                                self.despawn_creature_now(guid, 0);
                            }
                        }
                        self.brs_despawn_stadium_spectators();
                        if let Some(s) = self.blackrock_spire_mut() {
                            s.stadium_event_timer = 0;
                            s.stadium_mobs_alive = 0;
                            s.stadium_waves = 0;
                        }
                    }
                    if let Some(s) = self.blackrock_spire_mut() {
                        s.encounter[BRS_TYPE_STADIUM as usize] = data;
                    }
                }
            }
            BRS_TYPE_VALTHALAK => {
                if let Some(s) = self.blackrock_spire_mut() {
                    s.encounter[BRS_TYPE_VALTHALAK as usize] = data;
                }
            }
            BRS_TYPE_EVENT_DOOR_UBRS => {
                if data == DONE {
                    if let Some(s) = self.blackrock_spire_mut() {
                        s.ubrs_door_timer = 2000;
                    }
                }
                if let Some(s) = self.blackrock_spire_mut() {
                    s.encounter[BRS_TYPE_EVENT_DOOR_UBRS as usize] = data;
                }
            }
            BRS_TYPE_SOLAKAR => {
                if data == BRS_FAIL {
                    let running = self
                        .blackrock_spire()
                        .is_some_and(|s| s.father_flame_timer != 0);
                    if running {
                        // `DoRespawnGameObject(m_uiFatherFlameGUID, ...)`
                        // (cpp 355) is commented out in the fork.
                        if let Some(s) = self.blackrock_spire_mut() {
                            s.father_flame_timer = 0;
                            s.father_flame_wave_count = 0;
                        }
                    }
                }
                if data == IN_PROGRESS {
                    if let Some(s) = self.blackrock_spire_mut() {
                        s.father_flame_timer = 5000;
                    }
                }
                if let Some(s) = self.blackrock_spire_mut() {
                    s.encounter[BRS_TYPE_SOLAKAR as usize] = data;
                }
            }
            BRS_TYPE_DRAKKISATH => {
                if data == DONE {
                    let (door1, door2) = self
                        .blackrock_spire()
                        .map_or((ObjectGuid::EMPTY, ObjectGuid::EMPTY), |s| {
                            (s.drakkisath_door1, s.drakkisath_door2)
                        });
                    if door1 != ObjectGuid::EMPTY {
                        self.use_door(door1);
                    }
                    if door2 != ObjectGuid::EMPTY {
                        self.use_door(door2);
                    }
                }
                if let Some(s) = self.blackrock_spire_mut() {
                    s.encounter[BRS_TYPE_DRAKKISATH as usize] = data;
                }
            }
            _ => return false,
        }
        // Fork refreshes `strInstData` from the fixed 8-slot stream on ANY
        // field set DONE (cpp 374-385); separator form, no trailing space.
        if data == DONE {
            if let Some(s) = self.blackrock_spire_mut() {
                let e = s.encounter;
                s.save_string = format!(
                    "{} {} {} {} {} {} {} {}",
                    e[0], e[1], e[2], e[3], e[4], e[5], e[6], e[7]
                );
            }
        }
        true
    }

    /// `instance_blackrock_spire::OnCreatureDeath` (cpp 388-429).
    fn brs_on_creature_death(&mut self, victim: ObjectGuid) {
        let Some(entry) = self.object_entry(victim) else {
            return;
        };
        match entry {
            BRS_NPC_CHROMATIC_WHELP | BRS_NPC_CHROMATIC_DRAGON | BRS_NPC_BLACKHAND_HANDLER => {
                // Only summoned stadium mobs count; same-entry mobs already
                // spawned in the instance are ignored (cpp 396-397).
                // `IsTemporarySummon` == membership in `summons`
                // (spells.rs precedent).
                if !self.summons.contains_key(&victim) {
                    return;
                }
                // 5% chance for Nefarius or Rend to taunt (cpp 401-417).
                if self.spell_rng().irand(0, 100) < 5 {
                    let nefarius = self
                        .blackrock_spire()
                        .map_or(ObjectGuid::EMPTY, |s| s.nefarius);
                    if !nefarius.is_empty() && self.creatures.contains_key(&nefarius) {
                        // `PickRandomValue` over the 8 taunts (cpp 405).
                        let taunts = [
                            BRS_SAY_NEFARIUS_TAUNT1,
                            BRS_SAY_NEFARIUS_TAUNT2,
                            BRS_SAY_NEFARIUS_TAUNT3,
                            BRS_SAY_NEFARIUS_TAUNT4,
                            BRS_SAY_NEFARIUS_TAUNT5,
                            BRS_SAY_NEFARIUS_TAUNT6,
                            BRS_SAY_NEFARIUS_TAUNT7,
                            BRS_SAY_NEFARIUS_TAUNT8,
                        ];
                        let pick = self.spell_rng().irand(0, 7) as usize;
                        self.do_script_text(taunts[pick], nefarius, None, -1);
                    }
                }
                if self.spell_rng().irand(0, 100) < 5 {
                    let rend = self.blackrock_spire().map_or(ObjectGuid::EMPTY, |s| s.rend);
                    if !rend.is_empty() && self.creatures.contains_key(&rend) {
                        let taunts = [
                            BRS_SAY_REND_TAUNT1,
                            BRS_SAY_REND_TAUNT2,
                            BRS_SAY_REND_TAUNT3,
                            BRS_SAY_REND_TAUNT4,
                        ];
                        let pick = self.spell_rng().irand(0, 3) as usize;
                        self.do_script_text(taunts[pick], rend, None, -1);
                    }
                }
                let (alive, waves) = if let Some(s) = self.blackrock_spire_mut() {
                    s.stadium_mobs_alive = s.stadium_mobs_alive.wrapping_sub(1);
                    (s.stadium_mobs_alive, s.stadium_waves)
                } else {
                    return;
                };
                if alive == 0 && waves == BRS_MAX_STADIUM_WAVES {
                    self.brs_send_next_stadium_wave();
                }
            }
            BRS_NPC_GYTH | BRS_NPC_REND_BLACKHAND => {
                if !self.summons.contains_key(&victim) {
                    return;
                }
                let alive = if let Some(s) = self.blackrock_spire_mut() {
                    s.stadium_mobs_alive = s.stadium_mobs_alive.wrapping_sub(1);
                    s.stadium_mobs_alive
                } else {
                    return;
                };
                if alive == 0 {
                    // `StartNextDialogueText(SAY_NEFARIUS_VICTORY)`
                    // (cpp 426): no dialogue helper on `Map` (unresolved).
                }
            }
            _ => {}
        }
    }

    /// `instance_blackrock_spire::OnCreatureEvade` (cpp 431-447). No
    /// `instance_on_creature_evade` dispatcher exists on `Map` yet; the
    /// integrator wires this when one is added.
    fn brs_on_creature_evade(&mut self, creature: ObjectGuid) {
        let Some(entry) = self.object_entry(creature) else {
            return;
        };
        match entry {
            BRS_NPC_CHROMATIC_WHELP
            | BRS_NPC_CHROMATIC_DRAGON
            | BRS_NPC_BLACKHAND_HANDLER
            | BRS_NPC_GYTH
            | BRS_NPC_REND_BLACKHAND => {
                if !self.summons.contains_key(&creature) {
                    return;
                }
                self.brs_set_data(BRS_TYPE_STADIUM, BRS_FAIL);
                self.despawn_creature_now(creature, 0);
            }
            _ => {}
        }
    }

    /// `instance_blackrock_spire::SetData64` (cpp 697-719).
    fn brs_set_data64(&mut self, field: u32, data: ObjectGuid) -> bool {
        if field != BRS_TYPE_ROOM_EVENT {
            return false;
        }
        if self.brs_encounter(BRS_TYPE_ROOM_EVENT as usize) != IN_PROGRESS {
            return false;
        }
        let mut remaining = 0u32;
        for i in 0..BRS_MAX_ROOMS {
            let rune = self
                .blackrock_spire()
                .map_or(ObjectGuid::EMPTY, |s| s.room_runes[i]);
            if rune.is_empty() {
                // Rune already processed (cpp 704).
                continue;
            }
            let mut sorted = self
                .blackrock_spire()
                .map_or(Vec::new(), |s| s.room_mobs_sorted[i].clone());
            sorted.retain(|guid| *guid != data);
            let empty = sorted.is_empty();
            if let Some(s) = self.blackrock_spire_mut() {
                s.room_mobs_sorted[i] = sorted;
            }
            if empty {
                if rune != ObjectGuid::EMPTY {
                    self.use_door(rune);
                }
                if let Some(s) = self.blackrock_spire_mut() {
                    s.room_runes[i] = ObjectGuid::EMPTY;
                }
            } else {
                remaining += 1;
            }
        }
        if remaining == 0 {
            self.brs_set_data(BRS_TYPE_ROOM_EVENT, DONE);
        }
        true
    }

    /// `instance_blackrock_spire::GetData` (cpp 744-758).
    fn brs_get_data(&self, field: u32) -> Option<u32> {
        let s = self.blackrock_spire()?;
        match field {
            BRS_TYPE_ROOM_EVENT => Some(s.encounter[BRS_TYPE_ROOM_EVENT as usize]),
            BRS_TYPE_EMBERSEER => Some(s.encounter[BRS_TYPE_EMBERSEER as usize]),
            BRS_TYPE_FLAMEWREATH => Some(s.encounter[BRS_TYPE_FLAMEWREATH as usize]),
            BRS_TYPE_STADIUM => Some(s.encounter[BRS_TYPE_STADIUM as usize]),
            BRS_TYPE_VALTHALAK => Some(s.encounter[BRS_TYPE_VALTHALAK as usize]),
            BRS_TYPE_EVENT_DOOR_UBRS => Some(s.encounter[BRS_TYPE_EVENT_DOOR_UBRS as usize]),
            BRS_TYPE_SOLAKAR => Some(s.encounter[BRS_TYPE_SOLAKAR as usize]),
            BRS_TYPE_DRAKKISATH => Some(s.encounter[BRS_TYPE_DRAKKISATH as usize]),
            _ => None,
        }
    }

    /// `instance_blackrock_spire::GetData64` (cpp 760-782). A stored GUID is
    /// returned only when non-empty (the fork returns 0 then).
    pub(crate) fn brs_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        let guid = match field {
            BRS_GO_BLACKROCK_ALTAR => self.blackrock_spire().map(|s| s.blackrock_altar),
            BRS_NPC_LORD_VICTOR_NEFARIUS => self.blackrock_spire().map(|s| s.nefarius),
            BRS_NPC_REND_BLACKHAND => self.blackrock_spire().map(|s| s.rend),
            BRS_NPC_GYTH => self.blackrock_spire().map(|s| s.gyth),
            BRS_NPC_SCARSHIELD_INFILTRATOR => self.blackrock_spire().map(|s| s.infiltrator),
            BRS_GO_GYTH_COMBAT_DOOR => self.blackrock_spire().map(|s| s.gyth_combat_door),
            BRS_NPC_DRAKKISATH => self.blackrock_spire().map(|s| s.drakkisath),
            BRS_NPC_THE_BEAST => self.blackrock_spire().map(|s| s.beast),
            _ => None,
        }?;
        if guid.is_empty() { None } else { Some(guid) }
    }

    /// `instance_blackrock_spire::Save` (cpp 95): returns the cached string
    /// refreshed by `brs_set_data`, not a live recomputation.
    fn brs_save(&self) -> Option<String> {
        self.blackrock_spire().map(|s| s.save_string.clone())
    }

    /// `instance_blackrock_spire::Load` (cpp 721-741).
    fn brs_load(&mut self, data: &str) {
        let mut loaded = [0u32; BRS_MAX_ENCOUNTER];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = BRS_NOT_STARTED;
            }
        }
        if let Some(s) = self.blackrock_spire_mut() {
            s.encounter = loaded;
        }
    }

    /// `instance_blackrock_spire::Update` (cpp 599-695).
    #[allow(clippy::too_many_lines)] // one fork override port
    fn brs_update(&mut self, diff_ms: u32) {
        // `DialogueUpdate(diff_ms)` (cpp 601): no dialogue helper on `Map`
        // (unresolved).
        let stadium_timer = self.blackrock_spire().map_or(0, |s| s.stadium_event_timer);
        if stadium_timer != 0 {
            if stadium_timer <= diff_ms {
                self.brs_send_next_stadium_wave();
            } else if let Some(s) = self.blackrock_spire_mut() {
                s.stadium_event_timer -= diff_ms;
            }
        }
        // UBRS brazier/door sequence (cpp 611-644).
        let (ubrs_timer, ubrs_step) = self
            .blackrock_spire()
            .map_or((0, 0), |s| (s.ubrs_door_timer, s.ubrs_door_step));
        if ubrs_timer != 0 {
            if ubrs_timer <= diff_ms {
                let (b1, b2, b3, b4, b5, b6, door) = self.blackrock_spire().map_or(
                    (
                        ObjectGuid::EMPTY,
                        ObjectGuid::EMPTY,
                        ObjectGuid::EMPTY,
                        ObjectGuid::EMPTY,
                        ObjectGuid::EMPTY,
                        ObjectGuid::EMPTY,
                        ObjectGuid::EMPTY,
                    ),
                    |s| {
                        (
                            s.braziers[0],
                            s.braziers[1],
                            s.braziers[2],
                            s.braziers[3],
                            s.braziers[4],
                            s.braziers[5],
                            s.ubrs_door,
                        )
                    },
                );
                match ubrs_step {
                    0 => {
                        if b1 != ObjectGuid::EMPTY {
                            self.use_door(b1);
                        }
                        if b2 != ObjectGuid::EMPTY {
                            self.use_door(b2);
                        }
                        if let Some(s) = self.blackrock_spire_mut() {
                            s.ubrs_door_timer = 3000;
                            s.ubrs_door_step += 1;
                        }
                    }
                    1 => {
                        if b3 != ObjectGuid::EMPTY {
                            self.use_door(b3);
                        }
                        if b4 != ObjectGuid::EMPTY {
                            self.use_door(b4);
                        }
                        if let Some(s) = self.blackrock_spire_mut() {
                            s.ubrs_door_timer = 3000;
                            s.ubrs_door_step += 1;
                        }
                    }
                    2 => {
                        if b5 != ObjectGuid::EMPTY {
                            self.use_door(b5);
                        }
                        if b6 != ObjectGuid::EMPTY {
                            self.use_door(b6);
                        }
                        if let Some(s) = self.blackrock_spire_mut() {
                            s.ubrs_door_timer = 3000;
                            s.ubrs_door_step += 1;
                        }
                    }
                    _ => {
                        if door != ObjectGuid::EMPTY {
                            self.use_door(door);
                        }
                        if let Some(s) = self.blackrock_spire_mut() {
                            s.ubrs_door_step = 0;
                            s.ubrs_door_timer = 0;
                        }
                    }
                }
            } else if let Some(s) = self.blackrock_spire_mut() {
                s.ubrs_door_timer -= diff_ms;
            }
        }
        // Rookery/Solakar waves while the event runs (cpp 646-694).
        if self.brs_encounter(BRS_TYPE_SOLAKAR as usize) == IN_PROGRESS {
            let (flame_timer, wave_count) = self.blackrock_spire().map_or((0, 0), |s| {
                (s.father_flame_timer, s.father_flame_wave_count)
            });
            if flame_timer <= diff_ms {
                if wave_count == 0 {
                    // First wave is a Rookery Hatcher with a yell (cpp 650-656).
                    if let Some(hatcher) = self.summon_creature(
                        BRS_NPC_ROOKERY_HATCHER,
                        Position::new(55.232_34, -265.751_28, 93.883, 5.0),
                        ObjectGuid::EMPTY,
                        BRS_TEMPSUMMON_DEAD_DESPAWN,
                        3_600_000, // `HOUR * IN_MILLISECONDS` (cpp 652)
                    ) {
                        self.do_script_text(BRS_SAY_ROOKERY_EVENT_START, hatcher, None, -1);
                    }
                    self.summon_creature(
                        BRS_NPC_ROOKERY_HATCHER,
                        Position::new(60.011_333, -263.914_7, 94.022, 5.0),
                        ObjectGuid::EMPTY,
                        BRS_TEMPSUMMON_DEAD_DESPAWN,
                        3_600_000,
                    );
                    let delay = self.spell_rng().irand(30_000, 40_000) as u32;
                    if let Some(s) = self.blackrock_spire_mut() {
                        s.father_flame_timer = delay;
                        s.father_flame_wave_count += 1;
                    }
                } else if wave_count < 5 {
                    // `urand(0, 2)` wave mix (cpp 661-681).
                    let pick = self.spell_rng().irand(0, 2);
                    let guardian = Position::new(55.232_34, -265.751_28, 93.883, 5.0);
                    let hatchery = Position::new(60.011_333, -263.914_7, 94.022, 5.0);
                    match pick {
                        0 => {
                            self.summon_creature(
                                BRS_NPC_ROOKERY_GUARDIAN,
                                guardian,
                                ObjectGuid::EMPTY,
                                BRS_TEMPSUMMON_DEAD_DESPAWN,
                                3_600_000,
                            );
                            self.summon_creature(
                                BRS_NPC_ROOKERY_GUARDIAN,
                                hatchery,
                                ObjectGuid::EMPTY,
                                BRS_TEMPSUMMON_DEAD_DESPAWN,
                                3_600_000,
                            );
                        }
                        1 => {
                            self.summon_creature(
                                BRS_NPC_ROOKERY_HATCHER,
                                guardian,
                                ObjectGuid::EMPTY,
                                BRS_TEMPSUMMON_DEAD_DESPAWN,
                                3_600_000,
                            );
                            self.summon_creature(
                                BRS_NPC_ROOKERY_HATCHER,
                                hatchery,
                                ObjectGuid::EMPTY,
                                BRS_TEMPSUMMON_DEAD_DESPAWN,
                                3_600_000,
                            );
                        }
                        _ => {
                            self.summon_creature(
                                BRS_NPC_ROOKERY_GUARDIAN,
                                guardian,
                                ObjectGuid::EMPTY,
                                BRS_TEMPSUMMON_DEAD_DESPAWN,
                                3_600_000,
                            );
                            self.summon_creature(
                                BRS_NPC_ROOKERY_HATCHER,
                                hatchery,
                                ObjectGuid::EMPTY,
                                BRS_TEMPSUMMON_DEAD_DESPAWN,
                                3_600_000,
                            );
                        }
                    }
                    let delay = self.spell_rng().irand(30_000, 40_000) as u32;
                    if let Some(s) = self.blackrock_spire_mut() {
                        s.father_flame_timer = delay;
                        s.father_flame_wave_count += 1;
                    }
                } else {
                    self.summon_creature(
                        BRS_NPC_SOLAKAR,
                        Position::new(43.768_5, -259.82, 91.648_3, 0.0),
                        ObjectGuid::EMPTY,
                        BRS_TEMPSUMMON_DEAD_DESPAWN,
                        3_600_000,
                    );
                    self.brs_set_data(BRS_TYPE_SOLAKAR, DONE);
                    if let Some(s) = self.blackrock_spire_mut() {
                        s.father_flame_timer = 0;
                    }
                }
            } else if let Some(s) = self.blackrock_spire_mut() {
                s.father_flame_timer -= diff_ms;
            }
        }
    }

    /// `instance_blackrock_spire::DespawnStadiumSpectators` (cpp 518-526).
    fn brs_despawn_stadium_spectators(&mut self) {
        let spectators = self
            .blackrock_spire()
            .map_or(Vec::new(), |s| s.stadium_spectators.clone());
        if let Some(s) = self.blackrock_spire_mut() {
            s.stadium_spectators.clear();
        }
        for guid in spectators {
            self.despawn_creature_now(guid, 0);
        }
    }

    /// `instance_blackrock_spire::DoSendNextStadiumWave` (cpp 528-592).
    #[allow(clippy::cast_precision_loss)] // fork urand jitter
    fn brs_send_next_stadium_wave(&mut self) {
        let waves = self.blackrock_spire().map_or(0, |s| s.stadium_waves);
        match waves.cmp(&BRS_MAX_STADIUM_WAVES) {
            core::cmp::Ordering::Less => {
                let nefarius = self
                    .blackrock_spire()
                    .map_or(ObjectGuid::EMPTY, |s| s.nefarius);
                if !nefarius.is_empty() {
                    let mut first: Option<ObjectGuid> = None;
                    let mut spawned = 0u32;
                    for entry in BRS_STADIUM_EVENT_NPCS[waves as usize] {
                        if entry == 0 {
                            continue;
                        }
                        // `GetRandomPoint(..., 7.0f)` + x clamp (cpp 542-543):
                        // no random-point helper; `irand` jitter approximates.
                        let jx = self.spell_rng().irand(-70, 70) as f32 / 10.0;
                        let jy = self.spell_rng().irand(-70, 70) as f32 / 10.0;
                        let at = Position::new(
                            (BRS_STADIUM_LOCS[0][0] + jx).min(BRS_STADIUM_LOCS[0][0]),
                            BRS_STADIUM_LOCS[0][1] + jy,
                            BRS_STADIUM_LOCS[0][2],
                            0.0,
                        );
                        if let Some(mob) = self.summon_creature(
                            entry,
                            at,
                            nefarius,
                            BRS_TEMPSUMMON_DEAD_DESPAWN,
                            0,
                        ) {
                            if first.is_none() {
                                first = Some(mob);
                            }
                            // `JoinCreatureGroup` (cpp 549): no group helper
                            // (unresolved).
                            spawned += 1;
                        }
                    }
                    if let Some(leader) = first {
                        // `MoveWaypoint(0, PATH_FROM_SPECIAL, 0, 0,
                        // WAYPOINT_ID_STADIUM, true)` (cpp 555): the explicit
                        // path id has no helper; the DB waypoint lookup by entry
                        // (10442 == WAYPOINT_ID_STADIUM) approximates.
                        self.creature_move_waypoint(leader, 0, true);
                    }
                    if let Some(s) = self.blackrock_spire_mut() {
                        s.stadium_mobs_alive += spawned;
                    }
                }
                // Fires even when Nefarius is gone (cpp 558 sits outside the
                // `GetCreature` gate).
                let combat_door = self
                    .blackrock_spire()
                    .map_or(ObjectGuid::EMPTY, |s| s.gyth_combat_door);
                if combat_door != ObjectGuid::EMPTY {
                    self.use_door(combat_door);
                }
            }
            core::cmp::Ordering::Equal => {
                // `StartNextDialogueText(SAY_NEFARIUS_LOSE1)` (cpp 562):
                // no dialogue helper on `Map` (unresolved).
            }
            core::cmp::Ordering::Greater => {
                // Send Gyth (cpp 564-583).
                let nefarius = self
                    .blackrock_spire()
                    .map_or(ObjectGuid::EMPTY, |s| s.nefarius);
                if !nefarius.is_empty() {
                    // Stop Nefarius and put him back in place (cpp 569-570).
                    self.creature_move_idle(nefarius);
                    let back = Position::new(
                        BRS_STADIUM_LOCS[5][0],
                        BRS_STADIUM_LOCS[5][1],
                        BRS_STADIUM_LOCS[5][2],
                        0.0,
                    );
                    self.creature_move_point(nefarius, 0, back, 0, 0.0, BRS_STADIUM_LOCS[5][3]);
                    if let Some(gyth) = self.summon_creature(
                        BRS_NPC_GYTH,
                        Position::new(
                            BRS_STADIUM_LOCS[1][0],
                            BRS_STADIUM_LOCS[1][1],
                            BRS_STADIUM_LOCS[1][2],
                            0.0,
                        ),
                        nefarius,
                        BRS_TEMPSUMMON_DEAD_DESPAWN,
                        0,
                    ) {
                        self.set_walk(gyth, false);
                        self.creature_move_waypoint(gyth, 0, true);
                    }
                }
                // Set to 2, because Rend will be summoned later during the fight
                // (cpp 580).
                if let Some(s) = self.blackrock_spire_mut() {
                    s.stadium_mobs_alive = 2;
                }
                let combat_door = self
                    .blackrock_spire()
                    .map_or(ObjectGuid::EMPTY, |s| s.gyth_combat_door);
                if combat_door != ObjectGuid::EMPTY {
                    self.use_door(combat_door);
                }
            }
        }
        if let Some(s) = self.blackrock_spire_mut() {
            s.stadium_waves += 1;
            // Stop the timer when all the waves have been sent (cpp 588-591).
            if s.stadium_waves >= BRS_MAX_STADIUM_WAVES {
                s.stadium_event_timer = 0;
            } else {
                s.stadium_event_timer = 60_000;
            }
        }
    }

    /// `instance_blackrock_spire::DoSortRoomEventMobs` (cpp 784-810).
    /// Called from the LBRS areatrigger (cpp 824); no areatrigger dispatcher
    /// exists on `Map`, so the integrator wires this with that trigger.
    pub fn brs_sort_room_event_mobs(&mut self) {
        if self.brs_encounter(BRS_TYPE_ROOM_EVENT as usize) != BRS_NOT_STARTED {
            return;
        }
        for i in 0..BRS_MAX_ROOMS {
            let rune = self
                .blackrock_spire()
                .map_or(ObjectGuid::EMPTY, |s| s.room_runes[i]);
            if rune.is_empty() {
                continue;
            }
            let Some(rune_pos) = self.object_position(rune) else {
                continue;
            };
            let mobs = self
                .blackrock_spire()
                .map_or(Vec::new(), |s| s.room_event_mobs.clone());
            let mut sorted = Vec::new();
            for guid in mobs {
                let alive = self.creatures.get(&guid).is_some_and(|c| c.unit.is_alive());
                if !alive {
                    continue;
                }
                let close = self
                    .object_position(guid)
                    .is_some_and(|pos| crate::visibility::dist3d(pos, rune_pos) <= 10.0);
                if close {
                    sorted.push(guid);
                }
            }
            if let Some(s) = self.blackrock_spire_mut() {
                s.room_mobs_sorted[i] = sorted;
            }
        }
        self.brs_set_data(BRS_TYPE_ROOM_EVENT, IN_PROGRESS);
    }

    /// `instance_blackrock_spire::JustDidDialogueStep` (cpp 462-516). The
    /// `DialogueHelper` sequencing (`StartNextDialogueText`,
    /// `DialogueUpdate`) has no `Map` equivalent, so this runs only when a
    /// dialogue dispatcher is added (unresolved); every reachable movement /
    /// summon op inside is transcribed.
    #[allow(clippy::cast_possible_wrap)] // fork dialogue entry space
    pub fn brs_just_did_dialogue_step(&mut self, entry: i32) {
        if entry == BRS_NPC_BLACKHAND_HANDLER as i32 {
            if let Some(s) = self.blackrock_spire_mut() {
                s.stadium_event_timer = 1000;
            }
            // `pRend->SetFacingTo(...)` (cpp 470): no facing helper
            // (unresolved).
            let nefarius = self
                .blackrock_spire()
                .map_or(ObjectGuid::EMPTY, |s| s.nefarius);
            if !nefarius.is_empty() {
                let balcony = Position::new(
                    BRS_STADIUM_LOCS[5][0],
                    BRS_STADIUM_LOCS[5][1],
                    BRS_STADIUM_LOCS[5][2],
                    0.0,
                );
                self.creature_move_point(nefarius, 0, balcony, 0, 0.0, BRS_STADIUM_LOCS[5][3]);
                // Summon the spectators and move them to the western balcony
                // (cpp 475-486).
                for i in 0..12usize {
                    let at = Position::new(
                        BRS_SPECTATOR_SPAWNS[i][0],
                        BRS_SPECTATOR_SPAWNS[i][1],
                        BRS_SPECTATOR_SPAWNS[i][2],
                        BRS_SPECTATOR_SPAWNS[i][3],
                    );
                    if let Some(spec) = self.summon_creature(
                        BRS_SPECTATOR_ENTRIES[i],
                        at,
                        nefarius,
                        BRS_TEMPSUMMON_DEAD_DESPAWN,
                        0,
                    ) {
                        // `SetDetectionDistance(1.0f)` /
                        // `SetNoCallAssistance(true)` (cpp 479-480): no
                        // helpers (unresolved).
                        self.set_walk(spec, false);
                        // `SetHomePosition` (cpp 482): orientation copied
                        // exactly, fork passes it explicitly.
                        let home = Position::new(
                            BRS_SPECTATOR_TARGETS[i][0],
                            BRS_SPECTATOR_TARGETS[i][1],
                            BRS_SPECTATOR_TARGETS[i][2],
                            BRS_SPECTATOR_TARGETS[i][3],
                        );
                        if let Some(c) = self.creatures.get_mut(&spec) {
                            c.home_position = home;
                        }
                        self.creature_move_point(
                            spec,
                            0,
                            home,
                            0,
                            0.0,
                            BRS_SPECTATOR_TARGETS[i][3],
                        );
                        if let Some(s) = self.blackrock_spire_mut() {
                            s.stadium_spectators.push(spec);
                        }
                    }
                }
            }
        } else if entry == BRS_SAY_NEFARIUS_WARCHIEF {
            // Prepare for Gyth (cpp 489-498).
            let rend = self.blackrock_spire().map_or(ObjectGuid::EMPTY, |s| s.rend);
            if !rend.is_empty() {
                // `ForcedDespawn(5000)` delay has no helper (precedent:
                // immediate `despawn_creature_now`); move first so the walk
                // out is still issued before removal.
                self.set_walk(rend, false);
                let out = Position::new(
                    BRS_STADIUM_LOCS[6][0],
                    BRS_STADIUM_LOCS[6][1],
                    BRS_STADIUM_LOCS[6][2],
                    0.0,
                );
                // Fork passes no orientation (cpp 495); -10.0 keeps facing
                // (`motion.rs`: only `> -7.0` applies one).
                self.creature_move_point(rend, 0, out, 0, 0.0, -10.0);
                self.despawn_creature_now(rend, u32::MAX);
            }
            if let Some(s) = self.blackrock_spire_mut() {
                s.stadium_event_timer = 30_000;
            }
        } else if entry == BRS_SAY_NEFARIUS_PACING {
            // Nefarius walks back and forth while Rend prepares Gyth
            // (cpp 500-503).
            let nefarius = self
                .blackrock_spire()
                .map_or(ObjectGuid::EMPTY, |s| s.nefarius);
            if !nefarius.is_empty() {
                self.creature_move_waypoint(nefarius, 0, true);
            }
        } else if entry == BRS_SAY_NEFARIUS_VICTORY {
            self.brs_set_data(BRS_TYPE_STADIUM, DONE);
        } else if entry == BRS_NPC_REND_BLACKHAND as i32 {
            // Despawn Nefarius (cpp 507-514).
            let nefarius = self
                .blackrock_spire()
                .map_or(ObjectGuid::EMPTY, |s| s.nefarius);
            if !nefarius.is_empty() {
                let out = Position::new(
                    BRS_STADIUM_LOCS[6][0],
                    BRS_STADIUM_LOCS[6][1],
                    BRS_STADIUM_LOCS[6][2],
                    0.0,
                );
                self.creature_move_point(nefarius, 0, out, 0, 0.0, -10.0);
                self.despawn_creature_now(nefarius, u32::MAX);
            }
        }
    }

    /// `instance_blackrock_spire::GetSpeakerByEntry` (cpp 449-460). Same
    /// dialogue-dispatcher caveat as `brs_just_did_dialogue_step`; the fork
    /// returns null for unknown entries or missing creatures.
    #[must_use]
    pub fn brs_speaker_for_entry(&self, entry: u32) -> Option<ObjectGuid> {
        let guid = match entry {
            BRS_NPC_LORD_VICTOR_NEFARIUS => self.blackrock_spire().map(|s| s.nefarius),
            BRS_NPC_REND_BLACKHAND => self.blackrock_spire().map(|s| s.rend),
            _ => None,
        }?;
        if guid.is_empty() { None } else { Some(guid) }
    }

    // ------------------------------------------------ instance: temple of ahnqiraj

    fn aq40_encounter(&self, index: usize) -> u32 {
        self.temple_of_ahnqiraj()
            .and_then(|s| s.encounter.get(index).copied())
            .unwrap_or(0)
    }

    /// `instance_temple_of_ahnqiraj::OnCreatureCreate`
    /// (cpp 252-295). The fork caches boss GUIDs in
    /// `m_mNpcEntryGuidStore` for boss scripts; those arms
    /// are dropped here (re-resolved with
    /// `find_creature_by_entry`, Deadmines precedent).
    /// Ends with the fork's own `OnCreatureRespawn` tail
    /// call (cpp 293-294).
    fn aq40_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            AQ40_NPC_SARTURA_S_ROYAL_GUARD => {
                if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    if !s.royal_guards.contains(&guid) {
                        s.royal_guards.push(guid);
                    }
                }
            }
            AQ40_NPC_CAELESTRASZ => {
                let flags = self.object_get_field(guid, offsets::UNIT_NPC_FLAGS);
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::UNIT_NPC_FLAGS),
                    flags | AQ40_UNIT_NPC_FLAG_GOSSIP,
                );
            }
            _ => {}
        }
        // `QIRAJI_SLAYER` / `QIRAJI_MINDSLAYER` entry
        // randomization (cpp 269-285) needs
        // `SetEntry`/`UpdateEntry`/`AIM_Initialize`: no
        // `Map` helper (see unresolved notes).
        self.aq40_handle_respawn(guid);
    }

    /// `instance_temple_of_ahnqiraj::OnCreatureRespawn`
    /// (cpp 195-250). No respawn dispatcher exists on
    /// `Map`, so only the fork's tail call from
    /// `OnCreatureCreate` is wired; standalone respawn
    /// events are unwired (see unresolved notes).
    /// Removals use `despawn_creature_now(guid, u32::MAX)`
    /// (Zul'Gurub precedent: the fork re-removes on every
    /// respawn; steady state is identical).
    fn aq40_handle_respawn(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        // Skeram trash (cpp 199-202) gates on
        // `TYPE_SKERAM`; twins trash (cpp 223-227) on
        // `TYPE_TWINS`; C'thun trash (cpp 233-239) on
        // `TYPE_CTHUN`.
        let done_gated = matches!(
            entry,
            AQ40_NPC_ANUBISATH_SENTINEL | AQ40_NPC_OBSIDIAN_ERADICATOR
        ) && self.aq40_encounter(AQ40_TYPE_SKERAM as usize) == DONE
            || matches!(
                entry,
                AQ40_NPC_ANUBISATH_DEFENDER | AQ40_NPC_QIRAJI_SCARAB | AQ40_NPC_QIRAJI_SCORPION
            ) && self.aq40_encounter(AQ40_TYPE_TWINS as usize) == DONE
            || matches!(
                entry,
                AQ40_NPC_QIRAJI_MINDSLAYER
                    | AQ40_NPC_QIRAJI_SLAYER
                    | AQ40_NPC_QIRAJI_CHAMPION
                    | AQ40_NPC_ANUBISATH_WARDER
                    | AQ40_NPC_OBSIDIAN_NULLIFIER
            ) && self.aq40_encounter(AQ40_TYPE_CTHUN as usize) == DONE;
        if done_gated {
            self.despawn_creature_now(guid, u32::MAX);
            return;
        }
        // Sartura trash (cpp 204-210) gates on
        // `TYPE_SARTURA`; Huhuran trash (cpp 214-221) on
        // `TYPE_HUHURAN`; Fankriss trash (cpp 211-213) on
        // `TYPE_FANKRISS`.
        let sartura_trash = matches!(
            entry,
            AQ40_NPC_QIRAJI_BRAINWASHER
                | AQ40_NPC_VEKNISS_GUARDIAN
                | AQ40_NPC_VEKNISS_WARRIOR
                | AQ40_NPC_SARTURA_S_ROYAL_GUARD
        ) && self.aq40_encounter(AQ40_TYPE_SARTURA as usize) == DONE;
        let huhuran_trash = matches!(
            entry,
            AQ40_NPC_VEKNISS_DRONE
                | AQ40_NPC_VEKNISS_SOLDIER
                | AQ40_NPC_VEKNISS_HIVE_CRAWLER
                | AQ40_NPC_VEKNISS_WASP
                | AQ40_NPC_QIRAJI_LASHER
                | AQ40_NPC_VEKNISS_STINGER
        ) && self.aq40_encounter(AQ40_TYPE_HUHURAN as usize) == DONE;
        let fankriss_trash = matches!(entry, AQ40_NPC_VEKNISS_DRONE | AQ40_NPC_VEKNISS_SOLDIER)
            && self.aq40_encounter(AQ40_TYPE_FANKRISS as usize) == DONE;
        if sartura_trash || huhuran_trash || fankriss_trash {
            self.despawn_creature_now(guid, u32::MAX);
            return;
        }
        // Outro gates: ouro scarabs while Ouro is not in
        // progress (cpp 229-232); the Master's Eye once
        // the twins intro ran (cpp 241-248).
        if entry == AQ40_NPC_OURO_SCARAB
            && self.aq40_encounter(AQ40_TYPE_OURO as usize) != IN_PROGRESS
        {
            self.despawn_creature_now(guid, u32::MAX);
            return;
        }
        if entry == AQ40_NPC_MASTERS_EYE
            && self
                .temple_of_ahnqiraj()
                .is_some_and(|s| s.twins_intro_done)
        {
            self.despawn_creature_now(guid, u32::MAX);
        }
    }

    /// `instance_temple_of_ahnqiraj::OnObjectCreate`
    /// (cpp 166-193). Door GUIDs are re-resolved with
    /// `find_gameobject` at use sites (Deadmines
    /// precedent); only the grasp list is stored.
    fn aq40_on_object_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            AQ40_GO_SKERAM_GATE => {
                if self.aq40_encounter(AQ40_TYPE_SKERAM as usize) == DONE {
                    self.use_door(guid);
                }
            }
            AQ40_GO_TWINS_ENTER_DOOR => {
                if self.aq40_encounter(AQ40_TYPE_HUHURAN as usize) == DONE {
                    self.use_door(guid);
                }
            }
            AQ40_GO_TWINS_EXIT_DOOR => {
                if self.aq40_encounter(AQ40_TYPE_TWINS as usize) == DONE {
                    self.use_door(guid);
                }
            }
            AQ40_GO_GRASP_OF_CTHUN => {
                if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    if !s.grasps_of_cthun.contains(&guid) {
                        s.grasps_of_cthun.push(guid);
                    }
                }
                if self.aq40_encounter(AQ40_TYPE_CTHUN as usize) == DONE {
                    self.hidden_objects.insert(guid);
                }
            }
            _ => {}
        }
    }

    /// `instance_temple_of_ahnqiraj::SetData` (cpp 297-390).
    fn aq40_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            AQ40_TYPE_SKERAM => {
                if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    s.encounter[AQ40_TYPE_SKERAM as usize] = data;
                }
                if data == DONE
                    && let Some(gate) = self.find_gameobject(AQ40_GO_SKERAM_GATE, None)
                {
                    self.use_door(gate);
                }
            }
            AQ40_TYPE_BUG_TRIO => {
                // `SPECIAL` counts one twin death without
                // storing (cpp 309-317); the third
                // re-enters here as `DONE`.
                if data == AQ40_SPECIAL {
                    let deaths = self.temple_of_ahnqiraj_mut().map_or(0, |s| {
                        s.bug_trio_death_count += 1;
                        s.bug_trio_death_count
                    });
                    if deaths >= 3 {
                        self.aq40_set_data(AQ40_TYPE_BUG_TRIO, DONE);
                    }
                    return true;
                }
                if data == IN_PROGRESS
                    && let Some(s) = self.temple_of_ahnqiraj_mut()
                {
                    s.bug_trio_death_count = 0;
                }
                if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    s.encounter[AQ40_TYPE_BUG_TRIO as usize] = data;
                }
            }
            AQ40_TYPE_SARTURA | AQ40_TYPE_FANKRISS | AQ40_TYPE_VISCIDUS => {
                if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    s.encounter[field as usize] = data;
                }
            }
            AQ40_TYPE_HUHURAN => {
                if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    s.encounter[AQ40_TYPE_HUHURAN as usize] = data;
                }
                if data == DONE
                    && let Some(door) = self.find_gameobject(AQ40_GO_TWINS_ENTER_DOOR, None)
                {
                    self.use_door(door);
                }
            }
            AQ40_TYPE_TWINS => {
                // Either twin writes; a repeat write is a
                // no-op so the door/death-dialogue arms run
                // once (cpp 336-338).
                if self.aq40_encounter(AQ40_TYPE_TWINS as usize) == data {
                    return true;
                }
                if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    s.encounter[AQ40_TYPE_TWINS as usize] = data;
                }
                if data != IN_PROGRESS
                    && let Some(door) = self.find_gameobject(AQ40_GO_TWINS_ENTER_DOOR, None)
                {
                    self.use_door(door);
                }
                if data == DONE {
                    if let Some(door) = self.find_gameobject(AQ40_GO_TWINS_EXIT_DOOR, None) {
                        self.use_door(door);
                    }
                    // `m_twinsDeadDialogue.StartNextDialogueText`
                    // (cpp 353): no dialogue helper on `Map`
                    // (see unresolved notes).
                }
            }
            AQ40_TYPE_OURO => {
                if data == AQ40_FAIL {
                    // Fork `Respawn()`s the Ouro spawner
                    // (cpp 359-363): no creature-respawn
                    // helper on `Map` (NEEDS-MAP-HELPER).
                    let _spawner = self.find_creature_by_entry(AQ40_NPC_OURO_SPAWNER);
                }
                if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    s.encounter[AQ40_TYPE_OURO as usize] = data;
                }
            }
            AQ40_TYPE_CTHUN => {
                if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    s.encounter[AQ40_TYPE_CTHUN as usize] = data;
                }
                // Fork `SetVisible(uiData != DONE)`
                // (cpp 367-374) rides `hidden_objects`
                // (gameobject precedent: WC chest).
                let grasps = self
                    .temple_of_ahnqiraj()
                    .map_or(Vec::new(), |s| s.grasps_of_cthun.clone());
                for grasp in grasps {
                    if data == DONE {
                        self.hidden_objects.insert(grasp);
                    } else {
                        self.hidden_objects.remove(&grasp);
                    }
                }
            }
            _ => return false,
        }
        // Save refresh on ANY field set `DONE`, streaming
        // the whole encounter array with a trailing space
        // (fork `ostringstream` shape, cpp 377-389); the
        // base returns cached `strInstData`, so no live
        // recompute here.
        if data == DONE
            && let Some(s) = self.temple_of_ahnqiraj_mut()
        {
            let e = s.encounter;
            s.save_string = format!(
                "{} {} {} {} {} {} {} {} {} {} ",
                e[0], e[1], e[2], e[3], e[4], e[5], e[6], e[7], e[8], e[9]
            );
        }
        true
    }

    /// `instance_temple_of_ahnqiraj::GetData` (cpp 516).
    /// Bounds-guarded (no panics on wild `uiType`).
    fn aq40_get_data(&self, field: u32) -> Option<u32> {
        self.temple_of_ahnqiraj()
            .and_then(|s| s.encounter.get(field as usize).copied())
    }

    /// `instance_temple_of_ahnqiraj::CheckConditionCriteriaMeet`
    /// (cpp 518-524).
    fn aq40_check_condition(&self, _map_id: u32, condition_id: u32) -> bool {
        if condition_id as usize >= AQ40_MAX_ENCOUNTER {
            return false;
        }
        self.aq40_encounter(condition_id as usize) == DONE
    }

    /// `instance_temple_of_ahnqiraj::IsEncounterInProgress`
    /// (cpp 137-146).
    fn aq40_is_encounter_in_progress(&self) -> bool {
        self.temple_of_ahnqiraj().is_some_and(|s| {
            s.encounter
                .iter()
                .any(|&v| v == IN_PROGRESS || v == AQ40_SPECIAL)
        })
    }

    /// `instance_temple_of_ahnqiraj::Save` (cpp 144):
    /// returns the cached string.
    fn aq40_save(&self) -> Option<String> {
        self.temple_of_ahnqiraj().map(|s| s.save_string.clone())
    }

    /// `instance_temple_of_ahnqiraj::Load` (cpp 392-423).
    fn aq40_load(&mut self, data: &str) {
        let mut loaded = [0u32; AQ40_MAX_ENCOUNTER];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = 0; // NOT_STARTED
            }
        }
        if let Some(s) = self.temple_of_ahnqiraj_mut() {
            s.encounter = loaded;
            if s.encounter[AQ40_TYPE_TWINS as usize] == DONE {
                s.twins_intro_done = true;
            }
            if s.encounter[AQ40_TYPE_OURO as usize] != DONE {
                s.restore_ouro_timer_ms = 3000;
            }
        }
    }

    /// `instance_temple_of_ahnqiraj::Update` (cpp 491-512).
    /// Dialogue ticks (cpp 493-494) need the fork
    /// `DialogueHelper`: no `Map` helper (see unresolved
    /// notes).
    fn aq40_update(&mut self, diff_ms: u32) {
        self.aq40_update_cthun_whisper(diff_ms);
        self.aq40_update_stomach(diff_ms);
        let timer = self
            .temple_of_ahnqiraj()
            .map_or(0, |s| s.restore_ouro_timer_ms);
        if timer != 0 {
            if timer < diff_ms {
                self.aq40_restore_ouro_spawn_trigger();
            } else if let Some(s) = self.temple_of_ahnqiraj_mut() {
                s.restore_ouro_timer_ms -= diff_ms;
            }
        }
    }

    /// `instance_temple_of_ahnqiraj::UpdateCThunWhisper`
    /// (cpp 425-489). The charm-cast `ToDo` (cpp 485)
    /// needs research: only the whisper text is sent.
    #[allow(clippy::cast_possible_wrap, clippy::cast_possible_truncation)]
    fn aq40_update_cthun_whisper(&mut self, diff_ms: u32) {
        if self.aq40_encounter(AQ40_TYPE_CTHUN as usize) == DONE {
            return;
        }
        let timer = self
            .temple_of_ahnqiraj()
            .map_or(0, |s| s.cthun_whisper_timer_ms);
        if timer >= diff_ms {
            if let Some(s) = self.temple_of_ahnqiraj_mut() {
                s.cthun_whisper_timer_ms -= diff_ms;
            }
            return;
        }
        let next = self.spell_rng().irand(
            AQ40_CTHUN_WHISPER_FREQ_MIN as i32,
            AQ40_CTHUN_WHISPER_FREQ_MAX as i32,
        ) as u32;
        if let Some(s) = self.temple_of_ahnqiraj_mut() {
            s.cthun_whisper_timer_ms = next;
        }
        // Decay mute entries (cpp 439-448).
        if let Some(s) = self.temple_of_ahnqiraj_mut() {
            let prev = s.cthun_prev_whisper_timer_ms;
            let mut i = 0;
            while i < s.cthun_whisper_mutes.len() {
                let left = s.cthun_whisper_mutes[i].1;
                let decayed = left.saturating_sub(prev.min(left));
                if decayed < AQ40_CTHUN_WHISPER_FREQ_MAX {
                    s.cthun_whisper_mutes.remove(i);
                } else {
                    s.cthun_whisper_mutes[i].1 = decayed;
                    i += 1;
                }
            }
            s.cthun_prev_whisper_timer_ms = s.cthun_whisper_timer_ms;
        }
        if self.aq40_encounter(AQ40_TYPE_CTHUN as usize) == IN_PROGRESS {
            return;
        }
        let Some(cthun) = self.find_creature_by_entry(AQ40_NPC_CTHUN) else {
            return;
        };
        if self.players.is_empty() {
            return;
        }
        // Alive, unmuted players (fork checks only
        // `!IsDead`, cpp 469).
        let mutes: Vec<ObjectGuid> = self.temple_of_ahnqiraj().map_or(Vec::new(), |s| {
            s.cthun_whisper_mutes.iter().map(|&(g, _)| g).collect()
        });
        let candidates: Vec<ObjectGuid> = self
            .players
            .keys()
            .copied()
            .filter(|p| self.unit_is_alive(*p) && !mutes.contains(p))
            .collect();
        if candidates.is_empty() {
            return;
        }
        let pick = self.spell_rng().irand(0, candidates.len() as i32 - 1) as usize;
        let target = candidates[pick];
        let whisper = self
            .spell_rng()
            .irand(AQ40_SAY_CTHUN_WHISPER_8, AQ40_SAY_CTHUN_WHISPER_1);
        self.do_script_text(whisper, cthun, Some(target), -1);
        if let Some(s) = self.temple_of_ahnqiraj_mut() {
            s.cthun_whisper_mutes
                .push((target, AQ40_CTHUN_WHISPER_MUTE_DURATION));
        }
    }

    /// `instance_temple_of_ahnqiraj::DoHandleTempleAreaTrigger`
    /// (cpp 148-164). Called from `at_temple_ahnqiraj`;
    /// no area-trigger dispatcher exists on `Map`, so the
    /// wiring is left to the integrator. The twins intro
    /// dialogue `Start()` (cpp 155) has no helper: the
    /// once-flag is set directly.
    pub fn aq40_handle_temple_area_trigger(&mut self, trigger_id: u32) {
        if trigger_id == AQ40_AREATRIGGER_TWIN_EMPERORS
            && !self.aq40_twins_dialogue_started_or_done()
        {
            // `m_twinsIntroDialogue.Start()` needs the
            // fork `DialogueHelper` (see unresolved notes).
            if let Some(s) = self.temple_of_ahnqiraj_mut() {
                s.twins_intro_done = true;
            }
        } else if trigger_id == AQ40_AREATRIGGER_SARTURA {
            let state = self.aq40_encounter(AQ40_TYPE_SARTURA as usize);
            if (state == AQ40_NOT_STARTED || state == AQ40_FAIL)
                && let Some(sartura) = self.find_creature_by_entry(AQ40_NPC_BATTLEGUARD_SARTURA)
            {
                self.set_in_combat_with_zone(sartura);
            }
        }
    }

    /// `TwinsDialogueStartedOrDone` (cpp 514), read by
    /// `boss_twinemperors`.
    #[must_use]
    pub fn aq40_twins_dialogue_started_or_done(&self) -> bool {
        self.temple_of_ahnqiraj()
            .is_some_and(|s| s.twins_intro_done)
    }

    /// `GetRoyalGuardGUIDList` (header 142), read by
    /// `boss_sartura` leash handling.
    #[must_use]
    pub fn aq40_royal_guard_guids(&self) -> Vec<ObjectGuid> {
        self.temple_of_ahnqiraj()
            .map_or(Vec::new(), |s| s.royal_guards.clone())
    }

    /// `instance_temple_of_ahnqiraj::AddPlayerToStomach`
    /// (cpp 542-547), called from `boss_cthun`.
    pub fn aq40_add_player_to_stomach(&mut self, player: ObjectGuid) {
        if let Some(cthun) = self.find_creature_by_entry(AQ40_NPC_CTHUN) {
            let _ = self.cast_spell(
                cthun,
                AQ40_SPELL_DIGESTIVE_ACID,
                CastTarget::Unit(player),
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
        if let Some(s) = self.temple_of_ahnqiraj_mut() {
            s.players_in_stomach.push((
                player,
                Aq40StomachTimers {
                    acid_debuff_ms: AQ40_STOMACH_ACID_REFRESH_RATE,
                    since_ported_from_ms: 0,
                    since_ported_to_ms: 0,
                    did_knockback: false,
                },
            ));
        }
    }

    /// `instance_temple_of_ahnqiraj::PlayerInStomach`
    /// (cpp 598-604), read by `boss_cthun`.
    #[must_use]
    pub fn aq40_player_in_stomach(&self, unit: ObjectGuid) -> bool {
        self.temple_of_ahnqiraj()
            .is_some_and(|s| s.players_in_stomach.iter().any(|&(g, _)| g == unit))
    }

    /// `instance_temple_of_ahnqiraj::TeleportPlayerToCThun`
    /// (cpp 557-574). No area-trigger table exists on
    /// `Map`, so the fork's own hardcoded fallback
    /// coordinates are used.
    fn aq40_teleport_player_to_cthun(&mut self, player: ObjectGuid) {
        let facing = self.object_position(player).map_or(0.0, |p| p.o);
        let angle = self.spell_rng().frand01() * 2.0 * core::f32::consts::PI;
        let at = Position::new(
            -8578.0 + angle.cos() * 0.1,
            1986.8 + angle.sin() * 0.1,
            100.4,
            facing,
        );
        self.teleport_player_in_map(player, at);
    }

    /// `instance_temple_of_ahnqiraj::PerformCthunKnockback`
    /// (cpp 576-596). Same hardcoded-fallback rule as the
    /// teleport above.
    fn aq40_perform_cthun_knockback(&mut self) {
        let at = Position::new(-8578.0, 1986.8, 100.22, 0.0);
        if let Some(summoned) = self.summon_creature(
            AQ40_EXIT_KNOCKBACK_CREATURE,
            at,
            ObjectGuid::EMPTY,
            AQ40_TEMPSUMMON_TIMED_DESPAWN,
            1000,
        ) {
            let _ = self.cast_spell(
                summoned,
                AQ40_SPELL_EXIT_STOMACH_KNOCKBACK,
                CastTarget::Unit(summoned),
                CastOptions {
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
    }

    /// `instance_temple_of_ahnqiraj::HandleStomachTriggers`
    /// (cpp 606-647). Called from `at_temple_ahnqiraj`
    /// with the trigger's id + position (no area-trigger
    /// lookup exists on `Map`); unwired like the temple
    /// handler above.
    pub fn aq40_handle_stomach_trigger(
        &mut self,
        player: ObjectGuid,
        trigger_id: u32,
        x: f32,
        y: f32,
        z: f32,
    ) {
        if trigger_id == AQ40_AREATRIGGER_STOMACH_GROUND {
            let punt = self
                .temple_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.punt_creature);
            if punt == ObjectGuid::EMPTY
                && let Some(summoned) = self.summon_creature(
                    AQ40_PUNT_CREATURE,
                    Position::new(x, y, z, 0.0),
                    ObjectGuid::EMPTY,
                    AQ40_TEMPSUMMON_TIMED_DESPAWN,
                    4000,
                )
            {
                if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    s.punt_creature = summoned;
                    s.quake_timer_ms = 1000;
                    s.punt_countdown_ms = AQ40_STOMACH_PUNT_CAST_TIME;
                }
                // Fork sends only the visual (cpp 623).
                self.send_spell_go_simple(summoned, AQ40_SPELL_QUAKE, summoned, 0);
            }
        } else if trigger_id == AQ40_AREATRIGGER_STOMACH_AIR {
            self.aq40_teleport_player_to_cthun(player);
        } else if trigger_id == AQ40_AREATRIGGER_CTHUN_KNOCKBACK
            && self.aq40_encounter(AQ40_TYPE_CTHUN as usize) != DONE
        {
            self.aq40_perform_cthun_knockback();
            if let Some(s) = self.temple_of_ahnqiraj_mut()
                && let Some((_, timers)) =
                    s.players_in_stomach.iter_mut().find(|(g, _)| *g == player)
            {
                timers.did_knockback = true;
            }
        }
    }

    /// `instance_temple_of_ahnqiraj::KillPlayersInStomach`
    /// (cpp 649-675), called from `boss_cthun`. The
    /// god-mode carve-out (cpp 656-660) has no
    /// `Map` reader: everyone listed is killed.
    pub fn aq40_kill_players_in_stomach(&mut self) -> bool {
        loop {
            let len = self
                .temple_of_ahnqiraj()
                .map_or(0, |s| s.players_in_stomach.len());
            if len == 0 {
                break;
            }
            let guid = self
                .temple_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.players_in_stomach[0].0);
            if self.players.contains_key(&guid) {
                if self.unit_is_alive(guid) {
                    self.kill_unit(guid, None);
                }
                if self
                    .aura_holders(guid)
                    .iter()
                    .any(|h| h.spell_id == AQ40_SPELL_DIGESTIVE_ACID)
                {
                    self.remove_auras_due_to_spell(guid, AQ40_SPELL_DIGESTIVE_ACID);
                }
            }
            if let Some(s) = self.temple_of_ahnqiraj_mut() {
                s.players_in_stomach.remove(0);
            }
        }
        true
    }

    /// `instance_temple_of_ahnqiraj::UpdateStomachOfCthun`
    /// (cpp 677-792). The air-trigger proximity hack
    /// (cpp 776-787) needs the area-trigger table plus
    /// launch/fall state: no `Map` helpers (see
    /// unresolved notes).
    #[allow(clippy::too_many_lines)]
    fn aq40_update_stomach(&mut self, diff_ms: u32) {
        let punt = self
            .temple_of_ahnqiraj()
            .map_or(ObjectGuid::EMPTY, |s| s.punt_creature);
        if punt != ObjectGuid::EMPTY && self.creatures.contains_key(&punt) {
            let (quake, countdown) = self
                .temple_of_ahnqiraj()
                .map_or((0, 0), |s| (s.quake_timer_ms, s.punt_countdown_ms));
            if quake < diff_ms {
                self.send_spell_go_simple(punt, AQ40_SPELL_QUAKE, punt, 0);
                if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    s.quake_timer_ms = 1000;
                }
            } else if let Some(s) = self.temple_of_ahnqiraj_mut() {
                s.quake_timer_ms -= diff_ms;
            }
            if countdown < diff_ms {
                let _ = self.cast_spell(
                    punt,
                    AQ40_SPELL_PUNT_UPWARD,
                    CastTarget::Unit(punt),
                    CastOptions {
                        triggered: true,
                        skip_known: true,
                        ..Default::default()
                    },
                );
                if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    s.punt_countdown_ms = u32::MAX;
                    s.punt_creature = ObjectGuid::EMPTY;
                }
            } else if let Some(s) = self.temple_of_ahnqiraj_mut() {
                s.punt_countdown_ms -= diff_ms;
            }
        } else if let Some(s) = self.temple_of_ahnqiraj_mut() {
            s.punt_creature = ObjectGuid::EMPTY;
        }
        let empty = self
            .temple_of_ahnqiraj()
            .is_none_or(|s| s.players_in_stomach.is_empty());
        if empty {
            return;
        }
        let cthun = self.find_creature_by_entry(AQ40_NPC_CTHUN);
        let mut i = 0;
        loop {
            let len = self
                .temple_of_ahnqiraj()
                .map_or(0, |s| s.players_in_stomach.len());
            if i >= len {
                break;
            }
            let guid = self
                .temple_of_ahnqiraj()
                .map_or(ObjectGuid::EMPTY, |s| s.players_in_stomach[i].0);
            if !self.players.contains_key(&guid) {
                if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    s.players_in_stomach.remove(i);
                }
                continue;
            }
            if let Some(s) = self.temple_of_ahnqiraj_mut() {
                s.players_in_stomach[i].1.since_ported_to_ms += diff_ms;
            }
            // Outside the stomach (fork `GetPositionZ() >
            // 0.0`, cpp 729).
            let outside = self.object_position(guid).is_some_and(|p| p.z > 0.0);
            if outside {
                let ready = self
                    .temple_of_ahnqiraj()
                    .is_some_and(|s| s.players_in_stomach[i].1.since_ported_to_ms > 4000);
                if ready {
                    if self
                        .aura_holders(guid)
                        .iter()
                        .any(|h| h.spell_id == AQ40_SPELL_DIGESTIVE_ACID)
                    {
                        self.remove_auras_due_to_spell(guid, AQ40_SPELL_DIGESTIVE_ACID);
                    }
                    let (knocked, since_from) = self.temple_of_ahnqiraj().map_or((true, 0), |s| {
                        (
                            s.players_in_stomach[i].1.did_knockback,
                            s.players_in_stomach[i].1.since_ported_from_ms,
                        )
                    });
                    if !knocked && since_from > 0 {
                        self.aq40_perform_cthun_knockback();
                        if let Some(s) = self.temple_of_ahnqiraj_mut() {
                            s.players_in_stomach[i].1.did_knockback = true;
                        }
                    } else if let Some(s) = self.temple_of_ahnqiraj_mut() {
                        s.players_in_stomach[i].1.since_ported_from_ms += diff_ms;
                    }
                    let done = self
                        .temple_of_ahnqiraj()
                        .is_some_and(|s| s.players_in_stomach[i].1.since_ported_from_ms > 1500);
                    if done {
                        if let Some(s) = self.temple_of_ahnqiraj_mut() {
                            s.players_in_stomach.remove(i);
                        }
                        continue;
                    }
                }
            } else {
                let acid = self
                    .temple_of_ahnqiraj()
                    .map_or(0, |s| s.players_in_stomach[i].1.acid_debuff_ms);
                if acid < diff_ms {
                    if let Some(cthun) = cthun {
                        let _ = self.cast_spell(
                            cthun,
                            AQ40_SPELL_DIGESTIVE_ACID,
                            CastTarget::Unit(guid),
                            CastOptions {
                                triggered: true,
                                skip_known: true,
                                ..Default::default()
                            },
                        );
                    }
                    if let Some(s) = self.temple_of_ahnqiraj_mut() {
                        s.players_in_stomach[i].1.acid_debuff_ms += AQ40_STOMACH_ACID_REFRESH_RATE;
                    }
                } else if let Some(s) = self.temple_of_ahnqiraj_mut() {
                    s.players_in_stomach[i].1.acid_debuff_ms -= diff_ms;
                }
            }
            i += 1;
        }
    }

    /// `instance_temple_of_ahnqiraj::RestoreOuroSpawnTrigger`
    /// (cpp 794-803). The fork `Respawn()`s the spawner:
    /// no creature-respawn helper on `Map`
    /// (NEEDS-MAP-HELPER); home position is restored.
    fn aq40_restore_ouro_spawn_trigger(&mut self) {
        if let Some(spawner) = self.find_creature_by_entry(AQ40_NPC_OURO_SPAWNER)
            && let Some(c) = self.creatures.get_mut(&spawner)
        {
            c.home_position = Position::new(-9188.45, 2091.56, -64.17, 6.01);
        }
        if let Some(s) = self.temple_of_ahnqiraj_mut() {
            s.restore_ouro_timer_ms = 0;
        }
    }

    // ------------------------------------------------ instance: stratholme

    /// `instance_stratholme::UpdateGoState` (cpp 198-209): direct
    /// `SetGoState` unless `withRestoreTime` (fork `UseDoorOrButton(10)`),
    /// which has no timed-restore helper, so the reachable part is the
    /// toggle-open. All fork call sites pass `false`.
    fn strat_update_go_state(&mut self, go: ObjectGuid, new_state: u32, with_restore: bool) {
        if go.is_empty() {
            return;
        }
        if with_restore {
            self.use_door(go);
        } else {
            let _ = self.object_set_field(go, u32::from(offsets::GAMEOBJECT_STATE), new_state);
        }
    }

    /// `instance_stratholme::StartSlaugtherSquare` (cpp 167-194):
    /// missing crystals count as destroyed, like the fork's
    /// `GetCreature` null path.
    fn strat_start_slaughter_square(&mut self) -> bool {
        let guids = self.stratholme().map_or(Vec::new(), |s| s.crystals.clone());
        let mut count = guids.len() as u32;
        for guid in guids {
            let destroyed = self.creatures.get(&guid).is_none_or(|c| !c.unit.is_alive());
            if destroyed {
                count = count.wrapping_sub(1);
            }
        }
        if count != 0 {
            return false;
        }
        let (gauntlet, slaughter) = self
            .stratholme()
            .map_or((ObjectGuid::EMPTY, ObjectGuid::EMPTY), |s| {
                (s.port_gauntlet, s.port_slaughter)
            });
        if gauntlet != ObjectGuid::EMPTY {
            self.strat_update_go_state(gauntlet, GO_STATE_ACTIVE, false);
        }
        if slaughter != ObjectGuid::EMPTY {
            self.strat_update_go_state(slaughter, GO_STATE_ACTIVE, false);
        }
        self.strat_set_data(STRAT_TYPE_CRISTAL_ALL_DIE, DONE);
        true
    }

    /// `instance_stratholme::SummonRamstein` (cpp 959-968).
    /// Fork `instance->SummonCreature` has no summoner, so
    /// `ObjectGuid::EMPTY` is recorded.
    fn strat_summon_ramstein(&mut self) {
        let at = Position::new(4_032.35, -3_380.567, 119.739_57, 4.761_4);
        if let Some(ramstein) = self.summon_creature(
            STRAT_NPC_RAMSTEIN,
            at,
            ObjectGuid::EMPTY,
            STRAT_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
            1_800_000,
        ) {
            let dest = Position::new(4_033.009, -3_404.329_3, 115.355_4, 0.0);
            self.creature_move_point(ramstein, 0, dest, 0, 0.0, -10.0);
            if let Some(c) = self.creatures.get_mut(&ramstein) {
                c.home_position = Position::new(4_033.009, -3_404.329_3, 115.355_4, 4.788_97);
            }
            self.strat_set_data(STRAT_TYPE_RAMSTEIN_EVENT, DONE);
        }
    }

    /// `instance_stratholme::DoGateTrap` (cpp 969-986): close both trap
    /// gates. Fork `DoUseDoorOrButton` toggles; the trap fires while the
    /// gates stand open, so closing an `ACTIVE` door via a `READY` write
    /// is the reachable part.
    fn strat_do_gate_trap(&mut self, gate: usize) {
        if self.stratholme().map_or(0, |s| s.gate_trap_timers[gate][0]) != 0 {
            return;
        }
        for k in 0..2 {
            let go = self
                .stratholme()
                .map_or(ObjectGuid::EMPTY, |s| s.rat_trap_gates[2 * gate + k]);
            if go != ObjectGuid::EMPTY && self.go_state(go) == GO_STATE_ACTIVE {
                let _ =
                    self.object_set_field(go, u32::from(offsets::GAMEOBJECT_STATE), GO_STATE_READY);
            }
        }
        if let Some(s) = self.stratholme_mut() {
            // 30 * MINUTE * IN_MILLISECONDS, 20 / 2 * IN_MILLISECONDS.
            s.gate_trap_timers[gate][0] = 1_800_000;
            s.gate_trap_timers[gate][1] = 20_000;
            s.gate_trap_timers[gate][2] = 2000;
        }
    }

    /// `instance_stratholme::DoSpawnPlaguedCritters` (cpp 988-1000).
    /// Fork `GetRandomPoint(x, y, z, 8)` has no `Map` helper; the
    /// reachable part scatters spawns with `irand` square jitter around
    /// the trap instead (see unresolved notes).
    #[allow(clippy::cast_precision_loss)] // one fork override port
    fn strat_spawn_plagued_critters(&mut self, gate: usize, summoner: ObjectGuid) {
        let trap = STRAT_GATE_TRAP[gate];
        let entry = STRAT_PLAGUED_CRITTERS[self.spell_rng().irand(0, 2) as usize];
        for _ in 0..30 {
            let jx = self.spell_rng().irand(-8, 8) as f32;
            let jy = self.spell_rng().irand(-8, 8) as f32;
            let at = Position::new(trap[0] + jx, trap[1] + jy, trap[2], 0.0);
            self.summon_creature(entry, at, summoner, STRAT_TEMPSUMMON_DEAD_DESPAWN, 0);
        }
    }

    /// `instance_stratholme::MoveAbomnationMob` (cpp 700-721).
    #[allow(clippy::cast_possible_wrap, clippy::cast_sign_loss)] // one fork override port
    fn strat_move_abomnation_mob(&mut self) {
        let abos = self
            .stratholme()
            .map_or(Vec::new(), |s| s.slaughter_abos.clone());
        if abos.is_empty() {
            return;
        }
        let pick = self.spell_rng().irand(0, abos.len() as i32 - 1) as usize;
        let guid = abos[pick];
        if let Some(c) = self.creatures.get(&guid) {
            let entry = c.info.entry;
            if c.unit.is_alive() && !self.ai_in_combat(guid) {
                // `MovePoint(0, 4037.194, -3473.741_943, 121.738_81)`.
                let dest = Position::new(4_037.194, -3_473.742, 121.738_81, 0.0);
                self.creature_move_point(guid, 0, dest, 0, 0.0, -10.0);
            }
            // Fork always refreshes the timer and drops the mob from the
            // list once resolved (dead or alive, but not when gone).
            let delay = if entry == STRAT_NPC_ABOM_BILE {
                45_000
            } else {
                self.spell_rng().irand(35_000, 40_000) as u32
            };
            if let Some(s) = self.stratholme_mut() {
                s.slaughter_abo_mob_timer_ms = delay;
                s.slaughter_abos.retain(|g| *g != guid);
            }
        }
    }

    /// One Baron-run ultimatum broadcast (Update cpp 810-857): cast the
    /// aura on every player missing that spell's holder.
    fn strat_cast_ultimatum(&mut self, spell: u32) {
        let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
        for player in players {
            if !self
                .aura_holders(player)
                .iter()
                .any(|h| h.spell_id == spell)
            {
                let _ = self.cast_spell(
                    player,
                    spell,
                    CastTarget::SelfCast,
                    CastOptions {
                        triggered: true,
                        skip_known: true,
                        ..Default::default()
                    },
                );
            }
        }
    }

    /// `TYPE_BARON` DONE cleanup (cpp 522-542): strip the four ultimatum
    /// auras still held. Quest credit (`KilledMonsterCredit`) has no
    /// `Map` helper (see unresolved notes).
    fn strat_strip_ultimatums(&mut self, player: ObjectGuid) {
        for spell in [
            STRAT_SPELL_BARON_ULTIMATUM_45MIN,
            STRAT_SPELL_BARON_ULTIMATUM_10MIN,
            STRAT_SPELL_BARON_ULTIMATUM_5MIN,
            STRAT_SPELL_BARON_ULTIMATUM_1MIN,
        ] {
            if self
                .aura_holders(player)
                .iter()
                .any(|h| h.spell_id == spell)
            {
                self.remove_auras_due_to_spell(player, spell);
            }
        }
    }

    /// `instance_stratholme::OnCreatureCreate` (cpp 211-250). List/set
    /// pushes dedupe: create refires on respawn and has no distinct
    /// respawn dispatcher.
    fn strat_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            STRAT_NPC_BARON => {
                if let Some(s) = self.stratholme_mut() {
                    s.baron = guid;
                }
                if self.strat_get_data(STRAT_TYPE_RAMSTEIN) != Some(DONE) {
                    let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
                    let _ = self.object_set_field(
                        guid,
                        u32::from(offsets::UNIT_FIELD_FLAGS),
                        flags | (STRAT_UNIT_FLAG_NOT_SELECTABLE | STRAT_UNIT_FLAG_SPAWNING),
                    );
                }
            }
            STRAT_NPC_YSIDA_TRIGGER => {
                if let Some(s) = self.stratholme_mut() {
                    s.ysida_trigger = guid;
                }
            }
            STRAT_NPC_YSIDA => {
                if let Some(s) = self.stratholme_mut() {
                    s.ysida = guid;
                }
            }
            STRAT_NPC_CRYSTAL => {
                if let Some(s) = self.stratholme_mut()
                    && !s.crystals.contains(&guid)
                {
                    s.crystals.push(guid);
                }
            }
            STRAT_NPC_ABOM_BILE | STRAT_NPC_ABOM_VENOM => {
                if let Some(s) = self.stratholme_mut() {
                    if !s.abomnations.contains(&guid) {
                        s.abomnations.push(guid);
                    }
                    if !s.slaughter_abos.contains(&guid) {
                        s.slaughter_abos.push(guid);
                    }
                }
            }
            STRAT_NPC_RAMSTEIN => {
                if let Some(s) = self.stratholme_mut() {
                    s.ramstein = guid;
                }
            }
            STRAT_NPC_TIMMY => {
                if let Some(s) = self.stratholme_mut() {
                    s.timmy = guid;
                }
            }
            STRAT_NPC_DATHROHAN => {
                if let Some(s) = self.stratholme_mut() {
                    s.dathrohan = guid;
                }
            }
            STRAT_NPC_MAGISTRATE => {
                let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::UNIT_FIELD_FLAGS),
                    flags | STRAT_UNIT_FLAG_SPAWNING,
                );
            }
            _ => {}
        }
        // Fork tracks every creature here (triage happens per update;
        // the fork comment also notes a coordinate quirk with x/y/z = 0).
        if let Some(s) = self.stratholme_mut()
            && !s.scarlet_place.contains(&guid)
        {
            s.scarlet_place.push(guid);
        }
    }

    /// `instance_stratholme::OnGameObjectCreate` (cpp 252-321).
    #[allow(clippy::too_many_lines)] // one fork override port
    fn strat_on_object_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            STRAT_GO_SERVICE_ENTRANCE => {
                if let Some(s) = self.stratholme_mut() {
                    s.service_entrance = guid;
                }
            }
            STRAT_GO_GAUNTLET_GATE1 => {
                // Weird fork quirk, kept: the DB flag makes the client
                // respond as expected.
                let flags = self.object_get_field(guid, offsets::GAMEOBJECT_FLAGS);
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::GAMEOBJECT_FLAGS),
                    flags | STRAT_GO_FLAG_LOCKED,
                );
                if let Some(s) = self.stratholme_mut() {
                    s.gauntlet_gate1 = guid;
                }
            }
            STRAT_GO_SLAUGHTER_SQUARE_GATE => {
                if let Some(s) = self.stratholme_mut() {
                    s.slaughter_square_gate = guid;
                }
            }
            STRAT_GO_ZIGGURAT1 => {
                if let Some(s) = self.stratholme_mut() {
                    s.ziggurat1 = guid;
                }
                if self.strat_get_data(STRAT_TYPE_NERUB) == Some(DONE) {
                    self.use_door(guid);
                }
            }
            STRAT_GO_ZIGGURAT2 => {
                if let Some(s) = self.stratholme_mut() {
                    s.ziggurat2 = guid;
                }
                if self.strat_get_data(STRAT_TYPE_NERUB) == Some(DONE) {
                    self.use_door(guid);
                }
            }
            STRAT_GO_ZIGGURAT3 => {
                if let Some(s) = self.stratholme_mut() {
                    s.ziggurat3 = guid;
                }
                if self.strat_get_data(STRAT_TYPE_PALLID) == Some(DONE) {
                    self.use_door(guid);
                }
            }
            STRAT_GO_ZIGGURAT4 => {
                if self.strat_get_data(STRAT_TYPE_RAMSTEIN) == Some(DONE) {
                    self.use_door(guid);
                }
                if let Some(s) = self.stratholme_mut() {
                    s.ziggurat4 = guid;
                }
            }
            STRAT_GO_ZIGGURAT5 => {
                if self.strat_get_data(STRAT_TYPE_RAMSTEIN) == Some(DONE) {
                    self.use_door(guid);
                }
                if let Some(s) = self.stratholme_mut() {
                    s.ziggurat5 = guid;
                }
            }
            STRAT_GO_PORT_GAUNTLET => {
                if let Some(s) = self.stratholme_mut() {
                    s.port_gauntlet = guid;
                }
                if self.strat_get_data(STRAT_TYPE_CRISTAL_ALL_DIE) == Some(DONE) {
                    self.use_door(guid);
                }
            }
            STRAT_GO_PORT_SLAUGTHER => {
                if let Some(s) = self.stratholme_mut() {
                    s.port_slaughter = guid;
                }
                if self.strat_get_data(STRAT_TYPE_CRISTAL_ALL_DIE) == Some(DONE) {
                    self.use_door(guid);
                }
            }
            STRAT_GO_PORT_ELDERS => {
                if let Some(s) = self.stratholme_mut() {
                    s.port_elder = guid;
                }
            }
            STRAT_GO_PORT_TRAP_GATE_1 => {
                if let Some(s) = self.stratholme_mut() {
                    s.rat_trap_gates[0] = guid;
                }
            }
            STRAT_GO_PORT_TRAP_GATE_2 => {
                if let Some(s) = self.stratholme_mut() {
                    s.rat_trap_gates[1] = guid;
                }
            }
            STRAT_GO_PORT_TRAP_GATE_3 => {
                if let Some(s) = self.stratholme_mut() {
                    s.rat_trap_gates[2] = guid;
                }
            }
            STRAT_GO_PORT_TRAP_GATE_4 => {
                if let Some(s) = self.stratholme_mut() {
                    s.rat_trap_gates[3] = guid;
                }
            }
            STRAT_GO_CAGE_YSIDA => {
                if let Some(s) = self.stratholme_mut() {
                    s.cage_ysida = guid;
                }
            }
            _ => {}
        }
    }

    /// `instance_stratholme::OnCreatureDeath` (cpp 323-336).
    fn strat_on_creature_death(&mut self, victim: ObjectGuid) {
        if self.object_entry(victim) != Some(STRAT_NPC_BLACK_GUARD) {
            return;
        }
        let remaining = self
            .stratholme()
            .map_or(0, |s| s.blackguard_count)
            .wrapping_sub(1);
        if let Some(s) = self.stratholme_mut() {
            s.blackguard_count = remaining;
        }
        if remaining != 0 {
            return;
        }
        let baron = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.baron);
        if self.creatures.contains_key(&baron) {
            self.do_script_text(STRAT_RIVENDARE_YELL_READY, baron, None, -1);
        }
    }

    /// `instance_stratholme::GetData` (cpp 338-350). `TYPE_SH_QUEST`
    /// is derived (all five dead -> 1 else 0); other ids index the
    /// encounter array with the fork's bounds guard.
    fn strat_get_data(&self, field: u32) -> Option<u32> {
        if field == STRAT_TYPE_SH_QUEST {
            let done = self
                .stratholme()
                .is_some_and(|s| s.silver_hand_dead == [true; 5]);
            return Some(u32::from(done));
        }
        let s = self.stratholme()?;
        if (field as usize) < STRAT_MAX_ENCOUNTER {
            Some(s.encounter[field as usize])
        } else {
            None
        }
    }

    /// `instance_stratholme::GetData64` (cpp 352-364). Note the fork
    /// reuses the `NPC_DATHROHAN` creature entry as the data id.
    fn strat_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        let s = self.stratholme()?;
        let guid = match field {
            STRAT_DATA_BARON => s.baron,
            STRAT_DATA_YSIDA_TRIGGER => s.ysida_trigger,
            STRAT_NPC_DATHROHAN => s.dathrohan,
            _ => return None,
        };
        if guid.is_empty() { None } else { Some(guid) }
    }

    /// `instance_stratholme::IsEncounterInProgress` (cpp 159-165).
    fn strat_is_encounter_in_progress(&self) -> bool {
        self.stratholme()
            .is_some_and(|s| s.encounter.contains(&IN_PROGRESS))
    }

    /// `instance_stratholme::SetData` (cpp 366-628).
    #[allow(clippy::too_many_lines, clippy::if_not_else)] // one fork override port
    fn strat_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            STRAT_TYPE_BARON_RUN => {
                match data {
                    IN_PROGRESS => {
                        let active = self
                            .strat_get_data(STRAT_TYPE_BARON_RUN)
                            .is_some_and(|v| v == IN_PROGRESS || v == STRAT_FAIL);
                        if !active {
                            if let Some(s) = self.stratholme_mut() {
                                // 45 * MINUTE * IN_MILLISECONDS.
                                s.baron_run_timer_ms = 2_700_000;
                                s.phase_baron = 0;
                            }
                            let trigger = self
                                .stratholme()
                                .map_or(ObjectGuid::EMPTY, |s| s.ysida_trigger);
                            // `pYsidaT->SummonCreature(NPC_YSIDA, ..., 1 * HOUR * IN_MILLISECONDS)`.
                            self.summon_creature(
                                STRAT_NPC_YSIDA,
                                Position::new(4_044.163, -3_334.2, 115.059_6, 4.2),
                                trigger,
                                STRAT_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
                                3_600_000,
                            );
                        }
                    }
                    // `FAIL`: fork comment only (auras already gone).
                    DONE => {
                        let cage = self
                            .stratholme()
                            .map_or(ObjectGuid::EMPTY, |s| s.cage_ysida);
                        if cage != ObjectGuid::EMPTY {
                            self.strat_update_go_state(cage, GO_STATE_ACTIVE, false);
                        }
                        let ysida = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.ysida);
                        if ysida != ObjectGuid::EMPTY && self.creatures.contains_key(&ysida) {
                            let flags = self.object_get_field(ysida, offsets::UNIT_NPC_FLAGS);
                            let _ = self.object_set_field(
                                ysida,
                                u32::from(offsets::UNIT_NPC_FLAGS),
                                flags
                                    | (STRAT_UNIT_NPC_FLAG_GOSSIP | STRAT_UNIT_NPC_FLAG_QUESTGIVER),
                            );
                            self.set_walk(ysida, true);
                            // `MovePoint(1, 4041.2, -3339.0, 115.1, MOVE_PATHFINDING)`.
                            let dest = Position::new(4_041.2, -3_339.0, 115.1, 0.0);
                            self.creature_move_point(
                                ysida,
                                1,
                                dest,
                                STRAT_MOVE_PATHFINDING,
                                0.0,
                                -10.0,
                            );
                        }
                        if let Some(s) = self.stratholme_mut() {
                            s.ysida_reward_timer_ms = 5000;
                            s.baron_run_timer_ms = 0;
                        }
                    }
                    _ => {}
                }
                if let Some(s) = self.stratholme_mut() {
                    s.encounter[STRAT_TYPE_BARON_RUN as usize] = data;
                }
            }
            STRAT_TYPE_BARONESS => {
                if let Some(s) = self.stratholme_mut() {
                    s.encounter[STRAT_TYPE_BARONESS as usize] = data;
                }
                if data == DONE {
                    let go = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.ziggurat1);
                    if go != ObjectGuid::EMPTY {
                        self.strat_update_go_state(go, GO_STATE_ACTIVE, false);
                    }
                }
            }
            STRAT_TYPE_NERUB => {
                if let Some(s) = self.stratholme_mut() {
                    s.encounter[STRAT_TYPE_NERUB as usize] = data;
                }
                if data == DONE {
                    let go = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.ziggurat2);
                    if go != ObjectGuid::EMPTY {
                        self.strat_update_go_state(go, GO_STATE_ACTIVE, false);
                    }
                }
            }
            STRAT_TYPE_PALLID => {
                if let Some(s) = self.stratholme_mut() {
                    s.encounter[STRAT_TYPE_PALLID as usize] = data;
                }
                if data == DONE {
                    let go = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.ziggurat3);
                    if go != ObjectGuid::EMPTY {
                        self.strat_update_go_state(go, GO_STATE_ACTIVE, false);
                    }
                }
            }
            STRAT_TYPE_RAMSTEIN => {
                // `SPECIAL`: mob aggro, close the gauntlet port (cpp 426-432).
                if data == STRAT_SPECIAL {
                    let port = self
                        .stratholme()
                        .map_or(ObjectGuid::EMPTY, |s| s.port_gauntlet);
                    if port != ObjectGuid::EMPTY && self.go_state(port) != GO_STATE_READY {
                        self.strat_update_go_state(port, GO_STATE_READY, false);
                    }
                    if let Some(s) = self.stratholme_mut() {
                        s.slaughter_abo_mob_timer_ms = 20_000;
                    }
                }
                // `IN_PROGRESS`: mob death / Ramstein aggro (cpp 433-469).
                if data == IN_PROGRESS {
                    if self.stratholme().is_some_and(|s| s.summoning_ramstein) {
                        return true;
                    }
                    if let Some(s) = self.stratholme_mut() {
                        // Guards re-entrant `SummonRamstein -> SetData`.
                        s.summoning_ramstein = true;
                    }
                    let ramstein = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.ramstein);
                    if ramstein != ObjectGuid::EMPTY {
                        let port = self
                            .stratholme()
                            .map_or(ObjectGuid::EMPTY, |s| s.port_gauntlet);
                        if port != ObjectGuid::EMPTY && self.go_state(port) != GO_STATE_READY {
                            self.strat_update_go_state(port, GO_STATE_READY, false);
                        }
                        if let Some(s) = self.stratholme_mut() {
                            s.encounter[STRAT_TYPE_RAMSTEIN as usize] = data;
                            s.summoning_ramstein = false;
                        }
                    } else {
                        // Missing abomnations read as already dead here
                        // (no decrement), unlike `StartSlaugtherSquare`.
                        let abos = self
                            .stratholme()
                            .map_or(Vec::new(), |s| s.abomnations.clone());
                        let mut remaining = abos.len() as u32;
                        for guid in abos {
                            if let Some(c) = self.creatures.get(&guid)
                                && !c.unit.is_alive()
                            {
                                remaining = remaining.wrapping_sub(1);
                            }
                        }
                        if remaining == 0 {
                            let baron = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.baron);
                            if self.creatures.contains_key(&baron) {
                                self.do_script_text(
                                    STRAT_RIVENDARE_YELL_RAMMSTEIN,
                                    baron,
                                    None,
                                    -1,
                                );
                            }
                            let zig4 = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.ziggurat4);
                            if zig4 != ObjectGuid::EMPTY {
                                self.strat_update_go_state(zig4, GO_STATE_ACTIVE, false);
                            }
                            if let Some(s) = self.stratholme_mut() {
                                s.slaughter_square_timer_ms = 5000;
                            }
                            self.strat_summon_ramstein();
                        }
                        if let Some(s) = self.stratholme_mut() {
                            s.summoning_ramstein = false;
                        }
                    }
                }
                // `DONE`: Ramstein death, slaughter event (cpp 470-492).
                if data == DONE {
                    let gate = self
                        .stratholme()
                        .map_or(ObjectGuid::EMPTY, |s| s.slaughter_square_gate);
                    if gate != ObjectGuid::EMPTY {
                        // `DoUseDoorOrButton(gate, 91)`: opening use.
                        self.use_door(gate);
                    }
                    for _ in 0..34 {
                        let x = 3_929.6 + self.spell_rng().frand01() * 3.0;
                        let y = -3_384.3 + self.spell_rng().frand01() * 3.0;
                        // `instance->SummonCreature`: no summoner recorded.
                        // `GetRandomPoint` / `SetHomePosition` /
                        // `MoveRandom` have no `Map` helpers; the
                        // reachable part is spawn + walk-off + final
                        // `MovePoint` (see unresolved notes).
                        if let Some(undead) = self.summon_creature(
                            STRAT_NPC_MINDLESS_UNDEAD,
                            Position::new(x, y, 120.0, 4.88),
                            ObjectGuid::EMPTY,
                            STRAT_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
                            1_800_000,
                        ) {
                            self.set_walk(undead, false);
                            let dest = Position::new(3_941.29, -3_394.84, 119.69, 0.0);
                            self.creature_move_point(
                                undead,
                                1,
                                dest,
                                STRAT_MOVE_FORCE_DESTINATION | STRAT_MOVE_STRAIGHT_PATH,
                                0.0,
                                -10.0,
                            );
                        }
                    }
                    if let Some(s) = self.stratholme_mut() {
                        s.slaughter_square_timer_ms = 60_000;
                    }
                }
                // `FAIL`: mob evade / Ramstein evade (cpp 493-499).
                if data == STRAT_FAIL {
                    let port = self
                        .stratholme()
                        .map_or(ObjectGuid::EMPTY, |s| s.port_gauntlet);
                    if port != ObjectGuid::EMPTY && self.go_state(port) != GO_STATE_ACTIVE {
                        self.strat_update_go_state(port, GO_STATE_ACTIVE, false);
                    }
                    if let Some(s) = self.stratholme_mut() {
                        s.slaughter_abo_mob_timer_ms = 0;
                    }
                }
                if let Some(s) = self.stratholme_mut() {
                    s.encounter[STRAT_TYPE_RAMSTEIN as usize] = data;
                }
            }
            STRAT_TYPE_BARON => {
                if data == IN_PROGRESS {
                    let (zig4, zig5, port) = self.stratholme().map_or(
                        (ObjectGuid::EMPTY, ObjectGuid::EMPTY, ObjectGuid::EMPTY),
                        |s| (s.ziggurat4, s.ziggurat5, s.port_gauntlet),
                    );
                    for go in [zig4, zig5, port] {
                        if go != ObjectGuid::EMPTY && self.go_state(go) != GO_STATE_READY {
                            self.strat_update_go_state(go, GO_STATE_READY, false);
                        }
                    }
                }
                if data == DONE {
                    if self.strat_get_data(STRAT_TYPE_BARON_RUN) == Some(IN_PROGRESS) {
                        let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
                        for player in players {
                            self.strat_strip_ultimatums(player);
                        }
                        self.strat_set_data(STRAT_TYPE_BARON_RUN, DONE);
                    }
                    let (zig4, zig5, port) = self.stratholme().map_or(
                        (ObjectGuid::EMPTY, ObjectGuid::EMPTY, ObjectGuid::EMPTY),
                        |s| (s.ziggurat4, s.ziggurat5, s.port_gauntlet),
                    );
                    for go in [zig4, zig5, port] {
                        if go != ObjectGuid::EMPTY && self.go_state(go) != GO_STATE_ACTIVE {
                            self.strat_update_go_state(go, GO_STATE_ACTIVE, false);
                        }
                    }
                }
                if data == STRAT_FAIL {
                    let (zig4, zig5, port) = self.stratholme().map_or(
                        (ObjectGuid::EMPTY, ObjectGuid::EMPTY, ObjectGuid::EMPTY),
                        |s| (s.ziggurat4, s.ziggurat5, s.port_gauntlet),
                    );
                    for go in [zig4, zig5, port] {
                        if go != ObjectGuid::EMPTY && self.go_state(go) != GO_STATE_ACTIVE {
                            self.strat_update_go_state(go, GO_STATE_ACTIVE, false);
                        }
                    }
                }
                if let Some(s) = self.stratholme_mut() {
                    s.encounter[STRAT_TYPE_BARON as usize] = data;
                }
            }
            STRAT_TYPE_CRISTAL_DIE => {
                self.strat_start_slaughter_square();
            }
            STRAT_TYPE_CRISTAL_ALL_DIE
            | STRAT_TYPE_EVENT_AURIUS
            | STRAT_TYPE_RAMSTEIN_EVENT
            | STRAT_TYPE_UNFORGIVEN => {
                if let Some(s) = self.stratholme_mut() {
                    s.encounter[field as usize] = data;
                }
            }
            STRAT_TYPE_SH_AELMAR => {
                if let Some(s) = self.stratholme_mut() {
                    s.silver_hand_dead[0] = data != 0;
                }
            }
            STRAT_TYPE_SH_CATHELA => {
                if let Some(s) = self.stratholme_mut() {
                    s.silver_hand_dead[1] = data != 0;
                }
            }
            STRAT_TYPE_SH_GREGOR => {
                if let Some(s) = self.stratholme_mut() {
                    s.silver_hand_dead[2] = data != 0;
                }
            }
            STRAT_TYPE_SH_NEMAS => {
                if let Some(s) = self.stratholme_mut() {
                    s.silver_hand_dead[3] = data != 0;
                }
            }
            STRAT_TYPE_SH_VICAR => {
                if let Some(s) = self.stratholme_mut() {
                    s.silver_hand_dead[4] = data != 0;
                }
            }
            STRAT_TYPE_POSTMASTER => {
                if let Some(s) = self.stratholme_mut() {
                    s.encounter[STRAT_TYPE_POSTMASTER as usize] = data;
                }
                if data == IN_PROGRESS {
                    let used = self
                        .stratholme()
                        .map_or(0, |s| s.postboxes_used)
                        .wrapping_add(1);
                    if let Some(s) = self.stratholme_mut() {
                        s.postboxes_used = used;
                    }
                    // After the second postbox, arm the Post Master.
                    if used == 2 {
                        self.strat_set_data(STRAT_TYPE_POSTMASTER, STRAT_SPECIAL);
                    }
                }
                // Fork returns here: postboxes are never saved.
                return true;
            }
            _ => return false,
        }
        // Fork refresh condition, copied exactly: any owned field set
        // `DONE` (postmaster returns above) restreams the full array
        // with a trailing space (`<< i << ' '`).
        if data == DONE
            && let Some(s) = self.stratholme_mut()
        {
            let e = s.encounter;
            s.save_string = format!(
                "{} {} {} {} {} {} {} {} {} {} {} ",
                e[0], e[1], e[2], e[3], e[4], e[5], e[6], e[7], e[8], e[9], e[10],
            );
        }
        true
    }

    /// `instance_stratholme::Save` (cpp 632) / `Load` (cpp 634-647).
    /// `Save` returns the cached stream; `Load` parses whitespace
    /// `u32`s, maps `IN_PROGRESS` to 0, and re-summons Ramstein when the
    /// event finished without his death.
    fn strat_save(&self) -> Option<String> {
        self.stratholme().map(|s| s.save_string.clone())
    }

    fn strat_load(&mut self, data: &str) {
        let mut loaded = [0u32; STRAT_MAX_ENCOUNTER];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = 0;
            }
        }
        if let Some(s) = self.stratholme_mut() {
            s.encounter = loaded;
        }
        if self.strat_get_data(STRAT_TYPE_RAMSTEIN_EVENT) == Some(DONE)
            && self.strat_get_data(STRAT_TYPE_RAMSTEIN) != Some(DONE)
        {
            self.strat_summon_ramstein();
        }
    }

    /// `instance_stratholme::Update` (cpp 723-958).
    #[allow(clippy::too_many_lines, clippy::cast_precision_loss)] // one fork override port
    fn strat_update(&mut self, diff_ms: u32) {
        // The Unforgiven ambush (cpp 725-744): first living player
        // within 10 yards of the trigger spot. Fork also requires
        // `IsTargetableBy(nullptr)` plus GM/visibility filters, which
        // have no `Map` readers; aliveness is the reachable gate (see
        // unresolved notes). Fork `instance->SummonCreature`: no
        // summoner recorded.
        if self.strat_get_data(STRAT_TYPE_UNFORGIVEN) == Some(STRAT_NOT_STARTED) {
            let spot = Position::new(
                STRAT_UNFORGIVEN_SPOT[0],
                STRAT_UNFORGIVEN_SPOT[1],
                STRAT_UNFORGIVEN_SPOT[2],
                0.0,
            );
            let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
            let ambushed = players.iter().any(|p| {
                self.unit_is_alive(*p)
                    && self
                        .object_position(*p)
                        .is_some_and(|pp| crate::visibility::dist3d(pp, spot) <= 10.0)
            });
            if ambushed {
                self.strat_set_data(STRAT_TYPE_UNFORGIVEN, DONE);
                let summons = [
                    (
                        STRAT_NPC_THE_UNFORGIVEN,
                        Position::new(3_719.82, -3_426.25, 131.844, 3.341_2),
                    ),
                    (
                        STRAT_NPC_VENGEFUL_PHANTOM,
                        Position::new(3_715.85, -3_428.25, 131.442, 3.577_92),
                    ),
                    (
                        STRAT_NPC_VENGEFUL_PHANTOM,
                        Position::new(3_714.14, -3_423.75, 131.673, 3.612_83),
                    ),
                    (
                        STRAT_NPC_VENGEFUL_PHANTOM,
                        Position::new(3_721.93, -3_429.88, 131.844, 3.333_58),
                    ),
                    (
                        STRAT_NPC_VENGEFUL_PHANTOM,
                        Position::new(3_718.09, -3_432.27, 131.306, 4.338_1),
                    ),
                ];
                for (entry, at) in summons {
                    self.summon_creature(
                        entry,
                        at,
                        ObjectGuid::EMPTY,
                        STRAT_TEMPSUMMON_DEAD_DESPAWN,
                        3_600_000,
                    );
                }
            }
        }

        // Gate traps (cpp 746-799): each trap has a cooldown timer, a
        // gate-reopen timer, and a critter-spawn delay timer.
        for (gate, trap_entry) in STRAT_GATE_TRAP.iter().copied().enumerate() {
            let cooldown = self.stratholme().map_or(0, |s| s.gate_trap_timers[gate][0]);
            if cooldown != 0 {
                // Fork shape, copied literally: decrement first, then
                // compare against the same diff.
                let dec = cooldown.wrapping_sub(diff_ms);
                if dec <= diff_ms {
                    if let Some(s) = self.stratholme_mut() {
                        s.gate_trap_timers[gate][0] = 0;
                    }
                } else if let Some(s) = self.stratholme_mut() {
                    s.gate_trap_timers[gate][0] = dec;
                }
            } else {
                // Fork also accepts the player's pet and skips
                // GMs / invisible GMs; pets are reachable via
                // `pet_of`, GM state is not (see unresolved notes).
                let trap = trap_entry;
                let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
                let mut tripped = false;
                for player in players {
                    if !self.unit_is_alive(player) {
                        continue;
                    }
                    let near = |g: ObjectGuid| {
                        self.object_position(g).is_some_and(|p| {
                            crate::visibility::dist2d(
                                p,
                                Position::new(trap[0], trap[1], trap[2], trap[3]),
                            ) <= 5.5
                        })
                    };
                    if near(player) {
                        tripped = true;
                        break;
                    }
                    if let Some(pet) = self.pet_of(player)
                        && self.unit_is_alive(pet)
                        && near(pet)
                    {
                        tripped = true;
                        break;
                    }
                }
                if tripped {
                    self.strat_do_gate_trap(gate);
                }
            }
            let reopen = self.stratholme().map_or(0, |s| s.gate_trap_timers[gate][1]);
            if reopen != 0 {
                if reopen <= diff_ms {
                    for k in 0..2 {
                        let go = self
                            .stratholme()
                            .map_or(ObjectGuid::EMPTY, |s| s.rat_trap_gates[2 * gate + k]);
                        if go != ObjectGuid::EMPTY {
                            // Reopening use.
                            self.use_door(go);
                        }
                    }
                    if let Some(s) = self.stratholme_mut() {
                        s.gate_trap_timers[gate][1] = 0;
                    }
                } else if let Some(s) = self.stratholme_mut() {
                    s.gate_trap_timers[gate][1] -= diff_ms;
                }
            }
            let spawn_delay = self.stratholme().map_or(0, |s| s.gate_trap_timers[gate][2]);
            if spawn_delay != 0 {
                if spawn_delay <= diff_ms {
                    // Fork `GetPlayerInMap()`: first map player, if any.
                    let player = self.players.keys().next().copied();
                    if let Some(player) = player {
                        self.strat_spawn_plagued_critters(gate, player);
                    }
                    if let Some(s) = self.stratholme_mut() {
                        s.gate_trap_timers[gate][2] = 0;
                    }
                } else if let Some(s) = self.stratholme_mut() {
                    s.gate_trap_timers[gate][2] -= diff_ms;
                }
            }
        }

        // Baron 45-minute run (cpp 801-883). Phase gates read the
        // pre-decrement timer, like the fork.
        if self.stratholme().map_or(0, |s| s.baron_run_timer_ms) != 0 {
            let run = self.stratholme().map_or(0, |s| s.baron_run_timer_ms);
            let phase = self.stratholme().map_or(0, |s| s.phase_baron);
            if run <= 2_700_000 && phase == 0 {
                if let Some(s) = self.stratholme_mut() {
                    s.phase_baron = 1;
                }
                let baron = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.baron);
                if self.creatures.contains_key(&baron) {
                    self.do_script_text(STRAT_RIVENDARE_YELL_45MIN, baron, None, -1);
                }
                self.strat_cast_ultimatum(STRAT_SPELL_BARON_ULTIMATUM_45MIN);
            }
            if run <= 600_000 && self.stratholme().map_or(0, |s| s.phase_baron) == 1 {
                if let Some(s) = self.stratholme_mut() {
                    s.phase_baron = 2;
                }
                let baron = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.baron);
                if self.creatures.contains_key(&baron) {
                    self.do_script_text(STRAT_RIVENDARE_YELL_10MIN, baron, None, -1);
                }
                self.strat_cast_ultimatum(STRAT_SPELL_BARON_ULTIMATUM_10MIN);
            }
            if run <= 300_000 && self.stratholme().map_or(0, |s| s.phase_baron) == 2 {
                if let Some(s) = self.stratholme_mut() {
                    s.phase_baron = 3;
                }
                let baron = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.baron);
                if self.creatures.contains_key(&baron) {
                    self.do_script_text(STRAT_RIVENDARE_YELL_5MIN, baron, None, -1);
                }
                self.strat_cast_ultimatum(STRAT_SPELL_BARON_ULTIMATUM_5MIN);
            }
            if run <= 297_000 && self.stratholme().map_or(0, |s| s.phase_baron) == 3 {
                if let Some(s) = self.stratholme_mut() {
                    s.phase_baron = 4;
                }
                let ysida = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.ysida);
                if self.creatures.contains_key(&ysida) {
                    self.do_script_text(STRAT_YSIDA_YELL_5MIN, ysida, None, -1);
                }
            }
            if run <= 60_000 && self.stratholme().map_or(0, |s| s.phase_baron) == 4 {
                if let Some(s) = self.stratholme_mut() {
                    s.phase_baron = 5;
                }
                self.strat_cast_ultimatum(STRAT_SPELL_BARON_ULTIMATUM_1MIN);
            }
            if run <= diff_ms {
                if let Some(s) = self.stratholme_mut() {
                    s.phase_baron = 6;
                    s.baron_run_timer_ms = 0;
                }
                if self.strat_get_data(STRAT_TYPE_BARON_RUN) != Some(DONE) {
                    self.strat_set_data(STRAT_TYPE_BARON_RUN, STRAT_FAIL);
                }
                let baron = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.baron);
                if self.creatures.contains_key(&baron) {
                    self.do_script_text(STRAT_RIVENDARE_YELL_FAILED, baron, None, -1);
                }
                let cage = self
                    .stratholme()
                    .map_or(ObjectGuid::EMPTY, |s| s.cage_ysida);
                if cage != ObjectGuid::EMPTY {
                    self.strat_update_go_state(cage, GO_STATE_ACTIVE, false);
                }
                let ysida = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.ysida);
                if ysida != ObjectGuid::EMPTY && self.creatures.contains_key(&ysida) {
                    self.do_script_text(STRAT_YSIDA_YELL_FAILED, ysida, None, -1);
                    // Fork `CastSpell(pYsida, 5, true)` (deathtouch).
                    let _ = self.cast_spell(
                        ysida,
                        5,
                        CastTarget::SelfCast,
                        CastOptions {
                            triggered: true,
                            skip_known: true,
                            ..Default::default()
                        },
                    );
                }
            } else if let Some(s) = self.stratholme_mut() {
                s.baron_run_timer_ms -= diff_ms;
            }
        }

        // Slaughter-abomnation wander timer (cpp 885-896).
        if self
            .stratholme()
            .map_or(0, |s| s.slaughter_abo_mob_timer_ms)
            != 0
        {
            let timer = self
                .stratholme()
                .map_or(0, |s| s.slaughter_abo_mob_timer_ms);
            if timer <= diff_ms {
                if self
                    .stratholme()
                    .is_none_or(|s| s.slaughter_abos.is_empty())
                {
                    if let Some(s) = self.stratholme_mut() {
                        s.slaughter_abo_mob_timer_ms = 0;
                    }
                } else {
                    self.strat_move_abomnation_mob();
                }
            } else if let Some(s) = self.stratholme_mut() {
                s.slaughter_abo_mob_timer_ms -= diff_ms;
            }
        }

        // Slaughter-square timer (cpp 898-933).
        if self.stratholme().map_or(0, |s| s.slaughter_square_timer_ms) != 0 {
            let timer = self.stratholme().map_or(0, |s| s.slaughter_square_timer_ms);
            if timer <= diff_ms {
                if self.strat_get_data(STRAT_TYPE_RAMSTEIN) == Some(IN_PROGRESS) {
                    let zig4 = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.ziggurat4);
                    if zig4 != ObjectGuid::EMPTY {
                        self.strat_update_go_state(zig4, GO_STATE_READY, false);
                    }
                    let ramstein = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.ramstein);
                    if self.creatures.contains_key(&ramstein) {
                        self.do_script_text(STRAT_RAMMSTEIN_YELL_SPAWN, ramstein, None, -1);
                    }
                } else {
                    let baron = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.baron);
                    if baron != ObjectGuid::EMPTY && self.creatures.contains_key(&baron) {
                        // Five Black Guards (`pBaron->SummonCreature`).
                        for i in 0..5u8 {
                            let jx = self.spell_rng().irand(0, 2) as f32;
                            let jy = self.spell_rng().irand(0, 2) as f32;
                            if let Some(guard) = self.summon_creature(
                                STRAT_NPC_BLACK_GUARD,
                                Position::new(4_032.84 + jx, -3_380.567 + jy, 119.739_57, 4.761_4),
                                baron,
                                STRAT_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
                                1_800_000,
                            ) {
                                let dest = Position::new(4_033.34, -3_419.75, 116.35, 0.0);
                                self.creature_move_point(guard, 0, dest, 0, 0.0, -10.0);
                                if let Some(c) = self.creatures.get_mut(&guard) {
                                    c.home_position =
                                        Position::new(4_033.34, -3_419.75, 116.35, 4.80);
                                }
                                if i == 0 {
                                    self.do_script_text(
                                        STRAT_BLACKGUARD_YELL_SPAWN,
                                        guard,
                                        None,
                                        -1,
                                    );
                                }
                            }
                        }
                        let (zig4, zig5) = self
                            .stratholme()
                            .map_or((ObjectGuid::EMPTY, ObjectGuid::EMPTY), |s| {
                                (s.ziggurat4, s.ziggurat5)
                            });
                        if zig4 != ObjectGuid::EMPTY {
                            self.strat_update_go_state(zig4, GO_STATE_ACTIVE, false);
                        }
                        if zig5 != ObjectGuid::EMPTY {
                            self.strat_update_go_state(zig5, GO_STATE_ACTIVE, false);
                        }
                        // `RemoveFlag(NOT_SELECTABLE | SPAWNING)`.
                        let flags = self.object_get_field(baron, offsets::UNIT_FIELD_FLAGS);
                        let _ = self.object_set_field(
                            baron,
                            u32::from(offsets::UNIT_FIELD_FLAGS),
                            flags & !(STRAT_UNIT_FLAG_NOT_SELECTABLE | STRAT_UNIT_FLAG_SPAWNING),
                        );
                    }
                }
                if let Some(s) = self.stratholme_mut() {
                    s.slaughter_square_timer_ms = 0;
                }
            } else if let Some(s) = self.stratholme_mut() {
                s.slaughter_square_timer_ms -= diff_ms;
            }
        }

        // Ysida reward yell (cpp 935-957). The fork's Argent Dawn
        // reputation spell is commented out there, so it is not
        // transcribed either.
        if self.stratholme().map_or(0, |s| s.ysida_reward_timer_ms) != 0 {
            let timer = self.stratholme().map_or(0, |s| s.ysida_reward_timer_ms);
            if timer <= diff_ms {
                let ysida = self.stratholme().map_or(ObjectGuid::EMPTY, |s| s.ysida);
                if self.creatures.contains_key(&ysida) {
                    self.do_script_text(STRAT_YSIDA_SAY_REWARD, ysida, None, -1);
                }
                if let Some(s) = self.stratholme_mut() {
                    s.ysida_reward_timer_ms = 0;
                }
            } else if let Some(s) = self.stratholme_mut() {
                s.ysida_reward_timer_ms -= diff_ms;
            }
        }
    }

    // ------------------------------------------------ instance: blackrock depths

    /// `instance_blackrock_depths::OnCreatureCreate` (cpp 244-359). The
    /// commented-out Panzor block (cpp 301-312) is dead code; not transcribed.
    /// List pushes are contains-guarded: create refires on respawn.
    #[allow(clippy::too_many_lines)] // one fork override port
    fn brd_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            BRD_NPC_EMPEROR => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.emperor = guid;
                }
            }
            BRD_NPC_PRINCESS => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.princess = guid;
                }
            }
            BRD_NPC_PHALANX => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.phalanx = guid;
                }
            }
            BRD_NPC_HATEREL => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.haterel = guid;
                }
            }
            BRD_NPC_ANGERREL => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.angerrel = guid;
                }
            }
            BRD_NPC_VILEREL => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.vilerel = guid;
                }
            }
            BRD_NPC_GLOOMREL => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.gloomrel = guid;
                }
            }
            BRD_NPC_SEETHREL => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.seethrel = guid;
                }
            }
            BRD_NPC_DOOMREL => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.doomrel = guid;
                }
            }
            BRD_NPC_DOPEREL => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.doperel = guid;
                }
            }
            BRD_NPC_THELDREN => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.theldren = guid;
                }
            }
            BRD_NPC_RIBBLY_S_CRONY => {
                if let Some(s) = self.blackrock_depths_mut() {
                    if !s.ribbly_cronies.contains(&guid) {
                        s.ribbly_cronies.push(guid);
                    }
                }
            }
            BRD_NPC_MAGMUS => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.magmus = guid;
                }
            }
            BRD_NPC_ARENA_SPECTATOR
            | BRD_NPC_SHADOWFORGE_PEASANT
            | BRD_NPC_SHADOWFORGE_CITIZEN
            | BRD_NPC_SHADOWFORGE_SENATOR
            | BRD_NPC_ANVILRAGE_SOLDIER
            | BRD_NPC_ANVILRAGE_MEDIC
            | BRD_NPC_ANVILRAGE_OFFICER => {
                // `aArenaCrowdVolume` gate (cpp 295): outside the cylinder.
                let inside = self.object_position(guid).is_some_and(|pos| {
                    pos.z >= BRD_ARENA_CROWD_Z
                        && pos.z <= BRD_ARENA_CROWD_Z + BRD_ARENA_CROWD_HEIGHT
                        && crate::visibility::dist2d(
                            pos,
                            Position::new(
                                BRD_ARENA_CROWD_X,
                                BRD_ARENA_CROWD_Y,
                                BRD_ARENA_CROWD_Z,
                                0.0,
                            ),
                        ) <= BRD_ARENA_CROWD_RADIUS
                });
                if !inside {
                    return;
                }
                if let Some(s) = self.blackrock_depths_mut() {
                    if !s.arena_spectators.contains(&guid) {
                        s.arena_spectators.push(guid);
                    }
                }
                if self.brd_get_data(BRD_TYPE_RING_OF_LAW) == Some(DONE) {
                    // `SetFactionTemporary(..., TEMPFACTION_RESTORE_RESPAWN)`:
                    // sticky write; restore semantics unresolved.
                    let _ = self.object_set_field(
                        guid,
                        u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                        BRD_FACTION_ARENA_NEUTRAL,
                    );
                }
            }
            BRD_NPC_WRATH_HAMMER_CONSTRUCT | BRD_NPC_GOLEM_RAVAGE => {
                if let Some(s) = self.blackrock_depths_mut() {
                    if !s.argelmach_protectors.contains(&guid) {
                        s.argelmach_protectors.push(guid);
                    }
                }
            }
            BRD_NPC_GOLEM_LORD_ARGELMACH => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.golem_lord_argelmach = guid;
                }
            }
            BRD_NPC_PLUGGER_SPAZZRING => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.plugger_spazzring = guid;
                }
            }
            BRD_NPC_GUZZLING_PATRON | BRD_NPC_GRIM_PATRON | BRD_NPC_HAMMERED_PATRON => {
                if let Some(s) = self.blackrock_depths_mut() {
                    if !s.bar_patrons.contains(&guid) {
                        s.bar_patrons.push(guid);
                    }
                }
                if self.brd_get_data(BRD_TYPE_PLUGGER) == Some(DONE) {
                    let _ = self.object_set_field(
                        guid,
                        u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                        BRD_FACTION_DARK_IRON,
                    );
                    // `SetStandState(UNIT_STAND_STATE_STAND)`.
                    self.unit_set_byte(guid, offsets::UNIT_FIELD_BYTES_1, 0, STAND_STATE_STAND);
                    if let Some(s) = self.blackrock_depths_mut() {
                        s.bar_hostile = true;
                    }
                }
            }
            BRD_NPC_PRIVATE_ROCKNOT => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.rocknot = guid;
                }
            }
            BRD_NPC_MISTRESS_NAGMARA => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.nagmara = guid;
                }
            }
            BRD_NPC_OGRABISI => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.ograbisi = guid;
                }
            }
            BRD_NPC_SHILL => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.shill = guid;
                }
            }
            BRD_NPC_CREST => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.crest = guid;
                }
            }
            BRD_NPC_JAZ => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.jaz = guid;
                }
            }
            BRD_NPC_GRIMSTONE => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.grimstone = guid;
                }
            }
            BRD_NPC_FLAMELASH => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.flamelash = guid;
                }
            }
            _ => {}
        }
    }

