    /// `instance_blackrock_depths::OnCreatureDeath` (cpp 474-517). The
    /// commented-out Theldren arm (cpp 513-515) is dead code; not transcribed.
    fn brd_on_creature_death(&mut self, victim: ObjectGuid) {
        let Some(entry) = self.object_entry(victim) else {
            return;
        };
        match entry {
            BRD_NPC_BURNING_SPIRIT => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.burning_spirits.retain(|g| *g != victim);
                }
            }
            BRD_NPC_SHADOWFORGE_SENATOR => {
                // Emperor Dagran Thaurissan performs a random yell upon the
                // death of Shadowforge Senators in the Throne Room.
                let dagran = self
                    .brd_get_data64(BRD_DATA_EMPEROR)
                    .unwrap_or(ObjectGuid::EMPTY);
                if dagran.is_empty() || !self.unit_is_alive(dagran) {
                    return;
                }
                if self.blackrock_depths().map_or(0, |s| s.dagran_timer_ms) > 0 {
                    return;
                }
                // 45s anti-spam timer (cpp 510).
                let text = match self.spell_rng().irand(0, 3) {
                    0 => BRD_YELL_SENATOR_1,
                    1 => BRD_YELL_SENATOR_2,
                    2 => BRD_YELL_SENATOR_3,
                    _ => BRD_YELL_SENATOR_4,
                };
                self.do_script_text(text, dagran, None, -1);
                if let Some(s) = self.blackrock_depths_mut() {
                    s.dagran_timer_ms = 45_000;
                }
            }
            _ => {}
        }
    }

    /// `instance_blackrock_depths::HandleBarPatrons` (cpp 519-609).
    fn brd_handle_bar_patrons(&mut self, event: u32) {
        match event {
            BRD_PATRON_EMOTE => {
                if self.brd_get_data(BRD_TYPE_PLUGGER) == Some(DONE) {
                    return;
                }
                let patrons = self
                    .blackrock_depths()
                    .map_or(Vec::new(), |s| s.bar_patrons.clone());
                for patron in patrons {
                    if !self.creatures.contains_key(&patron) {
                        continue;
                    }
                    // About 5% of patrons emote at a given tick (cpp 532).
                    if self.spell_rng().irand(0, 100) < 4 {
                        let pick = self.spell_rng().irand(0, 5) as usize;
                        self.handle_emote_command(patron, BRD_PATRON_EMOTES[pick]);
                    }
                }
            }
            BRD_PATRON_PISSED => {
                // Three texts; patrons near the broken barrel react (cpp 543-573).
                let keg_trap = self
                    .blackrock_depths()
                    .map_or(ObjectGuid::EMPTY, |s| s.bar_keg_trap);
                let Some(trap_pos) = self.object_position(keg_trap) else {
                    return;
                };
                let patrons = self
                    .blackrock_depths()
                    .map_or(Vec::new(), |s| s.bar_patrons.clone());
                for patron in patrons {
                    let Some(pos) = self.object_position(patron) else {
                        continue;
                    };
                    if pos.z > trap_pos.z - 1.0 && crate::visibility::dist2d(pos, trap_pos) <= 18.0
                    {
                        // Case 1/2 is doubled to weight text 2 (cpp 559-562).
                        let text = match self.spell_rng().irand(0, 4) {
                            0 => BRD_SAY_PISSED_PATRON_3,
                            1 | 2 => BRD_SAY_PISSED_PATRON_2,
                            _ => BRD_SAY_PISSED_PATRON_1,
                        };
                        self.do_script_text(text, patron, None, -1);
                    }
                }
            }
            BRD_PATRON_HOSTILE => {
                if self.blackrock_depths().is_some_and(|s| s.bar_hostile) {
                    return;
                }
                if let Some(s) = self.blackrock_depths_mut() {
                    s.bar_hostile = true;
                }
                let patrons = self
                    .blackrock_depths()
                    .map_or(Vec::new(), |s| s.bar_patrons.clone());
                for patron in patrons {
                    if !self.creatures.contains_key(&patron) {
                        continue;
                    }
                    let _ = self.object_set_field(
                        patron,
                        u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                        BRD_FACTION_DARK_IRON,
                    );
                    self.unit_set_byte(patron, offsets::UNIT_FIELD_BYTES_1, 0, STAND_STATE_STAND);
                    self.handle_emote_command(patron, 0);
                    // `SetDefaultMovementType(RANDOM_MOTION_TYPE)` +
                    // `SetWanderDistance(3.0)` + `GetMotionMaster()->Initialize()`
                    // (cpp 589-591): no helpers (unresolved).
                }
                // Mistress Nagmara and Private Rocknot despawn if the bar turns
                // hostile (cpp 594-606).
                let rocknot = self
                    .brd_get_data64(BRD_DATA_ROCKNOT)
                    .unwrap_or(ObjectGuid::EMPTY);
                if !rocknot.is_empty() && self.creatures.contains_key(&rocknot) {
                    // No despawn if Rocknot and Nagmara are kissing.
                    if self
                        .aura_holders(rocknot)
                        .iter()
                        .any(|h| h.spell_id == BRD_AURA_ROCKNOT_NAGMARA)
                    {
                        return;
                    }
                    self.do_script_text(BRD_SAY_ROCKNOT_DESPAWN, rocknot, None, -1);
                    // `ForcedDespawn()`: normal respawn path.
                    self.despawn_creature_now(rocknot, 0);
                }
                let nagmara = self
                    .brd_get_data64(BRD_DATA_NAGMARA)
                    .unwrap_or(ObjectGuid::EMPTY);
                if !nagmara.is_empty() && self.creatures.contains_key(&nagmara) {
                    let _ = self.cast_spell(
                        nagmara,
                        BRD_SPELL_NAGMARA_VANISH,
                        CastTarget::SelfCast,
                        CastOptions {
                            triggered: true,
                            skip_known: true,
                            ..Default::default()
                        },
                    );
                    self.despawn_creature_now(nagmara, 0);
                }
            }
            _ => {}
        }
    }

    /// `instance_blackrock_depths::HandleBarPatrol` (cpp 611-679).
    #[allow(clippy::cast_precision_loss)] // one fork override port
    fn brd_handle_bar_patrol(&mut self, step: u32) {
        if self.brd_get_data(BRD_TYPE_PATROL) == Some(DONE) {
            return;
        }
        match step {
            0 => {
                let plugger = self
                    .brd_get_data64(BRD_DATA_PLUGGER)
                    .unwrap_or(ObjectGuid::EMPTY);
                if plugger.is_empty() || !self.creatures.contains_key(&plugger) {
                    return;
                }
                // If relevant, open the bar door (cpp 621-626).
                let bar_door = self
                    .blackrock_depths()
                    .map_or(ObjectGuid::EMPTY, |s| s.bar_door);
                if bar_door != ObjectGuid::EMPTY && self.go_state(bar_door) == GO_STATE_READY {
                    self.use_door(bar_door);
                }
                // One Fireguard Destroyer and two Anvilrage Officers are spawned
                // behind the bar door and march to the Grim Guzzler.
                for entry in BRD_BAR_PATROL_IDS {
                    // `GetRandomPoint(..., 2.0f)` (cpp 633/638): no
                    // random-point helper; `irand` jitter approximates.
                    let jx = self.spell_rng().irand(-20, 20) as f32 / 10.0;
                    let jy = self.spell_rng().irand(-20, 20) as f32 / 10.0;
                    let at = Position::new(
                        BRD_BAR_PATROL_SPAWN[0] + jx,
                        BRD_BAR_PATROL_SPAWN[1] + jy,
                        BRD_BAR_PATROL_SPAWN[2],
                        BRD_BAR_PATROL_SPAWN[3],
                    );
                    if let Some(summoned) =
                        self.summon_creature(entry, at, plugger, BRD_TEMPSUMMON_DEAD_DESPAWN, 0)
                    {
                        if let Some(s) = self.blackrock_depths_mut() {
                            if !s.bar_patrols.contains(&summoned) {
                                s.bar_patrols.push(summoned);
                            }
                        }
                        // `MoveIdle()` + `MovePoint(0, ...)` (cpp 639-640).
                        let kx = self.spell_rng().irand(-20, 20) as f32 / 10.0;
                        let ky = self.spell_rng().irand(-20, 20) as f32 / 10.0;
                        let dest = Position::new(
                            BRD_BAR_PATROL_DEST[0] + kx,
                            BRD_BAR_PATROL_DEST[1] + ky,
                            BRD_BAR_PATROL_DEST[2],
                            0.0,
                        );
                        self.creature_move_point(summoned, 0, dest, 0, 0.0, -10.0);
                    }
                }
                // Start the timer to handle the yells (cpp 644).
                if let Some(s) = self.blackrock_depths_mut() {
                    s.patrol_timer_ms = 5_000;
                }
            }
            1 => {
                let patrols = self
                    .blackrock_depths()
                    .map_or(Vec::new(), |s| s.bar_patrols.clone());
                for guid in patrols {
                    if self.object_entry(guid) == Some(BRD_NPC_ANVILRAGE_OFFICER) {
                        self.do_script_text(BRD_YELL_PATROL_1, guid, None, -1);
                        // Temporary SPECIAL before the next yell (cpp 655).
                        self.brd_set_data(BRD_TYPE_PATROL, BRD_SPECIAL);
                        if let Some(s) = self.blackrock_depths_mut() {
                            s.patrol_timer_ms = 3_000;
                        }
                        break;
                    }
                }
            }
            2 => {
                let patrols = self
                    .blackrock_depths()
                    .map_or(Vec::new(), |s| s.bar_patrols.clone());
                for guid in patrols {
                    if self.object_entry(guid) == Some(BRD_NPC_ANVILRAGE_OFFICER) {
                        self.do_script_text(BRD_YELL_PATROL_2, guid, None, -1);
                        self.brd_set_data(BRD_TYPE_PATROL, DONE);
                        if let Some(s) = self.blackrock_depths_mut() {
                            s.patrol_timer_ms = 0;
                        }
                        break;
                    }
                }
            }
            _ => {}
        }
    }

    /// `instance_blackrock_depths::BeginTheldrenEvent` (cpp 736-741). The
    /// `CustomSpellCasted` trigger (spell 27517, cpp 680-702) has no dispatcher
    /// slot; the integrator wires this helper to one.
    fn brd_begin_theldren_event(&mut self, player: ObjectGuid) {
        self.brd_set_data(BRD_DATA_THELDREN, IN_PROGRESS);
        if let Some(s) = self.blackrock_depths_mut() {
            s.challenger_player = player;
        }
    }

    /// `instance_blackrock_depths::DoSummonCreatureAndAttack` (cpp 704-734).
    /// Has no callers in the fork; transcribed for fidelity.
    #[allow(dead_code)] // no callers in the fork either
    fn brd_summon_creature_and_attack(&mut self, entry: u32, who: ObjectGuid, num: u32) {
        let (x, y) = match num {
            0 => (598.0, -153.0),
            1 => (577.0, -162.0),
            2 => (583.0, -158.0),
            3 => (593.0, -154.0),
            _ => (586.0, -152.0),
        };
        let at = Position::new(x, y, -52.0, 4.8);
        // `instance->SummonCreature` defaults: dead-despawn, 25000 ms.
        if let Some(summoned) = self.summon_creature(
            entry,
            at,
            ObjectGuid::EMPTY,
            BRD_TEMPSUMMON_DEAD_DESPAWN,
            25_000,
        ) {
            self.set_in_combat_with_zone(summoned);
            self.attack_start(summoned, who);
            let _ =
                self.object_set_field(summoned, u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE), 16);
        }
    }

    /// `instance_blackrock_depths::SetData` (cpp 767-1026). The fork stores
    /// the patrol/jail/flamelash fields at raw encounter indices (11-20)
    /// rather than at their header ids (31-43); mirrored exactly. The save
    /// refresh below fires on the passed-in `data == DONE` (streaming indices
    /// 0-19, separator form), copied verbatim from cpp 1014-1025.
    #[allow(clippy::too_many_lines)] // one fork override port
    pub(crate) fn brd_set_data(&mut self, field: u32, data: u32) -> bool {
        match field {
            BRD_TYPE_RING_OF_LAW => {
                if data == DONE {
                    let spectators = self
                        .blackrock_depths()
                        .map_or(Vec::new(), |s| s.arena_spectators.clone());
                    for guid in spectators {
                        if self.unit_is_alive(guid) {
                            let _ = self.object_set_field(
                                guid,
                                u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                                BRD_FACTION_ARENA_NEUTRAL,
                            );
                        }
                    }
                }
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[0] = data;
                }
            }
            BRD_TYPE_VAULT => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[1] = data;
                }
            }
            BRD_TYPE_ROCKNOT => {
                if data == BRD_SPECIAL {
                    if let Some(s) = self.blackrock_depths_mut() {
                        s.bar_ale_count += 1;
                    }
                } else {
                    if data == DONE {
                        self.brd_handle_bar_patrons(BRD_PATRON_PISSED);
                    }
                    if let Some(s) = self.blackrock_depths_mut() {
                        s.encounter[2] = data;
                    }
                }
            }
            BRD_TYPE_TOMB_OF_SEVEN => {
                match data {
                    IN_PROGRESS => {
                        let gate = self
                            .blackrock_depths()
                            .map_or(ObjectGuid::EMPTY, |s| s.tomb_enter);
                        if gate != ObjectGuid::EMPTY {
                            self.use_door(gate);
                        }
                    }
                    BRD_FAIL => {
                        // Prevent use more than one time (cpp 807).
                        if self.brd_get_data(BRD_TYPE_TOMB_OF_SEVEN) == Some(IN_PROGRESS) {
                            let gate = self
                                .blackrock_depths()
                                .map_or(ObjectGuid::EMPTY, |s| s.tomb_enter);
                            if gate != ObjectGuid::EMPTY {
                                self.use_door(gate);
                            }
                        }
                    }
                    DONE => {
                        // `DoRespawnGameObject(m_uiSevensChestGUID, HOUR)`:
                        // no gameobject-respawn helper (unresolved).
                        let exit = self
                            .blackrock_depths()
                            .map_or(ObjectGuid::EMPTY, |s| s.tomb_exit);
                        if exit != ObjectGuid::EMPTY {
                            self.use_door(exit);
                        }
                        let enter = self
                            .blackrock_depths()
                            .map_or(ObjectGuid::EMPTY, |s| s.tomb_enter);
                        if enter != ObjectGuid::EMPTY {
                            self.use_door(enter);
                        }
                    }
                    _ => {}
                }
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[3] = data;
                }
            }
            BRD_TYPE_LYCEUM => {
                // `if (uiData == IN_PROGRESS && GetData(TYPE_LYCEUM) == DONE)
                // uiData = DONE` (cpp 819-820).
                let mut data = data;
                if data == IN_PROGRESS && self.brd_get_data(BRD_TYPE_LYCEUM) == Some(DONE) {
                    data = DONE;
                }
                if data == DONE {
                    let golem_n = self
                        .blackrock_depths()
                        .map_or(ObjectGuid::EMPTY, |s| s.golem_n);
                    if golem_n != ObjectGuid::EMPTY {
                        // `DoOpenDoor`.
                        self.use_door(golem_n);
                    }
                    let golem_s = self
                        .blackrock_depths()
                        .map_or(ObjectGuid::EMPTY, |s| s.golem_s);
                    if golem_s != ObjectGuid::EMPTY {
                        self.use_door(golem_s);
                    }
                    // `SetRespawnDelay(4 * DAY)` over the 8901 Anvilrage grid
                    // list (cpp 827-833): no respawn-delay helper (unresolved).
                    // Reachable part: Magmus is present and yells.
                    let magmus = self
                        .blackrock_depths()
                        .map_or(ObjectGuid::EMPTY, |s| s.magmus);
                    if self.creatures.contains_key(&magmus) {
                        self.do_script_text(BRD_YELL_MAGMUS, magmus, None, -1);
                    }
                }
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[4] = data;
                }
            }
            BRD_TYPE_IRON_HALL => {
                match data {
                    IN_PROGRESS => {
                        // `DoResetDoor` closes; `use_door` only opens, so
                        // write READY (uld/sch precedent).
                        for slot in [0, 1] {
                            let door = self.blackrock_depths().map_or(ObjectGuid::EMPTY, |s| {
                                if slot == 0 { s.golem_n } else { s.golem_s }
                            });
                            if door != ObjectGuid::EMPTY && self.go_state(door) == GO_STATE_ACTIVE {
                                let _ = self.object_set_field(
                                    door,
                                    u32::from(offsets::GAMEOBJECT_STATE),
                                    GO_STATE_READY,
                                );
                            }
                        }
                    }
                    BRD_FAIL => {
                        let golem_n = self
                            .blackrock_depths()
                            .map_or(ObjectGuid::EMPTY, |s| s.golem_n);
                        if golem_n != ObjectGuid::EMPTY {
                            self.use_door(golem_n);
                        }
                        let golem_s = self
                            .blackrock_depths()
                            .map_or(ObjectGuid::EMPTY, |s| s.golem_s);
                        if golem_s != ObjectGuid::EMPTY {
                            self.use_door(golem_s);
                        }
                    }
                    DONE => {
                        let golem_n = self
                            .blackrock_depths()
                            .map_or(ObjectGuid::EMPTY, |s| s.golem_n);
                        if golem_n != ObjectGuid::EMPTY {
                            self.use_door(golem_n);
                        }
                        let golem_s = self
                            .blackrock_depths()
                            .map_or(ObjectGuid::EMPTY, |s| s.golem_s);
                        if golem_s != ObjectGuid::EMPTY {
                            self.use_door(golem_s);
                        }
                        let throne = self
                            .blackrock_depths()
                            .map_or(ObjectGuid::EMPTY, |s| s.throne);
                        if throne != ObjectGuid::EMPTY {
                            self.use_door(throne);
                        }
                        // `ReplacePrincessIfPossible()` (cpp 743-765): player
                        // iteration + quest-status check + `UpdateEntry` have
                        // no helpers (unresolved).
                    }
                    _ => {}
                }
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[5] = data;
                }
            }
            BRD_TYPE_THUNDERBREW => {
                if data == IN_PROGRESS {
                    let done = if let Some(s) = self.blackrock_depths_mut() {
                        s.thunderbrew_count += 1;
                        s.thunderbrew_count == 3
                    } else {
                        false
                    };
                    if done {
                        if let Some(s) = self.blackrock_depths_mut() {
                            s.encounter[6] = DONE;
                        }
                    }
                }
            }
            BRD_TYPE_RELIC_COFFER => {
                if data == IN_PROGRESS {
                    let done = if let Some(s) = self.blackrock_depths_mut() {
                        s.relic_coffer_door_count += 1;
                        s.relic_coffer_door_count == 12
                    } else {
                        false
                    };
                    if done {
                        if let Some(s) = self.blackrock_depths_mut() {
                            s.encounter[7] = DONE;
                        }
                    }
                }
            }
            BRD_TYPE_DOOMGRIP => {
                if data == DONE {
                    let door = self
                        .blackrock_depths()
                        .map_or(ObjectGuid::EMPTY, |s| s.secret_door);
                    if door != ObjectGuid::EMPTY {
                        self.use_door(door);
                    }
                }
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[8] = data;
                }
            }
            BRD_TYPE_RIBBLY => {
                if data == DONE {
                    let cronies = self
                        .blackrock_depths()
                        .map_or(Vec::new(), |s| s.ribbly_cronies.clone());
                    for guid in cronies {
                        if !self.unit_is_alive(guid) {
                            continue;
                        }
                        let _ = self.object_set_field(
                            guid,
                            u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                            14,
                        );
                        // `Unit* pVictim = pCreature->GetVictim()` (cpp 888).
                        if let Some(victim) =
                            self.creatures.get(&guid).and_then(|c| c.unit.melee_victim)
                        {
                            self.attack_start(guid, victim);
                        }
                    }
                }
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[9] = data;
                }
            }
            BRD_DATA_ARGELMACH_AGGRO => {
                if data == IN_PROGRESS {
                    let argelmach = self
                        .blackrock_depths()
                        .map_or(ObjectGuid::EMPTY, |s| s.golem_lord_argelmach);
                    let victim = self
                        .creatures
                        .get(&argelmach)
                        .and_then(|c| c.unit.melee_victim);
                    if let Some(victim) = victim {
                        let argelmach_pos = self.object_position(argelmach);
                        let protectors = self
                            .blackrock_depths()
                            .map_or(Vec::new(), |s| s.argelmach_protectors.clone());
                        for guid in protectors {
                            let in_range = argelmach_pos.is_some_and(|a| {
                                self.object_position(guid)
                                    .is_some_and(|p| crate::visibility::dist3d(a, p) <= 80.0)
                            });
                            if in_range && self.unit_is_alive(guid) {
                                self.attack_start(guid, victim);
                            }
                        }
                    }
                }
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[10] = data;
                }
            }
            BRD_TYPE_PATROL => {
                if data == IN_PROGRESS {
                    self.brd_handle_bar_patrol(0);
                }
                // Fork stores `TYPE_PATROL` (31) at raw index 11 (cpp 912).
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[11] = data;
                }
            }
            BRD_DATA_THELDREN => {
                if data == DONE {
                    // Kill-credit loop over players + `DoRespawnGameObject`
                    // (arena spoils) (cpp 917-927): no player-iteration or
                    // gameobject-respawn helpers (unresolved).
                }
                // Fork stores `DATA_THELDREN` (30) at raw index 12 (cpp 928).
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[12] = data;
                }
            }
            BRD_TYPE_NAGMARA => {
                // Fork stores `TYPE_NAGMARA` (32) at raw index 13 (cpp 931).
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[13] = data;
                }
            }
            BRD_TYPE_BRIDGE => {
                // Fork stores `TYPE_BRIDGE` (33) at raw index 14 (cpp 934).
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[14] = data;
                }
            }
            BRD_TYPE_PLUGGER => {
                // `if (uiData == SPECIAL)` ale-theft counting (cpp 937-945).
                let mut data = data;
                if data == BRD_SPECIAL {
                    let plugger = self
                        .brd_get_data64(BRD_DATA_PLUGGER)
                        .unwrap_or(ObjectGuid::EMPTY);
                    if !plugger.is_empty() && self.creatures.contains_key(&plugger) {
                        let count = if let Some(s) = self.blackrock_depths_mut() {
                            s.stolen_ales += 1;
                            s.stolen_ales
                        } else {
                            0
                        };
                        if count == 3 {
                            data = IN_PROGRESS;
                        }
                    }
                }
                // Fork stores `TYPE_PLUGGER` (34) at raw index 15 (cpp 946).
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[15] = data;
                }
            }
            BRD_TYPE_QUEST_JAIL_BREAK => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[16] = data;
                }
            }
            BRD_TYPE_JAIL_DUGHAL => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[17] = data;
                }
            }
            BRD_TYPE_JAIL_SUPPLY_ROOM => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[18] = data;
                }
            }
            BRD_TYPE_JAIL_TOBIAS => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[19] = data;
                }
            }
            BRD_GO_JAIL_DOOR_DUGHAL => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.door_dughal_opened = data != 0;
                }
            }
            BRD_GO_JAIL_DOOR_TOBIAS => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.door_tobias_opened = data != 0;
                }
            }
            BRD_GO_JAIL_DOOR_CREST => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.door_crest_opened = data != 0;
                }
            }
            BRD_GO_JAIL_DOOR_JAZ => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.door_jaz_opened = data != 0;
                }
            }
            BRD_GO_JAIL_DOOR_SHILL => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.door_shill_opened = data != 0;
                }
            }
            BRD_GO_JAIL_DOOR_SUPPLY => {
                if let Some(s) = self.blackrock_depths_mut() {
                    s.door_supply_opened = data != 0;
                }
            }
            BRD_EVENT_BAR_PATRONS => {
                self.brd_handle_bar_patrons(data);
            }
            BRD_TYPE_FLAMELASH => {
                if data == BRD_NOT_STARTED || data == BRD_FAIL || data == DONE {
                    for i in 0..BRD_DWARF_RUNES_MAX {
                        let rune = self
                            .blackrock_depths()
                            .map_or(ObjectGuid::EMPTY, |s| s.dwarf_runes[i]);
                        // `ResetDoorOrButton()`: close; `use_door` only opens.
                        if rune != ObjectGuid::EMPTY && self.go_state(rune) == GO_STATE_ACTIVE {
                            let _ = self.object_set_field(
                                rune,
                                u32::from(offsets::GAMEOBJECT_STATE),
                                GO_STATE_READY,
                            );
                        }
                    }
                    if let Some(s) = self.blackrock_depths_mut() {
                        s.spirit_timers = [5_000; BRD_DWARF_RUNES_MAX];
                    }
                    let spirits = self
                        .blackrock_depths()
                        .map_or(Vec::new(), |s| s.burning_spirits.clone());
                    for guid in spirits {
                        let in_combat = self.ai_in_combat(guid);
                        // Missing objects read as not-in-combat, like the
                        // fork's `GetCreature` null path.
                        if !in_combat || data != DONE {
                            // `DespawnOrUnsummon()`.
                            self.despawn_creature_now(guid, 0);
                        }
                        if let Some(s) = self.blackrock_depths_mut() {
                            s.burning_spirits.retain(|g| *g != guid);
                        }
                    }
                } else if data == IN_PROGRESS {
                    for i in 0..BRD_DWARF_RUNES_MAX {
                        let rune = self
                            .blackrock_depths()
                            .map_or(ObjectGuid::EMPTY, |s| s.dwarf_runes[i]);
                        if rune != ObjectGuid::EMPTY {
                            self.use_door(rune);
                        }
                    }
                }
                if let Some(s) = self.blackrock_depths_mut() {
                    s.encounter[20] = data;
                }
            }
            _ => return false,
        }
        // Fork `if (uiData == DONE)` save shape (cpp 1014-1025): separator
        // form over indices 0-19, so no trailing space.
        if data == DONE
            && let Some(s) = self.blackrock_depths_mut()
        {
            let e = s.encounter;
            s.save_string = format!(
                "{} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {}",
                e[0],
                e[1],
                e[2],
                e[3],
                e[4],
                e[5],
                e[6],
                e[7],
                e[8],
                e[9],
                e[10],
                e[11],
                e[12],
                e[13],
                e[14],
                e[15],
                e[16],
                e[17],
                e[18],
                e[19]
            );
        }
        true
    }

    /// `instance_blackrock_depths::GetData` (cpp 1048-1111).
    pub(crate) fn brd_get_data(&self, field: u32) -> Option<u32> {
        let s = self.blackrock_depths()?;
        match field {
            BRD_TYPE_RING_OF_LAW => Some(s.encounter[0]),
            BRD_TYPE_VAULT => Some(s.encounter[1]),
            BRD_TYPE_ROCKNOT => {
                // `if (m_auiEncounter[2] == IN_PROGRESS && m_uiBarAleCount == 3)
                // return SPECIAL` (cpp 1057-1060).
                if s.encounter[2] == IN_PROGRESS && s.bar_ale_count == 3 {
                    Some(BRD_SPECIAL)
                } else {
                    Some(s.encounter[2])
                }
            }
            BRD_TYPE_TOMB_OF_SEVEN => Some(s.encounter[3]),
            BRD_TYPE_LYCEUM => Some(s.encounter[4]),
            BRD_TYPE_IRON_HALL => Some(s.encounter[5]),
            BRD_TYPE_THUNDERBREW => Some(s.encounter[6]),
            BRD_TYPE_RELIC_COFFER => Some(s.encounter[7]),
            BRD_TYPE_DOOMGRIP => Some(s.encounter[8]),
            BRD_TYPE_RIBBLY => Some(s.encounter[9]),
            BRD_DATA_ARGELMACH_AGGRO => Some(s.encounter[10]),
            BRD_TYPE_PATROL => Some(s.encounter[11]),
            BRD_DATA_THELDREN => Some(s.encounter[12]),
            BRD_TYPE_NAGMARA => Some(s.encounter[13]),
            BRD_TYPE_BRIDGE => Some(s.encounter[14]),
            BRD_TYPE_PLUGGER => Some(s.encounter[15]),
            BRD_TYPE_QUEST_JAIL_BREAK => Some(s.encounter[16]),
            BRD_TYPE_JAIL_DUGHAL => Some(s.encounter[17]),
            BRD_TYPE_JAIL_SUPPLY_ROOM => Some(s.encounter[18]),
            BRD_TYPE_JAIL_TOBIAS => Some(s.encounter[19]),
            BRD_GO_JAIL_DOOR_DUGHAL => Some(u32::from(s.door_dughal_opened)),
            BRD_GO_JAIL_DOOR_TOBIAS => Some(u32::from(s.door_tobias_opened)),
            BRD_GO_JAIL_DOOR_CREST => Some(u32::from(s.door_crest_opened)),
            BRD_GO_JAIL_DOOR_JAZ => Some(u32::from(s.door_jaz_opened)),
            BRD_GO_JAIL_DOOR_SHILL => Some(u32::from(s.door_shill_opened)),
            BRD_GO_JAIL_DOOR_SUPPLY => Some(u32::from(s.door_supply_opened)),
            BRD_TYPE_FLAMELASH => Some(s.encounter[20]),
            _ => None,
        }
    }

    /// `instance_blackrock_depths::GetData64` (cpp 1113-1198). A stored GUID
    /// is returned only when non-empty; the fork returns 0 otherwise.
    pub(crate) fn brd_get_data64(&self, field: u32) -> Option<ObjectGuid> {
        let s = self.blackrock_depths()?;
        let guid = match field {
            BRD_DATA_EMPEROR => s.emperor,
            BRD_DATA_PRINCESS => s.princess,
            BRD_DATA_PHALANX => s.phalanx,
            BRD_DATA_HATEREL => s.haterel,
            BRD_DATA_ANGERREL => s.angerrel,
            BRD_DATA_VILEREL => s.vilerel,
            BRD_DATA_GLOOMREL => s.gloomrel,
            BRD_DATA_SEETHREL => s.seethrel,
            BRD_DATA_DOOMREL => s.doomrel,
            BRD_DATA_DOPEREL => s.doperel,
            BRD_DATA_ARENA1 => s.arena_door_1,
            BRD_DATA_ARENA2 => s.arena_door_2,
            BRD_DATA_ARENA3 => s.arena_door_3,
            BRD_DATA_ARENA4 => s.arena_door_4,
            BRD_DATA_GO_BAR_KEG => s.bar_keg,
            BRD_DATA_GO_BAR_KEG_TRAP => s.bar_keg_trap,
            BRD_DATA_GO_BAR_DOOR => s.bar_door,
            BRD_DATA_GO_CHALICE => s.spectral_chalice,
            BRD_DATA_GO_TOMB_EXIT => s.tomb_exit,
            BRD_DATA_ROCKNOT => s.rocknot,
            BRD_DATA_NAGMARA => s.nagmara,
            BRD_DATA_PLUGGER => s.plugger_spazzring,
            BRD_NPC_OGRABISI => s.ograbisi,
            BRD_NPC_SHILL => s.shill,
            BRD_NPC_CREST => s.crest,
            BRD_NPC_JAZ => s.jaz,
            BRD_GO_JAIL_DOOR_SUPPLY => s.jail_supply_room,
            BRD_GO_JAIL_SUPPLY_CRATE => s.jail_supply_crate,
            BRD_GO_DWARF_RUNE_A01 => s.dwarf_runes[0],
            BRD_GO_DWARF_RUNE_B01 => s.dwarf_runes[1],
            BRD_GO_DWARF_RUNE_C01 => s.dwarf_runes[2],
            BRD_GO_DWARF_RUNE_D01 => s.dwarf_runes[3],
            BRD_GO_DWARF_RUNE_E01 => s.dwarf_runes[4],
            BRD_GO_DWARF_RUNE_F01 => s.dwarf_runes[5],
            BRD_GO_DWARF_RUNE_G01 => s.dwarf_runes[6],
            BRD_DATA_ARENA_CHALLENGER => s.challenger_player,
            BRD_NPC_GRIMSTONE => s.grimstone,
            _ => return None,
        };
        (!guid.is_empty()).then_some(guid)
    }

    /// `instance_blackrock_depths::Update` (cpp 1200-1271).
    fn brd_update(&mut self, diff_ms: u32) {
        if self.blackrock_depths().map_or(0, |s| s.dagran_timer_ms) != 0 {
            let timer = self.blackrock_depths().map_or(0, |s| s.dagran_timer_ms);
            if let Some(s) = self.blackrock_depths_mut() {
                s.dagran_timer_ms = timer.saturating_sub(diff_ms);
            }
        }

        // Every second some patrons do one random emote if not hostile
        // (cpp 1210-1220); the re-arm is 1250 ms while `Initialize` sets 2000.
        if self
            .blackrock_depths()
            .map_or(0, |s| s.patron_emote_timer_ms)
            != 0
        {
            let timer = self
                .blackrock_depths()
                .map_or(0, |s| s.patron_emote_timer_ms);
            if timer <= diff_ms {
                self.brd_handle_bar_patrons(BRD_PATRON_EMOTE);
                if let Some(s) = self.blackrock_depths_mut() {
                    s.patron_emote_timer_ms = 1250;
                }
            } else if let Some(s) = self.blackrock_depths_mut() {
                s.patron_emote_timer_ms = timer - diff_ms;
            }
        }

        if self.blackrock_depths().map_or(0, |s| s.patrol_timer_ms) != 0 {
            let timer = self.blackrock_depths().map_or(0, |s| s.patrol_timer_ms);
            if timer <= diff_ms {
                match self.brd_get_data(BRD_TYPE_PATROL) {
                    Some(IN_PROGRESS) => self.brd_handle_bar_patrol(1),
                    Some(BRD_SPECIAL) => self.brd_handle_bar_patrol(2),
                    _ => {}
                }
            } else if let Some(s) = self.blackrock_depths_mut() {
                s.patrol_timer_ms = timer - diff_ms;
            }
        }

        if self.brd_get_data(BRD_TYPE_FLAMELASH) == Some(IN_PROGRESS) {
            for i in 0..BRD_DWARF_RUNES_MAX {
                let timer = self.blackrock_depths().map_or(0, |s| s.spirit_timers[i]);
                if timer < diff_ms {
                    let flamelash = self
                        .blackrock_depths()
                        .map_or(ObjectGuid::EMPTY, |s| s.flamelash);
                    if self.creatures.contains_key(&flamelash) {
                        let rune = self
                            .blackrock_depths()
                            .map_or(ObjectGuid::EMPTY, |s| s.dwarf_runes[i]);
                        if let Some(rune_pos) = self.object_position(rune) {
                            let count = self
                                .blackrock_depths()
                                .map_or(0, |s| s.burning_spirits.len());
                            if count < BRD_BURNING_SPIRIT_MAX {
                                // `GetMap()->SummonCreature(..., TEMPSUMMON_
                                // TIMED_OR_DEAD_DESPAWN, 60000)` (cpp 1254).
                                if let Some(spirit) = self.summon_creature(
                                    BRD_NPC_BURNING_SPIRIT,
                                    rune_pos,
                                    flamelash,
                                    BRD_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
                                    60_000,
                                ) {
                                    // `SetWalk(false)` = run.
                                    self.set_walk(spirit, false);
                                    // `MoveFollow(pFlamelash, 0, 0)`
                                    // (cpp 1257): no follow helper (unresolved).
                                    if let Some(s) = self.blackrock_depths_mut() {
                                        if !s.burning_spirits.contains(&spirit) {
                                            s.burning_spirits.push(spirit);
                                        }
                                    }
                                    let delay = self.spell_rng().irand(15_000, 30_000) as u32;
                                    if let Some(s) = self.blackrock_depths_mut() {
                                        s.spirit_timers[i] = delay;
                                    }
                                }
                            } else if let Some(s) = self.blackrock_depths_mut() {
                                s.spirit_timers[i] = 1_000;
                            }
                        }
                    }
                } else if let Some(s) = self.blackrock_depths_mut() {
                    s.spirit_timers[i] -= diff_ms;
                }
            }
        }
    }

    /// `instance_blackrock_depths::Save` (cpp 1273): the cached string,
    /// refreshed in `brd_set_data` whenever the passed-in data is DONE.
    fn brd_save(&self) -> Option<String> {
        self.blackrock_depths().map(|s| s.save_string.clone())
    }

    /// `instance_blackrock_depths::Load` (cpp 1275-1293). Only the first 20
    /// values are streamed (flamelash keeps its `Initialize` value); every
    /// `IN_PROGRESS` entry resets to `NOT_STARTED`. The C++ null-`in` check
    /// has no Rust equivalent (`&str` is never null).
    fn brd_load(&mut self, data: &str) {
        let mut loaded = [0u32; BRD_MAX_ENCOUNTER];
        for (slot, tok) in loaded.iter_mut().zip(data.split_whitespace()) {
            *slot = tok.parse().unwrap_or(0);
        }
        for value in &mut loaded {
            if *value == IN_PROGRESS {
                *value = BRD_NOT_STARTED;
            }
        }
        if let Some(s) = self.blackrock_depths_mut() {
            s.encounter = loaded;
        }
    }

    // ------------------------------------------------ instance: dire maul

    /// `instance_dire_maul::OnCreatureCreate` (cpp 192-239).
    fn dm_on_creature_create(&mut self, guid: ObjectGuid) {
        let Some(entry) = self.object_entry(guid) else {
            return;
        };
        match entry {
            DM_NPC_IMMOL_THAR => {
                if let Some(s) = self.dire_maul_mut() {
                    s.immol_thar = guid;
                }
                // Fork `SetFlag`s while the cristal event is
                // unfinished (cpp 198-200).
                if self.dm_get_data(DM_TYPE_CRISTAL_EVENT) != Some(DONE) {
                    self.dm_set_unit_flag(guid, DM_UNIT_FLAG_NOT_SELECTABLE);
                    self.dm_set_unit_flag(guid, DM_UNIT_FLAG_SPAWNING);
                }
            }
            DM_NPC_TORTHELDRIN => {
                if let Some(s) = self.dire_maul_mut() {
                    s.tortheldrin = guid;
                }
            }
            DM_NPC_RESTE_MANA | DM_NPC_ARCANE_ABERRATION => {
                // Create refires on respawn, so dedupe (batch-5 rule).
                let known = self
                    .dire_maul()
                    .is_some_and(|s| s.cristal_mobs.contains(&guid));
                if !known {
                    if let Some(s) = self.dire_maul_mut() {
                        s.cristal_mobs.push(guid);
                    }
                }
            }
            DM_NPC_IMMOL_THAR_GARDIEN => {
                let known = self
                    .dire_maul()
                    .is_some_and(|s| s.immol_thar_gardiens.contains(&guid));
                if !known {
                    if let Some(s) = self.dire_maul_mut() {
                        s.immol_thar_gardiens.push(guid);
                    }
                }
            }
            DM_NPC_GUARD_SLIPKIK => {
                if let Some(s) = self.dire_maul_mut() {
                    s.slipkik = guid;
                }
            }
            DM_NPC_KING_GORDOK => {
                if let Some(s) = self.dire_maul_mut() {
                    s.king_gordok = guid;
                }
            }
            DM_NPC_CHORUSH => {
                if let Some(s) = self.dire_maul_mut() {
                    s.chorush = guid;
                }
                if self.dm_get_data(DM_TYPE_GORDOK_TRIBUTE) == Some(DONE) {
                    let _ = self.object_set_field(
                        guid,
                        u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                        35,
                    );
                    // `SetStandState(UNIT_STAND_STATE_SIT)` (== 1).
                    self.unit_set_byte(guid, offsets::UNIT_FIELD_BYTES_1, 0, 1);
                }
            }
            _ => {}
        }
    }

