    /// `GOHello_go_cat_figurine` (cpp 45-49): summon the ghost saber on
    /// the player (triggered); always falls through to the default use.
    fn go_hello_cat_figurine(&mut self, player: ObjectGuid, go: ObjectGuid) -> bool {
        let _ = go;
        let _ = self.cast_spell(
            player,
            CATFIG_SPELL_SUMMON_GHOST_SABER,
            CastTarget::SelfCast,
            CastOptions {
                triggered: true,
                triggered_by_aura: false,
                skip_known: true,
                cast_item: None,
                custom_base_points: [None; 3],
                triggered_by_aura_spell: 0,
                triggered_by_spell: 0,
            },
        );
        false
    }

    /// `GOHello_go_field_repair_bot_74A` (cpp 56-61): teach spell 22704
    /// via cast 22864. Always consumes the use (`return true`).
    fn go_hello_field_repair_bot_74a(&mut self, player: ObjectGuid, go: ObjectGuid) -> bool {
        let _ = go;
        // Fork `HasSkill(SKILL_ENGINEERING)/GetSkillValueBase >= 300` gate
        // (cpp 58): no skill accessor on `Map` -- NEEDS-MAP-HELPER, see
        // unresolved. The `!HasSpell(22704)` arm is transcribed.
        if !self.player_knows_spell(player, REPAIRBOT_SPELL_TAUGHT) {
            let _ = self.cast_spell(
                player,
                REPAIRBOT_SPELL_TEACH,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: false,
                    triggered_by_aura: false,
                    skip_known: true,
                    cast_item: None,
                    custom_base_points: [None; 3],
                    triggered_by_aura_spell: 0,
                    triggered_by_spell: 0,
                },
            );
        }
        true
    }

    /// `GOHello_go_resonite_cask` (cpp 72-78): goober use summons
    /// Goggeroc at the fork's literal `(0, 0, 0, 0)`; falls through.
    fn go_hello_resonite_cask(&mut self, player: ObjectGuid, go: ObjectGuid) -> bool {
        let _ = player;
        if self
            .gameobjects
            .get(&go)
            .is_some_and(|g| g.info.go_type == RESONITE_GOOBER_TYPE)
        {
            // Fork passes explicit `0.0f` coords (cpp 75), kept literally.
            let at = Position::new(0.0, 0.0, 0.0, 0.0);
            let _ = self.summon_creature(
                RESONITE_NPC_GOGGEROC,
                at,
                go,
                TEMPSUMMON_TIMED_DESPAWN_OUT_OF_COMBAT,
                300_000,
            );
        }
        false
    }

    /// `GOHello_go_silithyste` (cpp 81-101): buff unless present, then
    /// deactivate (despawn the temporary mound). Always consumes the use.
    fn go_hello_silithyste(&mut self, player: ObjectGuid, go: ObjectGuid) -> bool {
        // Fork `HasAura(29519, EFFECT_INDEX_0)` (cpp 84): effect-index
        // nuance dropped, spell-id presence only (uld precedent).
        if self
            .aura_holders(player)
            .iter()
            .any(|h| h.spell_id == SILITHYSTE_SPELL_SILITHYST)
        {
            return true;
        }
        let _ = self.cast_spell(
            player,
            SILITHYSTE_SPELL_SILITHYST,
            CastTarget::SelfCast,
            CastOptions {
                triggered: true,
                triggered_by_aura: false,
                skip_known: true,
                cast_item: None,
                custom_base_points: [None; 3],
                triggered_by_aura_spell: 0,
                triggered_by_spell: 0,
            },
        );
        // Fork `sLog` player/session log line (cpp 89): NEEDS-MAP-HELPER
        // (session layer), skipped -- see unresolved.
        if self.object_entry(go) == Some(SILITHYSTE_GO_TEMP_MOUND) {
            // `SetLootState(GO_JUST_DEACTIVATED)` (cpp 95): no loot-state
            // accessor on `Map` (recorded); `AddObjectToRemoveList`
            // (cpp 96) is immediate here, not end-of-tick.
            self.despawn_gameobject_now(go);
        }
        // Else arm (cpp 98-99) is loot-state-only; nothing transcribable.
        true
    }

    /// `go_firework_rocketAI::UpdateAI` (cpp 340-359): single-shot
    /// despawn. Fork `isSpawned()` guard is implicit (map GOs are spawned).
    fn go_ai_firework_rocket_update(
        &mut self,
        go: ObjectGuid,
        state: &mut FireworkRocketGoAi,
        diff_ms: u32,
    ) {
        match state.despawn_timer_ms {
            Some(timer) if timer <= diff_ms => {
                state.despawn_timer_ms = None;
                // `Despawn()` (cpp 352): DB-respawn cycling unmodeled.
                self.despawn_gameobject_now(go);
            }
            Some(timer) => {
                state.despawn_timer_ms = Some(timer - diff_ms);
            }
            None => {}
        }
    }

