    /// `GOHello_go_thunderbrew_laguer_keg` (blackrock_depths.cpp:1197-1234):
    /// the third keg use completes `TYPE_THUNDERBREW` (counted in
    /// `brd_set_data`) and ambushes with Hurley + four cronies.
    #[allow(clippy::cast_precision_loss)] // fork urand jitter
    fn go_hello_thunderbrew_laguer_keg(&mut self, player: ObjectGuid, go: ObjectGuid) -> bool {
        let _ = go;
        if self.blackrock_depths().is_none() {
            return true;
        }
        if self.instance_get_data(BRD_TYPE_THUNDERBREW) == Some(DONE) {
            return false;
        }
        if self.instance_get_data(BRD_TYPE_THUNDERBREW) == Some(BRD_NOT_STARTED) {
            self.instance_set_data(BRD_TYPE_THUNDERBREW, IN_PROGRESS);
        }
        if self.instance_get_data(BRD_TYPE_THUNDERBREW) == Some(DONE) {
            // `SummonCreature(NPC_HURLEY, 856.087, -149.747, -49.672,
            // 0.059, TEMPSUMMON_TIMED_OR_DEAD_DESPAWN, 300000)` (cpp 1213).
            let Some(hurley) = self.summon_creature(
                TB_NPC_HURLEY,
                Position::new(856.087, -149.747, -49.672, 0.059),
                player,
                BRD_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
                300_000,
            ) else {
                return true;
            };
            // `SetWalk(false)` runs; `GetMotionMaster()->Clear(false,
            // true)` (cpp 1218) has no helper. `MoveWaypoint(0, 0, 1000,
            // 0, 0, false)` (cpp 1219) has no waypoint-path helper; the
            // entry waypoint lookup approximates (brs precedent).
            self.set_walk(hurley, false);
            self.creature_move_waypoint(hurley, 0, true);
            // Four cronies around Hurley (cpp 1222-1230).
            for _ in 0..4 {
                // `GetRandomPoint(856.087, -149.747, -49.672, 2.0f)`
                // (cpp 1225): no random-point helper; `irand` jitter
                // approximates (strat precedent).
                let jx = self.spell_rng().irand(-20, 20) as f32 / 10.0;
                let jy = self.spell_rng().irand(-20, 20) as f32 / 10.0;
                let at = Position::new(856.087 + jx, -149.747 + jy, -49.672, 0.059);
                if self
                    .summon_creature(
                        TB_NPC_HURLEY_CRONY,
                        at,
                        player,
                        BRD_TEMPSUMMON_DEAD_DESPAWN,
                        0,
                    )
                    .is_some()
                {
                    // `JoinCreatureGroup(pHurley, 3.0, i * (M_PI_F /
                    // 2.0f), OPTION_FORMATION_MOVE | OPTION_AGGRO_TOGETHER
                    // | OPTION_EVADE_TOGETHER)` (cpp 1228): no group helper
                    // (unresolved).
                }
            }
        }
        false
    }

    /// `GOHello_go_relic_coffer_door` (blackrock_depths.cpp:1245-1269):
    /// counts the coffer door toward `TYPE_RELIC_COFFER` (DONE at 12 in
    /// `brd_set_data`); when DONE, Ruinepoigne attacks the user.
    fn go_hello_relic_coffer_door(&mut self, player: ObjectGuid, go: ObjectGuid) -> bool {
        let _ = go;
        if self.blackrock_depths().is_none() {
            return true;
        }
        // `GetData != IN_PROGRESS || GetData != DONE` (cpp 1252) is
        // always true; transcribed verbatim.
        if self.instance_get_data(BRD_TYPE_RELIC_COFFER) != Some(IN_PROGRESS)
            || self.instance_get_data(BRD_TYPE_RELIC_COFFER) != Some(DONE)
        {
            self.instance_set_data(BRD_TYPE_RELIC_COFFER, IN_PROGRESS);
        }
        self.instance_set_data(BRD_TYPE_RELIC_COFFER, BRD_SPECIAL);
        if self.instance_get_data(BRD_TYPE_RELIC_COFFER) == Some(DONE) {
            let at = Position::new(819.45, -348.96, -50.49, 0.35);
            if let Some(ruinepoigne) = self.summon_creature(
                RC_RUINEPOIGNE_ENTRY,
                at,
                player,
                BRD_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
                300_000,
            ) {
                // `MonsterYell("Don't let them take the moutain hearth!",
                // 0, pPlayer)` (cpp 1262): literal-text yell has no helper
                // (NEEDS-MAP-HELPER, unresolved).
                self.attack_start(ruinepoigne, player);
            }
        }
        false
    }

    /// `GOUse_go_bar_ale_mug` (registered as `pGOHello`,
    /// blackrock_depths.cpp:1685-1710, 2378-2381): stolen-mug accounting
    /// via `TYPE_PLUGGER`; Plugger warns or attacks the thief.
    fn go_hello_bar_ale_mug(&mut self, player: ObjectGuid, go: ObjectGuid) -> bool {
        let _ = go;
        if self.blackrock_depths().is_none() {
            return false;
        }
        // GOs despawn on use, so this gate should never be true (cpp 1689).
        if matches!(
            self.instance_get_data(BRD_TYPE_PLUGGER),
            Some(IN_PROGRESS | DONE)
        ) {
            return false;
        }
        let plugger = self
            .instance_get_data64(BRD_DATA_PLUGGER)
            .unwrap_or(ObjectGuid::EMPTY);
        if plugger.is_empty() || !self.creatures.contains_key(&plugger) {
            return false;
        }
        // `SetData(TYPE_PLUGGER, SPECIAL)` counts the stolen mug (the
        // instance maps the third theft SPECIAL -> IN_PROGRESS, cpp
        // 1698-1700); `WarnThief` / `AttackThief`
        // (boss_plugger_spazzringAI, cpp 1578-1594, called at cpp
        // 1701-1704) need the unported plugger AI: yell ids 5053/5054/5055
        // + 5060/5267, `SetFacingToObject`, `SetFactionTemporary(54)` and
        // `AttackStart` (unresolved, NEEDS-MAP-HELPER for facing/faction).
        self.instance_set_data(BRD_TYPE_PLUGGER, BRD_SPECIAL);
        if self.instance_get_data(BRD_TYPE_PLUGGER) == Some(IN_PROGRESS) {
            // `pPluggerAI->AttackThief(pPlayer)` (cpp 1702).
            self.attack_start(plugger, player);
        } else {
            // `pPluggerAI->WarnThief(pPlayer)` (cpp 1704): yell + facing
            // only, no combat; unmodeled (unresolved).
        }
        false
    }

    /// `go_cell_doorAI::OnUse` (blackrock_depths.cpp:2255-2269): marks
    /// the jail door entry opened; Crest yells at the CREST door.
    fn go_ai_cell_door_on_use(&mut self, go: ObjectGuid, user: ObjectGuid) -> bool {
        let _ = user;
        if self.blackrock_depths().is_none() {
            return true;
        }
        // `SetData(me->GetEntry(), true)` (cpp 2262): jail-door entries
        // double as instance data fields (`brd_set_data` door arms treat
        // nonzero as opened).
        if let Some(entry) = self.object_entry(go) {
            self.instance_set_data(entry, 1);
        }
        // `GetClosestCreatureWithEntry(me, NPC_CREST, 50.0f)` (cpp 2263).
        let crest = self.object_position(go).and_then(|pos| {
            self.creatures
                .values()
                .filter(|c| c.info.entry == BRD_NPC_CREST)
                .map(|c| {
                    (
                        c.unit.guid(),
                        crate::visibility::dist3d(c.unit.world.position(), pos),
                    )
                })
                .filter(|(_, d)| *d <= 50.0)
                .min_by(|a, b| a.1.total_cmp(&b.1))
                .map(|(g, _)| g)
        });
        if self.object_entry(go) == Some(BRD_GO_JAIL_DOOR_CREST) {
            if let Some(temp) = crest {
                self.do_script_text(CELL_SAY_CREST_KILLER, temp, None, -1);
            }
        }
        false
    }

