    /// `GOOpen_go_stratholme_postbox` (stratholme.cpp:39-67): SPECIAL
    /// summons the postmaster and closes the set; otherwise the set
    /// opens, then three postmen spawn at jittered points near the user.
    #[allow(clippy::cast_precision_loss)] // one fork override port
    fn go_open_stratholme_postbox(&mut self, player: ObjectGuid, go: ObjectGuid) -> bool {
        let _ = go;
        if self.stratholme().is_none() {
            return false;
        }
        if self.instance_get_data(STRAT_TYPE_POSTMASTER) == Some(DONE) {
            return false;
        }
        if self.instance_get_data(STRAT_TYPE_POSTMASTER) == Some(STRAT_SPECIAL) {
            // C++ `pPlayer->CastSpell(pPlayer, SPELL, true)`.
            self.cast_spell(
                player,
                STRAT_SPELL_SUMMON_POSTMASTER,
                CastTarget::Unit(player),
                CastOptions {
                    triggered: true,
                    triggered_by_aura: false,
                    skip_known: true,
                    cast_item: None,
                    custom_base_points: [None; 3],
                    triggered_by_aura_spell: 0,
                    triggered_by_spell: 0,
                },
            );
            self.instance_set_data(STRAT_TYPE_POSTMASTER, DONE);
        } else {
            self.instance_set_data(STRAT_TYPE_POSTMASTER, IN_PROGRESS);
        }
        // C++ `GetRandomPoint(..., 6.0f)` has no `Map` helper; the
        // reachable part uses `irand(0, 2)` square jitter (strat precedent:
        // `strat_spawn_plagued_critters`). C++ orientation is 0.0.
        if let Some(at) = self.object_position(player) {
            for _ in 0..3u8 {
                let jx = self.spell_rng().irand(0, 2) as f32;
                let jy = self.spell_rng().irand(0, 2) as f32;
                self.summon_creature(
                    STRAT_NPC_UNDEAD_POSTMAN,
                    Position::new(at.x + jx, at.y + jy, at.z, 0.0),
                    player,
                    STRAT_TEMPSUMMON_DEAD_DESPAWN,
                    0,
                );
            }
        }
        false
    }

    /// `go_supply_crateAI::OnUse` (stratholme.cpp:602-630): summon
    /// `urand(1, 4)` plagued critters of one `urand(0, 2)` kind at
    /// jittered points near the user, then fall through to default use.
    /// Stateless: the fork struct carries no member state.
    #[allow(clippy::cast_precision_loss)] // one fork override port
    fn go_ai_supply_crate_on_use(&mut self, go: ObjectGuid, user: ObjectGuid) -> bool {
        let _ = go;
        // C++ `maxplagued = urand(1, 4)`; `switch (urand(0, 2))`.
        let count = self.spell_rng().irand(1, 4);
        let entry = match self.spell_rng().irand(0, 2) {
            0 => STRAT_NPC_PLAGUED_RAT,    // case 0: Plagued Rat (10441)
            1 => STRAT_NPC_PLAGUED_INSECT, // case 1: Plagued Insect (10461)
            _ => STRAT_NPC_PLAGUED_MAGGOT, // case 2: Plagued Maggot (10536)
        };
        // C++ `float(urand(0, 2))` offsets; orientation 1.0;
        // `HOUR * IN_MILLISECONDS` = 3_600_000 ms.
        if let Some(at) = self.object_position(user) {
            for _ in 0..count {
                let jx = self.spell_rng().irand(0, 2) as f32;
                let jy = self.spell_rng().irand(0, 2) as f32;
                self.summon_creature(
                    entry,
                    Position::new(at.x + jx, at.y + jy, at.z, 1.0),
                    user,
                    STRAT_TEMPSUMMON_DEAD_DESPAWN,
                    3_600_000,
                );
            }
        }
        // C++ `me->SetLootState(GO_JUST_DEACTIVATED)`: no GO loot-state
        // helper exists (recorded below).
        false
    }

    /// `GO_scarlet_cannon` (boss_cannon_master_willey.cpp:276-281).
