    /// `OnGossipHello_go_shallow_grave` (registered as `pGOOpen`,
    /// `zulfarrak.cpp:485`): roll one grave spawn, then the default use.
    fn go_open_shallow_grave(&mut self, _player: ObjectGuid, go: ObjectGuid) -> bool {
        // Fork `GetUseCount() == 0` gate + `AddUse()` (cpp
        // 488/496): the counter rides the GO AI state
        // (`GoAiState::ShallowGrave`); a missing state
        // counts as first use.
        let first_use = match self.go_ai.get_mut(&go) {
            Some(GoAiState::ShallowGrave { use_count }) => {
                let first = *use_count == 0;
                if first {
                    *use_count += 1;
                }
                first
            }
            _ => true,
        };
        if !first_use {
            return true;
        }
        let roll = self.spell_rng().irand(0, 100) as u32;
        if roll < GRAVE_ZOMBIE_CHANCE {
            if let Some(at) = self.object_position(go) {
                let spawn = Position::new(at.x, at.y, at.z, 0.0);
                let _ = self.summon_creature(
                    GRAVE_ZOMBIE,
                    spawn,
                    go,
                    GRAVE_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
                    30_000,
                );
            }
        } else if roll.wrapping_sub(GRAVE_ZOMBIE_CHANCE) < GRAVE_DEAD_HERO_CHANCE {
            if let Some(at) = self.object_position(go) {
                let spawn = Position::new(at.x, at.y, at.z, 0.0);
                let _ = self.summon_creature(
                    GRAVE_DEAD_HERO,
                    spawn,
                    go,
                    GRAVE_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
                    30_000,
                );
            }
        }
        true
    }

    /// `initBlyCrewMember` (`zulfarrak.cpp:190`): send one freed crew
    /// member to its stair post. `SetCombatStartPosition` (cpp 198) has no
    /// helper (unresolved); home + `MovePoint` + faction are transcribed.
    fn troll_cage_move_crew(&mut self, entry: u32, x: f32, y: f32, z: f32) {
        let Some(crew) = self.instance_get_data64(entry) else {
            return;
        };
        if !self.creatures.contains_key(&crew) {
            return;
        }
        // `SetHomePosition(x, y, z, 4.7f)` (cpp 199): direct field write,
        // same as the `home_position` precedent in `content.rs`.
        let home = Position::new(x, y, z, 4.7);
        if let Some(c) = self.creatures.get_mut(&crew) {
            c.home_position = home;
        }
        // `MovePoint(1, x, y, z, MOVE_PATHFINDING | MOVE_WALK_MODE)`
        // (cpp 200).
        self.creature_move_point(
            crew,
            1,
            home,
            ZF_MOVE_PATHFINDING | ZF_MOVE_WALK_MODE,
            0.0,
            4.7,
        );
        // `SetFactionTemplateId(FACTION_FREED)` (cpp 201).
        let _ = self.object_set_field(
            crew,
            u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
            CAGE_FACTION_FREED,
        );
    }

    /// `OnGossipHello_go_troll_cage` (`zulfarrak.cpp:205`): open the
