    /// Create-time entry fixup for `go_corrupted_plantAI` (ctor,
    /// `felwood.cpp:492-499`): resolve the cleansed entry for a GO
    /// entry. Called from `go_ai_create` once the state exists.
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn corrupted_plant_cleansed_for(entry: u32) -> u32 {
        for (corrupted, cleansed) in CPL_CLEANSED_PAIRS {
            if entry == corrupted || entry == cleansed {
                return cleansed;
            }
        }
        0
    }

    /// `go_corrupted_plantAI::UpdateAI` (`felwood.cpp:506-515`).
    /// `isSpawned()` is implicit for present GOs; the cleansed guid is
    /// cleared even when the cleansed GO is already gone (cpp 513).
    fn go_ai_corrupted_plant_update(
        &mut self,
        _go: ObjectGuid,
        state: &mut CorruptedPlantGoAi,
        _diff_ms: u32,
    ) {
        if state.cleansed_guid == ObjectGuid::EMPTY {
            return;
        }
        // `AddObjectToRemoveList`: DB-respawn cycling of removed GOs is
        // unmodeled (recorded).
        let cleansed = state.cleansed_guid;
        self.despawn_gameobject_now(cleansed);
        state.cleansed_guid = ObjectGuid::EMPTY;
    }

    /// `ossirian_crystalAI::OnUse` (`boss_ossirian.cpp:335-371`).
    /// Stateless (empty ctor, no members). False = fall through to the
    /// default use; true = already used / encounter not started.
    fn go_ai_ossirian_crystal_on_use(&mut self, go: ObjectGuid, _user: ObjectGuid) -> bool {
        if self.ruins_of_ahnqiraj().is_none() {
            // `sLog` error arm (cpp 339-343): no instance.
            return false;
        }
        let Some(go_pos) = self.object_position(go) else {
            return false;
        };
        // Already used: trigger nearby (cpp 346-347).
        let used = self.creatures.values().any(|c| {
            c.info.entry == OSS_CRYSTAL_TRIGGER
                && crate::visibility::dist3d(c.unit.world.position(), go_pos) <= 5.0
        });
        if used {
            return true;
        }
        // NEEDS-MAP-HELPER: `pInstance->SpawnNewCrystals(me->GetObjectGuid())`
        // (cpp 350; `ruins_of_ahnqiraj.h:134`, unported — same gap as the
        // `RuinsOfAhnqirajState` notes).
        // Closest Ossirian within 300 (cpp 352-358; the `GetData64`
        // guid in the log arm has no Rust read).
        let ossirian = self
            .creatures
            .iter()
            .filter(|(_, c)| c.info.entry == AQ20_NPC_OSSIRIAN)
            .map(|(g, c)| {
                (
                    *g,
                    crate::visibility::dist3d(c.unit.world.position(), go_pos),
                )
            })
            .filter(|(_, d)| *d <= 300.0)
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .map(|(g, _)| g);
        let Some(ossirian) = ossirian else {
            // `sLog` error arm (cpp 354-358): no Ossirian found.
            return false;
        };
        // Encounter not started (cpp 361-362; `SelectHostileTarget`'s
        // acquire side effect is not mirrored).
        if self.unit_victim(ossirian).is_none() {
            return true;
        }
        if let Some(trigger) = self.summon_creature(
            OSS_CRYSTAL_TRIGGER,
            go_pos,
            go,
            OSS_TEMPSUMMON_TIMED_DESPAWN,
            OSS_TRIGGER_DESPAWN_MS,
        ) {
            // `SpellWeakness[urand(0, 4)]` (cpp 367); clamped, so the
            // index is always in range.
            let roll = self.spell_rng().irand(0, 4);
            let idx = (roll.clamp(0, 4)) as usize;
            let spell = OSS_SPELL_WEAKNESS[idx];
            let _ = self.cast_spell(
                trigger,
                spell,
                CastTarget::Unit(ossirian),
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
        false
    }

    /// `go_inconspicuous_landmarkAI::UpdateAI` (`tanaris.cpp:210-223`):
    /// 10-minute rearm countdown, then reopen + clear in-use.
    fn go_ai_inconspicuous_landmark_update(
        &mut self,
        go: ObjectGuid,
        state: &mut InconspicuousLandmarkGoAi,
        diff_ms: u32,
    ) {
        if !state.in_use {
            return;
        }
        if state.rearm_timer_ms < diff_ms {
            state.in_use = false;
            let _ = self.object_set_field(go, u32::from(offsets::GAMEOBJECT_STATE), GO_STATE_READY);
            let flags = self.object_get_field(go, offsets::GAMEOBJECT_FLAGS);
            let _ = self.object_set_field(
                go,
                u32::from(offsets::GAMEOBJECT_FLAGS),
                flags & !ILM_GO_FLAG_IN_USE,
            );
        } else {
            state.rearm_timer_ms -= diff_ms;
        }
    }

    /// `GOHello_go_inconspicuous_landmark` (`tanaris.cpp:235-287`).
    /// `CheckCanStartEvent` (cpp 224) / `SetInUse` (cpp 226-232) are
    /// folded in. Always true (default use blocked, cpp 286).
    fn go_hello_inconspicuous_landmark(
        &mut self,
        player: ObjectGuid,
        go: ObjectGuid,
        state: &mut InconspicuousLandmarkGoAi,
    ) -> bool {
        if state.in_use {
            return true;
        }
        // `SetInUse` (cpp 226-232).
        state.in_use = true;
        state.rearm_timer_ms = ILM_REARM_DELAY_MS;
        let _ = self.object_set_field(go, u32::from(offsets::GAMEOBJECT_STATE), GO_STATE_ACTIVE);
        let flags = self.object_get_field(go, offsets::GAMEOBJECT_FLAGS);
        let _ = self.object_set_field(
            go,
            u32::from(offsets::GAMEOBJECT_FLAGS),
            flags | ILM_GO_FLAG_IN_USE,
        );
        let go_type = self
            .gameobjects
            .get(&go)
            .map_or(u32::MAX, |g| g.info.go_type);
        // Quest gate (cpp 245).
        if go_type == ILM_GAMEOBJECT_TYPE_GOOBER && self.player_quest_incomplete(player, 2_882) {
            let pirate_spawns = [
                (
                    ILM_NPC_PIRATES_1,
                    Position::new(-10_119.85, -4_068.36, 4.55, 1.35),
                ),
                (
                    ILM_NPC_PIRATES_2,
                    Position::new(-10_109.8, -4_054.45, 5.64, 3.17),
                ),
                (
                    ILM_NPC_PIRATES_3,
                    Position::new(-10_127.8, -4_047.04, 4.50, 5.07),
                ),
            ];
            for (entry, at) in pirate_spawns {
                if let Some(pirate) = self.summon_creature(
                    entry,
                    at,
                    go,
                    ILM_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
                    ILM_PIRATE_DESPAWN_MS,
                ) {
                    self.attack_start(pirate, player);
                }
            }
            // `extraPirateType` rolls (cpp 263-277).
            let mut extra = [ILM_NPC_PIRATES_1, ILM_NPC_PIRATES_2];
            for slot in &mut extra {
                *slot = match self.spell_rng().irand(0, 2) {
                    0 => ILM_NPC_PIRATES_1,
                    1 => ILM_NPC_PIRATES_2,
                    _ => ILM_NPC_PIRATES_3,
                };
            }
            let extra_spawns = [
                Position::new(-10_113.952, -4_040.484_4, 5.174_251, 4.300_828),
                Position::new(-10_136.779, -4_063.175, 4.787_039, 0.526_417),
            ];
            for (entry, at) in extra.iter().zip(extra_spawns) {
                if let Some(pirate) = self.summon_creature(
                    *entry,
                    at,
                    go,
                    ILM_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
                    ILM_PIRATE_DESPAWN_MS,
                ) {
                    self.attack_start(pirate, player);
                }
            }
        }
        true
    }

    /// `go_panther_cage` (`thousand_needles.cpp:312-326`). Stateless
    /// (no GOAI). False = the cage opens via default use (cpp 324-325).
    fn go_hello_panther_cage(&mut self, player: ObjectGuid, go: ObjectGuid) -> bool {
        // Quest gate (cpp 314).
        if self.player_quest_incomplete(player, 5_151)
            && let Some(go_pos) = self.object_position(go)
        {
            let panther = self
                .creatures
                .iter()
                .filter(|(_, c)| c.info.entry == PC_ENRAGED_PANTHER && c.unit.is_alive())
                .map(|(g, c)| {
                    (
                        *g,
                        crate::visibility::dist3d(c.unit.world.position(), go_pos),
                    )
                })
                .filter(|(_, d)| *d <= 5.0)
                .min_by(|a, b| a.1.total_cmp(&b.1))
                .map(|(g, _)| g);
            if let Some(panther) = panther {
                let flags = self.object_get_field(panther, offsets::UNIT_FIELD_FLAGS);
                let _ = self.object_set_field(
                    panther,
                    u32::from(offsets::UNIT_FIELD_FLAGS),
                    flags & !(PC_UNIT_FLAG_SPAWNING | PC_UNIT_FLAG_IMMUNE_TO_PLAYER),
                );
                self.attack_start(panther, player);
            }
        }
        false
    }

    // ------------------------------------------------ go scripts: world events

    /// `elemental_invasion_riftAI::UpdateAI` head (cpp 83-91, 121-123):
    /// the free-running `m_uiIncreaseTimer` countdown and the 70s
    /// `m_uiTimer` reload. Covers all four rift scripts
    /// (`GetAI_go_elemental_invasion_rift_fire/water/earth/air`, cpp 127-133,
    /// single shared class with `EVENT_IND_*` index 0/1/2/3).
    fn go_ai_elemental_invasion_rift_update(
        &mut self,
        go: ObjectGuid,
        state: &mut ElementalInvasionRiftGoAi,
        diff_ms: u32,
    ) {
        // `m_uiIncreaseTimer` (cpp 85-86; the fork never zeroes it, it only
        // stops subtracting once below `uiDiff`).
        if state.increase_timer_ms > diff_ms {
            state.increase_timer_ms -= diff_ms;
        }
        // `m_uiTimer` (cpp 88-91, 121-123): 500ms first tick, then 70s.
        if state.timer_ms >= diff_ms {
            state.timer_ms -= diff_ms;
            return;
        }
        state.timer_ms = WE_RIFT_UPDATE_INTERVAL_MS;
        // `IsActiveEvent(InvasionData[event].event)` (cpp 94-95): game events
        // are unmodeled on `Map` (see unresolved). The tick below is the
        // event-active path; integration must gate this call on the event
        // system before wiring it into `go_ai_update`.
        self.go_ai_elemental_invasion_rift_tick(go, state);
    }

    /// Rift tick: the event-active arm of `UpdateAI` (cpp 97-120).
    fn go_ai_elemental_invasion_rift_tick(
        &mut self,
        go: ObjectGuid,
        state: &mut ElementalInvasionRiftGoAi,
    ) {
        // `me->GetZoneId() != InvasionData[...].zone` (cpp 97-99).
        let zone = self
            .object_position(go)
            .map(|pos| self.zone_and_area_id(pos).0);
        if zone != Some(state.zone) {
            return;
        }
        // `GetSavedVariable(varDeadInvaders)/GetSavedVariable(varStage)` and
        // the stage-up/`SetSavedVariable` block (cpp 101-111): no
        // saved-variable accessor on `Map` (NEEDS-MAP-HELPER, see
        // unresolved). `spawn_stage` stays at its default 1, so the count
        // below is the stage-1 minimum.
        let spawn_count = (WE_RIFT_MIN_SPAWN + state.spawn_stage.saturating_sub(1))
            .min(WE_RIFT_MAX_SPAWN) as usize;
        // `GetCreature(m_uiInvadersGuid[i])` respawn loop (cpp 116-120),
        // two-phase for borrow order.
        let count = spawn_count.min(state.invaders.len());
        let mut missing = [false; WE_RIFT_MAX_SPAWN as usize];
        for (index, slot) in state.invaders.iter().enumerate().take(count) {
            if slot.is_none_or(|guid| !self.creatures.contains_key(&guid)) {
                missing[index] = true;
            }
        }
        for (index, respawn) in missing.iter().enumerate().take(count) {
            if *respawn {
                self.go_ai_elemental_invasion_rift_spawn(go, state, index);
            }
        }
    }

    /// `elemental_invasion_riftAI::DoSpawn` (cpp 53-81).
    fn go_ai_elemental_invasion_rift_spawn(
        &mut self,
        go: ObjectGuid,
        state: &mut ElementalInvasionRiftGoAi,
        index: usize,
    ) -> bool {
        // `InvasionData[m_uiEventIndex].invader` (cpp 33, 57).
        let entry = match state.event_index {
            WE_EVENT_IND_AIR => WE_RIFT_INVADER_AIR,
            WE_EVENT_IND_EARTH => WE_RIFT_INVADER_EARTH,
            WE_EVENT_IND_WATER => WE_RIFT_INVADER_WATER,
            _ => WE_RIFT_INVADER_FIRE,
        };
        // `me->GetPosition` + `SummonCreature(invader, x, y, z, 0,
        // TEMPSUMMON_TIMED_OR_DEAD_DESPAWN, HOUR * IN_MILLISECONDS)` (cpp 55-57).
        let Some(at) = self.object_position(go) else {
            return false;
        };
        let Some(invader) = self.summon_creature(
            entry,
            at,
            go,
            WE_RIFT_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
            WE_RIFT_HOUR_MS,
        ) else {
            return false;
        };
        // `GetWalkRandomPosition` spread (cpp 63-67): no walk-position helper
        // on `Map` (NEEDS-MAP-HELPER, see unresolved); the summon holds at
        // the rift position.
        // `SetHomePosition` (cpp 70): direct field write
        // (defias-gunpowder precedent).
        if let Some(c) = self.creatures.get_mut(&invader) {
            c.home_position = at;
        }
        // `SetWanderDistance/SetDefaultMovementType/MoveRandom` (cpp 71-77):
        // no wander/motion-master helpers (see unresolved).
        // `m_uiInvadersGuid[index] = ...` (cpp 79), bounds-guarded.
        let Some(slot) = state.invaders.get_mut(index) else {
            return false;
        };
        *slot = Some(invader);
        true
    }

    /// `go_cheer_speakerAI::UpdateAI` timer arms (cpp 140-142, 188-232).
    /// The wall-clock start/stop/big triggers (cpp 144-186) need localtime
    /// plus the game-event system (see unresolved); this transcribes the
    /// `EVENT_CHEER`/`EVENT_FIRE` handlers those triggers arm.
    fn go_ai_cheer_speaker_update(
        &mut self,
        go: ObjectGuid,
        state: &mut CheerSpeakerGoAi,
        diff_ms: u32,
    ) {
        // `m_events.Update(diff)` + `ExecuteEvent` (cpp 142, 188).
        let cheer_due = match state.cheer_timer_ms {
            Some(timer) if timer <= diff_ms => {
                state.cheer_timer_ms = None;
                true
            }
            Some(timer) => {
                state.cheer_timer_ms = Some(timer - diff_ms);
                false
            }
            None => false,
        };
        let fire_due = match state.fire_timer_ms {
            Some(timer) if timer <= diff_ms => {
                state.fire_timer_ms = None;
                true
            }
            Some(timer) => {
                state.fire_timer_ms = Some(timer - diff_ms);
                false
            }
            None => false,
        };
        if cheer_due {
            // `EVENT_CHEER` (cpp 192-196): `me->PlayDistanceSound(CheerPicker())`.
            let sound = self.go_ai_cheer_speaker_cheer_pick();
            self.play_direct_sound(go, sound, None);
        }
        if fire_due {
            // `EVENT_FIRE` (cpp 197-228): the zone-table pick plus
            // `SummonGameObject(entry, rndpos..., 1)` with instant
            // `SetRespawnTime(0)/Delete` (cpp 199-222). There is no
            // gameobject-summon helper on `Map` (NEEDS-MAP-HELPER, see
            // unresolved); the entry pick below is the transcribable head.
            let _firework_entry = if state.big {
                self.go_ai_cheer_speaker_fireworks_big_pick()
            } else {
                self.go_ai_cheer_speaker_fireworks_pick()
            };
            // Re-arm while the show runs (cpp 224-225):
            // `ScheduleEvent(EVENT_FIRE, Seconds(1), Seconds(2))`.
            if state.started {
                state.fire_timer_ms = Some(self.spell_rng().irand(1_000, 2_000) as u32);
            }
        }
    }

    /// `CheerPicker` (cpp 122-134): `urand(0, 3)` over the four sounds.
    fn go_ai_cheer_speaker_cheer_pick(&mut self) -> u32 {
        match self.spell_rng().irand(0, 3) {
            0 => CHEER_SOUND_CHEER_1,
            1 => CHEER_SOUND_CHEER_2,
            2 => CHEER_SOUND_CHEER_3,
            _ => CHEER_SOUND_CHEER_4,
        }
    }

    /// `FireworksPicker` (cpp 136): `SelectRandomContainerElement(fireworkIds)`.
    fn go_ai_cheer_speaker_fireworks_pick(&mut self) -> u32 {
        let bound = 22;
        let index = self.spell_rng().irand(0, bound) as usize;
        CHEER_FIREWORK_IDS
            .get(index)
            .copied()
            .unwrap_or(CHEER_FIREWORK_IDS[0])
    }

    /// `FireworksBIGOnlyPicker` (cpp 138).
    fn go_ai_cheer_speaker_fireworks_big_pick(&mut self) -> u32 {
        let bound = 11;
        let index = self.spell_rng().irand(0, bound) as usize;
        CHEER_FIREWORK_BIG_IDS
            .get(index)
            .copied()
            .unwrap_or(CHEER_FIREWORK_BIG_IDS[0])
    }

    /// `GoCircle` ctor (`scourge_invasion.cpp:259`): `me->CastSpell(me,
    /// SPELL_CREATE_CRYSTAL, true)`. A cast by the gameobject itself has no
    /// GO-caster helper on `Map` (NEEDS-MAP-HELPER, see unresolved); this is
    /// the `go_ai_create` docking point.
    #[allow(clippy::unused_self)]
    fn go_ai_scourge_invasion_go_circle_create(&mut self, go: ObjectGuid) {
        let _ = go;
    }

    /// `GoNecropolis` ctor (`scourge_invasion.cpp:270-274`):
    /// `SetActiveObjectState(true)` + `SetVisibilityModifier(3000.0f)`.
    /// Neither has a `Map` equivalent (NEEDS-MAP-HELPER, see unresolved);
    /// this is the `go_ai_create` docking point.
    #[allow(clippy::unused_self)]
    fn go_ai_scourge_invasion_go_necropolis_create(&mut self, go: ObjectGuid) {
        let _ = go;
    }

    // ------------------------------------------------ gameobject use

    /// `GameObject::Use` subset: GO AI `OnUse`, then
    /// `pGOHello` scripts, then the default
    /// door/button toggle. Called from
    /// `CMSG_GAMEOBJ_USE`.
    pub fn gameobject_use(&mut self, player: ObjectGuid, go_guid: ObjectGuid) {
        let Some(go_pos) = self.object_position(go_guid) else {
            return;
        };
        let Some(player_pos) = self.unit_position(player) else {
            return;
        };
        if crate::visibility::dist2d(player_pos, go_pos) > 10.0 {
            return;
        }
        // BG flag click (`GAMEOBJECT_TYPE_FLAGSTAND` 24 /
        // `FLAGDROP` 26): the fork dispatches inside the
        // type switch after `CanUseBattleGroundObject`.
        // UNMODELED in the gate: mounted/total-immune
        // arms (no mounted/immunity runtime reads here).
        let go_type_pre = self
            .gameobjects
            .get(&go_guid)
            .map_or(u32::MAX, |g| g.info.go_type);
        if (go_type_pre == 24 || go_type_pre == 26) && self.bg.is_some() {
            let sor = self.player_has_spirit_of_redemption(player);
            if !sor {
                self.remove_spells_causing_aura(player, mangos_spells::defines::aura::MOD_STEALTH);
                self.remove_spells_causing_aura(
                    player,
                    mangos_spells::defines::aura::MOD_INVISIBILITY,
                );
                self.bg_event_clicked_on_flag(player, go_guid);
            }
            return;
        }
        if self.go_ai_on_use(player, go_guid) {
            return;
        }
        if self.go_hello(player, go_guid) {
            return;
        }
        // Default door/button toggle subset
        // (`UseDoorOrButton` without the auto-close
        // cooldown / linked-trap tail) + the
        // `sGameObjectScripts` start.
        let go_type = self
            .gameobjects
            .get(&go_guid)
            .map_or(u32::MAX, |g| g.info.go_type);
        if go_type == 0 || go_type == 1 {
            let state = self.go_state(go_guid);
            let next = if state == GO_STATE_READY {
                GO_STATE_ACTIVE
            } else {
                GO_STATE_READY
            };
            let _ = self.object_set_field(go_guid, u32::from(offsets::GAMEOBJECT_STATE), next);
            self.scripts_start_gameobject(go_guid.counter(), player, go_guid);
            return;
        }
        if go_type == 2 {
            // `GAMEOBJECT_TYPE_QUESTGIVER` (`GameObject.cpp:1411`):
            // script hello first; the quest-list send is
            // actor-side in both fork paths (the scarab
            // gong script sends PreparedQuest itself).
            let _handled = self.gossip_script_on_hello_go(player, go_guid);
            self.events.push(crate::map::MapEvent::QuestGiverHello {
                player,
                object: go_guid,
            });
            return;
        }
        if go_type == 10 {
            self.go_use_goober(player, go_guid);
            return;
        }
        if go_type == 13 {
            self.go_use_camera(player, go_guid);
        }
    }

    /// `GAMEOBJECT_TYPE_GOOBER` use subset
    /// (`GameObject::Use`, `GameObject.cpp:1507`):
    /// page text, quest gate, process-event / DB
    /// script start, ACTIVE state. UNMODELED tails:
    /// GO gossip (`goober.gossipID`, no GO gossip
    /// session plumbing), `RewardPlayerAndGroupAtCast`
    /// GO-cast quest credit, linked trap, custom
    /// anim, auto-close/loot-state cooldown, and the
    /// `goober.spellId` GO-cast (GO spell casting is
    /// unmodeled wholesale).
    fn go_use_goober(&mut self, player: ObjectGuid, go_guid: ObjectGuid) {
        let Some(info) = self.gameobjects.get(&go_guid).map(|g| g.info.clone()) else {
            return;
        };
        // `goober.pageId` (data7) -> SMSG_GAMEOBJECT_PAGETEXT.
        if info.data_u32(7) != 0 {
            use mangos_protocol::buffer::PacketWriter;
            let mut writer = PacketWriter::new();
            writer.write_u64_le(go_guid.raw());
            let mut packet = mangos_protocol::world::WorldPacket::new(
                mangos_protocol::opcode_table::opcode_id::SMSG_GAMEOBJECT_PAGETEXT,
            );
            packet.take_writer(writer);
            self.events
                .push(crate::map::MapEvent::Packet { to: player, packet });
        }
        // Quest gate (`goober.questId`, data1): an
        // existing template with the player not on
        // INCOMPLETE aborts the whole use.
        let quest_id = info.data[1];
        if quest_id > 0 {
            #[allow(clippy::cast_sign_loss)]
            let quest_id = quest_id as u32;
            if self.stores.quest_templates.get(quest_id).is_some()
                && !self.player_quest_incomplete(player, quest_id)
            {
                return;
            }
        }
        // `goober.eventId` (data2): C++ process event,
        // else the DB `event_scripts` arm; no event id
        // runs the per-spawn `gameobject_scripts`.
        let event_id = info.data_u32(2);
        if event_id != 0 {
            if !self.process_event(event_id, Some(player), Some(go_guid), true) {
                self.scripts_start_event(event_id, player, go_guid);
            }
        } else {
            self.scripts_start_gameobject(go_guid.counter(), player, go_guid);
        }
        // IN_USE flag + ACTIVE state (loot-state /
        // auto-close subset as the door arm).
        let flags = self.object_get_field(go_guid, offsets::GAMEOBJECT_FLAGS);
        let _ = self.object_set_field(
            go_guid,
            u32::from(offsets::GAMEOBJECT_FLAGS),
            flags | 0x0001,
        );
        let _ = self.object_set_field(
            go_guid,
            u32::from(offsets::GAMEOBJECT_STATE),
            GO_STATE_ACTIVE,
        );
    }

    /// `GAMEOBJECT_TYPE_CAMERA` use subset
    /// (`GameObject.cpp:1569`): cinematic start +
    /// `camera.eventID` (data1) process event / DB arm.
    fn go_use_camera(&mut self, player: ObjectGuid, go_guid: ObjectGuid) {
        let Some(info) = self.gameobjects.get(&go_guid).map(|g| g.info.clone()) else {
            return;
        };
        // `camera.cinematicId` (data0).
        let cinematic_id = info.data_u32(0);
        if cinematic_id != 0 {
            use mangos_protocol::buffer::PacketWriter;
            let mut writer = PacketWriter::new();
            writer.write_u32_le(cinematic_id);
            let mut packet = mangos_protocol::world::WorldPacket::new(
                mangos_protocol::opcode_table::opcode_id::SMSG_TRIGGER_CINEMATIC,
            );
            packet.take_writer(writer);
            self.events
                .push(crate::map::MapEvent::Packet { to: player, packet });
        }
        let event_id = info.data_u32(1);
        if event_id != 0 && !self.process_event(event_id, Some(player), Some(go_guid), true) {
            self.scripts_start_event(event_id, player, go_guid);
        }
    }

    // ------------------------------------------------ Mr. Smite

    /// `boss_mr_smiteAI::Reset`.
    pub(crate) fn smite_reset(&mut self, guid: ObjectGuid) {
        let equip_id = self.creatures.get(&guid).map_or(0, |c| c.info.equipment_id);
        if let Some(ai) = self.ai.get_mut(&guid) {
            ai.script = Some(CreatureScriptAi::MrSmite(SmiteState::new()));
        }
        self.creature_load_equipment(guid, equip_id);
    }

    fn do_cast_spell_if_can(
        &mut self,
        guid: ObjectGuid,
        spell_id: u32,
        target: CastTarget,
    ) -> bool {
        self.cast_spell(
            guid,
            spell_id,
            target,
            CastOptions {
                triggered: false,
                triggered_by_aura: false,
                skip_known: true,
                cast_item: None,
                custom_base_points: [None; 3],
                triggered_by_aura_spell: 0,
                triggered_by_spell: 0,
            },
        ) == CastOutcome::Started
    }

    pub(crate) fn creature_health_percent(&self, guid: ObjectGuid) -> f32 {
        let cur = f64::from(self.unit_value_u32(guid, offsets::UNIT_FIELD_HEALTH));
        let max = f64::from(self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXHEALTH));
        if max == 0.0 {
            return 100.0;
        }
        #[allow(clippy::cast_possible_truncation)]
        {
            (cur * 100.0 / max) as f32
        }
    }

    /// The equip-phase branch of `UpdateAI` (also runs
    /// with no victim, as in C++).
    fn smite_equip_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let due = {
            let Some(smite) = self.ai.get_mut(&guid).and_then(|ai| ai.smite_mut()) else {
                return;
            };
            if smite.equip_timer_ms > 0 {
                if smite.equip_timer_ms > diff_ms {
                    smite.equip_timer_ms -= diff_ms;
                    return;
                }
                smite.equip_timer_ms = 0;
            }
            smite.phase
        };
        match due {
            SmitePhase::EquipStart => self.smite_phase_equip_start(guid),
            SmitePhase::EquipProcess => self.smite_phase_equip_process(guid),
            SmitePhase::EquipEnd => self.smite_phase_equip_end(guid),
            _ => {}
        }
    }

    fn smite_phase_equip_start(&mut self, guid: ObjectGuid) {
        let Some(chest) = self
            .unit_position(guid)
            .and_then(|_| self.find_gameobject(GO_SMITE_CHEST, None))
        else {
            if let Some(smite) = self.ai.get_mut(&guid).and_then(|ai| ai.smite_mut()) {
                smite.phase = SmitePhase::EquipProcess;
            }
            return;
        };
        let chest_pos = self.object_position(chest).unwrap_or_default();
        let my_pos = self.unit_position(guid).unwrap_or_default();
        // `GetContactPoint(.., CONTACT_DISTANCE)`.
        let dx = my_pos.x - chest_pos.x;
        let dy = my_pos.y - chest_pos.y;
        let len = (dx * dx + dy * dy).sqrt().max(0.01);
        let contact = Position::new(
            chest_pos.x + dx / len * 1.5,
            chest_pos.y + dy / len * 1.5,
            chest_pos.z,
            0.0,
        );
        self.stop_moving(guid);
        if let Some(smite) = self.ai.get_mut(&guid).and_then(|ai| ai.smite_mut()) {
            smite.phase = SmitePhase::EquipNull;
            smite.in_spline = true;
        }
        self.creature_move_point(guid, 0, contact, 0, 0.0, -10.0);
    }

    /// `MovementInform`/`SplineFinished` while running
    /// to the chest.
    pub(crate) fn smite_spline_finished(&mut self, guid: ObjectGuid) {
        let equiping = self
            .ai
            .get(&guid)
            .and_then(|ai| ai.smite())
            .is_some_and(|s| s.equiping);
        if !equiping {
            return;
        }
        if let Some(smite) = self.ai.get_mut(&guid).and_then(|ai| ai.smite_mut()) {
            smite.in_spline = false;
        }
        self.creature_load_equipment(guid, 0);
        self.unit_set_byte(guid, offsets::UNIT_FIELD_BYTES_2, 0, SHEATH_UNARMED);
        self.unit_set_byte(guid, offsets::UNIT_FIELD_BYTES_1, 0, STAND_STATE_KNEEL);
        if let Some(smite) = self.ai.get_mut(&guid).and_then(|ai| ai.smite_mut()) {
            smite.equip_timer_ms = 3000;
            smite.phase = SmitePhase::EquipProcess;
        }
    }

    fn smite_phase_equip_process(&mut self, guid: ObjectGuid) {
        if self.creature_health_percent(guid) < 33.0 {
            self.set_virtual_item_by_id(guid, 0, EQUIP_ID_HAMMER);
            self.set_virtual_item_by_id(guid, 1, 0);
            self.set_virtual_item_by_id(guid, 2, 0);
            self.do_cast_spell_if_can(guid, SPELL_SMITE_HAMMER, CastTarget::SelfCast);
        } else {
            self.set_virtual_item_by_id(guid, 0, EQUIP_ID_AXE);
            self.set_virtual_item_by_id(guid, 1, EQUIP_ID_AXE);
            self.set_virtual_item_by_id(guid, 2, 0);
        }
        self.unit_set_byte(guid, offsets::UNIT_FIELD_BYTES_1, 0, STAND_STATE_STAND);
        if let Some(smite) = self.ai.get_mut(&guid).and_then(|ai| ai.smite_mut()) {
            smite.phase = SmitePhase::EquipEnd;
            smite.equip_timer_ms = 1000;
        }
    }

    fn smite_phase_equip_end(&mut self, guid: ObjectGuid) {
        let Some(victim) = self.threat_targets_sorted(guid).first().copied() else {
            self.enter_evade_mode(guid);
            return;
        };
        self.unit_set_byte(guid, offsets::UNIT_FIELD_BYTES_2, 0, SHEATH_MELEE);
        let phase = if self.creature_health_percent(guid) < 33.0 {
            SmitePhase::Phase3
        } else {
            SmitePhase::Phase2
        };
        if let Some(smite) = self.ai.get_mut(&guid).and_then(|ai| ai.smite_mut()) {
            smite.phase = phase;
            smite.equiping = false;
        }
        self.attack_start(guid, victim);
        self.creature_move_chase(guid, victim, 0.0, 0.0);
    }

    fn smite_start_equip(&mut self, guid: ObjectGuid, say: i32) {
        self.do_script_text(say, guid, None, -1);
        self.stop_moving(guid);
        self.attack_stop(guid);
        if let Some(smite) = self.ai.get_mut(&guid).and_then(|ai| ai.smite_mut()) {
            smite.phase = SmitePhase::EquipStart;
            smite.equip_timer_ms = 2500;
            smite.equiping = true;
        }
    }

    /// `boss_mr_smiteAI::UpdateAI` (called instead of
    /// the generic creature update for script-bound
    /// Smite).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    pub(crate) fn update_smite(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let phase = {
            let Some(smite) = self.ai.get(&guid).and_then(|ai| ai.smite()) else {
                return;
            };
            smite.phase
        };
        // Equip phases run with or without a victim
        // (AttackStop cleared it), mirroring C++.
        if matches!(
            phase,
            SmitePhase::EquipNull
                | SmitePhase::EquipStart
                | SmitePhase::EquipProcess
                | SmitePhase::EquipEnd
        ) {
            self.smite_equip_update(guid, diff_ms);
            return;
        }
        let Some(victim) = self.get_hostile_target(guid) else {
            if self.ai_in_combat(guid) {
                self.enter_evade_mode(guid);
            } else {
                // `MoveInLineOfSight` proximity aggro
                // (the ScriptedAI base behavior).
                self.try_proximity_aggro(guid);
            }
            return;
        };
        if self.should_leash_evade(guid) {
            self.enter_evade_mode(guid);
            return;
        }
        let current_victim = self.unit_victim(guid);
        if current_victim != Some(victim) {
            self.attack_start(guid, victim);
        }
        if self.motion_type_of(guid) != crate::motion::CHASE_MOTION_TYPE
            || self.chase_target_of(guid) != Some(victim)
        {
            self.creature_move_chase(guid, victim, 0.0, 0.0);
        }
        let health_pct = self.creature_health_percent(guid);
        match phase {
            SmitePhase::Phase1 => {
                if health_pct < 66.0
                    && self.do_cast_spell_if_can(guid, SPELL_SMITE_STOMP, CastTarget::SelfCast)
                {
                    let say = if health_pct < 33.0 {
                        SAY_PHASE_3
                    } else {
                        SAY_PHASE_2
                    };
                    self.smite_start_equip(guid, say);
                    self.cancel_aura(guid, SPELL_NIBLE_REFLEXES);
                }
            }
            SmitePhase::Phase2 => {
                let due = {
                    let smite = self
                        .ai
                        .get_mut(&guid)
                        .and_then(|ai| ai.smite_mut())
                        .expect("smite");
                    if smite.thrash_timer_ms < diff_ms {
                        true
                    } else {
                        smite.thrash_timer_ms -= diff_ms;
                        false
                    }
                };
                if due && self.do_cast_spell_if_can(guid, SPELL_THRASH, CastTarget::Unit(victim)) {
                    let next = self.rng.urand(1500, 4000);
                    if let Some(smite) = self.ai.get_mut(&guid).and_then(|ai| ai.smite_mut()) {
                        smite.thrash_timer_ms = next;
                    }
                }
                if health_pct < 33.0
                    && self.do_cast_spell_if_can(guid, SPELL_SMITE_STOMP, CastTarget::SelfCast)
                {
                    self.smite_start_equip(guid, SAY_PHASE_3);
                }
            }
            SmitePhase::Phase3 => {
                let due = {
                    let smite = self
                        .ai
                        .get_mut(&guid)
                        .and_then(|ai| ai.smite_mut())
                        .expect("smite");
                    if smite.slam_timer_ms < diff_ms {
                        true
                    } else {
                        smite.slam_timer_ms -= diff_ms;
                        false
                    }
                };
                if due
                    && self.do_cast_spell_if_can(guid, SPELL_SMITE_SLAM, CastTarget::Unit(victim))
                {
                    if let Some(smite) = self.ai.get_mut(&guid).and_then(|ai| ai.smite_mut()) {
                        smite.slam_timer_ms = 11_000;
                    }
                }
            }
            _ => {}
        }
    }

