    /// `CreatureAI::EnterEvadeMode` script pre-base + `Reset`.
    #[allow(clippy::too_many_lines)] // generated variant match
    pub(crate) fn creature_script_enter_evade(&mut self, guid: ObjectGuid) {
        match self.ai.get(&guid).and_then(|ai| ai.script.as_ref()) {
            Some(CreatureScriptAi::Herod(_)) => self.herod_enter_evade(guid),
            Some(CreatureScriptAi::MalgenLongspear(_)) => self.malgen_longspear_enter_evade(guid),
            Some(CreatureScriptAi::Nefarian(_)) => self.nefarian_enter_evade(guid),
            Some(CreatureScriptAi::Golemagg(_)) => self.golemagg_enter_evade(guid),
            Some(CreatureScriptAi::CannonMasterWilley(_)) => self.willey_enter_evade(guid),
            Some(CreatureScriptAi::Gothik(_)) => self.gothik_enter_evade(guid),
            Some(CreatureScriptAi::Loatheb(_)) => self.loatheb_enter_evade(guid),
            Some(CreatureScriptAi::ScholomanceStudent(_)) => self.student_enter_evade(guid),
            Some(CreatureScriptAi::Jeklik(_)) => self.jeklik_enter_evade(guid),
            Some(CreatureScriptAi::Venoxis(_)) => self.venoxis_enter_evade(guid),
            Some(CreatureScriptAi::Archaedas(_)) => self.archaedas_enter_evade(guid),
            Some(CreatureScriptAi::ArchaedasMinion(_)) => self.archaedas_minion_enter_evade(guid),
            Some(CreatureScriptAi::StoneKeeper(_)) => self.stone_keeper_enter_evade(guid),
            Some(CreatureScriptAi::Kri(_)) => self.kri_enter_evade(guid),
            Some(CreatureScriptAi::Yauj(_)) => self.yauj_enter_evade(guid),
            Some(CreatureScriptAi::Vem(_)) => self.vem_enter_evade(guid),
            Some(CreatureScriptAi::Sartura(_)) => self.sartura_enter_evade(guid),
            Some(CreatureScriptAi::VeknissGuardian(_)) => self.vekniss_guardian_enter_evade(guid),
            Some(CreatureScriptAi::ImmolThar(_)) => self.immol_thar_enter_evade(guid),
            Some(CreatureScriptAi::Kromcrush(_)) => self.kromcrush_enter_evade(guid),
            Some(CreatureScriptAi::Onyxia(_)) => self.onyxia_enter_evade(guid),
            Some(CreatureScriptAi::Eranikus(_)) => self.eranikus_enter_evade(guid),
            Some(CreatureScriptAi::Colossus(_)) => self.colossus_enter_evade(guid),
            Some(CreatureScriptAi::PreciousDevourer(_)) => self.precious_enter_evade(guid),
            Some(CreatureScriptAi::Solenor(_)) => self.solenor_enter_evade(guid),
            Some(CreatureScriptAi::Vanndar(_)) => self.vanndar_enter_evade(guid),
            Some(CreatureScriptAi::Drekthar(_)) => self.drekthar_enter_evade(guid),
            Some(CreatureScriptAi::DragonTaerar(_)) => self.taerar_enter_evade(guid),
            Some(CreatureScriptAi::InjuredPatient(_)) => self.patient_enter_evade(guid),
            Some(CreatureScriptAi::Cleaner(_)) => self.cleaner_enter_evade(guid),
            Some(
                CreatureScriptAi::IronforgeInfantry(_)
                | CreatureScriptAi::OrgrimmarInfantry(_)
                | CreatureScriptAi::OrgrimmarRifleman(_)
                | CreatureScriptAi::Priestess(_),
            ) => self.infantryman_enter_evade(guid),
            Some(CreatureScriptAi::Saurfang(_)) => self.saurfang_enter_evade(guid),
            Some(CreatureScriptAi::CapturedSpriteDarter(_)) => {
                self.captured_sprite_darter_enter_evade(guid);
            }
            _ => {}
        }
        self.creature_script_reset(guid);
    }

