    /// Shared head of scripted `UpdateAI` bodies (fork
    /// `SelectHostileTarget` + `AttackStart` + chase sync, in the
    /// `update_smite` arrangement): hostile target, or evade /
    /// proximity-aggro when targetless. `drive` false keeps the
    /// victim/chase untouched (rooted whirlwind).
    fn script_combat_drive(&mut self, guid: ObjectGuid, drive: bool) -> Option<ObjectGuid> {
        let Some(victim) = self.get_hostile_target(guid) else {
            if self.ai_in_combat(guid) {
                self.enter_evade_mode(guid);
            } else if self.creature_script_has_move_in_line_of_sight(guid) {
                // `MoveInLineOfSight` replaces proximity aggro
                // (players only; fork also fires for other units).
                // Candidate range is the visibility distance;
                // bodies gate on their own ranges (fork
                // `AIRelocationNotifier`).
                let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
                for player in players {
                    let range = self.config.visibility_distance;
                    let near = match (self.unit_position(guid), self.unit_position(player)) {
                        (Some(a), Some(b)) => {
                            let dx = a.x - b.x;
                            let dy = a.y - b.y;
                            dx * dx + dy * dy <= range * range
                        }
                        _ => false,
                    };
                    if near && self.unit_is_alive(player) {
                        self.creature_script_move_in_line_of_sight(guid, player);
                    }
                }
            } else {
                self.try_proximity_aggro(guid);
            }
            return None;
        };
        if self.should_leash_evade(guid) {
            self.enter_evade_mode(guid);
            return None;
        }
        if drive {
            if self.unit_victim(guid) != Some(victim) {
                self.attack_start(guid, victim);
                if self.creature_script_attack_start(guid, victim) {
                    return Some(victim);
                }
            }
            // Fork `SetCombatMovement(false)` suppresses the
            // chase sync (script point/idle motion owns the
            // creature, e.g. Onyxia phase transitions).
            let combat_movement = self.ai.get(&guid).is_some_and(|ai| ai.combat_movement);
            if combat_movement
                && (self.motion_type_of(guid) != crate::motion::CHASE_MOTION_TYPE
                    || self.chase_target_of(guid) != Some(victim))
            {
                self.creature_move_chase(guid, victim, 0.0, 0.0);
            }
        }
        Some(victim)
    }

    /// `boss_herodAI::EnterEvadeMode` pre-base (fork override
    /// order: clear root, despawn myrmidons, then base resets).
    fn herod_enter_evade(&mut self, guid: ObjectGuid) {
        if let Some(u) = self.unit_base_mut(guid) {
            u.clear_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
        }
        self.herod_despawn_myrmidons(guid);
    }

    /// `boss_herodAI::KilledUnit`.
    fn herod_killed_unit(&mut self, guid: ObjectGuid, _victim: ObjectGuid) {
        self.do_script_text(HEROD_SAY_KILL, guid, None, -1);
    }

    /// `boss_herodAI::Reset`.
    fn herod_reset(&mut self, guid: ObjectGuid) {
        let whirlwind = self.rng.urand(10_000, 20_000);
        if let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut()) {
            s.reset_fields();
            s.whirlwind_timer_ms = whirlwind;
        }
    }

    /// `boss_herodAI::Aggro`.
    fn herod_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        self.herod_spawn_myrmidons(guid);
        self.do_script_text(HEROD_SAY_AGGRO, guid, None, -1);
        self.do_cast_spell_if_can(guid, HEROD_SPELL_RUSHING_CHARGE, CastTarget::SelfCast);
    }

    /// `boss_herodAI::SpawnMyrmidons`.
    fn herod_spawn_myrmidons(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut()) {
            s.myrmidons_spawned = true;
        }
        for _ in 0..4 {
            let jx = self.rng.frand(-3.0, 3.0);
            let jy = self.rng.frand(-3.0, 3.0);
            self.summon_creature(
                HEROD_NPC_SCARLET_MYRMIDON,
                Position::new(1926.03 + jx, -370.61 + jy, 18.0, 0.05),
                guid,
                HEROD_TEMPSUMMON_DEAD_DESPAWN,
                20_000,
            );
        }
    }

    /// `boss_herodAI::DespawnMyrmidons`.
    fn herod_despawn_myrmidons(&mut self, guid: ObjectGuid) {
        let guids = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Herod(s)) => Some(s.myrmidon_guids.clone()),
                _ => None,
            })
            .unwrap_or_default();
        for g in guids {
            if self.unit_is_alive(g) && self.unit_victim(g).is_none() {
                self.despawn_creature_now(g, 0);
            }
        }
        if let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut()) {
            s.myrmidons_spawned = false;
            s.myrmidon_guids.clear();
        }
    }

    /// `boss_herodAI::EngageMyrmidons`.
    fn herod_engage_myrmidons(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        let guids = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Herod(s)) => Some(s.myrmidon_guids.clone()),
                _ => None,
            })
            .unwrap_or_default();
        for g in guids {
            if !self.unit_is_alive(g) || self.unit_victim(g).is_some() {
                continue;
            }
            if self.unit_is_alive(victim) {
                self.enter_combat(g, victim);
            }
        }
    }

    /// `boss_herodAI::JustSummoned`.
    fn herod_just_summoned(&mut self, guid: ObjectGuid, summoned: ObjectGuid) {
        let entry = self.creatures.get(&summoned).map(|c| c.info.entry);
        if entry == Some(HEROD_NPC_SCARLET_TRAINEE) {
            let (say, nb) = {
                let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut()) else {
                    return;
                };
                let say = !s.trainee_say;
                s.trainee_say = true;
                let nb = s.nb_trainee;
                s.nb_trainee = s.nb_trainee.saturating_add(1);
                (say, nb)
            };
            if say {
                self.do_script_text(HEROD_SAY_TRAINEE_SPAWN, summoned, None, -1);
            }
            if nb < 10 {
                self.creature_move_point(
                    summoned,
                    0,
                    Position::new(1940.2571, -434.4543, 17.0945, 0.0),
                    0,
                    0.0,
                    0.0,
                );
            } else {
                self.creature_move_point(
                    summoned,
                    100,
                    Position::new(1940.5083, -428.8261, 17.0951, 0.0),
                    0,
                    0.0,
                    0.0,
                );
            }
            return;
        }
        // `SetNoXP` (fork): no no-XP flag in the Rust creature
        // state — recorded remainder (summons grant XP through
        // the generic kill path today).
        if let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut()) {
            s.myrmidon_guids.push(summoned);
        }
    }

    /// `boss_herodAI::JustDied`.
    fn herod_just_died(&mut self, guid: ObjectGuid) {
        self.herod_despawn_myrmidons(guid);
        for _ in 0..20 {
            self.summon_creature(
                HEROD_NPC_SCARLET_TRAINEE,
                Position::new(1939.18, -431.58, 17.09, 6.22),
                guid,
                HEROD_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
                180_000,
            );
        }
        // `FindNearestGameObject(GO_HEROD_DOOR, 100.0f)`.
        let me = self.unit_position(guid).unwrap_or_default();
        let door = self
            .gameobjects
            .iter()
            .filter(|(_, g)| g.info.id == HL_GO_HEROD_DOOR)
            .filter_map(|(g, _)| {
                self.object_position(*g).map(|p| {
                    let dx = p.x - me.x;
                    let dy = p.y - me.y;
                    (*g, dx * dx + dy * dy)
                })
            })
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .filter(|(_, d)| *d <= 100.0 * 100.0)
            .map(|(g, _)| g);
        if let Some(door) = door
            && self.go_state(door) != GO_STATE_ACTIVE
        {
            self.use_door(door);
        }
    }

    /// `boss_herodAI::UpdateAI`.
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn herod_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Whirlwind root runs before the drive (fork `UNIT_STATE_ROOT`
        // idles the chase generator; the Rust root flag does not gate
        // motion yet, so the cast also `stop_moving`s and the drive is
        // skipped here).
        let whirlwind = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Herod(s)) if s.whirlwind),
        );
        let Some(victim) = self.script_combat_drive(guid, !whirlwind) else {
            return;
        };
        // Room check (fork order: before the whirlwind branch).
        let mut engage = false;
        if let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut()) {
            if s.myrmidons_spawned && s.room_check_ms <= diff_ms {
                engage = true;
                s.room_check_ms = 500;
            } else {
                s.room_check_ms = s.room_check_ms.saturating_sub(diff_ms);
            }
        }
        if engage {
            let me = self.unit_position(guid).unwrap_or_default();
            let dx = me.x - 1965.09;
            let dy = me.y - (-431.61);
            if dx * dx + dy * dy > 32.0 * 32.0 {
                self.herod_engage_myrmidons(guid, victim);
            }
        }
        if whirlwind {
            let expired = {
                let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut()) else {
                    return;
                };
                if s.root_timer_ms < diff_ms {
                    s.whirlwind = false;
                    true
                } else {
                    s.root_timer_ms -= diff_ms;
                    false
                }
            };
            if expired {
                if let Some(u) = self.unit_base_mut(guid) {
                    u.clear_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
                }
            } else {
                return;
            }
        }
        // Enrage at <=50% (fork also gates on not casting a
        // non-melee spell; `bot_casting_spell` is the reduced
        // active-cast check).
        let enraged = self
            .ai
            .get(&guid)
            .is_some_and(|ai| matches!(&ai.script, Some(CreatureScriptAi::Herod(s)) if s.enrage));
        if !enraged
            && self.creature_health_percent(guid) <= 50.0
            && self.bot_casting_spell(guid).is_none()
            && self.do_cast_spell_if_can(guid, HEROD_SPELL_FRENZY, CastTarget::SelfCast)
        {
            self.do_script_text(HEROD_EMOTE_ENRAGE, guid, None, -1);
            self.do_script_text(HEROD_SAY_ENRAGE, guid, None, -1);
            if let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut()) {
                s.enrage = true;
            }
        }
        // Rushing Charge: fork timer does not tick down while due.
        let charge_due = {
            let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut()) else {
                return;
            };
            if s.rushing_charge_timer_ms < diff_ms {
                true
            } else {
                s.rushing_charge_timer_ms -= diff_ms;
                false
            }
        };
        if charge_due {
            // `!pVictim->IsInRange(m_creature, 0, MELEE_RANGE + 10)`
            // with `MELEE_RANGE` = 1.0 (center distance; the fork
            // bounding-radius fold is unmodeled).
            let far = match (self.unit_position(guid), self.unit_position(victim)) {
                (Some(a), Some(b)) => {
                    let dx = a.x - b.x;
                    let dy = a.y - b.y;
                    dx * dx + dy * dy > 11.0 * 11.0
                }
                _ => false,
            };
            if far
                && self.do_cast_spell_if_can(guid, HEROD_SPELL_RUSHING_CHARGE, CastTarget::SelfCast)
                && let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut())
            {
                s.rushing_charge_timer_ms = 4500;
            }
        }
        // Cleave.
        let cleave_due = {
            let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut()) else {
                return;
            };
            if s.cleave_timer_ms < diff_ms {
                true
            } else {
                s.cleave_timer_ms -= diff_ms;
                false
            }
        };
        if cleave_due
            && self.do_cast_spell_if_can(guid, HEROD_SPELL_CLEAVE, CastTarget::Unit(victim))
            && let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut())
        {
            s.cleave_timer_ms = 12_000;
        }
        // Whirlwind.
        let whirlwind_due = {
            let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut()) else {
                return;
            };
            if s.whirlwind_timer_ms < diff_ms {
                true
            } else {
                s.whirlwind_timer_ms -= diff_ms;
                false
            }
        };
        if whirlwind_due
            && self.do_cast_spell_if_can(guid, HEROD_SPELL_WHIRLWIND, CastTarget::Unit(victim))
        {
            if let Some(u) = self.unit_base_mut(guid) {
                u.add_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
            }
            self.stop_moving(guid);
            self.do_script_text(HEROD_SAY_WHIRLWIND, guid, None, -1);
            let next = self.rng.urand(20_000, 30_000);
            if let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.herod_mut()) {
                s.whirlwind = true;
                s.root_timer_ms = 11_000;
                s.whirlwind_timer_ms = next;
            }
        }
    }

    /// `mob_scarlet_traineeAI::Reset` (+ ctor start roll).
    fn trainee_reset(&mut self, guid: ObjectGuid) {
        let roll = self.rng.urand(1000, 6000);
        if let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.trainee_mut()) {
            s.has_fled = false;
            if !s.start_rolled {
                s.start_timer_ms = roll;
                s.start_rolled = true;
            }
        }
    }

    /// `mob_scarlet_traineeAI::UpdateAI`.
    fn trainee_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let start_due = {
            let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.trainee_mut()) else {
                return;
            };
            if s.start_timer_ms != 0 && s.start_timer_ms <= diff_ms {
                s.start_timer_ms = 0;
                Some((s.group1, s.group2))
            } else {
                s.start_timer_ms = s.start_timer_ms.saturating_sub(diff_ms);
                None
            }
        };
        if let Some((group1, group2)) = start_due {
            self.set_speed_rate(guid, mangos_entities::unit::MOVE_WALK, 2.20);
            if group1 {
                self.creature_move_point(
                    guid,
                    1,
                    Position::new(1946.4336, -435.9551, 16.3673, 0.0),
                    0,
                    0.0,
                    0.0,
                );
            } else if group2 {
                self.creature_move_point(
                    guid,
                    101,
                    Position::new(1940.2571, -434.4543, 17.0945, 0.0),
                    0,
                    0.0,
                    0.0,
                );
            }
        }
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let fled = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::ScarletTrainee(s)) if s.has_fled),
        );
        if !fled && self.creature_health_percent(guid) < 15.0 {
            if let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.trainee_mut()) {
                s.has_fled = true;
            }
            self.do_flee(guid, false);
        }
    }

    /// `mob_scarlet_traineeAI::MovementInform`.
    fn trainee_movement_inform(&mut self, guid: ObjectGuid, point_id: u32) {
        let next: Option<(u32, f32, f32, f32)> = match point_id {
            0 | 100 => {
                if let Some(s) = self.ai.get_mut(&guid).and_then(|ai| ai.trainee_mut()) {
                    if point_id == 0 {
                        s.group1 = true;
                    } else {
                        s.group2 = true;
                    }
                }
                None
            }
            1 => Some((2, 1952.8347, -447.5141, 13.8043)),
            101 => Some((102, 1953.0568, -416.1099, 13.8612)),
            2 => Some((3, 1965.592, -451.1538, 11.2723)),
            102 => Some((103, 1965.3696, -412.1479, 11.2724)),
            3 => Some((4, 1982.6927, -441.5143, 11.2723)),
            103 => Some((104, 1980.9081, -421.008, 11.2724)),
            4 => Some((5, 1978.0619, -428.5495, 11.2722)),
            104 => Some((105, 1979.139, -434.8569, 11.2724)),
            5 => Some((6, 1971.4471, -419.6293, 8.0872)),
            105 => Some((106, 1972.0448, -442.5686, 8.4346)),
            6 => Some((7, 1964.354, -418.6329, 6.1775)),
            106 => Some((107, 1964.6912, -444.223, 6.1776)),
            7 | 107 => Some((116, 1965.0398, -431.7339, 6.1775)),
            _ => None,
        };
        if let Some((id, x, y, z)) = next {
            self.creature_move_point(guid, id, Position::new(x, y, z, 0.0), 0, 0.0, 0.0);
        }
    }

