    /// Fork `EnterCombat` (cpp 381-391); `ScriptedAI::EnterCombat`
    /// calls `Aggro`, so this is the aggro hook body: summon pet.
    fn malgen_longspear_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        let pet = self
            .malgen_longspear_state_mut(guid)
            .map_or(ObjectGuid::EMPTY, |s| s.pet);
        if !pet.is_empty() && self.creatures.contains_key(&pet) {
            return;
        }
        let pos = self.unit_position(guid).unwrap_or_default();
        if let Some(pet) = self.summon_creature(
            MALGEN_NPC_GNASHJAW,
            pos,
            guid,
            MALGEN_TEMPSUMMON_TIMED_OOC,
            10_000,
        ) {
            if let Some(s) = self.malgen_longspear_state_mut(guid) {
                s.pet = pet;
            }
        }
    }

    /// Fork `EnterEvadeMode` pre-base work (cpp 372-379): despawn
    /// the pet (the dispatcher runs reset after).
    fn malgen_longspear_enter_evade(&mut self, guid: ObjectGuid) {
        let pet = self
            .malgen_longspear_state_mut(guid)
            .map_or(ObjectGuid::EMPTY, |s| s.pet);
        if !pet.is_empty() && self.creatures.contains_key(&pet) {
            self.despawn_creature_now(pet, 0);
            if let Some(s) = self.malgen_longspear_state_mut(guid) {
                s.pet = ObjectGuid::EMPTY;
            }
        }
    }

    /// Triggered-cast variant for the `CF_TRIGGERED` fork casts
    /// (cpp 401, 418).
    fn malgen_triggered_cast(
        &mut self,
        guid: ObjectGuid,
        spell_id: u32,
        target: CastTarget,
    ) -> bool {
        self.cast_spell(
            guid,
            spell_id,
            target,
            CastOptions {
                triggered: true,
                skip_known: true,
                ..Default::default()
            },
        ) == CastOutcome::Started
    }

    /// `npc_malgen_longspearAI::UpdateAI` (cpp 393-458).
    fn malgen_longspear_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Fork order: when feigned the hostile-target check is
        // skipped (cpp 395), so the feign/trap block runs first.
        // When not feigned and targetless the fork returns with
        // frozen timers.
        let feigned = self
            .malgen_longspear_state_mut(guid)
            .is_some_and(|s| s.is_feigned);
        if !feigned {
            let Some(_victim) = self.script_combat_drive(guid, true) else {
                return;
            };
        }
        self.malgen_feign_tick(guid, diff_ms);
        let feigned = self
            .malgen_longspear_state_mut(guid)
            .is_some_and(|s| s.is_feigned);
        if feigned {
            return;
        }
        // Re-drive: the trap branch may have ended feign and picked
        // a new chase target above; the fork then falls through to
        // the shot timers with a victim.
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let aimed_due = {
            let Some(s) = self.malgen_longspear_state_mut(guid) else {
                return;
            };
            if s.aimed_shot_timer_ms < diff_ms {
                true
            } else {
                s.aimed_shot_timer_ms -= diff_ms;
                false
            }
        };
        if aimed_due {
            // NEEDS-MAP-HELPER: `GetPlayerAtMinimumRange(8.0f)` (cpp 439).
            let target: Option<ObjectGuid> = None;
            if let Some(target) = target {
                if self.do_cast_spell_if_can(
                    guid,
                    MALGEN_SPELL_AIMED_SHOT,
                    CastTarget::Unit(target),
                ) {
                    let next = self.rng.urand(18_000, 24_000);
                    if let Some(s) = self.malgen_longspear_state_mut(guid) {
                        s.aimed_shot_timer_ms = next;
                    }
                }
            }
        }
        let multi_due = {
            let Some(s) = self.malgen_longspear_state_mut(guid) else {
                return;
            };
            if s.multi_shot_timer_ms < diff_ms {
                true
            } else {
                s.multi_shot_timer_ms -= diff_ms;
                false
            }
        };
        if multi_due {
            // NEEDS-MAP-HELPER: `GetPlayerAtMinimumRange(8.0f)` (cpp 449).
            let target: Option<ObjectGuid> = None;
            if let Some(target) = target {
                if self.do_cast_spell_if_can(
                    guid,
                    MALGEN_SPELL_MULTI_SHOT,
                    CastTarget::Unit(target),
                ) {
                    if let Some(s) = self.malgen_longspear_state_mut(guid) {
                        s.multi_shot_timer_ms = 20_000;
                    }
                }
            }
        }
    }

    /// Feign-death + frost-trap block (cpp 398-431).
    fn malgen_feign_tick(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let feign_due = {
            let Some(s) = self.malgen_longspear_state_mut(guid) else {
                return;
            };
            if s.feign_death_timer_ms < diff_ms {
                true
            } else {
                s.feign_death_timer_ms -= diff_ms;
                false
            }
        };
        if feign_due
            && self.malgen_triggered_cast(guid, MALGEN_SPELL_FEIGN_DEATH, CastTarget::SelfCast)
        {
            let next = self.rng.urand(50_000, 60_000);
            if let Some(s) = self.malgen_longspear_state_mut(guid) {
                s.is_feigned = true;
                s.frost_trap_timer_ms = 1000;
                s.feign_death_timer_ms = next;
            }
        }
        let trap = self
            .malgen_longspear_state_mut(guid)
            .map_or(0, |s| s.frost_trap_timer_ms);
        if trap != 0 {
            if trap < diff_ms {
                self.remove_auras_due_to_spell(guid, MALGEN_SPELL_FEIGN_DEATH);
                self.malgen_triggered_cast(guid, MALGEN_SPELL_FROST_TRAP, CastTarget::SelfCast);
                if let Some(s) = self.malgen_longspear_state_mut(guid) {
                    s.frost_trap_timer_ms = 0;
                    s.is_feigned = false;
                }
                // `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 0)` (cpp 423).
                if let Some(target) = self.select_random_hostile(guid) {
                    self.creature_move_chase(guid, target, 0.0, 0.0);
                }
            } else if let Some(s) = self.malgen_longspear_state_mut(guid) {
                s.frost_trap_timer_ms -= diff_ms;
            }
        }
    }

