    /// `npc_watchman_doomgripAI::Aggro` (cpp 1304-1321).
    fn watchman_doomgrip_aggro(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        // `GetCreatureListWithEntryInGrid(8905, 20.0f)` (cpp 1307).
        let me = self.unit_position(guid).unwrap_or_default();
        let golems: Vec<ObjectGuid> = self
            .creatures
            .iter()
            .filter_map(|(g, c)| {
                if c.info.entry != DOOMGRIP_NPC_WARBRINGER_CONSTRUCT {
                    return None;
                }
                let p = self.object_position(*g)?;
                let dx = p.x - me.x;
                let dy = p.y - me.y;
                (dx * dx + dy * dy <= 20.0 * 20.0).then_some(*g)
            })
            .collect();
        for golem in golems {
            if !self.unit_is_alive(golem) {
                continue;
            }
            self.remove_auras_due_to_spell(golem, DOOMGRIP_AURA_GOLEM_STUN);
            let flags = self.object_get_field(golem, offsets::UNIT_FIELD_FLAGS);
            let _ = self.object_set_field(
                golem,
                u32::from(offsets::UNIT_FIELD_FLAGS),
                flags
                    & !(DOOMGRIP_UNIT_FLAG_NOT_SELECTABLE
                        | DOOMGRIP_UNIT_FLAG_SPAWNING
                        | DOOMGRIP_UNIT_FLAG_IMMUNE_TO_NPC),
            );
            if !who.is_empty() && self.unit_is_alive(who) {
                self.attack_start(golem, who);
            }
        }
    }

