    /// `npc_watchman_doomgripAI::UpdateAI` (cpp 1323-1350).
    fn watchman_doomgrip_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        if self.creature_health_percent(guid) < 51.0 {
            let due = {
                let Some(s) = self.watchman_doomgrip_state_mut(guid) else {
                    return;
                };
                if s.healing_potion_timer_ms < diff_ms {
                    true
                } else {
                    s.healing_potion_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                // Fork casts on the victim (cpp 1333), no `CAST_OK` gate.
                self.do_cast_spell_if_can(
                    guid,
                    DOOMGRIP_SPELL_HEALING_POTION,
                    CastTarget::Unit(victim),
                );
                if let Some(s) = self.watchman_doomgrip_state_mut(guid) {
                    s.healing_potion_timer_ms = 15_000;
                }
            }
        }
        let due = {
            let Some(s) = self.watchman_doomgrip_state_mut(guid) else {
                return;
            };
            if s.sunder_armor_timer_ms < diff_ms {
                true
            } else {
                s.sunder_armor_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // No `CAST_OK` gate (cpp 1343).
            self.do_cast_spell_if_can(guid, DOOMGRIP_SPELL_SUNDER_ARMOR, CastTarget::Unit(victim));
            if let Some(s) = self.watchman_doomgrip_state_mut(guid) {
                s.sunder_armor_timer_ms = 10_000;
            }
        }
    }

