    /// `AttackThief` (cpp 1585-1594): external entry; transcribed as
    /// a `Map` helper.
    #[allow(dead_code)] // wired by the ale-mug GO handler
    fn plugger_attack_thief(&mut self, guid: ObjectGuid, player: ObjectGuid) {
        if player.is_empty() {
            return;
        }
        let yell = if self.rng.urand(0, 1) < 1 {
            PLUGGER_YELL_AGGRO_1
        } else {
            PLUGGER_YELL_AGGRO_2
        };
        self.do_script_text(yell, guid, None, -1);
        // NEEDS-MAP-HELPER: `SetFacingToObject(pPlayer)` (cpp 1590).
        // `SetFactionTemporary(FACTION_DARK_IRON,
        // TEMPFACTION_RESTORE_RESPAWN)` (cpp 1591): no
        // temporary-faction helper; the sticky write is the
        // reachable part (restore semantics unresolved).
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
            BRD_FACTION_DARK_IRON,
        );
        self.attack_start(guid, player);
    }

    /// `boss_plugger_spazzringAI::UpdateAI` (cpp 1596-1676): combat
    /// branch on hostile target, else the OOC branch (fork order).
    /// Uses `get_hostile_target` (no evade/proximity side effects)
    /// so the OOC says survive targetless ticks.
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn plugger_spazzring_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if let Some(victim) = self.get_hostile_target(guid) {
            let banish_due = {
                let Some(s) = self.plugger_spazzring_state_mut(guid) else {
                    return;
                };
                if s.banish_timer_ms < diff_ms {
                    true
                } else {
                    s.banish_timer_ms -= diff_ms;
                    false
                }
            };
            if banish_due {
                // `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 1)`
                // (cpp 1603).
                if let Some(target) = self.select_random_hostile(guid) {
                    if self.do_cast_spell_if_can(
                        guid,
                        PLUGGER_SPELL_BANISH,
                        CastTarget::Unit(target),
                    ) {
                        let next = self.rng.urand(26, 28) * 1000;
                        if let Some(s) = self.plugger_spazzring_state_mut(guid) {
                            s.banish_timer_ms = next;
                        }
                    }
                }
            }
            let immolate_due = {
                let Some(s) = self.plugger_spazzring_state_mut(guid) else {
                    return;
                };
                if s.immolate_timer_ms < diff_ms {
                    true
                } else {
                    s.immolate_timer_ms -= diff_ms;
                    false
                }
            };
            if immolate_due
                && self.do_cast_spell_if_can(guid, PLUGGER_SPELL_IMMOLATE, CastTarget::Unit(victim))
            {
                if let Some(s) = self.plugger_spazzring_state_mut(guid) {
                    s.immolate_timer_ms = 25_000;
                }
            }
            let bolt_due = {
                let Some(s) = self.plugger_spazzring_state_mut(guid) else {
                    return;
                };
                if s.shadow_bolt_timer_ms < diff_ms {
                    true
                } else {
                    s.shadow_bolt_timer_ms -= diff_ms;
                    false
                }
            };
            if bolt_due
                && self.do_cast_spell_if_can(
                    guid,
                    PLUGGER_SPELL_SHADOW_BOLT,
                    CastTarget::Unit(victim),
                )
            {
                let next = self.rng.urand(36, 63) * 100;
                if let Some(s) = self.plugger_spazzring_state_mut(guid) {
                    s.shadow_bolt_timer_ms = next;
                }
            }
            let tongues_due = {
                let Some(s) = self.plugger_spazzring_state_mut(guid) else {
                    return;
                };
                if s.curse_of_tongues_timer_ms < diff_ms {
                    true
                } else {
                    s.curse_of_tongues_timer_ms -= diff_ms;
                    false
                }
            };
            if tongues_due {
                // `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 0,
                // SPELL_CURSE_OF_TONGUES, SELECT_FLAG_POWER_MANA)`
                // (cpp 1630): mana-user filter unmodeled.
                if let Some(target) = self.select_random_hostile(guid) {
                    if self.do_cast_spell_if_can(
                        guid,
                        PLUGGER_SPELL_CURSE_OF_TONGUES,
                        CastTarget::Unit(target),
                    ) {
                        let next = self.rng.urand(19, 31) * 1000;
                        if let Some(s) = self.plugger_spazzring_state_mut(guid) {
                            s.curse_of_tongues_timer_ms = next;
                        }
                    }
                }
            }
        } else {
            // NOTE: fork uses `<=` for the OOC timers (cpp 1646, 1658).
            if self
                .plugger_spazzring_state_mut(guid)
                .is_some_and(|s| s.ooc_say_timer_ms != 0)
            {
                let say = {
                    let Some(s) = self.plugger_spazzring_state_mut(guid) else {
                        return;
                    };
                    if s.ooc_say_timer_ms <= diff_ms {
                        true
                    } else {
                        s.ooc_say_timer_ms -= diff_ms;
                        false
                    }
                };
                if say {
                    let text = PLUGGER_RANDOM_SAYS[self.rng.urand(0, 3) as usize];
                    self.do_script_text(text, guid, None, -1);
                    let next = self.rng.urand(30_000, 35_000);
                    if let Some(s) = self.plugger_spazzring_state_mut(guid) {
                        s.ooc_say_timer_ms = next;
                    }
                }
            }
            if self
                .plugger_spazzring_state_mut(guid)
                .is_some_and(|s| s.pickpocket_timer_ms != 0)
            {
                let caught = {
                    let Some(s) = self.plugger_spazzring_state_mut(guid) else {
                        return;
                    };
                    if s.pickpocket_timer_ms <= diff_ms {
                        true
                    } else {
                        s.pickpocket_timer_ms -= diff_ms;
                        false
                    }
                };
                if caught {
                    self.do_script_text(PLUGGER_YELL_PICKPOCKETED, guid, None, -1);
                    // `SetFactionTemporary(FACTION_DARK_IRON,
                    // TEMPFACTION_RESTORE_RESPAWN)` (cpp 1660): sticky
                    // write only (restore semantics unresolved).
                    let _ = self.object_set_field(
                        guid,
                        u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                        BRD_FACTION_DARK_IRON,
                    );
                    if let Some(s) = self.plugger_spazzring_state_mut(guid) {
                        s.pickpocket_timer_ms = 0;
                        s.ooc_say_timer_ms = 0;
                    }
                }
            }
            let armor_due = {
                let Some(s) = self.plugger_spazzring_state_mut(guid) else {
                    return;
                };
                if s.demon_armor_timer_ms < diff_ms {
                    true
                } else {
                    s.demon_armor_timer_ms -= diff_ms;
                    false
                }
            };
            if armor_due
                && self.do_cast_spell_if_can(guid, PLUGGER_SPELL_DEMON_ARMOR, CastTarget::SelfCast)
            {
                if let Some(s) = self.plugger_spazzring_state_mut(guid) {
                    s.demon_armor_timer_ms = 5 * 60 * 1000;
                }
            }
        }
    }

