    /// `boss_emperor_dagran_thaurissanAI::JustDied` (cpp 68-82).
    fn emperor_thaurissan_just_died(&mut self, _guid: ObjectGuid) {
        // `GetCreature(GetData64(DATA_PRINCESS))` (cpp 73).
        let princess = self
            .brd_get_data64(BRD_DATA_PRINCESS)
            .unwrap_or(ObjectGuid::EMPTY);
        if princess.is_empty() || !self.creatures.contains_key(&princess) {
            return;
        }
        if !self.unit_is_alive(princess) {
            return;
        }
        let _ = self.object_set_field(
            princess,
            u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
            EMPEROR_FACTION_FRIENDLY,
        );
        self.enter_evade_mode(princess);
        self.do_script_text(EMPEROR_EMOTE_SHAKEN, princess, None, -1);
    }

