    /// `boss_emperor_dagran_thaurissanAI::UpdateAI` (cpp 86-130).
    /// The fork `m_uiIronfoeTimer` block is commented out
    /// (cpp 118-127); dropped (see unresolved).
    fn emperor_thaurissan_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let hand_due = {
            let Some(s) = self.emperor_thaurissan_state_mut(guid) else {
                return;
            };
            if s.hand_of_thaurissan_timer_ms < diff_ms {
                true
            } else {
                s.hand_of_thaurissan_timer_ms -= diff_ms;
                false
            }
        };
        if hand_due {
            // `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 1,
            // nullptr, SELECT_FLAG_PLAYER)` existence check, then
            // the cast lands on the victim (cpp 93-97).
            if self.select_random_hostile(guid).is_some()
                && self.do_cast_spell_if_can(
                    guid,
                    EMPEROR_SPELL_HAND_OF_THAURISSAN,
                    CastTarget::Unit(victim),
                )
            {
                let next = self.rng.urand(10_000, 15_000);
                if let Some(s) = self.emperor_thaurissan_state_mut(guid) {
                    s.hand_of_thaurissan_timer_ms = next;
                }
            }
        }
        let avatar_due = {
            let Some(s) = self.emperor_thaurissan_state_mut(guid) else {
                return;
            };
            if s.avatar_of_flame_timer_ms < diff_ms {
                true
            } else {
                s.avatar_of_flame_timer_ms -= diff_ms;
                false
            }
        };
        if avatar_due {
            // No `CAST_OK` gate (cpp 104).
            self.do_cast_spell_if_can(guid, EMPEROR_SPELL_AVATAR_OF_FLAME, CastTarget::SelfCast);
            if let Some(s) = self.emperor_thaurissan_state_mut(guid) {
                s.avatar_of_flame_timer_ms = 18_000;
            }
        }
        let help_due = {
            let Some(s) = self.emperor_thaurissan_state_mut(guid) else {
                return;
            };
            if s.call_for_help_timer_ms < diff_ms {
                true
            } else {
                s.call_for_help_timer_ms -= diff_ms;
                false
            }
        };
        if help_due {
            // NEEDS-MAP-HELPER: `CallForHelp(VISIBLE_RANGE)` (cpp 112).
            if let Some(s) = self.emperor_thaurissan_state_mut(guid) {
                s.call_for_help_timer_ms = 20_000;
            }
        }
    }

