    /// `boss_general_angerforgeAI::UpdateAI` (cpp 65-97).
    fn general_angerforge_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let sunder_due = {
            let Some(s) = self.general_angerforge_state_mut(guid) else {
                return;
            };
            if s.sunder_armor_timer_ms < diff_ms {
                true
            } else {
                s.sunder_armor_timer_ms -= diff_ms;
                false
            }
        };
        if sunder_due
            && self.do_cast_spell_if_can(
                guid,
                ANGERFORGE_SPELL_SUNDER_ARMOR,
                CastTarget::Unit(victim),
            )
        {
            let next = self.rng.urand(5 * 1000, 15 * 1000);
            if let Some(s) = self.general_angerforge_state_mut(guid) {
                s.sunder_armor_timer_ms = next;
            }
        }
        if self.creature_health_percent(guid) < 30.0 {
            let alarm_due = {
                let Some(s) = self.general_angerforge_state_mut(guid) else {
                    return;
                };
                if s.alarm_timer_ms < diff_ms {
                    true
                } else {
                    s.alarm_timer_ms -= diff_ms;
                    false
                }
            };
            if alarm_due {
                self.do_script_text(ANGERFORGE_EMOTE_ALARM, guid, None, -1);
                for spawn in &ANGERFORGE_ADD_SPAWNS {
                    self.summon_creature(
                        spawn.entry,
                        Position::new(spawn.x, spawn.y, spawn.z, spawn.o),
                        guid,
                        ANGERFORGE_TEMPSUMMON_TIMED_OR_CORPSE,
                        30 * 1000,
                    );
                }
                if let Some(s) = self.general_angerforge_state_mut(guid) {
                    s.alarm_timer_ms = 3 * 60 * 1000;
                }
            }
        }
    }

