    /// `GetDwarfForPhase` (cpp 92-112) as a guid lookup; phase 6 is
    /// Doomrel itself, out-of-range phases yield `None` (fork
    /// `nullptr`). `m_pInstance` null reads yield `None` via the
    /// `brd_get_data64` accessors.
    fn doomrel_dwarf_for_phase(&self, guid: ObjectGuid, phase: u8) -> Option<ObjectGuid> {
        match phase {
            0 => self.brd_get_data64(BRD_DATA_ANGERREL),
            1 => self.brd_get_data64(BRD_DATA_SEETHREL),
            2 => self.brd_get_data64(BRD_DATA_DOPEREL),
            3 => self.brd_get_data64(BRD_DATA_GLOOMREL),
            4 => self.brd_get_data64(BRD_DATA_VILEREL),
            5 => self.brd_get_data64(BRD_DATA_HATEREL),
            6 => Some(guid),
            _ => None,
        }
    }

    /// `CallToFight` (cpp 114-132).
    fn doomrel_call_to_fight(&mut self, guid: ObjectGuid, round: u8, start_fight: bool) {
        let Some(dwarf) = self.doomrel_dwarf_for_phase(guid, round) else {
            return;
        };
        if !self.creatures.contains_key(&dwarf) {
            return;
        }
        if start_fight && self.unit_is_alive(dwarf) {
            let flags = self.object_get_field(dwarf, offsets::UNIT_FIELD_FLAGS);
            let _ = self.object_set_field(
                dwarf,
                u32::from(offsets::UNIT_FIELD_FLAGS),
                flags & !DOOMREL_UNIT_FLAG_IMMUNE_TO_PLAYER,
            );
            // Fork `SetFactionTemplateId(FACTION_HOSTILE)` (cpp 121);
            // `FACTION_HOSTILE` (54) reuses `BRD_FACTION_DARK_IRON`.
            let _ = self.object_set_field(
                dwarf,
                u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                BRD_FACTION_DARK_IRON,
            );
            self.set_in_combat_with_zone(dwarf);
        } else {
            if !self.unit_is_alive(dwarf) {
                // NEEDS-MAP-HELPER: `Respawn()` (cpp 127): no
                // creature-respawn helper.
            }
            let _ = self.object_set_field(
                dwarf,
                u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                DOOMREL_FACTION_NEUTRAL,
            );
        }
    }

    /// `boss_doomrelAI::UpdateAI` (cpp 134-233).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn doomrel_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Tomb event driver (fork order: before the drive, cpp 136-182).
        if self.brd_get_data(BRD_TYPE_TOMB_OF_SEVEN) == Some(IN_PROGRESS) {
            let round = self.doomrel_state_mut(guid).map_or(0, |s| s.dwarf_round);
            if round < DOOMREL_MAX_DWARF {
                let call_due = {
                    let Some(s) = self.doomrel_state_mut(guid) else {
                        return;
                    };
                    if s.call_to_fight_timer_ms < diff_ms {
                        true
                    } else {
                        s.call_to_fight_timer_ms -= diff_ms;
                        false
                    }
                };
                if call_due {
                    self.doomrel_call_to_fight(guid, round, true);
                    if let Some(s) = self.doomrel_state_mut(guid) {
                        s.dwarf_round = s.dwarf_round.saturating_add(1);
                        s.call_to_fight_timer_ms = 30_000;
                        s.wipe_check_timer_ms = 25_000;
                    }
                }
                let wipe_due = {
                    let Some(s) = self.doomrel_state_mut(guid) else {
                        return;
                    };
                    if s.wipe_check_timer_ms < diff_ms {
                        true
                    } else {
                        s.wipe_check_timer_ms -= diff_ms;
                        false
                    }
                };
                if wipe_due {
                    // `GetDwarfForPhase(m_uiDwarfRound - 1)` (cpp 154):
                    // `checked_sub` keeps the fork `nullptr` case
                    // (`round == 0`) as `None`.
                    let dwarf = round
                        .checked_sub(1)
                        .and_then(|prev| self.doomrel_dwarf_for_phase(guid, prev));
                    if let Some(dwarf) = dwarf {
                        if self.creatures.contains_key(&dwarf)
                            && self.unit_is_alive(dwarf)
                            && (self.get_hostile_target(dwarf).is_none()
                                || self.unit_victim(dwarf).is_none())
                        {
                            self.brd_set_data(BRD_TYPE_TOMB_OF_SEVEN, BRD_FAIL);
                        }
                    }
                    if let Some(s) = self.doomrel_state_mut(guid) {
                        s.wipe_check_timer_ms = 50_000;
                    }
                }
            }
        } else if self.brd_get_data(BRD_TYPE_TOMB_OF_SEVEN) == Some(BRD_FAIL) {
            for round in 0..DOOMREL_MAX_DWARF {
                self.doomrel_call_to_fight(guid, round, false);
            }
            if let Some(s) = self.doomrel_state_mut(guid) {
                s.dwarf_round = 0;
                s.call_to_fight_timer_ms = 0;
            }
            self.brd_set_data(BRD_TYPE_TOMB_OF_SEVEN, BRD_NOT_STARTED);
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let volley_due = {
            let Some(s) = self.doomrel_state_mut(guid) else {
                return;
            };
            if s.shadow_volley_timer_ms < diff_ms {
                true
            } else {
                s.shadow_volley_timer_ms -= diff_ms;
                false
            }
        };
        if volley_due {
            // No `CAST_OK` gate (cpp 190).
            self.do_cast_spell_if_can(
                guid,
                DOOMREL_SPELL_SHADOWBOLTVOLLEY,
                CastTarget::Unit(victim),
            );
            if let Some(s) = self.doomrel_state_mut(guid) {
                s.shadow_volley_timer_ms = 12_000;
            }
        }
        let immolate_due = {
            let Some(s) = self.doomrel_state_mut(guid) else {
                return;
            };
            if s.immolate_timer_ms < diff_ms {
                true
            } else {
                s.immolate_timer_ms -= diff_ms;
                false
            }
        };
        if immolate_due {
            // `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 0)` (cpp 199).
            if let Some(target) = self.select_random_hostile(guid) {
                self.do_cast_spell_if_can(guid, DOOMREL_SPELL_IMMOLATE, CastTarget::Unit(target));
            }
            if let Some(s) = self.doomrel_state_mut(guid) {
                s.immolate_timer_ms = 25_000;
            }
        }
        let weakness_due = {
            let Some(s) = self.doomrel_state_mut(guid) else {
                return;
            };
            if s.curse_of_weakness_timer_ms < diff_ms {
                true
            } else {
                s.curse_of_weakness_timer_ms -= diff_ms;
                false
            }
        };
        if weakness_due {
            // No `CAST_OK` gate (cpp 210).
            self.do_cast_spell_if_can(
                guid,
                DOOMREL_SPELL_CURSE_OF_WEAKNESS,
                CastTarget::Unit(victim),
            );
            if let Some(s) = self.doomrel_state_mut(guid) {
                s.curse_of_weakness_timer_ms = 45_000;
            }
        }
        let armor_due = {
            let Some(s) = self.doomrel_state_mut(guid) else {
                return;
            };
            if s.demon_armor_timer_ms < diff_ms {
                true
            } else {
                s.demon_armor_timer_ms -= diff_ms;
                false
            }
        };
        if armor_due {
            // No `CAST_OK` gate (cpp 219).
            self.do_cast_spell_if_can(guid, DOOMREL_SPELL_DEMON_ARMOR, CastTarget::SelfCast);
            if let Some(s) = self.doomrel_state_mut(guid) {
                s.demon_armor_timer_ms = 300_000;
            }
        }
        let summon = self
            .doomrel_state_mut(guid)
            .is_some_and(|s| !s.has_summoned);
        if summon && self.creature_health_percent(guid) <= 50.0 {
            // `CastSpell(m_creature, SPELL_SUMMON_VOIDWALKERS, true)`
            // (cpp 228): triggered self-cast.
            let _ = self.cast_spell(
                guid,
                DOOMREL_SPELL_SUMMON_VOIDWALKERS,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
            if let Some(s) = self.doomrel_state_mut(guid) {
                s.has_summoned = true;
            }
        }
    }

