    /// `boss_chromaggusAI::UpdateAI` (cpp 207-381).
    #[allow(clippy::similar_names)]
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn chromaggus_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Pre-drive lever walk (cpp 209-233): runs while out of combat and
        // never engaged.
        let engaged = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Chromaggus(s)) => Some(s.engaged_once),
                _ => None,
            })
            .unwrap_or(false);
        if !self.ai_in_combat(guid) && !engaged {
            let door_open = self
                .instance_get_data64(BWL_DATA_DOOR_CHROMAGGUS_SIDE)
                .is_some_and(|go| self.go_state(go) == GO_STATE_ACTIVE);
            if door_open {
                let due = {
                    let Some(s) = self.chromaggus_state_mut(guid) else {
                        return;
                    };
                    if s.moveto_lever_timer_ms < diff_ms {
                        true
                    } else {
                        s.moveto_lever_timer_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    if let Some(c) = self.creatures.get_mut(&guid) {
                        c.home_position =
                            Position::new(-7484.6094, -1075.6781, 477.1446, 0.616_172);
                    }
                    self.set_walk(guid, true);
                    self.creature_move_point(
                        guid,
                        0,
                        Position::new(-7484.6094, -1075.6781, 477.1446, 0.0),
                        BWL_MOVE_PATHFINDING,
                        0.0,
                        0.0,
                    );
                    let mask = BWL_UNIT_FLAG_NOT_SELECTABLE
                        | BWL_UNIT_FLAG_SPAWNING
                        | BWL_UNIT_FLAG_IMMUNE_TO_NPC;
                    let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
                    let _ = self.object_set_field(
                        guid,
                        u32::from(offsets::UNIT_FIELD_FLAGS),
                        flags & !mask,
                    );
                    if let Some(s) = self.chromaggus_state_mut(guid) {
                        s.engaged_once = true;
                    }
                }
            } else {
                let mask = BWL_UNIT_FLAG_NOT_SELECTABLE;
                if self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS) & mask == 0 {
                    let full = BWL_UNIT_FLAG_NOT_SELECTABLE
                        | BWL_UNIT_FLAG_SPAWNING
                        | BWL_UNIT_FLAG_IMMUNE_TO_NPC;
                    let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
                    let _ = self.object_set_field(
                        guid,
                        u32::from(offsets::UNIT_FIELD_FLAGS),
                        flags | full,
                    );
                }
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Shimmer (cpp 238-257): no re-roll while due; timer resets only on
        // a successful cast.
        let shimmer_due = {
            let Some(s) = self.chromaggus_state_mut(guid) else {
                return;
            };
            if s.shimmer_timer_ms < diff_ms {
                true
            } else {
                s.shimmer_timer_ms -= diff_ms;
                false
            }
        };
        if shimmer_due {
            let old = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::Chromaggus(s)) => Some(s.current_vulnerability_spell),
                    _ => None,
                })
                .unwrap_or(0);
            if old != 0 {
                self.cancel_aura(guid, old);
            }
            // `PickRandomValue` over the five vulnerabilities (cpp 246).
            let spell = match self.spell_rng().irand(0, 4) {
                0 => CHROMAGGUS_SPELL_FIRE_VULN,
                1 => CHROMAGGUS_SPELL_FROST_VULN,
                2 => CHROMAGGUS_SPELL_SHADOW_VULN,
                3 => CHROMAGGUS_SPELL_NATURE_VULN,
                _ => CHROMAGGUS_SPELL_ARCANE_VULN,
            };
            if self.do_cast_spell_if_can(guid, spell, CastTarget::SelfCast) {
                if let Some(s) = self.chromaggus_state_mut(guid) {
                    s.current_vulnerability_spell = spell;
                    s.shimmer_timer_ms = 20_000;
                }
                self.do_script_text(CHROMAGGUS_EMOTE_SHIMMER, guid, None, -1);
            }
        }
        // Breath one (cpp 259-266).
        let breath_one = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Chromaggus(s)) => Some(s.breath_one_spell),
                _ => None,
            })
            .unwrap_or(0);
        let breath_due = {
            let Some(s) = self.chromaggus_state_mut(guid) else {
                return;
            };
            if s.breath_one_timer_ms < diff_ms {
                true
            } else {
                s.breath_one_timer_ms -= diff_ms;
                false
            }
        };
        if breath_due
            && breath_one != 0
            && self.do_cast_spell_if_can(guid, breath_one, CastTarget::SelfCast)
            && let Some(s) = self.chromaggus_state_mut(guid)
        {
            s.breath_one_timer_ms = 60_000;
        }
        // Breath two (cpp 268-275).
        let breath_two = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Chromaggus(s)) => Some(s.breath_two_spell),
                _ => None,
            })
            .unwrap_or(0);
        let breath_two_due = {
            let Some(s) = self.chromaggus_state_mut(guid) else {
                return;
            };
            if s.breath_two_timer_ms < diff_ms {
                true
            } else {
                s.breath_two_timer_ms -= diff_ms;
                false
            }
        };
        if breath_two_due
            && breath_two != 0
            && self.do_cast_spell_if_can(guid, breath_two, CastTarget::SelfCast)
            && let Some(s) = self.chromaggus_state_mut(guid)
        {
            s.breath_two_timer_ms = 60_000;
        }
        // Affliction (cpp 277-324): `PickRandomValue` over the five
        // afflictions, applied 11-15 times to random targets.
        let affliction_due = {
            let Some(s) = self.chromaggus_state_mut(guid) else {
                return;
            };
            if s.affliction_timer_ms < diff_ms {
                true
            } else {
                s.affliction_timer_ms -= diff_ms;
                false
            }
        };
        if affliction_due {
            let afflict = match self.spell_rng().irand(0, 4) {
                0 => CHROMAGGUS_SPELL_BROODAF_BLUE,
                1 => CHROMAGGUS_SPELL_BROODAF_BLACK,
                2 => CHROMAGGUS_SPELL_BROODAF_RED,
                3 => CHROMAGGUS_SPELL_BROODAF_BRONZE,
                _ => CHROMAGGUS_SPELL_BROODAF_GREEN,
            };
            if afflict == CHROMAGGUS_SPELL_BROODAF_RED
                && let Some(s) = self.chromaggus_state_mut(guid)
            {
                s.red_affliction_guids.clear();
            }
            // Fork rolls `urand(11, 15)` on EVERY loop check (cpp 287), so the
            // trip count is re-drawn per iteration, not fixed up front.
            let mut afflicted = 0u32;
            while afflicted < self.rng.urand(11, 15) {
                // Fork `++i` runs even on `continue` (cpp 287-320).
                afflicted += 1;
                // NEEDS-MAP-HELPER: `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 0)`.
                let Some(target) = self.select_random_hostile(guid) else {
                    continue;
                };
                if self.bot_has_aura(target, CHROMAGGUS_SPELL_CHROMATIC_MUT_1) {
                    continue;
                }
                let cast = self.cast_spell(
                    guid,
                    afflict,
                    CastTarget::Unit(target),
                    CastOptions {
                        triggered: true,
                        skip_known: true,
                        ..Default::default()
                    },
                ) == CastOutcome::Started;
                if cast && afflict == CHROMAGGUS_SPELL_BROODAF_RED && target.is_player() {
                    if let Some(s) = self.chromaggus_state_mut(guid) {
                        s.red_affliction_guids.push(target);
                    }
                }
                if self.bot_has_aura(target, CHROMAGGUS_SPELL_BROODAF_BLUE)
                    && self.bot_has_aura(target, CHROMAGGUS_SPELL_BROODAF_BLACK)
                    && self.bot_has_aura(target, CHROMAGGUS_SPELL_BROODAF_RED)
                    && self.bot_has_aura(target, CHROMAGGUS_SPELL_BROODAF_BRONZE)
                    && self.bot_has_aura(target, CHROMAGGUS_SPELL_BROODAF_GREEN)
                {
                    self.cancel_aura(target, CHROMAGGUS_SPELL_BROODAF_BLUE);
                    self.cancel_aura(target, CHROMAGGUS_SPELL_BROODAF_BLACK);
                    self.cancel_aura(target, CHROMAGGUS_SPELL_BROODAF_RED);
                    self.cancel_aura(target, CHROMAGGUS_SPELL_BROODAF_BRONZE);
                    self.cancel_aura(target, CHROMAGGUS_SPELL_BROODAF_GREEN);
                    if target.is_player() {
                        // Fork `AddAura` caster form: applier is Chromaggus.
                        self.apply_aura_by_id(guid, CHROMAGGUS_SPELL_CHROMATIC_MUT_1, target);
                        self.apply_aura_by_id(guid, CHROMAGGUS_SPELL_CHROMATIC_MUT_ONE, target);
                        self.apply_aura_by_id(guid, CHROMAGGUS_SPELL_CHROMATIC_MUT_TWO, target);
                        if let Some(s) = self.chromaggus_state_mut(guid) {
                            s.chromatic_guids.push(target);
                        }
                    } else {
                        // NEEDS-MAP-HELPER: pet `DealDamage(self, GetHealth())`.
                    }
                }
            }
            if let Some(s) = self.chromaggus_state_mut(guid) {
                s.affliction_timer_ms = 7500;
            }
        }
        // Red-affliction deaths heal Chromaggus (cpp 326-343).
        let red_list = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Chromaggus(s)) => Some(s.red_affliction_guids.clone()),
                _ => None,
            })
            .unwrap_or_default();
        let mut red_idx = 0;
        while red_idx < red_list.len() {
            let player = red_list[red_idx];
            let alive = self.unit_is_alive(player);
            let has = self.bot_has_aura(player, CHROMAGGUS_SPELL_BROODAF_RED);
            if alive && !has {
                if let Some(s) = self.chromaggus_state_mut(guid) {
                    s.red_affliction_guids.retain(|g| *g != player);
                }
                continue;
            }
            if !alive {
                if self.do_cast_spell_if_can(
                    guid,
                    CHROMAGGUS_SPELL_CHROMA_HEAL,
                    CastTarget::SelfCast,
                ) && let Some(s) = self.chromaggus_state_mut(guid)
                {
                    s.red_affliction_guids.retain(|g| *g != player);
                }
                break;
            }
            red_idx += 1;
        }
        // Chromatic-mutation deaths (cpp 345-360); the fork casts
        // `SPELL_BROOD_AFFLICTION_RED` (== `SPELL_CHROMA_HEAL`, 23168).
        let chromatic = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Chromaggus(s)) => Some(s.chromatic_guids.clone()),
                _ => None,
            })
            .unwrap_or_default();
        for player in chromatic {
            if !self.unit_is_alive(player) {
                self.cancel_aura(player, CHROMAGGUS_SPELL_CHROMATIC_MUT_ONE);
                self.cancel_aura(player, CHROMAGGUS_SPELL_CHROMATIC_MUT_TWO);
                if self.do_cast_spell_if_can(
                    guid,
                    CHROMAGGUS_SPELL_CHROMA_HEAL,
                    CastTarget::SelfCast,
                ) && let Some(s) = self.chromaggus_state_mut(guid)
                {
                    s.chromatic_guids.retain(|g| *g != player);
                }
                break;
            }
        }
        // Frenzy (cpp 361-371).
        let frenzy_due = {
            let Some(s) = self.chromaggus_state_mut(guid) else {
                return;
            };
            if s.frenzy_timer_ms < diff_ms {
                true
            } else {
                s.frenzy_timer_ms -= diff_ms;
                false
            }
        };
        if frenzy_due
            && self.do_cast_spell_if_can(guid, CHROMAGGUS_SPELL_FRENZY, CastTarget::SelfCast)
        {
            self.do_script_text(CHROMAGGUS_EMOTE_FRENZY_KILL, guid, None, -1);
            if let Some(s) = self.chromaggus_state_mut(guid) {
                s.frenzy_timer_ms = 15_000;
            }
        }
        // Enrage below 20% (cpp 373-378).
        let enraged = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Chromaggus(s)) if s.enraged),
        );
        if !enraged
            && self.creature_health_percent(guid) < 20.0
            && self.do_cast_spell_if_can(guid, CHROMAGGUS_SPELL_ENRAGE, CastTarget::SelfCast)
            && let Some(s) = self.chromaggus_state_mut(guid)
        {
            s.enraged = true;
        }
        let _ = victim;
    }

