    /// `boss_flamegorAI::SpellHitTarget` (cpp 71-80). NO-DISPATCHER-YET.
    fn flamegor_spell_hit(&mut self, guid: ObjectGuid, target: ObjectGuid, spell_id: u32) {
        if spell_id != FLAMEGOR_SPELL_WING_BUFFET {
            return;
        }
        if !target.is_player() {
            return;
        }
        if self.threat_on(guid, target) != 0.0 {
            self.modify_threat_percent_of(guid, target, -50);
        }
    }

    /// `boss_flamegorAI::UpdateAI` (cpp 82-121).
    fn flamegor_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let shadow_due = {
            let Some(s) = self.flamegor_state_mut(guid) else {
                return;
            };
            if s.shadow_flame_timer_ms < diff_ms {
                true
            } else {
                s.shadow_flame_timer_ms -= diff_ms;
                false
            }
        };
        if shadow_due
            && self.do_cast_spell_if_can(guid, FLAMEGOR_SPELL_SHADOW_FLAME, CastTarget::SelfCast)
            && let Some(s) = self.flamegor_state_mut(guid)
        {
            s.shadow_flame_timer_ms = 16_000;
        }
        let buffet_due = {
            let Some(s) = self.flamegor_state_mut(guid) else {
                return;
            };
            if s.wing_buffet_timer_ms < diff_ms {
                true
            } else {
                s.wing_buffet_timer_ms -= diff_ms;
                false
            }
        };
        if buffet_due
            && self.do_cast_spell_if_can(guid, FLAMEGOR_SPELL_WING_BUFFET, CastTarget::Unit(victim))
            && let Some(s) = self.flamegor_state_mut(guid)
        {
            s.wing_buffet_timer_ms = 30_000;
        }
        let frenzy_due = {
            let Some(s) = self.flamegor_state_mut(guid) else {
                return;
            };
            if s.frenzy_timer_ms < diff_ms {
                true
            } else {
                s.frenzy_timer_ms -= diff_ms;
                false
            }
        };
        if frenzy_due
            && self.do_cast_spell_if_can(guid, FLAMEGOR_SPELL_FRENZY, CastTarget::SelfCast)
        {
            self.do_script_text(FLAMEGOR_EMOTE_FRENZY, guid, None, -1);
            if let Some(s) = self.flamegor_state_mut(guid) {
                s.frenzy_timer_ms = 10_000;
            }
        }
        // `IsAttackReady() && !urand(0, 2)` thrash (cpp 117-118).
        // NEEDS-MAP-HELPER: `IsAttackReady()` swing gate.
        if self.rng.urand(0, 2) == 0 {
            self.do_cast_spell_if_can(guid, FLAMEGOR_SPELL_THRASH, CastTarget::SelfCast);
        }
    }

    /// `boss_nefarianAI::Reset` (cpp 102-127).
    fn nefarian_reset(&mut self, guid: ObjectGuid) {
        let shadow_flame = self.rng.urand(18_000, 25_000);
        let roar = self.rng.urand(25_000, 30_000);
        let cleave = self.rng.urand(7000, 10_000);
        let class_call = self.rng.urand(25_000, 35_000);
        // NEEDS-MAP-HELPER: `GetMapId() != MAP_BLACKWING_LAIR` (map 469) for
        // the ctor `transition_done` init (cpp 111).
        if let Some(s) = self.nefarian_state_mut(guid) {
            s.shadow_flame_timer_ms = shadow_flame;
            s.bellowing_roar_timer_ms = roar;
            s.veil_of_shadow_timer_ms = 15_000;
            s.cleave_timer_ms = cleave;
            s.tail_lash_timer_ms = 10_000;
            s.class_call_timer_ms = class_call;
            s.phase3 = false;
            s.warrior_stance = false;
            s.transition_stage = 0;
            s.transition_timer_ms = 100;
            s.possible_calls = vec![
                (NEFARIAN_CLASS_WARRIOR, NEFARIAN_SAY_WARRIOR),
                (NEFARIAN_CLASS_PALADIN, NEFARIAN_SAY_PALADIN),
                (NEFARIAN_CLASS_HUNTER, NEFARIAN_SAY_HUNTER),
                (NEFARIAN_CLASS_ROGUE, NEFARIAN_SAY_ROGUE),
                (NEFARIAN_CLASS_PRIEST, NEFARIAN_SAY_PRIEST),
                (NEFARIAN_CLASS_SHAMAN, NEFARIAN_SAY_SHAMAN),
                (NEFARIAN_CLASS_MAGE, NEFARIAN_SAY_MAGE),
                (NEFARIAN_CLASS_WARLOCK, NEFARIAN_SAY_WARLOCK),
                (NEFARIAN_CLASS_DRUID, NEFARIAN_SAY_DRUID),
            ];
        }
    }

