    /// `boss_nefarianAI::HandleClassCall` (cpp 178-250). Returns whether a
    /// living player of the class was found; sets `warrior_stance`.
    fn nefarian_handle_class_call(&mut self, guid: ObjectGuid, class: u8) -> bool {
        if class == 0 {
            return false;
        }
        let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
        let mut found = false;
        for player in players {
            if !self.unit_is_alive(player) {
                continue;
            }
            // NEEDS-MAP-HELPER: `IsGameMaster()` screen + `GetClass()`.
            let player_class: u8 = 0; // NEEDS-MAP-HELPER (see above).
            if player_class != class {
                continue;
            }
            found = true;
            match class {
                NEFARIAN_CLASS_WARRIOR => {
                    self.apply_aura_by_id(guid, NEFARIAN_SPELL_WARRIOR, player);
                }
                NEFARIAN_CLASS_PALADIN => {
                    let _ = self.cast_spell(
                        player,
                        NEFARIAN_SPELL_PALADIN,
                        CastTarget::SelfCast,
                        CastOptions {
                            triggered: true,
                            skip_known: true,
                            ..Default::default()
                        },
                    );
                }
                NEFARIAN_CLASS_HUNTER => {
                    let _ = self.cast_spell(
                        player,
                        NEFARIAN_SPELL_HUNTER,
                        CastTarget::SelfCast,
                        CastOptions {
                            triggered: true,
                            skip_known: true,
                            ..Default::default()
                        },
                    );
                }
                NEFARIAN_CLASS_ROGUE => {
                    let _ = self.cast_spell(
                        player,
                        NEFARIAN_SPELL_ROGUE,
                        CastTarget::SelfCast,
                        CastOptions {
                            triggered: true,
                            skip_known: true,
                            ..Default::default()
                        },
                    );
                }
                NEFARIAN_CLASS_PRIEST => self.apply_aura_by_id(guid, NEFARIAN_SPELL_PRIEST, player),
                NEFARIAN_CLASS_SHAMAN => self.apply_aura_by_id(guid, NEFARIAN_SPELL_SHAMAN, player),
                NEFARIAN_CLASS_MAGE => {
                    let _ = self.cast_spell(
                        player,
                        NEFARIAN_SPELL_MAGE,
                        CastTarget::SelfCast,
                        CastOptions {
                            triggered: true,
                            skip_known: true,
                            ..Default::default()
                        },
                    );
                }
                NEFARIAN_CLASS_WARLOCK => {
                    let _ = self.cast_spell(
                        player,
                        NEFARIAN_SPELL_WARLOCK,
                        CastTarget::SelfCast,
                        CastOptions {
                            triggered: true,
                            skip_known: true,
                            ..Default::default()
                        },
                    );
                }
                NEFARIAN_CLASS_DRUID => self.apply_aura_by_id(guid, NEFARIAN_SPELL_DRUID, player),
                _ => {}
            }
        }
        let warrior = found && class == NEFARIAN_CLASS_WARRIOR;
        if let Some(s) = self.nefarian_state_mut(guid) {
            s.warrior_stance = warrior;
        }
        found
    }

    /// `boss_nefarianAI::UpdateAI` (cpp 252-377).
    #[allow(clippy::cast_possible_truncation)] // `pool.len() as u32` class pick
    #[allow(clippy::too_many_lines)]
    fn nefarian_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Landing transition (cpp 254-293): runs before (and without) the
        // drive; `<= diff` semantics with the stage bump after the switch.
        let (timer, done) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Nefarian(s)) => {
                    Some((s.transition_timer_ms, s.transition_done))
                }
                _ => None,
            })
            .unwrap_or((0, true));
        if timer != 0 && !done {
            let stage = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::Nefarian(s)) => Some(s.transition_stage),
                    _ => None,
                })
                .unwrap_or(0);
            if timer <= diff_ms {
                match stage {
                    0 => {
                        if let Some(ai) = self.ai.get_mut(&guid) {
                            ai.combat_movement = false;
                        }
                        self.set_in_combat_with_zone(guid);
                        // NEEDS-MAP-HELPER: `SetFly(true)` (cpp 263).
                        self.do_script_text(NEFARIAN_SAY_AGGRO, guid, None, -1);
                        self.creature_move_point(
                            guid,
                            1,
                            Position::new(-7449.145, -1320.647, 476.795, 0.0),
                            0,
                            0.0,
                            0.0,
                        );
                        // NEEDS-MAP-HELPER: `MonsterMoveWithSpeed(..., -10.0, 17,
                        // MOVE_FORCE_DESTINATION)` spline burst (cpp 268).
                        if let Some(s) = self.nefarian_state_mut(guid) {
                            s.transition_timer_ms = 0;
                        }
                    }
                    1 => {
                        // NEEDS-MAP-HELPER: `SetFly(false)` (cpp 272).
                        self.do_script_text(NEFARIAN_SAY_SHADOWFLAME, guid, None, -1);
                        self.handle_emote_command(guid, NEFARIAN_EMOTE_LAND);
                        if let Some(s) = self.nefarian_state_mut(guid) {
                            s.transition_timer_ms = 1000;
                        }
                    }
                    2 => {
                        self.set_walk(guid, true);
                        self.cancel_aura(guid, NEFARIAN_SPELL_HOVER);
                        if let Some(target) = self.unit_victim(guid) {
                            self.creature_move_chase(guid, target, 0.0, 0.0);
                            if let Some(ai) = self.ai.get_mut(&guid) {
                                ai.combat_movement = true;
                            }
                            let _ = self.cast_spell(
                                guid,
                                NEFARIAN_SPELL_SHADOWFLAME_PASSIV,
                                CastTarget::Unit(target),
                                CastOptions {
                                    triggered: true,
                                    skip_known: true,
                                    ..Default::default()
                                },
                            );
                        }
                        if let Some(s) = self.nefarian_state_mut(guid) {
                            s.transition_done = true;
                        }
                    }
                    _ => {}
                }
                if let Some(s) = self.nefarian_state_mut(guid) {
                    s.transition_stage = s.transition_stage.saturating_add(1);
                }
            } else if let Some(s) = self.nefarian_state_mut(guid) {
                s.transition_timer_ms -= diff_ms;
            }
        }
        let done = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Nefarian(s)) => Some(s.transition_done),
                _ => None,
            })
            .unwrap_or(true);
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        if !done {
            return;
        }
        let shadow_due = {
            let Some(s) = self.nefarian_state_mut(guid) else {
                return;
            };
            if s.shadow_flame_timer_ms < diff_ms {
                true
            } else {
                s.shadow_flame_timer_ms -= diff_ms;
                false
            }
        };
        if shadow_due
            && self.do_cast_spell_if_can(guid, NEFARIAN_SPELL_SHADOWFLAME, CastTarget::SelfCast)
        {
            let next = self.rng.urand(18_000, 25_000);
            if let Some(s) = self.nefarian_state_mut(guid) {
                s.shadow_flame_timer_ms = next;
            }
        }
        let roar_due = {
            let Some(s) = self.nefarian_state_mut(guid) else {
                return;
            };
            if s.bellowing_roar_timer_ms < diff_ms {
                true
            } else {
                s.bellowing_roar_timer_ms -= diff_ms;
                false
            }
        };
        if roar_due
            && self.do_cast_spell_if_can(guid, NEFARIAN_SPELL_BELLOWING_ROAR, CastTarget::SelfCast)
        {
            let next = self.rng.urand(25_000, 30_000);
            if let Some(s) = self.nefarian_state_mut(guid) {
                s.bellowing_roar_timer_ms = next;
            }
        }
        let veil_due = {
            let Some(s) = self.nefarian_state_mut(guid) else {
                return;
            };
            if s.veil_of_shadow_timer_ms < diff_ms {
                true
            } else {
                s.veil_of_shadow_timer_ms -= diff_ms;
                false
            }
        };
        if veil_due
            && self.do_cast_spell_if_can(
                guid,
                NEFARIAN_SPELL_VEIL_OF_SHADOW,
                CastTarget::Unit(victim),
            )
        {
            let next = self.rng.urand(10_000, 15_000);
            if let Some(s) = self.nefarian_state_mut(guid) {
                s.veil_of_shadow_timer_ms = next;
            }
        }
        let cleave_due = {
            let Some(s) = self.nefarian_state_mut(guid) else {
                return;
            };
            if s.cleave_timer_ms < diff_ms {
                true
            } else {
                s.cleave_timer_ms -= diff_ms;
                false
            }
        };
        if cleave_due
            && self.do_cast_spell_if_can(guid, NEFARIAN_SPELL_CLEAVE, CastTarget::Unit(victim))
        {
            let next = self.rng.urand(7000, 10_000);
            if let Some(s) = self.nefarian_state_mut(guid) {
                s.cleave_timer_ms = next;
            }
        }
        let lash_due = {
            let Some(s) = self.nefarian_state_mut(guid) else {
                return;
            };
            if s.tail_lash_timer_ms < diff_ms {
                true
            } else {
                s.tail_lash_timer_ms -= diff_ms;
                false
            }
        };
        if lash_due
            && self.do_cast_spell_if_can(guid, NEFARIAN_SPELL_TAIL_LASH, CastTarget::SelfCast)
        {
            let next = self.rng.urand(4000, 8000);
            if let Some(s) = self.nefarian_state_mut(guid) {
                s.tail_lash_timer_ms = next;
            }
        }
        // Class call (cpp 343-363): re-arms only when a living player of the
        // picked class exists; otherwise that class is dropped from the pool.
        let class_due = {
            let Some(s) = self.nefarian_state_mut(guid) else {
                return;
            };
            if s.class_call_timer_ms < diff_ms {
                true
            } else {
                s.class_call_timer_ms -= diff_ms;
                false
            }
        };
        if class_due {
            let pool = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::Nefarian(s)) => Some(s.possible_calls.clone()),
                    _ => None,
                })
                .unwrap_or_default();
            if !pool.is_empty() {
                let idx = self.rng.urand(0, pool.len() as u32 - 1) as usize;
                let (class, yell) = pool[idx];
                if self.nefarian_handle_class_call(guid, class) {
                    self.do_script_text(yell, guid, None, -1);
                    let next = self.rng.urand(25_000, 35_000);
                    if let Some(s) = self.nefarian_state_mut(guid) {
                        s.class_call_timer_ms = next;
                    }
                } else if let Some(s) = self.nefarian_state_mut(guid) {
                    s.possible_calls.remove(idx);
                }
            }
        }
        // Phase 3 below 20% (cpp 365-371): self-cast, triggered.
        let phase3 = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Nefarian(s)) if s.phase3),
        );
        if !phase3 && self.creature_health_percent(guid) < 20.0 {
            if let Some(s) = self.nefarian_state_mut(guid) {
                s.phase3 = true;
            }
            self.do_script_text(NEFARIAN_SAY_RAISE_SKELETONS, guid, None, -1);
            let _ = self.cast_spell(
                guid,
                NEFARIAN_SPELL_RAISE_DRAKONID,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
        // `DoMeleeAttackIfReady()` ticks globally; only the windfury bonus
        // roll is transcribed (cpp 373-376).
        if self.bot_has_aura(guid, NEFARIAN_SPELL_WINDFURY_PASSIVE)
            && !self.bot_has_aura(guid, NEFARIAN_SPELL_WINDFURY)
            && self.rng.urand(0, 4) == 0
        {
            let _ = self.cast_spell(
                guid,
                NEFARIAN_SPELL_WINDFURY,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
    }

    /// `npc_corrupted_totemAI::Reset` (cpp 409-418): entry/HP come from the
    /// ctor (cpp 394-402).
    fn corrupted_totem_reset(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: ctor `GetEntry()` + `SetMaxHealth/SetHealth(urand(200, 2000))` (cpp 394-398).
        if let Some(u) = self.unit_base_mut(guid) {
            u.add_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
        }
        // ROOT does not gate Rust motion yet and the fork relies on root to
        // hold the totem still: stop alongside (herod-whirlwind pattern).
        self.stop_moving(guid);
        if !self.bot_has_aura(guid, TOTEM_SPELL_ROOT_SELF) {
            self.apply_aura_by_id(guid, TOTEM_SPELL_ROOT_SELF, guid);
        }
        self.apply_aura_by_id(guid, TOTEM_SPELL_AVOIDANCE, guid);
        if let Some(s) = self.corrupted_totem_state_mut(guid) {
            s.check_timer_ms = 1000;
        }
    }

    /// `npc_corrupted_totemAI::Aggro` (cpp 420).
    fn corrupted_totem_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        self.set_in_combat_with_zone(guid);
    }

    /// `npc_corrupted_totemAI::JustDied` (cpp 422-436).
    fn corrupted_totem_just_died(&mut self, guid: ObjectGuid) {
        let entry = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::CorruptedTotem(s)) => Some(s.creature_entry),
                _ => None,
            })
            .unwrap_or(0);
        let aura = match entry {
            TOTEM_NPC_STONESKIN_VI => TOTEM_SPELL_STONESKIN,
            TOTEM_NPC_HEALING_STREAM_V => TOTEM_SPELL_HEALING_STREAM,
            TOTEM_NPC_WINDFURY_III => NEFARIAN_SPELL_WINDFURY_PASSIVE,
            _ => 0,
        };
        if aura != 0 {
            self.corrupted_totem_set_aura(guid, false, aura);
        }
    }

    /// `npc_corrupted_totemAI::SetAura` (cpp 438-503).
    fn corrupted_totem_set_aura(&mut self, guid: ObjectGuid, on: bool, spell_id: u32) {
        let center = self.object_position(guid).unwrap_or_default();
        let mut mobs: Vec<ObjectGuid> = Vec::new();
        for entry in [
            BWL_NPC_NEFARIAN,
            TOTEM_NPC_BONE_CONSTRUCT,
            TOTEM_NPC_BRONZE_DRAKANOID,
            TOTEM_NPC_BLUE_DRAKANOID,
            TOTEM_NPC_RED_DRAKANOID,
            TOTEM_NPC_GREEN_DRAKANOID,
            TOTEM_NPC_BLACK_DRAKANOID,
            TOTEM_NPC_CHROMATIC_DRAKANOID,
        ] {
            mobs.extend(self.creatures.values().filter_map(|c| {
                if c.info.entry != entry || !c.unit.is_alive() {
                    return None;
                }
                let d = crate::visibility::dist3d(c.unit.world.position(), center);
                if d <= 55.0 { Some(c.unit.guid()) } else { None }
            }));
        }
        let alive = self.unit_is_alive(guid);
        for mob in mobs {
            if on && alive {
                let near = match (self.unit_position(guid), self.unit_position(mob)) {
                    (Some(a), Some(b)) => {
                        let dx = a.x - b.x;
                        let dy = a.y - b.y;
                        let dz = a.z - b.z;
                        (dx * dx + dy * dy + dz * dz).sqrt() <= 40.0
                    }
                    _ => false,
                };
                if near {
                    if !self.bot_has_aura(mob, spell_id) {
                        // `CastCustomSpell` damage/bonus arms (cpp 472-489).
                        let custom: [Option<i32>; 3] = match spell_id {
                            TOTEM_SPELL_STONESKIN => [Some(-310), None, None],
                            TOTEM_SPELL_HEALING_STREAM => [Some(14_000), None, None],
                            _ => [None, None, None],
                        };
                        if custom == [None, None, None] {
                            self.apply_aura_by_id(mob, spell_id, mob);
                        } else {
                            let _ = self.cast_spell(
                                mob,
                                spell_id,
                                CastTarget::Unit(mob),
                                CastOptions {
                                    triggered: true,
                                    skip_known: true,
                                    custom_base_points: custom,
                                    ..Default::default()
                                },
                            );
                        }
                    }
                } else {
                    self.cancel_aura(mob, spell_id);
                }
            } else {
                self.cancel_aura(mob, spell_id);
            }
        }
    }

    /// `npc_corrupted_totemAI::UpdateAI` (cpp 505-545).
    fn corrupted_totem_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if !self.bot_has_aura(guid, TOTEM_SPELL_ROOT_SELF) {
            self.apply_aura_by_id(guid, TOTEM_SPELL_ROOT_SELF, guid);
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let _ = victim;
        let entry = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::CorruptedTotem(s)) => Some(s.creature_entry),
                _ => None,
            })
            .unwrap_or(0);
        // Fire nova totem: aura once, then `DeleteLater` (cpp 516-524).
        if entry == TOTEM_NPC_FIRE_NOVA_V {
            let added = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::CorruptedTotem(s)) => Some(s.aura_added),
                    _ => None,
                })
                .unwrap_or(true);
            if !added {
                self.apply_aura_by_id(guid, TOTEM_SPELL_FIRE_NOVA, guid);
                if let Some(s) = self.corrupted_totem_state_mut(guid) {
                    s.aura_added = true;
                }
                // NEEDS-MAP-HELPER: `DeleteLater()` (cpp 521).
                return;
            }
        }
        let add_aura = match entry {
            TOTEM_NPC_STONESKIN_VI => TOTEM_SPELL_STONESKIN,
            TOTEM_NPC_HEALING_STREAM_V => TOTEM_SPELL_HEALING_STREAM,
            TOTEM_NPC_WINDFURY_III => NEFARIAN_SPELL_WINDFURY_PASSIVE,
            _ => 0,
        };
        if add_aura == 0 {
            return;
        }
        let due = {
            let Some(s) = self.corrupted_totem_state_mut(guid) else {
                return;
            };
            if s.check_timer_ms < diff_ms {
                s.check_timer_ms = 1000;
                true
            } else {
                s.check_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            self.corrupted_totem_set_aura(guid, true, add_aura);
        }
    }

    /// `boss_razorgoreAI::Reset` (cpp 92-103). The ctor `SetUseAiAtControl`
    /// is bind-time work (see unresolved).
    fn razorgore_reset(&mut self, guid: ObjectGuid) {
        if let Some(ai) = self.ai.get_mut(&guid) {
            ai.combat_movement = true;
        }
        if let Some(s) = self.razorgore_state_mut(guid) {
            s.cleave_timer_ms = 9000;
            s.war_stomp_timer_ms = 22_000;
            s.conflagration_timer_ms = 12_000;
            s.fireball_volley_timer_ms = 7000;
            s.out_of_reach_timer_ms = 10_000;
            s.init_timer_ms = 5000;
            s.evade_troops_timer_ms = 5000;
        }
    }

