    /// `npc_death_talon_SeetherAI::UpdateAI` (cpp 670-703).
    fn death_talon_seether_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let frenzy_due = {
            let Some(s) = self.death_talon_seether_state_mut(guid) else {
                return;
            };
            if s.frenzy_timer_ms < diff_ms {
                true
            } else {
                s.frenzy_timer_ms -= diff_ms;
                false
            }
        };
        if frenzy_due && self.do_cast_spell_if_can(guid, SEETHER_SPELL_FRENZY, CastTarget::SelfCast)
        {
            self.do_script_text(SEETHER_EMOTE_FRENZY, guid, None, -1);
            if let Some(s) = self.death_talon_seether_state_mut(guid) {
                s.frenzy_timer_ms = 15_000;
            }
        }
        let engaged = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::DeathTalonSeether(s)) if s.engaged),
        );
        if engaged {
            let buffet_due = {
                let Some(s) = self.death_talon_seether_state_mut(guid) else {
                    return;
                };
                if s.flame_buffet_timer_ms < diff_ms {
                    true
                } else {
                    s.flame_buffet_timer_ms -= diff_ms;
                    false
                }
            };
            if buffet_due
                && self.do_cast_spell_if_can(
                    guid,
                    SEETHER_SPELL_FLAME_BUFFET,
                    CastTarget::Unit(victim),
                )
            {
                let next = self.rng.urand(8000, 12_000);
                if let Some(s) = self.death_talon_seether_state_mut(guid) {
                    s.flame_buffet_timer_ms = next;
                }
            }
        } else if self.can_reach_melee(guid, victim) {
            if let Some(s) = self.death_talon_seether_state_mut(guid) {
                s.engaged = true;
            }
        }
    }

    /// `boss_victor_nefariusAI::Reset` (cpp 141-181) + the ctor drake-pair
    /// roll (cpp 96-105): the pair reads instance `DATA_NEF_COLOR`, which has
    /// no BWL const (load-order-only scalar), so the roll runs here when both
    /// drakes are still 0. Ends with `LoadScepterRun`.
    fn victor_nefarius_reset(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: drake pair from instance `DATA_NEF_COLOR`
        // (cpp 98-104): `one = DRAKES[color % 5]`, `idx2 = color / 5`
        // (+1 when `idx2 == color % 5`), `two = DRAKES[idx2 % 5]`.
        let chroma = self.rng.urand(7000, 9000);
        if let Some(s) = self.victor_nefarius_state_mut(guid) {
            s.killed_adds = 0;
            s.add_spawn_timer_ms = 6000;
            s.add_chroma_spawn_timer_ms = chroma;
            s.shadow_bolt_timer_ms = 5000;
            s.shadow_bolt_volley_timer_ms = 15_000;
            s.fear_timer_ms = 8000;
            s.silence_timer_ms = 20_000;
            s.mind_control_timer_ms = 25_000;
            s.shadow_blink_timer_ms = 1000;
            s.scepter_run_time_ms = 0;
            s.next_scepter_taunt_ms = 0;
            s.scepter_taunt_id = 0;
            s.mind_controlled_guid = ObjectGuid::EMPTY;
            s.mind_controlled_aggro = 0.0;
            s.event_timer_ms = 1000;
            s.blabla_count = 0;
            s.nefa_event_start = false;
            s.phase1 = false;
            s.phase2 = false;
            s.phase2bis = false;
            s.smoke = false;
            s.scepter_run = false;
            s.watch_scepter_run = false;
        }
        let _ = self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE), 35);
        self.unit_set_byte(
            guid,
            offsets::UNIT_FIELD_BYTES_1,
            0,
            NEFARIUS_STAND_STATE_SIT_LOW_CHAIR,
        );
        let npc = self.object_get_field(guid, offsets::UNIT_NPC_FLAGS);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_NPC_FLAGS),
            npc | VAEL_UNIT_NPC_FLAG_GOSSIP,
        );
        // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_ON)` restore (cpp 177-178).
        self.victor_nefarius_load_scepter_run(guid);
    }

    /// `boss_victor_nefariusAI::LoadScepterRun` (cpp 183-207).
    fn victor_nefarius_load_scepter_run(&mut self, guid: ObjectGuid) {
        if self.instance_get_data(BWL_TYPE_SCEPTER_RUN) == Some(BWL_FAIL) {
            return;
        }
        if let Some(s) = self.victor_nefarius_state_mut(guid) {
            s.watch_scepter_run = true;
        }
        if self.instance_get_data(BWL_TYPE_SCEPTER_RUN) == Some(IN_PROGRESS) {
            // NEEDS-MAP-HELPER: `DATA_SCEPTER_RUN_TIME` scalar read (cpp 196;
            // the slot cannot ride `Option<ObjectGuid>`, same class as
            // `DATA_EGG`; see the instance port unresolved).
            if let Some(s) = self.victor_nefarius_state_mut(guid) {
                s.scepter_run = true;
                let elapsed = NEFARIUS_SCEPTER_RUN_TIME
                    .saturating_sub(s.scepter_run_time_ms)
                    .saturating_add(NEFARIUS_SCEPTER_TAUNT_OFFSET);
                s.scepter_taunt_id = elapsed / NEFARIUS_SCEPTER_TAUNT_INTERVAL;
                s.next_scepter_taunt_ms =
                    NEFARIUS_SCEPTER_TAUNT_INTERVAL - (elapsed % NEFARIUS_SCEPTER_TAUNT_INTERVAL);
            }
        }
    }

    /// `boss_victor_nefariusAI::StartScepterRun` (cpp 209-220).
    fn victor_nefarius_start_scepter_run(&mut self, guid: ObjectGuid) {
        self.do_script_text(NEFARIUS_SAY_SCEPTER_RUN_START, guid, None, -1);
        if let Some(s) = self.victor_nefarius_state_mut(guid) {
            s.scepter_taunt_id = 0;
            s.next_scepter_taunt_ms = NEFARIUS_SCEPTER_TAUNT_OFFSET;
            s.scepter_run_time_ms = NEFARIUS_SCEPTER_RUN_TIME;
            s.scepter_run = true;
        }
        self.instance_set_data(BWL_TYPE_SCEPTER_RUN, IN_PROGRESS);
    }

