    /// `boss_victor_nefariusAI::SummonedCreatureJustDied` (cpp 262-289).
    /// NO-DISPATCHER-YET.
    /// (dispatcher wired in step-3 batch)
    fn victor_nefarius_summoned_creature_just_died(
        &mut self,
        guid: ObjectGuid,
        victim: ObjectGuid,
    ) {
        if self.object_entry(victim) == Some(BWL_NPC_NEFARIAN) {
            let run = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::VictorNefarius(s)) => Some(s.scepter_run),
                    _ => None,
                })
                .unwrap_or(false);
            // NEEDS-MAP-HELPER: when `run` and the `DATA_SCEPTER_CHAMPION`
            // player still has `QUEST_NEFARIUS_CORRUPTION` incomplete
            // (cpp 274-279), the result below is `DONE`, not `FAIL`.
            let _ = (run, BWL_DATA_SCEPTER_CHAMPION);
            self.instance_set_data(BWL_TYPE_SCEPTER_RUN, BWL_FAIL);
            // NEEDS-MAP-HELPER: `SetRespawnDelay(7 * DAY)` + `ForcedDespawn()` (cpp 284-285).
        } else if let Some(s) = self.victor_nefarius_state_mut(guid) {
            s.killed_adds += 1;
        }
    }

    /// `boss_victor_nefariusAI::HandleScepterRun` (cpp 515-561).
    fn victor_nefarius_handle_scepter_run(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let due = {
            let Some(s) = self.victor_nefarius_state_mut(guid) else {
                return;
            };
            if s.next_scepter_taunt_ms <= diff_ms {
                true
            } else {
                s.next_scepter_taunt_ms -= diff_ms;
                false
            }
        };
        if due {
            let id = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::VictorNefarius(s)) => Some(s.scepter_taunt_id),
                    _ => None,
                })
                .unwrap_or(99);
            match id {
                0 => {
                    self.do_script_text(NEFARIUS_SAY_SCEPTER_TAUNT_0, guid, None, -1);
                    self.do_script_text(NEFARIUS_SAY_SCEPTER_RUN_LAUGHTER, guid, None, -1);
                }
                1 => {
                    self.do_script_text(NEFARIUS_SAY_SCEPTER_TAUNT_1, guid, None, -1);
                }
                2 => {
                    self.do_script_text(NEFARIUS_SAY_SCEPTER_TAUNT_2, guid, None, -1);
                }
                3 => {
                    self.do_script_text(NEFARIUS_SAY_SCEPTER_TAUNT_3, guid, None, -1);
                }
                4 => {
                    self.do_script_text(NEFARIUS_SAY_SCEPTER_TAUNT_4, guid, None, -1);
                }
                _ => {}
            }
            if let Some(s) = self.victor_nefarius_state_mut(guid) {
                s.scepter_taunt_id += 1;
                s.next_scepter_taunt_ms = NEFARIUS_SCEPTER_TAUNT_INTERVAL;
            }
        }
        // Overall run timer (cpp 553-557, `<=`).
        let expired = {
            let Some(s) = self.victor_nefarius_state_mut(guid) else {
                return;
            };
            if s.scepter_run_time_ms <= diff_ms {
                true
            } else {
                s.scepter_run_time_ms -= diff_ms;
                false
            }
        };
        if expired {
            self.victor_nefarius_fail_scepter_run(guid);
        }
        let remaining = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::VictorNefarius(s)) => Some(s.scepter_run_time_ms),
                _ => None,
            })
            .unwrap_or(0);
        self.instance_set_data(BWL_DATA_SCEPTER_RUN_TIME, remaining);
    }

    /// `boss_victor_nefariusAI::FailScepterRun` (cpp 563-574).
    fn victor_nefarius_fail_scepter_run(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.victor_nefarius_state_mut(guid) {
            s.scepter_run = false;
            s.watch_scepter_run = false;
        }
        self.instance_set_data(BWL_TYPE_SCEPTER_RUN, BWL_FAIL);
        self.do_script_text(NEFARIUS_SAY_SCEPTER_FAIL, guid, None, -1);
        self.do_script_text(NEFARIUS_SAY_SCEPTER_FAIL_LAUGHTER, guid, None, -1);
    }

    /// `boss_victor_nefariusAI::UpdateAI` (cpp 291-513).
    #[allow(clippy::cast_precision_loss)] // `urand(0, 8) as f32` blink offsets
    #[allow(clippy::too_many_lines)]
    fn victor_nefarius_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Gossip-started intro (cpp 293-324, `<`).
        let (started, phase1) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::VictorNefarius(s)) => Some((s.nefa_event_start, s.phase1)),
                _ => None,
            })
            .unwrap_or((false, true));
        if started && !phase1 {
            let due = {
                let Some(s) = self.victor_nefarius_state_mut(guid) else {
                    return;
                };
                if s.event_timer_ms < diff_ms {
                    true
                } else {
                    s.event_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                let count = {
                    let Some(s) = self.victor_nefarius_state_mut(guid) else {
                        return;
                    };
                    s.blabla_count += 1;
                    s.blabla_count
                };
                match count {
                    1 => {
                        self.do_script_text(NEFARIUS_SAY_GAMESBEGIN_1, guid, None, -1);
                        if let Some(s) = self.victor_nefarius_state_mut(guid) {
                            s.event_timer_ms = 7000;
                        }
                    }
                    2 => {
                        self.do_script_text(NEFARIUS_SAY_GAMESBEGIN_2, guid, None, -1);
                        if let Some(s) = self.victor_nefarius_state_mut(guid) {
                            s.event_timer_ms = 4000;
                        }
                    }
                    3 => {
                        self.do_cast_spell_if_can(
                            guid,
                            NEFARIUS_SPELL_BARRIER,
                            CastTarget::SelfCast,
                        );
                        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
                        let _ = self.object_set_field(
                            guid,
                            u32::from(offsets::UNIT_FIELD_FLAGS),
                            flags & !NEFARIUS_UNIT_FLAG_IMMUNE_TO_PLAYER,
                        );
                        let _ = self.object_set_field(
                            guid,
                            u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                            14,
                        );
                        let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
                        for player in players {
                            if self.unit_is_alive(player) {
                                self.add_threat(guid, player, 10_000.0);
                            }
                        }
                        let _ = self.cast_spell(
                            guid,
                            NEFARIUS_SPELL_ROOT,
                            CastTarget::SelfCast,
                            CastOptions {
                                triggered: true,
                                skip_known: true,
                                ..Default::default()
                            },
                        );
                    }
                    _ => {}
                }
            } else {
                // Fork decrements in the else (cpp 322-323); handled above.
            }
        }
        // Scepter-run watch (cpp 326-345).
        let (watch, run) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::VictorNefarius(s)) => {
                    Some((s.watch_scepter_run, s.scepter_run))
                }
                _ => None,
            })
            .unwrap_or((false, false));
        if watch {
            if run {
                self.victor_nefarius_handle_scepter_run(guid, diff_ms);
            } else {
                let status = self.instance_get_data(BWL_TYPE_SCEPTER_RUN).unwrap_or(0);
                if status == BWL_FAIL {
                    if let Some(s) = self.victor_nefarius_state_mut(guid) {
                        s.watch_scepter_run = false;
                    }
                } else if status == BWL_SPECIAL {
                    self.victor_nefarius_start_scepter_run(guid);
                }
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let phase2bis = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::VictorNefarius(s)) => Some(s.phase2bis),
                _ => None,
            })
            .unwrap_or(false);
        if phase2bis {
            return;
        }
        let (killed, phase2) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::VictorNefarius(s)) => Some((s.killed_adds, s.phase2)),
                _ => None,
            })
            .unwrap_or((0, true));
        if killed >= NEFARIUS_MAX_DRAKE_KILLED {
            if let Some(s) = self.victor_nefarius_state_mut(guid) {
                s.phase2bis = true;
            }
            if phase2 {
                return;
            }
        }
        // Add spawns (cpp 361-379, `<`).
        let spawn_due = {
            let Some(s) = self.victor_nefarius_state_mut(guid) else {
                return;
            };
            if s.add_spawn_timer_ms < diff_ms {
                true
            } else {
                s.add_spawn_timer_ms -= diff_ms;
                false
            }
        };
        if spawn_due {
            let (one, two) = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::VictorNefarius(s)) => {
                        Some((s.drake_type_one, s.drake_type_two))
                    }
                    _ => None,
                })
                .unwrap_or((0, 0));
            if one != 0 {
                self.summon_creature(
                    one,
                    Position::new(-7599.32, -1191.72, 475.545, 5.0),
                    guid,
                    NEFARIUS_TEMPSUMMON_TIMED_OOC_DESPAWN,
                    10_000,
                );
            }
            if two != 0 {
                self.summon_creature(
                    two,
                    Position::new(-7526.27, -1135.04, 473.445, 5.0),
                    guid,
                    NEFARIUS_TEMPSUMMON_TIMED_OOC_DESPAWN,
                    10_000,
                );
            }
            let next = self.rng.urand(6000, 7000);
            if let Some(s) = self.victor_nefarius_state_mut(guid) {
                s.add_spawn_timer_ms = next;
            }
        }
        let chroma_due = {
            let Some(s) = self.victor_nefarius_state_mut(guid) else {
                return;
            };
            if s.add_chroma_spawn_timer_ms < diff_ms {
                true
            } else {
                s.add_chroma_spawn_timer_ms -= diff_ms;
                false
            }
        };
        if chroma_due {
            self.summon_creature(
                NEFARIUS_NPC_CHROMATIC_DRAKANOID,
                Position::new(-7599.32, -1191.72, 475.545, 5.0),
                guid,
                NEFARIUS_TEMPSUMMON_TIMED_OOC_DESPAWN,
                10_000,
            );
            self.summon_creature(
                NEFARIUS_NPC_CHROMATIC_DRAKANOID,
                Position::new(-7526.27, -1135.04, 473.445, 5.0),
                guid,
                NEFARIUS_TEMPSUMMON_TIMED_OOC_DESPAWN,
                10_000,
            );
            if let Some(s) = self.victor_nefarius_state_mut(guid) {
                s.add_chroma_spawn_timer_ms = 35_000;
            }
        }
        if phase2 {
            return;
        }
        // Begin phase 2 by spawning Nefarian (cpp 384-411).
        if killed >= NEFARIUS_MAX_DRAKE_KILLED - 2 {
            // NEEDS-MAP-HELPER: `InterruptNonMeleeSpells(false)` (cpp 388).
            let _ = self.cast_spell(
                guid,
                NEFARIUS_SPELL_ROOT,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
            // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_OFF)` (cpp 394-395).
            if let Some(summoned) = self.summon_creature(
                BWL_NPC_NEFARIAN,
                Position::new(-7515.644, -1222.698, 534.716_9, 0.0),
                guid,
                NEFARIUS_TEMPSUMMON_MANUAL_DESPAWN,
                0,
            ) {
                let _ = self.cast_spell(
                    summoned,
                    NEFARIUS_SPELL_HOVER,
                    CastTarget::SelfCast,
                    CastOptions {
                        triggered: true,
                        skip_known: true,
                        ..Default::default()
                    },
                );
                // NEEDS-MAP-HELPER: `SetFly(true)` on the summon (cpp 402).
            }
            if let Some(s) = self.victor_nefarius_state_mut(guid) {
                s.phase2 = true;
            }
            return;
        }
        let bolt_due = {
            let Some(s) = self.victor_nefarius_state_mut(guid) else {
                return;
            };
            if s.shadow_bolt_timer_ms < diff_ms {
                true
            } else {
                s.shadow_bolt_timer_ms -= diff_ms;
                false
            }
        };
        if bolt_due
            && self.do_cast_spell_if_can(guid, NEFARIUS_SPELL_SHADOWBOLT, CastTarget::Unit(victim))
        {
            let next = self.rng.urand(3000, 10_000);
            if let Some(s) = self.victor_nefarius_state_mut(guid) {
                s.shadow_bolt_timer_ms = next;
            }
        }
        let volley_due = {
            let Some(s) = self.victor_nefarius_state_mut(guid) else {
                return;
            };
            if s.shadow_bolt_volley_timer_ms < diff_ms {
                true
            } else {
                s.shadow_bolt_volley_timer_ms -= diff_ms;
                false
            }
        };
        if volley_due
            && self.do_cast_spell_if_can(
                guid,
                NEFARIUS_SPELL_SHADOWBOLT_VOLLEY,
                CastTarget::Unit(victim),
            )
            && let Some(s) = self.victor_nefarius_state_mut(guid)
        {
            s.shadow_bolt_volley_timer_ms = 15_000;
        }
        let fear_due = {
            let Some(s) = self.victor_nefarius_state_mut(guid) else {
                return;
            };
            if s.fear_timer_ms < diff_ms {
                true
            } else {
                s.fear_timer_ms -= diff_ms;
                false
            }
        };
        if fear_due {
            // NEEDS-MAP-HELPER: `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 0)`.
            if let Some(target) = self.select_random_hostile(guid) {
                if self.do_cast_spell_if_can(guid, NEFARIUS_SPELL_FEAR, CastTarget::Unit(target)) {
                    let next = self.rng.urand(15_000, 25_000);
                    if let Some(s) = self.victor_nefarius_state_mut(guid) {
                        s.fear_timer_ms = next;
                    }
                }
            }
        }
        let silence_due = {
            let Some(s) = self.victor_nefarius_state_mut(guid) else {
                return;
            };
            if s.silence_timer_ms < diff_ms {
                true
            } else {
                s.silence_timer_ms -= diff_ms;
                false
            }
        };
        if silence_due {
            // NEEDS-MAP-HELPER: `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 0)`.
            if let Some(target) = self.select_random_hostile(guid) {
                if self.do_cast_spell_if_can(guid, NEFARIUS_SPELL_SILENCE, CastTarget::Unit(target))
                {
                    let next = self.rng.urand(25_000, 40_000);
                    if let Some(s) = self.victor_nefarius_state_mut(guid) {
                        s.silence_timer_ms = next;
                    }
                }
            }
        }
        // Shadow blink (cpp 455-478, `<`).
        let blink_due = {
            let Some(s) = self.victor_nefarius_state_mut(guid) else {
                return;
            };
            if s.shadow_blink_timer_ms < diff_ms {
                true
            } else {
                s.shadow_blink_timer_ms -= diff_ms;
                false
            }
        };
        if blink_due {
            let smoke = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::VictorNefarius(s)) => Some(s.smoke),
                    _ => None,
                })
                .unwrap_or(false);
            if smoke {
                // NEEDS-MAP-HELPER: `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 0)`.
                if let Some(target) = self.select_random_hostile(guid) {
                    if let Some(pos) = self.unit_position(target) {
                        let ox = self.rng.urand(0, 8) as f32;
                        let oy = self.rng.urand(0, 8) as f32;
                        let o = self.unit_position(guid).map_or(0.0, |p| p.o);
                        self.teleport_unit_within_map(
                            guid,
                            Position::new(pos.x + ox, pos.y + oy, pos.z, o),
                        );
                    }
                    // NEEDS-MAP-HELPER: `SendSpellGo(VISUAL_EFFECT)` (cpp 468).
                    self.attack_start(guid, target);
                    self.set_in_combat_with_zone(guid);
                    let _ = self.cast_spell(
                        guid,
                        NEFARIUS_SPELL_ROOT,
                        CastTarget::SelfCast,
                        CastOptions {
                            triggered: true,
                            skip_known: true,
                            ..Default::default()
                        },
                    );
                    let bolt = self.rng.urand(3000, 6000);
                    let blink = self.rng.urand(20_000, 25_000);
                    if let Some(s) = self.victor_nefarius_state_mut(guid) {
                        s.shadow_bolt_timer_ms = bolt;
                        s.shadow_blink_timer_ms = blink;
                        s.smoke = false;
                    }
                }
            } else {
                // NEEDS-MAP-HELPER: `InterruptNonMeleeSpells(false)` +
                // `SendSpellGo(VISUAL_EFFECT)` (cpp 460-461).
                if let Some(s) = self.victor_nefarius_state_mut(guid) {
                    s.shadow_blink_timer_ms = 1000;
                    s.smoke = true;
                }
            }
        }
        // Mind-control aggro restore (cpp 480-498).
        let mind_guid = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::VictorNefarius(s)) => Some(s.mind_controlled_guid),
                _ => None,
            })
            .unwrap_or(ObjectGuid::EMPTY);
        if !mind_guid.is_empty() {
            if self.creatures.contains_key(&mind_guid) || self.players.contains_key(&mind_guid) {
                if !self.bot_has_aura(mind_guid, NEFARIUS_SPELL_SHADOW_COMMAND) {
                    let saved = self
                        .ai
                        .get(&guid)
                        .and_then(|ai| match &ai.script {
                            Some(CreatureScriptAi::VictorNefarius(s)) => {
                                Some(s.mind_controlled_aggro)
                            }
                            _ => None,
                        })
                        .unwrap_or(0.0);
                    self.modify_threat_percent_of(guid, mind_guid, -100);
                    self.add_threat(guid, mind_guid, saved);
                    let _ = self.cast_spell(
                        guid,
                        NEFARIUS_SPELL_ROOT,
                        CastTarget::SelfCast,
                        CastOptions {
                            triggered: true,
                            skip_known: true,
                            ..Default::default()
                        },
                    );
                    if let Some(s) = self.victor_nefarius_state_mut(guid) {
                        s.mind_controlled_guid = ObjectGuid::EMPTY;
                        s.mind_controlled_aggro = 0.0;
                    }
                }
            } else if let Some(s) = self.victor_nefarius_state_mut(guid) {
                s.mind_controlled_guid = ObjectGuid::EMPTY;
                s.mind_controlled_aggro = 0.0;
            }
        }
        // Mind control (cpp 500-512, `<`).
        let mc_due = {
            let Some(s) = self.victor_nefarius_state_mut(guid) else {
                return;
            };
            if s.mind_control_timer_ms < diff_ms {
                true
            } else {
                s.mind_control_timer_ms -= diff_ms;
                false
            }
        };
        if mc_due {
            // NEEDS-MAP-HELPER: `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 1)`.
            if let Some(target) = self.select_random_hostile(guid) {
                let threat = self.threat_on(guid, target);
                if let Some(s) = self.victor_nefarius_state_mut(guid) {
                    s.mind_controlled_guid = target;
                    s.mind_controlled_aggro = threat;
                }
                // `CF_AURA_NOT_PRESENT` (cpp 507).
                if !self.bot_has_aura(target, NEFARIUS_SPELL_SHADOW_COMMAND)
                    && self.do_cast_spell_if_can(
                        guid,
                        NEFARIUS_SPELL_SHADOW_COMMAND,
                        CastTarget::Unit(target),
                    )
                {
                    let next = self.rng.urand(25_000, 40_000);
                    if let Some(s) = self.victor_nefarius_state_mut(guid) {
                        s.mind_control_timer_ms = next;
                    }
                }
            }
        }
    }

