    /// Uniform random pick over the live threat list (interim for every
    /// `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, ...)` in this lane;
    /// see NEEDS-MAP-HELPER notes at the call sites for the exact fork
    /// selector flags).
    #[allow(clippy::cast_possible_wrap)]
    fn mc_random_threat_target(&mut self, guid: ObjectGuid) -> Option<ObjectGuid> {
        let threats = self.threat_targets_sorted(guid);
        if threats.is_empty() {
            return None;
        }
        let idx = self.spell_rng().irand(0, threats.len() as i32 - 1) as usize;
        threats.get(idx).copied()
    }

    /// Uniform random pick over live player threat targets (interim for
    /// `SelectAttackingTarget(..., SELECT_FLAG_PLAYER)`; GM/LOS nuances
    /// unmodeled, see call-site notes).
    #[allow(clippy::cast_possible_wrap)]
    fn mc_random_player_target(&mut self, guid: ObjectGuid) -> Option<ObjectGuid> {
        let threats: Vec<ObjectGuid> = self
            .threat_targets_sorted(guid)
            .into_iter()
            .filter(|t| t.is_player() && self.unit_is_alive(*t))
            .collect();
        if threats.is_empty() {
            return None;
        }
        let idx = self.spell_rng().irand(0, threats.len() as i32 - 1) as usize;
        threats.get(idx).copied()
    }

    /// `boss_baron_geddonAI::Reset` (cpp 54-68).
    fn geddon_reset(&mut self, guid: ObjectGuid) {
        let ignite = self.rng.urand(10_000, 15_000);
        let living_bomb = self.rng.urand(15_000, 20_000);
        let inferno = self.rng.urand(18_000, 24_000);
        if let Some(s) = self.geddon_state_mut(guid) {
            s.ignite_mana_timer_ms = ignite;
            s.living_bomb_timer_ms = living_bomb;
            s.inferno_timer_ms = inferno;
            s.restore_target_timer_ms = 0;
            s.inferno = false;
            s.armageddon = false;
        }
        if self.unit_is_alive(guid) {
            self.instance_set_data(MC_TYPE_GEDDON, MC_NOT_STARTED);
        }
        if let Some(u) = self.unit_base_mut(guid) {
            u.clear_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
        }
        if let Some(ai) = self.ai.get_mut(&guid) {
            ai.combat_movement = true;
        }
    }

    /// `boss_baron_geddonAI::Aggro` (cpp 70-75).
    fn geddon_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        self.instance_set_data(MC_TYPE_GEDDON, IN_PROGRESS);
        self.set_in_combat_with_zone(guid);
    }

    /// `boss_baron_geddonAI::JustDied` (cpp 77-81).
    fn geddon_just_died(&mut self, _guid: ObjectGuid) {
        self.instance_set_data(MC_TYPE_GEDDON, DONE);
    }

    /// `boss_baron_geddonAI::UpdateAI` (cpp 83-199).
    #[allow(clippy::too_many_lines)]
    fn geddon_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        if self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::BaronGeddon(s)) if s.armageddon),
        ) {
            return;
        }
        // Armageddon below 5% (cpp 91-104).
        if !self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::BaronGeddon(s)) if s.armageddon),
        ) && self.creature_health_percent(guid) < 5.0
        {
            self.cancel_cast(guid, true);
            if let Some(ai) = self.ai.get_mut(&guid) {
                ai.combat_movement = false;
            }
            // Fork-commented-out `SetTargetGuid(ObjectGuid())` (cpp 98) is
            // dead code; not transcribed.
            let _ = self.cast_spell(
                guid,
                GEDDON_SPELL_ARMAGEDDOM,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
            self.do_script_text(GEDDON_EMOTE_SERVICE, guid, None, -1);
            if let Some(s) = self.geddon_state_mut(guid) {
                s.armageddon = true;
            }
            return;
        }
        // Living Bomb on a random player (cpp 106-120).
        let living_bomb_due = {
            let Some(s) = self.geddon_state_mut(guid) else {
                return;
            };
            if s.living_bomb_timer_ms < diff_ms {
                true
            } else {
                s.living_bomb_timer_ms -= diff_ms;
                false
            }
        };
        if living_bomb_due {
            // NEEDS-MAP-HELPER: exact fork selector
            // `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 0, nullptr,
            // SELECT_FLAG_PLAYER)`; interim is the threat-list player pick.
            if let Some(target) = self.mc_random_player_target(guid) {
                if self.do_cast_spell_if_can(
                    guid,
                    GEDDON_SPELL_LIVINGBOMB,
                    CastTarget::Unit(target),
                ) {
                    // NEEDS-MAP-HELPER: `SetInFront(pTarget)` /
                    // `SetTargetGuid(pTarget)` facing override (cpp 112-113).
                    let next = self.rng.urand(12_000, 15_000);
                    if let Some(s) = self.geddon_state_mut(guid) {
                        s.living_bomb_timer_ms = next;
                        s.restore_target_timer_ms = 800;
                    }
                }
            }
        }
        // Restore the original facing/target after the bomb (cpp 122-136;
        // fork uses `<=` here, not `<`).
        let restore_due = {
            let Some(s) = self.geddon_state_mut(guid) else {
                return;
            };
            if s.restore_target_timer_ms == 0 {
                false
            } else if s.restore_target_timer_ms <= diff_ms {
                true
            } else {
                s.restore_target_timer_ms -= diff_ms;
                false
            }
        };
        if restore_due {
            if let Some(target) = self.unit_victim(guid) {
                // NEEDS-MAP-HELPER: `SetInFront(pTarget)` /
                // `SetTargetGuid(pTarget)` facing override (cpp 129-130).
                let _ = target;
                if let Some(s) = self.geddon_state_mut(guid) {
                    s.restore_target_timer_ms = 0;
                }
            }
        }
        // Ignite Mana (cpp 138-144).
        let ignite_due = {
            let Some(s) = self.geddon_state_mut(guid) else {
                return;
            };
            if s.ignite_mana_timer_ms < diff_ms {
                true
            } else {
                s.ignite_mana_timer_ms -= diff_ms;
                false
            }
        };
        if ignite_due
            && self.do_cast_spell_if_can(guid, GEDDON_SPELL_IGNITEMANA, CastTarget::SelfCast)
        {
            let next = self.rng.urand(20_000, 30_000);
            if let Some(s) = self.geddon_state_mut(guid) {
                s.ignite_mana_timer_ms = next;
            }
        }
        // Inferno (cpp 146-158).
        let inferno_due = {
            let Some(s) = self.geddon_state_mut(guid) else {
                return;
            };
            if s.inferno_timer_ms < diff_ms {
                true
            } else {
                s.inferno_timer_ms -= diff_ms;
                false
            }
        };
        if inferno_due
            && self.do_cast_spell_if_can(guid, GEDDON_SPELL_INFERNO, CastTarget::SelfCast)
        {
            let next = self.rng.urand(18_000, 24_000);
            if let Some(s) = self.geddon_state_mut(guid) {
                s.inferno_timer_ms = next;
                s.inf_count = 0;
                s.tick_ms = 1000;
                s.inferno = true;
            }
            // Fork relies on root to stop movement; the Rust root flag does
            // not gate motion yet (herod pattern), so also stop moving.
            if let Some(u) = self.unit_base_mut(guid) {
                u.add_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
            }
            self.stop_moving(guid);
        }
        // Escalating inferno ticks (cpp 160-195).
        let in_inferno = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::BaronGeddon(s)) if s.inferno),
        );
        if in_inferno {
            let tick = {
                let Some(s) = self.geddon_state_mut(guid) else {
                    return;
                };
                if s.tick_ms >= 1000 {
                    let damage: i32 = match s.inf_count {
                        0 | 1 => 500,
                        2 | 3 => 1000,
                        4 | 5 => 2000,
                        6 => 3000,
                        _ => 5000,
                    };
                    if s.inf_count >= 7 {
                        s.inferno = false;
                    }
                    s.inf_count = s.inf_count.saturating_add(1);
                    s.tick_ms = 0;
                    Some(damage)
                } else {
                    None
                }
            };
            if let Some(damage) = tick {
                if !self.ai.get(&guid).is_some_and(
                    |ai| matches!(&ai.script, Some(CreatureScriptAi::BaronGeddon(s)) if s.inferno),
                ) && let Some(u) = self.unit_base_mut(guid)
                {
                    u.clear_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
                }
                // `CastCustomSpell(19698, Damage)` (cpp 189): custom base
                // points through `CastOptions`.
                let _ = self.cast_spell(
                    guid,
                    GEDDON_SPELL_INFERNO_DAMAGE,
                    CastTarget::SelfCast,
                    CastOptions {
                        triggered: true,
                        skip_known: true,
                        custom_base_points: [Some(damage), None, None],
                        ..Default::default()
                    },
                );
            }
            if let Some(s) = self.geddon_state_mut(guid) {
                s.tick_ms = s.tick_ms.saturating_add(diff_ms);
            }
        }
    }

    /// `boss_garrAI::Reset` (cpp 36-45).
    fn garr_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.garr_state_mut(guid) {
            s.anti_magic_timer_ms = 0;
            s.magma_shackles_timer_ms = 0;
            s.massive_eruption_timer_ms = 0;
            s.firesworn.clear();
        }
        if self.unit_is_alive(guid) && self.instance_get_data(MC_TYPE_GARR) != Some(DONE) {
            self.instance_set_data(MC_TYPE_GARR, MC_NOT_STARTED);
        }
    }

    /// `boss_garrAI::Aggro` (cpp 47-78).
    fn garr_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        if self.instance_get_data(MC_TYPE_GARR) == Some(DONE) {
            // NEEDS-MAP-HELPER: `DeleteLater()` (cpp 56); no
            // delayed-delete helper on `Map`.
            self.despawn_creature_now(guid, 0);
            return;
        }
        self.instance_set_data(MC_TYPE_GARR, IN_PROGRESS);
        self.set_in_combat_with_zone(guid);
        // Gather Firesworn within 150 yds (cpp 63-75).
        let me = self.unit_position(guid).unwrap_or_default();
        let mut adds: Vec<ObjectGuid> = Vec::new();
        for (g, c) in &self.creatures {
            if c.info.entry != MC_NPC_FIRESWORN {
                continue;
            }
            let p = self.unit_position(*g).unwrap_or_default();
            let dx = p.x - me.x;
            let dy = p.y - me.y;
            if dx * dx + dy * dy <= 150.0 * 150.0 {
                adds.push(*g);
            }
        }
        if let Some(s) = self.garr_state_mut(guid) {
            s.firesworn.clone_from(&adds);
        }
        for add in adds {
            // `CF_TRIGGERED | CF_AURA_NOT_PRESENT` (cpp 74).
            if !self
                .aura_holders(add)
                .iter()
                .any(|h| h.spell_id == GARR_SPELL_SEPARATION_ANXIETY)
            {
                let _ = self.cast_spell(
                    guid,
                    GARR_SPELL_SEPARATION_ANXIETY,
                    CastTarget::Unit(add),
                    CastOptions {
                        triggered: true,
                        skip_known: true,
                        ..Default::default()
                    },
                );
            }
        }
        if let Some(s) = self.garr_state_mut(guid) {
            s.anti_magic_timer_ms = 15_000;
            s.magma_shackles_timer_ms = 10_000;
            s.massive_eruption_timer_ms = 360_000;
        }
    }

    /// `boss_garrAI::JustDied` (cpp 80-86).
    fn garr_just_died(&mut self, guid: ObjectGuid) {
        let _ = guid;
        self.instance_set_data(MC_TYPE_GARR, DONE);
    }

    /// `boss_garrAI::SpellHit` (cpp 88-94). No dispatcher yet.
    fn garr_spell_hit(&mut self, guid: ObjectGuid, _caster: ObjectGuid, spell_id: u32) {
        if spell_id == GARR_SPELL_ENRAGE_TRIGGER {
            let _ = self.cast_spell(
                guid,
                GARR_SPELL_ENRAGE,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
    }

    /// `boss_garrAI::FireswornJustDied` (cpp 96-104): cross-AI call from
    /// `mob_fireswornAI::JustDied` via `dynamic_cast`.
    fn garr_firesworn_just_died(&mut self, guid: ObjectGuid, add: ObjectGuid) {
        if let Some(s) = self.garr_state_mut(guid) {
            s.firesworn.retain(|g| *g != add);
        }
    }

    /// `boss_garrAI::UpdateAI` + `UpdateEvents` (cpp 106-179).
    #[allow(clippy::cast_possible_wrap)]
    fn garr_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Anti-magic pulse (cpp 132-144; fork handles one event per tick
        // and retries failed casts in 1s — transcribed per-timer here).
        let anti_magic_due = {
            let Some(s) = self.garr_state_mut(guid) else {
                return;
            };
            if s.anti_magic_timer_ms < diff_ms {
                true
            } else {
                s.anti_magic_timer_ms -= diff_ms;
                false
            }
        };
        if anti_magic_due {
            if self.do_cast_spell_if_can(guid, GARR_SPELL_ANTIMAGICPULSE, CastTarget::SelfCast) {
                let next = self.rng.urand(15_000, 20_000);
                if let Some(s) = self.garr_state_mut(guid) {
                    s.anti_magic_timer_ms = next;
                }
            } else if let Some(s) = self.garr_state_mut(guid) {
                s.anti_magic_timer_ms = 1000;
            }
        }
        // Magma shackles (cpp 145-157).
        let shackles_due = {
            let Some(s) = self.garr_state_mut(guid) else {
                return;
            };
            if s.magma_shackles_timer_ms < diff_ms {
                true
            } else {
                s.magma_shackles_timer_ms -= diff_ms;
                false
            }
        };
        if shackles_due {
            if self.do_cast_spell_if_can(guid, GARR_SPELL_MAGMASHACKLES, CastTarget::SelfCast) {
                let next = self.rng.urand(10_000, 15_000);
                if let Some(s) = self.garr_state_mut(guid) {
                    s.magma_shackles_timer_ms = next;
                }
            } else if let Some(s) = self.garr_state_mut(guid) {
                s.magma_shackles_timer_ms = 1000;
            }
        }
        // Massive eruption (cpp 158-176): every 6 min, then every 20s a
        // random live Firesworn explodes.
        let eruption_due = {
            let Some(s) = self.garr_state_mut(guid) else {
                return;
            };
            if s.massive_eruption_timer_ms < diff_ms {
                true
            } else {
                s.massive_eruption_timer_ms -= diff_ms;
                false
            }
        };
        if eruption_due {
            let guids = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::Garr(s)) => Some(s.firesworn.clone()),
                    _ => None,
                })
                .unwrap_or_default();
            if !guids.is_empty() {
                let idx = self.spell_rng().irand(0, guids.len() as i32 - 1) as usize;
                if let Some(add) = guids.get(idx).copied()
                    && self.unit_is_alive(add)
                {
                    // `!HasAuraType(SPELL_AURA_MOD_STUN)` (cpp 167):
                    // interim is the stunned unit state (aura-type query
                    // unmodeled), see unresolved.
                    let stunned = self.unit_base_mut(add).is_some_and(|u| {
                        u.has_unit_state(mangos_entities::unit::UNIT_STATE_STUNNED)
                    });
                    if !stunned {
                        self.do_script_text(GARR_EMOTE_MASSIVE_ERUPTION, guid, None, -1);
                        let _ = self.cast_spell(
                            guid,
                            GARR_SPELL_ERUPTION_TRIGGER,
                            CastTarget::Unit(add),
                            CastOptions {
                                triggered: true,
                                skip_known: true,
                                ..Default::default()
                            },
                        );
                    }
                }
            }
            if let Some(s) = self.garr_state_mut(guid) {
                s.massive_eruption_timer_ms = 20_000;
            }
        }
    }

    /// `mob_fireswornAI::Reset` (cpp 209-213).
    fn firesworn_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.firesworn_state_mut(guid) {
            s.force_explosion = false;
            s.immolate_timer_ms = 0;
        }
    }

    /// `mob_fireswornAI::Aggro` (cpp 215-220).
    fn firesworn_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        // `CF_TRIGGERED | CF_AURA_NOT_PRESENT` (cpp 217).
        if !self
            .aura_holders(guid)
            .iter()
            .any(|h| h.spell_id == FIRESWORN_SPELL_THRASH)
        {
            let _ = self.cast_spell(
                guid,
                FIRESWORN_SPELL_THRASH,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
        self.set_in_combat_with_zone(guid);
        if let Some(s) = self.firesworn_state_mut(guid) {
            s.immolate_timer_ms = 10_000;
        }
    }

    /// `mob_fireswornAI::JustDied` (cpp 222-247).
    fn firesworn_just_died(&mut self, guid: ObjectGuid) {
        if let Some(garr) = self.instance_get_data64(MC_DATA_GARR) {
            if self.unit_is_alive(garr) {
                let _ = self.cast_spell(
                    guid,
                    GARR_SPELL_ENRAGE_TRIGGER,
                    CastTarget::Unit(garr),
                    CastOptions {
                        triggered: true,
                        skip_known: true,
                        ..Default::default()
                    },
                );
                self.garr_firesworn_just_died(garr, guid);
            }
        }
        let force = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Firesworn(s)) => Some(s.force_explosion),
                _ => None,
            })
            .unwrap_or(false);
        if !force {
            // `CastSpell(self, ADD_ERUPTION, true)` (cpp 245): direct,
            // unchecked.
            let _ = self.cast_spell(
                guid,
                FIRESWORN_SPELL_ADD_ERUPTION,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
    }

    /// `mob_fireswornAI::SpellHit` (cpp 249-256). No dispatcher yet.
    fn firesworn_spell_hit(&mut self, guid: ObjectGuid, _caster: ObjectGuid, spell_id: u32) {
        if spell_id == GARR_SPELL_ERUPTION_TRIGGER {
            if let Some(s) = self.firesworn_state_mut(guid) {
                s.force_explosion = true;
            }
            // `CastSpell(self, MASSIVE_ERUPTION, true)` (cpp 254): direct,
            // unchecked.
            let _ = self.cast_spell(
                guid,
                FIRESWORN_SPELL_MASSIVE_ERUPTION,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
    }

    /// `mob_fireswornAI::UpdateAI` (cpp 258-269).
    fn firesworn_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let immolate_due = {
            let Some(s) = self.firesworn_state_mut(guid) else {
                return;
            };
            if s.immolate_timer_ms < diff_ms {
                true
            } else {
                s.immolate_timer_ms -= diff_ms;
                false
            }
        };
        if immolate_due {
            if self.do_cast_spell_if_can(guid, FIRESWORN_SPELL_IMMOLATE, CastTarget::Unit(victim)) {
                if let Some(s) = self.firesworn_state_mut(guid) {
                    s.immolate_timer_ms = 20_000;
                }
            } else if let Some(s) = self.firesworn_state_mut(guid) {
                s.immolate_timer_ms = 1000;
            }
        }
    }

    /// `boss_gehennasAI::Reset` (cpp 50-59).
    fn gehennas_reset(&mut self, guid: ObjectGuid) {
        let curse = self.rng.urand(5_000, 10_000);
        let rain = self.rng.urand(6_000, 12_000);
        let bolt_random = self.rng.urand(3_000, 6_000);
        let bolt_target = self.rng.urand(3_000, 6_000);
        if let Some(s) = self.gehennas_state_mut(guid) {
            s.gehennas_curse_timer_ms = curse;
            s.rain_of_fire_timer_ms = rain;
            s.shadow_bolt_random_timer_ms = bolt_random;
            s.shadow_bolt_target_timer_ms = bolt_target;
        }
        if self.unit_is_alive(guid) {
            self.instance_set_data(MC_TYPE_GEHENNAS, MC_NOT_STARTED);
        }
    }

