    fn gehennas_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        self.instance_set_data(MC_TYPE_GEHENNAS, IN_PROGRESS);
        self.set_in_combat_with_zone(guid);
    }

