    /// `mob_core_ragerAI::DamageTaken` (cpp 254-276). No dispatcher yet.
    fn core_rager_damage_taken(
        &mut self,
        guid: ObjectGuid,
        _attacker: ObjectGuid,
        damage: &mut u32,
    ) {
        if self.instance_get_data(MC_TYPE_GOLEMAGG) == Some(DONE) {
            return;
        }
        // `HealthBelowPctDamaged(50, uiDamage)` (cpp 266).
        let hp = u64::from(self.unit_value_u32(guid, offsets::UNIT_FIELD_HEALTH));
        let max = u64::from(self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXHEALTH));
        if max != 0 && hp.saturating_sub(u64::from(*damage)) * 100 < 50 * max {
            *damage = 0;
            self.do_script_text(CORERAGER_EMOTE_LOWHP, guid, None, -1);
            let victim = self.unit_victim(guid);
            let healed = victim.is_some_and(|v| {
                self.do_cast_spell_if_can(guid, CORERAGER_SPELL_FULL_HEAL, CastTarget::Unit(v))
            });
            if !healed {
                // `SetHealth(GetMaxHealth())` (cpp 272).
                let max32 = self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXHEALTH);
                let _ = self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_HEALTH), max32);
            }
        }
    }

    /// `mob_core_ragerAI::UpdateAI` + `UpdateEvents` (cpp 278-346).
    fn core_rager_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Mangle (cpp 316-327).
        let mangle_due = {
            let Some(s) = self.core_rager_state_mut(guid) else {
                return;
            };
            if s.mangle_timer_ms < diff_ms {
                true
            } else {
                s.mangle_timer_ms -= diff_ms;
                false
            }
        };
        if mangle_due {
            if self.do_cast_spell_if_can(guid, CORERAGER_SPELL_MANGLE, CastTarget::Unit(victim)) {
                if let Some(s) = self.core_rager_state_mut(guid) {
                    s.mangle_timer_ms = 10_000;
                }
            } else if let Some(s) = self.core_rager_state_mut(guid) {
                s.mangle_timer_ms = 1000;
            }
        }
        // Leash check: evade Golemagg past 100 yds (cpp 328-343).
        let leash_due = {
            let Some(s) = self.core_rager_state_mut(guid) else {
                return;
            };
            if s.leash_check_timer_ms < diff_ms {
                true
            } else {
                s.leash_check_timer_ms -= diff_ms;
                false
            }
        };
        if leash_due {
            if let Some(golemagg) = self.instance_get_data64(MC_DATA_GOLEMAGG) {
                let far = match (self.unit_position(guid), self.unit_position(golemagg)) {
                    (Some(a), Some(b)) => {
                        let dx = a.x - b.x;
                        let dy = a.y - b.y;
                        dx * dx + dy * dy > 100.0 * 100.0
                    }
                    _ => false,
                };
                if far {
                    self.enter_evade_mode(golemagg);
                }
            }
            if let Some(s) = self.core_rager_state_mut(guid) {
                s.leash_check_timer_ms = 3_000;
            }
        }
    }

