    /// `FirewalkerAI::UpdateAI` (cpp 68-107).
    fn firewalker_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Fire Blossom channel start (cpp 73-82; count/prepare latch even
        // when the cast fails).
        let casting_due = {
            let Some(s) = self.firewalker_state_mut(guid) else {
                return;
            };
            if s.fire_blossom_casting_timer_ms < diff_ms {
                true
            } else {
                s.fire_blossom_casting_timer_ms -= diff_ms;
                false
            }
        };
        if casting_due {
            if self.do_cast_spell_if_can(
                guid,
                FIREWALKER_SPELL_FIREBLOSSOM_CASTING,
                CastTarget::SelfCast,
            ) {
                if let Some(s) = self.firewalker_state_mut(guid) {
                    s.fire_blossom_casting_timer_ms = 12_000;
                }
            }
            if let Some(s) = self.firewalker_state_mut(guid) {
                s.nb_blossom = 6;
                s.fire_blossom_preparing_timer_ms = 1000;
            }
        }
        // Incite Flames (cpp 84-90).
        let incite_due = {
            let Some(s) = self.firewalker_state_mut(guid) else {
                return;
            };
            if s.incite_flames_timer_ms < diff_ms {
                true
            } else {
                s.incite_flames_timer_ms -= diff_ms;
                false
            }
        };
        if incite_due
            && self.do_cast_spell_if_can(
                guid,
                FIREWALKER_SPELL_INCITE_FLAMES,
                CastTarget::Unit(victim),
            )
            && let Some(s) = self.firewalker_state_mut(guid)
        {
            s.incite_flames_timer_ms = 20_000;
        }
        // Fire Blossom ticks (cpp 92-104): the fork's `0 < diff` gate fires
        // immediately and `0 - 1` wraps the u32 counter; transcribed with
        // `wrapping_sub` (fork underflow preserved, see unresolved).
        let preparing_due = {
            let Some(s) = self.firewalker_state_mut(guid) else {
                return;
            };
            if s.fire_blossom_preparing_timer_ms < diff_ms {
                true
            } else {
                s.fire_blossom_preparing_timer_ms -= diff_ms;
                false
            }
        };
        if preparing_due {
            let blossoms = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::Firewalker(s)) => Some(s.nb_blossom),
                    _ => None,
                })
                .unwrap_or(0);
            if blossoms > 0 {
                // NEEDS-MAP-HELPER: exact fork selector
                // `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 0)` (cpp 96).
                if let Some(target) = self.mc_random_threat_target(guid) {
                    self.do_cast_spell_if_can(
                        guid,
                        FIREWALKER_SPELL_FIREBLOSSOM,
                        CastTarget::Unit(target),
                    );
                }
            }
            if let Some(s) = self.firewalker_state_mut(guid) {
                s.fire_blossom_preparing_timer_ms = 1000;
                s.nb_blossom = s.nb_blossom.wrapping_sub(1);
            }
        }
    }

    /// `mob_ancient_core_houndAI::Reset` (cpp 147-175).
    fn ancient_hound_reset(&mut self, guid: ObjectGuid) {
        let roll = self.rng.urand(0, 5);
        let debuff = match roll {
            0 => ANCIENTHOUND_SPELL_GROUND_STOMP,
            1 => ANCIENTHOUND_SPELL_ANCIENT_DREAD,
            2 => ANCIENTHOUND_SPELL_CAUTERIZING_FLAMES,
            3 => ANCIENTHOUND_SPELL_WITHERING_HEAT,
            4 => ANCIENTHOUND_SPELL_ANCIENT_DESPAIR,
            _ => ANCIENTHOUND_SPELL_ANCIENT_HYSTERIA,
        };
        let cone = self.rng.urand(4000, 7000);
        let random_debuff = self.rng.urand(12_000, 15_000);
        if let Some(s) = self.ancient_hound_state_mut(guid) {
            s.rand_debuff = debuff;
            s.cone_of_fire_timer_ms = cone;
            s.random_debuff_timer_ms = random_debuff;
            s.bite_timer_ms = 4000;
        }
        // NEEDS-MAP-HELPER: `SetNoCallAssistance(true)` (cpp 174);
        // no assistance-opt-out setter on `Map`.
    }

