    /// `mob_ancient_core_houndAI::UpdateAI` (cpp 204-245). The
    /// fork-commented-out `MoveInLineOfSight` override (cpp 187-202) is
    /// dead code; not transcribed.
    fn ancient_hound_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Cone of Fire: direct cast (cpp 211).
        let cone_due = {
            let Some(s) = self.ancient_hound_state_mut(guid) else {
                return;
            };
            if s.cone_of_fire_timer_ms < diff_ms {
                true
            } else {
                s.cone_of_fire_timer_ms -= diff_ms;
                false
            }
        };
        if cone_due {
            let _ = self.cast_spell(
                guid,
                ANCIENTHOUND_SPELL_CONE_OF_FIRE,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: false,
                    skip_known: true,
                    ..Default::default()
                },
            );
            let next = self.rng.urand(6000, 8000);
            if let Some(s) = self.ancient_hound_state_mut(guid) {
                s.cone_of_fire_timer_ms = next;
            }
        }
        // Random debuff (cpp 217-223).
        let debuff_due = {
            let Some(s) = self.ancient_hound_state_mut(guid) else {
                return;
            };
            if s.random_debuff_timer_ms < diff_ms {
                true
            } else {
                s.random_debuff_timer_ms -= diff_ms;
                false
            }
        };
        if debuff_due {
            let debuff = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::AncientCoreHound(s)) => Some(s.rand_debuff),
                    _ => None,
                })
                .unwrap_or(ANCIENTHOUND_SPELL_GROUND_STOMP);
            if self.do_cast_spell_if_can(guid, debuff, CastTarget::SelfCast) {
                let next = self.rng.urand(14_000, 24_000);
                if let Some(s) = self.ancient_hound_state_mut(guid) {
                    s.random_debuff_timer_ms = next;
                }
            }
        }
        // Bite when in reach (cpp 225-234; timer only resets in reach).
        let bite_due = {
            let Some(s) = self.ancient_hound_state_mut(guid) else {
                return;
            };
            if s.bite_timer_ms < diff_ms {
                true
            } else {
                s.bite_timer_ms -= diff_ms;
                false
            }
        };
        if bite_due && self.can_reach_melee(guid, victim) {
            let _ = self.cast_spell(
                guid,
                ANCIENTHOUND_SPELL_BITE,
                CastTarget::Unit(victim),
                CastOptions {
                    triggered: false,
                    skip_known: true,
                    ..Default::default()
                },
            );
            if let Some(s) = self.ancient_hound_state_mut(guid) {
                s.bite_timer_ms = 6000;
            }
        }
        // Vicious Bite on attack-ready in reach (cpp 236-244; attack-timer
        // internals tick globally, reach gate transcribed).
        if self.can_reach_melee(guid, victim) {
            let _ = self.cast_spell(
                guid,
                ANCIENTHOUND_SPELL_VICIOUS_BITE,
                CastTarget::Unit(victim),
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
    }

