    fn lava_surger_just_died(&mut self, guid: ObjectGuid) {
        let _ = guid;
        if self.instance_get_data(MC_TYPE_GARR) == Some(DONE) {
            // NEEDS-MAP-HELPER: `SetRespawnTime(7 * DAY)` +
            // `SaveRespawnTime()` (cpp 493-494); no respawn-time helpers.
        }
    }

    /// `mob_lava_surgerAI::UpdateAI` (cpp 497-521).
    fn lava_surger_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Banished (stun-aura) surgers skip their cooldowns (cpp 502-503):
        // interim is the stunned unit state, see unresolved.
        if self
            .unit_base_mut(guid)
            .is_some_and(|u| u.has_unit_state(mangos_entities::unit::UNIT_STATE_STUNNED))
        {
            return;
        }
        // Surge the farthest player in range (cpp 505-518).
        let surge_due = {
            let Some(s) = self.lava_surger_state_mut(guid) else {
                return;
            };
            if s.surge_timer_ms < diff_ms {
                true
            } else {
                s.surge_timer_ms -= diff_ms;
                false
            }
        };
        if surge_due {
            // NEEDS-MAP-HELPER: exact fork selector
            // `SelectAttackingTarget(ATTACKING_TARGET_FARTHEST, 0,
            // SPELL_SURGE, SELECT_FLAG_PLAYER | SELECT_FLAG_IN_LOS)`
            // (cpp 508); LOS unmodeled. Interim is the farthest live
            // player on the threat list.
            let me = self.unit_position(guid).unwrap_or_default();
            let mut farthest: Option<ObjectGuid> = None;
            let mut farthest_d2 = 0.0;
            for t in self.threat_targets_sorted(guid) {
                if !t.is_player() || !self.unit_is_alive(t) {
                    continue;
                }
                let p = self.unit_position(t).unwrap_or_default();
                let dx = p.x - me.x;
                let dy = p.y - me.y;
                let d2 = dx * dx + dy * dy;
                if farthest.is_none() || d2 > farthest_d2 {
                    farthest = Some(t);
                    farthest_d2 = d2;
                }
            }
            if let Some(target) = farthest {
                let tp = self.unit_position(target).unwrap_or_default();
                let dx = tp.x - me.x;
                let dy = tp.y - me.y;
                if dx * dx + dy * dy > 7.0 * 7.0
                    && self.do_cast_spell_if_can(
                        guid,
                        LAVASURGER_SPELL_SURGE,
                        CastTarget::Unit(target),
                    )
                {
                    let next = self.rng.urand(5000, 6000);
                    if let Some(s) = self.lava_surger_state_mut(guid) {
                        s.surge_timer_ms = next;
                    }
                }
            }
        }
    }

