    /// `boss_halyconAI::JustDied`.
    fn halycon_just_died(&mut self, guid: ObjectGuid) {
        let summon = self.halycon_state_mut(guid).is_some_and(|s| !s.summoned);
        if !summon {
            return;
        }
        // NEEDS-MAP-HELPER: `MonsterTextEmote` literal (cpp 78)
        // "Halycon lets loose a gutteral growl ..." (no text id,
        // so `do_script_text` does not apply).
        let gizrul = self.summon_creature(
            HALYCON_NPC_GIZRUL,
            Position::new(-167.58, -382.41, 64.401, 1.563),
            guid,
            BRS_TEMPSUMMON_DEAD_DESPAWN,
            0,
        );
        if let Some(gizrul) = gizrul {
            // `SetHomePosition` (cpp 81): direct field write
            // (home_position precedent in content.rs).
            if let Some(c) = self.creatures.get_mut(&gizrul) {
                c.home_position = Position::new(-172.633, -324.253, 64.401, 4.74);
            }
            self.set_in_combat_with_zone(gizrul);
        }
        if let Some(s) = self.halycon_state_mut(guid) {
            s.summoned = true;
        }
    }

