    /// `boss_overlordwyrmthalakAI::JustSummoned`.
    fn overlord_wyrmthalak_just_summoned(&mut self, guid: ObjectGuid, created: ObjectGuid) {
        let entry = self.creatures.get(&created).map(|c| c.info.entry);
        if entry != Some(WYRM_NPC_SPIRESTONE_WARLORD)
            && entry != Some(WYRM_NPC_SMOLDERTHORN_BERSERKER)
        {
            return;
        }
        if let Some(victim) = self.unit_victim(guid) {
            // NEEDS-MAP-HELPER: fork `SelectAttackingTarget(RANDOM, 0)`
            // with victim fallback (cpp 69-73).
            let target = self.select_random_hostile(created).or(Some(victim));
            if let Some(target) = target {
                self.attack_start(created, target);
            }
        }
    }

    /// `boss_overlordwyrmthalakAI::LeashIfOutOfCombatArea`.
    fn wyrmthalak_leash(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let tick = {
            let Some(s) = self.overlord_wyrmthalak_state_mut(guid) else {
                return;
            };
            if s.leash_check_ms < diff_ms {
                s.leash_check_ms = 3500;
                true
            } else {
                s.leash_check_ms -= diff_ms;
                false
            }
        };
        if !tick {
            return;
        }
        let high = self.unit_position(guid).is_some_and(|p| p.z > 100.0);
        let pulled = self
            .overlord_wyrmthalak_state_mut(guid)
            .is_some_and(|s| s.pulled_by_pet);
        if pulled || high {
            self.enter_evade_mode(guid);
        }
    }

