    fn overlord_wyrmthalak_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Fork order: leash check runs before the spell timers.
        self.wyrmthalak_leash(guid, diff_ms);
        let due = {
            let Some(s) = self.overlord_wyrmthalak_state_mut(guid) else {
                return;
            };
            if s.blast_wave_timer_ms < diff_ms {
                true
            } else {
                s.blast_wave_timer_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, WYRM_SPELL_BLAST_WAVE, CastTarget::SelfCast) {
            if let Some(s) = self.overlord_wyrmthalak_state_mut(guid) {
                s.blast_wave_timer_ms = 20_000;
            }
        }
        let due = {
            let Some(s) = self.overlord_wyrmthalak_state_mut(guid) else {
                return;
            };
            if s.shout_timer_ms < diff_ms {
                true
            } else {
                s.shout_timer_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, WYRM_SPELL_SHOUT, CastTarget::SelfCast) {
            if let Some(s) = self.overlord_wyrmthalak_state_mut(guid) {
                s.shout_timer_ms = 10_000;
            }
        }
        let due = {
            let Some(s) = self.overlord_wyrmthalak_state_mut(guid) else {
                return;
            };
            if s.cleave_timer_ms < diff_ms {
                true
            } else {
                s.cleave_timer_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, WYRM_SPELL_CLEAVE, CastTarget::Unit(victim)) {
            if let Some(s) = self.overlord_wyrmthalak_state_mut(guid) {
                s.cleave_timer_ms = 7000;
            }
        }
        let due = {
            let Some(s) = self.overlord_wyrmthalak_state_mut(guid) else {
                return;
            };
            if s.knockaway_timer_ms < diff_ms {
                true
            } else {
                s.knockaway_timer_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, WYRM_SPELL_KNOCKAWAY, CastTarget::SelfCast) {
            if let Some(s) = self.overlord_wyrmthalak_state_mut(guid) {
                s.knockaway_timer_ms = 14_000;
            }
        }
        let summon = !self
            .overlord_wyrmthalak_state_mut(guid)
            .is_some_and(|s| s.summoned)
            && self.creature_health_percent(guid) < 51.0;
        if summon {
            // Entry alternates warlord / berserker by slot.
            let spots = [
                (WYRM_NPC_SPIRESTONE_WARLORD, WYRM_SUMMON_SPOTS[0]),
                (WYRM_NPC_SMOLDERTHORN_BERSERKER, WYRM_SUMMON_SPOTS[1]),
            ];
            for (entry, spot) in spots {
                self.summon_creature(
                    entry,
                    Position::new(spot[0], spot[1], spot[2], spot[3]),
                    guid,
                    WYRM_TEMPSUMMON_TIMED_OOC,
                    10_000,
                );
            }
            if let Some(s) = self.overlord_wyrmthalak_state_mut(guid) {
                s.summoned = true;
            }
        }
    }

