    /// `boss_thebeastAI::SpellHit` (no dispatcher yet; the
    /// integrator adds dispatch).
    fn the_beast_spell_hit(&mut self, _guid: ObjectGuid, caster: ObjectGuid, spell_id: u32) {
        let skinned = self
            .stores
            .spells
            .get(spell_id)
            .is_some_and(|s| s.effects[0].effect == BEAST_SPELL_EFFECT_SKINNING);
        if skinned {
            // `pCaster->CastSpell(pCaster, SPELL_SUMMON_FINKLE, true)` (cpp 62).
            let _ = self.cast_spell(
                caster,
                BEAST_SPELL_SUMMON_FINKLE,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
    }

