    #[allow(clippy::too_many_lines)]
    fn the_beast_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Fork order: the immolate-aura upkeep runs before the
        // hostile-target check (cpp 67-68).
        if !self.bot_has_aura(guid, BEAST_AURA_IMMOLATE) {
            // `CastSpell(me, AURA_IMMOLATE, true)` (cpp 68).
            let _ = self.cast_spell(
                guid,
                BEAST_AURA_IMMOLATE,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let due = {
            let Some(s) = self.the_beast_state_mut(guid) else {
                return;
            };
            if s.flamebreak_timer_ms < diff_ms {
                true
            } else {
                s.flamebreak_timer_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, BEAST_SPELL_FLAMEBREAK, CastTarget::SelfCast) {
            let next = self.rng.urand(14_000, 20_000);
            if let Some(s) = self.the_beast_state_mut(guid) {
                s.flamebreak_timer_ms = next;
            }
        }
        let due = {
            let Some(s) = self.the_beast_state_mut(guid) else {
                return;
            };
            if s.terrifying_roar_timer_ms < diff_ms {
                true
            } else {
                s.terrifying_roar_timer_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, BEAST_SPELL_TERRIFYING_ROAR, CastTarget::SelfCast)
        {
            let next = self.rng.urand(16_000, 18_000);
            if let Some(s) = self.the_beast_state_mut(guid) {
                s.terrifying_roar_timer_ms = next;
            }
        }
        // Fork `Berserker Charge` uses `<= diff` (cpp 104); the
        // zeroed timer fires on the first tick against the victim
        // (cpp 107-108), then against a random target at index 1.
        let charge_due = {
            let Some(s) = self.the_beast_state_mut(guid) else {
                return;
            };
            if s.berserker_charge_timer_ms <= diff_ms {
                true
            } else {
                s.berserker_charge_timer_ms -= diff_ms;
                false
            }
        };
        if charge_due {
            let first = self
                .the_beast_state_mut(guid)
                .is_some_and(|s| s.berserker_charge_timer_ms == 0);
            // NEEDS-MAP-HELPER: fork `SelectAttackingTarget(RANDOM, 1)`
            // (cpp 106); falls back to `None` here when the helper
            // cannot supply a target.
            let target = if first {
                Some(victim)
            } else {
                self.select_random_hostile(guid)
            };
            if let Some(target) = target
                && self.do_cast_spell_if_can(
                    guid,
                    BEAST_SPELL_BERSERKER_CHARGE,
                    CastTarget::Unit(target),
                )
            {
                let next = self.rng.urand(15_000, 20_000);
                if let Some(s) = self.the_beast_state_mut(guid) {
                    s.berserker_charge_timer_ms = next;
                }
            }
        }
        // Fork `Fireball`: on due with a random target at index 1
        // the cast fires and re-arms `urand(10000, 12000)` (cpp 116-127).
        let fireball_due = {
            let Some(s) = self.the_beast_state_mut(guid) else {
                return;
            };
            if s.fireball_timer_ms < diff_ms {
                true
            } else {
                s.fireball_timer_ms -= diff_ms;
                false
            }
        };
        if fireball_due {
            // NEEDS-MAP-HELPER: fork `SelectAttackingTarget(RANDOM, 1)` (cpp 119).
            if let Some(target) = self.select_random_hostile(guid)
                && self.do_cast_spell_if_can(guid, BEAST_SPELL_FIREBALL, CastTarget::Unit(target))
            {
                let next = self.rng.urand(10_000, 12_000);
                if let Some(s) = self.the_beast_state_mut(guid) {
                    s.fireball_timer_ms = next;
                }
            }
        }
        let due = {
            let Some(s) = self.the_beast_state_mut(guid) else {
                return;
            };
            if s.fire_blast_timer_ms < diff_ms {
                true
            } else {
                s.fire_blast_timer_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, BEAST_SPELL_FIREBLAST, CastTarget::Unit(victim)) {
            let next = self.rng.urand(14_000, 20_000);
            if let Some(s) = self.the_beast_state_mut(guid) {
                s.fire_blast_timer_ms = next;
            }
        }
    }

