    /// `boss_warmastervooneAI::SpellHitTarget` (no dispatcher yet).
    fn warmaster_voone_spell_hit_target(
        &mut self,
        guid: ObjectGuid,
        _target: ObjectGuid,
        spell_id: u32,
    ) {
        if spell_id != VOONE_SPELL_THROW_AXE {
            return;
        }
        let count = self
            .warmaster_voone_state_mut(guid)
            .map_or(0, |s| s.axes_thrown_count);
        match count {
            0 => {
                // `SetVirtualItem(BASE_ATTACK, 12348)` /
                // `SetVirtualItem(OFF_ATTACK, 0)` (cpp 65-66).
                self.set_virtual_item_by_id(guid, 0, VOONE_VIRTUAL_ITEM_AXE);
                self.set_virtual_item_by_id(guid, 1, 0);
            }
            1 => {
                self.set_virtual_item_by_id(guid, 0, 0);
                self.set_virtual_item_by_id(guid, 1, 0);
                // `CastSpell(me, SPELL_UNARMED_PASSIVE, true)` (cpp 73).
                let _ = self.cast_spell(
                    guid,
                    VOONE_SPELL_UNARMED_PASSIVE,
                    CastTarget::SelfCast,
                    CastOptions {
                        triggered: true,
                        skip_known: true,
                        ..Default::default()
                    },
                );
            }
            _ => {}
        }
        if let Some(s) = self.warmaster_voone_state_mut(guid) {
            s.axes_thrown_count = s.axes_thrown_count.saturating_add(1);
        }
    }

