    /// `npc_blackhand_veteranAI::UpdateAI`. The fork `ManageTimer`
    /// fold (`timer < diff` due with no decrement, else decrement)
    /// is transcribed per timer in the standard shape.
    fn blackhand_veteran_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Charge: first cast goes to the victim and sets the flag,
        // later casts to a random target (cpp 56-71).
        let charge_due = {
            let Some(s) = self.blackhand_veteran_state_mut(guid) else {
                return;
            };
            if s.charge_timer_ms < diff_ms {
                true
            } else {
                s.charge_timer_ms -= diff_ms;
                false
            }
        };
        if charge_due {
            let first = self
                .blackhand_veteran_state_mut(guid)
                .is_some_and(|s| !s.first_charge_done);
            // NEEDS-MAP-HELPER: fork `SelectAttackingTarget(RANDOM, 0)` (cpp 60).
            let target = if first {
                Some(victim)
            } else {
                self.select_random_hostile(guid)
            };
            if let Some(target) = target {
                if first {
                    if let Some(s) = self.blackhand_veteran_state_mut(guid) {
                        s.first_charge_done = true;
                    }
                }
                if self.do_cast_spell_if_can(
                    guid,
                    VETERAN_SPELL_CHARGE_BOUCLIER,
                    CastTarget::Unit(target),
                ) {
                    let next = self.rng.urand(8000, 14_000);
                    if let Some(s) = self.blackhand_veteran_state_mut(guid) {
                        s.charge_timer_ms = next;
                    }
                }
            }
        }
        // Coup: only attempted against a non-melee caster, and only
        // 1-in-4 rolls cast (else the timer stays due, cpp 72-85).
        let coup_due = {
            let Some(s) = self.blackhand_veteran_state_mut(guid) else {
                return;
            };
            if s.coup_timer_ms < diff_ms {
                true
            } else {
                s.coup_timer_ms -= diff_ms;
                false
            }
        };
        if coup_due {
            // NEEDS-MAP-HELPER: fork `SelectAttackingTarget(RANDOM, 0)` (cpp 74)
            // plus `IsNonMeleeSpellCasted(false, false, true)` (cpp 76).
            if let Some(target) = self.select_random_hostile(guid) {
                let casting = false; // NEEDS-MAP-HELPER, see above.
                if casting
                    && self.rng.urand(0, 3) == 0
                    && self.do_cast_spell_if_can(
                        guid,
                        VETERAN_SPELL_COUP_BOUCLIER,
                        CastTarget::Unit(target),
                    )
                {
                    if let Some(s) = self.blackhand_veteran_state_mut(guid) {
                        s.coup_timer_ms = 10_000;
                    }
                }
            }
        }
        let frappe_due = {
            let Some(s) = self.blackhand_veteran_state_mut(guid) else {
                return;
            };
            if s.frappe_timer_ms < diff_ms {
                true
            } else {
                s.frappe_timer_ms -= diff_ms;
                false
            }
        };
        if frappe_due {
            // NEEDS-MAP-HELPER: fork `SelectAttackingTarget(RANDOM, 0)` (cpp 88).
            if let Some(target) = self.select_random_hostile(guid)
                && self.do_cast_spell_if_can(guid, VETERAN_SPELL_FRAPPE, CastTarget::Unit(target))
            {
                if let Some(s) = self.blackhand_veteran_state_mut(guid) {
                    s.frappe_timer_ms = 6000;
                }
            }
        }
    }

    /// `npc_klinfranAI::Reset`. Fork `Reset` branches on entry
    /// (cpp 444-471); the Nelson arm's respawn/home/teleport/
    /// movement/gossip writes have no helpers (noted inline).
    fn klinfran_reset(&mut self, guid: ObjectGuid) {
        let entry = self.creatures.get(&guid).map(|c| c.info.entry);
        if entry == Some(KLINFRAN_NPC_NELSON_THE_NICE) {
            // NEEDS-MAP-HELPER: `SetRespawnDelay/Time(35min)` +
            // `SetHomePosition(-8318.19, -993.662, 176.956, 5.65024)` +
            // `NearTeleportTo` + waypoint-motion re-init +
            // `SetUInt32Value(UNIT_NPC_FLAGS, UNIT_NPC_FLAG_GOSSIP)` (cpp 447-457).
            if let Some(s) = self.klinfran_state_mut(guid) {
                s.transform_timer_ms = 10_000;
                s.transform_emote_timer_ms = 5000;
                s.transform = false;
                s.despawn_timer_ms = 0;
            }
        } else if entry == Some(KLINFRAN_NPC_KLINFRAN_THE_CRAZED) {
            let arm = self
                .klinfran_state_mut(guid)
                .map_or(0, |s| s.despawn_timer_ms);
            if let Some(s) = self.klinfran_state_mut(guid) {
                // `20 * MINUTE * IN_MILLISECONDS` (cpp 466).
                if arm == 0 {
                    s.despawn_timer_ms = 1_200_000;
                }
                s.hunter = ObjectGuid::EMPTY;
                s.demonic_frenzy_timer_ms = 5000;
            }
        }
    }

