    /// `boss_dathrohan_balnazzarAI::UpdateAI` (cpp 166-344).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn dathrohan_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let transformed = self
            .ai
            .get(&guid)
            .and_then(|ai| ai.dathrohan())
            .is_some_and(|s| s.transformed);
        if transformed {
            self.dathrohan_update_transformed(guid, victim, diff_ms);
        } else {
            self.dathrohan_update_untransformed(guid, victim, diff_ms);
        }
    }

    /// Untransformed arm (cpp 172-223).
    fn dathrohan_update_untransformed(
        &mut self,
        guid: ObjectGuid,
        victim: ObjectGuid,
        diff_ms: u32,
    ) {
        // MindBlast (cpp 174-181).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.dathrohan())
            .is_some_and(|s| s.mind_blast_timer_ms < diff_ms)
        {
            if self.do_cast_spell_if_can(guid, DATHROHAN_SPELL_MINDBLAST, CastTarget::Unit(victim))
            {
                let next = self.rng.urand(15_000, 20_000);
                if let Some(s) = self.dathrohan_state_mut(guid) {
                    s.mind_blast_timer_ms = next;
                }
            }
        } else if let Some(s) = self.dathrohan_state_mut(guid) {
            s.mind_blast_timer_ms = s.mind_blast_timer_ms.saturating_sub(diff_ms);
        }
        // CrusadersHammer (cpp 183-190).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.dathrohan())
            .is_some_and(|s| s.crusaders_hammer_timer_ms < diff_ms)
        {
            if self.do_cast_spell_if_can(
                guid,
                DATHROHAN_SPELL_CRUSADERS_HAMMER,
                CastTarget::SelfCast,
            ) {
                if let Some(s) = self.dathrohan_state_mut(guid) {
                    s.crusaders_hammer_timer_ms = 12_000;
                }
            }
        } else if let Some(s) = self.dathrohan_state_mut(guid) {
            s.crusaders_hammer_timer_ms = s.crusaders_hammer_timer_ms.saturating_sub(diff_ms);
        }
        // CrusaderStrike (cpp 192-199).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.dathrohan())
            .is_some_and(|s| s.crusader_strike_timer_ms < diff_ms)
        {
            if self.do_cast_spell_if_can(
                guid,
                DATHROHAN_SPELL_CRUSADER_STRIKE,
                CastTarget::Unit(victim),
            ) {
                if let Some(s) = self.dathrohan_state_mut(guid) {
                    s.crusader_strike_timer_ms = 15_000;
                }
            }
        } else if let Some(s) = self.dathrohan_state_mut(guid) {
            s.crusader_strike_timer_ms = s.crusader_strike_timer_ms.saturating_sub(diff_ms);
        }
        // HolyStrike (cpp 201-208).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.dathrohan())
            .is_some_and(|s| s.holy_strike_timer_ms < diff_ms)
        {
            if self.do_cast_spell_if_can(
                guid,
                DATHROHAN_SPELL_HOLY_STRIKE,
                CastTarget::Unit(victim),
            ) {
                if let Some(s) = self.dathrohan_state_mut(guid) {
                    s.holy_strike_timer_ms = 15_000;
                }
            }
        } else if let Some(s) = self.dathrohan_state_mut(guid) {
            s.holy_strike_timer_ms = s.holy_strike_timer_ms.saturating_sub(diff_ms);
        }
        // BalnazzarTransform (cpp 210-222).
        if self.creature_health_percent(guid) < 40.0 {
            if self.bot_casting_spell(guid).is_some() {
                self.cancel_cast(guid, false);
            }
            // `DoCastSpellIfCan(m_creature, SPELL_BALNAZZARTRANSFORM)` (no
            // `== CAST_OK` check in the fork).
            self.do_cast_spell_if_can(
                guid,
                DATHROHAN_SPELL_BALNAZZAR_TRANSFORM,
                CastTarget::SelfCast,
            );
            // NEEDS-MAP-HELPER: `UpdateEntry(NPC_BALNAZZAR)` (restores full
            // HP/mana via the template switch; no update-entry helper).
            if let Some(s) = self.dathrohan_state_mut(guid) {
                s.transform_timer_ms = 4000;
                s.transformed = true;
            }
        }
    }

    /// Transformed arm (cpp 224-341).
    #[allow(clippy::too_many_lines)]
    fn dathrohan_update_transformed(&mut self, guid: ObjectGuid, victim: ObjectGuid, diff_ms: u32) {
        // Transform stun window (cpp 226-238).
        let transform_left = self
            .ai
            .get(&guid)
            .and_then(|ai| ai.dathrohan())
            .map_or(0, |s| s.transform_timer_ms);
        if transform_left != 0 {
            if transform_left <= diff_ms {
                self.do_script_text(DATHROHAN_SAY_TRANSFORM, guid, None, -1);
                if let Some(s) = self.dathrohan_state_mut(guid) {
                    s.transform_timer_ms = 0;
                }
            } else {
                if let Some(s) = self.dathrohan_state_mut(guid) {
                    s.transform_timer_ms = transform_left - diff_ms;
                }
                return;
            }
        }
        // MindControl threat restore (cpp 240-258).
        self.dathrohan_restore_threat(guid, true);
        // Sleep threat restore (cpp 259-277).
        self.dathrohan_restore_threat(guid, false);
        // MindBlast (cpp 278-285).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.dathrohan())
            .is_some_and(|s| s.mind_blast_timer_ms < diff_ms)
        {
            if self.do_cast_spell_if_can(guid, DATHROHAN_SPELL_MINDBLAST, CastTarget::Unit(victim))
            {
                let next = self.rng.urand(15_000, 20_000);
                if let Some(s) = self.dathrohan_state_mut(guid) {
                    s.mind_blast_timer_ms = next;
                }
            }
        } else if let Some(s) = self.dathrohan_state_mut(guid) {
            s.mind_blast_timer_ms = s.mind_blast_timer_ms.saturating_sub(diff_ms);
        }
        // ShadowShock (cpp 287-294; fork ignores the cast result and always
        // resets the timer).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.dathrohan())
            .is_some_and(|s| s.shadowshock_timer_ms < diff_ms)
        {
            self.do_cast_spell_if_can(guid, DATHROHAN_SPELL_SHADOWSHOCK, CastTarget::Unit(victim));
            if let Some(s) = self.dathrohan_state_mut(guid) {
                s.shadowshock_timer_ms = 11_000;
            }
        } else if let Some(s) = self.dathrohan_state_mut(guid) {
            s.shadowshock_timer_ms = s.shadowshock_timer_ms.saturating_sub(diff_ms);
        }
        // PsychicScream (cpp 296-303).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.dathrohan())
            .is_some_and(|s| s.psychic_scream_timer_ms < diff_ms)
        {
            if self.do_cast_spell_if_can(guid, DATHROHAN_SPELL_PSYCHIC_SCREAM, CastTarget::SelfCast)
            {
                if let Some(s) = self.dathrohan_state_mut(guid) {
                    s.psychic_scream_timer_ms = 20_000;
                }
            }
        } else if let Some(s) = self.dathrohan_state_mut(guid) {
            s.psychic_scream_timer_ms = s.psychic_scream_timer_ms.saturating_sub(diff_ms);
        }
        // DeepSleep (cpp 305-323): random target without the sleep aura.
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.dathrohan())
            .is_some_and(|s| s.deep_sleep_timer_ms < diff_ms)
        {
            // NEEDS-MAP-HELPER: `SelectAttackingTarget(ATTACKING_TARGET_RANDOM,
            // 1)` (no random-threat helper on `Map`).
            if let Some(target) = self.select_random_hostile(guid)
                && !self.bot_has_aura(target, DATHROHAN_SPELL_SLEEP)
            {
                let aggro = self.threat_on(guid, target);
                if self.do_cast_spell_if_can(guid, DATHROHAN_SPELL_SLEEP, CastTarget::Unit(target))
                {
                    if let Some(s) = self.dathrohan_state_mut(guid) {
                        s.sleep_player = target;
                        s.sleep_aggro = aggro;
                    }
                    self.modify_threat_percent_of(guid, target, -100);
                    if let Some(s) = self.dathrohan_state_mut(guid) {
                        s.deep_sleep_timer_ms = 15_000;
                    }
                }
            }
        } else if let Some(s) = self.dathrohan_state_mut(guid) {
            s.deep_sleep_timer_ms = s.deep_sleep_timer_ms.saturating_sub(diff_ms);
        }
        // MindControl (cpp 325-340): second-top-aggro target without sleep.
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.dathrohan())
            .is_some_and(|s| s.mind_control_timer_ms < diff_ms)
        {
            if let Some(target) = self.threat_targets_sorted(guid).get(1).copied()
                && !self.bot_has_aura(target, DATHROHAN_SPELL_SLEEP)
            {
                let aggro = self.threat_on(guid, target);
                if self.do_cast_spell_if_can(
                    guid,
                    DATHROHAN_SPELL_MINDCONTROL,
                    CastTarget::Unit(target),
                ) {
                    let next = self.rng.urand(25_000, 30_000);
                    if let Some(s) = self.dathrohan_state_mut(guid) {
                        s.mind_control_player = target;
                        s.mind_control_aggro = aggro;
                        s.mind_control_timer_ms = next;
                    }
                }
            }
        } else if let Some(s) = self.dathrohan_state_mut(guid) {
            s.mind_control_timer_ms = s.mind_control_timer_ms.saturating_sub(diff_ms);
        }
    }

    /// MC/Sleep aura-loss threat restore (cpp 240-277). `mind_control` picks
    /// the field pair; fork clears only on a live aura check or an empty
    /// slot, and keeps a stale guid when the player left the map.
    fn dathrohan_restore_threat(&mut self, guid: ObjectGuid, mind_control: bool) {
        let (stored, spell) =
            self.ai
                .get(&guid)
                .and_then(|ai| ai.dathrohan())
                .map_or((ObjectGuid::EMPTY, 0), |s| {
                    if mind_control {
                        (s.mind_control_player, DATHROHAN_SPELL_MINDCONTROL)
                    } else {
                        (s.sleep_player, DATHROHAN_SPELL_SLEEP)
                    }
                });
        if stored.is_empty() {
            return;
        }
        let Some(_player) = self.players.get(&stored) else {
            return;
        };
        if !self.bot_has_aura(stored, spell) {
            let aggro = self
                .ai
                .get(&guid)
                .and_then(|ai| ai.dathrohan())
                .map_or(0.0, |s| {
                    if mind_control {
                        s.mind_control_aggro
                    } else {
                        s.sleep_aggro
                    }
                });
            self.modify_threat_percent_of(guid, stored, -100);
            self.add_threat(guid, stored, aggro);
            if let Some(s) = self.dathrohan_state_mut(guid) {
                if mind_control {
                    s.mind_control_player = ObjectGuid::EMPTY;
                    s.mind_control_aggro = 0.0;
                } else {
                    s.sleep_player = ObjectGuid::EMPTY;
                    s.sleep_aggro = 0.0;
                }
            }
        }
    }
    fn barthilas_state_mut(&mut self, guid: ObjectGuid) -> Option<&mut MagistrateBarthilasAi> {
        self.ai.get_mut(&guid).and_then(|ai| ai.barthilas_mut())
    }

    /// `boss_magistrate_barthilasAI::Reset` (cpp 28-40).
    fn barthilas_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.barthilas_state_mut(guid) {
            s.draining_blow_timer_ms = 16_000;
            s.crowd_pummel_timer_ms = 12_000;
            s.mighty_blow_timer_ms = 8000;
            s.furious_anger_timer_ms = 5000;
            s.anger_count = 0;
        }
        // Fork branches on `IsAlive()` (ctor vs evade display).
        let model = if self.unit_is_alive(guid) {
            BARTHILAS_MODEL_NORMAL
        } else {
            BARTHILAS_MODEL_HUMAN
        };
        let _ = self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_DISPLAYID), model);
    }

    /// `boss_magistrate_barthilasAI::MoveInLineOfSight` (cpp 42-49).
    /// NO-DISPATCHER-YET.
    fn barthilas_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        if who.is_player()
            && self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS) & STRAT_UNIT_FLAG_SPAWNING
                != 0
        {
            let me = self.object_position(guid).unwrap_or_default();
            let other = self.object_position(who).unwrap_or_default();
            if crate::visibility::dist3d(me, other) <= 10.0 {
                let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::UNIT_FIELD_FLAGS),
                    flags & !STRAT_UNIT_FLAG_SPAWNING,
                );
            }
        }
        // Base `ScriptedAI::MoveInLineOfSight` proximity handling has no
        // hook here; the generic aggro tick covers it.
    }

    /// `boss_magistrate_barthilasAI::JustDied` (cpp 51).
    fn barthilas_just_died(&mut self, guid: ObjectGuid) {
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_DISPLAYID),
            BARTHILAS_MODEL_HUMAN,
        );
    }

    /// `boss_magistrate_barthilasAI::UpdateAI` (cpp 53-98).
    fn barthilas_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // FuriousAnger (cpp 58-68): re-arms every tick while due; past 25
        // stacks the fork `return`s before melee.
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.barthilas())
            .is_some_and(|s| s.furious_anger_timer_ms < diff_ms)
        {
            if let Some(s) = self.barthilas_state_mut(guid) {
                s.furious_anger_timer_ms = 4000;
            }
            // Fork checks `> 25` before incrementing (cpp 61-64).
            let over = self
                .ai
                .get(&guid)
                .and_then(|ai| ai.barthilas())
                .is_some_and(|s| s.anger_count > 25);
            if over {
                return;
            }
            if let Some(s) = self.barthilas_state_mut(guid) {
                s.anger_count = s.anger_count.saturating_add(1);
            }
            let _ = self.cast_spell(
                guid,
                BARTHILAS_SPELL_FURIOUS_ANGER,
                CastTarget::SelfCast,
                cai_triggered_cast_options(false),
            );
        } else if let Some(s) = self.barthilas_state_mut(guid) {
            s.furious_anger_timer_ms = s.furious_anger_timer_ms.saturating_sub(diff_ms);
        }
        // DrainingBlow (cpp 70-77; fork ignores the cast result).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.barthilas())
            .is_some_and(|s| s.draining_blow_timer_ms < diff_ms)
        {
            self.do_cast_spell_if_can(
                guid,
                BARTHILAS_SPELL_DRAINING_BLOW,
                CastTarget::Unit(victim),
            );
            if let Some(s) = self.barthilas_state_mut(guid) {
                s.draining_blow_timer_ms = 15_000;
            }
        } else if let Some(s) = self.barthilas_state_mut(guid) {
            s.draining_blow_timer_ms = s.draining_blow_timer_ms.saturating_sub(diff_ms);
        }
        // CrowdPummel (cpp 79-86; fork ignores the cast result).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.barthilas())
            .is_some_and(|s| s.crowd_pummel_timer_ms < diff_ms)
        {
            self.do_cast_spell_if_can(guid, BARTHILAS_SPELL_CROWD_PUMMEL, CastTarget::Unit(victim));
            if let Some(s) = self.barthilas_state_mut(guid) {
                s.crowd_pummel_timer_ms = 15_000;
            }
        } else if let Some(s) = self.barthilas_state_mut(guid) {
            s.crowd_pummel_timer_ms = s.crowd_pummel_timer_ms.saturating_sub(diff_ms);
        }
        // MightyBlow (cpp 88-95; fork ignores the cast result).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.barthilas())
            .is_some_and(|s| s.mighty_blow_timer_ms < diff_ms)
        {
            self.do_cast_spell_if_can(guid, BARTHILAS_SPELL_MIGHTY_BLOW, CastTarget::Unit(victim));
            if let Some(s) = self.barthilas_state_mut(guid) {
                s.mighty_blow_timer_ms = 20_000;
            }
        } else if let Some(s) = self.barthilas_state_mut(guid) {
            s.mighty_blow_timer_ms = s.mighty_blow_timer_ms.saturating_sub(diff_ms);
        }
    }
