    /// `boss_maleki_the_pallidAI::UpdateAI` (cpp 71-156).
    #[allow(clippy::too_many_lines)]
    fn maleki_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Iced-player threat restore (cpp 76-92).
        let iced = self
            .ai
            .get(&guid)
            .and_then(|ai| ai.maleki())
            .map_or(ObjectGuid::EMPTY, |s| s.iced_player);
        if !iced.is_empty() {
            if self.players.contains_key(&iced) && !self.bot_has_aura(iced, MALEKI_SPELL_ICETOMB) {
                let aggro = self
                    .ai
                    .get(&guid)
                    .and_then(|ai| ai.maleki())
                    .map_or(0.0, |s| s.iced_aggro);
                self.add_threat(guid, iced, aggro);
                if let Some(s) = self.maleki_state_mut(guid) {
                    s.iced_player = ObjectGuid::EMPTY;
                    s.iced_aggro = 0.0;
                }
            } else if !self.players.contains_key(&iced) {
                // Fork clears when the player left the map (cpp 87-91).
                if let Some(s) = self.maleki_state_mut(guid) {
                    s.iced_player = ObjectGuid::EMPTY;
                    s.iced_aggro = 0.0;
                }
            }
        }
        // Frostbolt (cpp 94-101).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.maleki())
            .is_some_and(|s| s.frostbolt_timer_ms < diff_ms)
        {
            if self.do_cast_spell_if_can(guid, MALEKI_SPELL_FROSTBOLT, CastTarget::Unit(victim)) {
                let next = self.rng.urand(3500, 4500);
                if let Some(s) = self.maleki_state_mut(guid) {
                    s.frostbolt_timer_ms = next;
                }
            }
        } else if let Some(s) = self.maleki_state_mut(guid) {
            s.frostbolt_timer_ms = s.frostbolt_timer_ms.saturating_sub(diff_ms);
        }
        // IceTomb (cpp 103-118).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.maleki())
            .is_some_and(|s| s.ice_tomb_timer_ms < diff_ms)
        {
            let aggro = self.threat_on(guid, victim);
            if self.do_cast_spell_if_can(guid, MALEKI_SPELL_ICETOMB, CastTarget::Unit(victim)) {
                let next = self.rng.urand(20_000, 25_000);
                if let Some(s) = self.maleki_state_mut(guid) {
                    s.iced_player = victim;
                    s.iced_aggro = aggro;
                    s.ice_tomb_timer_ms = next;
                }
                self.modify_threat_percent_of(guid, victim, -100);
            }
        } else if let Some(s) = self.maleki_state_mut(guid) {
            s.ice_tomb_timer_ms = s.ice_tomb_timer_ms.saturating_sub(diff_ms);
        }
        // DrainLife/DrainMana gate (cpp 120-137).
        let hp_pct = self.creature_health_percent(guid);
        let mana_pct = self.maleki_mana_percent(guid);
        if hp_pct < 60.0 || mana_pct < 50.0 {
            if let Some(s) = self.maleki_state_mut(guid) {
                s.need_move_closer = true;
            }
            if self
                .ai
                .get(&guid)
                .and_then(|ai| ai.maleki())
                .is_some_and(|s| s.drain_timer_ms < diff_ms)
            {
                let mana_target = self.object_get_field(victim, offsets::UNIT_FIELD_POWER1) != 0;
                let spell = if mana_target {
                    MALEKI_SPELL_DRAIN_MANA
                } else {
                    MALEKI_SPELL_DRAIN_LIFE
                };
                if self.do_cast_spell_if_can(guid, spell, CastTarget::Unit(victim)) {
                    let next = self.rng.urand(12_000, 18_000);
                    if let Some(s) = self.maleki_state_mut(guid) {
                        s.drain_timer_ms = next;
                    }
                }
            } else if let Some(s) = self.maleki_state_mut(guid) {
                s.drain_timer_ms = s.drain_timer_ms.saturating_sub(diff_ms);
            }
        } else if let Some(s) = self.maleki_state_mut(guid) {
            s.need_move_closer = false;
        }
        // Range handling (cpp 139-155): chase when far or oom, idle in
        // cast range. `SetCombatMovement` is `ai.combat_movement`.
        let need_closer = self
            .ai
            .get(&guid)
            .and_then(|ai| ai.maleki())
            .is_some_and(|s| s.need_move_closer);
        let mana_now = self.maleki_mana_percent(guid);
        let dist2d = match (self.unit_position(guid), self.unit_position(victim)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                (dx * dx + dy * dy).sqrt()
            }
            _ => 0.0,
        };
        let chase_range = if need_closer { 20.0 } else { 40.0 };
        if dist2d > chase_range || mana_now < 10.0 {
            if let Some(ai) = self.ai.get_mut(&guid) {
                ai.combat_movement = true;
            }
            self.creature_move_chase(guid, victim, 0.0, 0.0);
        } else {
            if let Some(ai) = self.ai.get_mut(&guid) {
                ai.combat_movement = false;
            }
            self.creature_move_idle(guid);
        }
    }
