    /// `boss_nerubenkanAI::RaiseUndeadScarab` (cpp 60-90).
    /// `DoSpawnCreature(entry, 10.0f, ...)` scatters around the caster; the
    /// fork scatter helper is unmodeled, so the offsets use the herod
    /// `frand` scatter precedent (square, not disc; see unresolved).
    fn nerubenkan_raise_undead_scarab(
        &mut self,
        guid: ObjectGuid,
        victim: ObjectGuid,
        crypt: bool,
    ) {
        if crypt {
            let amount = match self.rng.urand(0, 2) {
                0 => 4,
                1 => 6,
                _ => 8,
            };
            for _ in 0..amount {
                let jx = self.rng.frand(-10.0, 10.0);
                let jy = self.rng.frand(-10.0, 10.0);
                let me = self.unit_position(guid).unwrap_or_default();
                if let Some(summoned) = self.summon_creature(
                    NERUBENKAN_NPC_CRYPT_SCARAB,
                    Position::new(me.x + jx, me.y + jy, me.z, 0.0),
                    guid,
                    TEMPSUMMON_TIMED_DESPAWN_OUT_OF_COMBAT,
                    10_000,
                ) {
                    self.attack_start(summoned, victim);
                }
            }
        } else {
            let jx = self.rng.frand(-10.0, 10.0);
            let jy = self.rng.frand(-10.0, 10.0);
            let me = self.unit_position(guid).unwrap_or_default();
            if let Some(summoned) = self.summon_creature(
                NERUBENKAN_NPC_UNDEAD_SCARAB,
                Position::new(me.x + jx, me.y + jy, me.z, 0.0),
                guid,
                TEMPSUMMON_TIMED_DESPAWN_OUT_OF_COMBAT,
                10_000,
            ) {
                self.attack_start(summoned, victim);
            }
        }
    }

