    /// `boss_nerubenkanAI::UpdateAI` (cpp 98-160).
    fn nerubenkan_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Webbed-player threat restore (cpp 103-119).
        let webbed = self
            .ai
            .get(&guid)
            .and_then(|ai| ai.nerubenkan())
            .map_or(ObjectGuid::EMPTY, |s| s.webbed_player);
        if !webbed.is_empty() {
            if self.players.contains_key(&webbed)
                && !self.bot_has_aura(webbed, NERUBENKAN_SPELL_ENCASING_WEBS)
            {
                let aggro = self
                    .ai
                    .get(&guid)
                    .and_then(|ai| ai.nerubenkan())
                    .map_or(0.0, |s| s.webbed_aggro);
                self.add_threat(guid, webbed, aggro);
                if let Some(s) = self.nerubenkan_state_mut(guid) {
                    s.webbed_player = ObjectGuid::EMPTY;
                    s.webbed_aggro = 0.0;
                }
            } else if !self.players.contains_key(&webbed) {
                if let Some(s) = self.nerubenkan_state_mut(guid) {
                    s.webbed_player = ObjectGuid::EMPTY;
                    s.webbed_aggro = 0.0;
                }
            }
        }
        // EncasingWebs (cpp 121-136).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.nerubenkan())
            .is_some_and(|s| s.encasing_webs_timer_ms < diff_ms)
        {
            let aggro = self.threat_on(guid, victim);
            if self.do_cast_spell_if_can(
                guid,
                NERUBENKAN_SPELL_ENCASING_WEBS,
                CastTarget::Unit(victim),
            ) {
                let next = self.rng.urand(10_000, 15_000);
                if let Some(s) = self.nerubenkan_state_mut(guid) {
                    s.webbed_player = victim;
                    s.webbed_aggro = aggro;
                    s.encasing_webs_timer_ms = next;
                }
                self.modify_threat_percent_of(guid, victim, -100);
            }
        } else if let Some(s) = self.nerubenkan_state_mut(guid) {
            s.encasing_webs_timer_ms = s.encasing_webs_timer_ms.saturating_sub(diff_ms);
        }
        // PierceArmor (cpp 138-145).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.nerubenkan())
            .is_some_and(|s| s.pierce_armor_timer_ms < diff_ms)
        {
            if self.do_cast_spell_if_can(
                guid,
                NERUBENKAN_SPELL_PIERCE_ARMOR,
                CastTarget::Unit(victim),
            ) {
                let next = self.rng.urand(15_000, 20_000);
                if let Some(s) = self.nerubenkan_state_mut(guid) {
                    s.pierce_armor_timer_ms = next;
                }
            }
        } else if let Some(s) = self.nerubenkan_state_mut(guid) {
            s.pierce_armor_timer_ms = s.pierce_armor_timer_ms.saturating_sub(diff_ms);
        }
        // RaiseUndeadScarab (cpp 147-157).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.nerubenkan())
            .is_some_and(|s| s.raise_undead_scarab_timer_ms < diff_ms)
        {
            // NEEDS-MAP-HELPER: `SelectAttackingTarget(ATTACKING_TARGET_RANDOM,
            // 0)` (no random-threat helper on `Map`).
            if let Some(target) = self.select_random_hostile(guid) {
                let crypt = self.rng.urand(0, 1) != 0;
                self.nerubenkan_raise_undead_scarab(guid, target, crypt);
                let next = self.rng.urand(6000, 10_000);
                if let Some(s) = self.nerubenkan_state_mut(guid) {
                    s.raise_undead_scarab_timer_ms = next;
                }
            }
        } else if let Some(s) = self.nerubenkan_state_mut(guid) {
            s.raise_undead_scarab_timer_ms = s.raise_undead_scarab_timer_ms.saturating_sub(diff_ms);
        }
    }
