    /// Instance field for this boss' entry (cpp 64-82, 88-106).
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn silver_hand_type_for(entry: u32) -> Option<u32> {
        match entry {
            SILVER_HAND_ENTRY_AELMAR => Some(STRAT_TYPE_SH_AELMAR),
            SILVER_HAND_ENTRY_CATHELA => Some(STRAT_TYPE_SH_CATHELA),
            SILVER_HAND_ENTRY_GREGOR => Some(STRAT_TYPE_SH_GREGOR),
            SILVER_HAND_ENTRY_NEMAS => Some(STRAT_TYPE_SH_NEMAS),
            SILVER_HAND_ENTRY_VICAR => Some(STRAT_TYPE_SH_VICAR),
            _ => None,
        }
    }

    /// `boss_silver_hand_bossesAI::Reset` (cpp 57-83).
    fn silver_hand_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.silver_hand_state_mut(guid) {
            s.holy_light_timer_ms = 20_000;
            s.divine_shield_timer_ms = 20_000;
        }
        if let Some(field) = self.object_entry(guid).and_then(Self::silver_hand_type_for) {
            self.strat_set_data(field, 0);
        }
    }

    /// `boss_silver_hand_bossesAI::JustDied` (cpp 85-110). The killer credit
    /// needs the killer guid, which the dispatch shape does not forward;
    /// see unresolved.
    fn silver_hand_just_died(&mut self, guid: ObjectGuid) {
        if let Some(field) = self.object_entry(guid).and_then(Self::silver_hand_type_for) {
            self.strat_set_data(field, 2);
        }
        // NEEDS-MAP-HELPER: killer forwarding — fork does
        // `if (GetData(TYPE_SH_QUEST) && Killer->GetTypeId() == TYPEID_PLAYER)
        // ((Player*)Killer)->KilledMonsterCredit(SH_QUEST_CREDIT, GetGUID())`.
        // With the killer available: `quest_kill_credit_one(killer, guid,
        // 17915)` gated on
        // `strat_get_data(STRAT_TYPE_SH_QUEST).is_some_and(|v| v != 0)`
        // and `killer.is_player()`.
    }

    /// `boss_silver_hand_bossesAI::UpdateAI` (cpp 112-141).
    fn silver_hand_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // HolyLight (cpp 118-127): due but healthy just retries next tick.
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.silver_hand())
            .is_some_and(|s| s.holy_light_timer_ms < diff_ms)
        {
            if self.creature_health_percent(guid) < 20.0 {
                let _ = self.cast_spell(
                    guid,
                    SILVER_HAND_SPELL_HOLY_LIGHT,
                    CastTarget::SelfCast,
                    cai_triggered_cast_options(false),
                );
                if let Some(s) = self.silver_hand_state_mut(guid) {
                    s.holy_light_timer_ms = 20_000;
                }
            }
        } else if let Some(s) = self.silver_hand_state_mut(guid) {
            s.holy_light_timer_ms = s.holy_light_timer_ms.saturating_sub(diff_ms);
        }
        // DivineShield (cpp 129-138): same retry shape.
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.silver_hand())
            .is_some_and(|s| s.divine_shield_timer_ms < diff_ms)
        {
            if self.creature_health_percent(guid) < 5.0 {
                let _ = self.cast_spell(
                    guid,
                    SILVER_HAND_SPELL_DIVINE_SHIELD,
                    CastTarget::SelfCast,
                    cai_triggered_cast_options(false),
                );
                if let Some(s) = self.silver_hand_state_mut(guid) {
                    s.divine_shield_timer_ms = 40_000;
                }
            }
        } else if let Some(s) = self.silver_hand_state_mut(guid) {
            s.divine_shield_timer_ms = s.divine_shield_timer_ms.saturating_sub(diff_ms);
        }
    }
