    /// `boss_ramstein_the_gorgerAI::UpdateAI` (cpp 70-97).
    fn ramstein_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Trample (cpp 75-82; fork ignores the cast result).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.ramstein())
            .is_some_and(|s| s.trample_timer_ms < diff_ms)
        {
            self.do_cast_spell_if_can(guid, RAMSTEIN_SPELL_TRAMPLE, CastTarget::SelfCast);
            if let Some(s) = self.ramstein_state_mut(guid) {
                s.trample_timer_ms = 7000;
            }
        } else if let Some(s) = self.ramstein_state_mut(guid) {
            s.trample_timer_ms = s.trample_timer_ms.saturating_sub(diff_ms);
        }
        // Knockout (cpp 84-94).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.ramstein())
            .is_some_and(|s| s.knockout_timer_ms < diff_ms)
        {
            if self.do_cast_spell_if_can(guid, RAMSTEIN_SPELL_KNOCKOUT, CastTarget::Unit(victim)) {
                self.modify_threat_percent_of(guid, victim, -100);
                if let Some(s) = self.ramstein_state_mut(guid) {
                    s.knockout_timer_ms = 10_000;
                }
            }
        } else if let Some(s) = self.ramstein_state_mut(guid) {
            s.knockout_timer_ms = s.knockout_timer_ms.saturating_sub(diff_ms);
        }
    }
