    /// `npc_crimson_guardsmanAI::Reset` (cpp 82-88). The ctor DB-guid check
    /// is idempotent per guid, so it runs here too.
    fn guardsman_reset(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: fork reads the spawn-table guid
        // (`GetDBTableGUIDLow() == 54070`); `guid.counter()` is the
        // materialized-guid stand-in.
        let is_spawner = guid.counter() == GUARDSMAN_TIMMY_SPAWNER_DB_GUID;
        if let Some(s) = self.guardsman_state_mut(guid) {
            s.has_fled = false;
            s.is_timmy_spawner = is_spawner;
            s.disarm_timer_ms = 6000;
            s.shield_bash_timer_ms = 4000;
            s.shield_charge_timer_ms = 1000;
        }
    }

    /// `npc_crimson_guardsmanAI::JustDied` (cpp 90-105). `pKiller` is only
    /// the yell target; the dispatch shape carries no killer, so the yell
    /// uses no target (see unresolved).
    fn guardsman_just_died(&mut self, guid: ObjectGuid) {
        let is_spawner = self
            .ai
            .get(&guid)
            .and_then(|ai| ai.guardsman())
            .is_some_and(|s| s.is_timmy_spawner);
        if !is_spawner {
            return;
        }
        if let Some(timmy) = self.summon_creature(
            TIMMY_ENTRY,
            Position::new(
                GUARDSMAN_TIMMY_POS.0,
                GUARDSMAN_TIMMY_POS.1,
                GUARDSMAN_TIMMY_POS.2,
                GUARDSMAN_TIMMY_POS.3,
            ),
            guid,
            GUARDSMAN_TEMPSUMMON_MANUAL_DESPAWN,
            0,
        ) {
            // Reuses `TIMMY_SAY_SPAWN` (same file).
            self.do_script_text(TIMMY_SAY_SPAWN, timmy, None, -1);
            // NEEDS-MAP-HELPER: `SetRespawnTime(9999999)` (no
            // respawn-time helper on `Map`).
        }
        if let Some(s) = self.guardsman_state_mut(guid) {
            s.is_timmy_spawner = false;
        }
        // Fork `DeleteLater()`.
        self.despawn_creature_now(guid, u32::MAX);
    }

