    /// `mob_restless_soulAI::UpdateAI` (cpp 137-150): tagged countdown only;
    /// the fork never runs the combat drive here.
    #[allow(clippy::similar_names)]
    fn restless_soul_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let (tagged, tagger) = self
            .ai
            .get(&guid)
            .and_then(|ai| ai.restless_soul())
            .map_or((false, ObjectGuid::EMPTY), |s| (s.tagged, s.tagger));
        if !tagged {
            return;
        }
        let due = self
            .ai
            .get(&guid)
            .and_then(|ai| ai.restless_soul())
            .is_some_and(|s| s.die_timer_ms < diff_ms);
        if due {
            self.quest_kill_credit(guid, Some(tagger));
            let hp = self.object_get_field(guid, offsets::UNIT_FIELD_HEALTH);
            self.deal_damage(guid, guid, hp, false);
        } else if let Some(s) = self.restless_soul_state_mut(guid) {
            s.die_timer_ms = s.die_timer_ms.saturating_sub(diff_ms);
        }
    }
