    /// `mobs_spectral_ghostly_citizenAI::JustDied` (cpp 191-206).
    /// `GetRandomPoint(20.0f)` scatter is approximated with the herod
    /// `frand` offsets (square, not disc; see unresolved).
    fn spectral_just_died(&mut self, guid: ObjectGuid) {
        let tagged = self
            .ai
            .get(&guid)
            .and_then(|ai| ai.spectral())
            .is_some_and(|s| s.tagged);
        if !tagged {
            return;
        }
        let me = self.object_position(guid).unwrap_or_default();
        for i in 1..=4u32 {
            let jx = self.rng.frand(-20.0, 20.0);
            let jy = self.rng.frand(-20.0, 20.0);
            // Fork `100%, 50%, 33%, 25%` gate (`urand(1, i) == 1`).
            if self.rng.urand(1, i) == 1 {
                self.summon_creature(
                    RESTLESS_SOUL_ENTRY_RESTLESS,
                    Position::new(me.x + jx, me.y + jy, me.z, 0.0),
                    guid,
                    SPECTRAL_TEMPSUMMON_CORPSE_DESPAWN,
                    600_000,
                );
            }
        }
    }

    /// `mobs_spectral_ghostly_citizenAI::UpdateAI` (cpp 208-230).
    fn spectral_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Tagged countdown (cpp 210-216): no drive here.
        let tagged = self
            .ai
            .get(&guid)
            .and_then(|ai| ai.spectral())
            .is_some_and(|s| s.tagged);
        if tagged {
            let due = self
                .ai
                .get(&guid)
                .and_then(|ai| ai.spectral())
                .is_some_and(|s| s.die_timer_ms < diff_ms);
            if due {
                let hp = self.object_get_field(guid, offsets::UNIT_FIELD_HEALTH);
                self.deal_damage(guid, guid, hp, false);
            } else if let Some(s) = self.spectral_state_mut(guid) {
                s.die_timer_ms = s.die_timer_ms.saturating_sub(diff_ms);
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Haunting phantom (cpp 221-227; unconditional cast).
        if self
            .ai
            .get(&guid)
            .and_then(|ai| ai.spectral())
            .is_some_and(|s| s.haunting_timer_ms < diff_ms)
        {
            // Fork `m_creature->CastSpell(m_creature->GetVictim(), ...)`
            // (cpp 223).
            let _ = self.cast_spell(
                guid,
                SPECTRAL_SPELL_HAUNTING_PHANTOM,
                CastTarget::Unit(victim),
                cai_triggered_cast_options(false),
            );
            if let Some(s) = self.spectral_state_mut(guid) {
                s.haunting_timer_ms = 20_000;
            }
        } else if let Some(s) = self.spectral_state_mut(guid) {
            s.haunting_timer_ms = s.haunting_timer_ms.saturating_sub(diff_ms);
        }
    }

    /// `mobs_spectral_ghostly_citizenAI::ReceiveEmote` (cpp 232-260).
    /// NO-DISPATCHER-YET.
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn spectral_receive_emote(&mut self, guid: ObjectGuid, player: ObjectGuid, emote: u32) {
        match emote {
            SPECTRAL_TEXTEMOTE_DANCE => {
                let in_combat = self.ai_in_combat(guid);
                let evaded = self
                    .ai
                    .get(&guid)
                    .and_then(|ai| ai.spectral())
                    .is_some_and(|s| s.has_evaded_once);
                if in_combat && !evaded {
                    self.enter_evade_mode(guid);
                    if let Some(s) = self.spectral_state_mut(guid) {
                        s.has_evaded_once = true;
                    }
                } else {
                    self.handle_emote_command(guid, SPECTRAL_EMOTE_STATE_DANCE);
                }
            }
            SPECTRAL_TEXTEMOTE_RUDE => {
                if self.can_reach_melee(guid, player) {
                    // Fork `m_creature->CastSpell(pPlayer, SPELL_SLAP, false)`
                    // (cpp 250).
                    let _ = self.cast_spell(
                        guid,
                        SPECTRAL_SPELL_SLAP,
                        CastTarget::Unit(player),
                        cai_triggered_cast_options(false),
                    );
                } else {
                    self.handle_emote_command(guid, SPECTRAL_EMOTE_ONESHOT_RUDE);
                }
            }
            SPECTRAL_TEXTEMOTE_WAVE => {
                self.handle_emote_command(guid, SPECTRAL_EMOTE_ONESHOT_WAVE);
            }
            SPECTRAL_TEXTEMOTE_BOW => {
                self.handle_emote_command(guid, SPECTRAL_EMOTE_ONESHOT_BOW);
            }
            SPECTRAL_TEXTEMOTE_KISS => {
                // Fork answers kiss with `EMOTE_ONESHOT_FLEX` (cpp 259).
                self.handle_emote_command(guid, SPECTRAL_EMOTE_ONESHOT_FLEX);
            }
            _ => {}
        }
    }

