        // Fork `TEMPSUMMON_TIMED_DESPAWN, 1` and `GetPositionZ() - 100`.
        if let Some(pop) = self.summon_creature(
            CRISTAL_NPC_ACOLYTE,
            Position::new(me.x, me.y, me.z - 100.0, 0.0),
            guid,
            CRISTAL_TEMPSUMMON_TIMED_DESPAWN,
            1,
        ) {
            // Fork `MonsterYellToZone` (zone delivery follows the DB text
            // type, DM Immol'Thar precedent).
            self.do_script_text(CRISTAL_SAY_CRYSTAL_DESTROYED, pop, None, -1);
            self.strat_set_data(STRAT_TYPE_CRISTAL_DIE, IN_PROGRESS);
            if self.strat_get_data(STRAT_TYPE_CRISTAL_ALL_DIE) == Some(DONE) {
                self.do_script_text(CRISTAL_SAY_ALL_CRYSTALS_DESTROYED, pop, None, -1);
            }
        }
