    fn blaumeux_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let is_spirit = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Blaumeux(s)) => Some(s.is_spirit),
                _ => None,
            })
            .unwrap_or(false);
        // 74yd pull scan + kill-say decay (fork runs both every
        // update, cpp 344).
        let pull = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Blaumeux(s)) => {
                    Some((s.pull_check_ms, s.kill_say_cooldown_ms))
                }
                _ => None,
            })
            .unwrap_or((1000, 0));
        let next_pull = self.hm4_aggro_radius(guid, pull.0, diff_ms);
        if let Some(s) = self.blaumeux_state_mut(guid) {
            s.pull_check_ms = next_pull;
            s.kill_say_cooldown_ms = pull.1.saturating_sub(diff_ms);
        }
        if !is_spirit {
            let Some(_victim) = self.script_combat_drive(guid, true) else {
                return;
            };
            if self.should_leash_evade(guid) {
                return;
            }
        }
        let (mut mark, mut sw1, mut sw2, mut swt) = (0, false, false, 0);
        if let Some(s) = self.blaumeux_state_mut(guid) {
            mark = s.mark_timer_ms;
            sw1 = s.shield_wall_1;
            sw2 = s.shield_wall_2;
            swt = s.shield_wall_timer_ms;
        }
        self.hm4_shared_update(
            guid,
            diff_ms,
            BLAU_SPELL_MARK_OF_BLAUMEUX,
            &mut mark,
            &mut sw1,
            &mut sw2,
            &mut swt,
        );
        if let Some(s) = self.blaumeux_state_mut(guid) {
            s.mark_timer_ms = mark;
            s.shield_wall_1 = sw1;
            s.shield_wall_2 = sw2;
            s.shield_wall_timer_ms = swt;
        }
        // Void zone (EVENT_BOSS_ABILITY, 12s).
        let ability_due = {
            let Some(s) = self.blaumeux_state_mut(guid) else {
                return;
            };
            if is_spirit {
                false
            } else if s.ability_timer_ms < diff_ms {
                true
            } else {
                s.ability_timer_ms = s.ability_timer_ms.saturating_sub(diff_ms);
                false
            }
        };
        if ability_due {
            // NEEDS-MAP-HELPER: fork targets
            // `SelectAttackingTarget(RANDOM, 0, SPELL_VOIDZONE,
            // SELECT_FLAG_IN_LOS | SELECT_FLAG_PLAYER)`, floors
            // the height via map `GetHeight` (min 241.35), and
            // summons `NPC_VOID_ZONE` (16697) with
            // wander/random-motion + 0.1 run/walk speed.
            if self.do_cast_spell_if_can(guid, BLAU_SPELL_VOIDZONE, CastTarget::SelfCast) {
                self.do_script_text(BLAU_SAY_SPECIAL, guid, None, -1);
                if let Some(s) = self.blaumeux_state_mut(guid) {
                    s.ability_timer_ms = 12_000;
                }
            } else if let Some(s) = self.blaumeux_state_mut(guid) {
                s.ability_timer_ms = 100;
            }
        }
    }

