    fn gothik_open_the_gate(&mut self, guid: ObjectGuid) {
        let opened = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Gothik(s)) => Some(s.gates_opened),
                _ => None,
            })
            .unwrap_or(true);
        if opened {
            return;
        }
        self.do_script_text(GOTH_EMOTE_GATE, guid, None, -1);
        if let Some(s) = self.gothik_state_mut(guid) {
            s.gates_opened = true;
        }
        // NEEDS-MAP-HELPER: instance combat-gate GO lookup
        // (`GetSingleGameObjectFromStorage(GO_MILI_GOTH_COMBAT_GATE)`);
        // gate state write once resolved:
        // `object_set_field(go, GAMEOBJECT_STATE, GO_STATE_ACTIVE)`.
        let me = self.unit_position(guid).unwrap_or_default();
        let entries = [
            GOTH_NPC_UNREL_TRAINEE,
            GOTH_NPC_UNREL_DEATH_KNIGHT,
            GOTH_NPC_UNREL_RIDER,
            GOTH_NPC_SPECT_TRAINEE,
            GOTH_NPC_SPECT_DEATH_KNIGTH,
            GOTH_NPC_SPECT_RIDER,
            GOTH_NPC_SPECT_HORSE,
        ];
        let mut adds: Vec<ObjectGuid> = Vec::new();
        for (g, c) in &self.creatures {
            if !entries.contains(&c.info.entry) {
                continue;
            }
            if let Some(p) = self.object_position(*g) {
                let dx = p.x - me.x;
                let dy = p.y - me.y;
                if dx * dx + dy * dy <= 300.0 * 300.0 {
                    adds.push(*g);
                }
            }
        }
        for a in adds {
            self.set_in_combat_with_zone(a);
        }
    }

    fn gothik_has_less_players_per_side(&mut self, guid: ObjectGuid, count: u32) -> bool {
        // NEEDS-MAP-HELPER: needs the combat-gate GO position
        // (`GetSingleGameObjectFromStorage`), feign-death and
        // 100yd/gate-band exclusions (cpp 330-365). Player
        // count per side is approximated from known players.
        let _ = guid;
        let mut n = 0u32;
        let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
        for p in players {
            if self.unit_is_alive(p) {
                n += 1;
            }
        }
        n < count
    }

    fn gothik_reset_threat_and_attack_nearest(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: `DoResetThreat` + nearest
        // in-LOS target `AttackStart` + 300 threat (cpp
        // 573-581). Random-hostile approximation:
        let target = self.select_random_hostile(guid);
        if let Some(t) = target {
            self.attack_start(guid, t);
            self.add_threat(guid, t, 300.0);
        }
    }

    #[allow(clippy::too_many_lines)]
    fn gothik_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Aura-gated head (cpp 367-382): immune -> threat-empty
        // evade; corporeal -> normal drive + leash.
        let immune = self.unit_has_aura(guid, GOTH_SPELL_IMMUNE_ALL);
        if immune {
            if self.threat_targets_sorted(guid).is_empty() {
                self.enter_evade_mode(guid);
            }
        } else {
            let Some(_victim) = self.script_combat_drive(guid, true) else {
                return;
            };
            // NEEDS-MAP-HELPER: `HandleEvadeOutOfHome` gate.
            if self.should_leash_evade(guid) {
                return;
            }
        }
        let phase = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Gothik(s)) => Some(s.phase),
                _ => None,
            })
            .unwrap_or(GOTH_PHASE_SPEECH);
        match phase {
            GOTH_PHASE_SPEECH => {
                let due = {
                    let Some(s) = self.gothik_state_mut(guid) else {
                        return;
                    };
                    if s.speech_timer_ms < diff_ms {
                        true
                    } else {
                        s.speech_timer_ms -= diff_ms;
                        false
                    }
                };
                if !due {
                    return;
                }
                if self.gothik_has_less_players_per_side(guid, 10) {
                    self.enter_evade_mode(guid);
                    return;
                }
                if let Some(s) = self.gothik_state_mut(guid) {
                    s.speech_timer_ms = 5000;
                    s.speech_count = s.speech_count.saturating_add(1);
                }
                let count = self
                    .ai
                    .get(&guid)
                    .and_then(|ai| match &ai.script {
                        Some(CreatureScriptAi::Gothik(s)) => Some(s.speech_count),
                        _ => None,
                    })
                    .unwrap_or(0);
                match count {
                    1 => self.do_script_text(GOTH_SAY_SPEECH_2, guid, None, -1),
                    2 => self.do_script_text(GOTH_SAY_SPEECH_3, guid, None, -1),
                    3 => self.do_script_text(GOTH_SAY_SPEECH_4, guid, None, -1),
                    _ => {
                        if let Some(s) = self.gothik_state_mut(guid) {
                            s.phase = GOTH_PHASE_BALCONY;
                        }
                    }
                }
            }
            GOTH_PHASE_BALCONY => {
                let due = {
                    let Some(s) = self.gothik_state_mut(guid) else {
                        return;
                    };
                    if s.summon_timer_ms < diff_ms {
                        true
                    } else {
                        s.summon_timer_ms -= diff_ms;
                        false
                    }
                };
                if !due {
                    return;
                }
                let count = self
                    .ai
                    .get(&guid)
                    .and_then(|ai| match &ai.script {
                        Some(CreatureScriptAi::Gothik(s)) => Some(s.summon_count),
                        _ => None,
                    })
                    .unwrap_or(0);
                if count >= GOTH_MAX_WAVES {
                    self.do_script_text(GOTH_SAY_TELEPORT, guid, None, -1);
                    self.do_script_text(GOTH_EMOTE_TO_FRAY, guid, None, -1);
                    if self.do_cast_spell_if_can(
                        guid,
                        GOTH_SPELL_TELEPORT_RIGHT,
                        CastTarget::SelfCast,
                    ) {
                        if let Some(s) = self.gothik_state_mut(guid) {
                            s.just_teleported = true;
                        }
                        // NEEDS-MAP-HELPER: `SetTempPacified(1200)`.
                        if self.gothik_has_less_players_per_side(guid, 1) {
                            self.gothik_open_the_gate(guid);
                        } else {
                            // gates already open; nothing to do.
                        }
                        self.remove_auras_due_to_spell(guid, GOTH_SPELL_IMMUNE_ALL);
                        if let Some(s) = self.gothik_state_mut(guid) {
                            s.phase = GOTH_PHASE_GROUND;
                        }
                    }
                    return;
                }
                // NEEDS-MAP-HELPER: wave summons resolve trigger
                // positions (`gothik_summon_adds`); wave table:
                let wave = GOTH_WAVES[count as usize];
                for e in [wave[0], wave[1], wave[2]] {
                    if e != 0 {
                        self.gothik_summon_add(guid, e, 0.0, 0.0, 0.0, 0.0);
                    }
                }
                // `m_uiSummonTimer += wave[3] - diff` (fork keeps
                // overshoot; saturating add approximates).
                if let Some(s) = self.gothik_state_mut(guid) {
                    s.summon_timer_ms = s
                        .summon_timer_ms
                        .saturating_add(wave[3].saturating_sub(diff_ms));
                    s.summon_count = s.summon_count.saturating_add(1);
                }
            }
            _ => {
                // PHASE_GROUND.
                let just_tp = {
                    let Some(s) = self.gothik_state_mut(guid) else {
                        return;
                    };
                    if s.just_teleported {
                        s.just_teleported = false;
                        true
                    } else {
                        false
                    }
                };
                if just_tp {
                    // NEEDS-MAP-HELPER: `IsInRightSideGothArea`
                    // side latch.
                    self.gothik_reset_threat_and_attack_nearest(guid);
                }
                // Cross-side threat wipe (cpp 476-486).
                // NEEDS-MAP-HELPER: victim side comparison via
                // `IsInRightSideGothArea`; approximated as a
                // no-op here except the structure:
                let gates_opened = self
                    .ai
                    .get(&guid)
                    .and_then(|ai| match &ai.script {
                        Some(CreatureScriptAi::Gothik(s)) => Some(s.gates_opened),
                        _ => None,
                    })
                    .unwrap_or(true);
                if !gates_opened {
                    if self.creature_health_percent(guid) < 30.0 {
                        self.gothik_open_the_gate(guid);
                    }
                    let check_due = {
                        let Some(s) = self.gothik_state_mut(guid) else {
                            return;
                        };
                        if s.check_side_timer_ms < diff_ms {
                            s.check_side_timer_ms = 1000;
                            true
                        } else {
                            s.check_side_timer_ms -= diff_ms;
                            false
                        }
                    };
                    if check_due && self.gothik_has_less_players_per_side(guid, 1) {
                        self.gothik_open_the_gate(guid);
                    }
                    let tp_due = {
                        let Some(s) = self.gothik_state_mut(guid) else {
                            return;
                        };
                        if s.teleport_timer_ms < diff_ms {
                            true
                        } else {
                            s.teleport_timer_ms -= diff_ms;
                            false
                        }
                    };
                    if tp_due {
                        // NEEDS-MAP-HELPER: side-dependent
                        // teleport spell + pacify/cleartarget/stop
                        // + `just_teleported` latch (cpp 503-522).
                        if self.do_cast_spell_if_can(
                            guid,
                            GOTH_SPELL_TELEPORT_LEFT,
                            CastTarget::SelfCast,
                        ) {
                            let next = self.rng.urand(15_000, 20_000);
                            if let Some(s) = self.gothik_state_mut(guid) {
                                s.teleport_timer_ms = next;
                                s.shadowbolt_timer_ms = 1000;
                                s.teleport_cast_delay_ms = 300;
                                s.num_tp += 1;
                                s.just_teleported = true;
                                if s.num_tp >= 4 {
                                    // Gate opens from here; the
                                    // borrow ends before the call.
                                }
                            }
                            let open_at_four = self
                                .ai
                                .get(&guid)
                                .and_then(|ai| match &ai.script {
                                    Some(CreatureScriptAi::Gothik(s)) => {
                                        Some(s.num_tp >= 4 && !s.gates_opened)
                                    }
                                    _ => None,
                                })
                                .unwrap_or(false);
                            if open_at_four {
                                self.gothik_open_the_gate(guid);
                            }
                        }
                    }
                    // Teleport-proximity cast delay (cpp 534-535).
                    let tp_close = self
                        .ai
                        .get(&guid)
                        .and_then(|ai| match &ai.script {
                            Some(CreatureScriptAi::Gothik(s)) => Some(s.teleport_timer_ms <= 3000),
                            _ => None,
                        })
                        .unwrap_or(false);
                    if tp_close {
                        if let Some(s) = self.gothik_state_mut(guid) {
                            s.teleport_cast_delay_ms = 3000;
                        }
                    }
                }
                // Shadowbolt / Harvest Soul under the cast delay.
                let delay_ready = {
                    let Some(s) = self.gothik_state_mut(guid) else {
                        return;
                    };
                    if s.teleport_cast_delay_ms <= diff_ms {
                        true
                    } else {
                        s.teleport_cast_delay_ms -= diff_ms;
                        false
                    }
                };
                if delay_ready {
                    let sb_due = {
                        let Some(s) = self.gothik_state_mut(guid) else {
                            return;
                        };
                        if s.shadowbolt_timer_ms <= diff_ms {
                            true
                        } else {
                            s.shadowbolt_timer_ms -= diff_ms;
                            false
                        }
                    };
                    if sb_due {
                        // NEEDS-MAP-HELPER: fork targets
                        // `SelectAttackingTarget(RANDOM, 0,
                        // SPELL_SHADOWBOLT, SELECT_FLAG_IN_LOS)`.
                        if self.do_cast_spell_if_can(
                            guid,
                            GOTH_SPELL_SHADOWBOLT,
                            CastTarget::SelfCast,
                        ) {
                            let next = self.rng.urand(1600, 2000);
                            if let Some(s) = self.gothik_state_mut(guid) {
                                s.shadowbolt_timer_ms = next;
                            }
                        }
                    }
                    let hs_due = {
                        let Some(s) = self.gothik_state_mut(guid) else {
                            return;
                        };
                        if s.harvest_soul_timer_ms <= diff_ms {
                            true
                        } else {
                            s.harvest_soul_timer_ms -= diff_ms;
                            false
                        }
                    };
                    if hs_due
                        && self.do_cast_spell_if_can(
                            guid,
                            GOTH_SPELL_HARVESTSOUL,
                            CastTarget::SelfCast,
                        )
                    {
                        if let Some(s) = self.gothik_state_mut(guid) {
                            s.harvest_soul_timer_ms = 20_000;
                            if s.teleport_timer_ms <= 1000 {
                                s.teleport_timer_ms += 1200;
                            }
                        }
                    }
                }
            }
        }
    }

