    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn kt_p1_attack_start(&mut self, guid: ObjectGuid, who: ObjectGuid, has_aggroed: bool) -> bool {
        // Returns true when the engine attack proceeds (fork
        // `ScriptedAI::AttackStart`).
        // NEEDS-MAP-HELPER: fork gates the latch-attack on
        // 30yd 2D proximity (`ALCOVE_ADD_PULL_RADIUS`); the
        // distance check below approximates it.
        if has_aggroed {
            self.attack_start(guid, who);
            return true;
        }
        let close = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy < KT_ALCOVE_ADD_PULL_RADIUS * KT_ALCOVE_ADD_PULL_RADIUS
            }
            _ => false,
        };
        if close {
            self.kt_p1_actual_attack(guid, who);
            true
        } else {
            false
        }
    }

