    // ---- boss_kelthuzad (`boss_kelthuzadAI`, cpp 209-781) ----
    fn kelthuzad_reset(&mut self, guid: ObjectGuid) {
        let max_hp = self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXHEALTH);
        let _ = self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_HEALTH), max_hp);
        self.remove_auras_due_to_spell(guid, KT_SPELL_VISUAL_CHANNEL);
        // `SetFlag(IMMUNE_TO_PLAYER | NOT_SELECTABLE)` (cpp 257).
        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_FLAGS),
            flags | KT_UNIT_FLAG_IMMUNE_TO_PLAYER | KT_UNIT_FLAG_NOT_SELECTABLE,
        );
        if let Some(s) = self.kelthuzad_state_mut(guid) {
            s.enrage_timer_ms = 1_140_000;
            s.num_skeletons = 0;
            s.abom_spawn_idx = 0;
            s.soul_spawn_idx = 0;
            s.p3_started = false;
            s.num_summoned_guardians = 0;
            s.time_since_last_frost_blast_ms = 0;
            s.time_since_last_shadow_fissure_ms = 0;
            s.time_since_last_ae_frost_bolt_ms = 0;
            s.kill_say_timer_ms = 0;
            s.has_put_in_combat = false;
        }
        // NEEDS-MAP-HELPER: `EvadeAllGuardians` needs the
        // guardian guids (stored in state once the integrator
        // wires cross-AI reads); gameobject portal spawn /
        // scale / map re-add (cpp 261-274) and the intro-add
        // despawn list likewise need map GO helpers.
    }

