    fn maggot_move_in_line_of_sight_inner(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        // 1.5yd custom pull (cpp 76-97).
        // NEEDS-MAP-HELPER: `CanInitiateAttack`,
        // `IsTargetableBy`, `IsHostileTo`,
        // `IsInAccessablePlaceFor`, LOS, dungeon threat path.
        let dist_ok = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy <= 1.5 * 1.5
            }
            _ => false,
        };
        if dist_ok && !self.ai_in_combat(guid) {
            self.attack_start(guid, who);
        }
    }

