    fn maggot_update_inner(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let diseased = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::RottingMaggot(s) | CreatureScriptAi::DiseasedMaggot(s)) => {
                    Some(s.is_diseased)
                }
                _ => None,
            })
            .unwrap_or(false);
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        if diseased && !self.unit_has_aura(guid, MAGGOT_SPELL_RETCHING_PLAGUE) {
            self.do_cast_spell_if_can(guid, MAGGOT_SPELL_RETCHING_PLAGUE, CastTarget::SelfCast);
        }
        // 40yd leash to the aggro spot (cpp 114-121).
        let anchored = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::RottingMaggot(s) | CreatureScriptAi::DiseasedMaggot(s)) => {
                    Some((s.aggro_position, s.has_aggro_position))
                }
                _ => None,
            })
            .unwrap_or((Position::default(), false));
        if anchored.1 {
            if let Some(me) = self.unit_position(guid) {
                let dx = me.x - anchored.0.x;
                let dy = me.y - anchored.0.y;
                if dx * dx + dy * dy > 40.0 * 40.0 {
                    self.enter_evade_mode(guid);
                    return;
                }
            }
        }
        let _ = diff_ms;
    }

    // ---- mob_eyeStalkAI (cpp 125-201) ----
    fn eye_stalk_reset(&mut self, guid: ObjectGuid) {
        // `AddUnitState(ROOT)` + stop + `SetRooted(true)` (cpp
        // 142-147); root gates motion per the herod pattern.
        if let Some(u) = self.unit_base_mut(guid) {
            u.add_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
        }
        self.stop_moving(guid);
        if let Some(s) = self.eye_stalk_state_mut(guid) {
            s.time_since_spawn_ms = 0;
            s.have_submerged = false;
            s.have_cast_submerge = false;
        }
        // NEEDS-MAP-HELPER: `SetRooted(true)`,
        // `SetNoCallAssistance(true)`.
    }

    fn eye_stalk_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        // 3s arming + 19yd pull (cpp 149-171).
        // NEEDS-MAP-HELPER: hostility/LOS/accessible/dungeon
        // gates.
        let armed = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::EyeStalk(s)) => Some(s.time_since_spawn_ms >= 3000),
                _ => None,
            })
            .unwrap_or(false);
        if !armed {
            return;
        }
        let dist_ok = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy <= 19.0 * 19.0
            }
            _ => false,
        };
        if dist_ok && !self.ai_in_combat(guid) {
            self.attack_start(guid, who);
        }
    }

    fn eye_stalk_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // NEEDS-MAP-HELPER: `SetNoCallAssistance(true)` per
        // tick (cpp 175) unmodeled.
        // Fork `+= min(diff, u32::MAX - t)` (cpp 176).
        if let Some(s) = self.eye_stalk_state_mut(guid) {
            s.time_since_spawn_ms = s.time_since_spawn_ms.saturating_add(diff_ms);
        }
        let (submerged, cast_submerge) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::EyeStalk(s)) => {
                    Some((s.have_submerged, s.have_cast_submerge))
                }
                _ => None,
            })
            .unwrap_or((true, true));
        if submerged {
            if !cast_submerge {
                if let Some(s) = self.eye_stalk_state_mut(guid) {
                    s.have_cast_submerge = true;
                }
                self.do_cast_spell_if_can(guid, ESTALK_SPELL_SUBMERGE, CastTarget::SelfCast);
            }
            return;
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // NEEDS-MAP-HELPER: `IsNonMeleeSpellCasted` gate +
        // 35yd mind-flay range + `DoStopAttack` fallback (cpp
        // 192-197).
        if self.do_cast_spell_if_can(guid, ESTALK_SPELL_MIND_FLAY, CastTarget::Unit(victim)) {
            // Single-shot per combat pass; fork re-checks range
            // every tick.
        }
    }

    // ---- boss_maexxna (`boss_maexxnaAI`, cpp 141-408) ----
    fn maexxna_reset(&mut self, guid: ObjectGuid) {
        // `NecroticPoisonCooldown(true)` is a flat 15s (cpp
        // 74); only the shock roll is RNG here.
        let poison = self.rng.urand(9000, 11_000);
        if let Some(s) = self.maexxna_state_mut(guid) {
            s.web_wrap_timer_ms = 20_000;
            s.web_spray_timer_ms = 40_000;
            s.poison_shock_timer_ms = poison;
            s.necrotic_poison_timer_ms = 15_000;
            s.summon_spiderling_timer_ms = 30_000;
            s.enraged = false;
            s.wraps.clear();
            s.wraps2.clear();
        }
        let _ = guid;
    }

    fn maexxna_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        self.instance_set_data(NAX_TYPE_MAEXXNA, IN_PROGRESS);
        let _ = guid;
    }

    fn maexxna_just_died(&mut self, guid: ObjectGuid) {
        self.instance_set_data(NAX_TYPE_MAEXXNA, DONE);
        let _ = guid;
    }

    fn maexxna_just_reached_home(&mut self, guid: ObjectGuid) {
        self.instance_set_data(NAX_TYPE_MAEXXNA, NAX_FAIL);
        // Despawn spiderlings in 100yd (cpp 213-218).
        let me = self.unit_position(guid).unwrap_or_default();
        let mut adds: Vec<ObjectGuid> = Vec::new();
        for (g, c) in &self.creatures {
            if c.info.entry != MAEX_NPC_SPIDERLING {
                continue;
            }
            if let Some(p) = self.object_position(*g) {
                let dx = p.x - me.x;
                let dy = p.y - me.y;
                if dx * dx + dy * dy <= 100.0 * 100.0 {
                    adds.push(*g);
                }
            }
        }
        for a in adds {
            self.despawn_creature_now(a, 0);
        }
    }

    fn maexxna_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        // 40yd custom pull (cpp 190-208).
        // NEEDS-MAP-HELPER: LOS/accessible/hostility/dungeon
        // gates.
        let dist_ok = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy <= 40.0 * 40.0
            }
            _ => false,
        };
        if dist_ok && !self.ai_in_combat(guid) {
            self.attack_start(guid, who);
        }
    }

    fn maexxna_just_summoned(&mut self, guid: ObjectGuid, created: ObjectGuid) {
        if self.creatures.get(&created).map(|c| c.info.entry) != Some(MAEX_NPC_SPIDERLING) {
            return;
        }
        // NEEDS-MAP-HELPER: fork `AddThreat`s 100 and
        // `AttackStart`s a random target (cpp 289-297).
        let _ = guid;
    }

    fn maexxna_cast_web_wrap(&mut self, guid: ObjectGuid) -> bool {
        // Skip tank; wrap up to 3 alive, unwrapped players in
        // LOS (cpp 220-285).
        // NEEDS-MAP-HELPER: raw-threat-list iteration (skip
        // first), player-type + alive + aura + LOS filtering,
        // `SetLaunched` anticheat flag, `KnockBack` physics.
        let list = self.threat_targets_sorted(guid);
        if list.len() < 2 {
            return false;
        }
        let mut candidates: Vec<ObjectGuid> = Vec::new();
        for t in list.into_iter().skip(1) {
            if self.players.contains_key(&t)
                && self.unit_is_alive(t)
                && !self.unit_has_aura(t, MAEX_SPELL_WEBWRAP)
            {
                candidates.push(t);
            }
        }
        if candidates.is_empty() {
            return false;
        }
        // Fisher-Yates over the 8 wrap points.
        let mut locs = MAEX_WEB_WRAP_LOCS.to_vec();
        for i in (1..locs.len()).rev() {
            let j = usize::try_from(self.rng.urand(0, u32::try_from(i).unwrap_or(u32::MAX)))
                .unwrap_or(0);
            locs.swap(i, j);
        }
        for wrap_loc in locs.iter().take(3) {
            if candidates.is_empty() {
                break;
            }
            let pick = if candidates.len() > 1 {
                self.rng.urand(
                    0,
                    u32::try_from(candidates.len())
                        .unwrap_or(1)
                        .saturating_sub(1),
                ) as usize
            } else {
                0
            };
            let target = candidates.remove(pick);
            if let Some(s) = self.maexxna_state_mut(guid) {
                s.wraps.push((2000, target));
            }
            let _ = wrap_loc;
            // NEEDS-MAP-HELPER: knockback toward the wrap point
            // (horizontal/vertical speed math, cpp 261-279).
        }
        true
    }

    fn maexxna_update_wraps(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Two-stage wrap pipeline (cpp 299-342; fork clears the
        // whole stage vector when any entry fires — kept).
        let stage2: Vec<(u32, ObjectGuid)> = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Maexxna(s)) => Some(s.wraps2.clone()),
                _ => None,
            })
            .unwrap_or_default();
        let mut fired2 = false;
        let mut keep2: Vec<(u32, ObjectGuid)> = Vec::new();
        for (t, p) in stage2 {
            if t < diff_ms {
                // NEEDS-MAP-HELPER: fork summons `NPC_WEB_WRAP`
                // (16486) at the player and calls the webwrap AI's
                // `SetVictim` (aura + fly-to-player motion).
                let _ = p;
                fired2 = true;
            } else {
                keep2.push((t.saturating_sub(diff_ms), p));
            }
        }
        if let Some(s) = self.maexxna_state_mut(guid) {
            s.wraps2 = if fired2 { Vec::new() } else { keep2 };
        }
        let stage1: Vec<(u32, ObjectGuid)> = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Maexxna(s)) => Some(s.wraps.clone()),
                _ => None,
            })
            .unwrap_or_default();
        let mut fired1 = false;
        let mut keep1: Vec<(u32, ObjectGuid)> = Vec::new();
        for (t, p) in stage1 {
            if t < diff_ms {
                if self.players.contains_key(&p) {
                    self.do_cast_spell_if_can(p, MAEX_SPELL_WEBWRAP, CastTarget::Unit(p));
                    if let Some(s) = self.maexxna_state_mut(guid) {
                        s.wraps2.push((3000, p));
                    }
                }
                fired1 = true;
            } else {
                keep1.push((t.saturating_sub(diff_ms), p));
            }
        }
        if let Some(s) = self.maexxna_state_mut(guid) {
            s.wraps = if fired1 { Vec::new() } else { keep1 };
        }
    }

    #[allow(clippy::too_many_lines)]
    fn maexxna_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        self.maexxna_update_wraps(guid, diff_ms);
        // Web Wrap (always re-armed, even on failure).
        let due = {
            let Some(s) = self.maexxna_state_mut(guid) else {
                return;
            };
            if s.web_wrap_timer_ms < diff_ms {
                true
            } else {
                s.web_wrap_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            self.maexxna_cast_web_wrap(guid);
            if let Some(s) = self.maexxna_state_mut(guid) {
                s.web_wrap_timer_ms = 40_000;
            }
        }
        // Web Spray.
        let due = {
            let Some(s) = self.maexxna_state_mut(guid) else {
                return;
            };
            if s.web_spray_timer_ms < diff_ms {
                true
            } else {
                s.web_spray_timer_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, MAEX_SPELL_WEBSPRAY, CastTarget::Unit(victim)) {
            if let Some(s) = self.maexxna_state_mut(guid) {
                s.web_spray_timer_ms = 40_000;
            }
        }
        // Poison Shock.
        let due = {
            let Some(s) = self.maexxna_state_mut(guid) else {
                return;
            };
            if s.poison_shock_timer_ms < diff_ms {
                true
            } else {
                s.poison_shock_timer_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, MAEX_SPELL_POISONSHOCK, CastTarget::Unit(victim))
        {
            let next = self.rng.urand(9000, 11_000);
            if let Some(s) = self.maexxna_state_mut(guid) {
                s.poison_shock_timer_ms = next;
            }
        }
        // Necrotic Poison.
        let due = {
            let Some(s) = self.maexxna_state_mut(guid) else {
                return;
            };
            if s.necrotic_poison_timer_ms < diff_ms {
                true
            } else {
                s.necrotic_poison_timer_ms -= diff_ms;
                false
            }
        };
        if due
            && self.do_cast_spell_if_can(guid, MAEX_SPELL_NECROTICPOISON, CastTarget::Unit(victim))
        {
            let next = self.rng.urand(5000, 10_000);
            if let Some(s) = self.maexxna_state_mut(guid) {
                s.necrotic_poison_timer_ms = next;
            }
        }
        // Summon Spiderling.
        let due = {
            let Some(s) = self.maexxna_state_mut(guid) else {
                return;
            };
            if s.summon_spiderling_timer_ms < diff_ms {
                true
            } else {
                s.summon_spiderling_timer_ms -= diff_ms;
                false
            }
        };
        if due
            && self.do_cast_spell_if_can(guid, MAEX_SPELL_SUMMON_SPIDERLING, CastTarget::SelfCast)
        {
            if let Some(s) = self.maexxna_state_mut(guid) {
                s.summon_spiderling_timer_ms = 40_000;
            }
        }
        // Enrage below 30%.
        let enraged = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Maexxna(s)) => Some(s.enraged),
                _ => None,
            })
            .unwrap_or(true);
        if !enraged
            && self.creature_health_percent(guid) < 30.0
            && self.do_cast_spell_if_can(guid, MAEX_SPELL_ENRAGE, CastTarget::SelfCast)
        {
            self.do_script_text(MAEX_EMOTE_BOSS_GENERIC_ENRAGE, guid, None, -1);
            if let Some(s) = self.maexxna_state_mut(guid) {
                s.enraged = true;
            }
        }
    }

    // ---- mob_webwrapAI (cpp 76-139) ----
    // MoveInLineOfSight/AttackStart are fork noops.
    fn webwrap_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.webwrap_state_mut(guid) {
            // `m_uiWebWrapTimer`/`webWrapDone` (cpp 84-88) are
            // write-only in fork; only the victim latch is kept.
            s.victim_guid = ObjectGuid::EMPTY;
            s.has_victim = false;
        }
        let _ = guid;
    }

    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn webwrap_set_victim(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        // NOT a CreatureAI hook; called from
        // `maexxna_update_wraps` stage 2.
        // NEEDS-MAP-HELPER: `AddAura(SPELL_SUMMON_WEB_WRAP)`
        // on the player + `MovePoint(0, pos, FLY|CYCLIC)`
        // pursuit motion (cpp 94-104).
        if let Some(s) = self.webwrap_state_mut(guid) {
            s.victim_guid = victim;
            s.has_victim = true;
        }
    }

    fn webwrap_just_died(&mut self, guid: ObjectGuid) {
        // Frees the wrapped player (cpp 106-120).
        let victim = self.ai.get(&guid).and_then(|ai| match &ai.script {
            Some(CreatureScriptAi::Webwrap(s)) => {
                if s.has_victim {
                    Some(s.victim_guid)
                } else {
                    None
                }
            }
            _ => None,
        });
        if let Some(p) = victim {
            if self.players.contains_key(&p) {
                self.remove_auras_due_to_spell(p, MAEX_SPELL_WEBWRAP);
                self.remove_auras_due_to_spell(p, MAEX_SPELL_SUMMON_WEB_WRAP);
            }
        }
        self.despawn_creature_now(guid, 0);
    }

    fn webwrap_update(&mut self, guid: ObjectGuid, _diff_ms: u32) {
        // Victim-dead check (cpp 122-138); the MovePoint upkeep
        // is commented out in fork.
        let victim = self.ai.get(&guid).and_then(|ai| match &ai.script {
            Some(CreatureScriptAi::Webwrap(s)) => {
                if s.has_victim {
                    Some(s.victim_guid)
                } else {
                    None
                }
            }
            _ => None,
        });
        let Some(p) = victim else { return };
        let dead = !self.unit_is_alive(p);
        let gone = !self.players.contains_key(&p);
        if dead || gone {
            // `Kill(m_creature)` self-kill (cpp 130) → despawn.
            self.despawn_creature_now(guid, 0);
        }
    }

