    fn razuvious_rp_buddy(&mut self, guid: ObjectGuid) -> Option<ObjectGuid> {
        let buddy = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Razuvious(s)) => Some(s.rp_buddy),
                _ => None,
            })
            .unwrap_or(ObjectGuid::EMPTY);
        if buddy == ObjectGuid::EMPTY || !self.creatures.contains_key(&buddy) {
            None
        } else {
            Some(buddy)
        }
    }

    fn razuvious_update_rp(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // NEEDS-MAP-HELPER: every arm below needs facing/emote
        // helpers: `SetFacingToObject`,
        // `HandleEmote(EXCLAMATION/TALK/SALUTE/STAND/READY1H)`
        // numeric ids, the understudy cross-AI latch
        // (`attack_timer_ms`/`run_attack` via the matching
        // `DkUnderstudy` accessor — readable), and the
        // 16211-anchor creature search (cpp 244-301).
        let fire = |pending: bool, timer: u32| pending && timer <= diff_ms;
        let buddy = self.razuvious_rp_buddy(guid);
        // TURN_TO_TRAINEE.
        let go = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Razuvious(s)) => Some(fire(
                    s.rp_turn_to_trainee_pending,
                    s.rp_turn_to_trainee_timer_ms,
                )),
                _ => None,
            })
            .unwrap_or(false);
        if go {
            if let Some(s) = self.razuvious_state_mut(guid) {
                s.rp_turn_to_trainee_pending = false;
            }
            let _ = buddy;
        }
        // Decrement pending RP timers.
        if let Some(s) = self.razuvious_state_mut(guid) {
            for (p, t) in [
                (
                    &mut s.rp_turn_to_trainee_pending,
                    &mut s.rp_turn_to_trainee_timer_ms,
                ),
                (
                    &mut s.rp_emote_shout_pending,
                    &mut s.rp_emote_shout_timer_ms,
                ),
                (&mut s.rp_add_turn_pending, &mut s.rp_add_turn_timer_ms),
                (&mut s.rp_add_talk_pending, &mut s.rp_add_talk_timer_ms),
                (&mut s.rp_add_salute_pending, &mut s.rp_add_salute_timer_ms),
                (
                    &mut s.rp_add_turn_back_pending,
                    &mut s.rp_add_turn_back_timer_ms,
                ),
                (&mut s.rp_add_attack_pending, &mut s.rp_add_attack_timer_ms),
            ] {
                if *p {
                    *t = t.saturating_sub(diff_ms);
                }
            }
            // ADD_TURN latches the buddy understudy out of its
            // attack emote (cpp 261-270); ADD_ATTACK restores it
            // (cpp 289-299).
            if s.rp_add_turn_pending && s.rp_add_turn_timer_ms == 0 {
                s.rp_add_turn_pending = false;
            }
            if s.rp_emote_shout_pending && s.rp_emote_shout_timer_ms == 0 {
                s.rp_emote_shout_pending = false;
            }
            if s.rp_add_talk_pending && s.rp_add_talk_timer_ms == 0 {
                s.rp_add_talk_pending = false;
            }
            if s.rp_add_salute_pending && s.rp_add_salute_timer_ms == 0 {
                s.rp_add_salute_pending = false;
            }
            if s.rp_add_turn_back_pending && s.rp_add_turn_back_timer_ms == 0 {
                s.rp_add_turn_back_pending = false;
            }
            if s.rp_add_attack_pending && s.rp_add_attack_timer_ms == 0 {
                s.rp_add_attack_pending = false;
            }
        }
        // The buddy latch itself (`attack_timer_ms` /
        // `run_attack` on the buddy's `DkUnderstudy` state via
        // its AI accessor) is readable; the facing/emote half
        // of each arm is NEEDS-MAP-HELPER as noted above.
        let _ = buddy;
    }

    fn razuvious_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if !self.ai_in_combat(guid) {
            self.razuvious_update_rp(guid, diff_ms);
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // NEEDS-MAP-HELPER: `HandleEvadeOutOfHome` gate.
        if self.should_leash_evade(guid) {
            return;
        }
        // Unbalancing Strike.
        let due = {
            let Some(s) = self.razuvious_state_mut(guid) else {
                return;
            };
            if s.unbalancing_strike_timer_ms < diff_ms {
                true
            } else {
                s.unbalancing_strike_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            self.do_cast_spell_if_can(guid, RAZ_SPELL_UNBALANCING_STRIKE, CastTarget::Unit(victim));
            if let Some(s) = self.razuvious_state_mut(guid) {
                s.unbalancing_strike_timer_ms = 30_000;
            }
        }
        // Disrupting Shout.
        let due = {
            let Some(s) = self.razuvious_state_mut(guid) else {
                return;
            };
            if s.disrupting_shout_timer_ms < diff_ms {
                true
            } else {
                s.disrupting_shout_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            self.do_cast_spell_if_can(guid, RAZ_SPELL_DISRUPTING_SHOUT, CastTarget::Unit(victim));
            self.do_script_text(RAZ_EMOTE_SHOUT, guid, None, -1);
            if let Some(s) = self.razuvious_state_mut(guid) {
                s.disrupting_shout_timer_ms = 25_000;
            }
        }
        // Command.
        let due = {
            let Some(s) = self.razuvious_state_mut(guid) else {
                return;
            };
            if s.command_timer_ms < diff_ms {
                true
            } else {
                s.command_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            let say = match self.rng.urand(0, 3) {
                0 => RAZ_SAY_COMMAND1,
                1 => RAZ_SAY_COMMAND2,
                2 => RAZ_SAY_COMMAND3,
                _ => RAZ_SAY_COMMAND4,
            };
            self.do_script_text(say, guid, None, -1);
            let next = self.rng.urand(30_000, 60_000);
            if let Some(s) = self.razuvious_state_mut(guid) {
                s.command_timer_ms = next;
            }
        }
    }

    // ---- boss_sapphiron (`boss_sapphironAI`, cpp 90-496) ----
    fn sapphiron_reset(&mut self, guid: ObjectGuid) {
        self.remove_auras_due_to_spell(guid, SAPP_SPELL_FROST_AURA);
        self.remove_auras_due_to_spell(guid, SAPP_AURA_STUN_IMMUNE_EXTRA);
        self.sapphiron_unsummon_wing_buffet(guid);
        self.sapphiron_delete_ice_blocks(guid);
        // NEEDS-MAP-HELPER: `setHover(false, onReset=true)` +
        // `SetCombatMovement(true)` (ai field write below).
        if let Some(ai) = self.ai.get_mut(&guid) {
            ai.combat_movement = true;
        }
        if let Some(s) = self.sapphiron_state_mut(guid) {
            s.phase = SAPP_PHASE_GROUND;
            s.berserk_timer_ms = 900_000;
            s.icebolt_count = 0;
            s.icebolt_targets.clear();
            s.wing_buffet_creature = ObjectGuid::EMPTY;
            s.force_target_update_timer_ms = 0;
            s.move_to_fly_timer_ms = 0;
            s.liftoff_timer_ms = 0;
            s.liftoff_pending = false;
            s.land_timer_ms = 0;
            s.land_pending = false;
            s.landed_timer_ms = 0;
            s.landed_pending = false;
            s.icebolt_timer_ms = 0;
            s.blizzard_timer_ms = 0;
            s.life_drain_timer_ms = 0;
            s.tail_sweep_timer_ms = 0;
            s.cleave_timer_ms = 0;
            s.frost_breath_dummy_timer_ms = 0;
            s.frost_breath_dummy_pending = false;
            s.frost_breath_cast_timer_ms = 0;
            s.frost_breath_cast_pending = false;
        }
        if self.instance_get_data(NAX_TYPE_SAPPHIRON) != Some(DONE) {
            self.instance_set_data(NAX_TYPE_SAPPHIRON, NAX_NOT_STARTED);
        }
    }

    fn sapphiron_unsummon_wing_buffet(&mut self, guid: ObjectGuid) {
        let buffet = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Sapphiron(s)) => Some(s.wing_buffet_creature),
                _ => None,
            })
            .unwrap_or(ObjectGuid::EMPTY);
        if buffet != ObjectGuid::EMPTY && self.creatures.contains_key(&buffet) {
            self.despawn_creature_now(buffet, 0);
        }
        if let Some(s) = self.sapphiron_state_mut(guid) {
            s.wing_buffet_creature = ObjectGuid::EMPTY;
        }
    }

