    // ---- boss_thaddiusAI (cpp 519-1007) ----
    fn thaddius_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.thaddius_state_mut(guid) {
            s.ball_lightning_timer_ms = 1000;
            s.phase = THAD_PHASE_NOT_STARTED;
            s.kill_say_cooldown_ms = 0;
            s.transition_step = 0;
            s.transition_timer_ms = 0;
            s.polarity_shift_timer_ms = 0;
            s.polarity_change_timer_ms = 0;
            s.polarity_change_pending = false;
            s.chain_lightning_timer_ms = 0;
            s.thaddius_berserk_timer_ms = 0;
        }
        // Ctor add/coil seeding (cpp 524-536) runs here when the
        // slots are empty and the encounter is not DONE.
        let empty = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Thaddius(s)) => Some(
                    s.add_guids == [ObjectGuid::EMPTY; 2] && s.coil_guids == [ObjectGuid::EMPTY; 2],
                ),
                _ => None,
            })
            .unwrap_or(false);
        if empty && self.instance_get_data(NAX_TYPE_THADDIUS) != Some(DONE) {
            self.thaddius_check_spawn_adds(guid);
        }
        if !self.unit_has_aura(guid, THAD_SPELL_THADIUS_SPAWN) {
            self.apply_aura_by_id(guid, THAD_SPELL_THADIUS_SPAWN, guid);
        }
        // Ctor `NOT_SELECTABLE` flag (cpp 536).
        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_FLAGS),
            flags | THAD_UNIT_FLAG_NOT_SELECTABLE,
        );
    }

    fn thaddius_just_reached_home(&mut self, guid: ObjectGuid) {
        self.instance_set_data(NAX_TYPE_THADDIUS, NAX_FAIL);
        self.thaddius_check_spawn_adds(guid);
        // NEEDS-MAP-HELPER: spawn aura re-apply +
        // `NOT_SELECTABLE` re-flag (cpp 708-712).
    }

    fn thaddius_killed_unit(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        if !self.players.contains_key(&victim) {
            return;
        }
        let ready = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Thaddius(s)) => Some(s.kill_say_cooldown_ms == 0),
                _ => None,
            })
            .unwrap_or(false);
        if ready {
            self.do_script_text(THAD_SAY_SLAY, guid, None, -1);
            if let Some(s) = self.thaddius_state_mut(guid) {
                s.kill_say_cooldown_ms = 5000;
            }
        }
    }

    fn thaddius_just_died(&mut self, guid: ObjectGuid) {
        self.do_script_text(THAD_SAY_DEATH, guid, None, -1);
        self.instance_set_data(NAX_TYPE_THADDIUS, DONE);
    }

    fn thaddius_handle_check_spawn_add(&mut self, guid: ObjectGuid, which: usize) {
        // Respawn the add + its tesla coil (cpp 557-607).
        let (add_guid, coil_guid) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Thaddius(s)) => {
                    Some((s.add_guids[which], s.coil_guids[which]))
                }
                _ => None,
            })
            .unwrap_or((ObjectGuid::EMPTY, ObjectGuid::EMPTY));
        if add_guid != ObjectGuid::EMPTY && self.creatures.contains_key(&add_guid) {
            self.despawn_creature_now(add_guid, 0);
        }
        let entry = if which == 0 {
            THAD_NPC_STALAGG
        } else {
            THAD_NPC_FEUGEN
        };
        let pos = THAD_ADD_POSITIONS[which];
        let new_add = self.summon_creature(
            entry,
            Position::new(pos[0], pos[1], pos[2], pos[3]),
            guid,
            THAD_TEMPSUMMON_MANUAL_DESPAWN,
            0,
        );
        if coil_guid != ObjectGuid::EMPTY && self.creatures.contains_key(&coil_guid) {
            self.despawn_creature_now(coil_guid, 0);
        }
        let coil_pos = THAD_TESLA_COIL_POSITIONS[which];
        let new_coil = self.summon_creature(
            THAD_NPC_TESLA_COIL,
            Position::new(coil_pos[0], coil_pos[1], coil_pos[2], 0.0),
            guid,
            THAD_TEMPSUMMON_MANUAL_DESPAWN,
            0,
        );
        // NEEDS-MAP-HELPER: tesla GO state ACTIVE
        // (`GetSingleGameObjectFromStorage` + `SetGoState`).
        if let (Some(a), Some(c)) = (new_add, new_coil) {
            if let Some(s) = self.thaddius_state_mut(guid) {
                s.add_guids[which] = a;
                s.coil_guids[which] = c;
            }
            // Chain the coil to its add (cpp 594-596).
            if let Some(ts) = self.tesla_coil_state_mut(c) {
                ts.linked_guid = a;
                ts.to_feugen = which == 1;
            }
            self.do_cast_spell_if_can(
                c,
                if which == 1 {
                    THAD_SPELL_FEUGEN_CHAIN
                } else {
                    THAD_SPELL_STALAGG_CHAIN
                },
                CastTarget::SelfCast,
            );
        }
    }

    fn thaddius_check_spawn_adds(&mut self, guid: ObjectGuid) {
        // Respawn both adds + coils; link the adds (cpp 609-628).
        if self.instance_get_data(NAX_TYPE_THADDIUS) == Some(DONE) {
            return;
        }
        self.thaddius_handle_check_spawn_add(guid, 0);
        self.thaddius_handle_check_spawn_add(guid, 1);
        // Link adds to each other (cpp 618-627).
        let adds = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Thaddius(s)) => Some(s.add_guids),
                _ => None,
            })
            .unwrap_or([ObjectGuid::EMPTY; 2]);
        if adds[0] != ObjectGuid::EMPTY {
            if let Some(s) = self.stalagg_state_mut(adds[0]) {
                s.other_add = adds[1];
            } else if let Some(s) = self.feugen_state_mut(adds[0]) {
                s.other_add = adds[1];
            }
        }
        if adds[1] != ObjectGuid::EMPTY {
            if let Some(s) = self.feugen_state_mut(adds[1]) {
                s.other_add = adds[0];
            } else if let Some(s) = self.stalagg_state_mut(adds[1]) {
                s.other_add = adds[0];
            }
        }
    }

    fn thaddius_handle_unsummon_coil(&mut self, guid: ObjectGuid, which: usize) {
        let coil = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Thaddius(s)) => Some(s.coil_guids[which]),
                _ => None,
            })
            .unwrap_or(ObjectGuid::EMPTY);
        if coil != ObjectGuid::EMPTY && self.creatures.contains_key(&coil) {
            self.despawn_creature_now(coil, 0);
        }
        if let Some(s) = self.thaddius_state_mut(guid) {
            s.coil_guids[which] = ObjectGuid::EMPTY;
        }
        // NEEDS-MAP-HELPER: tesla GO state READY (cpp 646-649).
    }

    fn thaddius_handle_unsummon_add(&mut self, guid: ObjectGuid, which: usize) {
        let add = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Thaddius(s)) => Some(s.add_guids[which]),
                _ => None,
            })
            .unwrap_or(ObjectGuid::EMPTY);
        if add != ObjectGuid::EMPTY && self.creatures.contains_key(&add) {
            self.despawn_creature_now(add, 0);
        }
        if let Some(s) = self.thaddius_state_mut(guid) {
            s.add_guids[which] = ObjectGuid::EMPTY;
        }
    }

