    #[allow(clippy::unused_self)]
    fn thaddius_summoned_creature_despawn(&mut self, guid: ObjectGuid, _despawned: ObjectGuid) {
        // Fork body is commented out (cpp 664-675) — dropped.
        // NO-DISPATCHER-YET.
        let _ = guid;
    }

    fn thaddius_transition_to_phase(&mut self, guid: ObjectGuid, phase: u8) {
        if let Some(s) = self.thaddius_state_mut(guid) {
            s.phase = phase;
        }
        match phase {
            THAD_PHASE_NOT_STARTED => {
                // NEEDS-MAP-HELPER: `OnLeaveCombat` (cpp 756).
            }
            THAD_PHASE1 => {
                self.set_in_combat_with_zone(guid);
            }
            THAD_PHASE_TRANSITION => {
                // One-shot step machine replaces the three fork
                // transition events (10s / 13s / 14s, cpp 761-769).
                if let Some(s) = self.thaddius_state_mut(guid) {
                    s.transition_step = 0;
                    s.transition_timer_ms = 10_000;
                }
            }
            _ => {
                // NEEDS-MAP-HELPER: `DoResetThreat` (cpp 772).
                let shift = self.rng.urand(10_000, 15_000);
                let chain = self.rng.urand(10_000, 15_000);
                if let Some(t) = self.select_random_hostile(guid) {
                    self.attack_start(guid, t);
                }
                if let Some(s) = self.thaddius_state_mut(guid) {
                    s.thaddius_berserk_timer_ms = THAD_ENRAGE_TIMER;
                    s.polarity_shift_timer_ms = shift;
                    s.chain_lightning_timer_ms = chain;
                    s.ball_lightning_timer_ms = 1000;
                }
            }
        }
    }

    fn thaddius_transition_coil(&mut self, guid: ObjectGuid, which: usize) -> Option<ObjectGuid> {
        self.ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Thaddius(s)) => Some(s.coil_guids[which]),
                _ => None,
            })
            .filter(|c| *c != ObjectGuid::EMPTY && self.creatures.contains_key(c))
    }

    fn thaddius_update_transition_phase(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let (step, fire) = {
            let Some(s) = self.thaddius_state_mut(guid) else {
                return;
            };
            if s.transition_timer_ms <= diff_ms {
                (s.transition_step, true)
            } else {
                s.transition_timer_ms -= diff_ms;
                (s.transition_step, false)
            }
        };
        if !fire {
            return;
        }
        match step {
            // TRANSITION_1: unsummon adds + coil overload emotes.
            0 => {
                self.thaddius_handle_unsummon_add(guid, 0);
                self.thaddius_handle_unsummon_add(guid, 1);
                for which in 0..2 {
                    if let Some(coil) = self.thaddius_transition_coil(guid, which) {
                        self.do_script_text(THAD_EMOTE_TESLA_OVERLOAD, coil, None, -1);
                    }
                }
                if let Some(s) = self.thaddius_state_mut(guid) {
                    s.transition_step = 1;
                    s.transition_timer_ms = 3000;
                }
            }
            // TRANSITION_2: coils zap thaddius, spawn aura off,
            // flag off, lightning visual.
            1 => {
                for which in 0..2 {
                    if let Some(coil) = self.thaddius_transition_coil(guid, which) {
                        self.do_cast_spell_if_can(
                            coil,
                            THAD_SPELL_SHOCK_OVERLOAD,
                            CastTarget::Unit(guid),
                        );
                    }
                }
                self.remove_auras_due_to_spell(guid, THAD_SPELL_THADIUS_SPAWN);
                let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::UNIT_FIELD_FLAGS),
                    flags & !THAD_UNIT_FLAG_NOT_SELECTABLE,
                );
                // Triggered in fork (`CastSpell(..., true)`).
                self.do_cast_spell_if_can(
                    guid,
                    THAD_SPELL_THADIUS_LIGHTNING_VISUAL,
                    CastTarget::SelfCast,
                );
                if let Some(s) = self.thaddius_state_mut(guid) {
                    s.transition_step = 2;
                    s.transition_timer_ms = 1000;
                }
            }
            // TRANSITION_3: unsummon coils, engage.
            _ => {
                self.thaddius_handle_unsummon_coil(guid, 0);
                self.thaddius_handle_unsummon_coil(guid, 1);
                // NEEDS-MAP-HELPER: tesla GO state READY
                // (`GetSingleGameObjectFromStorage` x2; the fork
                // block is commented out anyway, cpp 819-824).
                self.thaddius_transition_to_phase(guid, THAD_PHASE2);
            }
        }
    }

    fn thaddius_do_polarity_shift(&mut self, guid: ObjectGuid) {
        self.do_script_text(THAD_SAY_ELECT, guid, None, -1);
        // NEEDS-MAP-HELPER: fork shuffles the alive map player
        // list, strips all six charge auras (AMP/APPLY/TICK x
        // POS 29659/28059/28062 and NEG 29660/28084/28085), and
        // casts POSITIVE (28059) on the first half / NEGATIVE
        // (28084) on the rest with the player as caster (cpp
        // 846-876).
        let _ = guid;
    }

    fn thaddius_do_spell_chain(&mut self, guid: ObjectGuid) -> bool {
        // Returns true when a cast was attempted (fork checks
        // `CAST_OK`; no fail-code plumbing — see unresolved).
        if let Some(t) = self.select_random_hostile(guid) {
            self.do_cast_spell_if_can(guid, THAD_SPELL_CHAIN_LIGHTNING, CastTarget::Unit(t));
            true
        } else {
            false
        }
    }

    #[allow(clippy::too_many_lines)]
    fn thaddius_update_p2(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Polarity Shift (30s; interrupt-previous in fork).
        let due = {
            let Some(s) = self.thaddius_state_mut(guid) else {
                return;
            };
            if s.polarity_shift_timer_ms < diff_ms {
                true
            } else {
                s.polarity_shift_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            if self.do_cast_spell_if_can(guid, THAD_SPELL_POLARITY_SHIFT, CastTarget::SelfCast) {
                if let Some(s) = self.thaddius_state_mut(guid) {
                    s.polarity_shift_timer_ms = 30_000;
                    s.polarity_change_timer_ms = 3000;
                    s.polarity_change_pending = true;
                }
            } else if let Some(s) = self.thaddius_state_mut(guid) {
                s.polarity_shift_timer_ms = 100;
            }
        }
        // Polarity Change (applies the charges, 3s).
        let due = {
            let Some(s) = self.thaddius_state_mut(guid) else {
                return;
            };
            if s.polarity_change_pending && s.polarity_change_timer_ms <= diff_ms {
                s.polarity_change_pending = false;
                true
            } else {
                if s.polarity_change_pending {
                    s.polarity_change_timer_ms -= diff_ms;
                }
                false
            }
        };
        if due {
            self.thaddius_do_polarity_shift(guid);
        }
        // Chain Lightning.
        let due = {
            let Some(s) = self.thaddius_state_mut(guid) else {
                return;
            };
            if s.chain_lightning_timer_ms < diff_ms {
                true
            } else {
                s.chain_lightning_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            if self.thaddius_do_spell_chain(guid) {
                let next = self.rng.urand(10_000, 15_000);
                if let Some(s) = self.thaddius_state_mut(guid) {
                    s.chain_lightning_timer_ms = next;
                }
            } else if let Some(s) = self.thaddius_state_mut(guid) {
                s.chain_lightning_timer_ms = 100;
            }
        }
        // Berserk (single shot; repeats at 100ms only on failure).
        let due = {
            let Some(s) = self.thaddius_state_mut(guid) else {
                return;
            };
            if s.thaddius_berserk_timer_ms < diff_ms {
                true
            } else {
                s.thaddius_berserk_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            if self.do_cast_spell_if_can(guid, THAD_SPELL_BESERK, CastTarget::SelfCast) {
                if let Some(s) = self.thaddius_state_mut(guid) {
                    s.thaddius_berserk_timer_ms = u32::MAX;
                }
            } else if let Some(s) = self.thaddius_state_mut(guid) {
                s.thaddius_berserk_timer_ms = 100;
            }
        }
        // Ball lightning when melee is unreachable (cpp 928-952).
        // NEEDS-MAP-HELPER: fork keys off the melee-attack-ready
        // swing state and `IsNonMeleeSpellCasted`; approximated
        // with a 5yd position check here.
        let in_melee = match (self.unit_position(guid), self.unit_position(victim)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy <= 5.0 * 5.0
            }
            _ => true,
        };
        if in_melee {
            if let Some(s) = self.thaddius_state_mut(guid) {
                s.ball_lightning_timer_ms = 1000;
            }
        } else if let Some(s) = self.thaddius_state_mut(guid) {
            s.ball_lightning_timer_ms = s.ball_lightning_timer_ms.saturating_sub(diff_ms);
        }
        let ball_ready = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Thaddius(s)) => Some(s.ball_lightning_timer_ms < diff_ms),
                _ => None,
            })
            .unwrap_or(false);
        // NEEDS-MAP-HELPER: fork also gates on
        // `!IsNonMeleeSpellCasted`.
        if ball_ready
            && self.do_cast_spell_if_can(guid, THAD_SPELL_BALL_LIGHTNING, CastTarget::Unit(victim))
        {
            if let Some(s) = self.thaddius_state_mut(guid) {
                s.ball_lightning_timer_ms = 1500;
            }
        }
        let _ = diff_ms;
    }

    fn thaddius_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if let Some(s) = self.thaddius_state_mut(guid) {
            s.kill_say_cooldown_ms = s.kill_say_cooldown_ms.saturating_sub(diff_ms);
        }
        let phase = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Thaddius(s)) => Some(s.phase),
                _ => None,
            })
            .unwrap_or(THAD_PHASE_NOT_STARTED);
        match phase {
            THAD_PHASE_NOT_STARTED => {
                if self.ai_in_combat(guid) {
                    self.thaddius_transition_to_phase(guid, THAD_PHASE_NOT_STARTED);
                } else if self.instance_get_data(NAX_TYPE_THADDIUS) == Some(IN_PROGRESS) {
                    self.thaddius_transition_to_phase(guid, THAD_PHASE1);
                }
            }
            THAD_PHASE1 => {
                if self.instance_get_data(NAX_TYPE_THADDIUS) == Some(NAX_FAIL) {
                    self.thaddius_transition_to_phase(guid, THAD_PHASE_NOT_STARTED);
                } else if self.instance_get_data(NAX_TYPE_THADDIUS) == Some(NAX_SPECIAL) {
                    self.thaddius_transition_to_phase(guid, THAD_PHASE_TRANSITION);
                }
            }
            THAD_PHASE_TRANSITION => {
                self.thaddius_update_transition_phase(guid, diff_ms);
            }
            _ => {
                self.thaddius_update_p2(guid, diff_ms);
            }
        }
    }

    // ---- instance_naxxramas mobs ----
    // mob_spiritOfNaxxramasAI (cpp 1433-1501).
    fn spirit_of_naxxramas_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.spirit_of_naxxramas_state_mut(guid) {
            s.portal_timer_ms = 5000;
            s.shadowbolt_volley_timer_ms = 6000;
        }
        self.spirit_of_naxxramas_despawn_portal(guid);
        // Ctor stealth-detection aura (cpp 1438).
        self.apply_aura_by_id(guid, SPIRIT_SPELL_STEALTH_DETECT, guid);
    }

    fn spirit_of_naxxramas_despawn_portal(&mut self, guid: ObjectGuid) {
        let portal = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::SpiritOfNaxxramas(s)) => Some(s.portal),
                _ => None,
            })
            .unwrap_or(ObjectGuid::EMPTY);
        if portal != ObjectGuid::EMPTY && self.creatures.contains_key(&portal) {
            self.despawn_creature_now(portal, 0);
        }
        if let Some(s) = self.spirit_of_naxxramas_state_mut(guid) {
            s.portal = ObjectGuid::EMPTY;
        }
    }

    fn spirit_of_naxxramas_just_died(&mut self, guid: ObjectGuid) {
        self.spirit_of_naxxramas_despawn_portal(guid);
    }

    fn spirit_of_naxxramas_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Portal of shadows (one-shot, 5s).
        let due = {
            let Some(s) = self.spirit_of_naxxramas_state_mut(guid) else {
                return;
            };
            if s.portal_timer_ms == 0 {
                false
            } else if s.portal_timer_ms < diff_ms {
                s.portal_timer_ms = 0;
                true
            } else {
                s.portal_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            if let Some(portal) = self.summon_creature(
                SPIRIT_NPC_PORTAL,
                self.unit_position(guid).unwrap_or_default(),
                guid,
                SPIRIT_TEMPSUMMON_TIMED_DESPAWN,
                60_000,
            ) {
                // `SendSpellGo` visual for the manual summon
                // (cpp 1478).
                self.send_spell_go_simple(guid, SPIRIT_SPELL_PORTAL_VISUAL, guid, 0);
                if let Some(s) = self.spirit_of_naxxramas_state_mut(guid) {
                    s.portal = portal;
                }
                // Portal casts the shadow aura on itself (cpp 1480).
                self.do_cast_spell_if_can(portal, SPIRIT_SPELL_PORTAL_SHADOW, CastTarget::SelfCast);
            }
        }
        // Shadowbolt volley (10s).
        let due = {
            let Some(s) = self.spirit_of_naxxramas_state_mut(guid) else {
                return;
            };
            if s.shadowbolt_volley_timer_ms < diff_ms {
                true
            } else {
                s.shadowbolt_volley_timer_ms -= diff_ms;
                false
            }
        };
        if due
            && self.do_cast_spell_if_can(guid, SPIRIT_SPELL_SHADOWBOLT_VOLLEY, CastTarget::SelfCast)
        {
            if let Some(s) = self.spirit_of_naxxramas_state_mut(guid) {
                s.shadowbolt_volley_timer_ms = 10_000;
            }
        }
    }

    // mob_naxxramasGarboyleAI (cpp 1513-1586).
    fn naxx_gargoyle_enter_stoneform(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: fork gates on
        // `GetDefaultMovementType() == IDLE_MOTION_TYPE` +
        // entry 16168 (cpp 1526-1528, 1540).
        if self.creatures.get(&guid).map(|c| c.info.entry) == Some(GARG_NPC_STONESKIN_ENTRY) {
            self.apply_aura_by_id(guid, GARG_SPELL_GARGOYLE_STONEFORM_VISUAL, guid);
            self.apply_aura_by_id(guid, GARG_SPELL_INVISIBILITY_STEALTH_DETECTION, guid);
        }
    }

    fn naxx_gargoyle_reset(&mut self, guid: ObjectGuid) {
        let roll = self.rng.urand(2800, 6500);
        if let Some(s) = self.naxx_gargoyle_state_mut(guid) {
            s.acid_volley_timer_ms = roll;
        }
        // Ctor also enters stoneform (cpp 1518).
        self.naxx_gargoyle_enter_stoneform(guid);
    }

    fn naxx_gargoyle_just_reached_home(&mut self, guid: ObjectGuid) {
        self.naxx_gargoyle_enter_stoneform(guid);
    }

    fn naxx_gargoyle_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        if self.unit_has_aura(guid, GARG_SPELL_GARGOYLE_STONEFORM_VISUAL) {
            // `RemoveAurasDueToSpellByCancel` (cpp 1554).
            self.remove_auras_due_to_spell(guid, GARG_SPELL_GARGOYLE_STONEFORM_VISUAL);
        }
    }

    fn naxx_gargoyle_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        // Stoneform-gated 17yd pull (cpp 1536-1549).
        // NEEDS-MAP-HELPER: LOS + feign-death / unattackable
        // aura checks on `who`; base-MLOS fallback.
        if self.unit_has_aura(guid, GARG_SPELL_GARGOYLE_STONEFORM_VISUAL) {
            let dist_ok = match (self.unit_position(guid), self.unit_position(who)) {
                (Some(a), Some(b)) => {
                    let dx = a.x - b.x;
                    let dy = a.y - b.y;
                    dx * dx + dy * dy <= 17.0 * 17.0
                }
                _ => false,
            };
            if self.players.contains_key(&who) && !self.ai_in_combat(guid) && dist_ok {
                self.attack_start(guid, who);
            }
        } else {
            // NEEDS-MAP-HELPER: base MLOS proximity pull.
        }
    }

    fn naxx_gargoyle_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Stoneskin at 30% (fork double-casts + emote, cpp 1562-1569).
        if self.creature_health_percent(guid) < 30.0
            && !self.unit_has_aura(guid, GARG_SPELL_STONESKIN)
            && self.bot_casting_spell(guid).is_none()
            && self.do_cast_spell_if_can(guid, GARG_SPELL_STONESKIN, CastTarget::SelfCast)
        {
            // NEEDS-MAP-HELPER: fork casts STONESKIN a
            // second time (triggered) after the DoCast.
            self.do_script_text(GARG_BCT_STRANGE_NOISE, guid, None, -1);
        }
        // NEEDS-MAP-HELPER: `IsNonMeleeSpellCasted` gate below
        // approximated with the bot-cast check.
        let casting = self.bot_casting_spell(guid).is_some();
        let due = {
            let Some(s) = self.naxx_gargoyle_state_mut(guid) else {
                return;
            };
            if s.acid_volley_timer_ms < diff_ms && !casting {
                true
            } else {
                s.acid_volley_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: DB-guid 88095 exemption (no
            // spawn-guid helper; cpp 1575).
            if self.do_cast_spell_if_can(guid, GARG_SPELL_ACID_VOLLEY, CastTarget::SelfCast) {
                if let Some(s) = self.naxx_gargoyle_state_mut(guid) {
                    s.acid_volley_timer_ms = 8000;
                }
            }
        }
        let _ = victim;
    }

    // mob_naxxramasPlagueSlimeAI (cpp 1588-1637).
    fn naxx_plague_slime_change_color(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: `UpdateEntry` on the rolled spell's
        // `EffectMiscValue[0]` (entry morph) + `SetObjectScale
        // (2.0)` (cpp 1599-1611); aura half transcribed.
        let spell = self.rng.urand(28_987, 28_990);
        let prev = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::NaxxPlagueSlime(s)) => Some(s.prev_spell),
                _ => None,
            })
            .unwrap_or(0);
        if prev != 0 {
            self.remove_auras_due_to_spell(guid, prev);
        }
        self.do_cast_spell_if_can(guid, spell, CastTarget::SelfCast);
        if let Some(s) = self.naxx_plague_slime_state_mut(guid) {
            s.prev_spell = spell;
        }
    }

    fn naxx_plague_slime_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.naxx_plague_slime_state_mut(guid) {
            s.color_change_timer_ms = 0;
        }
        self.naxx_plague_slime_change_color(guid);
    }

