    /// `boss_theolenkrastinovAI::UpdateAI` (cpp 46-77).
    fn theolen_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Rend_Timer.
        let rend_due = {
            let Some(s) = self.theolen_state_mut(guid) else {
                return;
            };
            if s.rend_timer_ms < diff_ms {
                true
            } else {
                s.rend_timer_ms -= diff_ms;
                false
            }
        };
        if rend_due {
            self.do_cast_spell_if_can(guid, THEOLEN_SPELL_REND, CastTarget::Unit(victim));
            if let Some(s) = self.theolen_state_mut(guid) {
                s.rend_timer_ms = 10_000;
            }
        }
        // Backhand_Timer (+ threat wipe).
        let backhand_due = {
            let Some(s) = self.theolen_state_mut(guid) else {
                return;
            };
            if s.backhand_timer_ms < diff_ms {
                true
            } else {
                s.backhand_timer_ms -= diff_ms;
                false
            }
        };
        if backhand_due {
            self.do_cast_spell_if_can(guid, THEOLEN_SPELL_BACKHAND, CastTarget::Unit(victim));
            self.modify_threat_percent_of(guid, victim, -100);
            if let Some(s) = self.theolen_state_mut(guid) {
                s.backhand_timer_ms = 10_000;
            }
        }
        // Frenzy_Timer (only ticks below 26% health, fork order).
        if self.creature_health_percent(guid) < 26.0 {
            let frenzy_due = {
                let Some(s) = self.theolen_state_mut(guid) else {
                    return;
                };
                if s.frenzy_timer_ms < diff_ms {
                    true
                } else {
                    s.frenzy_timer_ms -= diff_ms;
                    false
                }
            };
            if frenzy_due
                && self.do_cast_spell_if_can(guid, HEROD_SPELL_FRENZY, CastTarget::SelfCast)
            {
                self.do_script_text(THEOLEN_EMOTE_GENERIC_FRENZY_KILL, guid, None, -1);
                if let Some(s) = self.theolen_state_mut(guid) {
                    s.frenzy_timer_ms = 120_000;
                }
            }
        }
    }

