    /// `boss_jandicebarovAI::SummonIllusions` (cpp 59-66): fork
    /// `DoSpawnCreature(11439, 10.0f, TIMED_OR_CORPSE, 60000)` spawns at a
    /// random point within 10y; approximated with an frand box (herod style).
    fn jandice_summon_illusions(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        let me = self.unit_position(guid).unwrap_or_default();
        let jx = self.rng.frand(-10.0, 10.0);
        let jy = self.rng.frand(-10.0, 10.0);
        let at = Position::new(me.x + jx, me.y + jy, me.z, 0.0);
        let summoned = self.summon_creature(
            JANDICE_NPC_ILLUSION,
            at,
            guid,
            JANDICE_TEMPSUMMON_TIMED_OR_CORPSE_DESPAWN,
            60_000,
        );
        if let Some(created) = summoned {
            self.attack_start(created, victim);
            if let Some(s) = self.jandice_state_mut(guid) {
                s.illusion_guids.push(created);
            }
        }
    }

    /// `boss_jandicebarovAI::UnsummonIllusions` (cpp 68-79).
    fn jandice_unsummon_illusions(&mut self, guid: ObjectGuid) {
        let guids = self
            .jandice_state_mut(guid)
            .map(|s| std::mem::take(&mut s.illusion_guids))
            .unwrap_or_default();
        for g in guids {
            if self.creatures.contains_key(&g) {
                self.despawn_creature_now(g, 0);
            }
            // else fork `sLog` missing-creature line (no log helper ported).
        }
    }

    /// `boss_jandicebarovAI::JustDied` (cpp 81-90).
    fn jandice_just_died(&mut self, guid: ObjectGuid) {
        self.jandice_unsummon_illusions(guid);
        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_FLAGS),
            flags & !JANDICE_UNIT_FLAG_NOT_SELECTABLE,
        );
        // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_ON)` (cpp 85).
        // NEEDS-MAP-HELPER: `sWorld.GetWowPatch() >= WOW_PATCH_109` gate (cpp 87).
        let _ = self.cast_spell(
            guid,
            JANDICE_SPELL_DROP_JOURNAL,
            CastTarget::SelfCast,
            CastOptions {
                triggered: true,
                triggered_by_aura: false,
                skip_known: true,
                cast_item: None,
                custom_base_points: [None; 3],
                triggered_by_aura_spell: 0,
                triggered_by_spell: 0,
            },
        );
    }

    /// `boss_jandicebarovAI::DamageTaken` (cpp 92-102).
    /// NO-DISPATCHER-YET: no `DamageTaken` dispatcher in content.rs.
    fn jandice_damage_taken(&mut self, guid: ObjectGuid, _attacker: ObjectGuid, damage: &mut u32) {
        let dealt = *damage;
        let over = {
            let Some(s) = self.jandice_state_mut(guid) else {
                return;
            };
            if !s.check_for_damage {
                return;
            }
            s.damage_taken = s.damage_taken.saturating_add(dealt);
            if s.damage_taken <= 500 {
                return;
            }
            s.check_for_damage = false;
            s.damage_taken = 0;
            true
        };
        if over {
            self.jandice_unsummon_illusions(guid);
        }
    }

    /// `boss_jandicebarovAI::UpdateAI` (cpp 104-156). The invisible
    /// preamble runs before the combat drive (fork order).
    fn jandice_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let invisible = self.jandice_state_mut(guid).is_some_and(|s| s.invisible);
        if invisible {
            let due = {
                let Some(s) = self.jandice_state_mut(guid) else {
                    return;
                };
                if s.invisible_timer_ms < diff_ms {
                    true
                } else {
                    s.invisible_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                // Become visible again.
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                    JANDICE_FACTION_VISIBLE,
                );
                let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::UNIT_FIELD_FLAGS),
                    flags & !JANDICE_UNIT_FLAG_NOT_SELECTABLE,
                );
                // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_ON)` (cpp 111).
                if let Some(s) = self.jandice_state_mut(guid) {
                    s.invisible = false;
                    s.damage_taken = 0;
                    s.check_for_damage = true;
                }
            } else {
                // Do nothing while invisible.
                return;
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // CurseOfBlood_Timer.
        let curse_due = {
            let Some(s) = self.jandice_state_mut(guid) else {
                return;
            };
            if s.curse_of_blood_timer_ms < diff_ms {
                true
            } else {
                s.curse_of_blood_timer_ms -= diff_ms;
                false
            }
        };
        if curse_due {
            self.do_cast_spell_if_can(guid, JANDICE_SPELL_CURSE_OF_BLOOD, CastTarget::Unit(victim));
            if let Some(s) = self.jandice_state_mut(guid) {
                s.curse_of_blood_timer_ms = 30_000;
            }
        }
        // Illusion_Timer (skipped while invisible, fork `!Invisible &&`).
        let illusion_due = {
            let Some(s) = self.jandice_state_mut(guid) else {
                return;
            };
            if !s.invisible && s.illusion_timer_ms < diff_ms {
                true
            } else {
                s.illusion_timer_ms = s.illusion_timer_ms.saturating_sub(diff_ms);
                false
            }
        };
        if illusion_due {
            // NEEDS-MAP-HELPER: `InterruptNonMeleeSpells(false)` (cpp 138).
            let _ = self.object_set_field(
                guid,
                u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                JANDICE_FACTION_HIDDEN,
            );
            let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
            let _ = self.object_set_field(
                guid,
                u32::from(offsets::UNIT_FIELD_FLAGS),
                flags | JANDICE_UNIT_FLAG_NOT_SELECTABLE,
            );
            self.modify_threat_percent_of(guid, victim, -99);
            // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_OFF)` (cpp 142).
            if let Some(s) = self.jandice_state_mut(guid) {
                s.damage_taken = 0;
                s.invisible = true;
                s.invisible_timer_ms = 3000;
                s.illusion_timer_ms = 25_000;
            }
            // Summon 10 illusions on random gamers.
            for _ in 0..10 {
                // NEEDS-MAP-HELPER: fork `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 0)`.
                if let Some(target) = self.select_random_hostile(guid) {
                    self.jandice_summon_illusions(guid, target);
                }
            }
        }
    }

