    /// `boss_vectusAI::UpdateAI` (cpp 82-170): the gambit preamble runs
    /// with no target (before the drive); the room-aggro sweep runs
    /// after the first successful drive (fork order).
    fn vectus_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let gambit_open = self.vectus_state_mut(guid).is_some_and(|s| !s.gambit_done);
        if gambit_open {
            let due = {
                let Some(s) = self.vectus_state_mut(guid) else {
                    return;
                };
                if s.gambit_event_timer_ms < diff_ms {
                    true
                } else {
                    s.gambit_event_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                self.vectus_gambit_step(guid);
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Room aggro sweep once pulled.
        let sweep = {
            let Some(s) = self.vectus_state_mut(guid) else {
                return;
            };
            if s.full_aggro_done {
                false
            } else {
                s.full_aggro_done = true;
                true
            }
        };
        if sweep {
            let students: Vec<ObjectGuid> = self
                .creatures
                .values()
                .filter(|c| c.info.entry == VECTUS_NPC_STUDENT)
                .filter(|c| {
                    match (
                        self.object_position(guid),
                        self.object_position(c.unit.guid()),
                    ) {
                        (Some(a), Some(b)) => {
                            let dx = a.x - b.x;
                            let dy = a.y - b.y;
                            dx * dx + dy * dy <= 100.0 * 100.0
                        }
                        _ => false,
                    }
                })
                .map(|c| c.unit.guid())
                .collect();
            for student in students {
                let _ = self.object_set_field(
                    student,
                    u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                    VECTUS_FACTION_MONSTER,
                );
                self.attack_start(student, victim);
            }
        }
        // FlameStrike_Timer (self ground cast in the fork; no position
        // arg: `DoCastSpellIfCan(m_creature, ...)`).
        let strike_due = {
            let Some(s) = self.vectus_state_mut(guid) else {
                return;
            };
            if s.flame_strike_timer_ms < diff_ms {
                true
            } else {
                s.flame_strike_timer_ms -= diff_ms;
                false
            }
        };
        if strike_due {
            self.do_cast_spell_if_can(guid, VECTUS_SPELL_FLAMESTRIKE, CastTarget::SelfCast);
            if let Some(s) = self.vectus_state_mut(guid) {
                s.flame_strike_timer_ms = 30_000;
            }
        }
        // BlastWave_Timer.
        let wave_due = {
            let Some(s) = self.vectus_state_mut(guid) else {
                return;
            };
            if s.blast_wave_timer_ms < diff_ms {
                true
            } else {
                s.blast_wave_timer_ms -= diff_ms;
                false
            }
        };
        if wave_due {
            self.do_cast_spell_if_can(guid, VECTUS_SPELL_BLAST_WAVE, CastTarget::Unit(victim));
            if let Some(s) = self.vectus_state_mut(guid) {
                s.blast_wave_timer_ms = 12_000;
            }
        }
        // Frenzy block commented out in the fork (cpp 190-203): skipped.
    }

    /// Gambit event step (vectus cpp 85-128), one timer tick.
    fn vectus_gambit_step(&mut self, guid: ObjectGuid) {
        let (started, found) = self
            .vectus_state_mut(guid)
            .map_or((true, true), |s| (s.gambit_started, s.gambit_found));
        if !started {
            if found {
                // NEEDS-MAP-HELPER: `pGambit->Delete()` (cpp 99).
                let _ = self.vectus_state_mut(guid).and_then(|s| s.gambit_go);
                if let Some(s) = self.vectus_state_mut(guid) {
                    s.gambit_event_timer_ms = 12_000;
                    s.gambit_started = true;
                }
            } else {
                // `GetClosestGameObjectWithEntry(GO_DAWN_S_GAMBIT, 100.0f)`.
                let me = self.unit_position(guid).unwrap_or_default();
                let go = self
                    .gameobjects
                    .iter()
                    .filter(|(_, g)| g.info.id == VECTUS_GO_DAWN_GAMBIT)
                    .filter_map(|(g, _)| {
                        self.object_position(*g).map(|p| {
                            let dx = p.x - me.x;
                            let dy = p.y - me.y;
                            (*g, dx * dx + dy * dy)
                        })
                    })
                    .min_by(|a, b| a.1.total_cmp(&b.1))
                    .filter(|(_, d)| *d <= 100.0 * 100.0)
                    .map(|(g, _)| g);
                if let Some(go) = go {
                    if let Some(s) = self.vectus_state_mut(guid) {
                        s.gambit_go = Some(go);
                        s.gambit_event_timer_ms = 2000;
                        s.gambit_found = true;
                    }
                }
            }
            return;
        }
        // Event start: Marduk + students hostile, students transformed.
        if let Some(marduk) =
            self.nearest_creature_with_entry(guid, VECTUS_NPC_MARDUK_BLACKPOOL, 100.0)
        {
            let _ = self.object_set_field(
                marduk,
                u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                VECTUS_FACTION_MONSTER,
            );
            // NEEDS-MAP-HELPER: `SetReactState(REACT_AGGRESSIVE)` +
            // `AIM_Initialize()` (cpp 108-109).
        }
        let students: Vec<ObjectGuid> = self
            .creatures
            .values()
            .filter(|c| c.info.entry == VECTUS_NPC_STUDENT)
            .filter(|c| {
                match (
                    self.object_position(guid),
                    self.object_position(c.unit.guid()),
                ) {
                    (Some(a), Some(b)) => {
                        let dx = a.x - b.x;
                        let dy = a.y - b.y;
                        dx * dx + dy * dy <= 100.0 * 100.0
                    }
                    _ => false,
                }
            })
            .map(|c| c.unit.guid())
            .collect();
        for student in students {
            let _ = self.cast_spell(
                student,
                VECTUS_SPELL_STUDENT_TRANSFORM,
                CastTarget::Unit(student),
                CastOptions {
                    triggered: true,
                    triggered_by_aura: false,
                    skip_known: true,
                    cast_item: None,
                    custom_base_points: [None; 3],
                    triggered_by_aura_spell: 0,
                    triggered_by_spell: 0,
                },
            );
            // NEEDS-MAP-HELPER: `CreatureGroup::RemoveMember` +
            // `SetCreatureGroup(nullptr)` (cpp 116-119).
            let _ = self.object_set_field(
                student,
                u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
                VECTUS_FACTION_MONSTER,
            );
            // NEEDS-MAP-HELPER: `SetReactState(REACT_AGGRESSIVE)` +
            // `AIM_Initialize()` (cpp 122-123).
        }
        self.do_script_text(VECTUS_SPEECH_GAMBIT_EVENT_START, guid, None, -1);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_FACTIONTEMPLATE),
            VECTUS_FACTION_MONSTER,
        );
        // NEEDS-MAP-HELPER: `SetReactState(REACT_AGGRESSIVE)` +
        // `AIM_Initialize()` (cpp 126-127).
        if let Some(s) = self.vectus_state_mut(guid) {
            s.gambit_done = true;
        }
    }

