    /// `npc_highprotectorlorikAI::Reset` (wpl cpp 127-135).
    fn lorik_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.lorik_state_mut(guid) {
            s.global_cooldown_ms = 0;
            s.arcane_blast_timer_ms = 7000;
            s.divine_shield_timer_ms = 2000;
            s.holy_light_timer_ms = 2000;
            s.shield_slam_timer_ms = 2000;
        }
    }

    /// `npc_highprotectorlorikAI::UpdateAI` (wpl cpp 137-218). The aura
    /// upkeep runs before the combat drive (fork order).
    #[allow(clippy::too_many_lines)]
    fn lorik_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if !self.bot_has_aura(guid, LORIK_SPELL_RETRIBUTION_AURA) {
            let _ = self.cast_spell(
                guid,
                LORIK_SPELL_RETRIBUTION_AURA,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    triggered_by_aura: false,
                    skip_known: true,
                    cast_item: None,
                    custom_base_points: [None; 3],
                    triggered_by_aura_spell: 0,
                    triggered_by_spell: 0,
                },
            );
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // GlobalCD block (fork `IsNonMeleeSpellCasted` ~ active cast).
        let gcd_start = self
            .lorik_state_mut(guid)
            .map_or(0, |s| s.global_cooldown_ms);
        let gcd = if gcd_start > diff_ms {
            if let Some(s) = self.lorik_state_mut(guid) {
                s.global_cooldown_ms -= diff_ms;
            }
            gcd_start - diff_ms
        } else if self.bot_casting_spell(guid).is_some() {
            if let Some(s) = self.lorik_state_mut(guid) {
                s.global_cooldown_ms = 1;
            }
            1
        } else {
            if let Some(s) = self.lorik_state_mut(guid) {
                s.global_cooldown_ms = 0;
            }
            0
        };
        // DIVINESHIELD (<=15% health, off-GCD).
        let shield_due = {
            let Some(s) = self.lorik_state_mut(guid) else {
                return;
            };
            if s.divine_shield_timer_ms < diff_ms {
                true
            } else {
                s.divine_shield_timer_ms -= diff_ms;
                false
            }
        };
        if shield_due
            && gcd == 0
            && self.creature_health_percent(guid) <= 15.0
            && self.do_cast_spell_if_can(guid, LORIK_SPELL_DIVINE_SHIELD, CastTarget::SelfCast)
        {
            if let Some(s) = self.lorik_state_mut(guid) {
                s.divine_shield_timer_ms = 45_000;
                s.global_cooldown_ms = 1000;
            }
        }
        // ARCANEBLAST (urand re-roll on success, fork order).
        let blast_due = {
            let Some(s) = self.lorik_state_mut(guid) else {
                return;
            };
            if s.arcane_blast_timer_ms < diff_ms {
                true
            } else {
                s.arcane_blast_timer_ms -= diff_ms;
                false
            }
        };
        if blast_due {
            let off_gcd = self
                .lorik_state_mut(guid)
                .is_some_and(|s| s.global_cooldown_ms == 0);
            if off_gcd
                && self.do_cast_spell_if_can(
                    guid,
                    LORIK_SPELL_ARCANE_BLAST,
                    CastTarget::Unit(victim),
                )
            {
                let next = self.rng.urand(10_000, 12_000);
                if let Some(s) = self.lorik_state_mut(guid) {
                    s.arcane_blast_timer_ms = next;
                    s.global_cooldown_ms = 1000;
                }
            }
        }
        // HOLYLIGHT (<=60% health, mana gate; `GetPower(POWER_MANA)` ~
        // UNIT_FIELD_POWER1).
        let light_due = {
            let Some(s) = self.lorik_state_mut(guid) else {
                return;
            };
            if s.holy_light_timer_ms < diff_ms {
                true
            } else {
                s.holy_light_timer_ms -= diff_ms;
                false
            }
        };
        if light_due {
            let mana = self.unit_value_u32(guid, offsets::UNIT_FIELD_POWER1);
            let off_gcd = self
                .lorik_state_mut(guid)
                .is_some_and(|s| s.global_cooldown_ms == 0);
            if off_gcd
                && self.creature_health_percent(guid) <= 60.0
                && mana > 700
                && self.do_cast_spell_if_can(guid, LORIK_SPELL_HOLY_LIGHT, CastTarget::SelfCast)
            {
                let next = self.rng.urand(2000, 6000);
                if let Some(s) = self.lorik_state_mut(guid) {
                    s.holy_light_timer_ms = next;
                    s.global_cooldown_ms = 1000;
                }
            }
        }
        // SHIELDSLAM (victim mid-cast, off-GCD).
        let slam_due = {
            let Some(s) = self.lorik_state_mut(guid) else {
                return;
            };
            if s.shield_slam_timer_ms < diff_ms {
                true
            } else {
                s.shield_slam_timer_ms -= diff_ms;
                false
            }
        };
        if slam_due {
            let victim_casting = self.bot_casting_spell(victim).is_some();
            let off_gcd = self
                .lorik_state_mut(guid)
                .is_some_and(|s| s.global_cooldown_ms == 0);
            if off_gcd
                && victim_casting
                && self.do_cast_spell_if_can(
                    guid,
                    LORIK_SPELL_SHIELD_SLAM,
                    CastTarget::Unit(victim),
                )
            {
                if let Some(s) = self.lorik_state_mut(guid) {
                    s.shield_slam_timer_ms = 9000;
                    s.global_cooldown_ms = 1000;
                }
            }
        }
    }

