    /// `mob_yennikuAI::SpellHit` (no dispatcher yet: NO-DISPATCHER-YET).
    fn yenniku_spell_hit(&mut self, guid: ObjectGuid, caster: ObjectGuid, spell_id: u32) {
        let _ = caster;
        let pending = self
            .yenniku_state_mut(guid)
            .is_some_and(|s| !s.reset_pending);
        if !pending || spell_id != YENNIKU_SPELL_RELEASE {
            return;
        }
        // NEEDS-MAP-HELPER: `caster->GetTypeId() == TYPEID_PLAYER` +
        // `GetQuestStatus(592) == INCOMPLETE` player/quest gate (cpp 56).
        // NEEDS-MAP-HELPER: `UNIT_NPC_EMOTESTATE = EMOTE_STATE_STUN` write,
        // `CombatStop`, `DeleteThreatList`, `SetFactionTemplateId(83)`
        // horde generic (cpp 58-61).
        if let Some(s) = self.yenniku_state_mut(guid) {
            s.reset_pending = true;
            s.reset_timer_ms = YENNIKU_RESET_DELAY_MS;
        }
    }

    /// `mob_yennikuAI::UpdateAI`.
    fn yenniku_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let (pending, due) = self.yenniku_state_mut(guid).map_or((false, false), |s| {
            if s.reset_pending && s.reset_timer_ms < diff_ms {
                (true, true)
            } else {
                if s.reset_pending {
                    s.reset_timer_ms -= diff_ms;
                }
                (s.reset_pending, false)
            }
        });
        if !pending {
            // Fall through to the hostile head below.
        } else if due {
            self.enter_evade_mode(guid);
            if let Some(s) = self.yenniku_state_mut(guid) {
                s.reset_pending = false;
            }
            // NEEDS-MAP-HELPER: `SetFactionTemplateId(28)` troll/bloodscalp
            // (cpp 79).
            // Fork falls through to the hostile head (no return, cpp 86-87).
        } else {
            return;
        }
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
    }

