    /// `npc_witch_doctor_unbagwaAI::SummonedCreatureDespawn` (no dispatcher:
    /// NO-DISPATCHER-YET).
    fn unbagwa_summoned_creature_despawn(&mut self, guid: ObjectGuid) {
        let active = self.unbagwa_state_mut(guid).is_some_and(|s| s.start_event);
        if !active {
            return;
        }
        // NEEDS-MAP-HELPER: `pCreature->IsAlive()` despawned-creature liveness
        // gate (cpp 225); the dispatcher hands only the summoner guid.
        if let Some(s) = self.unbagwa_state_mut(guid) {
            s.reset_event = true;
            if s.attackers_count > 0 {
                s.attackers_count -= 1;
            }
            let reset = s.attackers_count == 0;
            if reset {
                // `ResetCreature()` inline (borrowed state already held).
                s.start_event = false;
                s.reset_event = false;
                s.wave_count = 1;
                s.attackers_count = 0;
                s.mob_wave_timer_ms = UNBAGWA_MOB_WAVE_DELAY_MS;
            }
        }
        // NEEDS-MAP-HELPER: questgiver-flag restore on the inline
        // `ResetCreature` path (see `unbagwa_reset_creature`).
    }

    /// `npc_witch_doctor_unbagwaAI::SummonedCreatureJustDied` (no dispatcher
    /// yet: NO-DISPATCHER-YET).
    fn unbagwa_summoned_creature_just_died(&mut self, guid: ObjectGuid) {
        let (active, wave, reset_event) =
            self.unbagwa_state_mut(guid).map_or((false, 0, false), |s| {
                (s.start_event, s.wave_count, s.reset_event)
            });
        if !active {
            return;
        }
        if let Some(s) = self.unbagwa_state_mut(guid) {
            if s.attackers_count > 0 {
                s.attackers_count -= 1;
            }
            if s.attackers_count == 0 && (reset_event || wave > UNBAGWA_MAX_WAVE_COUNT) {
                s.start_event = false;
                s.reset_event = false;
                s.wave_count = 1;
                s.attackers_count = 0;
                s.mob_wave_timer_ms = UNBAGWA_MOB_WAVE_DELAY_MS;
            }
        }
        // NEEDS-MAP-HELPER: questgiver-flag restore on the inline
        // `ResetCreature` path (see `unbagwa_reset_creature`).
    }

