    /// `boss_arlokkAI::Aggro`.
    fn arlokk_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        self.do_script_text(ARLOKK_SAY_AGGRO, guid, None, -1);
        self.set_in_combat_with_zone(guid);
        let me = self.unit_position(guid).unwrap_or_default();
        let door = self
            .gameobjects
            .iter()
            .filter(|(_, g)| g.info.id == ARLOKK_GO_FORCE_FIELD)
            .filter_map(|(g, _)| {
                self.object_position(*g).map(|p| {
                    let dx = p.x - me.x;
                    let dy = p.y - me.y;
                    (*g, dx * dx + dy * dy)
                })
            })
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .filter(|(_, d)| *d <= 100.0 * 100.0)
            .map(|(g, _)| g);
        if let Some(door) = door {
            self.use_door(door);
        }
    }

    /// `boss_arlokkAI::JustReachedHome` (no dispatcher: NO-DISPATCHER-YET).
    fn arlokk_just_reached_home(&mut self, guid: ObjectGuid) {
        let done = self.instance_get_data(ZG_TYPE_ARLOKK) == Some(DONE);
        if !done {
            self.instance_set_data(ZG_TYPE_ARLOKK, ZG_NOT_STARTED);
        }
        let me = self.unit_position(guid).unwrap_or_default();
        let find_go = |entry: u32| {
            self.gameobjects
                .iter()
                .filter(move |(_, g)| g.info.id == entry)
                .filter_map(|(g, _)| {
                    self.object_position(*g).map(|p| {
                        let dx = p.x - me.x;
                        let dy = p.y - me.y;
                        (*g, dx * dx + dy * dy)
                    })
                })
                .min_by(|a, b| a.1.total_cmp(&b.1))
                .filter(|(_, d)| *d <= 100.0 * 100.0)
                .map(|(g, _)| g)
        };
        if let Some(door) = find_go(ARLOKK_GO_FORCE_FIELD) {
            // NEEDS-MAP-HELPER: `ResetDoorOrButton` (cpp 148); only `use_door`
            // exists on `Map`.
            let _ = door;
        }
        if find_go(ARLOKK_GO_GONG).is_some() {
            // NEEDS-MAP-HELPER: `GameObject::Respawn` for the gong (cpp 150).
        }
        // Fork is summoned, so it despawns on reaching home.
        self.despawn_creature_now(guid, 0);
    }

    /// `boss_arlokkAI::JustDied`.
    fn arlokk_just_died(&mut self, guid: ObjectGuid) {
        self.do_script_text(ARLOKK_SAY_DEATH, guid, None, -1);
        self.cancel_aura(guid, ARLOKK_SPELL_PANTHER_TRANSFORM);
        // NEEDS-MAP-HELPER: `LeaveVanish` (cpp 160).
        // NEEDS-MAP-HELPER: `SetFloatValue(OBJECT_FIELD_SCALE_X, 1.0)`
        // (cpp 161).
        self.instance_set_data(ZG_TYPE_ARLOKK, DONE);
        let me = self.unit_position(guid).unwrap_or_default();
        let door = self
            .gameobjects
            .iter()
            .filter(|(_, g)| g.info.id == ARLOKK_GO_FORCE_FIELD)
            .filter_map(|(g, _)| {
                self.object_position(*g).map(|p| {
                    let dx = p.x - me.x;
                    let dy = p.y - me.y;
                    (*g, dx * dx + dy * dy)
                })
            })
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .filter(|(_, d)| *d <= 100.0 * 100.0)
            .map(|(g, _)| g);
        if let Some(door) = door {
            // NEEDS-MAP-HELPER: `ResetDoorOrButton` (cpp 166).
            let _ = door;
        }
        let _ = self.cast_spell(
            guid,
            ARLOKK_SPELL_HAKKAR_POWER_DOWN,
            CastTarget::SelfCast,
            CastOptions {
                triggered: true,
                skip_known: true,
                ..Default::default()
            },
        );
    }

    /// `boss_arlokkAI::DoSummonSinglePhanter`.
    fn arlokk_summon_single_phanter(
        &mut self,
        guid: ObjectGuid,
        x: f32,
        y: f32,
        z: f32,
        target: Option<ObjectGuid>,
    ) {
        let summoned = self.summon_creature(
            ARLOKK_NPC_ZULIAN_PROWLER,
            Position::new(x, y, z, 0.0),
            guid,
            ARLOKK_TEMPSUMMON_TIMED_OOC_DESPAWN,
            15_000,
        );
        if let (Some(summoned), Some(target)) = (summoned, target) {
            self.attack_start(summoned, target);
        }
    }

    /// `boss_arlokkAI::DoSummonPhanters`.
    fn arlokk_summon_phanters(&mut self, guid: ObjectGuid) {
        let marked = self
            .arlokk_state_mut(guid)
            .map_or(ObjectGuid::EMPTY, |s| s.marked_guid);
        let marked_alive = !marked.is_empty() && self.unit_is_alive(marked);
        let target = if marked_alive {
            Some(marked)
        } else {
            // NEEDS-MAP-HELPER: exact `SelectAttackingTarget(
            // ATTACKING_TARGET_RANDOM, 0)` top-threat exclusion semantics;
            // `select_random_hostile` is the pending helper (cpp 196).
            self.select_random_hostile(guid)
        };
        self.arlokk_summon_single_phanter(guid, -11_532.79, -1649.673, 41.48, target);
        self.arlokk_summon_single_phanter(guid, -11_532.99, -1606.484, 41.297_9, target);
    }

    /// `boss_arlokkAI::JustSummoned`.
    fn arlokk_just_summoned(&mut self, guid: ObjectGuid, created: ObjectGuid) {
        let marked = self
            .arlokk_state_mut(guid)
            .map_or(ObjectGuid::EMPTY, |s| s.marked_guid);
        if !marked.is_empty() && self.unit_is_alive(marked) {
            self.attack_start(created, marked);
            if let Some(s) = self.arlokk_state_mut(guid) {
                s.summon_count = s.summon_count.saturating_add(1);
            }
            return;
        }
        // NEEDS-MAP-HELPER: exact `SelectAttackingTarget(
        // ATTACKING_TARGET_RANDOM, 0)` semantics; `select_random_hostile` is
        // the pending helper (cpp 196).
        if let Some(target) = self.select_random_hostile(guid) {
            self.attack_start(created, target);
            if let Some(s) = self.arlokk_state_mut(guid) {
                s.summon_count = s.summon_count.saturating_add(1);
            }
            return;
        }
        self.despawn_creature_now(created, 0);
        self.enter_evade_mode(guid);
    }

    /// `boss_arlokkAI::UpdateAI`.
    #[allow(clippy::too_many_lines)]
    fn arlokk_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let (phase_two, vanished) = self
            .arlokk_state_mut(guid)
            .map_or((false, false), |s| (s.phase_two, s.vanished));
        if !phase_two && !vanished {
            // P1: troll.
            let due = {
                let Some(s) = self.arlokk_state_mut(guid) else {
                    return;
                };
                if s.shadow_word_pain_timer_ms < diff_ms {
                    true
                } else {
                    s.shadow_word_pain_timer_ms -= diff_ms;
                    false
                }
            };
            if due
                && self.do_cast_spell_if_can(
                    guid,
                    ARLOKK_SPELL_SHADOWWORDPAIN,
                    CastTarget::Unit(victim),
                )
                && let Some(s) = self.arlokk_state_mut(guid)
            {
                s.shadow_word_pain_timer_ms = 15_000;
            }
            let due = {
                let Some(s) = self.arlokk_state_mut(guid) else {
                    return;
                };
                if s.backstab_timer_ms < diff_ms {
                    true
                } else {
                    s.backstab_timer_ms -= diff_ms;
                    false
                }
            };
            if due
                && self.do_cast_spell_if_can(guid, ARLOKK_SPELL_BACKSTAB, CastTarget::Unit(victim))
            {
                let next = self.rng.urand(6000, 12_000);
                if let Some(s) = self.arlokk_state_mut(guid) {
                    s.backstab_timer_ms = next;
                }
            }
            let due = {
                let Some(s) = self.arlokk_state_mut(guid) else {
                    return;
                };
                if s.mark_timer_ms < diff_ms {
                    true
                } else {
                    s.mark_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                // NEEDS-MAP-HELPER: exact `SelectAttackingTarget(
                // ATTACKING_TARGET_RANDOM, 0)` semantics; `select_random_hostile`
                // is the pending helper (cpp 232).
                if let Some(target) = self.select_random_hostile(guid) {
                    let old_marked = self
                        .arlokk_state_mut(guid)
                        .map_or(ObjectGuid::EMPTY, |s| s.marked_guid);
                    if !old_marked.is_empty() {
                        self.cancel_aura(old_marked, ARLOKK_SPELL_MARK);
                    }
                    // NEEDS-MAP-HELPER: `GetCharmerOrOwnerPlayerOrPlayerItself`
                    // player resolution (cpp 238).
                    if self.do_cast_spell_if_can(guid, ARLOKK_SPELL_MARK, CastTarget::Unit(target))
                    {
                        if let Some(s) = self.arlokk_state_mut(guid) {
                            s.marked_guid = target;
                            s.mark_timer_ms = 15_000;
                        }
                        self.do_script_text(ARLOKK_SAY_FEAST_PANTHER, guid, Some(target), -1);
                    }
                } else {
                    // NEEDS-MAP-HELPER: fork `sLog` error line (cpp 252);
                    // no log helper on `Map`.
                    if let Some(s) = self.arlokk_state_mut(guid) {
                        if !s.marked_guid.is_empty() {
                            s.marked_guid = ObjectGuid::EMPTY;
                        }
                    }
                }
            }
        } else if !vanished {
            // P2: panther.
            let due = {
                let Some(s) = self.arlokk_state_mut(guid) else {
                    return;
                };
                if s.thrash_timer_ms < diff_ms {
                    true
                } else {
                    s.thrash_timer_ms -= diff_ms;
                    false
                }
            };
            if due && self.do_cast_spell_if_can(guid, ARLOKK_SPELL_ROSSER, CastTarget::Unit(victim))
            {
                let next = self.rng.urand(5000, 9000);
                if let Some(s) = self.arlokk_state_mut(guid) {
                    s.thrash_timer_ms = next;
                }
            }
            // Ravage (fork uses `<=`, cpp 270).
            let due = {
                let Some(s) = self.arlokk_state_mut(guid) else {
                    return;
                };
                if s.ravage_timer_ms <= diff_ms {
                    true
                } else {
                    s.ravage_timer_ms -= diff_ms;
                    false
                }
            };
            if due
                && self.do_cast_spell_if_can(guid, ARLOKK_SPELL_RAVAGE, CastTarget::Unit(victim))
                && let Some(s) = self.arlokk_state_mut(guid)
            {
                s.ravage_timer_ms = 16_000;
            }
            let due = {
                let Some(s) = self.arlokk_state_mut(guid) else {
                    return;
                };
                if s.gouge_timer_ms < diff_ms {
                    true
                } else {
                    s.gouge_timer_ms -= diff_ms;
                    false
                }
            };
            if due && self.do_cast_spell_if_can(guid, ARLOKK_SPELL_GOUGE, CastTarget::Unit(victim))
            {
                if self.threat_on(guid, victim) > 0.0 {
                    self.modify_threat_percent_of(guid, victim, -80);
                }
                let next = self.rng.urand(17_000, 27_000);
                if let Some(s) = self.arlokk_state_mut(guid) {
                    s.gouge_timer_ms = next;
                }
            }
            let due = {
                let Some(s) = self.arlokk_state_mut(guid) else {
                    return;
                };
                if s.tourbillon_timer_ms < diff_ms {
                    true
                } else {
                    s.tourbillon_timer_ms -= diff_ms;
                    false
                }
            };
            if due
                && self.do_cast_spell_if_can(
                    guid,
                    ARLOKK_SPELL_TOURBILLON,
                    CastTarget::Unit(victim),
                )
                && let Some(s) = self.arlokk_state_mut(guid)
            {
                s.tourbillon_timer_ms = 16_000;
            }
        }
        // Panther summons (both phases while under the cap).
        let summon_count = self
            .arlokk_state_mut(guid)
            .map_or(u32::MAX, |s| s.summon_count);
        if summon_count < ARLOKK_MAX_PANTHER_COUNT {
            let due = {
                let Some(s) = self.arlokk_state_mut(guid) else {
                    return;
                };
                if s.summon_timer_ms < diff_ms {
                    true
                } else {
                    s.summon_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                self.arlokk_summon_phanters(guid);
                if let Some(s) = self.arlokk_state_mut(guid) {
                    s.summon_timer_ms = 5000;
                }
            }
        }
        // Troll -> Vanish.
        let vanish_due = {
            let Some(s) = self.arlokk_state_mut(guid) else {
                return;
            };
            if s.vanish_timer_ms < diff_ms {
                true
            } else {
                s.vanish_timer_ms -= diff_ms;
                false
            }
        };
        if vanish_due {
            self.cancel_aura(guid, ARLOKK_SPELL_PANTHER_TRANSFORM);
            // NEEDS-MAP-HELPER: `EnterVanish` (cpp 320).
            let next = self.rng.urand(35_000, 50_000);
            if let Some(s) = self.arlokk_state_mut(guid) {
                s.vanished = true;
                s.visible_timer_ms = next;
                s.vanish_timer_ms = ARLOKK_DISABLE_TIMER;
            }
        }
        let vanished = self.arlokk_state_mut(guid).is_some_and(|s| s.vanished);
        if vanished {
            // Vanish -> Panther.
            let due = {
                let Some(s) = self.arlokk_state_mut(guid) else {
                    return;
                };
                if s.visible_timer_ms < diff_ms {
                    true
                } else {
                    s.visible_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                let _ = self.cast_spell(
                    guid,
                    ARLOKK_SPELL_PANTHER_TRANSFORM,
                    CastTarget::SelfCast,
                    CastOptions {
                        triggered: false,
                        skip_known: true,
                        ..Default::default()
                    },
                );
                // NEEDS-MAP-HELPER: `SetFloatValue(OBJECT_FIELD_SCALE_X, 1.7)`
                // + `GetDefaultDamageRange`/`SetBaseWeaponDamage(+35%)`/
                // `UpdateDamagePhysical` (cpp 338-345).
                // NEEDS-MAP-HELPER: exact `SelectAttackingTarget(
                // ATTACKING_TARGET_RANDOM, 0)` semantics; `select_random_hostile`
                // is the pending helper (cpp 348).
                let vanish_target = self.select_random_hostile(guid);
                // NEEDS-MAP-HELPER: `LeaveVanish` + `Ambush(target,
                // SPELL_BACKSTAB)` (cpp 349-350).
                let _ = vanish_target;
                if let Some(s) = self.arlokk_state_mut(guid) {
                    s.phase_two = true;
                    s.vanished = false;
                    s.switch_to_troll_timer_ms = 45_000;
                    s.vanish_timer_ms = 45_000 + 30_000;
                }
            }
        }
        // Panther -> Troll after 45s in panther form.
        let (phase_two, troll_due) = self.arlokk_state_mut(guid).map_or((false, false), |s| {
            if s.phase_two && s.switch_to_troll_timer_ms < diff_ms {
                (true, true)
            } else {
                if s.phase_two {
                    s.switch_to_troll_timer_ms -= diff_ms;
                }
                (s.phase_two, false)
            }
        });
        if phase_two && troll_due {
            self.cancel_aura(guid, ARLOKK_SPELL_PANTHER_TRANSFORM);
            if let Some(s) = self.arlokk_state_mut(guid) {
                s.phase_two = false;
                s.switch_to_troll_timer_ms = ARLOKK_DISABLE_TIMER;
            }
        }
    }

    fn prowler_state_mut(&mut self, guid: ObjectGuid) -> Option<&mut ProwlerAi> {
        match &mut self.ai.get_mut(&guid)?.script {
            Some(CreatureScriptAi::Prowler(s)) => Some(s),
            _ => None,
        }
    }

    /// `mob_prowlerAI::GetArlokkAI` (cross-AI lookup by nearest Arlokk).
    fn prowler_arlokk(&mut self, guid: ObjectGuid) -> Option<ObjectGuid> {
        let cached = self
            .prowler_state_mut(guid)
            .map_or(ObjectGuid::EMPTY, |s| s.arlokk_guid);
        if !cached.is_empty() && self.unit_is_alive(cached) {
            return Some(cached);
        }
        let me = self.unit_position(guid).unwrap_or_default();
        let found = self
            .creatures
            .iter()
            .filter(|(_, c)| c.info.entry == ZG_NPC_ARLOKK)
            .filter_map(|(g, _)| {
                self.object_position(*g).map(|p| {
                    let dx = p.x - me.x;
                    let dy = p.y - me.y;
                    (*g, dx * dx + dy * dy)
                })
            })
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .filter(|(_, d)| *d <= 100.0 * 100.0)
            .map(|(g, _)| g);
        if let Some(found) = found
            && self.unit_is_alive(found)
        {
            if let Some(s) = self.prowler_state_mut(guid) {
                s.arlokk_guid = found;
            }
            return Some(found);
        }
        None
    }

    /// `mob_prowlerAI::Reset`.
    fn prowler_reset(&mut self, guid: ObjectGuid) {
        self.do_cast_spell_if_can(guid, ARLOKK_PROWLER_SPELL_SELF_VISUAL, CastTarget::SelfCast);
        let thrash = self.rng.urand(5000, 9000);
        if let Some(s) = self.prowler_state_mut(guid) {
            s.thrash_timer_ms = thrash;
            s.update_target_timer_ms = 2000;
        }
    }

    /// `mob_prowlerAI::JustDied`.
    fn prowler_just_died(&mut self, guid: ObjectGuid) {
        if let Some(arlokk) = self.prowler_arlokk(guid)
            && let Some(s) = self.arlokk_state_mut(arlokk)
        {
            s.summon_count = s.summon_count.saturating_sub(1);
        }
    }

    /// `mob_prowlerAI::UpdateAI`.
    fn prowler_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Retarget timer (fork uses `<=`, cpp 416).
        let due = {
            let Some(s) = self.prowler_state_mut(guid) else {
                return;
            };
            if s.update_target_timer_ms <= diff_ms {
                true
            } else {
                s.update_target_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            let Some(arlokk) = self.prowler_arlokk(guid) else {
                self.despawn_creature_now(guid, 0);
                return;
            };
            let marked = self
                .arlokk_state_mut(arlokk)
                .map_or(ObjectGuid::EMPTY, |s| s.marked_guid);
            if let Some(victim) = self.unit_victim(guid)
                && self.threat_on(guid, victim) > 0.0
            {
                self.modify_threat_percent_of(guid, victim, -100);
            }
            if !marked.is_empty() {
                self.attack_start(guid, marked);
                self.do_cast_spell_if_can(
                    guid,
                    ARLOKK_PROWLER_SPELL_SELF_VISUAL,
                    CastTarget::SelfCast,
                );
            }
            if let Some(s) = self.prowler_state_mut(guid) {
                s.update_target_timer_ms = 2000;
            }
        }
        // Thrash (fork uses `<=`, cpp 440).
        let due = {
            let Some(s) = self.prowler_state_mut(guid) else {
                return;
            };
            if s.thrash_timer_ms <= diff_ms {
                true
            } else {
                s.thrash_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // Fork `DoCast(m_creature, SPELL_ROSSER)` (non-checking self cast).
            let _ = self.cast_spell(
                guid,
                ARLOKK_SPELL_ROSSER,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: false,
                    skip_known: true,
                    ..Default::default()
                },
            );
            let next = self.rng.urand(5000, 9000);
            if let Some(s) = self.prowler_state_mut(guid) {
                s.thrash_timer_ms = next;
            }
        }
    }

    fn gahzranka_state_mut(&mut self, guid: ObjectGuid) -> Option<&mut GahzrankaAi> {
        match &mut self.ai.get_mut(&guid)?.script {
            Some(CreatureScriptAi::Gahzranka(s)) => Some(s),
            _ => None,
        }
    }

    /// `boss_gahzrankaAI::Reset`.
    fn gahzranka_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.gahzranka_state_mut(guid) {
            s.frostbreath_timer_ms = 8000;
            s.massive_geyser_timer_ms = 25_000;
            s.slam_timer_ms = 17_000;
        }
        if self.instance_get_data(ZG_TYPE_GAHZRANKA) != Some(DONE) {
            self.instance_set_data(ZG_TYPE_GAHZRANKA, ZG_NOT_STARTED);
        }
    }

    /// `boss_gahzrankaAI::CheckSpawnStatus` (ctor + `JustRespawned`).
    fn gahzranka_check_spawn_status(&mut self, guid: ObjectGuid) {
        if self.instance_get_data(ZG_TYPE_GAHZRANKA) == Some(IN_PROGRESS) {
            self.creature_move_point(
                guid,
                0,
                Position::new(-11_709.34, -1749.965, 8.733, 5.347_8),
                0,
                0.0,
                0.0,
            );
            // NEEDS-MAP-HELPER: `SetHomePosition(-11688.95, -1777.21, 12.593,
            // 5.81)` (cpp 94); no home writer on `Map`.
        } else {
            // `DisappearAndDie` + `SetRespawnTime(259200)`.
            self.despawn_creature_now(guid, 259_200);
        }
    }

    /// `boss_gahzrankaAI::Aggro`.
    fn gahzranka_aggro(&mut self, _guid: ObjectGuid, _who: ObjectGuid) {
        self.instance_set_data(ZG_TYPE_GAHZRANKA, IN_PROGRESS);
    }

    /// `boss_gahzrankaAI::JustDied`.
    fn gahzranka_just_died(&mut self, _guid: ObjectGuid) {
        self.instance_set_data(ZG_TYPE_GAHZRANKA, DONE);
    }

    /// `boss_gahzrankaAI::JustRespawned` (no dispatcher: NO-DISPATCHER-YET).
    fn gahzranka_just_respawned(&mut self, guid: ObjectGuid) {
        self.gahzranka_check_spawn_status(guid);
    }

    /// `boss_gahzrankaAI::MovementInform`.
    fn gahzranka_movement_inform(&mut self, guid: ObjectGuid, point_id: u32) {
        // Fork gates on `uiType != POINT_MOTION_TYPE`; the dispatcher hands
        // only point motion.
        if point_id == 0 {
            self.creature_move_point(
                guid,
                1,
                Position::new(-11_688.95, -1777.21, 12.593, 5.81),
                0,
                0.0,
                0.0,
            );
        }
    }

    /// `boss_gahzrankaAI::UpdateAI`.
    fn gahzranka_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let due = {
            let Some(s) = self.gahzranka_state_mut(guid) else {
                return;
            };
            if s.frostbreath_timer_ms < diff_ms {
                true
            } else {
                s.frostbreath_timer_ms -= diff_ms;
                false
            }
        };
        if due
            && self.do_cast_spell_if_can(
                guid,
                GAHZRANKA_SPELL_FROSTBREATH,
                CastTarget::Unit(victim),
            )
        {
            let next = self.rng.urand(8000, 20_000);
            if let Some(s) = self.gahzranka_state_mut(guid) {
                s.frostbreath_timer_ms = next;
            }
        }
        let due = {
            let Some(s) = self.gahzranka_state_mut(guid) else {
                return;
            };
            if s.massive_geyser_timer_ms < diff_ms {
                true
            } else {
                s.massive_geyser_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: exact `SelectAttackingTarget(
            // ATTACKING_TARGET_RANDOM, 0)` semantics; `select_random_hostile`
            // is the pending helper (cpp 125).
            if let Some(target) = self.select_random_hostile(guid) {
                if self.do_cast_spell_if_can(
                    guid,
                    GAHZRANKA_SPELL_MASSIVEGEYSER,
                    CastTarget::Unit(target),
                ) {
                    let next = self.rng.urand(16_000, 24_000);
                    if let Some(s) = self.gahzranka_state_mut(guid) {
                        s.massive_geyser_timer_ms = next;
                    }
                    // NEEDS-MAP-HELPER: `DoResetThreat` (cpp 130); no
                    // threat-wipe helper on `Map`.
                }
            }
        }
        let due = {
            let Some(s) = self.gahzranka_state_mut(guid) else {
                return;
            };
            if s.slam_timer_ms < diff_ms {
                true
            } else {
                s.slam_timer_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, GAHZRANKA_SPELL_SLAM, CastTarget::Unit(victim)) {
            let next = self.rng.urand(12_000, 20_000);
            if let Some(s) = self.gahzranka_state_mut(guid) {
                s.slam_timer_ms = next;
            }
        }
    }

