    /// `boss_hakkarAI::UpdateAI`.
    #[allow(clippy::too_many_lines)]
    fn hakkar_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if self.zul_gurub().is_none() {
            return;
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Exploit guard (cpp 141-145): z outside [45.8, 57.28] evades.
        let z = self.unit_position(guid).map_or(50.0, |p| p.z);
        if z > 57.28 || z < 45.8 {
            self.enter_evade_mode(guid);
            return;
        }
        // Insanity restore check (CC delay gate).
        let cc_due = {
            let Some(s) = self.hakkar_state_mut(guid) else {
                return;
            };
            if s.cc_delay_insanity_timer_ms < diff_ms {
                true
            } else {
                s.cc_delay_insanity_timer_ms -= diff_ms;
                false
            }
        };
        if cc_due {
            let insane = self
                .hakkar_state_mut(guid)
                .map_or(ObjectGuid::EMPTY, |s| s.insane_player_guid);
            if !insane.is_empty() {
                // NEEDS-MAP-HELPER: `GetMap()->GetPlayer` typed player lookup
                // (cpp 151). Fork restores saved threat when the aura lapses
                // (`modifyThreatPercent(-100)` + `addThreatDirectly`) and only
                // clears here when the player is gone; transcribed as
                // clear-only until the lookup lands.
                if let Some(s) = self.hakkar_state_mut(guid) {
                    s.insane_player_guid = ObjectGuid::EMPTY;
                    s.insane_player_aggro = 0.0;
                }
            }
        }
        if self.bot_casting_spell(guid).is_some() {
            return;
        }
        // Blood Siphon stun on self.
        let due = {
            let Some(s) = self.hakkar_state_mut(guid) else {
                return;
            };
            if s.bloodsiphon_timer_ms < diff_ms {
                true
            } else {
                s.bloodsiphon_timer_ms -= diff_ms;
                false
            }
        };
        if due
            && self.do_cast_spell_if_can(guid, HAKKAR_SPELL_BLOODSIPHON_STUN, CastTarget::SelfCast)
            && let Some(s) = self.hakkar_state_mut(guid)
        {
            s.bloodsiphon_timer_ms = 90_000;
        }
        // Corrupted Blood on a random target.
        let due = {
            let Some(s) = self.hakkar_state_mut(guid) else {
                return;
            };
            if s.corrupted_blood_timer_ms < diff_ms {
                true
            } else {
                s.corrupted_blood_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: exact `SelectAttackingTarget(
            // ATTACKING_TARGET_RANDOM, 0)` semantics; `select_random_hostile`
            // is the pending helper (cpp 188).
            if let Some(target) = self.select_random_hostile(guid) {
                if self.do_cast_spell_if_can(
                    guid,
                    HAKKAR_SPELL_CORRUPTEDBLOOD,
                    CastTarget::Unit(target),
                ) {
                    let next = self.rng.urand(14_000, 16_000);
                    if let Some(s) = self.hakkar_state_mut(guid) {
                        s.corrupted_blood_timer_ms = next;
                    }
                }
            }
        }
        // Cause Insanity on the victim.
        let due = {
            let Some(s) = self.hakkar_state_mut(guid) else {
                return;
            };
            if s.cause_insanity_timer_ms < diff_ms {
                true
            } else {
                s.cause_insanity_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            let aggro = self.threat_on(guid, victim);
            if let Some(s) = self.hakkar_state_mut(guid) {
                s.insane_player_guid = victim;
                s.insane_player_aggro = aggro;
            }
            if self.do_cast_spell_if_can(guid, HAKKAR_SPELL_CAUSEINSANITY, CastTarget::Unit(victim))
            {
                // `DoScriptText(SAY_FLEEING, ...)` is commented out (cpp 208).
                let next = self.rng.urand(20_000, 25_000);
                if let Some(s) = self.hakkar_state_mut(guid) {
                    s.cc_delay_insanity_timer_ms = 4000;
                    s.cause_insanity_timer_ms = next;
                }
            }
        }
        // Berserk (fork has no 5% enrage gate active; `Enraged` unused).
        let due = {
            let Some(s) = self.hakkar_state_mut(guid) else {
                return;
            };
            if s.berserk_timer_ms < diff_ms {
                true
            } else {
                s.berserk_timer_ms -= diff_ms;
                false
            }
        };
        if due
            // `CF_AURA_NOT_PRESENT` has no cast option; the re-cast lands on
            // the 2000ms retry while the aura persists (cpp 220).
            && self.do_cast_spell_if_can(guid, HAKKAR_SPELL_BERSERK, CastTarget::SelfCast)
            && let Some(s) = self.hakkar_state_mut(guid)
        {
            s.berserk_timer_ms = 2000;
        }
        // Aspect of Jeklik (victim) while Jeklik lives.
        if self.instance_get_data(ZG_TYPE_JEKLIK) != Some(DONE) {
            let due = {
                let Some(s) = self.hakkar_state_mut(guid) else {
                    return;
                };
                if s.aspect_of_jeklik_timer_ms < diff_ms {
                    true
                } else {
                    s.aspect_of_jeklik_timer_ms -= diff_ms;
                    false
                }
            };
            if due
                && self.do_cast_spell_if_can(
                    guid,
                    HAKKAR_SPELL_ASPECT_OF_JEKLIK,
                    CastTarget::Unit(victim),
                )
            {
                let next = self.rng.urand(10_000, 14_000);
                if let Some(s) = self.hakkar_state_mut(guid) {
                    s.aspect_of_jeklik_timer_ms = next;
                }
            }
        }
        // Aspect of Venoxis (victim) while Venoxis lives.
        if self.instance_get_data(ZG_TYPE_VENOXIS) != Some(DONE) {
            let due = {
                let Some(s) = self.hakkar_state_mut(guid) else {
                    return;
                };
                if s.aspect_of_venoxis_timer_ms < diff_ms {
                    true
                } else {
                    s.aspect_of_venoxis_timer_ms -= diff_ms;
                    false
                }
            };
            if due
                && self.do_cast_spell_if_can(
                    guid,
                    HAKKAR_SPELL_ASPECT_OF_VENOXIS,
                    CastTarget::Unit(victim),
                )
                && let Some(s) = self.hakkar_state_mut(guid)
            {
                s.aspect_of_venoxis_timer_ms = 8000;
            }
        }
        // Aspect of Marli (victim) while Marli lives.
        if self.instance_get_data(ZG_TYPE_MARLI) != Some(DONE) {
            let due = {
                let Some(s) = self.hakkar_state_mut(guid) else {
                    return;
                };
                if s.aspect_of_marli_timer_ms < diff_ms {
                    true
                } else {
                    s.aspect_of_marli_timer_ms -= diff_ms;
                    false
                }
            };
            if due
                && self.do_cast_spell_if_can(
                    guid,
                    HAKKAR_SPELL_ASPECT_OF_MARLI,
                    CastTarget::Unit(victim),
                )
                && let Some(s) = self.hakkar_state_mut(guid)
            {
                s.aspect_of_marli_timer_ms = 10_000;
            }
        }
        // Aspect of Thekal (self) while Thekal lives.
        if self.instance_get_data(ZG_TYPE_THEKAL) != Some(DONE) {
            let due = {
                let Some(s) = self.hakkar_state_mut(guid) else {
                    return;
                };
                if s.aspect_of_thekal_timer_ms < diff_ms {
                    true
                } else {
                    s.aspect_of_thekal_timer_ms -= diff_ms;
                    false
                }
            };
            if due
                && self.do_cast_spell_if_can(
                    guid,
                    HAKKAR_SPELL_ASPECT_OF_THEKAL,
                    CastTarget::SelfCast,
                )
                && let Some(s) = self.hakkar_state_mut(guid)
            {
                s.aspect_of_thekal_timer_ms = 15_000;
            }
        }
        // Aspect of Arlokk (self) while Arlokk lives.
        if self.instance_get_data(ZG_TYPE_ARLOKK) != Some(DONE) {
            let due = {
                let Some(s) = self.hakkar_state_mut(guid) else {
                    return;
                };
                if s.aspect_of_arlokk_timer_ms < diff_ms {
                    true
                } else {
                    s.aspect_of_arlokk_timer_ms -= diff_ms;
                    false
                }
            };
            if due
                && self.do_cast_spell_if_can(
                    guid,
                    HAKKAR_SPELL_ASPECT_OF_ARLOKK,
                    CastTarget::SelfCast,
                )
            {
                let next = self.rng.urand(10_000, 15_000);
                if let Some(s) = self.hakkar_state_mut(guid) {
                    s.aspect_of_arlokk_timer_ms = next;
                }
            }
        }
    }

