    /// `boss_jeklikAI::Aggro` (ends with the `ScriptedAI::Aggro` base call).
    fn jeklik_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        if let Some(u) = self.unit_base_mut(guid) {
            u.add_unit_state(mangos_entities::unit::UNIT_STATE_IGNORE_PATHFINDING);
        }
        self.do_script_text(JEKLIK_SAY_AGGRO, guid, None, -1);
        self.apply_aura_by_id(guid, JEKLIK_SPELL_BAT_FORM, guid);
        // NEEDS-MAP-HELPER: `SetFly(true)` + `SetObjectScale(2.0)` (cpp 122-123).
        self.instance_set_data(ZG_TYPE_JEKLIK, IN_PROGRESS);
    }

