    /// `boss_jeklikAI::UpdateAI`.
    #[allow(clippy::too_many_lines)]
    fn jeklik_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if self.zul_gurub().is_none() {
            return;
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Phase transition at 50% (fork order: before everything else).
        if !self.jeklik_state_mut(guid).is_some_and(|s| s.phase_two)
            && self.creature_health_percent(guid) < 50.0
        {
            if let Some(ai) = self.ai.get_mut(&guid) {
                ai.invincibility_hp = 0;
            }
            self.cancel_aura(guid, JEKLIK_SPELL_BAT_FORM);
            // NEEDS-MAP-HELPER: `SetFly(false)` + `SetObjectScale(1.5)`
            // (cpp 157-158).
            // NEEDS-MAP-HELPER: `DoResetThreat` (cpp 159).
            if let Some(s) = self.jeklik_state_mut(guid) {
                s.phase_two = true;
            }
        }
        let phase_two = self.jeklik_state_mut(guid).is_some_and(|s| s.phase_two);
        if !phase_two && self.creature_health_percent(guid) > 50.0 {
            let due = {
                let Some(s) = self.jeklik_state_mut(guid) else {
                    return;
                };
                if s.spawn_bats_timer_ms < diff_ms {
                    true
                } else {
                    s.spawn_bats_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                self.do_script_text(JEKLIK_TEXT_SUMMON_BATS, guid, None, -1);
                for _ in 0..6 {
                    let jx = self.rng.frand(0.0, 5.0);
                    let jy = self.rng.frand(0.0, 5.0);
                    let summoned = self.summon_creature(
                        JEKLIK_NPC_CAVE_BAT,
                        Position::new(-12_294.0 + jx, -1382.0 + jy, 144.830_4, 5.483),
                        guid,
                        JEKLIK_TEMPSUMMON_TIMED_OOC_DESPAWN,
                        15_000,
                    );
                    // NEEDS-MAP-HELPER: exact `SelectAttackingTarget(
                    // ATTACKING_TARGET_RANDOM, 0)` semantics;
                    // `select_random_hostile` is the pending helper (cpp 174).
                    if let (Some(summoned), Some(target)) =
                        (summoned, self.select_random_hostile(guid))
                    {
                        self.attack_start(summoned, target);
                    }
                }
                if let Some(s) = self.jeklik_state_mut(guid) {
                    s.spawn_bats_timer_ms = 65_000;
                }
            }
        }
        if phase_two {
            let due = {
                let Some(s) = self.jeklik_state_mut(guid) else {
                    return;
                };
                if s.spawn_flying_bats_timer_ms < diff_ms {
                    true
                } else {
                    s.spawn_flying_bats_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                // NEEDS-MAP-HELPER: exact `SelectAttackingTarget(
                // ATTACKING_TARGET_RANDOM, 0)` semantics; `select_random_hostile`
                // is the pending helper (cpp 189).
                if let Some(target) = self.select_random_hostile(guid) {
                    let pos = self.unit_position(target).unwrap_or_default();
                    let summoned = self.summon_creature(
                        JEKLIK_NPC_FLYING_BAT,
                        Position::new(pos.x, pos.y, pos.z + 15.0, 0.0),
                        guid,
                        JEKLIK_TEMPSUMMON_TIMED_OOC_DESPAWN,
                        1_800_000,
                    );
                    if let Some(summoned) = summoned {
                        self.attack_start(summoned, target);
                        self.do_script_text(JEKLIK_SAY_RAIN_FIRE, guid, None, -1);
                    }
                }
                if let Some(s) = self.jeklik_state_mut(guid) {
                    s.spawn_flying_bats_timer_ms = 10_000;
                }
            }
        }
        if self.bot_casting_spell(guid).is_some() {
            if let Some(s) = self.jeklik_state_mut(guid) {
                s.diff_add_ms += diff_ms;
            }
            return;
        }
        // Global cooldown gate (fork adds the casting overflow to `diff`).
        let global = self
            .jeklik_state_mut(guid)
            .map_or(0, |s| s.global_cooldown_ms);
        if global > diff_ms {
            if let Some(s) = self.jeklik_state_mut(guid) {
                s.diff_add_ms += diff_ms;
                s.global_cooldown_ms -= diff_ms;
            }
            return;
        }
        let (diff_add, _) = self
            .jeklik_state_mut(guid)
            .map_or((0, 0), |s| (s.diff_add_ms, s.global_cooldown_ms));
        let diff = diff_add + diff_ms;
        if let Some(s) = self.jeklik_state_mut(guid) {
            s.diff_add_ms = 0;
            s.skill_started = false;
        }
        let phase_two = self.jeklik_state_mut(guid).is_some_and(|s| s.phase_two);
        if phase_two {
            // Shadow Word: Pain (random).
            let due = {
                let Some(s) = self.jeklik_state_mut(guid) else {
                    return;
                };
                if s.shadow_word_pain_timer_ms < diff {
                    true
                } else {
                    s.shadow_word_pain_timer_ms -= diff;
                    false
                }
            };
            if due {
                let started = self.jeklik_state_mut(guid).is_some_and(|s| s.skill_started);
                if !started {
                    // NEEDS-MAP-HELPER: exact `SelectAttackingTarget(
                    // ATTACKING_TARGET_RANDOM, 0)` semantics;
                    // `select_random_hostile` is the pending helper (cpp 318).
                    if let Some(target) = self.select_random_hostile(guid) {
                        if self.do_cast_spell_if_can(
                            guid,
                            JEKLIK_SPELL_SHADOW_WORD_PAIN,
                            CastTarget::Unit(target),
                        ) {
                            let next = self.rng.urand(8000, 12_000);
                            if let Some(s) = self.jeklik_state_mut(guid) {
                                s.shadow_word_pain_timer_ms = next;
                                s.global_cooldown_ms = 1000;
                                s.skill_started = true;
                            }
                        }
                    }
                }
            }
            // Great Heal (self).
            let due = {
                let Some(s) = self.jeklik_state_mut(guid) else {
                    return;
                };
                if s.great_heal_timer_ms < diff {
                    true
                } else {
                    s.great_heal_timer_ms -= diff;
                    false
                }
            };
            if due {
                let started = self.jeklik_state_mut(guid).is_some_and(|s| s.skill_started);
                if !started {
                    // NEEDS-MAP-HELPER: `InterruptNonMeleeSpells(false)`
                    // (cpp 337).
                    if self.do_cast_spell_if_can(
                        guid,
                        JEKLIK_SPELL_GREAT_HEAL,
                        CastTarget::SelfCast,
                    ) {
                        self.do_script_text(JEKLIK_TEXT_GREAT_HEAL, guid, None, -1);
                        let next = self.rng.urand(20_000, 25_000);
                        if let Some(s) = self.jeklik_state_mut(guid) {
                            s.skill_started = true;
                            s.great_heal_timer_ms = next;
                        }
                    }
                }
            }
            // Mind Flay (random).
            let due = {
                let Some(s) = self.jeklik_state_mut(guid) else {
                    return;
                };
                if s.mind_flay_timer_ms < diff {
                    true
                } else {
                    s.mind_flay_timer_ms -= diff;
                    false
                }
            };
            if due {
                let started = self.jeklik_state_mut(guid).is_some_and(|s| s.skill_started);
                if !started {
                    // NEEDS-MAP-HELPER: `InterruptNonMeleeSpells(false)`
                    // (cpp 354) + exact random-target semantics (cpp 355).
                    if let Some(target) = self.select_random_hostile(guid) {
                        if self.do_cast_spell_if_can(
                            guid,
                            JEKLIK_SPELL_MIND_FLAY,
                            CastTarget::Unit(target),
                        ) {
                            let next = self.rng.urand(25_000, 30_000);
                            if let Some(s) = self.jeklik_state_mut(guid) {
                                s.mind_flay_timer_ms = next;
                                s.skill_started = true;
                            }
                        }
                    }
                }
            }
            // Curse of Blood (random).
            let due = {
                let Some(s) = self.jeklik_state_mut(guid) else {
                    return;
                };
                if s.curse_of_blood_timer_ms < diff {
                    true
                } else {
                    s.curse_of_blood_timer_ms -= diff;
                    false
                }
            };
            if due {
                let started = self.jeklik_state_mut(guid).is_some_and(|s| s.skill_started);
                if !started {
                    // NEEDS-MAP-HELPER: `InterruptNonMeleeSpells(false)`
                    // (cpp 373) + exact random-target semantics (cpp 374).
                    if let Some(target) = self.select_random_hostile(guid) {
                        if self.do_cast_spell_if_can(
                            guid,
                            JEKLIK_SPELL_CURSE_OF_BLOOD,
                            CastTarget::Unit(target),
                        ) {
                            let next = self.rng.urand(25_000, 30_000);
                            if let Some(s) = self.jeklik_state_mut(guid) {
                                s.curse_of_blood_timer_ms = next;
                                s.skill_started = true;
                            }
                        }
                    }
                }
            }
        } else {
            // Charge: nearest-victim charge 10-40yd.
            let due = {
                let Some(s) = self.jeklik_state_mut(guid) else {
                    return;
                };
                if s.charge_timer_ms < diff {
                    true
                } else {
                    s.charge_timer_ms -= diff;
                    false
                }
            };
            if due {
                let started = self.jeklik_state_mut(guid).is_some_and(|s| s.skill_started);
                if !started {
                    // NEEDS-MAP-HELPER: `CastSpellOnNearestVictim(24408, 10,
                    // 40)` (cpp 231); no nearest-victim cast helper.
                    // Fork retry gate: success -> 15-30s, else 2s (cpp 234-238).
                    if let Some(s) = self.jeklik_state_mut(guid) {
                        s.charge_timer_ms = 2000;
                    }
                }
            }
            // Screech.
            let due = {
                let Some(s) = self.jeklik_state_mut(guid) else {
                    return;
                };
                if s.screech_timer_ms < diff {
                    true
                } else {
                    s.screech_timer_ms -= diff;
                    false
                }
            };
            if due {
                let started = self.jeklik_state_mut(guid).is_some_and(|s| s.skill_started);
                if !started
                    && self.do_cast_spell_if_can(
                        guid,
                        JEKLIK_SPELL_SCREECH,
                        CastTarget::Unit(victim),
                    )
                {
                    if let Some(s) = self.jeklik_state_mut(guid) {
                        s.skill_started = true;
                        s.screech_timer_ms = 30_000;
                        s.global_cooldown_ms = 1000;
                    }
                } else if !started {
                    // Fork bug (cpp 256): failure resets Charge, not Screech.
                    if let Some(s) = self.jeklik_state_mut(guid) {
                        s.charge_timer_ms = 1000;
                    }
                }
            }
            // Sonic Burst.
            let due = {
                let Some(s) = self.jeklik_state_mut(guid) else {
                    return;
                };
                if s.sonic_burst_timer_ms < diff {
                    true
                } else {
                    s.sonic_burst_timer_ms -= diff;
                    false
                }
            };
            if due {
                let started = self.jeklik_state_mut(guid).is_some_and(|s| s.skill_started);
                if !started
                    && self.do_cast_spell_if_can(
                        guid,
                        JEKLIK_SPELL_SONICBURST,
                        CastTarget::Unit(victim),
                    )
                {
                    let next = self.rng.urand(20_000, 24_000);
                    if let Some(s) = self.jeklik_state_mut(guid) {
                        s.skill_started = true;
                        s.sonic_burst_timer_ms = next;
                        s.global_cooldown_ms = 1000;
                    }
                }
            }
            // Swoop.
            let due = {
                let Some(s) = self.jeklik_state_mut(guid) else {
                    return;
                };
                if s.swoop_timer_ms < diff {
                    true
                } else {
                    s.swoop_timer_ms -= diff;
                    false
                }
            };
            if due {
                let started = self.jeklik_state_mut(guid).is_some_and(|s| s.skill_started);
                if !started
                    && self.do_cast_spell_if_can(guid, JEKLIK_SPELL_SWOOP, CastTarget::Unit(victim))
                {
                    let next = self.rng.urand(12_000, 15_000);
                    if let Some(s) = self.jeklik_state_mut(guid) {
                        s.skill_started = true;
                        s.swoop_timer_ms = next;
                        s.global_cooldown_ms = 1000;
                    }
                }
            }
            // Pierce Armor.
            let due = {
                let Some(s) = self.jeklik_state_mut(guid) else {
                    return;
                };
                if s.pierce_armor_timer_ms < diff {
                    true
                } else {
                    s.pierce_armor_timer_ms -= diff;
                    false
                }
            };
            if due {
                let started = self.jeklik_state_mut(guid).is_some_and(|s| s.skill_started);
                if !started
                    && self.do_cast_spell_if_can(
                        guid,
                        JEKLIK_SPELL_PIERCEARMOR,
                        CastTarget::Unit(victim),
                    )
                {
                    let next = self.rng.urand(16_000, 18_000);
                    if let Some(s) = self.jeklik_state_mut(guid) {
                        s.skill_started = true;
                        s.pierce_armor_timer_ms = next;
                        s.global_cooldown_ms = 1000;
                    }
                }
            }
        }
    }

    fn batrider_state_mut(&mut self, guid: ObjectGuid) -> Option<&mut BatriderAi> {
        match &mut self.ai.get_mut(&guid)?.script {
            Some(CreatureScriptAi::Batrider(s)) => Some(s),
            _ => None,
        }
    }

    /// `mob_batriderAI::Reset` (also sets the unselectable flag from the ctor).
    fn batrider_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.batrider_state_mut(guid) {
            s.bomb_timer_ms = 2000;
        }
        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
        self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_FLAGS),
            flags | BATRIDER_UNIT_FLAG_NOT_SELECTABLE,
        );
    }

    /// `mob_batriderAI::DoAttack`.
    fn batrider_do_attack(&mut self, guid: ObjectGuid) {
        let ready = self
            .batrider_state_mut(guid)
            .is_some_and(|s| s.bomb_timer_ms == 0);
        if !ready {
            return;
        }
        let next = self.rng.urand(5000, 10_000);
        if let Some(s) = self.batrider_state_mut(guid) {
            s.bomb_timer_ms = next;
        }
        // Nearest Jeklik within 150yd (herod door pattern).
        let me = self.unit_position(guid).unwrap_or_default();
        let jeklik = self
            .creatures
            .iter()
            .filter(|(_, c)| c.info.entry == ZG_NPC_JEKLIK)
            .filter_map(|(g, _)| {
                self.object_position(*g).map(|p| {
                    let dx = p.x - me.x;
                    let dy = p.y - me.y;
                    (*g, dx * dx + dy * dy)
                })
            })
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .filter(|(_, d)| *d <= 150.0 * 150.0)
            .map(|(g, _)| g);
        let Some(jeklik) = jeklik else {
            // NEEDS-MAP-HELPER: fork `sLog` minimal line (cpp 424).
            return;
        };
        // NEEDS-MAP-HELPER: exact `SelectAttackingTarget(
        // ATTACKING_TARGET_RANDOM, 0)` on Jeklik (cpp 419);
        // `select_random_hostile` is the pending helper.
        if let Some(target) = self.select_random_hostile(jeklik) {
            self.do_cast_spell_if_can(
                guid,
                BATRIDER_SPELL_THROW_LIQUID_FIRE,
                CastTarget::Unit(target),
            );
        } else {
            // NEEDS-MAP-HELPER: fork `sLog` minimal line (cpp 421).
        }
    }

    /// `mob_batriderAI::SpellHitTarget` (ground-bomb trigger; no dispatcher:
    /// NO-DISPATCHER-YET).
    fn batrider_spell_hit_target(&mut self, guid: ObjectGuid, target: ObjectGuid, spell_id: u32) {
        if spell_id != BATRIDER_SPELL_THROW_LIQUID_FIRE {
            return;
        }
        if let Some(pos) = self.object_position(target) {
            let _ = self.cast_spell(
                guid,
                BATRIDER_SPELL_BOMB,
                CastTarget::Dest(pos),
                CastOptions {
                    triggered: false,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
    }

    /// `mob_batriderAI::UpdateAI` (instance-gated; no hostile head).
    fn batrider_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if self.zul_gurub().is_none() {
            return;
        }
        let due = {
            let Some(s) = self.batrider_state_mut(guid) else {
                return;
            };
            if s.bomb_timer_ms < diff_ms {
                true
            } else {
                s.bomb_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            if let Some(s) = self.batrider_state_mut(guid) {
                s.bomb_timer_ms = 0;
            }
        }
        match self.instance_get_data(ZG_TYPE_JEKLIK) {
            Some(IN_PROGRESS) => self.batrider_do_attack(guid),
            _ => self.despawn_creature_now(guid, 0),
        }
    }

