    /// `boss_marliAI::UpdateAI`.
    #[allow(clippy::too_many_lines)]
    fn marli_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let phase_two = self.marli_state_mut(guid).is_some_and(|s| s.phase_two);
        if phase_two {
            // Spider form (fork `else` ticks the webs timer even while
            // webbed, cpp 266-267).
            let webs_due = self.marli_state_mut(guid).is_some_and(|s| {
                if !s.has_webbed && s.webs_timer_ms < diff_ms {
                    true
                } else {
                    s.webs_timer_ms = s.webs_timer_ms.saturating_sub(diff_ms);
                    false
                }
            });
            if webs_due {
                self.do_cast_spell_if_can(
                    guid,
                    MARLI_SPELL_ENVELOPINGWEBS,
                    CastTarget::Unit(victim),
                );
                let next = self.rng.urand(10_000, 15_000);
                if let Some(s) = self.marli_state_mut(guid) {
                    s.webs_timer_ms = next;
                    s.charge_timer_ms = 1000;
                    s.has_webbed = true;
                }
            }
            // Fork `else` ticks the charge timer even while unwebbed
            // (cpp 293-294).
            let charge_due = self.marli_state_mut(guid).is_some_and(|s| {
                if s.has_webbed && s.charge_timer_ms < diff_ms {
                    true
                } else {
                    s.charge_timer_ms = s.charge_timer_ms.saturating_sub(diff_ms);
                    false
                }
            });
            let has_webbed = self.marli_state_mut(guid).is_some_and(|s| s.has_webbed);
            if has_webbed && charge_due {
                // Fork charges top aggro (comment: not the webbed player,
                // but no mana-user search is implemented, cpp 272-290).
                if let Some(target) = self.threat_targets_sorted(guid).first().copied() {
                    self.do_cast_spell_if_can(guid, MARLI_SPELL_CHARGE, CastTarget::Unit(target));
                    // NEEDS-MAP-HELPER: `DoResetThreat` (cpp 275).
                    self.attack_start(guid, target);
                    if let Some(s) = self.marli_state_mut(guid) {
                        s.has_webbed = false;
                    }
                }
                let next = self.rng.urand(10_000, 20_000);
                if let Some(s) = self.marli_state_mut(guid) {
                    s.webs_timer_ms = next;
                }
            }
            let due = {
                let Some(s) = self.marli_state_mut(guid) else {
                    return;
                };
                if s.corrosive_poison_timer_ms < diff_ms {
                    true
                } else {
                    s.corrosive_poison_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                self.do_cast_spell_if_can(
                    guid,
                    MARLI_SPELL_CORROSIVE_POISON,
                    CastTarget::Unit(victim),
                );
                let next = self.rng.urand(25_000, 35_000);
                if let Some(s) = self.marli_state_mut(guid) {
                    s.corrosive_poison_timer_ms = next;
                }
            }
        } else {
            // Troll form.
            let due = {
                let Some(s) = self.marli_state_mut(guid) else {
                    return;
                };
                if s.poison_volley_timer_ms < diff_ms {
                    true
                } else {
                    s.poison_volley_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                self.do_cast_spell_if_can(guid, MARLI_SPELL_POISONVOLLEY, CastTarget::Unit(victim));
                let next = self.rng.urand(10_000, 20_000);
                if let Some(s) = self.marli_state_mut(guid) {
                    s.poison_volley_timer_ms = next;
                }
            }
            let due = {
                let Some(s) = self.marli_state_mut(guid) else {
                    return;
                };
                if s.drain_life_timer_ms < diff_ms {
                    true
                } else {
                    s.drain_life_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                self.do_cast_spell_if_can(guid, MARLI_SPELL_DRAIN_LIFE, CastTarget::Unit(victim));
                let next = self.rng.urand(20_000, 50_000);
                if let Some(s) = self.marli_state_mut(guid) {
                    s.drain_life_timer_ms = next;
                }
            }
            let due = {
                let Some(s) = self.marli_state_mut(guid) else {
                    return;
                };
                if s.spawn_spider_timer_ms < diff_ms {
                    true
                } else {
                    s.spawn_spider_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                let count = self.rng.urand(1, 4);
                for _ in 0..count {
                    if let Some(egg) = self.marli_select_next_egg(guid) {
                        // NEEDS-MAP-HELPER: `SetGoState(GO_STATE_ACTIVE)`
                        // (cpp 237).
                        let pos = self.object_position(egg).unwrap_or_default();
                        self.summon_creature(
                            MARLI_NPC_SPAWN_OF_MARLI,
                            Position::new(pos.x, pos.y, pos.z, 0.0),
                            guid,
                            MARLI_TEMPSUMMON_TIMED_OOC_DESPAWN,
                            15_000,
                        );
                    }
                }
                let next = self.rng.urand(20_000, 30_000);
                if let Some(s) = self.marli_state_mut(guid) {
                    s.spawn_spider_timer_ms = next;
                }
            }
            let due = {
                let Some(s) = self.marli_state_mut(guid) else {
                    return;
                };
                if s.aggrandir_timer_ms < diff_ms {
                    true
                } else {
                    s.aggrandir_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                if !self.bot_has_aura(guid, MARLI_SPELL_AGGRANDIR) {
                    self.do_cast_spell_if_can(guid, MARLI_SPELL_AGGRANDIR, CastTarget::SelfCast);
                }
                let next = self.rng.urand(10_000, 20_000);
                if let Some(s) = self.marli_state_mut(guid) {
                    s.aggrandir_timer_ms = next;
                }
            }
        }
        // Form swap every 35s.
        let due = {
            let Some(s) = self.marli_state_mut(guid) else {
                return;
            };
            if s.transform_back_timer_ms < diff_ms {
                true
            } else {
                s.transform_back_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: `InterruptNonMeleeSpells(false)` (cpp 309/329).
            let phase_two = self.marli_state_mut(guid).is_some_and(|s| s.phase_two);
            if phase_two {
                self.do_cast_spell_if_can(guid, MARLI_SPELL_TRANSFORM_BACK, CastTarget::SelfCast);
                // NEEDS-MAP-HELPER: `SetDisplayId(defaultModel)` (cpp 333).
                // NEEDS-MAP-HELPER: `GetDefaultDamageRange`/
                // `SetBaseWeaponDamage(+1%)`/`UpdateDamagePhysical` (cpp 338-340).
                if let Some(s) = self.marli_state_mut(guid) {
                    s.phase_two = false;
                }
            } else {
                self.do_script_text(MARLI_SAY_TRANSFORM, guid, None, -1);
                self.do_cast_spell_if_can(guid, MARLI_SPELL_SPIDER_FORM, CastTarget::SelfCast);
                // NEEDS-MAP-HELPER: `GetDefaultDamageRange`/
                // `SetBaseWeaponDamage(+35%)`/`UpdateDamagePhysical` (cpp 318-320).
                // NEEDS-MAP-HELPER: `DoResetThreat` (cpp 322).
                if let Some(s) = self.marli_state_mut(guid) {
                    s.phase_two = true;
                }
            }
            if let Some(s) = self.marli_state_mut(guid) {
                s.transform_back_timer_ms = 35_000;
            }
        }
        // Trash on the victim.
        let due = {
            let Some(s) = self.marli_state_mut(guid) else {
                return;
            };
            if s.trash_timer_ms < diff_ms {
                true
            } else {
                s.trash_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            self.do_cast_spell_if_can(guid, MARLI_SPELL_TRASH, CastTarget::Unit(victim));
            let next = self.rng.urand(10_000, 20_000);
            if let Some(s) = self.marli_state_mut(guid) {
                s.trash_timer_ms = next;
            }
        }
    }

