    /// `boss_renatakiAI::Reset` (RNG rolls belong here, herod pattern; the
    /// fork ctor sets `Light = false` after `Reset()`).
    fn renataki_reset(&mut self, guid: ObjectGuid) {
        let invisible = self.rng.urand(28_000, 32_000);
        let suriner = self.rng.urand(9000, 11_000);
        let aggro = self.rng.urand(15_000, 25_000);
        let thousand = self.rng.urand(4000, 8000);
        if let Some(s) = self.renataki_state_mut(guid) {
            s.tick_timer_ms = 1000;
            s.invisible_timer_ms = invisible;
            s.suriner_timer_ms = suriner;
            s.visible_timer_ms = 20_000;
            s.aggro_timer_ms = aggro;
            s.thousand_blades_timer_ms = thousand;
            s.invisible = false;
            s.light = false;
        }
        self.object_set_field(
            guid,
            u32::from(offsets::UNIT_VIRTUAL_ITEM_SLOT_DISPLAY),
            31_818,
        );
        self.object_set_field(
            guid,
            u32::from(offsets::UNIT_VIRTUAL_ITEM_INFO),
            218_171_138,
        );
        self.object_set_field(guid, u32::from(offsets::UNIT_VIRTUAL_ITEM_INFO) + 1, 3);
    }

