    /// `boss_renatakiAI::UpdateAI`.
    #[allow(clippy::too_many_lines)]
    fn renataki_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Red-lightning intro (OOC work before the drive, trainee pattern).
        if !self.renataki_state_mut(guid).is_some_and(|s| s.light) {
            let _ = self.cast_spell(
                guid,
                RENATAKI_SPELL_RED_LIGHTNING,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
            if let Some(s) = self.renataki_state_mut(guid) {
                s.light = true;
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Enrage below 30% (`CF_AURA_NOT_PRESENT` unmodeled: re-cast lands on
        // the per-tick retry, cpp 82).
        if self.creature_health_percent(guid) < 30.0 {
            self.do_cast_spell_if_can(guid, RENATAKI_SPELL_ENRAGE, CastTarget::SelfCast);
        }
        if self.renataki_state_mut(guid).is_some_and(|s| s.invisible) {
            let due = {
                let Some(s) = self.renataki_state_mut(guid) else {
                    return;
                };
                if s.visible_timer_ms < diff_ms {
                    true
                } else {
                    s.visible_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                // NEEDS-MAP-HELPER: exact `SelectAttackingTarget(
                // ATTACKING_TARGET_RANDOM, 0)` semantics; `select_random_hostile`
                // is the pending helper (cpp 88). Fork `ASSERT`s non-null.
                let Some(target) = self.select_random_hostile(guid) else {
                    return;
                };
                // NEEDS-MAP-HELPER: `LeaveVanish` + `Ambush(target, 24337)`
                // (cpp 89-91).
                let _ = target;
                if let Some(s) = self.renataki_state_mut(guid) {
                    s.invisible = false;
                    s.visible_timer_ms = 20_000;
                }
            }
            return;
        }
        let due = {
            let Some(s) = self.renataki_state_mut(guid) else {
                return;
            };
            if s.suriner_timer_ms < diff_ms {
                true
            } else {
                s.suriner_timer_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, RENATAKI_SPELL_SURINER_ZONE, CastTarget::SelfCast)
        {
            let next = self.rng.urand(9000, 11_000);
            if let Some(s) = self.renataki_state_mut(guid) {
                s.suriner_timer_ms = next;
            }
        }
        let due = {
            let Some(s) = self.renataki_state_mut(guid) else {
                return;
            };
            if s.invisible_timer_ms < diff_ms {
                true
            } else {
                s.invisible_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: `EnterVanish` (cpp 112).
            let next = self.rng.urand(30_000, 42_000);
            if let Some(s) = self.renataki_state_mut(guid) {
                s.invisible = true;
                s.invisible_timer_ms = next;
            }
        }
        // Aggro juggle (second-random target, -50% victim threat).
        let due = {
            let Some(s) = self.renataki_state_mut(guid) else {
                return;
            };
            if s.aggro_timer_ms < diff_ms {
                true
            } else {
                s.aggro_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: `SelectAttackingTarget(RANDOM, 1)`
            // second-random semantics (cpp 124).
            let target = self.select_random_hostile(guid);
            if self.threat_on(guid, victim) > 0.0 {
                self.modify_threat_percent_of(guid, victim, -50);
            }
            if let Some(target) = target {
                self.attack_start(guid, target);
            }
            let next = self.rng.urand(7000, 20_000);
            if let Some(s) = self.renataki_state_mut(guid) {
                s.aggro_timer_ms = next;
            }
        }
        let due = {
            let Some(s) = self.renataki_state_mut(guid) else {
                return;
            };
            if s.thousand_blades_timer_ms < diff_ms {
                true
            } else {
                s.thousand_blades_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            self.do_cast_spell_if_can(
                guid,
                RENATAKI_SPELL_THOUSANDBLADES,
                CastTarget::Unit(victim),
            );
            let next = self.rng.urand(7000, 12_000);
            if let Some(s) = self.renataki_state_mut(guid) {
                s.thousand_blades_timer_ms = next;
            }
        }
        // NEEDS-MAP-HELPER: `IsAttackReady()` gate (cpp 146).
        if self.rng.urand(0, 2) == 0 {
            let _ = self.cast_spell(
                guid,
                RENATAKI_SPELL_TRASH,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
    }

