    /// `boss_venoxisAI::Reset` (`m_fDefaultSize` from the ctor has no getter;
    /// starts 0.0 until the integrator wires display scale).
    fn venoxis_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.venoxis_state_mut(guid) {
            s.holy_fire_timer_ms = 10_000;
            s.holy_wrath_timer_ms = 30_000;
            s.venom_spit_timer_ms = 5500;
            s.renew_timer_ms = 30_500;
            s.poison_cloud_timer_ms = 2000;
            s.dispell_timer_ms = 35_000;
            s.parasitic_timer_ms = 10_000;
            s.trash_timer_ms = 5000;
            s.holy_nova_timer_ms = 7500;
            s.frenzy = false;
            s.phase_two = false;
        }
        // NEEDS-MAP-HELPER: `SetFloatValue(OBJECT_FIELD_SCALE_X,
        // m_fDefaultSize)` (cpp 106); no scale writer on `Map`.
        // NEEDS-MAP-HELPER: `ResetStats` (cpp 107).
        let adds = self
            .venoxis_state_mut(guid)
            .map(|s| std::mem::take(&mut s.adds_guids))
            .unwrap_or_default();
        for g in adds {
            if self.creatures.contains_key(&g) {
                self.despawn_creature_now(g, 0);
            }
        }
    }

    /// `boss_venoxisAI::Aggro`.
    fn venoxis_aggro(&mut self, _guid: ObjectGuid, _who: ObjectGuid) {
        self.instance_set_data(ZG_TYPE_VENOXIS, IN_PROGRESS);
    }

    /// `boss_venoxisAI::EnterEvadeMode` (pre-base ONLY: despawn the cobras;
    /// the dispatcher runs base evade + `venoxis_reset` after).
    fn venoxis_enter_evade(&mut self, guid: ObjectGuid) {
        let me = self.unit_position(guid).unwrap_or_default();
        let cobras: Vec<ObjectGuid> = self
            .creatures
            .iter()
            .filter(|(_, c)| c.info.entry == VENOXIS_NPC_RAZZASHI_COBRA)
            .filter_map(|(g, _)| {
                self.object_position(*g).map(|p| {
                    let dx = p.x - me.x;
                    let dy = p.y - me.y;
                    (*g, dx * dx + dy * dy)
                })
            })
            .filter(|(_, d)| *d <= 300.0 * 300.0)
            .map(|(g, _)| g)
            .collect();
        // Fork uses `DEFAULT_VISIBILITY_INSTANCE` radius; 300yd approximates
        // the grid window (cpp 130).
        for cobra in cobras {
            self.despawn_creature_now(cobra, 0);
        }
    }

