    /// `GurubashiAxeThrowerAI::UpdateAI`.
    fn axe_thrower_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let due = {
            let Some(s) = self.axe_thrower_state_mut(guid) else {
                return;
            };
            if s.axe_flurry_timer_ms < diff_ms {
                true
            } else {
                s.axe_flurry_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: `HasFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_DISARMED)`
            // gate (cpp 40); flag value unconfirmed on `Map`.
            if self.do_cast_spell_if_can(
                guid,
                AXETHROWER_SPELL_AXE_FLURRY,
                CastTarget::Unit(victim),
            ) {
                let next = self.rng.urand(14_000, 19_000);
                if let Some(s) = self.axe_thrower_state_mut(guid) {
                    s.axe_flurry_timer_ms = next;
                }
            }
        }
        let due = {
            let Some(s) = self.axe_thrower_state_mut(guid) else {
                return;
            };
            if s.throw_timer_ms < diff_ms {
                true
            } else {
                s.throw_timer_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, AXETHROWER_SPELL_THROW, CastTarget::Unit(victim))
        {
            let next = self.rng.urand(4000, 7000);
            if let Some(s) = self.axe_thrower_state_mut(guid) {
                s.throw_timer_ms = next;
            }
        }
        if !self.axe_thrower_state_mut(guid).is_some_and(|s| s.enrage)
            && self.creature_health_percent(guid) < 50.0
        {
            let _ = self.cast_spell(
                guid,
                AXETHROWER_SPELL_FRENZY,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: false,
                    skip_known: true,
                    ..Default::default()
                },
            );
            if let Some(s) = self.axe_thrower_state_mut(guid) {
                s.enrage = true;
            }
        }
    }

