    /// `npc_hakkari_doctor::JustDied` (fork summons the spirit on the killer;
    /// the hook shape carries no killer, so the current victim stands in).
    fn hakkari_just_died(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: fork `SummonCreatureAndAttack(15009, pKiller)`
        // targets the killer (cpp 242), not the current victim.
        let Some(victim) = self.unit_victim(guid) else {
            return;
        };
        let summoned = self.summon_creature(
            HAKKARI_NPC_ESPRIT_VAUDOU,
            self.unit_position(victim).unwrap_or_default(),
            guid,
            HAKKARI_TEMPSUMMON_CORPSE_TIMED_DESPAWN,
            0,
        );
        if let Some(summoned) = summoned {
            self.attack_start(summoned, victim);
        }
    }

    /// `npc_hakkari_doctor::UpdateAI`.
    #[allow(clippy::too_many_lines)]
    fn hakkari_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let due = {
            let Some(s) = self.hakkari_state_mut(guid) else {
                return;
            };
            if s.malefice_timer_ms < diff_ms {
                true
            } else {
                s.malefice_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: `GetFarthestVictimInRange(10, 20)` (cpp 194).
            if let Some(target) = self.select_random_hostile(guid) {
                self.do_cast_spell_if_can(guid, HAKKARI_SPELL_MALEFICE, CastTarget::Unit(target));
                let next = self.rng.urand(20_000, 40_000);
                if let Some(s) = self.hakkari_state_mut(guid) {
                    s.malefice_timer_ms = next;
                }
            }
        }
        let due = {
            let Some(s) = self.hakkari_state_mut(guid) else {
                return;
            };
            if s.crapauds_timer_ms < diff_ms {
                true
            } else {
                s.crapauds_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: `GetFarthestVictimInRange(10, 20)` (cpp 203).
            if let Some(target) = self.select_random_hostile(guid) {
                for _ in 0..4 {
                    // Fork `SummonCreatureAndAttack(15010, pTarget)` (kind +
                    // duration default to `TEMPSUMMON_CORPSE_TIMED_DESPAWN`/0;
                    // fork default unconfirmed, cpp 209).
                    let summoned = self.summon_creature(
                        HAKKARI_NPC_CRAPAUD,
                        self.unit_position(target).unwrap_or_default(),
                        guid,
                        HAKKARI_TEMPSUMMON_CORPSE_TIMED_DESPAWN,
                        0,
                    );
                    if let Some(summoned) = summoned {
                        self.attack_start(summoned, target);
                    }
                }
                let next = self.rng.urand(10, 40) * 1000;
                if let Some(s) = self.hakkari_state_mut(guid) {
                    s.crapauds_timer_ms = next;
                }
            }
        }
        let due = {
            let Some(s) = self.hakkari_state_mut(guid) else {
                return;
            };
            if s.crapauds_liberation_timer_ms < diff_ms {
                true
            } else {
                s.crapauds_liberation_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // Nearest toad within 40yd (fork `FindNearestCreature`, cpp 217).
            let me = self.unit_position(guid).unwrap_or_default();
            let toad = self
                .creatures
                .iter()
                .filter(|(_, c)| c.info.entry == HAKKARI_NPC_CRAPAUD)
                .filter_map(|(g, _)| {
                    self.object_position(*g).map(|p| {
                        let dx = p.x - me.x;
                        let dy = p.y - me.y;
                        (*g, dx * dx + dy * dy)
                    })
                })
                .min_by(|a, b| a.1.total_cmp(&b.1))
                .filter(|(_, d)| *d <= 40.0 * 40.0)
                .map(|(g, _)| g);
            if let Some(toad) = toad {
                let _ = self.cast_spell(
                    toad,
                    HAKKARI_SPELL_CRAPAUD_LIBERATION,
                    CastTarget::SelfCast,
                    CastOptions {
                        triggered: true,
                        skip_known: true,
                        ..Default::default()
                    },
                );
                self.despawn_creature_now(toad, 0);
            }
            if let Some(s) = self.hakkari_state_mut(guid) {
                s.crapauds_liberation_timer_ms = 1000;
            }
        }
        let due = {
            let Some(s) = self.hakkari_state_mut(guid) else {
                return;
            };
            if s.ombre_timer_ms < diff_ms {
                true
            } else {
                s.ombre_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: `GetFarthestVictimInRange(10, 20)` (cpp 227).
            if let Some(target) = self.select_random_hostile(guid) {
                // Fork `CastSpell(pTarget, 17289, true)` (triggered).
                let _ = self.cast_spell(
                    guid,
                    HAKKARI_SPELL_OMBRE,
                    CastTarget::Unit(target),
                    CastOptions {
                        triggered: true,
                        skip_known: true,
                        ..Default::default()
                    },
                );
                let next = self.rng.urand(5000, 20_000);
                if let Some(s) = self.hakkari_state_mut(guid) {
                    s.ombre_timer_ms = next;
                }
            }
        }
    }

    /// `npc_esprit_vaudou::Reset` (stateless; the ctor flag write repeats here).
    fn vaudou_reset(&mut self, guid: ObjectGuid) {
        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
        self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_FLAGS),
            flags | VAUDOU_UNIT_FLAG_SPAWNING | VAUDOU_UNIT_FLAG_NOT_SELECTABLE,
        );
    }

    /// `npc_esprit_vaudou::UpdateAI` (victim-touch detonation; no hostile
    /// head in the fork).
    fn vaudou_update(&mut self, guid: ObjectGuid, _diff_ms: u32) {
        let Some(victim) = self.unit_victim(guid) else {
            return;
        };
        let close = self
            .unit_position(guid)
            .zip(self.unit_position(victim))
            .is_some_and(|(a, b)| {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                let dz = a.z - b.z;
                dx * dx + dy * dy + dz * dz < 5.0 * 5.0
            });
        if close {
            let _ = self.cast_spell(
                victim,
                VAUDOU_SPELL_EXPLOSION,
                CastTarget::Unit(victim),
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
            self.despawn_creature_now(guid, 0);
        }
    }

