    /// `npc_narm_faulkAI::Reset` (`dun_morogh.cpp:20-26`).
    fn narm_faulk_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.narm_faulk_state_mut(guid) {
            s.life_timer_ms = 120_000;
            s.spell_hit = false;
        }
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_DYNAMIC_FLAGS),
            NARM_UNIT_DYNFLAG_DEAD,
        );
        self.unit_set_byte(
            guid,
            offsets::UNIT_FIELD_BYTES_1,
            0,
            NARM_UNIT_STAND_STATE_DEAD,
        );
    }

    /// `npc_narm_faulkAI::MoveInLineOfSight` (cpp 28: explicit no-op).
    /// NO-DISPATCHER-YET.
    #[allow(clippy::unused_self)]
    fn narm_faulk_move_in_line_of_sight(&mut self, _guid: ObjectGuid) {}

    /// `npc_narm_faulkAI::UpdateAI` (cpp 30-39).
    fn narm_faulk_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // `IsStandingUp()`: stand state is anything but dead.
        let standing = (self.unit_value_u32(guid, offsets::UNIT_FIELD_BYTES_1) & 0xFF)
            != u32::from(NARM_UNIT_STAND_STATE_DEAD);
        if !standing {
            return;
        }
        let expired = match self.narm_faulk_state_mut(guid) {
            Some(s) => {
                if s.life_timer_ms < diff_ms {
                    true
                } else {
                    s.life_timer_ms -= diff_ms;
                    false
                }
            }
            None => return,
        };
        if expired {
            self.enter_evade_mode(guid);
        }
    }

    /// `npc_narm_faulkAI::SpellHit` (cpp 41-51). NO-DISPATCHER-YET.
    fn narm_faulk_spell_hit(&mut self, guid: ObjectGuid, caster: ObjectGuid, spell_id: u32) {
        let hit = self
            .narm_faulk_state_mut(guid)
            .is_some_and(|s| !s.spell_hit);
        if spell_id != NARM_SPELL_AWAKEN || !hit {
            return;
        }
        // `m_creature->SetStandState(UNIT_STAND_STATE_STAND)`.
        self.unit_set_byte(guid, offsets::UNIT_FIELD_BYTES_1, 0, STAND_STATE_STAND);
        let _ = self.object_set_field(guid, u32::from(offsets::UNIT_DYNAMIC_FLAGS), 0);
        // `RemoveAllAuras` is commented out in the fork (cpp 47); omitted.
        self.do_script_text(NARM_SAY_HEAL, guid, Some(caster), -1);
        if let Some(s) = self.narm_faulk_state_mut(guid) {
            s.spell_hit = true;
        }
    }

