    /// `boss_thermapluggAI::Reset` (cpp 65-74).
    fn thermaplugg_reset(&mut self, guid: ObjectGuid) {
        let knock_away = self.rng.urand(17_000, 20_000);
        let activate = self.rng.urand(10_000, 15_000);
        if let Some(s) = self.thermaplugg_state_mut(guid) {
            s.knock_away_timer_ms = knock_away;
            s.activate_bomb_timer_ms = activate;
            s.phase_two = false;
            s.spawn_x = 0.0;
            s.spawn_y = 0.0;
            s.spawn_z = 0.0;
            s.landed_bombs.clear();
        }
    }

    /// `boss_thermapluggAI::Aggro` (cpp 86-99).
    fn thermaplugg_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        self.do_script_text(THERM_SAY_AGGRO, guid, None, -1);
        self.instance_set_data(GNO_TYPE_THERMAPLUGG, IN_PROGRESS);
        if let Some(p) = self.unit_position(guid) {
            if let Some(s) = self.thermaplugg_state_mut(guid) {
                s.spawn_x = p.x;
                s.spawn_y = p.y;
                s.spawn_z = p.z;
            }
        }
        // `m_asBombFaces` (cpp 93) is instance state (`GnomereganState`);
        // the bomb-face loop in `thermaplugg_update` reads it there.
    }

    /// `boss_thermapluggAI::JustDied` (cpp 78-84).
    fn thermaplugg_just_died(&mut self, guid: ObjectGuid) {
        self.instance_set_data(GNO_TYPE_THERMAPLUGG, DONE);
        if let Some(s) = self.thermaplugg_state_mut(guid) {
            s.summoned_bombs.clear();
        }
    }

    /// `boss_thermapluggAI::KilledUnit` (cpp 76).
    fn thermaplugg_killed_unit(&mut self, guid: ObjectGuid, _victim: ObjectGuid) {
        self.do_script_text(THERM_SAY_SLAY, guid, None, -1);
    }

    /// `boss_thermapluggAI::JustReachedHome` (cpp 101-113).
    /// NO-DISPATCHER-YET.
    fn thermaplugg_just_reached_home(&mut self, guid: ObjectGuid) {
        self.instance_set_data(GNO_TYPE_THERMAPLUGG, GNO_FAIL);
        let bombs = self
            .thermaplugg_state_mut(guid)
            .map(|s| s.summoned_bombs.clone())
            .unwrap_or_default();
        for bomb in bombs {
            if self.creatures.contains_key(&bomb) {
                self.despawn_creature_now(bomb, 0);
            }
        }
        if let Some(s) = self.thermaplugg_state_mut(guid) {
            s.summoned_bombs.clear();
        }
    }

    /// `boss_thermapluggAI::JustSummoned` (cpp 115-129).
    fn thermaplugg_just_summoned(&mut self, guid: ObjectGuid, created: ObjectGuid) {
        let is_bomb = self
            .creatures
            .get(&created)
            .is_some_and(|c| c.info.entry == THERM_NPC_WALKING_BOMB);
        if !is_bomb {
            return;
        }
        if let Some(s) = self.thermaplugg_state_mut(guid) {
            s.summoned_bombs.push(created);
        }
        let Some((sx, sy, sz)) = self
            .thermaplugg_state_mut(guid)
            .map(|s| (s.spawn_x, s.spawn_y, s.spawn_z))
        else {
            return;
        };
        let Some(p) = self.unit_position(created) else {
            return;
        };
        let (px, py) = (p.x, p.y);
        let fx = 0.2 * sx + 0.8 * px;
        let fy = 0.2 * sy + 0.8 * py;
        let fz = sz - 2.0;
        // NEEDS-MAP-HELPER: `UpdateGroundPositionZ(fX, fY, fZ)` (cpp 125).
        self.creature_move_point(created, 1, Position::new(fx, fy, fz, 0.0), 0, 0.0, 0.0);
    }

    /// `boss_thermapluggAI::SummonedMovementInform` (cpp 130-134).
    /// NO-DISPATCHER-YET.
    /// (dispatcher wired in step-3 batch)
    fn thermaplugg_summoned_movement_inform(
        &mut self,
        guid: ObjectGuid,
        summoned: ObjectGuid,
        point_id: u32,
    ) {
        let is_bomb = self
            .creatures
            .get(&summoned)
            .is_some_and(|c| c.info.entry == THERM_NPC_WALKING_BOMB);
        if !is_bomb || point_id != 1 {
            return;
        }
        if let Some(s) = self.thermaplugg_state_mut(guid) {
            s.landed_bombs.push(summoned);
        }
    }

    /// `boss_thermapluggAI::SummonedCreatureDespawn` (cpp 136).
    /// NO-DISPATCHER-YET.
    /// (dispatcher wired in step-3 batch)
    fn thermaplugg_summoned_despawn(&mut self, guid: ObjectGuid, summoned: ObjectGuid) {
        if let Some(s) = self.thermaplugg_state_mut(guid) {
            s.summoned_bombs.retain(|g| *g != summoned);
        }
    }

    /// `boss_thermapluggAI::UpdateAI` (cpp 138-219).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn thermaplugg_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // OOC work the fork does BEFORE the `SelectHostileTarget` check
        // (cpp 143-152): landed bombs follow Thermaplugg.
        let landed = self
            .thermaplugg_state_mut(guid)
            .map(|s| s.landed_bombs.clone())
            .unwrap_or_default();
        if !landed.is_empty() {
            for bomb in &landed {
                // NEEDS-MAP-HELPER: `MoveFollow(m_creature, 0.0, 0.0)`
                // (cpp 148); no follow helper on `Map`.
                let _ = bomb;
            }
            if let Some(s) = self.thermaplugg_state_mut(guid) {
                s.landed_bombs.clear();
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        if !self
            .thermaplugg_state_mut(guid)
            .is_some_and(|s| s.phase_two)
            && self.creature_health_percent(guid) < 50.0
        {
            self.do_script_text(THERM_SAY_PHASE, guid, None, -1);
            if let Some(s) = self.thermaplugg_state_mut(guid) {
                s.phase_two = true;
            }
        }
        let phase_two = self
            .thermaplugg_state_mut(guid)
            .is_some_and(|s| s.phase_two);
        // Knock Away.
        let knock_due = match self.thermaplugg_state_mut(guid) {
            Some(s) => {
                if s.knock_away_timer_ms < diff_ms {
                    true
                } else {
                    s.knock_away_timer_ms -= diff_ms;
                    false
                }
            }
            None => return,
        };
        if knock_due {
            if phase_two {
                if self.do_cast_spell_if_can(guid, THERM_SPELL_KNOCK_AWAY_AOE, CastTarget::SelfCast)
                {
                    if let Some(s) = self.thermaplugg_state_mut(guid) {
                        s.knock_away_timer_ms = 12_000;
                    }
                }
            } else if self.do_cast_spell_if_can(
                guid,
                THERM_SPELL_KNOCK_AWAY,
                CastTarget::Unit(victim),
            ) {
                let next = self.rng.urand(17_000, 20_000);
                if let Some(s) = self.thermaplugg_state_mut(guid) {
                    s.knock_away_timer_ms = next;
                }
            }
        }
        // Activate Bomb.
        let bomb_due = match self.thermaplugg_state_mut(guid) {
            Some(s) => {
                if s.activate_bomb_timer_ms < diff_ms {
                    true
                } else {
                    s.activate_bomb_timer_ms -= diff_ms;
                    false
                }
            }
            None => return,
        };
        if bomb_due {
            let spell = if phase_two {
                THERM_SPELL_ACTIVATE_BOMB_B
            } else {
                THERM_SPELL_ACTIVATE_BOMB_A
            };
            if self.do_cast_spell_if_can(guid, spell, CastTarget::SelfCast) {
                let secs = if phase_two {
                    self.rng.urand(6, 12)
                } else {
                    self.rng.urand(12, 17)
                };
                if let Some(s) = self.thermaplugg_state_mut(guid) {
                    s.activate_bomb_timer_ms = secs * 1_000;
                }
                // `!urand(0, 5)`: say on roll 0 (cpp 181).
                if self.rng.urand(0, 5) == 0 {
                    self.do_script_text(THERM_SAY_BOMB, guid, None, -1);
                }
            }
        }
        // Spawn bombs from activated faces (cpp 188-216). Face state lives
        // in `GnomereganState`; collect first so the summon borrows end.
        let faces: Vec<(usize, f32, f32)> = self
            .gnomeregan()
            .map(|gno| {
                gno.bomb_faces
                    .iter()
                    .enumerate()
                    .filter(|(_, f)| f.activated)
                    .map(|(i, f)| (i, f.face))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default()
            .into_iter()
            .filter_map(|(i, face_guid)| self.object_position(face_guid).map(|p| (i, p.x, p.y)))
            .collect();
        let (sx, sy) = match self.thermaplugg_state_mut(guid) {
            Some(s) => (s.spawn_x, s.spawn_y),
            None => return,
        };
        for (i, fx, fy) in faces {
            // The per-face bomb timer (`m_uiBombTimer`, cpp 210) mutates
            // instance state; each arm re-borrows so summons can run.
            let tick = match self.gnomeregan_mut() {
                Some(gno) => {
                    let face = &mut gno.bomb_faces[i];
                    if face.bomb_timer_ms < diff_ms {
                        face.bomb_timer_ms = 0;
                        true
                    } else {
                        face.bomb_timer_ms -= diff_ms;
                        false
                    }
                }
                None => false,
            };
            if !tick {
                continue;
            }
            let bomb_count = self
                .creatures
                .values()
                .filter(|c| {
                    c.info.entry == THERM_NPC_WALKING_BOMB
                        && self
                            .object_position(c.unit.guid())
                            .and_then(|bp| self.unit_position(guid).map(|mp| (bp, mp)))
                            .is_some_and(|(bp, mp)| {
                                let dx = bp.x - mp.x;
                                let dy = bp.y - mp.y;
                                dx * dx + dy * dy <= 250.0 * 250.0
                            })
                })
                .count();
            if bomb_count < GNO_MAX_GNOME_FACES {
                let fx = 0.35 * sx + 0.65 * fx;
                let fy = 0.35 * sy + 0.65 * fy;
                self.summon_creature(
                    THERM_NPC_WALKING_BOMB,
                    Position::new(fx, fy, THERM_BOMB_SPAWN_Z, 0.0),
                    guid,
                    THERM_TEMPSUMMON_CORPSE_DESPAWN,
                    0,
                );
            }
            let next = self.rng.urand(10_000, 25_000);
            if let Some(gno) = self.gnomeregan_mut() {
                gno.bomb_faces[i].bomb_timer_ms = next;
            }
        }
    }

    fn windsor_state_mut(&mut self, guid: ObjectGuid) -> Option<&mut WindsorAi> {
        match self.ai.get_mut(&guid).and_then(|ai| ai.script.as_mut()) {
            Some(CreatureScriptAi::ReginaldWindsor(s)) => Some(s),
            _ => None,
        }
    }

