    fn windsor_reset(&mut self, _guid: ObjectGuid) {}

    /// `npc_reginald_windsorAI::ResetCreature` (cpp 23-53).
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn windsor_reset_creature(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.windsor_state_mut(guid) {
            s.rowe_knows = false;
            s.squire_rowe_guid = ObjectGuid::EMPTY;
            s.despawn_timer_ms = 300_000;
            s.timer_ms = 3000;
            s.tick = 0;
            s.player_guid = None;
            s.greet_player = false;
            s.quest_accepted = false;
            s.begin_quest = false;
            s.begin = true;
            s.need_check = false;
            s.phase_finale = false;
            s.the_end = false;
            s.combat_just_ended = false;
            s.guard_timer_ms.fill(0);
            s.guard_need.fill(false);
            s.guard_guids.fill(ObjectGuid::EMPTY);
            s.drag_guids.fill(ObjectGuid::EMPTY);
        }
        // NEEDS-MAP-HELPER: `EnableMoveInLosEvent` (cpp 52); no move-in-LOS
        // event flag helper on `Map`.
    }

    /// `npc_reginald_windsorAI::PokeRowe` (cpp 61-75).
    fn windsor_poke_rowe(&mut self, guid: ObjectGuid) {
        let done = self.windsor_state_mut(guid).is_some_and(|s| s.rowe_knows);
        if done {
            return;
        }
        let rowe = self
            .windsor_state_mut(guid)
            .map_or(ObjectGuid::EMPTY, |s| s.squire_rowe_guid);
        if self.creatures.contains_key(&rowe) {
            self.rowe_reset_creature(rowe);
            if let Some(s) = self.windsor_state_mut(guid) {
                s.rowe_knows = true;
            }
        }
    }

