    /// `QUEST_THE_GREAT_MASQUERADE` 6403).
    #[allow(clippy::unused_self)]
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn windsor_complete_quest(&mut self, _guid: ObjectGuid) {}

    /// `npc_reginald_windsorAI::EndScene` (cpp 97-129).
    fn windsor_end_scene(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: `GetRespawnCoord` (cpp 106/116), `SetStandState`
        // on another creature (Bolvar, cpp 105), `MovePoint` with `MOVE_NONE`
        // + orientation on another creature, `RemoveAurasDueToSpell` +
        // triggered `CastSpell` on Onyxia (cpp 126-128), walk-speed ETA
        // (`GetSpeed(MOVE_WALK)`, cpp 120).
        if let Some(bolvar) =
            self.nearest_creature_with_entry(guid, WINDSOR_NPC_BOLVAR_FORDRAGON, 150.0)
        {
            let _ = bolvar;
        }
        if let Some(anduin) =
            self.nearest_creature_with_entry(guid, WINDSOR_NPC_ANDUIN_WRYNN, 150.0)
        {
            if let Some(s) = self.windsor_state_mut(guid) {
                s.phase_finale = true;
            }
            let _ = anduin;
        }
        if let Some(onyxia) = self.nearest_creature_with_entry(guid, WINDSOR_NPC_LADY_ONYXIA, 150.0)
        {
            self.remove_auras_due_to_spell(onyxia, WINDSOR_SPELL_GREATER_INVISIBILITY);
            self.cast_spell(
                onyxia,
                WINDSOR_SPELL_INVISIBILITY,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    triggered_by_aura: false,
                    skip_known: true,
                    cast_item: None,
                    custom_base_points: [None; 3],
                    triggered_by_aura_spell: 0,
                    triggered_by_spell: 0,
                },
            );
        }
    }

    /// `npc_reginald_windsorAI::JustDied` (cpp 55-59).
    fn windsor_just_died(&mut self, guid: ObjectGuid) {
        self.windsor_poke_rowe(guid);
        // NEEDS-MAP-HELPER: delayed `DespawnOrUnsummon(7 * MINUTE)` (cpp 58);
        // the corpse must persist for `windsor_update_corpse`.
        self.despawn_creature_now(guid, 0);
    }

    /// `npc_reginald_windsorAI::MoveInLineOfSight` (cpp 197-225).
    /// NO-DISPATCHER-YET.
    fn windsor_move_in_line_of_sight(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        if !self.unit_is_alive(victim) {
            return;
        }
        let entry = self.creatures.get(&victim).map(|c| c.info.entry);
        if !matches!(
            entry,
            Some(
                WINDSOR_NPC_STORMWIND_CITY_GUARD
                    | WINDSOR_NPC_STORMWIND_ROYAL_GUARD
                    | WINDSOR_NPC_STORMWIND_CITY_PATROL
            )
        ) {
            return;
        }
        let (dist2d, need_check, me_y) =
            match (self.unit_position(guid), self.unit_position(victim)) {
                (Some(m), Some(v)) => {
                    let dx = m.x - v.x;
                    let dy = m.y - v.y;
                    (
                        dx * dx + dy * dy,
                        self.windsor_state_mut(guid).is_some_and(|s| s.need_check),
                        m.y,
                    )
                }
                _ => return,
            };
        if dist2d >= 8.0 * 8.0 || !need_check {
            return;
        }
        let known = self
            .windsor_state_mut(guid)
            .map(|s| s.guard_guids.clone())
            .unwrap_or_default();
        if known.contains(&victim) || me_y < 360.0 {
            return;
        }
        // NEEDS-MAP-HELPER: `SetFacingToObject(m_creature)` on the guard
        // (cpp 213); no facing helper on `Map`.
        self.handle_emote_command(victim, WINDSOR_EMOTE_ONESHOT_SALUTE);
        let text = match self.rng.urand(0, 7) {
            0 => 8167,
            1 => 8170,
            2 => 8172,
            3 => 8175,
            4 => 8177,
            5 => 8180,
            6 => 8183,
            _ => 8184,
        };
        self.do_script_text(text, victim, None, -1);
        if let Some(s) = self.windsor_state_mut(guid) {
            if let Some(slot) = s.guard_guids.iter_mut().find(|g| g.is_empty()) {
                *slot = victim;
            }
        }
    }

    /// `npc_reginald_windsorAI::SpellHit` (cpp 227-231). NO-DISPATCHER-YET.
