    /// `npc_squire_roweAI::MovementInform` (cpp 857-878).
    fn rowe_movement_inform(&mut self, guid: ObjectGuid, point_id: u32) {
        // Fork gates on `POINT_MOTION_TYPE`; the dispatcher only fires for
        // point motion (smite precedent: spline filter at the call site).
        if !self.rowe_state_mut(guid).is_some_and(|s| s.event_processed) {
            return;
        }
        match point_id {
            1 => {
                let w = WINDSOR_ROWE_WAYPOINTS[1];
                self.creature_move_point(guid, 2, Position::new(w.0, w.1, w.2, 0.0), 0, 0.0, 0.0);
            }
            2 => {
                self.handle_emote_command(guid, WINDSOR_EMOTE_ONESHOT_KNEEL);
                if let Some(s) = self.rowe_state_mut(guid) {
                    s.timer_ms = 5000;
                    s.step += 1;
                }
            }
            4 => {
                let flags = self.object_get_field(guid, offsets::UNIT_NPC_FLAGS);
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::UNIT_NPC_FLAGS),
                    flags | WINDSOR_UNIT_NPC_FLAG_GOSSIP,
                );
                // `SAY_SIGNAL_SENT` (14389) is only read here; no gossip-id
                // const emitted for the other gossip menu ids (9063-9066,
                // other kinds) — inline like the fork's guard-text ids.
                self.do_script_text(14_389, guid, None, -1);
                if let Some(s) = self.rowe_state_mut(guid) {
                    s.event_processed = false;
                }
            }
            _ => {}
        }
    }

    /// `npc_squire_roweAI::UpdateAI` (cpp 880-935).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn rowe_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if self.rowe_state_mut(guid).is_some_and(|s| s.event_processed) {
            let due = match self.rowe_state_mut(guid) {
                Some(s) => {
                    if s.timer_ms < diff_ms {
                        true
                    } else {
                        s.timer_ms -= diff_ms;
                        false
                    }
                }
                None => return,
            };
            if !due {
                return;
            }
            let step = self.rowe_state_mut(guid).map_or(0, |s| s.step);
            match step {
                0 => {
                    self.set_speed_rate(guid, mangos_entities::unit::MOVE_RUN, 1.1);
                    let w = WINDSOR_ROWE_WAYPOINTS[0];
                    self.creature_move_point(
                        guid,
                        1,
                        Position::new(w.0, w.1, w.2, 0.0),
                        0,
                        0.0,
                        0.0,
                    );
                    if let Some(s) = self.rowe_state_mut(guid) {
                        s.timer_ms = 1000;
                        s.step += 1;
                    }
                }
                2 => {
                    // NEEDS-MAP-HELPER: `SummonGameObject(GO_FLARE_OF_JUSTICE
                    // 181987, -9095.8398, 411.179, 92.2445, 2.3038, 10s)`
                    // (cpp 895); no gameobject-summon helper.
                    let w = WINDSOR_ROWE_WAYPOINTS[0];
                    self.creature_move_point(
                        guid,
                        3,
                        Position::new(w.0, w.1, w.2, 0.0),
                        0,
                        0.0,
                        0.0,
                    );
                    if let Some(s) = self.rowe_state_mut(guid) {
                        s.timer_ms = 1500;
                        s.step += 1;
                    }
                }
                3 => {
                    if let Some(windsor) = self.summon_creature(
                        WINDSOR_NPC_REGINALD_WINDSOR,
                        Position::new(
                            WINDSOR_SUMMON.0,
                            WINDSOR_SUMMON.1,
                            WINDSOR_SUMMON.2,
                            WINDSOR_SUMMON.3,
                        ),
                        guid,
                        WINDSOR_TEMPSUMMON_MANUAL_DESPAWN,
                        5_400_000,
                    ) {
                        // Fork wires the fresh Windsor AI directly
                        // (cpp 905-911); state may not be bound yet in Rust
                        // (integrator: ensure `ensure_ai` ran at
                        // materialize, else this silently no-ops).
                        let (player, rowe) = match self.rowe_state_mut(guid) {
                            Some(s) => {
                                s.windsor_up = true;
                                (s.player_guid, guid)
                            }
                            None => return,
                        };
                        if let Some(ws) = self.windsor_state_mut(windsor) {
                            if !player.is_empty() {
                                ws.player_guid = Some(player);
                            }
                            ws.squire_rowe_guid = rowe;
                        }
                        // NEEDS-MAP-HELPER: `Mount(2410)` (cpp 914).
                        self.set_walk(windsor, false);
                        self.set_speed_rate(windsor, mangos_entities::unit::MOVE_RUN, 1.0);
                        let w = WINDSOR_WAYPOINTS[0];
                        self.creature_move_point(
                            windsor,
                            0,
                            Position::new(w.0, w.1, w.2, 0.0),
                            0,
                            0.0,
                            0.0,
                        );
                        let flags = self.object_get_field(windsor, offsets::UNIT_NPC_FLAGS);
                        let _ = self.object_set_field(
                            windsor,
                            u32::from(offsets::UNIT_NPC_FLAGS),
                            flags & !WINDSOR_UNIT_NPC_FLAG_QUESTGIVER,
                        );
                    }
                    if let Some(s) = self.rowe_state_mut(guid) {
                        s.step += 1;
                    }
                }
                4 => {
                    // NEEDS-MAP-HELPER: `GetRespawnCoord` (cpp 924); no
                    // respawn-coord helper on `Map`.
                    if let Some(s) = self.rowe_state_mut(guid) {
                        s.step += 1;
                    }
                }
                _ => {}
            }
            return;
        }
        // Fork `else ScriptedAI::UpdateAI(uiDiff)`: generic combat arm.
        let _ = self.script_combat_drive(guid, true);
    }

