    /// `npc_bartlebyAI::DamageTaken` (cpp 67-80). NO-DISPATCHER-YET.
    fn bartleby_damage_taken(&mut self, guid: ObjectGuid, attacker: ObjectGuid, damage: &mut u32) {
        let health = self.unit_value_u32(guid, offsets::UNIT_FIELD_HEALTH);
        let max_health = self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXHEALTH);
        let cap = *damage > health
            || (max_health != 0 && (health - (*damage).min(health)) * 100 / max_health < 15);
        if !cap {
            return;
        }
        *damage = 0;
        // NEEDS-MAP-HELPER: `AreaExploredOrEventHappens(QUEST_BEAT 1640)`
        // on a player attacker (cpp 76-77); no quest-credit helper.
        let _ = attacker;
        self.enter_evade_mode(guid);
    }

