    /// `npc_dashel_stonefistAI::DamageTaken` (cpp 207-252). NO-DISPATCHER-YET.
    fn dashel_damage_taken(&mut self, guid: ObjectGuid, _attacker: ObjectGuid, damage: &mut u32) {
        if !self
            .dashel_state_mut(guid)
            .is_some_and(|s| s.quest_fight_started)
        {
            return;
        }
        // Fork `uiDamage > GetHealth() || GetHealthPercent() < 20.0f`.
        let health = self.unit_value_u32(guid, offsets::UNIT_FIELD_HEALTH);
        if *damage <= health && self.creature_health_percent(guid) >= 20.0 {
            return;
        }
        *damage = 0;
        self.do_script_text(DASH_SAY_PROGRESS_2, guid, None, -1);
        // NEEDS-MAP-HELPER: `RemoveAllAuras` (cpp 218); no remove-all-auras
        // helper (`remove_auras_due_to_spell` is single-spell).
        // NEEDS-MAP-HELPER: `SetFactionTemplateId(35)` (cpp 219).
        // NEEDS-MAP-HELPER: `DeleteThreatList` + `CombatStop` (cpp 220-221);
        // no threat-clear helper (`modify_threat_percent_of` is per-victim).
        self.attack_stop(guid);
        // Fork `MoveTargetedHome` (cpp 223-224): base handles evade/home
        // internals; nothing to transcribe.
        let thugs = self
            .dashel_state_mut(guid)
            .map(|s| s.thugs.clone())
            .unwrap_or_default();
        let mut any_alive = false;
        for thug in thugs {
            if !self.creatures.contains_key(&thug) || !self.unit_is_alive(thug) {
                continue;
            }
            // NEEDS-MAP-HELPER: per-thug `RemoveAllAuras` (cpp 233).
            // NEEDS-MAP-HELPER: `DeleteThreatList` + `CombatStop` (cpp 234-235).
            // NEEDS-MAP-HELPER: `SetFactionTemplateId(35)` (cpp 237).
            // Fork `MoveTargetedHome` (cpp 240-241): base handles.
            self.attack_stop(thug);
            any_alive = true;
        }
        if let Some(s) = self.dashel_state_mut(guid) {
            s.quest_fight_started = false;
            s.dialog_started = true;
            s.event_phase = DASH_MDQP_NONE;
            s.thugs_alive = any_alive;
        }
    }

    /// `npc_dashel_stonefistAI::ResetThug` (cpp 354-367).
    fn dashel_reset_thug(&mut self, guid: ObjectGuid, thug: usize) {
        if thug >= 2 {
            return;
        }
        let target = self
            .dashel_state_mut(guid)
            .and_then(|s| s.thugs.get(thug).copied())
            .unwrap_or(ObjectGuid::EMPTY);
        if target.is_empty() || !self.unit_is_alive(target) {
            return;
        }
        let p = DASH_THUG_RESET_POS[thug];
        // Fork `MovePoint(0, reset, MOVE_WALK_MODE)` (cpp 363): point id 0
        // with walk speed; `set_walk` selects the walk generator speed.
        self.set_walk(target, true);
        self.creature_move_point(target, 0, Position::new(p.0, p.1, p.2, 0.0), 0, 0.0, 0.0);
        // Fork `DespawnOrUnsummon(3000)` (cpp 364): despawn after 3s; the
        // delay arm is unmodeled, despawn is immediate here.
        self.despawn_creature_now(target, 0);
    }

