    /// `npc_dashel_stonefistAI::UpdateAI` (cpp 254-352). The fork `default`
    /// arm calls `ScriptedAI::UpdateAI`; transcribed as the shared combat
    /// drive.
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn dashel_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let phase = self
            .dashel_state_mut(guid)
            .map_or(DASH_MDQP_NONE, |s| s.event_phase);
        match phase {
            DASH_MDQP_SAY1 => {
                let due = match self.dashel_state_mut(guid) {
                    Some(s) => {
                        if s.next_phase_delay_ms < diff_ms {
                            true
                        } else {
                            s.next_phase_delay_ms -= diff_ms;
                            false
                        }
                    }
                    None => return,
                };
                if due {
                    self.do_script_text(DASH_SAY_PROGRESS_3, guid, None, -1);
                    if let Some(s) = self.dashel_state_mut(guid) {
                        s.next_phase_delay_ms = 3000;
                        s.event_phase = DASH_MDQP_SAY2;
                    }
                }
            }
            DASH_MDQP_SAY2 => {
                let due = match self.dashel_state_mut(guid) {
                    Some(s) => {
                        if s.next_phase_delay_ms < diff_ms {
                            true
                        } else {
                            s.next_phase_delay_ms -= diff_ms;
                            false
                        }
                    }
                    None => return,
                };
                if due {
                    // Recheck liveness (gm kills etc., cpp 278).
                    let thug0 = self
                        .dashel_state_mut(guid)
                        .and_then(|s| s.thugs.first().copied())
                        .unwrap_or(ObjectGuid::EMPTY);
                    if self.unit_is_alive(thug0) {
                        self.do_script_text(DASH_SAY_PROGRESS_4, thug0, None, -1);
                    }
                    if let Some(s) = self.dashel_state_mut(guid) {
                        s.next_phase_delay_ms = 1500;
                        s.event_phase = DASH_MDQP_SAY3;
                    }
                }
            }
            DASH_MDQP_SAY3 => {
                let due = match self.dashel_state_mut(guid) {
                    Some(s) => {
                        if s.next_phase_delay_ms < diff_ms {
                            true
                        } else {
                            s.next_phase_delay_ms -= diff_ms;
                            false
                        }
                    }
                    None => return,
                };
                if due {
                    let thug1 = self
                        .dashel_state_mut(guid)
                        .and_then(|s| s.thugs.get(1).copied())
                        .unwrap_or(ObjectGuid::EMPTY);
                    if self.unit_is_alive(thug1) {
                        self.do_script_text(DASH_SAY_PROGRESS_5, thug1, None, -1);
                    }
                    if let Some(s) = self.dashel_state_mut(guid) {
                        s.next_phase_delay_ms = 1000;
                        s.event_phase = DASH_MDQP_THUG_WALK_AWAY_1;
                    }
                }
            }
            DASH_MDQP_THUG_WALK_AWAY_1 => {
                let due = match self.dashel_state_mut(guid) {
                    Some(s) => {
                        if s.next_phase_delay_ms < diff_ms {
                            true
                        } else {
                            s.next_phase_delay_ms -= diff_ms;
                            false
                        }
                    }
                    None => return,
                };
                if due {
                    self.dashel_reset_thug(guid, 0);
                    if let Some(s) = self.dashel_state_mut(guid) {
                        s.next_phase_delay_ms = 1500;
                        s.event_phase = DASH_MDQP_THUG_WALK_AWAY_2;
                    }
                }
            }
            DASH_MDQP_THUG_WALK_AWAY_2 => {
                let due = match self.dashel_state_mut(guid) {
                    Some(s) => {
                        if s.next_phase_delay_ms < diff_ms {
                            true
                        } else {
                            s.next_phase_delay_ms -= diff_ms;
                            false
                        }
                    }
                    None => return,
                };
                if due {
                    self.dashel_reset_thug(guid, 1);
                    if let Some(s) = self.dashel_state_mut(guid) {
                        s.next_phase_delay_ms = 1000;
                        s.event_phase = DASH_MDQP_QUEST_COMPLETE;
                    }
                }
            }
            DASH_MDQP_QUEST_COMPLETE => {
                let due = match self.dashel_state_mut(guid) {
                    Some(s) => {
                        if s.next_phase_delay_ms < diff_ms {
                            true
                        } else {
                            s.next_phase_delay_ms -= diff_ms;
                            false
                        }
                    }
                    None => return,
                };
                if due {
                    // NEEDS-MAP-HELPER: `GroupEventHappens(1447)` on the
                    // stored player (cpp 340); no quest-credit helper.
                    let _ = self.dashel_state_mut(guid).map(|s| s.player_guid);
                    self.dashel_reset(guid);
                }
            }
            _ => {
                // `MDQP_NONE`: fork `ScriptedAI::UpdateAI(uiDiff)`.
                let _ = self.script_combat_drive(guid, true);
            }
        }
    }

    /// `npc_dashel_stonefistAI::JustReachedHome` (cpp 370-380).
    /// NO-DISPATCHER-YET (no `just_reached_home` dispatcher).
    fn dashel_just_reached_home(&mut self, guid: ObjectGuid) {
        let (dialog_started, thugs_alive) = match self.dashel_state_mut(guid) {
            Some(s) => (s.dialog_started, s.thugs_alive),
            None => return,
        };
        if !dialog_started {
            return;
        }
        if let Some(s) = self.dashel_state_mut(guid) {
            s.event_phase = if thugs_alive {
                DASH_MDQP_SAY1
            } else {
                DASH_MDQP_QUEST_COMPLETE
            };
        }
    }

    /// `npc_dashel_stonefistAI::JustDied` (cpp 382-396).
    fn dashel_just_died(&mut self, guid: ObjectGuid) {
        let active = self
            .dashel_state_mut(guid)
            .is_some_and(|s| s.dialog_started || s.quest_fight_started);
        if !active {
            return;
        }
        let thugs = self
            .dashel_state_mut(guid)
            .map(|s| s.thugs.clone())
            .unwrap_or_default();
        for thug in thugs {
            if self.creatures.contains_key(&thug) {
                // Fork `TemporarySummon::UnSummon()` (cpp 391).
                self.despawn_creature_now(thug, 0);
            }
        }
        if let Some(s) = self.dashel_state_mut(guid) {
            s.thugs.fill(ObjectGuid::EMPTY);
        }
    }

    /// `npc_dashel_stonefistAI::SummonedCreatureJustDied` (cpp 397-407).
    /// NO-DISPATCHER-YET.
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn dashel_summoned_just_died(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        if let Some(s) = self.dashel_state_mut(guid) {
            for t in &mut s.thugs {
                if *t == victim {
                    *t = ObjectGuid::EMPTY;
                }
            }
        }
    }

    /// `npc_dashel_stonefistAI::SummonedCreatureDespawn` (cpp 409-416).
