    fn dashel_summoned_despawn(&mut self, guid: ObjectGuid, summoned: ObjectGuid) {
        if let Some(s) = self.dashel_state_mut(guid) {
            for t in &mut s.thugs {
                if *t == summoned {
                    *t = ObjectGuid::EMPTY;
                }
            }
        }
    }

