    /// `npc_malfurionAI` ctor + `Reset` (`sunken_temple.cpp:57-80`).
    /// Fork `Reset()` is empty; the ctor runs once at spawn (flag strip,
    /// visibility off, temple emote) while the reset dispatch also fires on
    /// evade — the integrator should gate the one-time arm at spawn.
    fn malfurion_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.malfurion_state_mut(guid) {
            s.say_timer_ms = 3000;
            s.speech = 0;
            // NEEDS-MAP-HELPER: seed `in_dungeon` from `GetMap()->IsDungeon()`
            // (cpp 66); no map-dungeon helper.
        }
        let flags = self.object_get_field(guid, offsets::UNIT_NPC_FLAGS);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_NPC_FLAGS),
            flags & !(MALF_UNIT_NPC_FLAG_QUESTGIVER | MALF_UNIT_NPC_FLAG_GOSSIP),
        );
        // NEEDS-MAP-HELPER: one-time spawn arm (cpp 68-73):
        // `SetVisibility(VISIBILITY_OFF)` + `DoScriptText(EMOTE_MALFURION1)`
        // when in the dungeon; no visibility helper.
    }

    /// `npc_malfurionAI::UpdateAI` (cpp 82-137).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn malfurion_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if !self.malfurion_state_mut(guid).is_some_and(|s| s.in_dungeon) {
            return;
        }
        let speech = self
            .malfurion_state_mut(guid)
            .map_or(MALF_MAX_TEMPLE_SPEECHES, |s| s.speech);
        if speech >= MALF_MAX_TEMPLE_SPEECHES {
            return;
        }
        let due = match self.malfurion_state_mut(guid) {
            Some(s) => {
                if s.say_timer_ms <= diff_ms {
                    true
                } else {
                    s.say_timer_ms -= diff_ms;
                    false
                }
            }
            None => return,
        };
        if !due {
            return;
        }
        match speech {
            0 => {
                // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_ON)` (cpp 94).
                self.handle_emote_command(guid, MALF_EMOTE_ONESHOT_ROAR);
                self.cast_spell(
                    guid,
                    MALF_SPELL_RESURRECT_VISUAL,
                    CastTarget::SelfCast,
                    CastOptions {
                        triggered: true,
                        triggered_by_aura: false,
                        skip_known: true,
                        cast_item: None,
                        custom_base_points: [None; 3],
                        triggered_by_aura_spell: 0,
                        triggered_by_spell: 0,
                    },
                );
                if let Some(s) = self.malfurion_state_mut(guid) {
                    s.say_timer_ms = 1500;
                }
            }
            1 => {
                self.handle_emote_command(guid, MALF_EMOTE_ONESHOT_BOW);
                if let Some(s) = self.malfurion_state_mut(guid) {
                    s.say_timer_ms = 2000;
                }
            }
            2 => {
                self.do_script_text(MALF_SAY_MALFURION1, guid, None, -1);
                if let Some(s) = self.malfurion_state_mut(guid) {
                    s.say_timer_ms = 10_000;
                }
            }
            3 => {
                self.do_script_text(MALF_SAY_MALFURION2, guid, None, -1);
                if let Some(s) = self.malfurion_state_mut(guid) {
                    s.say_timer_ms = 10_000;
                }
            }
            4 => {
                self.do_script_text(MALF_SAY_MALFURION3, guid, None, -1);
                if let Some(s) = self.malfurion_state_mut(guid) {
                    s.say_timer_ms = 8000;
                }
            }
            5 => {
                self.do_script_text(MALF_SAY_MALFURION4, guid, None, -1);
                if let Some(s) = self.malfurion_state_mut(guid) {
                    s.say_timer_ms = 5000;
                }
            }
            6 => {
                let flags = self.object_get_field(guid, offsets::UNIT_NPC_FLAGS);
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::UNIT_NPC_FLAGS),
                    flags | (MALF_UNIT_NPC_FLAG_QUESTGIVER | MALF_UNIT_NPC_FLAG_GOSSIP),
                );
            }
            _ => {}
        }
        if let Some(s) = self.malfurion_state_mut(guid) {
            s.speech += 1;
        }
    }

