    /// `boss_archaedasAI::Reset` (cpp 86-97). Spawn coords / `just_created`
    /// are ctor state (see `ArchaedasAi::new`); the flag arm runs here.
    fn archaedas_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.archaedas_state_mut(guid) {
            s.tremor_timer_ms = 60_000;
            s.awaken_timer_ms = 0;
            s.wall_minion_timer_ms = 10_000;
            s.room_check_ms = 500;
            s.waking_up = false;
            s.guardians_awake = false;
            s.vault_warders_awake = false;
        }
        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_FLAGS),
            flags | ARCH_UNIT_FLAG_NOT_SELECTABLE,
        );
    }

    /// `boss_archaedasAI::SpellHit` (cpp 99-108). NO-DISPATCHER-YET.
    fn archaedas_spell_hit(&mut self, guid: ObjectGuid, _caster: ObjectGuid, spell_id: u32) {
        let waking = self.archaedas_state_mut(guid).is_some_and(|s| s.waking_up);
        if spell_id != ULD_SPELL_ARCHAEDAS_AWAKEN || waking {
            return;
        }
        self.do_script_text(ARCH_SAY_AGGRO, guid, None, -1);
        if let Some(s) = self.archaedas_state_mut(guid) {
            s.awaken_timer_ms = 4000;
            s.waking_up = true;
        }
    }

