    /// `boss_archaedasAI::UpdateAI` (cpp 119-219).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn archaedas_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Spawn-time `JustReachedHome` (cpp 121-126).
        let just_created = self
            .archaedas_state_mut(guid)
            .is_some_and(|s| s.just_created);
        if just_created {
            if let Some(s) = self.archaedas_state_mut(guid) {
                s.just_created = false;
            }
            self.archaedas_just_reached_home(guid);
        }
        // Dormant until the altar event starts the encounter (cpp 127-128).
        if self.instance_get_data(ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS) != Some(IN_PROGRESS) {
            return;
        }
        // Awaken animation (cpp 131-144, `int32` timer).
        let waking = self.archaedas_state_mut(guid).is_some_and(|s| s.waking_up);
        if waking {
            let still_waiting = match self.archaedas_state_mut(guid) {
                Some(s) => {
                    if s.awaken_timer_ms >= 0 {
                        let step: i32 = diff_ms.try_into().unwrap_or(i32::MAX);
                        s.awaken_timer_ms = s.awaken_timer_ms.saturating_sub(step);
                        true
                    } else {
                        false
                    }
                }
                None => return,
            };
            if still_waiting {
                return;
            }
            if let Some(s) = self.archaedas_state_mut(guid) {
                s.waking_up = false;
            }
            // NEEDS-MAP-HELPER: `SelectNearestTarget(80.0f)` (cpp 139);
            // `nearest_creature_with_entry` is entry-filtered.
            return;
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Room check (cpp 153-163).
        let room_due = match self.archaedas_state_mut(guid) {
            Some(s) => {
                if s.room_check_ms <= diff_ms {
                    s.room_check_ms = 500;
                    true
                } else {
                    s.room_check_ms -= diff_ms;
                    false
                }
            }
            None => return,
        };
        if room_due {
            // `UnitIsOutside`: 2D distance from the spawn point > 38.
            let (sx, sy) = match self.archaedas_state_mut(guid) {
                Some(s) => (s.spawn_x, s.spawn_y),
                None => return,
            };
            let outside = match (self.unit_position(guid), self.unit_position(victim)) {
                (Some(m), Some(v)) => {
                    let dxm = m.x - sx;
                    let dym = m.y - sy;
                    let dxv = v.x - sx;
                    let dyv = v.y - sy;
                    dxm * dxm + dym * dym > 38.0 * 38.0 || dxv * dxv + dyv * dyv > 38.0 * 38.0
                }
                _ => false,
            };
            if outside {
                self.enter_evade_mode(guid);
                return;
            }
        }
        // Wake a wall minion every 10s (cpp 166-172; re-sets IN_PROGRESS).
        let wall_due = match self.archaedas_state_mut(guid) {
            Some(s) => {
                if s.wall_minion_timer_ms <= diff_ms {
                    s.wall_minion_timer_ms = 10_000;
                    true
                } else {
                    s.wall_minion_timer_ms -= diff_ms;
                    false
                }
            }
            None => return,
        };
        if wall_due {
            self.instance_set_data(ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS, IN_PROGRESS);
        }
        // Guardians at 66% (cpp 175-180).
        if !self
            .archaedas_state_mut(guid)
            .is_some_and(|s| s.guardians_awake)
            && self.creature_health_percent(guid) <= 66.0
        {
            self.cast_spell(
                guid,
                ARCH_SPELL_AWAKEN_EARTHEN_GUARDIAN,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: false,
                    triggered_by_aura: false,
                    skip_known: true,
                    cast_item: None,
                    custom_base_points: [None; 3],
                    triggered_by_aura_spell: 0,
                    triggered_by_spell: 0,
                },
            );
            self.do_script_text(ARCH_SAY_SUMMON, guid, None, -1);
            if let Some(s) = self.archaedas_state_mut(guid) {
                s.guardians_awake = true;
            }
        }
        // Vault warders at 33% (cpp 183-206).
        if !self
            .archaedas_state_mut(guid)
            .is_some_and(|s| s.vault_warders_awake)
            && self.creature_health_percent(guid) <= 33.0
        {
            for field in [12u32, 13u32] {
                if let Some(furniture) = self.instance_get_data64(field) {
                    self.despawn_creature_now(furniture, 0);
                }
            }
            // NEEDS-MAP-HELPER: `SetFactionTemporary(415,
            // RESTORE_RESPAWN | RESTORE_COMBAT_STOP)` (cpp 194/200).
            for field in [1u32, 2u32] {
                if let Some(warder) = self.instance_get_data64(field) {
                    let flags = self.object_get_field(warder, offsets::UNIT_FIELD_FLAGS);
                    let _ = self.object_set_field(
                        warder,
                        u32::from(offsets::UNIT_FIELD_FLAGS),
                        flags
                            & !(ARCH_UNIT_FLAG_IMMUNE_TO_PLAYER
                                | ARCH_UNIT_FLAG_IMMUNE_TO_NPC
                                | ARCH_UNIT_FLAG_NOT_SELECTABLE),
                    );
                    self.cast_spell(
                        warder,
                        ARCH_SPELL_STONE_DWARF_AWAKEN,
                        CastTarget::SelfCast,
                        CastOptions {
                            triggered: false,
                            triggered_by_aura: false,
                            skip_known: true,
                            cast_item: None,
                            custom_base_points: [None; 3],
                            triggered_by_aura_spell: 0,
                            triggered_by_spell: 0,
                        },
                    );
                }
            }
            self.cast_spell(
                guid,
                ARCH_SPELL_AWAKEN_VAULT_WARDER,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: false,
                    triggered_by_aura: false,
                    skip_known: true,
                    cast_item: None,
                    custom_base_points: [None; 3],
                    triggered_by_aura_spell: 0,
                    triggered_by_spell: 0,
                },
            );
            self.do_script_text(ARCH_SAY_SUMMON_2, guid, None, -1);
            if let Some(s) = self.archaedas_state_mut(guid) {
                s.vault_warders_awake = true;
            }
        }
        // Ground Tremor (cpp 208-216).
        let tremor_due = match self.archaedas_state_mut(guid) {
            Some(s) => {
                if s.tremor_timer_ms <= diff_ms {
                    true
                } else {
                    s.tremor_timer_ms -= diff_ms;
                    false
                }
            }
            None => return,
        };
        if tremor_due
            && self.do_cast_spell_if_can(guid, ARCH_SPELL_GROUND_TREMOR, CastTarget::Unit(victim))
        {
            if let Some(s) = self.archaedas_state_mut(guid) {
                s.tremor_timer_ms = 45_000;
            }
        }
    }

    fn archaedas_minion_state_mut(&mut self, guid: ObjectGuid) -> Option<&mut ArchaedasMinionAi> {
        match self.ai.get_mut(&guid).and_then(|ai| ai.script.as_mut()) {
            Some(CreatureScriptAi::ArchaedasMinion(s)) => Some(s),
            _ => None,
        }
    }

    /// `mob_archaedas_minionsAI::Reset` (cpp 272-284).
    fn archaedas_minion_reset(&mut self, guid: ObjectGuid) {
        let trample = self.rng.urand(4000, 10_000);
        let reconstruct = self.rng.urand(4000, 10_000);
        if let Some(s) = self.archaedas_minion_state_mut(guid) {
            s.trample_timer_ms = trample;
            s.reconstruct_timer_ms = reconstruct;
            s.awaken_timer_ms = 4000;
            s.wake_spell_hit = false;
            s.woken_up = false;
            s.waking_up = false;
            s.awake = false;
        }
        // NEEDS-MAP-HELPER: `EnableMoveInLosEvent` (cpp 283); no move-in-LOS
        // event flag helper on `Map`.
    }

    /// `mob_archaedas_minionsAI::EnterEvadeMode` (cpp 286-301, pre-base).
    /// Fork re-acquires Archaedas's victim (or any nearby hostile) and skips
    /// the base + `Reset` entirely when it finds one; the dispatcher runs
    /// reset after — the early-return divergence is the integrator's.
    fn archaedas_minion_enter_evade(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: `SelectNearestHostileUnitInAggroRange(true)`
        // (cpp 288); no aggro-range helper on `Map`.
        let archaedas_victim = self
            .instance_get_data64(11)
            .and_then(|a| self.unit_victim(a));
        if let Some(target) = archaedas_victim {
            self.attack_start(guid, target);
        }
    }

    /// `mob_archaedas_minionsAI::JoinCombat` (cpp 302-310).
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn archaedas_minion_join_combat(&mut self, guid: ObjectGuid) {
        // `SetData64(1, me)` unfreezes the minion (`uld_set_data64`,
        // `ULD_UNIT_FLAG_FROZEN` handling lives in the instance port).
        self.instance_set_data64(1, guid);
        if let Some(s) = self.archaedas_minion_state_mut(guid) {
            s.awake = true;
        }
        // NEEDS-MAP-HELPER: `SelectNearestTarget(80.0f)` (cpp 306).
    }

    /// `mob_archaedas_minionsAI::SpellHit` (cpp 312-326). NO-DISPATCHER-YET.
    fn archaedas_minion_spell_hit(&mut self, guid: ObjectGuid, _caster: ObjectGuid, spell_id: u32) {
        if spell_id == ULD_SPELL_AWAKEN_EARTHEN_DWARF
            || spell_id == ARCH_SPELL_AWAKEN_EARTHEN_GUARDIAN
        {
            if let Some(s) = self.archaedas_minion_state_mut(guid) {
                s.wake_spell_hit = true;
                s.woken_up = true;
            }
        } else if spell_id == ARCH_SPELL_AWAKEN_VAULT_WARDER {
            if let Some(s) = self.archaedas_minion_state_mut(guid) {
                s.wake_spell_hit = true;
            }
            self.archaedas_minion_join_combat(guid);
        }
    }

    /// `mob_archaedas_minionsAI::MoveInLineOfSight` (cpp 328-334).
    /// NO-DISPATCHER-YET.
    fn archaedas_minion_move_in_line_of_sight(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        // Fork gates the base proximity-aggro on `bAwake`.
        if !self
            .archaedas_minion_state_mut(guid)
            .is_some_and(|s| s.awake)
        {
            return;
        }
        let _ = victim;
        self.try_proximity_aggro(guid);
    }

    /// `mob_archaedas_minionsAI::UpdateAI` (cpp 336-398).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn archaedas_minion_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if self.instance_get_data(ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS) != Some(IN_PROGRESS) {
            if self
                .archaedas_minion_state_mut(guid)
                .is_some_and(|s| s.wake_spell_hit)
            {
                self.archaedas_minion_reset(guid);
            }
            return;
        }
        // 1st wake phase: wait for the awakening spell, then play the
        // stone-dwarf visual (cpp 345-351).
        let woken_up = self
            .archaedas_minion_state_mut(guid)
            .is_some_and(|s| s.woken_up);
        if woken_up {
            let awaken = self
                .archaedas_minion_state_mut(guid)
                .map_or(0, |s| s.awaken_timer_ms);
            if awaken <= diff_ms.saturating_add(3000) {
                self.cast_spell(
                    guid,
                    ARCH_SPELL_STONE_DWARF_AWAKEN,
                    CastTarget::SelfCast,
                    CastOptions {
                        triggered: false,
                        triggered_by_aura: false,
                        skip_known: true,
                        cast_item: None,
                        custom_base_points: [None; 3],
                        triggered_by_aura_spell: 0,
                        triggered_by_spell: 0,
                    },
                );
                if let Some(s) = self.archaedas_minion_state_mut(guid) {
                    s.waking_up = true;
                    s.woken_up = false;
                    s.awaken_timer_ms = s.awaken_timer_ms.saturating_sub(diff_ms);
                }
                return;
            }
        }
        // 2nd wake phase: wait out the visual, then join if still
        // IN_PROGRESS (cpp 354-362).
        let waking_up = self
            .archaedas_minion_state_mut(guid)
            .is_some_and(|s| s.waking_up);
        if waking_up {
            let awaken = self
                .archaedas_minion_state_mut(guid)
                .map_or(0, |s| s.awaken_timer_ms);
            if awaken <= diff_ms {
                if let Some(s) = self.archaedas_minion_state_mut(guid) {
                    s.waking_up = false;
                    s.awaken_timer_ms = 4000;
                }
                if self.instance_get_data(ULD_ULDAMAN_ENCOUNTER_ARCHAEDAS) == Some(IN_PROGRESS) {
                    self.archaedas_minion_join_combat(guid);
                }
                return;
            }
        }
        let mid_wake = self
            .archaedas_minion_state_mut(guid)
            .is_some_and(|s| s.woken_up || s.waking_up);
        if mid_wake {
            if let Some(s) = self.archaedas_minion_state_mut(guid) {
                s.awaken_timer_ms = s.awaken_timer_ms.saturating_sub(diff_ms);
            }
            return;
        }
        // Earthen Custodian heal (cpp 369-381).
        if self
            .archaedas_minion_state_mut(guid)
            .is_some_and(|s| s.awake)
            && self
                .creatures
                .get(&guid)
                .is_some_and(|c| c.info.entry == ULD_NPC_EARTHEN_CUSTODIAN)
        {
            let due = match self.archaedas_minion_state_mut(guid) {
                Some(s) => {
                    if s.reconstruct_timer_ms <= diff_ms {
                        true
                    } else {
                        s.reconstruct_timer_ms -= diff_ms;
                        false
                    }
                }
                None => return,
            };
            if due {
                if let Some(archaedas) = self.instance_get_data64(11) {
                    if self.creature_health_percent(archaedas) < 50.0 {
                        self.do_cast_spell_if_can(
                            guid,
                            ARCHMIN_SPELL_RECONSTRUCT,
                            CastTarget::Unit(archaedas),
                        );
                    }
                }
                if let Some(s) = self.archaedas_minion_state_mut(guid) {
                    s.reconstruct_timer_ms = 10_000;
                }
            }
        } else if let Some(s) = self.archaedas_minion_state_mut(guid) {
            s.reconstruct_timer_ms = s.reconstruct_timer_ms.saturating_sub(diff_ms);
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Vault Warder trample (cpp 389-395).
        if self
            .creatures
            .get(&guid)
            .is_some_and(|c| c.info.entry == ULD_NPC_VAULT_WARDER)
        {
            let due = match self.archaedas_minion_state_mut(guid) {
                Some(s) => {
                    if s.trample_timer_ms <= diff_ms {
                        true
                    } else {
                        s.trample_timer_ms -= diff_ms;
                        false
                    }
                }
                None => return,
            };
            if due
                && self.do_cast_spell_if_can(guid, ARCHMIN_SPELL_TRAMPLE, CastTarget::Unit(victim))
            {
                if let Some(s) = self.archaedas_minion_state_mut(guid) {
                    s.trample_timer_ms = 10_000;
                }
            }
        } else if let Some(s) = self.archaedas_minion_state_mut(guid) {
            s.trample_timer_ms = s.trample_timer_ms.saturating_sub(diff_ms);
        }
        // Fork `uiArcing_Timer` (cpp 262/273) is never read by the fork
        // UpdateAI either (dropped from state; see struct docs).
    }

