    /// `boss_ironayaAI::Reset` (cpp 48-52; only the bools — `Arcing_Timer`
    /// is never initialized by the fork, `hasMoved` is ctor state).
    fn ironaya_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.ironaya_state_mut(guid) {
            s.casted_knockaway = false;
            s.casted_wstomp = false;
        }
    }

    /// `boss_ironayaAI::Aggro` (cpp 54-58).
    fn ironaya_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        self.do_script_text(IRON_SAY_AGGRO, guid, None, -1);
        self.set_in_combat_with_zone(guid);
    }

    /// `boss_ironayaAI::UpdateAI` (cpp 60-112).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn ironaya_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // First-victim engage (cpp 62-69): while still flagged immune, pull
        // the keystone opener onto the threat list once.
        if !self.ironaya_state_mut(guid).is_some_and(|s| s.moved) {
            let immune = {
                let flags = self.unit_value_u32(guid, offsets::UNIT_FIELD_FLAGS);
                flags & (IRON_UNIT_FLAG_IMMUNE_TO_PLAYER | IRON_UNIT_FLAG_IMMUNE_TO_NPC) != 0
            };
            if !immune {
                if let Some(target) = self
                    .instance_get_data64(0)
                    .filter(|t| self.creatures.contains_key(t) || self.players.contains_key(t))
                {
                    self.attack_start(guid, target);
                }
                if let Some(s) = self.ironaya_state_mut(guid) {
                    s.moved = true;
                }
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Knockaway once at 50% (cpp 78-94).
        if !self
            .ironaya_state_mut(guid)
            .is_some_and(|s| s.casted_knockaway)
            && self.creature_health_percent(guid) < 50.0
        {
            self.cast_spell(
                guid,
                IRON_SPELL_KNOCKAWAY,
                CastTarget::Unit(victim),
                CastOptions {
                    triggered: false,
                    triggered_by_aura: false,
                    skip_known: true,
                    cast_item: None,
                    custom_base_points: [None; 3],
                    triggered_by_aura_spell: 0,
                    triggered_by_spell: 0,
                },
            );
            self.modify_threat_percent_of(guid, victim, -100);
            // Retarget off the knocked-away victim (cpp 84-88):
            // TOPAGGRO 0, else TOPAGGRO 1 when same/missing.
            let mut target = self.select_attacking_target(guid, 1, 0, 0);
            if target.is_none_or(|t| Some(t) == Some(victim)) {
                target = self.select_attacking_target(guid, 1, 1, 0);
            }
            if let Some(t) = target {
                self.attack_start(guid, t);
            }
            if let Some(s) = self.ironaya_state_mut(guid) {
                s.casted_knockaway = true;
            }
        }
        // Arcing Smash (cpp 97-103): fork reads the never-initialized timer
        // with `< diff` (see `IronayaAi`).
        let arcing_due = match self.ironaya_state_mut(guid) {
            Some(s) => {
                if s.arcing_timer_ms < diff_ms {
                    true
                } else {
                    s.arcing_timer_ms -= diff_ms;
                    false
                }
            }
            None => return,
        };
        if arcing_due
            && self.do_cast_spell_if_can(guid, IRON_SPELL_ARCINGSMASH, CastTarget::SelfCast)
        {
            if let Some(s) = self.ironaya_state_mut(guid) {
                s.arcing_timer_ms = 13_000;
            }
        }
        // Stomp once at 25% (cpp 105-109).
        if !self
            .ironaya_state_mut(guid)
            .is_some_and(|s| s.casted_wstomp)
            && self.creature_health_percent(guid) < 25.0
            && self.do_cast_spell_if_can(guid, IRON_SPELL_WSTOMP, CastTarget::SelfCast)
        {
            if let Some(s) = self.ironaya_state_mut(guid) {
                s.casted_wstomp = true;
            }
        }
    }

