    /// `AnnoraAI` ctor + `Reset` (`uldaman.cpp:172-185`). Fork `Reset()` is
    /// empty and `Aggro()` is empty; spawn effects (invisible + immune) are
    /// ctor state re-applied here (reset dispatch is the spawn hook).
    fn annora_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.annora_state_mut(guid) {
            s.scorpion_count = 0;
            s.spawned = false;
        }
        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_FLAGS),
            flags | (ANNO_UNIT_FLAG_IMMUNE_TO_PLAYER | ANNO_UNIT_FLAG_IMMUNE_TO_NPC),
        );
        // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_OFF)` (cpp 175);
        // no visibility helper.
    }

    /// `AnnoraAI::Aggro` (cpp 187: explicit no-op).
    #[allow(clippy::unused_self)]
    fn annora_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        let _ = guid;
    }

    /// `AnnoraAI::UpdateAI` (cpp 189-221).
    fn annora_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let _ = diff_ms;
        if self.annora_state_mut(guid).is_some_and(|s| !s.spawned) {
            // `GetCreatureListWithEntryInGrid(7078, 30.0f)` live count
            // (cpp 191-206).
            let me = self.unit_position(guid);
            let mut count = 0u32;
            if let Some(mp) = me {
                for c in self.creatures.values() {
                    if c.info.entry != ANNO_NPC_SCORPION || !c.unit.is_alive() {
                        continue;
                    }
                    if let Some(p) = self.object_position(c.unit.guid()) {
                        let dx = p.x - mp.x;
                        let dy = p.y - mp.y;
                        if dx * dx + dy * dy <= 30.0 * 30.0 {
                            count += 1;
                        }
                    }
                }
            }
            if let Some(s) = self.annora_state_mut(guid) {
                s.scorpion_count = count;
            }
            let empty = self
                .annora_state_mut(guid)
                .is_some_and(|s| s.scorpion_count == 0);
            if empty {
                // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_ON)` (cpp 208).
                self.creature_move_point(
                    guid,
                    1,
                    Position::new(ANNO_MOVE_X, ANNO_MOVE_Y, ANNO_MOVE_Z, 0.0),
                    0,
                    0.0,
                    0.0,
                );
                if let Some(s) = self.annora_state_mut(guid) {
                    s.spawned = true;
                }
            }
        } else {
            // Already revealed; fall through to the (targetless) combat arm.
        }
        // Fork always runs the targetless combat arm (cpp 214-220).
        let _ = self.script_combat_drive(guid, true);
    }

    /// `npc_reginald_windsorAI::UpdateAI_corpse` (cpp 131-173).
    /// NO-DISPATCHER-YET (corpse update has no `creature_script_*` hook).
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn windsor_update_corpse(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if !self.windsor_state_mut(guid).is_some_and(|s| s.phase_finale) {
            return;
        }
        // NEEDS-MAP-HELPER: `GetRespawnCoord` + `SetFacingTo` on
        // Bolvar/Anduin/Onyxia, `SetEntry(1749)` + `UpdateEntry` morph on
        // Onyxia (cpp 140-159); no respawn-coord / entry-morph helpers.
        let expired = match self.windsor_state_mut(guid) {
            Some(s) => {
                if s.final_timer_ms < diff_ms {
                    true
                } else {
                    s.final_timer_ms -= diff_ms;
                    false
                }
            }
            None => return,
        };
        if expired {
            if let Some(s) = self.windsor_state_mut(guid) {
                s.the_end = true;
                s.final_timer_ms = 5000;
            }
        }
        let the_end = self.windsor_state_mut(guid).is_some_and(|s| s.the_end);
        if !the_end {
            return;
        }
        let due = match self.windsor_state_mut(guid) {
            Some(s) => {
                if s.final_timer_ms < diff_ms {
                    true
                } else {
                    s.final_timer_ms -= diff_ms;
                    false
                }
            }
            None => return,
        };
        if due {
            self.windsor_poke_rowe(guid);
            if let Some(s) = self.windsor_state_mut(guid) {
                s.the_end = false;
            }
        }
    }

