    /// `npc_twilight_corrupterAI::Reset` (`duskwood.cpp:79-90`).
    fn twilight_corrupter_reset(&mut self, guid: ObjectGuid) {
        let soul = self.rng.urand(6000, 18_000);
        let nightmare = self.rng.urand(10_000, 20_000);
        if let Some(s) = self.twilight_corrupter_state_mut(guid) {
            s.soul_corruption_timer_ms = soul;
            s.creature_of_nightmare_timer_ms = nightmare;
            s.check_timer_ms = 1000;
            s.nightmare_player = ObjectGuid::EMPTY;
            s.nightmare_aggro = 0.0;
            s.engaged = false;
            s.player_guids.fill(ObjectGuid::EMPTY);
        }
    }

    /// `npc_twilight_corrupterAI::Aggro` (`duskwood.cpp:92-99`).
    fn twilight_corrupter_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        let say = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::TwilightCorrupter(s)) if !s.engaged),
        );
        if say {
            self.do_script_text(DUSK_AGGRO_TEXT, guid, None, -1);
            if let Some(s) = self.twilight_corrupter_state_mut(guid) {
                s.engaged = true;
            }
        }
    }

    /// `npc_twilight_corrupterAI::FillPlayerList` (`duskwood.cpp:101-115`).
    /// Fork quirk: no `break` in the inner loop, so one threat entry
    /// fills every empty slot.
    fn twilight_corrupter_fill_player_list(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.twilight_corrupter_state_mut(guid) {
            s.player_guids.fill(ObjectGuid::EMPTY);
        }
        let mut players = Vec::new();
        if let Some(ai) = self.ai.get(&guid) {
            for h in ai.threat.threat_list() {
                let t = mangos_threat::HostileRef::target(h);
                if t.is_player() {
                    players.push(t);
                }
            }
        }
        for t in players {
            if let Some(s) = self.twilight_corrupter_state_mut(guid) {
                for slot in &mut s.player_guids {
                    if *slot == ObjectGuid::EMPTY {
                        *slot = t;
                    }
                }
            }
        }
    }

    /// `npc_twilight_corrupterAI::UpdateAI` (`duskwood.cpp:116-185`).
    #[allow(clippy::too_many_lines)]
    fn twilight_corrupter_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let soul_due = {
            let Some(s) = self.twilight_corrupter_state_mut(guid) else {
                return;
            };
            if s.soul_corruption_timer_ms < diff_ms {
                true
            } else {
                s.soul_corruption_timer_ms -= diff_ms;
                false
            }
        };
        // Fork self-cast (`DoCastSpellIfCan(m_creature, ...)`); the
        // drive `victim` is unused here (`duskwood.cpp:121-124`).
        let _ = victim;
        if soul_due
            && self.do_cast_spell_if_can(guid, DUSK_SPELL_SOUL_CORRUPTION, CastTarget::SelfCast)
        {
            let next = self.rng.urand(20_000, 30_000);
            if let Some(s) = self.twilight_corrupter_state_mut(guid) {
                s.soul_corruption_timer_ms = next;
            }
        }
        let nightmare = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::TwilightCorrupter(s)) => Some(s.nightmare_player),
                _ => None,
            })
            .unwrap_or(ObjectGuid::EMPTY);
        if nightmare != ObjectGuid::EMPTY {
            let gone = self.player(nightmare).is_none();
            if gone {
                if let Some(s) = self.twilight_corrupter_state_mut(guid) {
                    s.nightmare_player = ObjectGuid::EMPTY;
                    s.nightmare_aggro = 0.0;
                }
            } else if !self.bot_has_aura(nightmare, DUSK_SPELL_CREATURE_OF_NIGHTMARE) {
                let aggro = self
                    .ai
                    .get(&guid)
                    .and_then(|ai| match &ai.script {
                        Some(CreatureScriptAi::TwilightCorrupter(s)) => Some(s.nightmare_aggro),
                        _ => None,
                    })
                    .unwrap_or(0.0);
                // Fork `modifyThreatPercent(pTarget, -100)` then
                // `addThreatDirectly(pTarget, CoNPlayerAggro)` (cpp 135-137).
                self.modify_threat_percent_of(guid, nightmare, -100);
                // REMAINDER: no direct-threat helper; `add_threat` adds
                // through the generic path.
                self.add_threat(guid, nightmare, aggro);
                if let Some(s) = self.twilight_corrupter_state_mut(guid) {
                    s.nightmare_player = ObjectGuid::EMPTY;
                    s.nightmare_aggro = 0.0;
                }
            }
        }
        let nightmare_due = {
            let Some(s) = self.twilight_corrupter_state_mut(guid) else {
                return;
            };
            if s.creature_of_nightmare_timer_ms < diff_ms {
                true
            } else {
                s.creature_of_nightmare_timer_ms -= diff_ms;
                false
            }
        };
        if nightmare_due {
            let target = self.select_attacking_target(guid, 0, 0, DUSK_SELECT_FLAG_NO_TOTEM);
            if let Some(target) = target
                && target.is_player()
            {
                let aggro = self.threat_on(guid, target);
                if let Some(s) = self.twilight_corrupter_state_mut(guid) {
                    s.nightmare_player = target;
                    s.nightmare_aggro = aggro;
                }
                if self.do_cast_spell_if_can(
                    guid,
                    DUSK_SPELL_CREATURE_OF_NIGHTMARE,
                    CastTarget::Unit(target),
                ) {
                    let next = self.rng.urand(35_000, 40_000);
                    if let Some(s) = self.twilight_corrupter_state_mut(guid) {
                        s.creature_of_nightmare_timer_ms = next;
                    }
                }
            }
        }
        let check_due = {
            let Some(s) = self.twilight_corrupter_state_mut(guid) else {
                return;
            };
            if s.check_timer_ms < diff_ms {
                true
            } else {
                s.check_timer_ms -= diff_ms;
                false
            }
        };
        if check_due {
            self.twilight_corrupter_fill_player_list(guid);
            // NEEDS-MAP-HELPER: dead-player sweep (`IsDead` per
            // `player_guids`, dynamic `MonsterTextEmote`, triggered
            // `SPELL_SWELL_OF_SOULS` (21307) self-cast; duskwood.cpp:164-178).
            if let Some(s) = self.twilight_corrupter_state_mut(guid) {
                s.check_timer_ms = 1000;
            }
        }
    }

