    /// `npc_sirra_vonindiAI::SummonStitches` (`duskwood.cpp:627-646`).
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn sirra_vonindi_summon_stitches(&mut self, guid: ObjectGuid) -> bool {
        let (stitches, can_summon) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::SirraVonindi(s)) => Some((s.stitches, s.can_summon)),
                _ => None,
            })
            .unwrap_or((ObjectGuid::EMPTY, false));
        if self.creatures.contains_key(&stitches) {
            return false;
        }
        if !can_summon {
            return false;
        }
        let created = self.summon_creature(
            DUSK_NPC_STITCHES,
            Position::new(-10_277.63, 54.27, 42.2, 4.22),
            guid,
            RFD_TEMPSUMMON_DEAD_DESPAWN,
            0,
        );
        // NEEDS-MAP-HELPER: active summon (`SummonCreature(..., true)`,
        // duskwood.cpp:635) + `SetObjectScale(2.0)` (duskwood.cpp:639).
        if let Some(created) = created {
            if let Some(s) = self.sirra_vonindi_state_mut(guid) {
                s.can_summon = false;
                s.stitches = created;
            }
            // NEEDS-MAP-HELPER: `LaunchStitches` cross-AI wiring
            // (`m_townCrierGuid`, `m_sirraVonIndiGuide`, `Start()`;
            // duskwood.cpp:648-661).
            return true;
        }
        false
    }

    /// `npc_sirra_vonindiAI::UpdateAI` (`duskwood.cpp:355-365`).
    /// Out-of-combat summon timer only; fork then runs the
    /// `ScriptedAI::UpdateAI` base (unmodeled).
    fn sirra_vonindi_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let (stitches, can_summon) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::SirraVonindi(s)) => Some((s.stitches, s.can_summon)),
                _ => None,
            })
            .unwrap_or((ObjectGuid::EMPTY, false));
        if stitches == ObjectGuid::EMPTY && !can_summon {
            let due = {
                let Some(s) = self.sirra_vonindi_state_mut(guid) else {
                    return;
                };
                if s.timer_ms < diff_ms {
                    true
                } else {
                    s.timer_ms -= diff_ms;
                    false
                }
            };
            if due && let Some(s) = self.sirra_vonindi_state_mut(guid) {
                s.can_summon = true;
            }
        }
        // Fork `ScriptedAI::UpdateAI(uiDiff)` base (duskwood.cpp:364).
    }

