    /// `npc_eris_havenfireAI::MoveInLineOfSight`
    /// (`eastern_plaguelands.cpp:179-195`). NO-DISPATCHER-YET.
    fn eris_havenfire_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        let (started, cleaner, player) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::ErisHavenfire(s)) => {
                    Some((s.quest_started, s.cleaner_spawn, s.player))
                }
                _ => None,
            })
            .unwrap_or((false, true, ObjectGuid::EMPTY));
        if !started || cleaner {
            return;
        }
        // NEEDS-MAP-HELPER: pet branch (`IsPet`, `who != m_playerGUID ||
        // IsPet`; eastern_plaguelands.cpp:181-183).
        if self.player(who).is_none() || who == player {
            return;
        }
        if let Some(cleaner) = self.summon_creature(
            ERIS_NPC_CLEANER,
            Position::new(3_358.11, -3_049.806, 166.226, 1.87),
            guid,
            TEMPSUMMON_TIMED_DESPAWN_OUT_OF_COMBAT,
            1000,
        ) {
            self.enter_combat(cleaner, who);
            self.creature_move_chase(cleaner, who, 0.0, 0.0);
            if let Some(s) = self.eris_havenfire_state_mut(guid) {
                s.quest_started = false;
                s.cleaner_spawn = true;
            }
            let player = self.eris_player(guid);
            self.eris_havenfire_fail_event(guid, player, false);
        }
    }

    /// `npc_eris_havenfireAI::SetAttackOnPeasantOrPlayer`
    /// (`eastern_plaguelands.cpp:197-227`).
    #[allow(clippy::cast_precision_loss)]
    fn eris_havenfire_set_attack(&mut self, guid: ObjectGuid, summoned: ObjectGuid) {
        let me = self.unit_position(guid).unwrap_or_default();
        let mut mobs = Vec::new();
        for (g, c) in &self.creatures {
            if !matches!(c.info.entry, ERIS_NPC_PEASANT_0 | ERIS_NPC_PEASANT_1) {
                continue;
            }
            if !self.unit_is_alive(*g) {
                continue;
            }
            if let Some(p) = self.object_position(*g) {
                let dx = p.x - me.x;
                let dy = p.y - me.y;
                if dx * dx + dy * dy <= 100.0 * 100.0 {
                    mobs.push(*g);
                }
            }
        }
        for mob in mobs {
            let threat = self.rng.urand(100, 200) as f32;
            self.add_threat(summoned, mob, threat);
        }
        if let Some(player) = self.eris_player(guid) {
            if self.unit_is_alive(player) {
                self.add_threat(summoned, player, 50.0);
                // NEEDS-MAP-HELPER: `player->SetCombatTimer(1500)`
                // (eastern_plaguelands.cpp:214).
                if self.rng.urand(0, 3) > 0 {
                    if let Some(victim) = self.unit_victim(summoned) {
                        // NEEDS-MAP-HELPER: `SendMeleeAttackStop(victim)`
                        // (eastern_plaguelands.cpp:219).
                        let _ = victim;
                    }
                    self.add_threat(summoned, player, 200.0);
                    // NEEDS-MAP-HELPER: `GetMotionMaster()->Clear(false)`
                    // (eastern_plaguelands.cpp:221).
                    self.creature_move_chase(summoned, player, 0.0, 0.0);
                    if let Some(victim) = self.unit_victim(summoned) {
                        // NEEDS-MAP-HELPER: `SendMeleeAttackStart(victim)`
                        // (eastern_plaguelands.cpp:223).
                        let _ = victim;
                    }
                }
            }
        }
    }

    /// `npc_eris_havenfireAI::DespawnAll`
    /// (`eastern_plaguelands.cpp:229-245`).
    fn eris_havenfire_despawn_all(&mut self, guid: ObjectGuid) {
        let me = self.unit_position(guid).unwrap_or_default();
        let mut dead = Vec::new();
        for (g, c) in &self.creatures {
            if !matches!(
                c.info.entry,
                ERIS_NPC_PEASANT_0 | ERIS_NPC_PEASANT_1 | ERIS_NPC_WARRIOR | ERIS_NPC_ARCHER
            ) {
                continue;
            }
            if !self.unit_is_alive(*g) {
                continue;
            }
            if let Some(p) = self.object_position(*g) {
                let dx = p.x - me.x;
                let dy = p.y - me.y;
                if dx * dx + dy * dy <= 150.0 * 150.0 {
                    dead.push(*g);
                }
            }
        }
        for g in dead {
            // Fork `ForcedDespawn()` (eastern_plaguelands.cpp:235).
            self.despawn_creature_now(g, 0);
        }
        let posts: Vec<ObjectGuid> = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::ErisHavenfire(s)) => Some(s.death_post_guids.to_vec()),
                _ => None,
            })
            .unwrap_or_default();
        for go in posts {
            if go != ObjectGuid::EMPTY {
                self.despawn_gameobject_now(go);
            }
        }
        if let Some(s) = self.eris_havenfire_state_mut(guid) {
            s.death_post_guids = [ObjectGuid::EMPTY; 14];
        }
    }

    /// `npc_eris_havenfireAI::JustSummoned`
    /// (`eastern_plaguelands.cpp:247-276`).
    fn eris_havenfire_just_summoned(&mut self, guid: ObjectGuid, summoned: ObjectGuid) {
        let entry = self.creatures.get(&summoned).map(|c| c.info.entry);
        match entry {
            Some(ERIS_NPC_ARCHER) => {
                self.unit_set_byte(summoned, offsets::UNIT_FIELD_BYTES_2, 0, ERIS_SHEATH_RANGED);
                if let Some(s) = self.eris_havenfire_state_mut(guid) {
                    let mut j: usize = 0;
                    while s.archer_guids[j] != ObjectGuid::EMPTY && j < 7 {
                        j += 1;
                    }
                    s.archer_guids[j] = summoned;
                }
            }
            Some(ERIS_NPC_WARRIOR) => {
                self.eris_havenfire_set_attack(guid, summoned);
            }
            Some(ERIS_NPC_PEASANT_1) => {
                // REMAINDER: fork triggered cast
                // (`CastSpell(summoned, SEETHING_PLAGUE, true)`);
                // transcribed as the aura path.
                self.apply_aura_by_id(summoned, ERIS_SPELL_SEETHING_PLAGUE, summoned);
                if let Some(s) = self.eris_havenfire_state_mut(guid) {
                    let mut j: usize = 0;
                    while s.villager_guids[j] != ObjectGuid::EMPTY && j < 49 {
                        j += 1;
                    }
                    if j < 50 {
                        s.villager_guids[j] = summoned;
                    }
                }
                let flags = self.object_get_field(summoned, offsets::UNIT_FIELD_FLAGS);
                let _ = self.object_set_field(
                    summoned,
                    u32::from(offsets::UNIT_FIELD_FLAGS),
                    flags | ERIS_UNIT_FLAG_PVP,
                );
            }
            Some(ERIS_NPC_PEASANT_0) => {
                if let Some(s) = self.eris_havenfire_state_mut(guid) {
                    let mut j: usize = 0;
                    while s.villager_guids[j] != ObjectGuid::EMPTY && j < 49 {
                        j += 1;
                    }
                    if j < 50 {
                        s.villager_guids[j] = summoned;
                    }
                }
                let flags = self.object_get_field(summoned, offsets::UNIT_FIELD_FLAGS);
                let _ = self.object_set_field(
                    summoned,
                    u32::from(offsets::UNIT_FIELD_FLAGS),
                    flags | ERIS_UNIT_FLAG_PVP,
                );
            }
            _ => {}
        }
    }

    /// `npc_eris_havenfireAI::SummonedMovementInform`
    /// (`eastern_plaguelands.cpp:278-315`). NO-DISPATCHER-YET.
    fn eris_havenfire_summoned_movement_inform(
        &mut self,
        guid: ObjectGuid,
        summoned: ObjectGuid,
        point_id: u32,
    ) {
        let entry = self.creatures.get(&summoned).map(|c| c.info.entry);
        if !matches!(entry, Some(ERIS_NPC_PEASANT_0 | ERIS_NPC_PEASANT_1)) {
            return;
        }
        if point_id != ERIS_POINT_END_EVENT {
            return;
        }
        let survived = {
            let Some(s) = self.eris_havenfire_state_mut(guid) else {
                return;
            };
            s.villager_survived += 1;
            s.villager_survived
        };
        match self.rng.urand(0, 14) {
            0 => self.do_script_text(ERIS_SAY_PEASANT_END_1, summoned, None, -1),
            1 => self.do_script_text(ERIS_SAY_PEASANT_END_2, summoned, None, -1),
            2 => self.do_script_text(ERIS_SAY_PEASANT_END_3, summoned, None, -1),
            3 => self.do_script_text(ERIS_SAY_PEASANT_END_4, summoned, None, -1),
            _ => {}
        }
        if let Some(s) = self.eris_havenfire_state_mut(guid) {
            let mut j: usize = 0;
            while s.villager_guids[j] != summoned && j < 49 {
                j += 1;
            }
            if j < 50 {
                s.villager_guids[j] = ObjectGuid::EMPTY;
            }
        }
        // Fork `ForcedDespawn()` (eastern_plaguelands.cpp:309).
        self.despawn_creature_now(summoned, 0);
        if survived >= 50 {
            let player = self.eris_player(guid);
            self.eris_havenfire_complete_event(guid, player);
        }
    }

    /// `npc_eris_havenfireAI::SummonedCreatureJustDied`
    /// (`eastern_plaguelands.cpp:317-342`).
    fn eris_havenfire_summoned_creature_just_died(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        let entry = self.creatures.get(&victim).map(|c| c.info.entry);
        if matches!(entry, Some(ERIS_NPC_PEASANT_0 | ERIS_NPC_PEASANT_1)) {
            let died = {
                let Some(s) = self.eris_havenfire_state_mut(guid) else {
                    return;
                };
                s.villager_died
            };
            if (died as usize) < ERIS_DEATH_POST_SPAWNS_COUNT {
                let spawn = ERIS_DEATH_POST_SPAWNS[died as usize];
                // NEEDS-MAP-HELPER: `SummonGameObject(spawn.0..spawn.8,
                // 1200000, false)` storing the guid in
                // `death_post_guids[died]` (eastern_plaguelands.cpp:327-328).
                let _ = spawn;
            }
            let died = {
                let Some(s) = self.eris_havenfire_state_mut(guid) else {
                    return;
                };
                s.villager_died += 1;
                s.villager_died
            };
            if died >= 15 {
                let player = self.eris_player(guid);
                self.eris_havenfire_fail_event(guid, player, true);
            }
        }
        if let Some(s) = self.eris_havenfire_state_mut(guid) {
            let mut j: usize = 0;
            while s.villager_guids[j] != victim && j < 49 {
                j += 1;
            }
            if j < 50 {
                s.villager_guids[j] = ObjectGuid::EMPTY;
            }
        }
    }

    /// `npc_eris_havenfireAI::FailEvent`
    /// (`eastern_plaguelands.cpp:344-365`).
    fn eris_havenfire_fail_event(
        &mut self,
        guid: ObjectGuid,
        player: Option<ObjectGuid>,
        npc_despawn: bool,
    ) {
        // NEEDS-MAP-HELPER: quest check (`GetQuestStatus(7622)`) +
        // `FailQuest(7622)` (eastern_plaguelands.cpp:346-347).
        let _ = player;
        if self.rng.urand(0, 1) == 1 {
            self.do_script_text(ERIS_SAY_ERIS_FAIL_1, guid, None, -1);
        } else {
            self.do_script_text(ERIS_SAY_ERIS_FAIL_2, guid, None, -1);
        }
        if let Some(light) = self.nearest_gameobject_with_entry(guid, ERIS_GO_LIGHT, 100.0) {
            // Fork `AddObjectToRemoveList`
            // (eastern_plaguelands.cpp:354-355).
            self.despawn_gameobject_now(light);
        }
        // NEEDS-MAP-HELPER: `CombatStop()` (eastern_plaguelands.cpp:357).
        self.eris_havenfire_despawn_all(guid);
        if npc_despawn {
            // Fork `DisappearAndDie()` (eastern_plaguelands.cpp:362).
            self.despawn_creature_now(guid, 0);
        } else {
            self.eris_havenfire_reset(guid);
        }
    }

    /// `npc_eris_havenfireAI::BeginEvent`
    /// (`eastern_plaguelands.cpp:367-395`).
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn eris_havenfire_begin_event(&mut self, guid: ObjectGuid, player: ObjectGuid) {
        if let Some(s) = self.eris_havenfire_state_mut(guid) {
            s.wave = 0;
            s.villager_died = 0;
            s.villager_survived = 0;
            s.cleaner_spawn = false;
            s.quest_started = true;
            s.player = player;
            s.wave_timer_ms = [10_000, 100_000];
            s.buff_timer_ms = 95_000;
            s.archer_timer_ms = [5000; 8];
            s.archer_guids = [ObjectGuid::EMPTY; 8];
            s.villager_guids = [ObjectGuid::EMPTY; 50];
        }
        for a in ERIS_EVENT
            .iter()
            .skip(ERIS_POS_ARCHER_SPAWN0)
            .take(ERIS_POS_END - ERIS_POS_ARCHER_SPAWN0)
        {
            self.summon_creature(
                ERIS_NPC_ARCHER,
                Position::new(a[0], a[1], a[2], a[3]),
                guid,
                RFD_TEMPSUMMON_DEAD_DESPAWN,
                0,
            );
        }
        if self
            .nearest_gameobject_with_entry(guid, ERIS_GO_LIGHT, 100.0)
            .is_none()
        {
            // NEEDS-MAP-HELPER: `SummonGameObject(GO_LIGHT, 3327.0,
            // -2970.0, 160.034, 5.2135, 0, 0, 0, 0, 0)`
            // (eastern_plaguelands.cpp:394).
        }
    }

    /// `npc_eris_havenfireAI::GenerateWaveNumber`
    /// (`eastern_plaguelands.cpp:446-464`).
    fn eris_havenfire_generate_wave_number(&mut self, guid: ObjectGuid, peasants: bool) -> u32 {
        let wave = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::ErisHavenfire(s)) => Some(s.wave),
                _ => None,
            })
            .unwrap_or(0);
        if wave > 4 && peasants {
            return 0;
        }
        if peasants {
            if wave == 3 {
                13
            } else if wave == 4 {
                16
            } else {
                12
            }
        } else {
            self.rng.urand(2, 6)
        }
    }

    /// `npc_eris_havenfireAI::NewWave`
    /// (`eastern_plaguelands.cpp:397-444`).
    fn eris_havenfire_new_wave(&mut self, guid: ObjectGuid, peasants: bool) {
        let count = self.eris_havenfire_generate_wave_number(guid, peasants);
        let rnd = self.rng.urand(1, 4);
        // NEEDS-MAP-HELPER: wave summon loop (`GetRandomPoint` around
        // `ERIS_EVENT[POS_PEASANT_SPAWN]` / warrior anchors 2..=4 +
        // `SummonCreature` warrior/peasant + first-peasant
        // `SAY_PEASANT_SPAWN_*` + `m_wave` increment;
        // eastern_plaguelands.cpp:404-444).
        let _ = (count, rnd, peasants);
    }

    /// `npc_eris_havenfireAI::CompleteEvent`
    /// (`eastern_plaguelands.cpp:466-484`).
    fn eris_havenfire_complete_event(&mut self, guid: ObjectGuid, player: Option<ObjectGuid>) {
        // NEEDS-MAP-HELPER: quest check (`GetQuestStatus(7622)`) +
        // `AreaExploredOrEventHappens(7622)`
        // (eastern_plaguelands.cpp:471-472).
        let _ = player;
        self.do_script_text(ERIS_SAY_ERIS_END, guid, None, -1);
        if let Some(light) = self.nearest_gameobject_with_entry(guid, ERIS_GO_LIGHT, 30.0) {
            self.despawn_gameobject_now(light);
        }
        // NEEDS-MAP-HELPER: `CombatStop()` (eastern_plaguelands.cpp:479).
        self.eris_havenfire_despawn_all(guid);
        self.eris_havenfire_reset(guid);
    }

    /// `npc_eris_havenfireAI::UpdateAI`
    /// (`eastern_plaguelands.cpp:486-569`).
    #[allow(clippy::too_many_lines)]
    fn eris_havenfire_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let (started, cleaner) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::ErisHavenfire(s)) => {
                    Some((s.quest_started, s.cleaner_spawn))
                }
                _ => None,
            })
            .unwrap_or((false, true));
        if !started || cleaner {
            return;
        }
        if let Some(player) = self.eris_player(guid) {
            // NEEDS-MAP-HELPER: `player->SetCombatTimer(1500)`
            // (eastern_plaguelands.cpp:493).
            let _ = player;
        }
        for i in 0..2 {
            let due = {
                let Some(s) = self.eris_havenfire_state_mut(guid) else {
                    return;
                };
                if s.wave_timer_ms[i] < diff_ms {
                    true
                } else {
                    s.wave_timer_ms[i] -= diff_ms;
                    false
                }
            };
            if due {
                if i == 0 {
                    self.eris_havenfire_new_wave(guid, true);
                    if let Some(s) = self.eris_havenfire_state_mut(guid) {
                        s.wave_timer_ms[i] = 80_000;
                    }
                } else {
                    let next = self.rng.urand(10_000, 14_000);
                    if let Some(s) = self.eris_havenfire_state_mut(guid) {
                        s.wave_timer_ms[i] = next;
                    }
                    // Fork `(rand() % 7) > 0` (~85%).
                    if self.rng.urand(0, 6) > 0 {
                        self.eris_havenfire_new_wave(guid, false);
                    }
                }
            }
        }
        let buff_due = {
            let Some(s) = self.eris_havenfire_state_mut(guid) else {
                return;
            };
            if s.buff_timer_ms < diff_ms {
                true
            } else {
                s.buff_timer_ms -= diff_ms;
                false
            }
        };
        if buff_due
            && self.do_cast_spell_if_can(
                guid,
                ERIS_SPELL_BLESSING_OF_NORDRASSIL,
                CastTarget::SelfCast,
            )
        {
            let player = self.eris_player(guid);
            if let Some(player) = player {
                self.do_script_text(ERIS_SAY_ERIS_HEAL, guid, Some(player), -1);
            }
            let next = self.rng.urand(75_000, 90_000);
            if let Some(s) = self.eris_havenfire_state_mut(guid) {
                s.buff_timer_ms = next;
            }
        }
        for i in 0..8 {
            let due = {
                let Some(s) = self.eris_havenfire_state_mut(guid) else {
                    return;
                };
                if s.archer_timer_ms[i] < diff_ms {
                    true
                } else {
                    s.archer_timer_ms[i] -= diff_ms;
                    false
                }
            };
            if !due {
                continue;
            }
            let archer = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::ErisHavenfire(s)) => Some(s.archer_guids[i]),
                    _ => None,
                })
                .unwrap_or(ObjectGuid::EMPTY);
            if archer == ObjectGuid::EMPTY {
                continue;
            }
            if !self.creatures.contains_key(&archer) {
                continue;
            }
            let villagers: Vec<ObjectGuid> = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::ErisHavenfire(s)) => Some(s.villager_guids.to_vec()),
                    _ => None,
                })
                .unwrap_or_default()
                .into_iter()
                .filter(|g| *g != ObjectGuid::EMPTY && self.unit_is_alive(*g))
                .collect();
            if villagers.is_empty() {
                continue;
            }
            let count = villagers.len() as u32;
            let target = villagers[self.rng.urand(0, count - 1) as usize];
            // REMAINDER: fork triggered cast
            // (`pArcher->CastSpell(pTarget, SPELL_SHOOT, true)`); the
            // shared helper issues untriggered casts.
            if self.do_cast_spell_if_can(archer, ERIS_SPELL_SHOOT, CastTarget::Unit(target)) {
                let next = self.rng.urand(3000, 4400);
                if let Some(s) = self.eris_havenfire_state_mut(guid) {
                    s.archer_timer_ms[i] = next;
                }
            }
        }
    }

