    /// `npc_eris_havenfire_peasantAI::Reset`
    /// (`eastern_plaguelands.cpp:600-614`).
    #[allow(clippy::cast_precision_loss)]
    #[allow(clippy::similar_names)]
    #[allow(clippy::cast_precision_loss)]
    #[allow(clippy::similar_names)]
    #[allow(clippy::cast_precision_loss)]
    fn eris_peasant_reset(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: the guarded `GetRandomPoint(dest, 5.0)` roll
        // (eastern_plaguelands.cpp:602-603); its result is immediately
        // overwritten by the literals below.
        let roll_cx = self.rng.urand(0, 12) as f32;
        let roll_cy = self.rng.urand(0, 12) as f32;
        let roll_x = self.rng.urand(0, 6) as f32;
        let roll_y = self.rng.urand(0, 6) as f32;
        let say = self.rng.urand(10_000, 30_000);
        if let Some(s) = self.eris_peasant_state_mut(guid) {
            s.cx = 3_347.801 + roll_cx;
            s.cy = -3_048.162 + roll_cy;
            s.cz = 163.679_32;
            s.x = 3_324.0 + roll_x;
            s.y = -2_973.0 + roll_y;
            s.z = 161.0;
            s.need_to_move = true;
            s.say_timer_ms = say;
        }
        if let Some(ai) = self.ai.get_mut(&guid) {
            ai.combat_movement = false;
        }
    }

