    /// `npc_eris_havenfire_peasantAI::MovementInform`
    /// (`eastern_plaguelands.cpp:656-670`). Fork takes both motion
    /// type and point; the dispatcher implies `POINT_MOTION_TYPE`.
    fn eris_peasant_movement_inform(&mut self, guid: ObjectGuid, point_id: u32) {
        if point_id != ERIS_POINT_START_COMBAT {
            return;
        }
        let peasant = self
            .creatures
            .get(&guid)
            .is_none_or(|c| c.info.entry == ERIS_NPC_PEASANT_0);
        let speed = if peasant { 1.0 } else { 1.7 };
        self.set_walk(guid, true);
        let (x, y, z) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::ErisHavenfirePeasant(s)) => Some((s.x, s.y, s.z)),
                _ => None,
            })
            .unwrap_or((0.0, 0.0, 0.0));
        self.creature_move_point(
            guid,
            ERIS_POINT_END_EVENT,
            Position::new(x, y, z, 0.0),
            ERIS_MOVE_PATHFINDING,
            speed,
            0.0,
        );
        if let Some(s) = self.eris_peasant_state_mut(guid) {
            s.cx = 0.0;
            s.cy = 0.0;
            s.cz = 0.0;
        }
    }

    /// `npc_eris_havenfire_peasantAI::UpdateAI`
    /// (`eastern_plaguelands.cpp:672-703`). No combat drive (OOC walk
    /// + chatter only).
    fn eris_peasant_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let need = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::ErisHavenfirePeasant(s)) if s.need_to_move),
        );
        if need {
            let peasant = self
                .creatures
                .get(&guid)
                .is_none_or(|c| c.info.entry == ERIS_NPC_PEASANT_0);
            let speed = if peasant { 1.0 } else { 1.7 };
            // REMAINDER: fork `IsWalking` guard unmodeled; walk forced.
            self.set_walk(guid, true);
            let (cx, cy, cz) = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::ErisHavenfirePeasant(s)) => Some((s.cx, s.cy, s.cz)),
                    _ => None,
                })
                .unwrap_or((0.0, 0.0, 0.0));
            self.creature_move_point(
                guid,
                ERIS_POINT_START_COMBAT,
                Position::new(cx, cy, cz, 0.0),
                ERIS_MOVE_PATHFINDING,
                speed,
                0.0,
            );
            if let Some(s) = self.eris_peasant_state_mut(guid) {
                s.need_to_move = false;
            }
        }
        // REMAINDER: fork `IsWalking` re-check unmodeled
        // (eastern_plaguelands.cpp:682-683).
        self.set_walk(guid, true);
        let due = {
            let Some(s) = self.eris_peasant_state_mut(guid) else {
                return;
            };
            if s.say_timer_ms < diff_ms {
                true
            } else {
                s.say_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // Fork `rand() % 30` (eastern_plaguelands.cpp:687).
            match self.rng.urand(0, 29) {
                0 => self.do_script_text(ERIS_SAY_PEASANT_RANDOM_1, guid, None, -1),
                1 => self.do_script_text(ERIS_SAY_PEASANT_RANDOM_2, guid, None, -1),
                2 => self.do_script_text(ERIS_SAY_PEASANT_RANDOM_3, guid, None, -1),
                _ => {}
            }
            let next = self.rng.urand(20_000, 50_000);
            if let Some(s) = self.eris_peasant_state_mut(guid) {
                s.say_timer_ms = next;
            }
        }
    }

