    /// (`eastern_plaguelands.cpp:1551-1596`). Fork does not check the
    /// motion type; the dispatcher implies `POINT_MOTION_TYPE`.
    fn joseph_redpath_movement_inform(&mut self, guid: ObjectGuid, point_id: u32) {
        match point_id {
            0 => {
                self.creature_move_point(
                    guid,
                    1,
                    Position::new(1_434.22, -3_668.756, 76.671, 0.0),
                    JOSEPH_MOVE_PATHFINDING,
                    1.5,
                    0.0,
                );
            }
            1 => {
                self.creature_move_point(
                    guid,
                    2,
                    Position::new(1_438.526, -3_632.733, 78.268, 0.0),
                    JOSEPH_MOVE_PATHFINDING,
                    1.2,
                    0.0,
                );
                self.do_script_text(JOSEPH_SAY_JOSEPH_1, guid, None, -1);
                if let Some(s) = self.joseph_redpath_state_mut(guid) {
                    s.event_timer_ms = 3000;
                }
            }
            2 => {
                if let Some(pamela) =
                    self.nearest_creature_with_entry(guid, JOSEPH_NPC_PAMELA_REDPATH, 150.0)
                {
                    self.do_script_text(JOSEPH_SAY_PAMELA_2, pamela, None, -1);
                    self.set_walk(guid, false);
                    // NEEDS-MAP-HELPER: `GetContactPoint(me, 1.0)` +
                    // `MovePoint(3, x, y, z, PATHFINDING, 4.0)`
                    // (eastern_plaguelands.cpp:1576-1578).
                    if let Some(s) = self.joseph_redpath_state_mut(guid) {
                        s.event_timer_ms = 0;
                    }
                } else if let Some(s) = self.joseph_redpath_state_mut(guid) {
                    s.event_timer_ms = 1;
                }
            }
            3 => {
                if let Some(pamela) =
                    self.nearest_creature_with_entry(guid, JOSEPH_NPC_PAMELA_REDPATH, 20.0)
                {
                    // NEEDS-MAP-HELPER: mutual `SetFacingToObject`
                    // (eastern_plaguelands.cpp:1589-1590).
                    let _ = pamela;
                }
                if let Some(s) = self.joseph_redpath_state_mut(guid) {
                    s.event_timer_ms = 2000;
                }
            }
            _ => {}
        }
    }

    /// `npc_joseph_redpathAI::UpdateAI`
    /// (`eastern_plaguelands.cpp:1598-1667`). No combat drive (event
    /// timer only).
    #[allow(clippy::too_many_lines)]
    fn joseph_redpath_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let timer = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::JosephRedpath(s)) => Some(s.event_timer_ms),
                _ => None,
            })
            .unwrap_or(0);
        if timer == 0 {
            return;
        }
        if timer > diff_ms {
            if let Some(s) = self.joseph_redpath_state_mut(guid) {
                s.event_timer_ms -= diff_ms;
            }
            return;
        }
        let step = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::JosephRedpath(s)) => Some(s.event_step),
                _ => None,
            })
            .unwrap_or(u32::MAX);
        match step {
            0 => {
                let flags = self.object_get_field(guid, offsets::UNIT_NPC_FLAGS);
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::UNIT_NPC_FLAGS),
                    flags & !JOSEPH_UNIT_NPC_FLAG_GOSSIP,
                );
                if let Some(s) = self.joseph_redpath_state_mut(guid) {
                    s.event_step += 1;
                    s.event_timer_ms = 0;
                }
                self.creature_move_point(
                    guid,
                    0,
                    Position::new(1_431.501, -3_684.229, 75.726, 0.0),
                    JOSEPH_MOVE_PATHFINDING,
                    1.5,
                    0.0,
                );
            }
            1 => {
                if let Some(pamela) =
                    self.nearest_creature_with_entry(guid, JOSEPH_NPC_PAMELA_REDPATH, 150.0)
                {
                    self.do_script_text(JOSEPH_SAY_PAMELA_1, pamela, None, -1);
                    self.creature_move_point(
                        pamela,
                        0,
                        Position::new(1_450.733, -3_599.974, 85.621, 0.0),
                        JOSEPH_MOVE_PATHFINDING,
                        4.0,
                        0.0,
                    );
                }
                if let Some(s) = self.joseph_redpath_state_mut(guid) {
                    s.event_step += 1;
                    s.event_timer_ms = 0;
                }
            }
            2 => {
                if let Some(pamela) =
                    self.nearest_creature_with_entry(guid, JOSEPH_NPC_PAMELA_REDPATH, 150.0)
                {
                    self.do_script_text(JOSEPH_SAY_PAMELA_3, pamela, None, -1);
                }
                if let Some(s) = self.joseph_redpath_state_mut(guid) {
                    s.event_step += 1;
                    s.event_timer_ms = 5000;
                }
            }
            3 => {
                self.do_script_text(JOSEPH_SAY_JOSEPH_2, guid, None, -1);
                if let Some(s) = self.joseph_redpath_state_mut(guid) {
                    s.event_step += 1;
                    s.event_timer_ms = 3000;
                }
            }
            4 => {
                if let Some(pamela) =
                    self.nearest_creature_with_entry(guid, JOSEPH_NPC_PAMELA_REDPATH, 150.0)
                {
                    self.do_script_text(JOSEPH_SAY_PAMELA_4, pamela, None, -1);
                }
                if let Some(s) = self.joseph_redpath_state_mut(guid) {
                    s.event_step += 1;
                    s.event_timer_ms = 4000;
                }
            }
            5 => {
                self.do_script_text(JOSEPH_SAY_JOSEPH_3, guid, None, -1);
                let flags = self.object_get_field(guid, offsets::UNIT_NPC_FLAGS);
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::UNIT_NPC_FLAGS),
                    flags | JOSEPH_UNIT_NPC_FLAG_GOSSIP,
                );
                // Fork `ForcedDespawn(6000/4000)`
                // (eastern_plaguelands.cpp:1654-1657).
                if let Some(pamela) =
                    self.nearest_creature_with_entry(guid, JOSEPH_NPC_PAMELA_REDPATH, 150.0)
                {
                    self.despawn_creature_now(pamela, 4);
                }
                self.despawn_creature_now(guid, 6);
                if let Some(s) = self.joseph_redpath_state_mut(guid) {
                    s.event_timer_ms = 0;
                }
            }
            _ => {}
        }
    }

