    /// `npc_demetriaAI::Reset` (`eastern_plaguelands.cpp:859-869`).
    fn demetria_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.demetria_state_mut(guid) {
            s.mind_blast_ms = 3000;
            s.shadow_word_pain_ms = 9000;
            s.mind_flay_ms = 15_000;
            s.dominate_mind_ms = 6000;
            s.psychic_scream_hp = 30;
            s.dispel_magic_ms = 0;
            s.resurrect_ms = 10_000;
        }
        self.apply_aura_by_id(guid, DEM_SPELL_SHADOWFORM, guid);
    }

    /// `npc_demetriaAI::DespawnTroopers`
    /// (`eastern_plaguelands.cpp:764-771`).
    fn demetria_despawn_troopers(&mut self, guid: ObjectGuid) {
        let troopers: Vec<ObjectGuid> = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Demetria(s)) => Some(s.trooper_guids.to_vec()),
                _ => None,
            })
            .unwrap_or_default();
        for t in troopers {
            if self.creatures.contains_key(&t) {
                // Fork `AddObjectToRemoveList`
                // (eastern_plaguelands.cpp:769).
                self.despawn_creature_now(t, 0);
            }
        }
    }

    /// `npc_demetriaAI::MovementInform`
    /// (`eastern_plaguelands.cpp:728-760`). Fork guards
    /// `WAYPOINT_MOTION_TYPE` (not point motion).
    /// NO-DISPATCHER-YET (see unresolved).
    #[allow(clippy::cast_precision_loss)]
    fn demetria_movement_inform(&mut self, guid: ObjectGuid, point_id: u32) {
        if point_id == 0 {
            if self
                .nearest_creature_with_entry(guid, DEM_NPC_SCARLET_TROOPER, 60.0)
                .is_some()
            {
                // Fork `ForcedDespawn()` (eastern_plaguelands.cpp:735).
                self.despawn_creature_now(guid, 0);
                return;
            }
            // NEEDS-MAP-HELPER: `JoinCreatureGroup` formation ring
            // (eastern_plaguelands.cpp:738) + per-trooper
            // `JoinCreatureGroup` (eastern_plaguelands.cpp:748).
            let me = self.unit_position(guid).unwrap_or_default();
            let o = me.o;
            for i in 1..=9u32 {
                let angle = i as f32 * 2.0 * core::f32::consts::PI / 9.0;
                let x = me.x + 3.0 * angle.cos();
                let y = me.y + 3.0 * angle.sin();
                let created = self.summon_creature(
                    DEM_NPC_SCARLET_TROOPER,
                    Position::new(x, y, me.z, o),
                    guid,
                    MC_TEMPSUMMON_MANUAL_DESPAWN,
                    0,
                );
                if let Some(created) = created
                    && let Some(s) = self.demetria_state_mut(guid)
                {
                    s.trooper_guids[(i - 1) as usize] = created;
                }
            }
            return;
        }
        if point_id == 99 {
            self.demetria_despawn_troopers(guid);
            // Fork `ForcedDespawn()` (eastern_plaguelands.cpp:759).
            self.despawn_creature_now(guid, 0);
        }
    }

    /// `npc_demetriaAI::JustDied` (`eastern_plaguelands.cpp:762`).
    fn demetria_just_died(&mut self, guid: ObjectGuid) {
        self.demetria_despawn_troopers(guid);
    }

    /// `npc_demetriaAI::DoRessurectUnit` (`eastern_plaguelands.cpp:871-887`,
    /// Thekal pattern).
    fn demetria_do_ressurect_unit(&mut self, dead: ObjectGuid, victim: Option<ObjectGuid>) {
        let pos = self.unit_position(dead).unwrap_or_default();
        self.unit_set_byte(dead, offsets::UNIT_FIELD_BYTES_1, 0, STAND_STATE_STAND);
        let flags = self.object_get_field(dead, offsets::UNIT_FIELD_FLAGS);
        let _ = self.object_set_field(
            dead,
            u32::from(offsets::UNIT_FIELD_FLAGS),
            flags & !ULD_UNIT_FLAG_NOT_SELECTABLE,
        );
        let max = self.object_get_field(dead, offsets::UNIT_FIELD_MAXHEALTH);
        let _ = self.object_set_field(dead, u32::from(offsets::UNIT_FIELD_HEALTH), max);
        // NEEDS-MAP-HELPER: `Respawn()` + `NearTeleportTo(x, y, z, o)` +
        // `Update(0, 0)` (eastern_plaguelands.cpp:881-883).
        let _ = pos;
        // Fork `SendSpellGo(creature, 20770)` (eastern_plaguelands.cpp:884).
        self.send_spell_go_simple(dead, DEM_SPELL_RESURRECT_VISUAL, dead, 0);
        if let Some(victim) = victim {
            self.attack_start(dead, victim);
        }
    }

    /// `npc_demetriaAI::UpdateAI` (`eastern_plaguelands.cpp:781-857`).
    #[allow(clippy::too_many_lines)]
    fn demetria_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Resurrect scan runs before the drive (no victim required).
        let resurrect_due = {
            let Some(s) = self.demetria_state_mut(guid) else {
                return;
            };
            if s.resurrect_ms < diff_ms {
                true
            } else {
                s.resurrect_ms -= diff_ms;
                false
            }
        };
        if resurrect_due {
            // NEEDS-MAP-HELPER: dead-trooper search (alive-filtered
            // `FindNearestCreature(12352, 40.0)`; the shared nearest
            // helper has no alive filter; eastern_plaguelands.cpp:785).
            if let Some(dead) =
                self.nearest_creature_with_entry(guid, DEM_NPC_SCARLET_TROOPER, 40.0)
            {
                let victim = self.unit_victim(guid);
                self.demetria_do_ressurect_unit(dead, victim);
                if let Some(s) = self.demetria_state_mut(guid) {
                    s.resurrect_ms = 10_000;
                }
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        if !self.bot_has_aura(guid, DEM_SPELL_SHADOWFORM) {
            self.do_cast_spell_if_can(guid, DEM_SPELL_SHADOWFORM, CastTarget::SelfCast);
        }
        let blast_due = {
            let Some(s) = self.demetria_state_mut(guid) else {
                return;
            };
            if s.mind_blast_ms < diff_ms {
                true
            } else {
                s.mind_blast_ms -= diff_ms;
                false
            }
        };
        let roll_6 = self.rng.urand(4000, 5000);
        if blast_due
            && self.do_cast_spell_if_can(guid, DEM_SPELL_MIND_BLAST, CastTarget::Unit(victim))
            && let Some(s) = self.demetria_state_mut(guid)
        {
            let next = roll_6;
            s.mind_blast_ms = next;
        }
        let pain_due = {
            let Some(s) = self.demetria_state_mut(guid) else {
                return;
            };
            if s.shadow_word_pain_ms < diff_ms {
                true
            } else {
                s.shadow_word_pain_ms -= diff_ms;
                false
            }
        };
        if pain_due {
            let target = self.select_attacking_target(guid, 0, 0, DEM_SELECT_FLAG_NO_TOTEM);
            let roll_5 = self.rng.urand(18_000, 24_000);
            if let Some(target) = target
                && self.do_cast_spell_if_can(
                    guid,
                    DEM_SPELL_SHADOW_WORD_PAIN,
                    CastTarget::Unit(target),
                )
                && let Some(s) = self.demetria_state_mut(guid)
            {
                s.shadow_word_pain_ms = roll_5;
            }
        }
        let flay_due = {
            let Some(s) = self.demetria_state_mut(guid) else {
                return;
            };
            if s.mind_flay_ms < diff_ms {
                true
            } else {
                s.mind_flay_ms -= diff_ms;
                false
            }
        };
        if flay_due {
            let target = self.select_attacking_target(guid, 0, 0, DEM_SELECT_FLAG_NO_TOTEM);
            let roll_4 = self.rng.urand(15_000, 18_000);
            if let Some(target) = target
                && self.do_cast_spell_if_can(guid, DEM_SPELL_MIND_FLAY, CastTarget::Unit(target))
                && let Some(s) = self.demetria_state_mut(guid)
            {
                s.mind_flay_ms = roll_4;
            }
        }
        let dominate_due = {
            let Some(s) = self.demetria_state_mut(guid) else {
                return;
            };
            if s.dominate_mind_ms < diff_ms {
                true
            } else {
                s.dominate_mind_ms -= diff_ms;
                false
            }
        };
        if dominate_due {
            let target = self.select_attacking_target(guid, 0, 1, DEM_SELECT_FLAG_NO_TOTEM);
            let roll_3 = self.rng.urand(20_000, 25_000);
            if let Some(target) = target
                && self.do_cast_spell_if_can(
                    guid,
                    DEM_SPELL_DOMINATE_MIND,
                    CastTarget::Unit(target),
                )
                && let Some(s) = self.demetria_state_mut(guid)
            {
                s.dominate_mind_ms = roll_3;
            }
        }
        let dispel_due = {
            let Some(s) = self.demetria_state_mut(guid) else {
                return;
            };
            if s.dispel_magic_ms < diff_ms {
                true
            } else {
                s.dispel_magic_ms -= diff_ms;
                false
            }
        };
        if dispel_due {
            // NEEDS-MAP-HELPER: friendly-CCed search in 15.0
            // (`CreatureListSearcher`; eastern_plaguelands.cpp:833-836) +
            // `SPELL_DISPELL_MAGIC_FRIENDLY` on the first hit.
            if self.do_cast_spell_if_can(guid, DEM_SPELL_DISPELL_MAGIC2, CastTarget::Unit(victim))
                && let Some(s) = self.demetria_state_mut(guid)
            {
                s.dispel_magic_ms = 6000;
            }
        }
        let hp_check = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Demetria(s)) => Some(s.psychic_scream_hp),
                _ => None,
            })
            .unwrap_or(0);
        if self.creature_health_percent(guid) < f32::from(hp_check)
            && self.do_cast_spell_if_can(guid, DEM_SPELL_PSYCHIC_SCREAM2, CastTarget::SelfCast)
            && let Some(s) = self.demetria_state_mut(guid)
        {
            s.psychic_scream_hp = 0;
        }
    }

