    /// `npc_guard_didierAI::JustReachedHome`
    /// (`eastern_plaguelands.cpp:1775-1808`). NO-DISPATCHER-YET.
    fn guard_didier_just_reached_home(&mut self, guid: ObjectGuid) {
        let mule_died = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::GuardDidier(s)) if s.mule_died),
        );
        if mule_died {
            if let Some(s) = self.guard_didier_state_mut(guid) {
                s.mule_died = false;
            }
            // NEEDS-MAP-HELPER: `GetMotionMaster()->Clear` + `MoveIdle`
            // (eastern_plaguelands.cpp:1780-1781).
            self.do_script_text(DID_SAY_MULE_DIED, guid, None, -1);
            self.handle_emote_command(guid, DID_EMOTE_ONESHOT_CRY);
            // NEEDS-MAP-HELPER: `SetDefaultGossipMenuId(7168)`
            // (eastern_plaguelands.cpp:1784).
            let flags = self.object_get_field(guid, offsets::UNIT_NPC_FLAGS);
            let _ = self.object_set_field(
                guid,
                u32::from(offsets::UNIT_NPC_FLAGS),
                flags | DID_UNIT_NPC_FLAG_GOSSIP,
            );
            // NEEDS-MAP-HELPER: group aura-strip
            // (`RemoveAurasDueToSpell(28114)`) + `DespawnOrUnsummon(90s)`
            // over `GetCreatureGroup` members
            // (eastern_plaguelands.cpp:1789-1798).
            // Fork `DespawnOrUnsummon(90 * IN_MILLISECONDS)`
            // (eastern_plaguelands.cpp:1799).
            self.despawn_creature_now(guid, 90);
            self.cancel_aura(guid, DID_SPELL_MARK_OF_DIDIER);
        }
        // NEEDS-MAP-HELPER: `SetReactState(REACT_PASSIVE)`
        // (eastern_plaguelands.cpp:1806).
    }

