    /// `npc_henze_faulkAI::SpellHit` (`elwynn_forest.cpp:64-74`).
    /// NO-DISPATCHER-YET.
    fn henze_faulk_spell_hit(&mut self, guid: ObjectGuid, caster: ObjectGuid, spell_id: u32) {
        if spell_id != HENZE_SPELL_HEAL_TRIGGER {
            return;
        }
        let hit = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::HenzeFaulk(s)) if !s.spell_hit),
        );
        if !hit {
            return;
        }
        self.unit_set_byte(guid, offsets::UNIT_FIELD_BYTES_1, 0, STAND_STATE_STAND);
        let _ = self.object_set_field(guid, u32::from(offsets::UNIT_DYNAMIC_FLAGS), 0);
        self.do_script_text(HENZE_SAY_HEAL, guid, Some(caster), -1);
        if let Some(s) = self.henze_faulk_state_mut(guid) {
            s.spell_hit = true;
        }
    }

    /// `npc_henze_faulkAI::UpdateAI` (`elwynn_forest.cpp:53-62`). No
    /// combat drive (OOC lie-down timer only).
    fn henze_faulk_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Fork `IsStandingUp()` (`STAND` or `DEAD`; `Unit.cpp:9351`).
        let standing = matches!(
            self.unit_value_u32(guid, offsets::UNIT_FIELD_BYTES_1) & 0xFF,
            0 | 7
        );
        if !standing {
            return;
        }
        let due = {
            let Some(s) = self.henze_faulk_state_mut(guid) else {
                return;
            };
            if s.life_timer_ms < diff_ms {
                true
            } else {
                s.life_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // Fork `m_creature->AI()->EnterEvadeMode()`
            // (elwynn_forest.cpp:58).
            self.enter_evade_mode(guid);
        }
    }

