    /// `npc_obsidionAI::Reset` (`searing_gorge.cpp:69-81`).
    fn obsidion_reset(&mut self, guid: ObjectGuid) {
        let dorius = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Obsidion(s)) => Some(s.dorius),
                _ => None,
            })
            .unwrap_or(ObjectGuid::EMPTY);
        if self.creatures.contains_key(&dorius) {
            // Fork `DeleteLater()` (searing_gorge.cpp:79).
            self.despawn_creature_now(dorius, 0);
        }
        // Fork `SetStandState(UNIT_STAND_STATE_DEAD)` (== 7).
        self.unit_set_byte(guid, offsets::UNIT_FIELD_BYTES_1, 0, 7);
        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_FLAGS),
            flags | ULD_UNIT_FLAG_IMMUNE_TO_PLAYER | ULD_UNIT_FLAG_IMMUNE_TO_NPC,
        );
        if let Some(s) = self.obsidion_state_mut(guid) {
            s.ground_smash_ms = 8000;
            s.knock_away_ms = 12_000;
            s.player_list.clear();
            s.event_running = false;
            s.dorius = ObjectGuid::EMPTY;
        }
    }

    /// `npc_obsidionAI::Aggro` (`searing_gorge.cpp:83-88`).
    fn obsidion_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_FIELD_FLAGS),
            flags & !ULD_UNIT_FLAG_IMMUNE_TO_PLAYER & !ULD_UNIT_FLAG_IMMUNE_TO_NPC,
        );
    }

    /// `npc_obsidionAI::StartEvent` (`searing_gorge.cpp:90-98`).
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn obsidion_start_event(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.obsidion_state_mut(guid) {
            s.talk_timer_ms = 5000;
            s.next_text = OBS_SAY_DORIUS1;
            s.event_running = true;
        }
        if let Some(dorius) = self.summon_creature(
            OBS_NPC_DORIUS,
            Position::new(-6_460.25, -1_244.86, 180.36, 3.04),
            guid,
            BRD_TEMPSUMMON_TIMED_OR_DEAD_DESPAWN,
            180_000,
        ) && let Some(s) = self.obsidion_state_mut(guid)
        {
            s.dorius = dorius;
        }
    }

    /// `npc_obsidionAI::SummonedCreatureDespawn`
    /// (`searing_gorge.cpp:101-105`). NO-DISPATCHER-YET.
    fn obsidion_summoned_creature_despawn(&mut self, guid: ObjectGuid, summoned: ObjectGuid) {
        let entry = self.creatures.get(&summoned).map(|c| c.info.entry);
        if entry != Some(OBS_NPC_LATHORIC_THE_BLACK) {
            return;
        }
        if self.unit_is_alive(guid) && self.ai_in_combat(guid) {
            return;
        }
        self.obsidion_reset(guid);
    }

    /// `npc_obsidionAI::JustRespawned` (`searing_gorge.cpp:107`).
    /// NO-DISPATCHER-YET (see unresolved).
    fn obsidion_just_respawned(&mut self, guid: ObjectGuid) {
        self.obsidion_reset(guid);
    }

    /// `npc_obsidionAI::UpdateAI` (`searing_gorge.cpp:109-183`).
    #[allow(clippy::too_many_lines)]
    fn obsidion_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let running = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Obsidion(s)) if s.event_running),
        );
        if !running {
            return;
        }
        if !self.ai_in_combat(guid) {
            let (next, dorius) = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::Obsidion(s)) => Some((s.next_text, s.dorius)),
                    _ => None,
                })
                .unwrap_or((0, ObjectGuid::EMPTY));
            if next == OBS_SAY_LATHORIC1
                && let Some(dorius_creature) = self.creatures.get(&dorius)
                && dorius_creature.info.entry != OBS_NPC_LATHORIC_THE_BLACK
            {
                // NEEDS-MAP-HELPER: `UpdateEntry(NPC_LATHORIC_THE_BLACK)`
                // (searing_gorge.cpp:121).
            }
            if (OBS_SAY_LATHORIC1..=OBS_SAY_DORIUS6).contains(&next) {
                let due = {
                    let Some(s) = self.obsidion_state_mut(guid) else {
                        return;
                    };
                    if s.talk_timer_ms < diff_ms {
                        true
                    } else {
                        s.talk_timer_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    if self.creatures.contains_key(&dorius) {
                        self.do_script_text(next, dorius, None, -1);
                    }
                    if let Some(s) = self.obsidion_state_mut(guid) {
                        s.next_text += 1;
                        if s.next_text > OBS_SAY_DORIUS6 {
                            s.next_text = OBS_SAY_LATHORIC1;
                        }
                        if s.next_text == OBS_SAY_DORIUS1 {
                            s.next_text += 10;
                        }
                        s.talk_timer_ms = 6000;
                    }
                }
            }
            if next == OBS_SAY_LATHORIC2 {
                let players: Vec<ObjectGuid> = self
                    .ai
                    .get(&guid)
                    .and_then(|ai| match &ai.script {
                        Some(CreatureScriptAi::Obsidion(s)) => Some(s.player_list.clone()),
                        _ => None,
                    })
                    .unwrap_or_default();
                for player in players {
                    if self.player(player).is_none() {
                        continue;
                    }
                    // Fork `SetStandState(UNIT_STAND_STATE_STAND)`
                    // (searing_gorge.cpp:147).
                    self.unit_set_byte(guid, offsets::UNIT_FIELD_BYTES_1, 0, STAND_STATE_STAND);
                    let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
                    let _ = self.object_set_field(
                        guid,
                        u32::from(offsets::UNIT_FIELD_FLAGS),
                        flags & !ULD_UNIT_FLAG_IMMUNE_TO_NPC,
                    );
                    self.attack_start(guid, player);
                    let lathoric = self
                        .ai
                        .get(&guid)
                        .and_then(|ai| match &ai.script {
                            Some(CreatureScriptAi::Obsidion(s)) => Some(s.dorius),
                            _ => None,
                        })
                        .unwrap_or(ObjectGuid::EMPTY);
                    if self.creatures.contains_key(&lathoric) {
                        let flags = self.object_get_field(lathoric, offsets::UNIT_FIELD_FLAGS);
                        let _ = self.object_set_field(
                            lathoric,
                            u32::from(offsets::UNIT_FIELD_FLAGS),
                            flags & !ULD_UNIT_FLAG_IMMUNE_TO_PLAYER,
                        );
                        self.attack_start(lathoric, player);
                    }
                    break;
                }
            }
        }
        // Combat timers (fork head, searing_gorge.cpp:163-164).
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let smash_due = {
            let Some(s) = self.obsidion_state_mut(guid) else {
                return;
            };
            if s.ground_smash_ms < diff_ms {
                true
            } else {
                s.ground_smash_ms -= diff_ms;
                false
            }
        };
        if smash_due
            && self.do_cast_spell_if_can(guid, OBS_SPELL_GROUND_SMASH, CastTarget::Unit(victim))
            && let Some(s) = self.obsidion_state_mut(guid)
        {
            s.ground_smash_ms = 8000;
        }
        let knock_due = {
            let Some(s) = self.obsidion_state_mut(guid) else {
                return;
            };
            if s.knock_away_ms < diff_ms {
                true
            } else {
                s.knock_away_ms -= diff_ms;
                false
            }
        };
        if knock_due
            && self.do_cast_spell_if_can(guid, OBS_SPELL_KNOCK_AWAY, CastTarget::Unit(victim))
            && let Some(s) = self.obsidion_state_mut(guid)
        {
            s.knock_away_ms = 12_000;
        }
    }

