    /// `boss_sylvanasAI::UpdateAI` (`undercity.cpp:64-135`).
    /// Fork `<=` timer semantics transcribed exactly.
    #[allow(clippy::too_many_lines)]
    fn sylvanas_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let faded = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Sylvanas(s)) => Some(s.faded_ms),
                _ => None,
            })
            .unwrap_or(0);
        if faded != 0 {
            if faded > diff_ms {
                if let Some(s) = self.sylvanas_state_mut(guid) {
                    s.faded_ms -= diff_ms;
                }
                return;
            }
            if let Some(s) = self.sylvanas_state_mut(guid) {
                s.faded_ms = 0;
            }
            // Fork `GetMotionMaster()->Clear()` (undercity.cpp:74).
            self.stop_moving(guid);
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let skel_due = {
            let Some(s) = self.sylvanas_state_mut(guid) else {
                return;
            };
            if s.summ_skel_ms <= diff_ms {
                true
            } else {
                s.summ_skel_ms -= diff_ms;
                false
            }
        };
        if skel_due
            && self.do_cast_spell_if_can(guid, SYLV_SPELL_SUMMON_SKEL, CastTarget::SelfCast)
            && let Some(s) = self.sylvanas_state_mut(guid)
        {
            s.summ_skel_ms = 25_000;
        }
        let fade_due = {
            let Some(s) = self.sylvanas_state_mut(guid) else {
                return;
            };
            if s.fade_ms <= diff_ms {
                true
            } else {
                s.fade_ms -= diff_ms;
                false
            }
        };
        if fade_due && self.do_cast_spell_if_can(guid, SYLV_SPELL_FADE, CastTarget::SelfCast) {
            // NEEDS-MAP-HELPER: `MoveFollow(victim, 30.0f, angle)`
            // (undercity.cpp:92).
            if let Some(s) = self.sylvanas_state_mut(guid) {
                s.fade_ms = 50_000;
                s.black_arrow_ms = 0;
                s.multi_shot_ms = 0;
                s.shoot_ms = 0;
                s.faded_ms = 5000;
            }
        }
        let arrow_due = {
            let Some(s) = self.sylvanas_state_mut(guid) else {
                return;
            };
            if s.black_arrow_ms <= diff_ms {
                true
            } else {
                s.black_arrow_ms -= diff_ms;
                false
            }
        };
        if arrow_due {
            let target = self.select_attacking_target(guid, 0, 0, SYLV_SELECT_FLAG_NO_TOTEM);
            if let Some(target) = target
                && self.do_cast_spell_if_can(guid, SYLV_SPELL_BLACK_ARROW, CastTarget::Unit(target))
                && let Some(s) = self.sylvanas_state_mut(guid)
            {
                s.black_arrow_ms = 15_000;
            }
        }
        let multi_due = {
            let Some(s) = self.sylvanas_state_mut(guid) else {
                return;
            };
            if s.multi_shot_ms <= diff_ms {
                true
            } else {
                s.multi_shot_ms -= diff_ms;
                false
            }
        };
        if multi_due {
            let target = self.select_attacking_target(guid, 0, 0, SYLV_SELECT_FLAG_NO_TOTEM);
            if let Some(target) = target
                && self.do_cast_spell_if_can(guid, SYLV_SPELL_MULTI_SHOT, CastTarget::Unit(target))
                && let Some(s) = self.sylvanas_state_mut(guid)
            {
                s.multi_shot_ms = 10_000;
            }
        }
        let shoot_due = {
            let Some(s) = self.sylvanas_state_mut(guid) else {
                return;
            };
            if s.shoot_ms <= diff_ms {
                true
            } else {
                s.shoot_ms -= diff_ms;
                false
            }
        };
        if shoot_due
            && self.do_cast_spell_if_can(guid, SYLV_SPELL_SHOOT, CastTarget::Unit(victim))
            && let Some(s) = self.sylvanas_state_mut(guid)
        {
            s.shoot_ms = 10_000;
        }
        // Fork `EnterEvadeIfOutOfCombatArea(uiDiff)` (undercity.cpp:134);
        // the shared leash check runs again here.
        if self.should_leash_evade(guid) {
            self.enter_evade_mode(guid);
        }
    }

