    /// `npc_slims_friendAI::UpdateCombatAI` (`wetlands.cpp:97-120`).
    fn slims_friend_update_combat(&mut self, guid: ObjectGuid, victim: ObjectGuid, diff_ms: u32) {
        let poison_due = {
            let Some(s) = self.slims_friend_state_mut(guid) else {
                return;
            };
            if s.slowing_poison_ms < diff_ms {
                true
            } else {
                s.slowing_poison_ms -= diff_ms;
                false
            }
        };
        // Fork `CF_AURA_NOT_PRESENT` flag (wetlands.cpp:102).
        let roll_2 = self.rng.urand(8400, 15_300);
        if poison_due
            && !self.bot_has_aura(victim, SLIMS_SPELL_SLOWING_POISON)
            && self.do_cast_spell_if_can(guid, SLIMS_SPELL_SLOWING_POISON, CastTarget::Unit(victim))
            && let Some(s) = self.slims_friend_state_mut(guid)
        {
            s.slowing_poison_ms = roll_2;
        }
        let backstab_due = {
            let Some(s) = self.slims_friend_state_mut(guid) else {
                return;
            };
            if s.backstab_ms < diff_ms {
                true
            } else {
                s.backstab_ms -= diff_ms;
                false
            }
        };
        let roll_1 = self.rng.urand(2100, 5600);
        if backstab_due
            && self.do_cast_spell_if_can(guid, SLIMS_SPELL_BACKSTAB, CastTarget::Unit(victim))
            && let Some(s) = self.slims_friend_state_mut(guid)
        {
            s.backstab_ms = roll_1;
        }
    }

