    /// `boss_kurinnaxxAI::UpdateAI` (cpp 92-162).
    fn kurinnaxx_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Stale-trap sweep runs before the hostile head (cpp 94-104;
        // fork `<` and the timer is left armed).
        let clean_due = self.kurinnaxx_state_mut(guid).is_some_and(|s| {
            if s.clean_trap_ms < diff_ms {
                true
            } else {
                s.clean_trap_ms = s.clean_trap_ms.saturating_sub(diff_ms);
                false
            }
        });
        if clean_due {
            // NEEDS-MAP-HELPER: closest `GO_TRAP` (180647) within
            // `DEFAULT_VISIBILITY_DISTANCE` + `SendObjectDeSpawnAnim` +
            // `Delete` (cpp 97-101); no gameobject-removal helper on `Map`.
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Enrage at 30% (cpp 109-117).
        let enraged = self.kurinnaxx_state_mut(guid).is_none_or(|s| s.enraged);
        if !enraged
            && self.creature_health_percent(guid) <= 30.0
            && self.do_cast_spell_if_can(guid, KURINNAXX_SPELL_ENRAGE, CastTarget::SelfCast)
        {
            self.do_script_text(KURINNAXX_EMOTE_FRENZY, guid, None, -1);
            if let Some(s) = self.kurinnaxx_state_mut(guid) {
                s.enraged = true;
            }
        }
        // Mortal Wound (cpp 119-126; fork `<`).
        let due = self.kurinnaxx_state_mut(guid).is_some_and(|s| {
            if s.mortal_ms < diff_ms {
                true
            } else {
                s.mortal_ms = s.mortal_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due
            && self.do_cast_spell_if_can(
                guid,
                KURINNAXX_SPELL_MORTALWOUND,
                CastTarget::Unit(victim),
            )
        {
            if let Some(s) = self.kurinnaxx_state_mut(guid) {
                s.mortal_ms = 9000;
            }
        }
        // Sand trap on a random target (cpp 128-141; fork `<`).
        let due = self.kurinnaxx_state_mut(guid).is_some_and(|s| {
            if s.sandtrap_ms < diff_ms {
                true
            } else {
                s.sandtrap_ms = s.sandtrap_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due {
            if let Some(_target) = self.select_random_hostile(guid) {
                // NEEDS-MAP-HELPER: `SummonGameObject(GO_TRAP, target.x,
                // target.y, target.z, ...)` + `SetOwnerGuid(me)` (cpp 134-135);
                // the retrap timers below assume the summon succeeded.
                let next = self.rng.urand(5100, 7000);
                if let Some(s) = self.kurinnaxx_state_mut(guid) {
                    s.sandtrap_ms = next;
                    s.clean_trap_ms = 5000;
                }
            }
        }
        // Wide Slash (cpp 143-150; fork `<` + `10000 + rand() % 10000`).
        let due = self.kurinnaxx_state_mut(guid).is_some_and(|s| {
            if s.wideslash_ms < diff_ms {
                true
            } else {
                s.wideslash_ms = s.wideslash_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due
            && self.do_cast_spell_if_can(guid, KURINNAXX_SPELL_WIDE_SLASH, CastTarget::Unit(victim))
        {
            let next = 10_000 + self.rng.urand(0, 9_999);
            if let Some(s) = self.kurinnaxx_state_mut(guid) {
                s.wideslash_ms = next;
            }
        }
        // Trash (cpp 152-159; fork `<` + `10000 + rand() % 10000`).
        let due = self.kurinnaxx_state_mut(guid).is_some_and(|s| {
            if s.trash_ms < diff_ms {
                true
            } else {
                s.trash_ms = s.trash_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due && self.do_cast_spell_if_can(guid, KURINNAXX_SPELL_TRASH, CastTarget::Unit(victim)) {
            let next = 10_000 + self.rng.urand(0, 9_999);
            if let Some(s) = self.kurinnaxx_state_mut(guid) {
                s.trash_ms = next;
            }
        }
    }

