    /// `boss_moamAI::JustSummoned` (`boss_moam.cpp` 100-122).
    fn moam_just_summoned(&mut self, guid: ObjectGuid, created: ObjectGuid) {
        if let Some(target) = self.select_attacking_target(guid, 1, 0, 0) {
            if self.unit_is_alive(target) {
                self.attack_start(created, target);
                let entry = self.creatures.get(&created).map_or(0, |c| c.info.entry);
                if entry == MOAM_NPC_MANA_FIEND {
                    // Teleportation-spell visual (cpp 110).
                    self.send_spell_go_simple(created, MOAM_SPELL_SUMMON_MANA_FIEND, created, 0);
                    return;
                }
            }
        }
        if self.get_hostile_target(guid).is_none() || self.unit_victim(guid).is_none() {
            self.despawn_creature_now(created, 0);
            return;
        }
        self.despawn_creature_now(created, 0);
    }

    /// `boss_moamAI::UpdateAI` (`boss_moam.cpp` 124-203). Mana reads/writes
    /// go through the unit power fields (no power helper on `Map`).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn moam_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Fork head (cpp 126): targetless ticks pass only in stone form.
        let victim = if self.unit_has_aura(guid, MOAM_SPELL_ENERGIZE) {
            self.unit_victim(guid)
        } else {
            let Some(v) = self.script_combat_drive(guid, true) else {
                return;
            };
            Some(v)
        };
        let Some(victim) = victim else {
            return;
        };
        // Stone-form expiry (cpp 130-148).
        if self.unit_has_aura(guid, MOAM_SPELL_ENERGIZE) {
            if let Some(s) = self.moam_state_mut(guid) {
                s.turn_back_ms = s.turn_back_ms.saturating_sub(diff_ms);
            }
            let mana = self.unit_value_u32(guid, offsets::UNIT_FIELD_POWER1);
            let mana_max = self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXPOWER1);
            let expired = self
                .moam_state_mut(guid)
                .is_some_and(|s| s.turn_back_ms == 0);
            if mana >= mana_max || expired {
                let memorized = self
                    .moam_state_mut(guid)
                    .map_or(ObjectGuid::EMPTY, |s| s.victim_guid);
                if !memorized.is_empty() && self.unit_is_alive(memorized) {
                    self.attack_start(guid, memorized);
                } else if let Some(random) = self.select_random_hostile(guid) {
                    self.attack_start(guid, random);
                }
                self.remove_auras_due_to_spell(guid, MOAM_SPELL_ENERGIZE);
                // `DoCast(victim, ARCANEERUPTION, true)` (cpp 144).
                let _ = self.cast_spell(
                    guid,
                    MOAM_SPELL_ARCANEERUPTION,
                    CastTarget::Unit(victim),
                    CastOptions {
                        triggered: true,
                        skip_known: true,
                        ..Default::default()
                    },
                );
                self.do_script_text(MOAM_EMOTE_MANA_FULL, guid, None, -1);
                // NEEDS-MAP-HELPER: `SetArmor` restore of the fork default
                // armor (cpp 69 / 146); no armor reader/writer on `Map`.
            }
        }
        if self.unit_has_aura(guid, MOAM_SPELL_ENERGIZE) {
            return;
        }
        // Eruption at full mana outside stone form (cpp 154-158).
        let mana = self.unit_value_u32(guid, offsets::UNIT_FIELD_POWER1);
        let mana_max = self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXPOWER1);
        if mana == mana_max {
            // `DoCast(victim, ARCANEERUPTION)` (cpp 156).
            let _ = self.cast_spell(
                guid,
                MOAM_SPELL_ARCANEERUPTION,
                CastTarget::Unit(victim),
                CastOptions {
                    triggered: false,
                    skip_known: true,
                    ..Default::default()
                },
            );
            self.do_script_text(MOAM_EMOTE_MANA_FULL, guid, None, -1);
        }
        // Energize + fiend wave (cpp 160-182; fork `<`).
        let due = self.moam_state_mut(guid).is_some_and(|s| {
            if s.summon_fiend_ms < diff_ms {
                true
            } else {
                s.summon_fiend_ms = s.summon_fiend_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due && self.do_cast_spell_if_can(guid, MOAM_SPELL_ENERGIZE, CastTarget::SelfCast) {
            // NEEDS-MAP-HELPER: `SetArmor(18000)` (cpp 166); no armor writer.
            let me = self.unit_position(guid).unwrap_or_default();
            for _ in 0..3 {
                self.summon_creature(
                    MOAM_NPC_MANA_FIEND,
                    Position::new(me.x + 2.0, me.y, me.z, me.o),
                    guid,
                    MOAM_TEMPSUMMON_TIMED_OOC_DESPAWN,
                    10_000,
                );
            }
            let hoist87 = self.unit_victim(guid).unwrap_or(ObjectGuid::EMPTY);
            if let Some(s) = self.moam_state_mut(guid) {
                s.summon_fiend_ms = 90_000;
                s.turn_back_ms = 90_000;
                s.victim_guid = hoist87;
            }
            self.attack_stop(guid);
            self.do_script_text(MOAM_EMOTE_DRAIN, guid, None, -1);
        }
        // Trample (cpp 184-191; fork `<`).
        let due = self.moam_state_mut(guid).is_some_and(|s| {
            if s.trample_ms < diff_ms {
                true
            } else {
                s.trample_ms = s.trample_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due && self.do_cast_spell_if_can(guid, MOAM_SPELL_TRAMPLE, CastTarget::Unit(victim)) {
            if let Some(s) = self.moam_state_mut(guid) {
                s.trample_ms = 15_000;
            }
        }
        // Drain Mana (cpp 193-200; fork `<`).
        let due = self.moam_state_mut(guid).is_some_and(|s| {
            if s.drain_ms < diff_ms {
                true
            } else {
                s.drain_ms = s.drain_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due {
            // `DoCast(self, DRAINMANA)` (cpp 196).
            let _ = self.cast_spell(
                guid,
                MOAM_SPELL_DRAINMANA,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: false,
                    skip_known: true,
                    ..Default::default()
                },
            );
            if let Some(s) = self.moam_state_mut(guid) {
                s.drain_ms = 7000;
            }
        }
    }

    fn ossirian_state_mut(&mut self, guid: ObjectGuid) -> Option<&mut OssirianAi> {
        match &mut self.ai.get_mut(&guid)?.script {
            Some(CreatureScriptAi::Ossirian(s)) => Some(s),
            _ => None,
        }
    }

    /// `boss_ossirianAI::Reset` (`boss_ossirian.cpp` 91-129).
    fn ossirian_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.ossirian_state_mut(guid) {
            s.aggro_done = false;
            s.curse_ms = 30_000;
            s.strength_ms = 25_000;
            s.stomp_ms = 25_000;
            s.winds_ms = 20_000;
            s.speed_ms = 10_000;
            s.tmp_threat.clear();
            s.tmp_threat_val.clear();
            s.enraged = true;
        }
        // `DoCast(self, STRENGTH_OF_OSSIRIAN)` (cpp 95): direct,
        // non-triggered.
        let _ = self.cast_spell(
            guid,
            OSSIRIAN_SPELL_STRENGTH,
            CastTarget::SelfCast,
            CastOptions {
                triggered: false,
                skip_known: true,
                ..Default::default()
            },
        );
        self.set_speed_rate(guid, mangos_entities::unit::MOVE_RUN, 1.0);
        self.set_speed_rate(guid, mangos_entities::unit::MOVE_WALK, 1.0);
        // Tornado sweep (cpp 111-121).
        let tornados: Vec<ObjectGuid> = self
            .ossirian_state_mut(guid)
            .map(|s| s.tornado_guids.clone())
            .unwrap_or_default();
        if let Some(s) = self.ossirian_state_mut(guid) {
            s.tornado_guids.clear();
        }
        for t in tornados {
            if self.creatures.contains_key(&t) {
                self.despawn_creature_now(t, 0);
            }
        }
        // NEEDS-MAP-HELPER: `SetWeather(zone, WEATHER_TYPE_FINE, 0, false)`
        // (cpp 126); no weather setter on `Map`.
        self.instance_set_data(AQ20_TYPE_OSSIRIAN, AQ20_FAIL);
    }

    /// `boss_ossirianAI::SpellHitTarget` (cpp 131-139).
    fn ossirian_spell_hit_target(&mut self, guid: ObjectGuid, target: ObjectGuid, spell_id: u32) {
        if spell_id != OSSIRIAN_SPELL_ENVELOPING_WINDS {
            return;
        }
        let threat = self.threat_on(guid, target);
        if let Some(s) = self.ossirian_state_mut(guid) {
            s.tmp_threat_val.push(threat);
            s.tmp_threat.push(target);
        }
        self.modify_threat_percent_of(guid, target, -100);
    }

    /// `boss_ossirianAI::SpellHit` (cpp 141-158).
    fn ossirian_spell_hit(&mut self, guid: ObjectGuid, caster: ObjectGuid, spell_id: u32) {
        let _ = caster;
        for weakness in OSSIRIAN_SPELL_WEAKNESS {
            if spell_id != weakness {
                continue;
            }
            if let Some(s) = self.ossirian_state_mut(guid) {
                s.strength_ms = 45_000;
            }
            let enraged = self.ossirian_state_mut(guid).is_some_and(|s| s.enraged);
            if enraged || self.unit_has_aura(guid, OSSIRIAN_SPELL_STRENGTH) {
                self.remove_auras_due_to_spell(guid, OSSIRIAN_SPELL_STRENGTH);
                if let Some(s) = self.ossirian_state_mut(guid) {
                    s.enraged = false;
                }
            }
            break;
        }
    }

    /// `boss_ossirianAI::Aggro` (cpp 160-188).
    fn ossirian_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        self.do_script_text(OSSIRIAN_SAY_AGGRO, guid, None, -1);
        self.set_in_combat_with_zone(guid);
        // `DoCast(self, STRENGTH_OF_OSSIRIAN)` (cpp 164).
        let _ = self.cast_spell(
            guid,
            OSSIRIAN_SPELL_STRENGTH,
            CastTarget::SelfCast,
            CastOptions {
                triggered: false,
                skip_known: true,
                ..Default::default()
            },
        );
        for spawn in OSSIRIAN_TORNADO_SPAWN {
            if let Some(tornado) = self.summon_creature(
                OSSIRIAN_NPC_TORNADO,
                Position::new(spawn[0], spawn[1], spawn[2], 0.0),
                guid,
                OSSIRIAN_TEMPSUMMON_MANUAL_DESPAWN,
                0,
            ) {
                // `CastSpell(self, SANDSTORM, true)` (cpp 170).
                let _ = self.cast_spell(
                    tornado,
                    OSSIRIAN_SPELL_SANDSTORM,
                    CastTarget::SelfCast,
                    CastOptions {
                        triggered: true,
                        skip_known: true,
                        ..Default::default()
                    },
                );
                let flags = self.object_get_field(tornado, offsets::UNIT_FIELD_FLAGS);
                self.object_set_field(
                    tornado,
                    u32::from(offsets::UNIT_FIELD_FLAGS),
                    flags | OSSIRIAN_UNIT_FLAG_NOT_SELECTABLE,
                );
                if let Some(v) = self.unit_victim(guid) {
                    self.attack_start(tornado, v);
                }
                if let Some(s) = self.ossirian_state_mut(guid) {
                    s.tornado_guids.push(tornado);
                }
            }
        }
        let first = self.ossirian_state_mut(guid).is_none_or(|s| s.aggro_done);
        if !first {
            if let Some(s) = self.ossirian_state_mut(guid) {
                s.aggro_done = true;
                s.speed_ms = 10_000;
            }
            // NEEDS-MAP-HELPER: `SpawnNewCrystals(ObjectGuid())` instance
            // script (cpp 181); no crystal surface on `Map`.
        }
        // NEEDS-MAP-HELPER: `SetWeather(zone, WEATHER_TYPE_STORM, 1, false)`
        // (cpp 185); no weather setter on `Map`.
        self.instance_set_data(AQ20_TYPE_OSSIRIAN, IN_PROGRESS);
    }

    /// `boss_ossirianAI::JustDied` (cpp 190-205).
    fn ossirian_just_died(&mut self, guid: ObjectGuid) {
        self.do_script_text(OSSIRIAN_SAY_DEATH, guid, None, -1);
        let tornados: Vec<ObjectGuid> = self
            .ossirian_state_mut(guid)
            .map(|s| s.tornado_guids.clone())
            .unwrap_or_default();
        if let Some(s) = self.ossirian_state_mut(guid) {
            s.tornado_guids.clear();
        }
        for t in tornados {
            if self.creatures.contains_key(&t) {
                self.despawn_creature_now(t, 0);
            }
        }
        self.instance_set_data(AQ20_TYPE_OSSIRIAN, DONE);
    }

    /// `boss_ossirianAI::KilledUnit` (cpp 207-211).
    fn ossirian_killed_unit(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        if victim.is_player() {
            self.do_script_text(OSSIRIAN_SAY_SLAY, guid, None, -1);
        }
    }

    /// `boss_ossirianAI::UpdateAI` (cpp 213-278).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    #[allow(clippy::cast_precision_loss)]
    fn ossirian_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Curse of Tongues (cpp 218-224; fork `<` + `10000 + rand()%10000`).
        let due = self.ossirian_state_mut(guid).is_some_and(|s| {
            if s.curse_ms < diff_ms {
                true
            } else {
                s.curse_ms = s.curse_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due
            && self.do_cast_spell_if_can(
                guid,
                OSSIRIAN_SPELL_CURSE_OF_TONGUES,
                CastTarget::Unit(victim),
            )
        {
            let next = 10_000 + self.rng.urand(0, 9_999);
            if let Some(s) = self.ossirian_state_mut(guid) {
                s.curse_ms = next;
            }
        }
        // Run-speed ramp (cpp 226-230; fork `>=` with no else arm: once the
        // timer drops below `diff` it freezes with the last rate).
        let rate = self.ossirian_state_mut(guid).and_then(|s| {
            if s.speed_ms >= diff_ms {
                s.speed_ms -= diff_ms;
                Some(2.0 - (s.speed_ms as f32) / 10_000.0)
            } else {
                None
            }
        });
        if let Some(rate) = rate {
            self.set_speed_rate(guid, mangos_entities::unit::MOVE_RUN, rate);
        }
        // Strength of Ossirian re-cast (cpp 232-240; fork `<` with the
        // decrement in the else arm, so the timer also ticks while enraged).
        let strength_due = self
            .ossirian_state_mut(guid)
            .is_some_and(|s| !s.enraged && s.strength_ms < diff_ms);
        if strength_due {
            if self.do_cast_spell_if_can(guid, OSSIRIAN_SPELL_STRENGTH, CastTarget::SelfCast) {
                if let Some(s) = self.ossirian_state_mut(guid) {
                    s.enraged = true;
                }
            }
        } else if let Some(s) = self.ossirian_state_mut(guid) {
            // Fork decrements whenever the cast arm is skipped, enraged or
            // not (cpp 239).
            s.strength_ms = s.strength_ms.saturating_sub(diff_ms);
        }
        // War Stomp (cpp 242-248; fork `<` + `25000 + rand()%10000`).
        let due = self.ossirian_state_mut(guid).is_some_and(|s| {
            if s.stomp_ms < diff_ms {
                true
            } else {
                s.stomp_ms = s.stomp_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due && self.do_cast_spell_if_can(guid, OSSIRIAN_SPELL_WAR_STOMP, CastTarget::SelfCast) {
            let next = 25_000 + self.rng.urand(0, 9_999);
            if let Some(s) = self.ossirian_state_mut(guid) {
                s.stomp_ms = next;
            }
        }
        // Enveloping Winds (cpp 250-256; fork `<`).
        let due = self.ossirian_state_mut(guid).is_some_and(|s| {
            if s.winds_ms < diff_ms {
                true
            } else {
                s.winds_ms = s.winds_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due
            && self.do_cast_spell_if_can(
                guid,
                OSSIRIAN_SPELL_ENVELOPING_WINDS,
                CastTarget::Unit(victim),
            )
        {
            if let Some(s) = self.ossirian_state_mut(guid) {
                s.winds_ms = 15_000;
            }
        }
        // Parked-threat restore (cpp 258-275).
        let pending: Vec<(ObjectGuid, f32)> = self
            .ossirian_state_mut(guid)
            .map(|s| {
                s.tmp_threat
                    .clone()
                    .into_iter()
                    .zip(s.tmp_threat_val.clone())
                    .collect()
            })
            .unwrap_or_default();
        if let Some(s) = self.ossirian_state_mut(guid) {
            s.tmp_threat.clear();
            s.tmp_threat_val.clear();
        }
        for (unit, value) in pending {
            if !self.unit_is_alive(unit) {
                continue;
            }
            if self.unit_has_aura(unit, OSSIRIAN_SPELL_ENVELOPING_WINDS) {
                // Fork `continue` keeps aura'd entries parked (cpp 268).
                if let Some(s) = self.ossirian_state_mut(guid) {
                    s.tmp_threat.push(unit);
                    s.tmp_threat_val.push(value);
                }
                continue;
            }
            self.add_threat(guid, unit, value);
        }
    }

