    /// `npc_sandstalkerAI::UpdateAI` (cpp 34-51; no hostile head: the
    /// out-of-combat vanish upkeep runs targetless).
    fn sandstalker_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if !self.ai_in_combat(guid) {
            // NEEDS-MAP-HELPER: `EnterVanish` (cpp 38); no stealth helper.
        }
        let due = self.sandstalker_state_mut(guid).is_some_and(|s| {
            if s.burrow_ms < diff_ms {
                true
            } else {
                s.burrow_ms = s.burrow_ms.saturating_sub(diff_ms);
                false
            }
        });
        if !due {
            return;
        }
        // NEEDS-MAP-HELPER: `EnterVanish` (cpp 41); no stealth helper.
        let vanish_target = self.select_random_hostile(guid);
        // NEEDS-MAP-HELPER: `LeaveVanish` + `Ambush(target, SPELL_BURROW)`
        // (cpp 42-44); no stealth/ambush helpers on `Map`.
        let _ = vanish_target;
        let next = self.rng.urand(5000, 10_000);
        if let Some(s) = self.sandstalker_state_mut(guid) {
            s.burrow_ms = next;
        }
    }

