    /// `mob_anubisath_guardianAI::Reset` (`ruins_of_ahnqiraj.cpp` 74-91;
    /// the `urand` option rolls live here, herod pattern).
    fn anubisath_guardian_reset(&mut self, guid: ObjectGuid) {
        let roll1 = self.rng.urand(0, 1);
        let roll2 = self.rng.urand(0, 1);
        let roll3 = self.rng.urand(0, 1);
        let roll4 = self.rng.urand(0, 1);
        let roll5 = self.rng.urand(0, 1);
        if let Some(s) = self.anubisath_guardian_state_mut(guid) {
            s.spell1_id = if roll1 == 0 {
                ANUBISATH_SPELL_METEOR
            } else {
                ANUBISATH_SPELL_PLAGUE
            };
            s.spell2_id = if roll2 == 0 {
                ANUBISATH_SPELL_SHADOW_STORM
            } else {
                ANUBISATH_SPELL_THUNDER_CLAP
            };
            s.spell3_id = if roll3 == 0 {
                ANUBISATH_SPELL_REFLECT_ARFR
            } else {
                ANUBISATH_SPELL_REFLECT_FSSH
            };
            s.spell4_id = if roll4 == 0 {
                ANUBISATH_SPELL_ENRAGE
            } else {
                ANUBISATH_SPELL_INIT_EXPLODE
            };
            s.summon_entry = if roll5 == 0 {
                ANUBISATH_NPC_WARRIOR
            } else {
                ANUBISATH_NPC_SWARM
            };
            s.spell1_ms = 10_000;
            s.spell2_ms = 20_000;
            s.summon_ms = 10_000;
            s.enraged = false;
            s.exploding = false;
            s.summon_count = 0;
            s.explode_ms = 6000;
        }
        self.remove_all_auras(guid);
    }

