    /// `mob_anubisath_guardianAI::DamageTaken` (cpp 109-126).
    fn anubisath_guardian_damage_taken(
        &mut self,
        guid: ObjectGuid,
        _attacker: ObjectGuid,
        damage: &mut u32,
    ) {
        let _ = damage;
        let enraged = self
            .anubisath_guardian_state_mut(guid)
            .is_none_or(|s| s.enraged);
        if enraged || self.creature_health_percent(guid) >= 10.0 {
            return;
        }
        let spell4 = self
            .anubisath_guardian_state_mut(guid)
            .map_or(0, |s| s.spell4_id);
        if spell4 == ANUBISATH_SPELL_ENRAGE {
            // `DoCast(victim, ENRAGE)` (cpp 115).
            if let Some(victim) = self.unit_victim(guid) {
                let _ = self.cast_spell(
                    guid,
                    spell4,
                    CastTarget::Unit(victim),
                    CastOptions {
                        triggered: false,
                        skip_known: true,
                        ..Default::default()
                    },
                );
            }
            self.do_script_text(ANUBISATH_EMOTE_FRENZY, guid, None, -1);
            if let Some(s) = self.anubisath_guardian_state_mut(guid) {
                s.enraged = true;
            }
        } else {
            // `CastSpell(self, INIT_EXPLODE, false)` (cpp 121).
            let _ = self.cast_spell(
                guid,
                spell4,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: false,
                    skip_known: true,
                    ..Default::default()
                },
            );
            if let Some(s) = self.anubisath_guardian_state_mut(guid) {
                s.exploding = true;
                s.explode_ms = 6000;
            }
        }
    }

    /// `mob_anubisath_guardianAI::UpdateAI` (cpp 128-180).
    fn anubisath_guardian_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Explode upkeep (cpp 133-139; fork decrements the timer even while
        // not exploding, and the `<` arm requires the flag too).
        let (exploding, explode_due) = self
            .anubisath_guardian_state_mut(guid)
            .map_or((false, false), |s| (s.exploding, s.explode_ms < diff_ms));
        if explode_due && exploding {
            if self.do_cast_spell_if_can(guid, ANUBISATH_SPELL_EXPLODE, CastTarget::SelfCast) {
                if let Some(s) = self.anubisath_guardian_state_mut(guid) {
                    s.explode_ms = 15_000;
                }
            }
        } else if let Some(s) = self.anubisath_guardian_state_mut(guid) {
            s.explode_ms = s.explode_ms.saturating_sub(diff_ms);
        }
        // Random-target spell1 with send-spell-go visual (cpp 142-156).
        let spell1 = self
            .anubisath_guardian_state_mut(guid)
            .map_or(0, |s| s.spell1_id);
        let spell1_due = self.anubisath_guardian_state_mut(guid).is_some_and(|s| {
            if s.spell1_ms < diff_ms {
                true
            } else {
                s.spell1_ms = s.spell1_ms.saturating_sub(diff_ms);
                false
            }
        });
        if spell1_due {
            if let Some(unit) = self.select_random_hostile(guid) {
                // Creature-to-visual `SendSpellGo` (cpp 148).
                self.send_spell_go_simple(guid, spell1, guid, 0);
                if self.do_cast_spell_if_can(guid, spell1, CastTarget::Unit(unit)) {
                    if let Some(s) = self.anubisath_guardian_state_mut(guid) {
                        s.spell1_ms = 15_000;
                    }
                }
            }
        }
        // Spell2 on the victim (cpp 158-164; fork `<`).
        let spell2 = self
            .anubisath_guardian_state_mut(guid)
            .map_or(0, |s| s.spell2_id);
        let spell2_due = self.anubisath_guardian_state_mut(guid).is_some_and(|s| {
            if s.spell2_ms < diff_ms {
                true
            } else {
                s.spell2_ms = s.spell2_ms.saturating_sub(diff_ms);
                false
            }
        });
        if spell2_due && self.do_cast_spell_if_can(guid, spell2, CastTarget::Unit(victim)) {
            if let Some(s) = self.anubisath_guardian_state_mut(guid) {
                s.spell2_ms = 15_000;
            }
        }
        // Summon upkeep, at most 4 live (cpp 166-177; fork `<`, reset
        // unconditionally after the check).
        let summon_entry = self
            .anubisath_guardian_state_mut(guid)
            .map_or(0, |s| s.summon_entry);
        let (summon_count, summon_due) =
            self.anubisath_guardian_state_mut(guid)
                .map_or((4, false), |s| {
                    (
                        s.summon_count,
                        if s.summon_ms < diff_ms {
                            true
                        } else {
                            s.summon_ms = s.summon_ms.saturating_sub(diff_ms);
                            false
                        },
                    )
                });
        if summon_due {
            if summon_count < 4 {
                let me = self.unit_position(guid).unwrap_or_default();
                self.summon_creature(
                    summon_entry,
                    Position::new(me.x, me.y, me.z, me.o),
                    guid,
                    ANUBISATH_TEMPSUMMON_TIMED_DESPAWN,
                    60_000,
                );
                // Teleportation-spell visual (cpp 172).
                self.send_spell_go_simple(guid, ANUBISATH_SPELL_SUMMON_VISUAL, guid, 0);
            }
            if let Some(s) = self.anubisath_guardian_state_mut(guid) {
                s.summon_ms = 15_000;
            }
        }
    }

    /// `OssirianTornadoAI::Reset` (`ruins_of_ahnqiraj.cpp` 183-196; the ctor
    /// aura/wander setup runs here too since reset re-fires on evade).
    fn ossirian_tornado_reset(&mut self, guid: ObjectGuid) {
        if let Some(ai) = self.ai.get_mut(&guid) {
            ai.combat_movement = false;
        }
        // `CastSpell(self, 25160, false)` + `CastSpell(self, 10092, false)`
        // (cpp 188-189): direct, non-triggered.
        for spell in [TORNADO_SPELL_SANDSTORM, TORNADO_SPELL_AURA] {
            let _ = self.cast_spell(
                guid,
                spell,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: false,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
        // NEEDS-MAP-HELPER: `SetDefaultMovementType(RANDOM)` +
        // `SetWanderDistance(55.0)` + motion `Initialize` (cpp 190-192); no
        // wander setup on `Map`.
    }

