    /// `mob_flesh_hunterAI::UpdateAI` (cpp 272-352).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn flesh_hunter_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Poison Bolt on a random target (cpp 277-287; fork `<`).
        let due = self.flesh_hunter_state_mut(guid).is_some_and(|s| {
            if s.poison_ms < diff_ms {
                true
            } else {
                s.poison_ms = s.poison_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due {
            if let Some(target) = self.select_random_hostile(guid) {
                if self.do_cast_spell_if_can(
                    guid,
                    FLESH_HUNTER_SPELL_POISON_BOLT,
                    CastTarget::Unit(target),
                ) {
                    if let Some(s) = self.flesh_hunter_state_mut(guid) {
                        s.poison_ms = 3000;
                    }
                }
            }
        }
        // Consume the top-aggro target (cpp 288-301; fork `<`).
        let due = self.flesh_hunter_state_mut(guid).is_some_and(|s| {
            if s.consume_ms < diff_ms {
                true
            } else {
                s.consume_ms = s.consume_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due {
            if let Some(target) = self.select_attacking_target(guid, 1, 0, 0) {
                if self.do_cast_spell_if_can(
                    guid,
                    FLESH_HUNTER_SPELL_CONSUME,
                    CastTarget::Unit(target),
                ) {
                    if let Some(s) = self.flesh_hunter_state_mut(guid) {
                        s.consume_victim = target;
                        s.consume_ms = 30_000;
                    }
                }
            }
        }
        // Consume-victim drain (cpp 303-341).
        let (consume_victim, charged) = self
            .flesh_hunter_state_mut(guid)
            .map_or((ObjectGuid::EMPTY, false), |s| {
                (s.consume_victim, s.consumed_charged)
            });
        if !consume_victim.is_empty() {
            if self.unit_has_aura(consume_victim, FLESH_HUNTER_SPELL_CONSUME) {
                let due = self.flesh_hunter_state_mut(guid).is_some_and(|s| {
                    if s.consume_dmg_ms < diff_ms {
                        true
                    } else {
                        s.consume_dmg_ms = s.consume_dmg_ms.saturating_sub(diff_ms);
                        false
                    }
                });
                if due
                    && self.do_cast_spell_if_can(
                        guid,
                        FLESH_HUNTER_SPELL_CONSUME_DMG,
                        CastTarget::Unit(consume_victim),
                    )
                {
                    self.stop_moving(guid);
                    // NEEDS-MAP-HELPER: `GetMotionMaster()->Initialize()`
                    // (cpp 312); `StopMoving` above is the interim.
                    self.modify_threat_percent_of(guid, consume_victim, -100);
                    if let Some(s) = self.flesh_hunter_state_mut(guid) {
                        s.consume_dmg_ms = 1000;
                        s.consumed_charged = true;
                    }
                    // `SetHealth(GetHealth - GetMaxHealth / 10)` (cpp 317).
                    let cur = self.unit_value_u32(consume_victim, offsets::UNIT_FIELD_HEALTH);
                    let max = self.unit_value_u32(consume_victim, offsets::UNIT_FIELD_MAXHEALTH);
                    let less = cur.saturating_sub(max / 10);
                    let _ = self.object_set_field(
                        consume_victim,
                        u32::from(offsets::UNIT_FIELD_HEALTH),
                        less,
                    );
                }
                if !self.unit_is_alive(consume_victim) {
                    if let Some(target) = self.select_random_hostile(guid) {
                        self.creature_move_chase(guid, target, 0.0, 0.0);
                    }
                    // `SetHealth(GetMaxHealth())` (cpp 327).
                    let maxh = self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXHEALTH);
                    let _ =
                        self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_HEALTH), maxh);
                }
            } else if self.unit_is_alive(consume_victim)
                && charged
                && self.do_cast_spell_if_can(
                    guid,
                    FLESH_HUNTER_SPELL_SPLIT,
                    CastTarget::Unit(consume_victim),
                )
            {
                if let Some(s) = self.flesh_hunter_state_mut(guid) {
                    s.consumed_charged = false;
                }
                if let Some(v) = self.unit_victim(guid) {
                    self.creature_move_chase(guid, v, 0.0, 0.0);
                }
            }
        }
        // Trash (cpp 343-349; fork `<` + `5000 + rand() % 2000`).
        let due = self.flesh_hunter_state_mut(guid).is_some_and(|s| {
            if s.trash_ms < diff_ms {
                true
            } else {
                s.trash_ms = s.trash_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due
            && self.do_cast_spell_if_can(guid, FLESH_HUNTER_SPELL_TRASH, CastTarget::Unit(victim))
        {
            let next = 5000 + self.rng.urand(0, 1999);
            if let Some(s) = self.flesh_hunter_state_mut(guid) {
                s.trash_ms = next;
            }
        }
    }

