    /// `ObsidianDestroyerAI::JustDied` (cpp 387-391).
    #[allow(clippy::unused_self)]
    fn obsidian_destroyer_just_died(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: `SummonGameObject(181068, x, y, z, ...)` +
        // `SetRespawnTime(AQ20_RESPAWN_FOUR_DAYS)` (cpp 389-390); no
        // gameobject-summon helper on `Map`.
        let _ = guid;
    }

    /// `ObsidianDestroyerAI::UpdateAI` (cpp 393-411).
    fn obsidian_destroyer_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let in_combat = self
            .obsidian_destroyer_state_mut(guid)
            .is_some_and(|s| s.in_combat);
        let mana = self.unit_value_u32(guid, offsets::UNIT_FIELD_POWER1);
        let mana_max = self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXPOWER1);
        if mana >= mana_max && in_combat {
            // `DoCast(self, PURGE, true)` (cpp 399).
            let _ = self.cast_spell(
                guid,
                OBSIDIAN_SPELL_PURGE,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
        let due = self.obsidian_destroyer_state_mut(guid).is_some_and(|s| {
            if s.drain_ms < diff_ms {
                true
            } else {
                s.drain_ms = s.drain_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due {
            // `DoCast(self, DRAINMANA)` (cpp 405).
            let _ = self.cast_spell(
                guid,
                OBSIDIAN_SPELL_DRAINMANA,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: false,
                    skip_known: true,
                    ..Default::default()
                },
            );
            if let Some(s) = self.obsidian_destroyer_state_mut(guid) {
                s.drain_ms = 7000;
            }
        }
    }

