    /// `HiveZaraSoldierAI::UpdateAI` (cpp 436-463).
    fn hive_zara_soldier_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Venom Spit on a random target (cpp 441-448; fork `<`).
        let due = self.hive_zara_soldier_state_mut(guid).is_some_and(|s| {
            if s.venom_ms < diff_ms {
                true
            } else {
                s.venom_ms = s.venom_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due {
            if let Some(target) = self.select_random_hostile(guid) {
                if self.do_cast_spell_if_can(
                    guid,
                    SOLDIER_SPELL_VENOM_SPIT,
                    CastTarget::Unit(target),
                ) {
                    let next = self.rng.urand(5000, 10_000);
                    if let Some(s) = self.hive_zara_soldier_state_mut(guid) {
                        s.venom_ms = next;
                    }
                }
            }
        }
        // Retaliation below 20% (cpp 450-460; the fork repeats the block
        // verbatim, transcribed once).
        let retaliated = self
            .hive_zara_soldier_state_mut(guid)
            .is_none_or(|s| s.retaliation);
        if !retaliated && self.creature_health_percent(guid) < 20.0 {
            // `CastSpell(self, RETALIATION, false)` (cpp 453): direct,
            // non-triggered.
            let _ = self.cast_spell(
                guid,
                SOLDIER_SPELL_RETALIATION,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: false,
                    skip_known: true,
                    ..Default::default()
                },
            );
            if let Some(s) = self.hive_zara_soldier_state_mut(guid) {
                s.retaliation = true;
            }
        }
    }

