    /// `QirajiGladiatorAI::UpdateAI` (cpp 583-611).
    fn qiraji_gladiator_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // A fallen gladiator enrages its mate (cpp 588-592).
        let enraged = self
            .qiraji_gladiator_state_mut(guid)
            .is_none_or(|s| s.enraged);
        if self
            .instance_get_data(AQ20_TYPE_QIRAJI_GLADIATOR)
            .unwrap_or(0)
            > 0
            && !enraged
            && self.do_cast_spell_if_can(guid, GLADIATOR_SPELL_VENGEANCE, CastTarget::SelfCast)
        {
            if let Some(s) = self.qiraji_gladiator_state_mut(guid) {
                s.enraged = true;
            }
        }
        // Trample (cpp 594-600; fork `<`).
        let due = self.qiraji_gladiator_state_mut(guid).is_some_and(|s| {
            if s.trample_ms < diff_ms {
                true
            } else {
                s.trample_ms = s.trample_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due && self.do_cast_spell_if_can(guid, GLADIATOR_SPELL_TRAMPLE, CastTarget::Unit(victim))
        {
            let next = self.rng.urand(4000, 6000);
            if let Some(s) = self.qiraji_gladiator_state_mut(guid) {
                s.trample_ms = next;
            }
        }
        // Uppercut (cpp 602-608; fork `<`).
        let due = self.qiraji_gladiator_state_mut(guid).is_some_and(|s| {
            if s.uppercut_ms < diff_ms {
                true
            } else {
                s.uppercut_ms = s.uppercut_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due
            && self.do_cast_spell_if_can(guid, GLADIATOR_SPELL_UPPERCUT, CastTarget::Unit(victim))
        {
            let next = self.rng.urand(10_000, 15_000);
            if let Some(s) = self.qiraji_gladiator_state_mut(guid) {
                s.uppercut_ms = next;
            }
        }
    }

