    /// `HiveZaraStingerAI::Reset` (`ruins_of_ahnqiraj.cpp` 628-633).
    fn hive_zara_stinger_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.hive_zara_stinger_state_mut(guid) {
            s.charge_ms = 3000;
            s.charged_ms = 0;
            s.charged = false;
        }
        let _ = guid;
    }

    /// `HiveZaraStingerAI::UpdateAI` (cpp 635-666; no aggro hook).
    fn hive_zara_stinger_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Charge, then a delayed chase re-sync (cpp 640-662; fork `<` and
        // the post-decrement compare below are transcribed exactly).
        let due = self
            .hive_zara_stinger_state_mut(guid)
            .is_some_and(|s| s.charge_ms < diff_ms);
        if due {
            if let Some(target) = self.select_random_hostile(guid) {
                if self.do_cast_spell_if_can(guid, STINGER_SPELL_CHARGE, CastTarget::Unit(target)) {
                    if let Some(s) = self.hive_zara_stinger_state_mut(guid) {
                        s.charge_ms = 5000;
                        s.charged = true;
                        s.charged_ms = 500;
                    }
                }
            }
        } else {
            if let Some(s) = self.hive_zara_stinger_state_mut(guid) {
                s.charge_ms = s.charge_ms.saturating_sub(diff_ms);
            }
            let charged = self
                .hive_zara_stinger_state_mut(guid)
                .is_some_and(|s| s.charged);
            if charged {
                if let Some(s) = self.hive_zara_stinger_state_mut(guid) {
                    s.charged_ms = s.charged_ms.saturating_sub(diff_ms);
                }
                let expired = self
                    .hive_zara_stinger_state_mut(guid)
                    .is_some_and(|s| s.charged_ms < diff_ms);
                if expired {
                    if let Some(s) = self.hive_zara_stinger_state_mut(guid) {
                        s.charged = false;
                    }
                    self.creature_move_chase(guid, victim, 0.0, 0.0);
                }
            }
        }
    }

