    /// `TuubidAI::UpdateAI` (cpp 695-744).
    fn tuubid_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Attack Order mark (cpp 700-724; fork `<`).
        let due = self.tuubid_state_mut(guid).is_some_and(|s| {
            if s.order_ms < diff_ms {
                true
            } else {
                s.order_ms = s.order_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due {
            if let Some(target) = self.select_random_hostile(guid) {
                let old = self
                    .tuubid_state_mut(guid)
                    .map_or(ObjectGuid::EMPTY, |s| s.marked_guid);
                if !old.is_empty() {
                    self.remove_auras_due_to_spell(old, TUUBID_SPELL_ATTACK_ORDER);
                }
                if target.is_player() {
                    // NEEDS-MAP-HELPER: `GetCharmerOrOwnerPlayerOrPlayerItself`
                    // (cpp 707); the target itself is the interim mark.
                    let _ = self.do_cast_spell_if_can(
                        guid,
                        TUUBID_SPELL_ATTACK_ORDER,
                        CastTarget::Unit(target),
                    );
                    if let Some(s) = self.tuubid_state_mut(guid) {
                        s.marked_guid = target;
                    }
                    self.do_script_text(TUUBID_SAY_KILL, guid, Some(target), -1);
                } else if let Some(s) = self.tuubid_state_mut(guid) {
                    s.marked_guid = ObjectGuid::EMPTY;
                }
            }
            if let Some(s) = self.tuubid_state_mut(guid) {
                s.order_ms = 9000;
            }
        }
        // Cleave (cpp 726-732; fork `<`).
        let due = self.tuubid_state_mut(guid).is_some_and(|s| {
            if s.cleave_ms < diff_ms {
                true
            } else {
                s.cleave_ms = s.cleave_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due && self.do_cast_spell_if_can(guid, TUUBID_SPELL_CLEAVE, CastTarget::Unit(victim)) {
            if let Some(s) = self.tuubid_state_mut(guid) {
                s.cleave_ms = 10_000;
            }
        }
        // Sunder Armor, self-cast (cpp 734-740; fork `<`).
        let due = self.tuubid_state_mut(guid).is_some_and(|s| {
            if s.sunder_ms < diff_ms {
                true
            } else {
                s.sunder_ms = s.sunder_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due && self.do_cast_spell_if_can(guid, TUUBID_SPELL_SUNDER_ARMOR, CastTarget::SelfCast) {
            if let Some(s) = self.tuubid_state_mut(guid) {
                s.sunder_ms = 15_000;
            }
        }
    }

