    /// `QirajiWarriorAI::DamageTaken` (cpp 790-797).
    fn qiraji_warrior_damage_taken(
        &mut self,
        guid: ObjectGuid,
        _attacker: ObjectGuid,
        damage: &mut u32,
    ) {
        let _ = damage;
        let enraged = self
            .qiraji_warrior_state_mut(guid)
            .is_none_or(|s| s.enraged);
        // Fork also gates on `!IsNonMeleeSpellCasted(false)` (cpp 792); the
        // reduced active-cast check is `bot_casting_spell`.
        if !enraged
            && self.creature_health_percent(guid) <= 20.0
            && self.bot_casting_spell(guid).is_none()
        {
            // `DoCast(victim, ENRAGE)` (cpp 794).
            if let Some(victim) = self.unit_victim(guid) {
                let _ = self.cast_spell(
                    guid,
                    WARRIOR_SPELL_ENRAGE,
                    CastTarget::Unit(victim),
                    CastOptions {
                        triggered: false,
                        skip_known: true,
                        ..Default::default()
                    },
                );
            }
            if let Some(s) = self.qiraji_warrior_state_mut(guid) {
                s.enraged = true;
            }
        }
    }

    /// `QirajiWarriorAI::UpdateAI` (cpp 799-851).
    fn qiraji_warrior_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // NEEDS-MAP-HELPER: `GetCreatureGroup` original-leader-entry gate
        // (cpp 802-809); interim keeps the mandated drive head.
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Mark-system target sync (cpp 813-828; `GetTuubidAI` cpp 766-776).
        let target_due = self.qiraji_warrior_state_mut(guid).is_some_and(|s| {
            if s.update_target_ms < diff_ms {
                true
            } else {
                s.update_target_ms = s.update_target_ms.saturating_sub(diff_ms);
                false
            }
        });
        if target_due {
            let cached = self
                .qiraji_warrior_state_mut(guid)
                .map_or(ObjectGuid::EMPTY, |s| s.tuubid_guid);
            let tuubid = if cached.is_empty() {
                let me = self.unit_position(guid).unwrap_or_default();
                let found: Vec<ObjectGuid> = self
                    .creatures
                    .iter()
                    .filter(|(_, c)| c.info.entry == AQ20_NPC_CAPTAIN_TUUBID)
                    .filter_map(|(g, _)| self.object_position(*g).map(|p| (*g, p)))
                    .filter(|(g, p)| {
                        let dx = p.x - me.x;
                        let dy = p.y - me.y;
                        dx * dx + dy * dy <= 100.0 * 100.0 && self.unit_is_alive(*g)
                    })
                    .map(|(g, _)| g)
                    .collect();
                let found = found.into_iter().next().unwrap_or(ObjectGuid::EMPTY);
                if let Some(s) = self.qiraji_warrior_state_mut(guid) {
                    s.tuubid_guid = found;
                }
                found
            } else {
                cached
            };
            if !tuubid.is_empty() && self.unit_is_alive(tuubid) {
                let marked = self
                    .tuubid_state_mut(tuubid)
                    .map_or(ObjectGuid::EMPTY, |s| s.marked_guid);
                if !marked.is_empty() && self.unit_is_alive(marked) {
                    self.attack_start(guid, marked);
                }
            }
            // Fork records Tuubid-down in `m_bisTuubidAlive` here; the flag
            // is dropped (never read outside the untranscribed group gate).
            if let Some(s) = self.qiraji_warrior_state_mut(guid) {
                s.update_target_ms = 1400;
            }
        }
        // Thunderclap (cpp 831-840; fork `<`; the fork compares the
        // creature's distance to itself, always < 5.0, so the check is
        // transcribed unconditionally).
        let due = self.qiraji_warrior_state_mut(guid).is_some_and(|s| {
            if s.thunder_ms < diff_ms {
                true
            } else {
                s.thunder_ms = s.thunder_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due
            && self.do_cast_spell_if_can(guid, WARRIOR_SPELL_THUNDERCLAP, CastTarget::Unit(victim))
        {
            if let Some(s) = self.qiraji_warrior_state_mut(guid) {
                s.thunder_ms = 6000;
            }
        }
        // Uppercut (cpp 842-848; fork `<`).
        let due = self.qiraji_warrior_state_mut(guid).is_some_and(|s| {
            if s.uppercut_ms < diff_ms {
                true
            } else {
                s.uppercut_ms = s.uppercut_ms.saturating_sub(diff_ms);
                false
            }
        });
        if due && self.do_cast_spell_if_can(guid, WARRIOR_SPELL_UPPERCUT, CastTarget::Unit(victim))
        {
            if let Some(s) = self.qiraji_warrior_state_mut(guid) {
                s.uppercut_ms = 10_000;
            }
        }
    }

