    /// `boss_huhuranAI::MoveInLineOfSight` (80yd pull + base).
    fn huhuran_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        // NEEDS-MAP-HELPER: feign-death aura check
        // (`SPELL_AURA_FEIGN_DEATH`); proximity pull itself:
        let in_combat = self.ai_in_combat(guid);
        let dist_ok = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy <= 80.0 * 80.0
            }
            _ => false,
        };
        if self.players.contains_key(&who) && !in_combat && dist_ok {
            self.attack_start(guid, who);
        }
    }

    /// `boss_huhuranAI::UpdateAI` (cpp 99-161).
    #[allow(clippy::too_many_lines)]
    fn huhuran_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Frenzy (fork `<` + `!HasAura(SPELL_FRENZY)` gate).
        let has_frenzy = self.bot_has_aura(guid, HUHURAN_SPELL_FRENZY);
        let frenzy_due = {
            let Some(s) = self.huhuran_state_mut(guid) else {
                return;
            };
            if s.frenzy_timer_ms < diff_ms && !has_frenzy {
                true
            } else {
                s.frenzy_timer_ms = s.frenzy_timer_ms.saturating_sub(diff_ms);
                false
            }
        };
        if frenzy_due && self.do_cast_spell_if_can(guid, HUHURAN_SPELL_FRENZY, CastTarget::SelfCast)
        {
            self.do_script_text(HUHURAN_EMOTE_GENERIC_FRENZY_KILL, guid, None, -1);
            let next = self.rng.urand(25_000, 35_000);
            if let Some(s) = self.huhuran_state_mut(guid) {
                s.frenzy_timer_ms = next;
            }
        }
        // Wyvern Sting (suppressed while berserk).
        let berserk = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Huhuran(s)) if s.berserk),
        );
        if !berserk {
            let due = {
                let Some(s) = self.huhuran_state_mut(guid) else {
                    return;
                };
                if s.wyvern_timer_ms < diff_ms {
                    true
                } else {
                    s.wyvern_timer_ms -= diff_ms;
                    false
                }
            };
            let hoist86 = self.rng.urand(15_000, 32_000);
            if due
                && self.do_cast_spell_if_can(
                    guid,
                    HUHURAN_SPELL_WYVERNSTING,
                    CastTarget::Unit(victim),
                )
                && let Some(s) = self.huhuran_state_mut(guid)
            {
                s.wyvern_timer_ms = hoist86;
            }
        }
        // Acid Spit.
        let due = {
            let Some(s) = self.huhuran_state_mut(guid) else {
                return;
            };
            if s.spit_timer_ms < diff_ms {
                true
            } else {
                s.spit_timer_ms -= diff_ms;
                false
            }
        };
        let hoist85 = self.rng.urand(5000, 10_000);
        if due
            && self.do_cast_spell_if_can(guid, HUHURAN_SPELL_ACIDSPIT, CastTarget::Unit(victim))
            && let Some(s) = self.huhuran_state_mut(guid)
        {
            s.spit_timer_ms = hoist85;
        }
        // Noxious Poison (random target).
        let due = {
            let Some(s) = self.huhuran_state_mut(guid) else {
                return;
            };
            if s.noxious_poison_timer_ms < diff_ms {
                true
            } else {
                s.noxious_poison_timer_ms -= diff_ms;
                false
            }
        };
        let hoist84 = self.rng.urand(12_000, 24_000);
        if due
            && let Some(target) = self.select_random_hostile(guid)
            && self.do_cast_spell_if_can(
                guid,
                HUHURAN_SPELL_NOXIOUSPOISON,
                CastTarget::Unit(target),
            )
            && let Some(s) = self.huhuran_state_mut(guid)
        {
            s.noxious_poison_timer_ms = hoist84;
        }
        // Berserk (`CF_AURA_NOT_PRESENT` folds into the IfCan cast).
        let berserk = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Huhuran(s)) if s.berserk),
        );
        if berserk {
            self.do_cast_spell_if_can(guid, HUHURAN_SPELL_BERSERK, CastTarget::SelfCast);
        } else if self.creature_health_percent(guid) < 31.0 {
            self.do_script_text(HUHURAN_EMOTE_GENERIC_BERSERK, guid, None, -1);
            if let Some(s) = self.huhuran_state_mut(guid) {
                s.berserk = true;
            }
        } else {
            let expired = {
                let Some(s) = self.huhuran_state_mut(guid) else {
                    return;
                };
                if s.berserk_timer_ms < diff_ms {
                    true
                } else {
                    s.berserk_timer_ms -= diff_ms;
                    false
                }
            };
            if expired {
                self.do_script_text(HUHURAN_EMOTE_GENERIC_BERSERK, guid, None, -1);
                if let Some(s) = self.huhuran_state_mut(guid) {
                    s.berserk = true;
                }
            }
        }
    }

    fn skeram_state_mut(&mut self, guid: ObjectGuid) -> Option<&mut SkeramAi> {
        self.ai.get_mut(&guid).and_then(|ai| match &mut ai.script {
            Some(CreatureScriptAi::Skeram(s)) => Some(s),
            _ => None,
        })
    }

    /// `boss_skeramAI::Reset` (cpp 87-109).
    fn skeram_reset(&mut self, guid: ObjectGuid) {
        let arcane = self.rng.urand(6000, 8000);
        let fulfill = self.rng.urand(10_000, 15_000);
        let blink = self.rng.urand(15_000, 20_000);
        if let Some(s) = self.skeram_state_mut(guid) {
            s.arcane_explosion_timer_ms = arcane;
            s.earth_shock_timer_ms = 2000;
            s.fulfillment_timer_ms = fulfill;
            s.blink_timer_ms = blink;
            s.next_split_percent = 75.0;
            // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_ON)`.
            s.image_a = ObjectGuid::EMPTY;
            // Fork clears `ImageA` twice and never `ImageB` (cpp 98-99);
            // transcribed as-is.
            s.controlled_player = ObjectGuid::EMPTY;
            // NEEDS-MAP-HELPER: `SetMeleeZReach(74.0f)`.
        }
    }

    /// `boss_skeramAI::CancelFulfillment` (cpp 111-120).
    fn skeram_cancel_fulfillment(&mut self, guid: ObjectGuid) {
        let target = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Skeram(s)) => Some(s.controlled_player),
                _ => None,
            })
            .unwrap_or(ObjectGuid::EMPTY);
        if target.is_empty() {
            return;
        }
        self.remove_auras_due_to_spell(target, SKERAM_SPELL_TRUE_FULFILLMENT);
        self.remove_auras_due_to_spell(target, SKERAM_SPELL_TF_HASTE);
        self.remove_auras_due_to_spell(target, SKERAM_SPELL_TF_MOD_HEAL);
        self.remove_auras_due_to_spell(target, SKERAM_SPELL_TF_IMMUNITY);
    }

    /// `boss_skeramAI::MoveInLineOfSight` (28yd player pull + base, cpp 122-130).
    fn skeram_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        // NEEDS-MAP-HELPER: feign-death aura check
        // (`SPELL_AURA_FEIGN_DEATH`); proximity pull itself:
        let in_combat = self.ai_in_combat(guid);
        let dist_ok = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy <= 28.0 * 28.0
            }
            _ => false,
        };
        if self.players.contains_key(&who) && !in_combat && dist_ok {
            self.attack_start(guid, who);
        }
    }

    /// `boss_skeramAI::KilledUnit` (cpp 132-146).
    fn skeram_killed_unit(&mut self, guid: ObjectGuid, _victim: ObjectGuid) {
        match self.rng.urand(0, 8) {
            0 => self.do_script_text(SKERAM_SAY_SLAY_1, guid, None, -1),
            1 => self.do_script_text(SKERAM_SAY_SLAY_2, guid, None, -1),
            2 => self.do_script_text(SKERAM_SAY_SLAY_3, guid, None, -1),
            _ => {}
        }
    }

    /// `boss_skeramAI::JustDied` (cpp 148-165).
    fn skeram_just_died(&mut self, guid: ObjectGuid) {
        let is_image = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Skeram(s)) if s.is_image),
        );
        if is_image {
            self.skeram_cancel_fulfillment(guid);
            self.despawn_creature_now(guid, 0);
            return;
        }
        self.do_script_text(SKERAM_SAY_DEATH, guid, None, -1);
        // NEEDS-MAP-HELPER: `SetRespawnDelay(7 * DAY)` +
        // `BindToInstanceOrRaid` on the killer's owner (cpp 158-161).
        self.aq40_set_data(AQ40_TYPE_SKERAM, DONE);
    }

    /// `boss_skeramAI::Aggro` (cpp 167-187).
    fn skeram_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        let is_image = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Skeram(s)) if s.is_image),
        );
        if is_image {
            return;
        }
        if self.aq40_encounter(AQ40_TYPE_SKERAM as usize) == IN_PROGRESS {
            return;
        }
        match self.spell_rng().irand(0, 2) {
            0 => self.do_script_text(SKERAM_SAY_AGGRO_1, guid, None, -1),
            1 => self.do_script_text(SKERAM_SAY_AGGRO_2, guid, None, -1),
            _ => self.do_script_text(SKERAM_SAY_AGGRO_3, guid, None, -1),
        }
        self.aq40_set_data(AQ40_TYPE_SKERAM, IN_PROGRESS);
        // NEEDS-MAP-HELPER: `GetPlayersCountExceptGMs` + 1.12-patch branch
        // (cpp 180-186); pre-1.12 default:
        if let Some(s) = self.skeram_state_mut(guid) {
            s.max_melee_allowed = 4;
        }
    }

    /// `boss_skeramAI::JustReachedHome` (cpp 189-198).
    fn skeram_just_reached_home(&mut self, guid: ObjectGuid) {
        self.skeram_cancel_fulfillment(guid);
        let is_image = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Skeram(s)) if s.is_image),
        );
        if is_image {
            self.kill_unit(guid, None);
        }
        self.aq40_set_data(AQ40_TYPE_SKERAM, AQ40_FAIL);
    }

    /// `boss_skeramAI::UpdateAI` (cpp 200-282).
    #[allow(clippy::too_many_lines)]
    fn skeram_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Images despawn instantly once the true prophet died (cpp 203-204).
        let is_image = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Skeram(s)) if s.is_image),
        );
        if is_image && self.aq40_encounter(AQ40_TYPE_SKERAM as usize) == DONE {
            self.kill_unit(guid, None);
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Arcane Explosion, gated on melee-range player count (fork `<`).
        let arcane_due = {
            let Some(s) = self.skeram_state_mut(guid) else {
                return;
            };
            if s.arcane_explosion_timer_ms < diff_ms {
                true
            } else {
                s.arcane_explosion_timer_ms -= diff_ms;
                false
            }
        };
        if arcane_due {
            // `GetPlayersWithinRange(GetMeleeReach())` (cpp 214):
            // threat members within melee reach via the motion helper.
            let max = self
                .skeram_state_mut(guid)
                .map_or(0, |s| s.max_melee_allowed);
            let mut in_reach = 0u32;
            let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
            for p in players {
                if self.unit_is_alive(p) && self.can_reach_melee(guid, p) {
                    in_reach += 1;
                }
            }
            if in_reach > max {
                let hoist83 = self.rng.urand(6000, 14_000);
                if self.do_cast_spell_if_can(
                    guid,
                    SKERAM_SPELL_ARCANE_EXPLOSION,
                    CastTarget::Unit(victim),
                ) && let Some(s) = self.skeram_state_mut(guid)
                {
                    s.arcane_explosion_timer_ms = hoist83;
                }
            } else if let Some(s) = self.skeram_state_mut(guid) {
                s.arcane_explosion_timer_ms = 1000;
            }
        }
        // Earth Shock when the victim is out of melee range
        // (`DoMeleeAttackIfReady` ticks globally; dropped).
        if !self.can_reach_melee(guid, victim) {
            let due = {
                let Some(s) = self.skeram_state_mut(guid) else {
                    return;
                };
                if s.earth_shock_timer_ms < diff_ms {
                    true
                } else {
                    s.earth_shock_timer_ms -= diff_ms;
                    false
                }
            };
            if due
                && self.do_cast_spell_if_can(
                    guid,
                    SKERAM_SPELL_EARTH_SHOCK,
                    CastTarget::Unit(victim),
                )
                && let Some(s) = self.skeram_state_mut(guid)
            {
                s.earth_shock_timer_ms = 2000;
            }
        }
        // True Fulfillment on the nearest hostile player (40yd).
        let due = {
            let Some(s) = self.skeram_state_mut(guid) else {
                return;
            };
            if s.fulfillment_timer_ms < diff_ms {
                true
            } else {
                s.fulfillment_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: `FindNearestHostilePlayer(40.0f)`; nearest
            // live player within 40yd:
            let me = self.unit_position(guid).unwrap_or_default();
            let mut best: Option<(ObjectGuid, f32)> = None;
            let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
            for p in players {
                if !self.unit_is_alive(p) {
                    continue;
                }
                if let Some(pp) = self.unit_position(p) {
                    let dx = pp.x - me.x;
                    let dy = pp.y - me.y;
                    let d = dx * dx + dy * dy;
                    if d <= 40.0 * 40.0 && best.is_none_or(|(_, bd)| d < bd) {
                        best = Some((p, d));
                    }
                }
            }
            // `CF_AURA_NOT_PRESENT` folds into the IfCan cast.
            if let Some((target, _)) = best
                && self.do_cast_spell_if_can(
                    guid,
                    SKERAM_SPELL_TRUE_FULFILLMENT,
                    CastTarget::Unit(target),
                )
            {
                self.skeram_cancel_fulfillment(guid);
                self.aq_triggered_cast(guid, SKERAM_SPELL_TF_HASTE, CastTarget::Unit(target));
                self.aq_triggered_cast(guid, SKERAM_SPELL_TF_MOD_HEAL, CastTarget::Unit(target));
                self.aq_triggered_cast(guid, SKERAM_SPELL_TF_IMMUNITY, CastTarget::Unit(target));
                let next = self.rng.urand(20_500, 25_000);
                if let Some(s) = self.skeram_state_mut(guid) {
                    s.fulfillment_timer_ms = next;
                    s.controlled_player = target;
                }
            }
        }
        // Blink.
        let due = {
            let Some(s) = self.skeram_state_mut(guid) else {
                return;
            };
            if s.blink_timer_ms < diff_ms {
                true
            } else {
                s.blink_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            self.skeram_cast_blink(guid, guid, 0x7);
            let next = self.rng.urand(10_000, 18_000);
            if let Some(s) = self.skeram_state_mut(guid) {
                s.blink_timer_ms = next;
            }
        }
        // Split: summon images every 25% HP (fork `HealthPercent < NextSplit`).
        let split_at = self
            .skeram_state_mut(guid)
            .map_or(100.0, |s| s.next_split_percent);
        let mut say_split = false;
        if !is_image
            && self.creature_health_percent(guid) < split_at
            && self.do_cast_spell_if_can(guid, SKERAM_SPELL_SUMMON_IMAGES, CastTarget::SelfCast)
            && let Some(s) = self.skeram_state_mut(guid)
        {
            if s.next_split_percent < 26.0 {
                say_split = true;
            }
            s.next_split_percent -= 25.0;
        }
        if say_split {
            self.do_script_text(SKERAM_SAY_SPLIT, guid, None, -1);
        }
    }

    /// `boss_skeramAI::JustSummoned` (cpp 284-316).
    fn skeram_just_summoned(&mut self, guid: ObjectGuid, created: ObjectGuid) {
        let same_entry = self.creatures.get(&guid).map(|c| c.info.entry)
            == self.creatures.get(&created).map(|c| c.info.entry);
        if !same_entry {
            return;
        }
        if let Some(ai) = self.ai.get_mut(&created) {
            if let Some(CreatureScriptAi::Skeram(s)) = &mut ai.script {
                s.is_image = true;
            }
        }
        let health_pct = self.creature_health_percent(guid);
        let max_pct = if health_pct < 25.0 {
            0.50
        } else if health_pct < 50.0 {
            0.20
        } else {
            0.10
        };
        let _ = max_pct;
        // NEEDS-MAP-HELPER: `SetMaxHealth(GetMaxHealth() * pct)` +
        // `SetHealthPercent` on the image (cpp 304-305).
        self.set_in_combat_with_zone(created);
        // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_OFF)` on the image.
        let full = self.ai.get(&guid).and_then(|ai| match &ai.script {
            Some(CreatureScriptAi::Skeram(s)) => Some((s.image_a, s.image_b)),
            _ => None,
        });
        if let Some((a, b)) = full {
            if a.is_empty() {
                if let Some(s) = self.skeram_state_mut(guid) {
                    s.image_a = created;
                }
            } else {
                let _ = b;
                if let Some(s) = self.skeram_state_mut(guid) {
                    s.image_b = created;
                }
                self.skeram_unison_blink(guid);
            }
        }
    }

    /// `boss_skeramAI::UnisonBlink` (cpp 318-340).
    fn skeram_unison_blink(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: `RemoveAllAuras` (mapped below), `ClearTargetIcon`,
        // `ClearComboPointHolders`, `InterruptSpellsCastedOnMe`,
        // `RemoveAllAttackers`, `SetVisibility(VISIBILITY_OFF)` (cpp 327-332).
        self.remove_all_auras(guid);
        // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_OFF)` on self.
        let (a, b) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Skeram(s)) => Some((s.image_a, s.image_b)),
                _ => None,
            })
            .unwrap_or((ObjectGuid::EMPTY, ObjectGuid::EMPTY));
        self.skeram_cast_blink(a, a, 0x7);
        self.skeram_cast_blink(b, b, 0x7);
        self.skeram_cast_blink(guid, guid, 0x7);
        if let Some(s) = self.skeram_state_mut(guid) {
            s.image_a = ObjectGuid::EMPTY;
            s.image_b = ObjectGuid::EMPTY;
        }
    }

    /// `boss_skeramAI::CastBlink(Creature*)` (cpp 342-347).
    fn skeram_cast_blink(&mut self, guid: ObjectGuid, caster: ObjectGuid, mut mask: u32) {
        let mut pos = self.rng.urand(0, 2);
        while mask & (1 << pos) == 0 {
            pos = self.rng.urand(0, 2);
        }
        mask &= !(1 << pos);
        let _ = mask;
        self.attack_stop(caster);
        match pos {
            0 => {
                self.aq_triggered_cast(caster, SKERAM_SPELL_BLINK_0, CastTarget::SelfCast);
            }
            1 => {
                self.aq_triggered_cast(caster, SKERAM_SPELL_BLINK_1, CastTarget::SelfCast);
            }
            _ => {
                self.aq_triggered_cast(caster, SKERAM_SPELL_BLINK_2, CastTarget::SelfCast);
            }
        }
        // NEEDS-MAP-HELPER: `DoResetThreat` on the caster (cpp 376).
        if let Some(ai) = self.ai.get_mut(&caster) {
            if let Some(CreatureScriptAi::Skeram(s)) = &mut ai.script {
                s.earth_shock_timer_ms = 2000;
            }
        }
        // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_ON)` on the caster.
        let _ = guid;
    }

