    /// `creature_spawn_fankrissAI::UpdateAI` (cpp 90-111).
    fn spawn_fankriss_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let due = {
            let Some(s) = self.spawn_fankriss_state_mut(guid) else {
                return;
            };
            if s.enrage_timer_ms < diff_ms {
                true
            } else {
                s.enrage_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // Fork gates on `sWorld.GetWowPatch() >= WOW_PATCH_110`
            // (cpp 101): 1.12 assumed.
            self.aq_triggered_cast(guid, FANKRISS_SPELL_SPAWN_ENRAGE, CastTarget::SelfCast);
            if let Some(s) = self.spawn_fankriss_state_mut(guid) {
                s.enrage_timer_ms = u32::MAX;
            }
        }
    }

