    /// `creature_vekniss_hatchlingAI::MoveInLineOfSight` gate (cpp 148-152).
    fn vekniss_hatchling_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        let engaged = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::VeknissHatchling(s)) if s.has_engaged),
        );
        if engaged {
            // Fork base `ScriptedAI::MoveInLineOfSight` (standard proximity
            // aggro); `creature_script_has_move_in_line_of_sight` is false
            // for this variant so the drive skips its own MLO pass.
            self.try_proximity_aggro(guid);
            let _ = who;
        }
    }
    // NO-DISPATCHER-YET: `creature_vekniss_hatchlingAI::EnterCombat` gate
    // (cpp 144-147) and `Aggro` gate (cpp 153-157, base no-op) — no
    // `enter_combat`/`aggro`-gate dispatch shape for the engaged check.

    /// `creature_vekniss_hatchlingAI::UpdateAI` (cpp 159-190; fork `<=`).
    fn vekniss_hatchling_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let engaged = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::VeknissHatchling(s)) if s.has_engaged),
        );
        if !engaged {
            let timer = self
                .vekniss_hatchling_state_mut(guid)
                .map_or(0, |s| s.engage_timer_ms);
            if timer <= diff_ms {
                if let Some(s) = self.vekniss_hatchling_state_mut(guid) {
                    s.has_engaged = true;
                }
                self.set_in_combat_with_zone(guid);
                let was_attacked = self.ai.get(&guid).is_some_and(|ai| {
                    matches!(&ai.script, Some(CreatureScriptAi::VeknissHatchling(s)) if s.was_attacked)
                });
                if !was_attacked {
                    // `SelectAttackingTarget(NEAREST, 0)` (cpp 167).
                    if let Some(target) = self.select_attacking_target(guid, 3, 0, 0) {
                        // Fork bails when the target is >200yd out (cpp 169).
                        let far = match (self.unit_position(guid), self.unit_position(target)) {
                            (Some(a), Some(b)) => {
                                let dx = a.x - b.x;
                                let dy = a.y - b.y;
                                dx * dx + dy * dy > 200.0 * 200.0
                            }
                            _ => true,
                        };
                        if far {
                            return;
                        }
                        self.add_threat(guid, target, 1.0);
                        self.attack_start(guid, target);
                    }
                }
            } else {
                if let Some(s) = self.vekniss_hatchling_state_mut(guid) {
                    s.engage_timer_ms -= diff_ms;
                }
                return;
            }
        }
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
    }

    fn fankriss_state_mut(&mut self, guid: ObjectGuid) -> Option<&mut FankrissAi> {
        self.ai.get_mut(&guid).and_then(|ai| match &mut ai.script {
            Some(CreatureScriptAi::Fankriss(s)) => Some(s),
            _ => None,
        })
    }

    /// Fisher-Yates shuffle of a 3-slot order triple via the map RNG.
    fn fankriss_shuffle3(&mut self, a: &mut u8, b: &mut u8, c: &mut u8) {
        let mut slots = [*a, *b, *c];
        for i in (1..3).rev() {
            let j = self.rng.urand(0, i as u32) as usize;
            slots.swap(i, j);
        }
        *a = slots[0];
        *b = slots[1];
        *c = slots[2];
    }

    /// `boss_fankrissAI::ReinitializeWebTimers` (cpp 313-325).
    fn fankriss_reinitialize_web_timers(&mut self, guid: ObjectGuid, add_ms: u32) {
        let (o0, o1, o2) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Fankriss(s)) => {
                    Some((s.entangle_order_0, s.entangle_order_1, s.entangle_order_2))
                }
                _ => None,
            })
            .unwrap_or((0, 1, 2));
        let (mut a, mut b, mut c) = (o0, o1, o2);
        self.fankriss_shuffle3(&mut a, &mut b, &mut c);
        let t0 = self.rng.urand(2000 + add_ms, 18_000 + add_ms);
        let t1 = self.rng.urand(15_000 + add_ms, 28_000 + add_ms);
        let t2 = self.rng.urand(25_000 + add_ms, 45_000 + add_ms);
        if let Some(s) = self.fankriss_state_mut(guid) {
            s.entangle_order_0 = a;
            s.entangle_order_1 = b;
            s.entangle_order_2 = c;
            s.entangle_timer_0_ms = t0;
            s.entangle_timer_1_ms = t1;
            s.entangle_timer_2_ms = t2;
            s.entangle_cast_0 = false;
            s.entangle_cast_1 = false;
            s.entangle_cast_2 = false;
            s.entangle_rotation_timer_ms = 45_000 + add_ms;
        }
    }

    /// `boss_fankrissAI::Reset` (cpp 234-255).
    fn fankriss_reset(&mut self, guid: ObjectGuid) {
        let mortal = self.rng.urand(4000, 8000);
        let worm0 = self.rng.urand(20_000, 30_000);
        if let Some(s) = self.fankriss_state_mut(guid) {
            s.mortal_wound_timer_ms = mortal;
            s.worm_should_0 = true;
            s.worm_spawned_0 = false;
            s.worm_spawn_0_ms = worm0;
            s.worm_enrage_0_ms = FANKRISS_WORM_ENRAGE_BASE_MS;
            s.worm_should_1 = false;
            s.worm_should_2 = false;
            s.num_worms_last_wave = 1;
            s.evade_check_timer_ms = 2500;
            s.alive_hatchlings = 0;
            s.hatchling_batches.clear();
        }
        self.fankriss_reinitialize_web_timers(guid, 8000);
        let (mut a, mut b, mut c) = (0u8, 1u8, 2u8);
        self.fankriss_shuffle3(&mut a, &mut b, &mut c);
        if let Some(s) = self.fankriss_state_mut(guid) {
            s.worm_loc_order_0 = a;
            s.worm_loc_order_1 = b;
            s.worm_loc_order_2 = c;
        }
    }

    /// `boss_fankrissAI::MoveInLineOfSight` (100yd pull + base, cpp 257-265).
    fn fankriss_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        // NEEDS-MAP-HELPER: feign-death aura check; proximity pull itself:
        let in_combat = self.ai_in_combat(guid);
        let dist_ok = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy <= 100.0 * 100.0
            }
            _ => false,
        };
        if self.players.contains_key(&who) && !in_combat && dist_ok {
            self.attack_start(guid, who);
        }
    }

