    /// `boss_fankrissAI::JustSummoned` (cpp 285-299).
    fn fankriss_just_summoned(&mut self, guid: ObjectGuid, created: ObjectGuid) {
        let entry = self.creatures.get(&created).map(|c| c.info.entry);
        if entry == Some(FANKRISS_NPC_HATCHLING) {
            if let Some(s) = self.fankriss_state_mut(guid) {
                s.alive_hatchlings += 1;
            }
        } else if entry == Some(FANKRISS_NPC_SPAWN) {
            self.set_in_combat_with_zone(created);
            // `SelectAttackingTarget(RANDOM, 0)` (cpp 294).
            if let Some(target) = self.select_random_hostile(guid) {
                self.attack_start(created, target);
            }
        }
    }

    /// `boss_fankrissAI::SummonedCreatureJustDied` (cpp 301-311).
    fn fankriss_summoned_creature_just_died(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        let entry = self.creatures.get(&victim).map(|c| c.info.entry);
        if entry != Some(FANKRISS_NPC_HATCHLING) {
            return;
        }
        if let Some(s) = self.fankriss_state_mut(guid) {
            for batch in &mut s.hatchling_batches {
                batch.retain(|g| *g != victim);
            }
            s.alive_hatchlings = s.alive_hatchlings.saturating_sub(1);
        }
    }

    /// `boss_fankrissAI::GetHatchlingSpawnAmount` (cpp 327-334).
    fn fankriss_hatchling_spawn_amount(&mut self, guid: ObjectGuid) -> usize {
        let alive = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Fankriss(s)) => Some(s.alive_hatchlings as usize),
                _ => None,
            })
            .unwrap_or(0);
        let mut amount =
            FANKRISS_MAX_HATCHLINGS_PER_WEB.min(FANKRISS_MAX_HATCHLINGS.saturating_sub(alive));
        if amount > 2 {
            amount = self.rng.urand(2, amount as u32) as usize;
        }
        amount
    }

    /// `boss_fankrissAI::SummonHatchling` (cpp 335-341).
    fn fankriss_summon_hatchling(
        &mut self,
        guid: ObjectGuid,
        batch: &mut Vec<ObjectGuid>,
        x: f32,
        y: f32,
        z: f32,
    ) {
        if let Some(created) = self.summon_creature(
            FANKRISS_NPC_HATCHLING,
            Position::new(x, y, z, 0.0),
            guid,
            FANKRISS_TEMPSUMMON_TIMED_OOC,
            65_000,
        ) {
            batch.push(created);
        }
    }

    /// `boss_fankrissAI::HandleHatchlings` (cpp 343-405;
    /// `ALWAYS_HATCHLINGS_IN_3_LOCATIONS` defined).
    fn fankriss_handle_hatchlings(&mut self, guid: ObjectGuid, diff_ms: u32) {
        for i in 0..3u8 {
            let (cast, timer) = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::Fankriss(s)) => Some(match i {
                        0 => (s.entangle_cast_0, s.entangle_timer_0_ms),
                        1 => (s.entangle_cast_1, s.entangle_timer_1_ms),
                        _ => (s.entangle_cast_2, s.entangle_timer_2_ms),
                    }),
                    _ => None,
                })
                .unwrap_or((true, 0));
            if cast {
                continue;
            }
            // Set only when this tick fires the web (fork spawns the batch
            // in the same iteration, not on later ticks).
            let mut fired = false;
            if timer < diff_ms {
                let order = self
                    .ai
                    .get(&guid)
                    .and_then(|ai| match &ai.script {
                        Some(CreatureScriptAi::Fankriss(s)) => Some(match i {
                            0 => s.entangle_order_0,
                            1 => s.entangle_order_1,
                            _ => s.entangle_order_2,
                        }),
                        _ => None,
                    })
                    .unwrap_or(0);
                let spell = match order {
                    0 => FANKRISS_SPELL_ENTANGLE_1,
                    1 => FANKRISS_SPELL_ENTANGLE_2,
                    _ => FANKRISS_SPELL_ENTANGLE_3,
                };
                // `SelectAttackingTarget(RANDOM, 0, nullptr, SELECT_FLAG_PLAYER)`
                // (cpp 355): player filter unmodeled.
                if let Some(target) = self.select_random_hostile(guid)
                    && self.do_cast_spell_if_can(guid, spell, CastTarget::Unit(target))
                    && let Some(s) = self.fankriss_state_mut(guid)
                {
                    match i {
                        0 => s.entangle_cast_0 = true,
                        1 => s.entangle_cast_1 = true,
                        _ => s.entangle_cast_2 = true,
                    }
                    fired = true;
                }
            } else if let Some(s) = self.fankriss_state_mut(guid) {
                match i {
                    0 => s.entangle_timer_0_ms -= diff_ms,
                    1 => s.entangle_timer_1_ms -= diff_ms,
                    _ => s.entangle_timer_2_ms -= diff_ms,
                }
            }
            // Hatchlings in all 3 web locations per cast web.
            if fired {
                let mut batch = Vec::new();
                for (x, y, z) in [
                    (-8_043.01, 1254.2, -84.19),
                    (-8_003.0, 1222.9, -82.1),
                    (-8_022.68, 1150.08, -89.33),
                ] {
                    let amount = self.fankriss_hatchling_spawn_amount(guid);
                    for _ in 0..amount {
                        self.fankriss_summon_hatchling(guid, &mut batch, x, y, z);
                    }
                }
                if let Some(s) = self.fankriss_state_mut(guid) {
                    s.hatchling_batches.push(batch);
                }
            }
        }
        let all_cast = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::Fankriss(s)) if s.entangle_cast_0 && s.entangle_cast_1 && s.entangle_cast_2)
        });
        let rotation_due = {
            let Some(s) = self.fankriss_state_mut(guid) else {
                return;
            };
            if all_cast && s.entangle_rotation_timer_ms < diff_ms {
                true
            } else {
                s.entangle_rotation_timer_ms = s.entangle_rotation_timer_ms.saturating_sub(diff_ms);
                false
            }
        };
        if rotation_due {
            self.fankriss_reinitialize_web_timers(guid, 0);
        }
    }

    /// `boss_fankrissAI::SummonWorm` (cpp 407-419).
    fn fankriss_summon_worm(&mut self, guid: ObjectGuid, x: f32, y: f32, z: f32, enrage_ms: u32) {
        if let Some(created) = self.summon_creature(
            FANKRISS_NPC_SPAWN,
            Position::new(x, y, z, 0.0),
            guid,
            FANKRISS_TEMPSUMMON_TIMED_OOC,
            50_000,
        ) {
            // Fork `dynamic_cast` + error log (cpp 411-416): no-op on mismatch.
            if let Some(ai) = self.ai.get_mut(&created) {
                if let Some(CreatureScriptAi::SpawnFankriss(s)) = &mut ai.script {
                    s.enrage_timer_ms = enrage_ms;
                }
            }
        }
    }

    /// `boss_fankrissAI::UpdateAI` (cpp 421-519).
    #[allow(clippy::too_many_lines)]
    fn fankriss_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Out-of-combat zone-in pull check (cpp 423-443).
        if !self.ai_in_combat(guid) {
            // NEEDS-MAP-HELPER: player Z (`> -70` skip), 3D distance to the
            // pull center (-8074.88, 1193.64, -92.11) + LOS (cpp 434-437);
            // 2D proximity approximation:
            let me = self.unit_position(guid).unwrap_or_default();
            let dx = me.x - -8_074.88;
            let dy = me.y - 1193.64;
            let mut pull: Option<ObjectGuid> = None;
            if dx * dx + dy * dy <= FANKRISS_PULL_DISTANCE * FANKRISS_PULL_DISTANCE {
                let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
                for p in players {
                    if self.unit_is_alive(p) {
                        pull = Some(p);
                        break;
                    }
                }
            }
            if let Some(p) = pull {
                self.attack_start(guid, p);
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Mortal Wound.
        let due = {
            let Some(s) = self.fankriss_state_mut(guid) else {
                return;
            };
            if s.mortal_wound_timer_ms < diff_ms {
                true
            } else {
                s.mortal_wound_timer_ms -= diff_ms;
                false
            }
        };
        let hoist82 = self.rng.urand(4000, 8000);
        if due
            && self.do_cast_spell_if_can(
                guid,
                FANKRISS_SPELL_MORTAL_WOUND,
                CastTarget::Unit(victim),
            )
            && let Some(s) = self.fankriss_state_mut(guid)
        {
            s.mortal_wound_timer_ms = hoist82;
        }
        // Worm waves (cpp 460-504).
        let waves = self.ai.get(&guid).and_then(|ai| match &ai.script {
            Some(CreatureScriptAi::Fankriss(s)) => Some((
                s.worm_should_0,
                s.worm_spawned_0,
                s.worm_spawn_0_ms,
                s.worm_enrage_0_ms,
                s.worm_loc_order_0,
                s.worm_should_1,
                s.worm_spawned_1,
                s.worm_spawn_1_ms,
                s.worm_enrage_1_ms,
                s.worm_loc_order_1,
                s.worm_should_2,
                s.worm_spawned_2,
                s.worm_spawn_2_ms,
                s.worm_enrage_2_ms,
                s.worm_loc_order_2,
            )),
            _ => None,
        });
        if let Some(w) = waves {
            let loc = |o: u8| -> (f32, f32, f32) {
                match o {
                    0 => (-8_076.53, 1120.37, -88.5),
                    1 => (-8_150.18, 1146.97, -87.45),
                    _ => (-8_023.31, 1242.42, -83.47),
                }
            };
            let mut all_spawned = true;
            let flags = [(w.0, w.1, w.2), (w.5, w.6, w.7), (w.10, w.11, w.12)];
            for (idx, (should, have, timer)) in flags.iter().enumerate() {
                if *should && !*have {
                    if *timer < diff_ms {
                        let (x, y, z) = loc(match idx {
                            0 => w.4,
                            1 => w.9,
                            _ => w.14,
                        });
                        let enrage = match idx {
                            0 => w.3,
                            1 => w.8,
                            _ => w.13,
                        };
                        self.fankriss_summon_worm(guid, x, y, z, enrage);
                        if let Some(s) = self.fankriss_state_mut(guid) {
                            match idx {
                                0 => s.worm_spawned_0 = true,
                                1 => s.worm_spawned_1 = true,
                                _ => s.worm_spawned_2 = true,
                            }
                        }
                    } else {
                        all_spawned = false;
                        if let Some(s) = self.fankriss_state_mut(guid) {
                            match idx {
                                0 => s.worm_spawn_0_ms -= diff_ms,
                                1 => s.worm_spawn_1_ms -= diff_ms,
                                _ => s.worm_spawn_2_ms -= diff_ms,
                            }
                        }
                    }
                }
            }
            if all_spawned {
                let (mut a, mut b, mut c) = (0u8, 1u8, 2u8);
                self.fankriss_shuffle3(&mut a, &mut b, &mut c);
                let count = self.rng.urand(1, 3);
                let last = self
                    .ai
                    .get(&guid)
                    .and_then(|ai| match &ai.script {
                        Some(CreatureScriptAi::Fankriss(s)) => Some(s.num_worms_last_wave),
                        _ => None,
                    })
                    .unwrap_or(1);
                let mut prev = 0u32;
                for i in 0..3u32 {
                    let should = i < count;
                    let (enrage, spawn) = if should {
                        let e = FANKRISS_WORM_ENRAGE_BASE_MS + FANKRISS_WORM_ENRAGE_ADDITION_MS * i;
                        let sp = if i == 0 {
                            18_000 + (last.saturating_sub(1)) * 7000 + self.rng.urand(0, 5000)
                        } else {
                            prev + self.rng.urand(4000, 8000)
                        };
                        prev = sp;
                        (e, sp)
                    } else {
                        (0, 0)
                    };
                    if let Some(s) = self.fankriss_state_mut(guid) {
                        match i {
                            0 => {
                                s.worm_should_0 = should;
                                s.worm_spawned_0 = false;
                                s.worm_enrage_0_ms = enrage;
                                s.worm_spawn_0_ms = spawn;
                            }
                            1 => {
                                s.worm_should_1 = should;
                                s.worm_spawned_1 = false;
                                s.worm_enrage_1_ms = enrage;
                                s.worm_spawn_1_ms = spawn;
                            }
                            _ => {
                                s.worm_should_2 = should;
                                s.worm_spawned_2 = false;
                                s.worm_enrage_2_ms = enrage;
                                s.worm_spawn_2_ms = spawn;
                            }
                        }
                    }
                }
                if let Some(s) = self.fankriss_state_mut(guid) {
                    s.worm_loc_order_0 = a;
                    s.worm_loc_order_1 = b;
                    s.worm_loc_order_2 = c;
                    s.num_worms_last_wave = count;
                }
            }
        }
        self.fankriss_handle_hatchlings(guid, diff_ms);
        // Leash: evade past the tunnel mouth (cpp 511-518).
        let due = {
            let Some(s) = self.fankriss_state_mut(guid) else {
                return;
            };
            if s.evade_check_timer_ms < diff_ms {
                s.evade_check_timer_ms = 2500;
                true
            } else {
                s.evade_check_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: `GetPositionY` read; 2D position fallback:
            let y = self.unit_position(guid).map_or(0.0, |p| p.y);
            if y > 1400.0 {
                self.enter_evade_mode(guid);
            }
        }
    }

