    /// Shared `boss_bug_trioAI::JustDied` (cpp 89-108).
    fn bug_trio_just_died(&mut self, guid: ObjectGuid) {
        self.aq40_set_data(AQ40_TYPE_BUG_TRIO, AQ40_SPECIAL);
        if self.aq40_encounter(AQ40_TYPE_BUG_TRIO as usize) != DONE {
            // NEEDS-MAP-HELPER: `SetLootRecipient(nullptr)` +
            // `ForcedDespawn(4000)` on self (cpp 95-96).
            for entry in [BUGTRIO_NPC_KRI, BUGTRIO_NPC_YAUJ, BUGTRIO_NPC_VEM] {
                if let Some(mate) = self.find_creature_by_entry(entry) {
                    if mate != guid {
                        self.bug_trio_trigger_devour(mate, guid);
                    }
                }
            }
        }
    }

    /// Shared `boss_bug_trioAI::TriggerDevour` (cpp 126-137).
    fn bug_trio_trigger_devour(&mut self, guid: ObjectGuid, corpse: ObjectGuid) {
        if !self.unit_is_alive(guid) {
            return;
        }
        let pos = self.unit_position(corpse).unwrap_or_default();
        let apply = |base: &mut BugTrioBase| {
            base.devour_timer_ms = 4000;
            base.is_eating = true;
        };
        if let Some(ai) = self.ai.get_mut(&guid) {
            match &mut ai.script {
                Some(CreatureScriptAi::Kri(s)) => apply(&mut s.base),
                Some(CreatureScriptAi::Yauj(s)) => apply(&mut s.base),
                Some(CreatureScriptAi::Vem(s)) => apply(&mut s.base),
                _ => {}
            }
        }
        // NEEDS-MAP-HELPER: `UpdateSpeed(MOVE_RUN, true, 2.7f)` +
        // `SetTargetGuid(ObjectGuid())` (cpp 133-136); movement itself:
        self.creature_move_point(
            guid,
            1,
            Position::new(pos.x, pos.y, pos.z, 0.0),
            0,
            0.0,
            0.0,
        );
    }

