    /// `boss_yaujAI::JustDied` (cpp 294-310).
    fn yauj_just_died(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: `GetRandomPoint(40.0f)` + room-center LOS check
        // (cpp 303-307); random-point approximation:
        let me = self.unit_position(guid).unwrap_or_default();
        for _ in 0..10 {
            let p = self.random_point(me, 40.0);
            let (x, y, z) = p.map_or((me.x, me.y, me.z), |q| (q.x, q.y, q.z));
            self.summon_creature(
                BUGTRIO_NPC_YAUJ_BROOD,
                Position::new(x, y, z, 0.0),
                guid,
                FANKRISS_TEMPSUMMON_TIMED_OOC,
                10_000,
            );
        }
        self.bug_trio_just_died(guid);
    }

