    /// `boss_kriAI::UpdateAI` via `UpdateBugAI` (cpp 167-206 + 235-265).
    fn kri_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        if !self.bug_trio_update_devour(guid, diff_ms) {
            return;
        }
        let due = {
            let Some(s) = self.kri_state_mut(guid) else {
                return;
            };
            if s.cleave_timer_ms < diff_ms {
                true
            } else {
                s.cleave_timer_ms -= diff_ms;
                false
            }
        };
        let hoist81 = self.rng.urand(5000, 12_000);
        if due
            && self.do_cast_spell_if_can(guid, BUGTRIO_SPELL_CLEAVE, CastTarget::Unit(victim))
            && let Some(s) = self.kri_state_mut(guid)
        {
            s.cleave_timer_ms = hoist81;
        }
        let due = {
            let Some(s) = self.kri_state_mut(guid) else {
                return;
            };
            if s.toxic_volley_timer_ms < diff_ms {
                true
            } else {
                s.toxic_volley_timer_ms -= diff_ms;
                false
            }
        };
        let hoist80 = self.rng.urand(8000, 14_000);
        if due
            && self.do_cast_spell_if_can(guid, BUGTRIO_SPELL_TOXIC_VOLLEY, CastTarget::SelfCast)
            && let Some(s) = self.kri_state_mut(guid)
        {
            s.toxic_volley_timer_ms = hoist80;
        }
        let due = {
            let Some(s) = self.kri_state_mut(guid) else {
                return;
            };
            if s.thrash_timer_ms < diff_ms {
                true
            } else {
                s.thrash_timer_ms -= diff_ms;
                false
            }
        };
        let hoist79 = self.rng.urand(2000, 8000);
        if due
            && self.do_cast_spell_if_can(guid, BUGTRIO_SPELL_THRASH, CastTarget::SelfCast)
            && let Some(s) = self.kri_state_mut(guid)
        {
            s.thrash_timer_ms = hoist79;
        }
        self.bug_trio_update_leash(guid, diff_ms);
    }

    /// `boss_yaujAI::UpdateAI` via `UpdateBugAI` (cpp 167-206 + 320-362).
    fn yauj_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        if !self.bug_trio_update_devour(guid, diff_ms) {
            return;
        }
        // Fear + threat wipe.
        let due = {
            let Some(s) = self.yauj_state_mut(guid) else {
                return;
            };
            if s.fear_timer_ms < diff_ms {
                true
            } else {
                s.fear_timer_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, BUGTRIO_SPELL_FEAR, CastTarget::SelfCast) {
            // NEEDS-MAP-HELPER: `DoResetThreat` (cpp 328).
            if let Some(s) = self.yauj_state_mut(guid) {
                s.fear_timer_ms = 20_000;
            }
        }
        // Heal: self under 93%, else lowest-HP friendly in 100yd.
        let due = {
            let Some(s) = self.yauj_state_mut(guid) else {
                return;
            };
            if s.heal_timer_ms < diff_ms {
                true
            } else {
                s.heal_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            if self.creature_health_percent(guid) <= 93.0 {
                if self.do_cast_spell_if_can(guid, BUGTRIO_SPELL_HEAL, CastTarget::Unit(guid))
                    && let Some(s) = self.yauj_state_mut(guid)
                {
                    s.heal_timer_ms = 12_000;
                }
            } else {
                // NEEDS-MAP-HELPER: `FindLowestHpFriendlyUnit(100.0f)`
                // (cpp 343); lowest-HP live friendly approximation skipped:
                // no heal target resolved this tick.
            }
        }
        // Ravage.
        let due = {
            let Some(s) = self.yauj_state_mut(guid) else {
                return;
            };
            if s.ravage_timer_ms < diff_ms {
                true
            } else {
                s.ravage_timer_ms -= diff_ms;
                false
            }
        };
        let hoist78 = self.rng.urand(12_000, 20_000);
        if due
            && self.do_cast_spell_if_can(guid, BUGTRIO_SPELL_RAVAGE, CastTarget::Unit(victim))
            && let Some(s) = self.yauj_state_mut(guid)
        {
            s.ravage_timer_ms = hoist78;
        }
        self.bug_trio_update_leash(guid, diff_ms);
    }

    /// `boss_vemAI::UpdateAI` via `UpdateBugAI` (cpp 167-206 + 400-440).
    fn vem_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        if !self.bug_trio_update_devour(guid, diff_ms) {
            return;
        }
        // Charge (random target outside melee range).
        let due = {
            let Some(s) = self.vem_state_mut(guid) else {
                return;
            };
            if s.charge_timer_ms < diff_ms {
                true
            } else {
                s.charge_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // `SelectAttackingTarget(RANDOM, 0, SPELL_CHARGE,
            // SELECT_FLAG_NOT_IN_MELEE_RANGE)` (cpp 406): melee filter
            // unmodeled, random hostile used.
            let hoist77 = self.rng.urand(15_000, 20_000);
            if let Some(target) = self.select_random_hostile(guid)
                && self.do_cast_spell_if_can(guid, BUGTRIO_SPELL_CHARGE, CastTarget::Unit(target))
                && let Some(s) = self.vem_state_mut(guid)
            {
                s.charge_timer_ms = hoist77;
            }
        }
        // Knock Away (melee-range victim, not stunned).
        let due = {
            let Some(s) = self.vem_state_mut(guid) else {
                return;
            };
            if s.knockback_timer_ms < diff_ms {
                true
            } else {
                s.knockback_timer_ms -= diff_ms;
                false
            }
        };
        let hoist76 = self.rng.urand(10_000, 14_000);
        if due
            // NEEDS-MAP-HELPER: victim `UNIT_STATE_STUNNED` check (cpp 418).
            && self.can_reach_melee(guid, victim)
            && self.do_cast_spell_if_can(guid, BUGTRIO_SPELL_KNOCKBACK, CastTarget::Unit(victim))
            && let Some(s) = self.vem_state_mut(guid)
        {
            s.knockback_timer_ms = hoist76;
        }
        // Knockdown (random melee-range target, cast on victim).
        let due = {
            let Some(s) = self.vem_state_mut(guid) else {
                return;
            };
            if s.knockdown_timer_ms < diff_ms {
                true
            } else {
                s.knockdown_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // `SelectAttackingTarget(RANDOM, 0, SPELL_KNOCKDOWN,
            // SELECT_FLAG_IN_MELEE_RANGE)` (cpp 430): existence check only —
            // fork still casts on the victim.
            let hoist75 = self.rng.urand(15_000, 20_000);
            if self.select_random_hostile(guid).is_some()
                && self.do_cast_spell_if_can(
                    guid,
                    BUGTRIO_SPELL_KNOCKDOWN,
                    CastTarget::Unit(victim),
                )
                && let Some(s) = self.vem_state_mut(guid)
            {
                s.knockdown_timer_ms = hoist75;
            }
        }
        self.bug_trio_update_leash(guid, diff_ms);
    }

