    /// `boss_sarturaAI::Reset` (cpp 79-91).
    fn sartura_reset(&mut self, guid: ObjectGuid) {
        let whirlwind = self.rng.urand(8000, 12_000);
        let aggro = self.rng.urand(5000, 7500);
        if let Some(s) = self.sartura_state_mut(guid) {
            s.cleave_timer_ms = 4000;
            s.whirlwind_timer_ms = whirlwind;
            s.whirlwind_end_timer_ms = 0;
            s.aggro_reset_timer_ms = aggro;
            s.enrage_hard_timer_ms = 600_000;
            s.is_enraged = false;
            s.evade_check_timer_ms = 2500;
        }
    }

    /// `boss_sarturaAI::MoveInLineOfSight` (85yd + LOS pull, cpp 93-101).
