    /// `boss_sarturaAI::UpdateAI` (cpp 162-266).
    #[allow(clippy::too_many_lines)]
    fn sartura_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let in_whirlwind = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::Sartura(s)) if s.whirlwind_end_timer_ms != 0)
        });
        if in_whirlwind {
            let due = {
                let Some(s) = self.sartura_state_mut(guid) else {
                    return;
                };
                if s.aggro_reset_timer_ms < diff_ms {
                    true
                } else {
                    s.aggro_reset_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                self.sartura_assign_random_threat(guid);
                let next = self.rng.urand(1000, 2000);
                if let Some(s) = self.sartura_state_mut(guid) {
                    s.aggro_reset_timer_ms = next;
                }
            }
            // Fork `<=` end-of-whirlwind (cpp 179).
            let end_timer = self
                .sartura_state_mut(guid)
                .map_or(0, |s| s.whirlwind_end_timer_ms);
            if end_timer <= diff_ms {
                let whirlwind = self.rng.urand(5000, 10_000);
                let aggro = self.rng.urand(3000, 7000);
                if let Some(s) = self.sartura_state_mut(guid) {
                    s.whirlwind_end_timer_ms = 0;
                    s.whirlwind_timer_ms = whirlwind;
                    s.aggro_reset_timer_ms = aggro;
                }
                // NEEDS-MAP-HELPER: `ApplyAttackTimePercentMod(BASE_ATTACK, 0,
                // true)` + `SetAttackTimer(BASE_ATTACK, 100)` (cpp 185-186).
            } else if let Some(s) = self.sartura_state_mut(guid) {
                s.whirlwind_end_timer_ms -= diff_ms;
            }
        } else {
            // Enter whirlwind.
            let due = {
                let Some(s) = self.sartura_state_mut(guid) else {
                    return;
                };
                if s.whirlwind_timer_ms < diff_ms {
                    true
                } else {
                    s.whirlwind_timer_ms -= diff_ms;
                    false
                }
            };
            if due && self.do_cast_spell_if_can(guid, SARTURA_SPELL_WHIRLWIND, CastTarget::SelfCast)
            {
                self.sartura_assign_random_threat(guid);
                let aggro = self.rng.urand(1000, 2000);
                if let Some(s) = self.sartura_state_mut(guid) {
                    s.whirlwind_end_timer_ms = 15_000;
                    s.aggro_reset_timer_ms = aggro;
                }
            }
            // Periodic retarget.
            let due = {
                let Some(s) = self.sartura_state_mut(guid) else {
                    return;
                };
                if s.aggro_reset_timer_ms < diff_ms {
                    true
                } else {
                    s.aggro_reset_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                self.sartura_assign_random_threat(guid);
                let next = self.rng.urand(3000, 7000);
                if let Some(s) = self.sartura_state_mut(guid) {
                    s.aggro_reset_timer_ms = next;
                }
            }
            // Sundering Cleave.
            let due = {
                let Some(s) = self.sartura_state_mut(guid) else {
                    return;
                };
                if s.cleave_timer_ms < diff_ms {
                    true
                } else {
                    s.cleave_timer_ms -= diff_ms;
                    false
                }
            };
            let hoist74 = self.rng.urand(3000, 4000);
            if due
                && self.do_cast_spell_if_can(guid, SARTURA_SPELL_CLEAVE, CastTarget::Unit(victim))
                && let Some(s) = self.sartura_state_mut(guid)
            {
                s.cleave_timer_ms = hoist74;
            }
        }
        // Soft enrage below 20% (triggered while whirlwinding, cpp 229).
        let enraged = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Sartura(s)) if s.is_enraged),
        );
        let in_whirlwind = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::Sartura(s)) if s.whirlwind_end_timer_ms != 0)
        });
        if !enraged && self.creature_health_percent(guid) <= 20.0 {
            let cast_ok = if in_whirlwind {
                self.aq_triggered_cast(guid, SARTURA_SPELL_ENRAGE, CastTarget::SelfCast)
            } else {
                self.do_cast_spell_if_can(guid, SARTURA_SPELL_ENRAGE, CastTarget::SelfCast)
            };
            if cast_ok {
                self.do_script_text(SARTURA_EMOTE_ENRAGE, guid, None, -1);
                if let Some(s) = self.sartura_state_mut(guid) {
                    s.is_enraged = true;
                }
            }
        }
        // Hard enrage after 10 minutes (fork `<=`, cpp 240).
        let hard_timer = self
            .sartura_state_mut(guid)
            .map_or(0, |s| s.enrage_hard_timer_ms);
        if hard_timer != 0 {
            if hard_timer <= diff_ms {
                let cast_ok = if in_whirlwind {
                    self.aq_triggered_cast(guid, SARTURA_SPELL_ENRAGEHARD, CastTarget::SelfCast)
                } else {
                    self.do_cast_spell_if_can(guid, SARTURA_SPELL_ENRAGEHARD, CastTarget::SelfCast)
                };
                if cast_ok {
                    self.do_script_text(SARTURA_EMOTE_ENRAGEHARD, guid, None, -1);
                    if let Some(s) = self.sartura_state_mut(guid) {
                        s.enrage_hard_timer_ms = 0;
                        s.is_enraged = true;
                    }
                }
            } else if let Some(s) = self.sartura_state_mut(guid) {
                s.enrage_hard_timer_ms -= diff_ms;
            }
        }
        // Leash past the throne room (cpp 255-265).
        let due = {
            let Some(s) = self.sartura_state_mut(guid) else {
                return;
            };
            if s.evade_check_timer_ms < diff_ms {
                s.evade_check_timer_ms = 2500;
                true
            } else {
                s.evade_check_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: `GetPositionY` read; 2D fallback:
            let y = self.unit_position(guid).map_or(0.0, |p| p.y);
            if y > 1780.0 {
                self.enter_evade_mode(guid);
                self.sartura_leash_encounter(guid);
            }
        }
    }

