    /// `mob_vekniss_guardianAI::MoveInLineOfSight` (50yd + LOS pull, cpp 465-473).
    fn vekniss_guardian_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        // NEEDS-MAP-HELPER: feign-death aura check + `IsWithinLOSInMap`;
        // proximity pull itself:
        let in_combat = self.ai_in_combat(guid);
        let dist_ok = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy <= 50.0 * 50.0
            }
            _ => false,
        };
        if self.players.contains_key(&who) && !in_combat && dist_ok {
            self.attack_start(guid, who);
        }
    }

