    /// `npc_dirt_moundAI::UpdateAI` (cpp 502-535).
    fn dirt_mound_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let (current, change_timer) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::DirtMound(s)) => {
                    Some((s.current_target_guid, s.change_target_timer_ms))
                }
                _ => None,
            })
            .unwrap_or((ObjectGuid::EMPTY, 0));
        // NEEDS-MAP-HELPER: `IsImmuneToDamage(NATURE)` + `IsDead` checks on
        // the current target (cpp 505).
        let force = current.is_empty() || !self.unit_is_alive(current);
        if force || change_timer < diff_ms {
            let target = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::DirtMound(s)) => Some(s.target_guid),
                    _ => None,
                })
                .unwrap_or(ObjectGuid::EMPTY);
            if !target.is_empty()
                && (self.creatures.contains_key(&target) || self.players.contains_key(&target))
            {
                // NEEDS-MAP-HELPER: `MoveFollow(target, 0, 0)` (cpp 513).
                if let Some(s) = self.dirt_mound_state_mut(guid) {
                    s.current_target_guid = target;
                    s.target_guid = ObjectGuid::EMPTY;
                }
            } else {
                // NEEDS-MAP-HELPER: `MoveRandom` (cpp 519).
            }
            let next = self.rng.urand(0, 10_000);
            if let Some(s) = self.dirt_mound_state_mut(guid) {
                s.change_target_timer_ms = next;
            }
        } else if let Some(s) = self.dirt_mound_state_mut(guid) {
            s.change_target_timer_ms -= diff_ms;
        }
        // Despawn + scarab shower (fork `<`, cpp 526).
        let due = {
            let Some(s) = self.dirt_mound_state_mut(guid) else {
                return;
            };
            if s.despawn_timer_ms < diff_ms {
                true
            } else {
                s.despawn_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            self.aq_triggered_cast(guid, OURO_SPELL_SUMMON_SCARABS, CastTarget::SelfCast);
            self.despawn_creature_now(guid, 0);
        }
    }

