    /// `boss_viscidusAI::Reset` (cpp 205-225).
    fn viscidus_reset(&mut self, guid: ObjectGuid) {
        let toxin = self.rng.urand(30_000, 40_000);
        let shock = self.rng.urand(7000, 12_000);
        let volley = self.rng.urand(10_000, 15_000);
        if let Some(s) = self.viscidus_state_mut(guid) {
            s.grow_timer_ms = 0;
            s.phase = VISCIDUS_PHASE_NORMAL;
            s.restore_target_timer_ms = 0;
            s.hit_count = 0;
            s.explode_delay_timer_ms = 0;
            s.toxin_timer_ms = toxin;
            s.poison_shock_timer_ms = shock;
            s.poisonbolt_volley_timer_ms = volley;
            s.grow_count = 0;
            // NEEDS-MAP-HELPER: `SetObjectScale(m_initialScale)` (cpp 218).
            s.track_mask = 0;
        }
        self.aq_triggered_cast(guid, VISCIDUS_SPELL_MEMBRANE, CastTarget::SelfCast);
        self.aq_triggered_cast(guid, VISCIDUS_SPELL_WEAKNESS, CastTarget::SelfCast);
        self.viscidus_reset_state(guid);
    }

