    /// `boss_viscidusAI::ResetFrozenPhase` (cpp 418-426; called from the
    /// freeze-aura-dummy spell script — spell kind, see census).
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    pub(crate) fn viscidus_reset_frozen_phase(&mut self, guid: ObjectGuid) {
        let phase = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Viscidus(s)) => Some(s.phase),
                _ => None,
            })
            .unwrap_or(0);
        if phase == VISCIDUS_PHASE_EXPLODED {
            return;
        }
        if let Some(s) = self.viscidus_state_mut(guid) {
            s.phase = VISCIDUS_PHASE_NORMAL;
            s.hit_count = 0;
        }
    }

    /// `boss_viscidusAI::SummonedCreatureJustDied` (cpp 289-315).
    fn viscidus_summoned_creature_just_died(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        if self.creatures.get(&victim).map(|c| c.info.entry) != Some(VISCIDUS_NPC_GLOB) {
            return;
        }
        if self.aq_triggered_cast(guid, VISCIDUS_SPELL_SHRINKS_HP, CastTarget::SelfCast) {
            // Each dead glob costs 5% of max health, floor 1% (cpp 296-305).
            let hp = u64::from(self.unit_value_u32(guid, offsets::UNIT_FIELD_HEALTH));
            let max = u64::from(self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXHEALTH));
            let cost = max * 5 / 100;
            let new_hp = hp.saturating_sub(cost);
            if new_hp != 0 && new_hp <= max {
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::UNIT_FIELD_HEALTH),
                    new_hp as u32,
                );
            } else {
                // NEEDS-MAP-HELPER: `SetHealthPercent(1.0f)` exact-shape
                // fallback (cpp 304); field-write approximation:
                let one_pct = (max / 100).max(1) as u32;
                let _ = self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_HEALTH), one_pct);
            }
        }
        if let Some(s) = self.viscidus_state_mut(guid) {
            s.glob_guids.retain(|g| *g != victim);
        }
        let empty = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::Viscidus(s)) if s.glob_guids.is_empty())
        });
        if empty {
            self.viscidus_reset_state(guid);
        }
    }

    /// `boss_viscidusAI::SummonedMovementInform` (cpp 317-331).
    fn viscidus_summoned_movement_inform(
        &mut self,
        guid: ObjectGuid,
        created: ObjectGuid,
        point_id: u32,
    ) {
        // Fork also gates on `uiType == POINT_MOTION_TYPE` (cpp 319).
        if self.creatures.get(&created).map(|c| c.info.entry) != Some(VISCIDUS_NPC_GLOB) {
            return;
        }
        if point_id == 0 {
            return;
        }
        if let Some(s) = self.viscidus_state_mut(guid) {
            s.glob_guids.retain(|g| *g != created);
        }
        self.aq_triggered_cast(created, VISCIDUS_SPELL_REJOIN, CastTarget::Unit(guid));
        self.despawn_creature_now(created, 1);
        let mut empty = false;
        if let Some(s) = self.viscidus_state_mut(guid) {
            s.grow_count = s.grow_count.saturating_add(1);
            empty = s.glob_guids.is_empty();
        }
        if empty {
            self.viscidus_reset_state(guid);
        }
    }

    /// `boss_viscidusAI::SpellHit` (cpp 333-416). The frost-school counting
    /// (cpp 360-415) keys on `SpellEntry.School` + the attacker's wand item,
    /// neither visible here (NEEDS-MAP-HELPER); only the explode branch
    /// (spell-id gated) is transcribed.
    #[allow(clippy::needless_range_loop)]
    fn viscidus_spell_hit(&mut self, guid: ObjectGuid, _caster: ObjectGuid, spell_id: u32) {
        if spell_id != VISCIDUS_SPELL_EXPLODE {
            // NEEDS-MAP-HELPER: frost-hit counting (`HITCOUNT_SLOW/SLOW_MORE/
            // FREEZE` + slowed emotes/auras, wand frost check, cpp 360-415).
            return;
        }
        if self.creature_health_percent(guid) < 5.0 {
            // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_ON)` +
            // `SetInvincibilityHpThreshold(0)` (cpp 340-341); damage itself:
            if self.aq_triggered_cast(guid, VISCIDUS_SPELL_SUICIDE, CastTarget::SelfCast) {
                // NEEDS-MAP-HELPER: `DealDamage(self, health)` exact-shape
                // self-kill (cpp 344).
                self.kill_unit(guid, None);
            }
            return;
        }
        if let Some(s) = self.viscidus_state_mut(guid) {
            s.phase = VISCIDUS_PHASE_EXPLODED;
            s.glob_guids.clear();
        }
        let globes = (self.creature_health_percent(guid) / 5.0) as usize;
        for i in 0..globes.min(VISCIDUS_GLOB_SUMMON_SPELLS.len()) {
            self.aq_triggered_cast(guid, VISCIDUS_GLOB_SUMMON_SPELLS[i], CastTarget::SelfCast);
        }
        if let Some(s) = self.viscidus_state_mut(guid) {
            s.explode_delay_timer_ms = 2500;
        }
    }

    /// `boss_viscidusAI::HackyScaleUpdate` (cpp 428-437).
    fn viscidus_hacky_scale_update(&mut self, guid: ObjectGuid) {
        let hp = (self.creature_health_percent(guid) / 5.0) as u32;
        if hp >= 32 {
            return;
        }
        let bit = 1u32 << hp;
        let known = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Viscidus(s)) => Some(s.track_mask),
                _ => None,
            })
            .unwrap_or(0);
        if hp as usize != 20 && known & bit == 0 {
            if let Some(s) = self.viscidus_state_mut(guid) {
                s.track_mask |= bit;
            }
            self.aq_triggered_cast(guid, VISCIDUS_SPELL_SHRINKS, CastTarget::SelfCast);
        }
    }

    /// `boss_viscidusAI::UpdateAI` (cpp 439-542).
    #[allow(clippy::too_many_lines)]
    fn viscidus_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        self.viscidus_hacky_scale_update(guid);
        // Grow ticks (fork `<=`, cpp 447).
        let grow_timer = self.viscidus_state_mut(guid).map_or(0, |s| s.grow_timer_ms);
        if grow_timer <= diff_ms {
            let count = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::Viscidus(s)) => Some(s.grow_count),
                    _ => None,
                })
                .unwrap_or(0);
            if count != 0 {
                self.aq_triggered_cast(guid, VISCIDUS_SPELL_GROWS, CastTarget::SelfCast);
                // NEEDS-MAP-HELPER: `SetObjectScale(+0.04f)` (cpp 452).
                if let Some(s) = self.viscidus_state_mut(guid) {
                    s.grow_count -= 1;
                }
            }
            if let Some(s) = self.viscidus_state_mut(guid) {
                s.grow_timer_ms = 150;
            }
        } else if let Some(s) = self.viscidus_state_mut(guid) {
            s.grow_timer_ms -= diff_ms;
        }
        // Explode invisibility delay (fork `<=`, cpp 460).
        let explode = self
            .viscidus_state_mut(guid)
            .map_or(0, |s| s.explode_delay_timer_ms);
        if explode != 0 {
            if explode <= diff_ms {
                // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_OFF)` +
                // `SetObjectScale(-0.04 * glob_count)` (cpp 465-470).
                if let Some(s) = self.viscidus_state_mut(guid) {
                    s.explode_delay_timer_ms = 0;
                }
            } else if let Some(s) = self.viscidus_state_mut(guid) {
                s.explode_delay_timer_ms -= diff_ms;
            }
        }
        // Toxin-target visual restore (fork `<=`, cpp 479).
        let restore = self
            .viscidus_state_mut(guid)
            .map_or(0, |s| s.restore_target_timer_ms);
        if restore != 0 {
            if restore <= diff_ms {
                // NEEDS-MAP-HELPER: `SetInFront` + `SetTargetGuid` back to the
                // victim (cpp 484-485).
                if let Some(s) = self.viscidus_state_mut(guid) {
                    s.restore_target_timer_ms = 0;
                }
            } else if let Some(s) = self.viscidus_state_mut(guid) {
                s.restore_target_timer_ms -= diff_ms;
            }
        }
        // Only the normal phase casts (cpp 493).
        let phase = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Viscidus(s)) => Some(s.phase),
                _ => None,
            })
            .unwrap_or(0);
        if phase != VISCIDUS_PHASE_NORMAL {
            return;
        }
        // Poison Shock.
        let due = {
            let Some(s) = self.viscidus_state_mut(guid) else {
                return;
            };
            if s.poison_shock_timer_ms < diff_ms {
                true
            } else {
                s.poison_shock_timer_ms -= diff_ms;
                false
            }
        };
        let hoist72 = self.rng.urand(7000, 12_000);
        if due
            && self.do_cast_spell_if_can(guid, VISCIDUS_SPELL_POISON_SHOCK, CastTarget::SelfCast)
            && let Some(s) = self.viscidus_state_mut(guid)
        {
            s.poison_shock_timer_ms = hoist72;
        }
        // Poison Bolt Volley.
        let due = {
            let Some(s) = self.viscidus_state_mut(guid) else {
                return;
            };
            if s.poisonbolt_volley_timer_ms < diff_ms {
                true
            } else {
                s.poisonbolt_volley_timer_ms -= diff_ms;
                false
            }
        };
        let hoist71 = self.rng.urand(10_000, 15_000);
        if due
            && self.do_cast_spell_if_can(
                guid,
                VISCIDUS_SPELL_POISONBOLT_VOLLEY,
                CastTarget::SelfCast,
            )
            && let Some(s) = self.viscidus_state_mut(guid)
        {
            s.poisonbolt_volley_timer_ms = hoist71;
        }
        // Toxin trigger summon (random LOS target, cpp 512).
        let due = {
            let Some(s) = self.viscidus_state_mut(guid) else {
                return;
            };
            if s.toxin_timer_ms < diff_ms {
                true
            } else {
                s.toxin_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // `SelectAttackingTarget(RANDOM, 0, nullptr, SELECT_FLAG_IN_LOS)`
            // (cpp 514): LOS filter unmodeled.
            if let Some(target) = self.select_random_hostile(guid) {
                let pos = self.unit_position(target).unwrap_or_default();
                if let Some(trigger) = self.summon_creature(
                    VISCIDUS_NPC_TRIGGER,
                    Position::new(pos.x, pos.y, pos.z, pos.o),
                    guid,
                    VISCIDUS_TEMPSUMMON_TIMED,
                    180_000,
                ) {
                    let next = self.rng.urand(30_000, 40_000);
                    if let Some(s) = self.viscidus_state_mut(guid) {
                        s.toxin_timer_ms = next;
                    }
                    // NEEDS-MAP-HELPER: trigger `RemoveFlag(NOT_SELECTABLE)`,
                    // `SetInFront`/`SetTargetGuid` visual + `CastSpell(26601)`
                    // + trigger `SetFlag(NOT_SELECTABLE)` (cpp 523-532).
                    let _ = trigger;
                    if let Some(s) = self.viscidus_state_mut(guid) {
                        s.restore_target_timer_ms = 800;
                    }
                }
            }
        }
        // NEEDS-MAP-HELPER: `EnterEvadeIfOutOfCombatArea` (cpp 541).
    }

