    /// Shared `boss_twinemperorsAI::MoveInLineOfSight` (cpp 247-263).
    fn twins_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        // NEEDS-MAP-HELPER: `IsTargetableBy` + `IsInAccessablePlaceFor` +
        // `GetAttackDistance` + Z-window (`<= 7`, cpp 254-261); PULL_RANGE
        // fallback:
        if self.unit_victim(guid).is_some() || self.ai_in_combat(guid) {
            return;
        }
        if !self.players.contains_key(&who) {
            return;
        }
        let (dist_ok, z_ok) = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => (
                {
                    let dx = a.x - b.x;
                    let dy = a.y - b.y;
                    dx * dx + dy * dy <= TWINS_PULL_RANGE * TWINS_PULL_RANGE
                },
                (a.z - b.z).abs() <= 7.0,
            ),
            _ => (false, false),
        };
        if dist_ok && z_ok {
            self.attack_start(guid, who);
        }
    }

