    // NO-DISPATCHER-YET: `boss_twinemperorsAI::HealedBy` twin-health mirror
    // (cpp 363-375) — no `healed_by` dispatcher.
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn twins_healed_by(&mut self, guid: ObjectGuid, healed_amount: u32) {
        let Some(other) = self.twins_other_boss(guid) else {
            return;
        };
        let self_max = u64::from(self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXHEALTH));
        let other_max = u64::from(self.unit_value_u32(other, offsets::UNIT_FIELD_MAXHEALTH));
        if self_max == 0 {
            return;
        }
        let twin_heal = (u64::from(healed_amount)) * other_max / self_max;
        let other_hp = u64::from(self.unit_value_u32(other, offsets::UNIT_FIELD_HEALTH));
        let new_hp = (other_hp + twin_heal).min(other_max);
        let _ = self.object_set_field(other, u32::from(offsets::UNIT_FIELD_HEALTH), new_hp as u32);
    }

