    /// Shared `boss_twinemperorsAI::Aggro` (cpp 318-354).
    fn twins_aggro(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        if self.aq40_encounter(AQ40_TYPE_TWINS as usize) == IN_PROGRESS {
            return;
        }
        self.aq40_set_data(AQ40_TYPE_TWINS, IN_PROGRESS);
        // Anubisath defenders join (800yd, cpp 330-339).
        let me = self.unit_position(guid).unwrap_or_default();
        let mut opened = false;
        let mut defenders: Vec<ObjectGuid> = Vec::new();
        for (g, c) in &self.creatures {
            if c.info.entry != TWINS_NPC_ANUBISATH_DEFENDER {
                continue;
            }
            let ok = match self.unit_position(*g) {
                Some(p) => {
                    let dx = p.x - me.x;
                    let dy = p.y - me.y;
                    dx * dx + dy * dy <= 800.0 * 800.0
                }
                None => false,
            };
            if ok && self.unit_is_alive(*g) {
                defenders.push(*g);
            }
        }
        for d in defenders {
            // NEEDS-MAP-HELPER: `SetActiveObjectState(true)` (cpp 335).
            self.set_in_combat_with_zone(d);
            self.attack_start(d, who);
            opened = true;
        }
        if !opened {
            // NEEDS-MAP-HELPER: `DoResetDoor` on `GO_TWINS_ENTER_DOOR`
            // (cpp 341-343).
        }
        self.set_in_combat_with_zone(guid);
        if let Some(other) = self.twins_other_boss(guid) {
            self.attack_start(other, who);
            self.set_in_combat_with_zone(other);
        }
    }

