    /// `boss_veklorAI::KilledUnit` (cpp 674-681; fork says the Veknilash slay
    /// text, transcribed as-is).
    fn veklor_killed_unit(&mut self, guid: ObjectGuid, _victim: ObjectGuid) {
        let cd = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Veklor(s)) => Some(s.base.kill_say_cooldown_ms),
                _ => None,
            })
            .unwrap_or(1);
        if cd == 0 {
            self.do_script_text(TWINS_SAY_VEKNILASH_SLAY, guid, None, -1);
            let next = self.rng.urand(5000, 10_000);
            if let Some(s) = self.veklor_state_mut(guid) {
                s.base.kill_say_cooldown_ms = next;
            }
        }
    }

