    /// Shared `OnStartTeleport` (cpp 468-480).
    #[allow(clippy::many_single_char_names)]
    fn twins_on_start_teleport(&mut self, guid: ObjectGuid, x: f32, y: f32, z: f32, o: f32) {
        let apply = |base: &mut TwinsBase| {
            base.just_teleported = true;
            base.just_teleported_timer_ms = TWINS_JUST_TELEPORTED_FREEZE_MS;
        };
        if let Some(ai) = self.ai.get_mut(&guid) {
            match &mut ai.script {
                Some(CreatureScriptAi::Veklor(s)) => apply(&mut s.base),
                Some(CreatureScriptAi::Veknilash(s)) => apply(&mut s.base),
                _ => {}
            }
        }
        // NEEDS-MAP-HELPER: `InterruptNonMeleeSpells` + `DoStopAttack` +
        // `DoResetThreat` + `StopMoving` (cpp 473-475); teleport itself:
        self.teleport_creature_in_map(guid, Position::new(x, y, z, o));
        if let Some(ai) = self.ai.get_mut(&guid) {
            match &mut ai.script {
                Some(CreatureScriptAi::Veklor(s)) => {
                    s.base.closest_target_after_tp = ObjectGuid::EMPTY;
                }
                Some(CreatureScriptAi::Veknilash(s)) => {
                    s.base.closest_target_after_tp = ObjectGuid::EMPTY;
                }
                _ => {}
            }
        }
        self.aq_triggered_cast(guid, TWINS_SPELL_TWIN_TELEPORT_MSG, CastTarget::SelfCast);
        self.aq_triggered_cast(guid, TWINS_SPELL_TWIN_TELEPORT_VISUAL, CastTarget::SelfCast);
    }

    /// Shared `OnEndTeleport` + `OnEndTeleportVirtual` (cpp 484-499, 759-766,
    /// 915-918).
    fn twins_on_end_teleport(&mut self, guid: ObjectGuid) {
        let apply = |base: &mut TwinsBase| {
            base.just_teleported = false;
        };
        if let Some(ai) = self.ai.get_mut(&guid) {
            match &mut ai.script {
                Some(CreatureScriptAi::Veklor(s)) => apply(&mut s.base),
                Some(CreatureScriptAi::Veknilash(s)) => apply(&mut s.base),
                _ => {}
            }
        }
        let closest = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Veklor(s)) => Some(s.base.closest_target_after_tp),
                Some(CreatureScriptAi::Veknilash(s)) => Some(s.base.closest_target_after_tp),
                _ => None,
            })
            .unwrap_or(ObjectGuid::EMPTY);
        if !closest.is_empty() && self.players.contains_key(&closest) {
            self.attack_start(guid, closest);
        }
        // Vek'lor virtual: shadowbolt reset (cpp 759-766); Vek'nilash: none.
        if let Some(ai) = self.ai.get_mut(&guid) {
            if let Some(CreatureScriptAi::Veklor(s)) = &mut ai.script {
                s.shadowbolt_timer_ms = 0;
            }
        }
    }

    /// Shared `HandleBugSpell` (cpp 501-548).
    fn twins_handle_bug_spell(
        &mut self,
        guid: ObjectGuid,
        diff_ms: u32,
        bug_spell: u32,
        bug_cd: (u32, u32),
    ) {
        let frozen = self.ai.get(&guid).is_some_and(|ai| match &ai.script {
            Some(CreatureScriptAi::Veklor(s)) => s.base.just_teleported,
            Some(CreatureScriptAi::Veknilash(s)) => s.base.just_teleported,
            _ => false,
        });
        let timer = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Veklor(s)) => Some(s.base.bug_mutation_timer_ms),
                Some(CreatureScriptAi::Veknilash(s)) => Some(s.base.bug_mutation_timer_ms),
                _ => None,
            })
            .unwrap_or(0);
        if timer < diff_ms {
            if frozen {
                return;
            }
            // Bugs of either type within 20yd, skipping used/dead ones.
            // NEEDS-MAP-HELPER: `HasAura(MUTATE/EXPLODE)` skip (cpp 520).
            let me = self.unit_position(guid).unwrap_or_default();
            let mut pool: Vec<ObjectGuid> = Vec::new();
            for (g, c) in &self.creatures {
                if c.info.entry != TWINS_BUG_TYPE_1 && c.info.entry != TWINS_BUG_TYPE_2 {
                    continue;
                }
                if !self.unit_is_alive(*g) {
                    continue;
                }
                let ok = match self.unit_position(*g) {
                    Some(p) => {
                        let dx = p.x - me.x;
                        let dy = p.y - me.y;
                        dx * dx + dy * dy <= TWINS_BUG_SPELL_MAX_DIST * TWINS_BUG_SPELL_MAX_DIST
                    }
                    None => false,
                };
                if ok {
                    pool.push(*g);
                }
            }
            if pool.is_empty() {
                return;
            }
            let idx = self.rng.urand(0, pool.len() as u32 - 1) as usize;
            if let Some(bug) = pool.get(idx) {
                self.twins_bug_go_be_bad_bug(*bug, bug_spell);
            }
            let next = self.rng.urand(bug_cd.0, bug_cd.1);
            let apply = |base: &mut TwinsBase| {
                base.bug_mutation_timer_ms = next;
            };
            if let Some(ai) = self.ai.get_mut(&guid) {
                match &mut ai.script {
                    Some(CreatureScriptAi::Veklor(s)) => apply(&mut s.base),
                    Some(CreatureScriptAi::Veknilash(s)) => apply(&mut s.base),
                    _ => {}
                }
            }
        } else {
            let dec = |base: &mut TwinsBase| {
                base.bug_mutation_timer_ms -= diff_ms;
            };
            if let Some(ai) = self.ai.get_mut(&guid) {
                match &mut ai.script {
                    Some(CreatureScriptAi::Veklor(s)) => dec(&mut s.base),
                    Some(CreatureScriptAi::Veknilash(s)) => dec(&mut s.base),
                    _ => {}
                }
            }
        }
    }

    /// `boss_twinemperorsAI::CheckEnrage` (cpp 550-566).
    fn twins_check_enrage(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let frozen = self.ai.get(&guid).is_some_and(|ai| match &ai.script {
            Some(CreatureScriptAi::Veklor(s)) => s.base.just_teleported,
            Some(CreatureScriptAi::Veknilash(s)) => s.base.just_teleported,
            _ => false,
        });
        let timer = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Veklor(s)) => Some(s.base.enrage_timer_ms),
                Some(CreatureScriptAi::Veknilash(s)) => Some(s.base.enrage_timer_ms),
                _ => None,
            })
            .unwrap_or(0);
        // NEEDS-MAP-HELPER: `!HasAura(SPELL_BERSERK)` gate (cpp 552).
        if timer < diff_ms {
            if frozen {
                return;
            }
            self.aq_triggered_cast(guid, TWINS_SPELL_BERSERK, CastTarget::SelfCast);
            let apply = |base: &mut TwinsBase| {
                base.enrage_timer_ms = 300_000;
            };
            if let Some(ai) = self.ai.get_mut(&guid) {
                match &mut ai.script {
                    Some(CreatureScriptAi::Veklor(s)) => apply(&mut s.base),
                    Some(CreatureScriptAi::Veknilash(s)) => apply(&mut s.base),
                    _ => {}
                }
            }
        } else {
            let dec = |base: &mut TwinsBase| {
                base.enrage_timer_ms -= diff_ms;
            };
            if let Some(ai) = self.ai.get_mut(&guid) {
                match &mut ai.script {
                    Some(CreatureScriptAi::Veklor(s)) => dec(&mut s.base),
                    Some(CreatureScriptAi::Veknilash(s)) => dec(&mut s.base),
                    _ => {}
                }
            }
        }
    }

    /// `boss_twinemperorsAI::GetPlayerInP2PRange` (cpp 571-601): center-distance
    /// player pick on the threat list, optionally skipping top aggro.
    fn twins_player_in_p2p_range(
        &mut self,
        guid: ObjectGuid,
        min: f32,
        max: f32,
        skip_top_aggro: bool,
    ) -> Option<ObjectGuid> {
        let mut list = self.threat_targets_sorted(guid);
        if list.len() > 1 && skip_top_aggro {
            list.remove(0);
        }
        let me = self.unit_position(guid).unwrap_or_default();
        let mut pool: Vec<ObjectGuid> = Vec::new();
        for t in list {
            if !self.players.contains_key(&t) {
                continue;
            }
            // NEEDS-MAP-HELPER: `IsInRange` center-distance semantics
            // (cpp 592); 2D approximation:
            let ok = match self.unit_position(t) {
                Some(p) => {
                    let dx = p.x - me.x;
                    let dy = p.y - me.y;
                    let d = (dx * dx + dy * dy).sqrt();
                    d >= min && d <= max
                }
                None => false,
            };
            if ok {
                pool.push(t);
            }
        }
        if pool.is_empty() {
            return None;
        }
        let idx = self.rng.urand(0, pool.len() as u32 - 1) as usize;
        pool.get(idx).copied()
    }

    /// Shared `UpdateAI` skeleton (cpp 377-458); `UpdateEmperor` is per twin.
    /// Returns `(run_shared, victim)`: `run_shared` false stops the whole
    /// tick (evade/death/no-victim outside the teleport freeze, cpp 384-437).
    fn twins_update_shared(
        &mut self,
        guid: ObjectGuid,
        diff_ms: u32,
    ) -> (bool, Option<ObjectGuid>) {
        // Evade above the throne room (cpp 384-392).
        let z = self.unit_position(guid).map_or(-100.0, |p| p.z);
        if z > -95.0 {
            if let Some(other) = self.twins_other_boss(guid) {
                self.enter_evade_mode(other);
            }
            self.enter_evade_mode(guid);
            return (false, None);
        }
        if !self.unit_is_alive(guid) {
            return (false, None);
        }
        let teleported = self.ai.get(&guid).is_some_and(|ai| match &ai.script {
            Some(CreatureScriptAi::Veklor(s)) => s.base.just_teleported,
            Some(CreatureScriptAi::Veknilash(s)) => s.base.just_teleported,
            _ => false,
        });
        if teleported {
            // First post-TP tick selects the nearest player (cpp 405-419).
            // NEEDS-MAP-HELPER: `GetNearestVictimInRange(0, 300)`; random
            // hostile approximation + 3000 threat:
            let has = self.ai.get(&guid).is_some_and(|ai| match &ai.script {
                Some(CreatureScriptAi::Veklor(s)) => !s.base.closest_target_after_tp.is_empty(),
                Some(CreatureScriptAi::Veknilash(s)) => !s.base.closest_target_after_tp.is_empty(),
                _ => true,
            });
            if !has {
                self.set_in_combat_with_zone(guid);
                if let Some(closest) = self.select_random_hostile(guid) {
                    self.add_threat(guid, closest, TWINS_AFTER_TELEPORT_THREAT);
                    let apply = |base: &mut TwinsBase| {
                        base.closest_target_after_tp = closest;
                    };
                    if let Some(ai) = self.ai.get_mut(&guid) {
                        match &mut ai.script {
                            Some(CreatureScriptAi::Veklor(s)) => apply(&mut s.base),
                            Some(CreatureScriptAi::Veknilash(s)) => apply(&mut s.base),
                            _ => {}
                        }
                    }
                }
            }
            let timer = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::Veklor(s)) => Some(s.base.just_teleported_timer_ms),
                    Some(CreatureScriptAi::Veknilash(s)) => Some(s.base.just_teleported_timer_ms),
                    _ => None,
                })
                .unwrap_or(0);
            if timer <= diff_ms {
                self.twins_on_end_teleport(guid);
            } else {
                let dec = |base: &mut TwinsBase| {
                    base.just_teleported_timer_ms -= diff_ms;
                };
                if let Some(ai) = self.ai.get_mut(&guid) {
                    match &mut ai.script {
                        Some(CreatureScriptAi::Veklor(s)) => dec(&mut s.base),
                        Some(CreatureScriptAi::Veknilash(s)) => dec(&mut s.base),
                        _ => {}
                    }
                }
            }
        } else {
            let Some(victim) = self.script_combat_drive(guid, true) else {
                return (false, None);
            };
            // Kill-say cooldown (fork plain `-=`, cpp 439-443).
            let apply_cd = |base: &mut TwinsBase| {
                base.kill_say_cooldown_ms = base.kill_say_cooldown_ms.saturating_sub(diff_ms);
            };
            if let Some(ai) = self.ai.get_mut(&guid) {
                match &mut ai.script {
                    Some(CreatureScriptAi::Veklor(s)) => apply_cd(&mut s.base),
                    Some(CreatureScriptAi::Veknilash(s)) => apply_cd(&mut s.base),
                    _ => {}
                }
            }
            self.twins_check_enrage(guid, diff_ms);
            return (true, Some(victim));
        }
        // TP-stunned ticks still run enrage/bug/heal (cpp 447-450) but skip
        // the emperor spells (caller gates on `!justTeleported`).
        self.twins_check_enrage(guid, diff_ms);
        let apply_cd = |base: &mut TwinsBase| {
            base.kill_say_cooldown_ms = base.kill_say_cooldown_ms.saturating_sub(diff_ms);
        };
        if let Some(ai) = self.ai.get_mut(&guid) {
            match &mut ai.script {
                Some(CreatureScriptAi::Veklor(s)) => apply_cd(&mut s.base),
                Some(CreatureScriptAi::Veknilash(s)) => apply_cd(&mut s.base),
                _ => {}
            }
        }
        (true, self.unit_victim(guid))
    }

    /// `boss_veklorAI::UpdateTeleportToMyBrother` (cpp 693-724; fork `>=`).
    fn veklor_update_teleport(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let timer = self
            .veklor_state_mut(guid)
            .map_or(0, |s| s.teleport_timer_ms);
        if timer >= diff_ms {
            if let Some(s) = self.veklor_state_mut(guid) {
                s.teleport_timer_ms -= diff_ms;
            }
            return;
        }
        let next = self
            .rng
            .urand(TWINS_TELEPORTTIME_MIN_MS, TWINS_TELEPORTTIME_MAX_MS);
        if let Some(s) = self.veklor_state_mut(guid) {
            s.teleport_timer_ms = next;
        }
        let Some(other) = self.twins_other_boss(guid) else {
            return;
        };
        let (ox, oy, oz, oo) = self
            .unit_position(other)
            .map_or((0.0, 0.0, 0.0, 0.0), |p| (p.x, p.y, p.z, p.o));
        let (mx, my, mz, _) = self
            .unit_position(guid)
            .map_or((0.0, 0.0, 0.0, 0.0), |p| (p.x, p.y, p.z, p.o));
        // Fork swaps positions keeping each facing (cpp 719-723).
        self.twins_on_start_teleport(
            guid,
            ox,
            oy,
            oz,
            self.unit_position(guid).map_or(0.0, |p| p.o),
        );
        self.twins_on_start_teleport(other, mx, my, mz, oo);
    }

    /// `boss_veklorAI::TryHealBrother` (cpp 726-757).
    fn veklor_try_heal_brother(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let frozen = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Veklor(s)) if s.base.just_teleported),
        );
        if frozen {
            if let Some(s) = self.veklor_state_mut(guid) {
                s.heal_timer_ms = s.heal_timer_ms.saturating_sub(diff_ms);
            }
            return;
        }
        let timer = self.veklor_state_mut(guid).map_or(0, |s| s.heal_timer_ms);
        if timer < diff_ms {
            if let Some(other) = self.twins_other_boss(guid) {
                let close = match (self.unit_position(guid), self.unit_position(other)) {
                    (Some(a), Some(b)) => {
                        let dx = a.x - b.x;
                        let dy = a.y - b.y;
                        dx * dx + dy * dy <= TWINS_HEAL_BROTHER_RANGE * TWINS_HEAL_BROTHER_RANGE
                    }
                    _ => false,
                };
                if self.unit_is_alive(other) && close {
                    if self.do_cast_spell_if_can(
                        guid,
                        TWINS_SPELL_HEAL_BROTHER,
                        CastTarget::Unit(other),
                    ) {
                        self.aq_triggered_cast(
                            other,
                            TWINS_SPELL_HEAL_BROTHER,
                            CastTarget::Unit(guid),
                        );
                        if let Some(s) = self.veklor_state_mut(guid) {
                            s.heal_timer_ms = 1500;
                        }
                    }
                } else if let Some(s) = self.veklor_state_mut(guid) {
                    s.heal_timer_ms = 0;
                }
            } else if let Some(s) = self.veklor_state_mut(guid) {
                s.heal_timer_ms = 0;
            }
        } else if let Some(s) = self.veklor_state_mut(guid) {
            s.heal_timer_ms -= diff_ms;
        }
    }

    /// `boss_veklorAI::UpdateBlizzard` (cpp 768-784).
    fn veklor_update_blizzard(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let range = self
            .veklor_state_mut(guid)
            .map_or(45.0, |s| s.blizzard_range);
        let timer = self
            .veklor_state_mut(guid)
            .map_or(0, |s| s.blizzard_timer_ms);
        if timer < diff_ms {
            if let Some(p) = self.twins_player_in_p2p_range(guid, 0.0, range, true) {
                if self.do_cast_spell_if_can(guid, TWINS_SPELL_BLIZZARD, CastTarget::Unit(p)) {
                    let next = self.rng.urand(TWINS_BLIZZARD_MIN_MS, TWINS_BLIZZARD_MAX_MS);
                    if let Some(s) = self.veklor_state_mut(guid) {
                        s.blizzard_timer_ms = next;
                    }
                }
            }
        } else if let Some(s) = self.veklor_state_mut(guid) {
            s.blizzard_timer_ms -= diff_ms;
        }
    }

    /// `boss_veklorAI::updateArcaneBurst` (cpp 786-800).
    fn veklor_update_arcane_burst(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let timer = self
            .veklor_state_mut(guid)
            .map_or(0, |s| s.arcane_burst_timer_ms);
        if timer < diff_ms {
            if let Some(p) =
                self.twins_player_in_p2p_range(guid, 0.0, TWINS_ARCANE_BURST_RANGE, false)
            {
                if self.do_cast_spell_if_can(guid, TWINS_SPELL_ARCANEBURST, CastTarget::Unit(p)) {
                    let next = self
                        .rng
                        .urand(TWINS_ARCANE_BURST_MIN_MS, TWINS_ARCANE_BURST_MAX_MS);
                    if let Some(s) = self.veklor_state_mut(guid) {
                        s.arcane_burst_timer_ms = next;
                    }
                }
            }
        } else if let Some(s) = self.veklor_state_mut(guid) {
            s.arcane_burst_timer_ms -= diff_ms;
        }
    }

    /// `boss_veklorAI::UpdateAI` emperor part (cpp 802-879).
    fn veklor_update_emperor(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Pull yell (fork `<`, cpp 808).
        let pulled = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::Veklor(s)) if s.base.did_pull_dialogue)
        });
        if !pulled {
            let timer = self
                .veklor_state_mut(guid)
                .map_or(0, |s| s.pull_dialogue_timer_ms);
            if timer < diff_ms {
                if let Some(s) = self.veklor_state_mut(guid) {
                    s.base.did_pull_dialogue = true;
                }
                match self.spell_rng().irand(0, 1) {
                    0 => self.do_script_text(TWINS_SAY_VEKLOR_AGGRO_1, guid, None, -1),
                    _ => self.do_script_text(TWINS_SAY_VEKLOR_AGGRO_2, guid, None, -1),
                }
            } else if let Some(s) = self.veklor_state_mut(guid) {
                s.pull_dialogue_timer_ms -= diff_ms;
            }
        }
        self.veklor_update_blizzard(guid, diff_ms);
        self.veklor_update_arcane_burst(guid, diff_ms);
        let Some(victim) = self.unit_victim(guid) else {
            return;
        };
        // NEEDS-MAP-HELPER: `IsWithinLOSInMap` + `IsMoving` + stand-state
        // churn (cpp 827/844/846); melee reach itself:
        let is_melee = self.can_reach_melee(guid, victim);
        let since = self
            .veklor_state_mut(guid)
            .map_or(0, |s| s.time_since_last_sb_ms);
        if !is_melee && since > TWINS_SHADOWBOLT_RANGED_MAX_MS {
            if let Some(s) = self.veklor_state_mut(guid) {
                s.shadowbolt_timer_ms = 0;
            }
        }
        if is_melee && self.bot_casting_spell(guid).is_none() {
            // Fork melees then waits a tick (cpp 840-843); swings global.
            if let Some(s) = self.veklor_state_mut(guid) {
                s.shadowbolt_timer_ms = s.shadowbolt_timer_ms.saturating_sub(diff_ms);
            }
        } else {
            let timer = self
                .veklor_state_mut(guid)
                .map_or(0, |s| s.shadowbolt_timer_ms);
            if timer < diff_ms {
                if self.do_cast_spell_if_can(guid, TWINS_SPELL_SHADOWBOLT, CastTarget::Unit(victim))
                {
                    let next = if is_melee {
                        self.rng
                            .urand(TWINS_SHADOWBOLT_MELEE_MIN_MS, TWINS_SHADOWBOLT_MELEE_MAX_MS)
                    } else {
                        self.rng.urand(
                            TWINS_SHADOWBOLT_RANGED_MIN_MS,
                            TWINS_SHADOWBOLT_RANGED_MAX_MS,
                        )
                    };
                    if let Some(s) = self.veklor_state_mut(guid) {
                        s.shadowbolt_timer_ms = next;
                        s.time_since_last_sb_ms = 0;
                    }
                }
            } else if let Some(s) = self.veklor_state_mut(guid) {
                s.shadowbolt_timer_ms -= diff_ms;
            }
        }
        if let Some(s) = self.veklor_state_mut(guid) {
            s.time_since_last_sb_ms += diff_ms;
        }
    }

    /// `boss_veklorAI::UpdateAI` (cpp 377-458 + 802-879).
    fn veklor_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let (run_shared, victim) = self.twins_update_shared(guid, diff_ms);
        if !run_shared {
            return;
        }
        self.veklor_update_teleport(guid, diff_ms);
        self.twins_handle_bug_spell(
            guid,
            diff_ms,
            TWINS_SPELL_EXPLODEBUG,
            (TWINS_EXPLODE_BUG_MIN_MS, TWINS_EXPLODE_BUG_MAX_MS),
        );
        self.veklor_try_heal_brother(guid, diff_ms);
        let frozen = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Veklor(s)) if s.base.just_teleported),
        );
        if !frozen && victim.is_some() {
            self.veklor_update_emperor(guid, diff_ms);
        }
    }

    /// `boss_veknilashAI::GetPlayerInMeleeRange` (cpp 924-950; fork picks the
    /// LAST melee candidate).
    fn veknilash_player_in_melee_range(&mut self, guid: ObjectGuid) -> Option<ObjectGuid> {
        let mut last: Option<ObjectGuid> = None;
        for t in self.threat_targets_sorted(guid) {
            if self.can_reach_melee(guid, t) {
                last = Some(t);
            }
        }
        last
    }

    /// `boss_veknilashAI::UpdateEmperor` (cpp 952-993).
    fn veknilash_update_emperor(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let pulled = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::Veknilash(s)) if s.base.did_pull_dialogue)
        });
        if !pulled {
            if let Some(s) = self.veknilash_state_mut(guid) {
                s.base.did_pull_dialogue = true;
            }
            match self.spell_rng().irand(0, 3) {
                0 => self.do_script_text(TWINS_SAY_VEKNILASH_AGGRO_1, guid, None, -1),
                1 => self.do_script_text(TWINS_SAY_VEKNILASH_AGGRO_2, guid, None, -1),
                2 => self.do_script_text(TWINS_SAY_VEKNILASH_AGGRO_3, guid, None, -1),
                _ => self.do_script_text(TWINS_SAY_VEKNILASH_AGGRO_4, guid, None, -1),
            }
        }
        // NEEDS-MAP-HELPER: `HasAura(DOUBLE_ATTACK)` gate (cpp 961); upkeep
        // cast itself (re-cast each tick would spam — gate missing):
        // skipped until the aura check lands (see unresolved).
        let due = {
            let Some(s) = self.veknilash_state_mut(guid) else {
                return;
            };
            if s.unbalancing_strike_timer_ms < diff_ms {
                true
            } else {
                s.unbalancing_strike_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            let next_unbalancing_ms = self
                .rng
                .urand(TWINS_UNBALANCING_MIN_MS, TWINS_UNBALANCING_MAX_MS);
            let victim = self.unit_victim(guid);
            if let Some(v) = victim
                && self.do_cast_spell_if_can(
                    guid,
                    TWINS_SPELL_UNBALANCING_STRIKE,
                    CastTarget::Unit(v),
                )
                && let Some(s) = self.veknilash_state_mut(guid)
            {
                s.unbalancing_strike_timer_ms = next_unbalancing_ms;
            }
        }
        let due = {
            let Some(s) = self.veknilash_state_mut(guid) else {
                return;
            };
            if s.uppercut_timer_ms < diff_ms {
                true
            } else {
                s.uppercut_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            let next_uppercut_ms = self.rng.urand(TWINS_UPPERCUT_MIN_MS, TWINS_UPPERCUT_MAX_MS);
            if let Some(melee) = self.veknilash_player_in_melee_range(guid) {
                if self.do_cast_spell_if_can(guid, TWINS_SPELL_UPPERCUT, CastTarget::Unit(melee))
                    && let Some(s) = self.veknilash_state_mut(guid)
                {
                    s.uppercut_timer_ms = next_uppercut_ms;
                }
            }
        }
    }

    /// `boss_veknilashAI::UpdateAI` (cpp 377-458 + 952-993).
    fn veknilash_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let (run_shared, victim) = self.twins_update_shared(guid, diff_ms);
        if !run_shared {
            return;
        }
        // Vek'nilash has no teleport/heal arm (`UpdateTeleportToMyBrother` /
        // `TryHealBrother` base no-ops, cpp 210-211).
        self.twins_handle_bug_spell(
            guid,
            diff_ms,
            TWINS_SPELL_MUTATE_BUG,
            (TWINS_MUTATE_BUG_MIN_MS, TWINS_MUTATE_BUG_MAX_MS),
        );
        let frozen = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::Veknilash(s)) if s.base.just_teleported)
        });
        if !frozen && victim.is_some() {
            self.veknilash_update_emperor(guid, diff_ms);
        }
    }

