    /// `cthunAI::SpawnTentacleIfReady` (cpp 1806-1833).
    fn cthun_spawn_tentacle_if_ready(
        &mut self,
        guid: ObjectGuid,
        timer_ms: u32,
        reset_ms: u32,
        entry: u32,
        diff_ms: u32,
    ) -> u32 {
        if timer_ms < diff_ms {
            // `SelectRandomAliveNotStomach`: stomach exclusion unmodeled.
            if let Some(target) = self.select_random_hostile(guid) {
                // NEEDS-MAP-HELPER: `GetRandomPoint(0.5)` (cpp 1819);
                // on-target approximation:
                let pos = self.unit_position(target).unwrap_or_default();
                if let Some(created) = self.summon_creature(
                    entry,
                    Position::new(pos.x, pos.y, pos.z, 0.0),
                    guid,
                    CTHUN_TEMPSUMMON_CORPSE_TIMED,
                    1500,
                ) {
                    self.set_in_combat_with_zone(created);
                    self.attack_start(created, target);
                }
                return reset_ms;
            }
        } else {
            return timer_ms - diff_ms;
        }
        timer_ms
    }

