    /// `cthunAI::UpdateTentaclesP1` (cpp 1625-1639).
    fn cthun_update_tentacles_p1(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let claw = self
            .cthun_state_mut(guid)
            .map_or(0, |s| s.claw_tentacle_timer_p1_ms);
        let claw = self.cthun_spawn_tentacle_if_ready(
            guid,
            claw,
            CTHUN_P1_CLAW_RESPAWN_MS,
            CTHUN_MOB_CLAW_TENTACLE,
            diff_ms,
        );
        if let Some(s) = self.cthun_state_mut(guid) {
            s.claw_tentacle_timer_p1_ms = claw;
        }
        let eye = self
            .cthun_state_mut(guid)
            .map_or(0, |s| s.eye_tentacle_timer_p1_ms);
        if eye < diff_ms {
            self.cthun_spawn_eye_tentacles(guid);
            if let Some(s) = self.cthun_state_mut(guid) {
                s.eye_tentacle_timer_p1_ms = CTHUN_P1_EYE_RESPAWN_MS;
            }
        } else if let Some(s) = self.cthun_state_mut(guid) {
            s.eye_tentacle_timer_p1_ms -= diff_ms;
        }
    }

