    /// `cthunAI::UpdateStomachGrab` (cpp 1723-1762).
    fn cthun_update_stomach_grab(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let target = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Cthun(s)) => Some(s.stomach_target),
                _ => None,
            })
            .unwrap_or(ObjectGuid::EMPTY);
        if !target.is_empty() {
            let timer = self
                .cthun_state_mut(guid)
                .map_or(0, |s| s.stomach_port_timer_ms);
            if timer < diff_ms {
                // NEEDS-MAP-HELPER: `DoTeleportPlayer` to the stomach + aura
                // strip + `AddPlayerToStomach` (cpp 1732-1735, instance-owned).
                if let Some(s) = self.cthun_state_mut(guid) {
                    s.stomach_target = ObjectGuid::EMPTY;
                    s.stomach_port_timer_ms = 0;
                }
            } else if let Some(s) = self.cthun_state_mut(guid) {
                s.stomach_port_timer_ms -= diff_ms;
            }
        }
        let grab = self
            .cthun_state_mut(guid)
            .map_or(0, |s| s.next_stomach_grab_timer_ms);
        if grab < diff_ms {
            // `SelectRandomAliveNotStomach`: stomach exclusion unmodeled.
            if let Some(target) = self.select_random_hostile(guid) {
                // NEEDS-MAP-HELPER: victim `InterruptNonMeleeSpells` +
                // victim-cast MOUTH_TENTACLE channeled by the body (cpp 1751-1752).
                if let Some(s) = self.cthun_state_mut(guid) {
                    s.stomach_port_timer_ms = CTHUN_STOMACH_GRAB_DURATION_MS;
                    s.stomach_target = target;
                }
            }
            if let Some(s) = self.cthun_state_mut(guid) {
                s.next_stomach_grab_timer_ms = CTHUN_STOMACH_GRAB_CD_MS;
            }
        } else if let Some(s) = self.cthun_state_mut(guid) {
            s.next_stomach_grab_timer_ms -= diff_ms;
        }
    }

    /// `cthunAI::UpdateTransitionPhase` (cpp 1641-1657).
    fn cthun_update_transition_phase(&mut self, guid: ObjectGuid, diff_ms: u32) {
        self.cthun_update_tentacles_p2(guid, diff_ms);
        self.cthun_update_stomach_grab(guid, diff_ms);
        let emerge = self.cthun_state_mut(guid).map_or(0, |s| s.emerge_timer_ms);
        if emerge < diff_ms {
            // NEEDS-MAP-HELPER: `RemoveFlag(UNIT_FIELD_FLAGS, SPAWNING)`
            // (cpp 1648).
            self.set_in_combat_with_zone(guid);
            if let Some(s) = self.cthun_state_mut(guid) {
                s.phase = CTHUN_PHASE_INVULNERABLE;
            }
        } else if let Some(s) = self.cthun_state_mut(guid) {
            s.emerge_timer_ms -= diff_ms;
        }
    }

    /// `cthunAI::UpdateInvulnerablePhase` (cpp 1659-1689).
    fn cthun_update_invulnerable_phase(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let empty = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::Cthun(s)) if s.flesh_tentacles.is_empty())
        });
        if empty {
            if let Some(s) = self.cthun_state_mut(guid) {
                s.weakness_timer_ms = CTHUN_WEAKNESS_DURATION_MS;
            }
            self.do_script_text(CTHUN_EMOTE_WEAKENED, guid, None, -1);
            // Grabbed-player release (cpp 1668-1674).
            let target = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::Cthun(s)) => Some(s.stomach_target),
                    _ => None,
                })
                .unwrap_or(ObjectGuid::EMPTY);
            if !target.is_empty() {
                self.remove_auras_due_to_spell(target, CTHUN_SPELL_MOUTH_TENTACLE);
            }
            self.aq_triggered_cast(guid, CTHUN_SPELL_VULNERABLE, CastTarget::SelfCast);
            self.remove_auras_due_to_spell(guid, CTHUN_SPELL_CARAPACE);
            if let Some(s) = self.cthun_state_mut(guid) {
                s.phase = CTHUN_PHASE_WEAKENED;
            }
        } else {
            self.cthun_update_tentacles_p2(guid, diff_ms);
            self.cthun_update_stomach_grab(guid, diff_ms);
        }
    }

    /// `cthunAI::UpdateWeakenedPhase` (cpp 1691-1707).
    fn cthun_update_weakened_phase(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let weakness = self
            .cthun_state_mut(guid)
            .map_or(0, |s| s.weakness_timer_ms);
        if weakness < diff_ms {
            self.cthun_restart_unvulnerable_phase(guid, true);
            self.remove_auras_due_to_spell(guid, CTHUN_SPELL_VULNERABLE);
            if let Some(s) = self.cthun_state_mut(guid) {
                s.phase = CTHUN_PHASE_INVULNERABLE;
            }
        } else if let Some(s) = self.cthun_state_mut(guid) {
            s.weakness_timer_ms -= diff_ms;
        }
    }

    /// `cthunAI::UpdateAI` (cpp 1430-1519;
    /// `USE_POSTFIX_PRENERF_PULL_LOGIC` defined).
    #[allow(clippy::match_same_arms)]
    fn cthun_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if !self.unit_is_alive(guid) {
            return;
        }
        // Wipe eye-respawn delay (fork mixed saturating/plain dec, cpp 1436-1444).
        let wipe = self
            .cthun_state_mut(guid)
            .map_or(0, |s| s.wipe_respawn_eye_timer_ms);
        if wipe != 0 {
            let dec = wipe.saturating_sub(diff_ms);
            if let Some(s) = self.cthun_state_mut(guid) {
                s.wipe_respawn_eye_timer_ms = dec;
            }
            if dec < diff_ms {
                self.cthun_check_respawn_eye(guid);
                if let Some(s) = self.cthun_state_mut(guid) {
                    s.wipe_respawn_eye_timer_ms = 0;
                }
            }
        }
        let in_progress = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Cthun(s)) if s.in_progress),
        );
        if in_progress {
            // NEEDS-MAP-HELPER: `GetPlayerInMap(true, false)` wipe check
            // (cpp 1459).
        } else {
            // NEEDS-MAP-HELPER: `wipeRespawnEyeTimer` gate read (cpp 1449);
            // pull itself:
            if self.cthun_aggro_radius(guid) {
                if let Some(s) = self.cthun_state_mut(guid) {
                    s.in_progress = true;
                }
            } else {
                return;
            }
        }
        // Delayed zone-combat entry (cpp 1468-1483; fork `<`).
        let zoned = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Cthun(s)) if s.in_combat_with_zone),
        );
        if !zoned {
            let timer = self
                .cthun_state_mut(guid)
                .map_or(0, |s| s.delayed_combat_timer_ms);
            if timer < diff_ms {
                if let Some(s) = self.cthun_state_mut(guid) {
                    s.in_combat_with_zone = true;
                }
                self.set_in_combat_with_zone(guid);
                let eye = self
                    .ai
                    .get(&guid)
                    .and_then(|ai| match &ai.script {
                        Some(CreatureScriptAi::Cthun(s)) => Some(s.eye_guid),
                        _ => None,
                    })
                    .unwrap_or(ObjectGuid::EMPTY);
                if !eye.is_empty() {
                    self.set_in_combat_with_zone(eye);
                }
            } else if let Some(s) = self.cthun_state_mut(guid) {
                s.delayed_combat_timer_ms -= diff_ms;
            }
        }
        // NEEDS-MAP-HELPER: `SetTargetGuid(0)` (cpp 1486).
        let phase = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Cthun(s)) => Some(s.phase),
                _ => None,
            })
            .unwrap_or(CTHUN_PHASE_EYE_NORMAL);
        match phase {
            CTHUN_PHASE_EYE_NORMAL | CTHUN_PHASE_EYE_DARK_GLARE => {
                self.cthun_update_tentacles_p1(guid, diff_ms);
            }
            CTHUN_PHASE_PRE_TRANSITION => {}
            CTHUN_PHASE_TRANSITION => {
                self.cthun_update_transition_phase(guid, diff_ms);
            }
            CTHUN_PHASE_INVULNERABLE => {
                self.cthun_update_invulnerable_phase(guid, diff_ms);
                self.cthun_check_if_all_dead(guid);
            }
            CTHUN_PHASE_WEAKENED => {
                self.cthun_update_weakened_phase(guid, diff_ms);
                self.cthun_check_if_all_dead(guid);
            }
            _ => {}
        }
    }

