    /// `AI_QirajiMindslayer::JustDied` (cpp 821-850).
    fn qiraji_mindslayer_just_died(&mut self, guid: ObjectGuid) {
        // Closest live player, any distance (cpp 827-845).
        let me = self.unit_position(guid).unwrap_or_default();
        let mut best: Option<(ObjectGuid, f32)> = None;
        let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
        for p in players {
            if !self.unit_is_alive(p) {
                continue;
            }
            if let Some(pp) = self.unit_position(p) {
                let dx = pp.x - me.x;
                let dy = pp.y - me.y;
                let dz = pp.z - me.z;
                let d = dx * dx + dy * dy + dz * dz;
                if best.is_none_or(|(_, bd)| d < bd) {
                    best = Some((p, d));
                }
            }
        }
        // Fork `CF_TRIGGERED | CF_INTERRUPT_PREVIOUS` (cpp 848): triggered
        // shape, interrupt-previous unmodeled.
        if let Some((closest, _)) = best {
            self.aq_triggered_cast(guid, MINDSLAYER_SPELL_MANABURN, CastTarget::Unit(closest));
        }
    }

    /// `AI_QirajiMindslayer::UpdateAI` (cpp 852-906).
    fn qiraji_mindslayer_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Fork skips the hostile-target check while channeling (cpp 854-858).
        if self.bot_casting_spell(guid).is_none() {
            let Some(_victim) = self.script_combat_drive(guid, true) else {
                return;
            };
        }
        // Mind Flay (random, spell 26044 + PLAYER + LOS: filters unmodeled).
        let due = {
            let Some(s) = self.qiraji_mindslayer_state_mut(guid) else {
                return;
            };
            if s.mind_flay_timer_ms < diff_ms {
                true
            } else {
                s.mind_flay_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            if let Some(target) = self.select_random_hostile(guid) {
                if self.do_cast_spell_if_can(
                    guid,
                    MINDSLAYER_SPELL_MIND_FLAY,
                    CastTarget::Unit(target),
                ) {
                    let next = self.rng.urand(12_000, 15_000);
                    if let Some(s) = self.qiraji_mindslayer_state_mut(guid) {
                        s.mind_flay_timer_ms = next;
                    }
                }
            }
        }
        // Mind Blast (top aggro, spell 26048 + PLAYER + LOS: filters unmodeled).
        let due = {
            let Some(s) = self.qiraji_mindslayer_state_mut(guid) else {
                return;
            };
            if s.mind_blast_timer_ms < diff_ms {
                true
            } else {
                s.mind_blast_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            if let Some(target) = self.select_attacking_target(guid, 1, 0, 0) {
                if self.do_cast_spell_if_can(
                    guid,
                    MINDSLAYER_SPELL_MIND_BLAST,
                    CastTarget::Unit(target),
                ) {
                    let next = self.rng.urand(9000, 12_000);
                    if let Some(s) = self.qiraji_mindslayer_state_mut(guid) {
                        s.mind_blast_timer_ms = next;
                    }
                }
            }
        }
        // Insanity (random, spell 26079 + PLAYER + LOS: filters unmodeled).
        let due = {
            let Some(s) = self.qiraji_mindslayer_state_mut(guid) else {
                return;
            };
            if s.insanity_timer_ms < diff_ms {
                true
            } else {
                s.insanity_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            if let Some(target) = self.select_random_hostile(guid) {
                if self.do_cast_spell_if_can(
                    guid,
                    MINDSLAYER_SPELL_INSANITY,
                    CastTarget::Unit(target),
                ) {
                    if let Some(s) = self.qiraji_mindslayer_state_mut(guid) {
                        s.insanity_timer_ms = 10_000;
                    }
                }
            }
        }
    }
