    /// `boss_chorushAI::Reset` (cpp 176-202). The equipment set comes from
    /// the instance (`dm_chorush_equipment`, cpp 181-182).
    fn chorush_reset(&mut self, guid: ObjectGuid) {
        let equipment = self.dm_chorush_equipment();
        let mut rolls = [0u32; CHORUSH_MAX_SPELLS];
        for roll in &mut rolls {
            *roll = self.rng.urand(1000, 2000);
        }
        if let Some(s) = self.chorush_state_mut(guid) {
            s.link_check_timer_ms = 2500;
            s.equipment = equipment;
            s.in_melee = true;
            s.spell_timers_ms = rolls;
        }
        let equip_id = match equipment {
            CHORUSH_SET_MAGE => CHORUSH_EQUIPMENT_MAGE,
            CHORUSH_SET_SHAMAN => CHORUSH_EQUIPMENT_SHAMAN,
            CHORUSH_SET_PRIEST => CHORUSH_EQUIPMENT_PRIEST,
            _ => return,
        };
        self.creature_load_equipment(guid, equip_id);
        if let Some(ai) = self.ai.get_mut(&guid) {
            ai.combat_movement = true;
        }
    }

    /// `boss_chorushAI::UpdateAI` (cpp 208-243). The link check is
    /// statically enabled (patch 1.12 `>= WOW_PATCH_109`, cpp 173).
    fn chorush_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let equipment = self.chorush_state_mut(guid).map_or(0, |s| s.equipment);
        match equipment {
            CHORUSH_SET_MAGE => self.chorush_update_mage(guid, victim, diff_ms),
            CHORUSH_SET_SHAMAN => self.chorush_update_shaman(guid, victim, diff_ms),
            CHORUSH_SET_PRIEST => self.chorush_update_prist(guid, victim, diff_ms),
            _ => {}
        }
        // Observer/King link (cpp 231-241).
        let link_due = {
            let Some(s) = self.chorush_state_mut(guid) else {
                return;
            };
            if s.link_check_timer_ms < diff_ms {
                true
            } else {
                s.link_check_timer_ms -= diff_ms;
                false
            }
        };
        if link_due {
            if let Some(king) = self.dm_get_data64(DM_NPC_KING_GORDOK) {
                if !self.ai_in_combat(king) {
                    self.attack_start(king, victim);
                }
            }
            if let Some(s) = self.chorush_state_mut(guid) {
                s.link_check_timer_ms = 2500;
            }
        }
    }

