    /// Shared melee/range dance (cpp 316-335, 394-413, 475-494).
    /// `IsCombatMovementEnabled` is `ai.combat_movement`; `DoStartMovement`
    /// re-chases, `DoStartNoMovement` stops (facing unmodeled).
    /// NEEDS-MAP-HELPER: the `IsWithinLOSInMap` + `GetPowerPercent(POWER_MANA)`
    /// gates fold out (distance-only below; unresolved).
    fn chorush_melee_dance(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        let in_melee = self.chorush_state_mut(guid).is_some_and(|s| s.in_melee);
        let combat_movement = self.ai.get(&guid).is_some_and(|ai| ai.combat_movement);
        let dist2d = match (self.unit_position(guid), self.unit_position(victim)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                (dx * dx + dy * dy).sqrt()
            }
            _ => 0.0,
        };
        if !combat_movement {
            if !in_melee && (dist2d < 5.0 || dist2d > 30.0) {
                if let Some(ai) = self.ai.get_mut(&guid) {
                    ai.combat_movement = true;
                }
                self.creature_move_chase(guid, victim, 0.0, 0.0);
                if let Some(s) = self.chorush_state_mut(guid) {
                    s.in_melee = true;
                }
            }
        } else if in_melee && (5.0..=30.0).contains(&dist2d) {
            if let Some(ai) = self.ai.get_mut(&guid) {
                ai.combat_movement = false;
            }
            self.stop_moving(guid);
            if let Some(s) = self.chorush_state_mut(guid) {
                s.in_melee = false;
            }
        }
    }

