    /// `boss_tendris_warpwoodAI::Reset` (cpp 73-80).
    fn tendris_warpwood_reset(&mut self, guid: ObjectGuid) {
        let trample = self.rng.urand(5000, 9000);
        let uppercut = self.rng.urand(2000, 4000);
        let vines = self.rng.urand(9000, 12_000);
        if let Some(s) = self.tendris_warpwood_state_mut(guid) {
            s.invocation_timer_ms = 0;
            s.trample_timer_ms = trample;
            s.uppercut_timer_ms = uppercut;
            s.grasping_vines_timer_ms = vines;
            s.aggro_protector = false;
        }
    }

    /// `boss_tendris_warpwoodAI::Aggro` (cpp 52-71). The patch gate
    /// (`>= WOW_PATCH_110`, cpp 58) is statically true on this build.
    fn tendris_warpwood_aggro(&mut self, guid: ObjectGuid, _who: ObjectGuid) {
        let called = self
            .tendris_warpwood_state_mut(guid)
            .is_some_and(|s| s.aggro_protector);
        if called {
            return;
        }
        // Living ironbark protectors join zone-wide (cpp 60-67).
        let me = self.unit_position(guid).unwrap_or_default();
        let mut protectors = Vec::new();
        for (g, c) in &self.creatures {
            if c.info.entry != TENDRIS_NPC_IRONBARK_PROTECTOR {
                continue;
            }
            if let Some(p) = self.object_position(*g) {
                let dx = p.x - me.x;
                let dy = p.y - me.y;
                let dz = p.z - me.z;
                if dx * dx + dy * dy + dz * dz <= 1800.0 * 1800.0 {
                    protectors.push(*g);
                }
            }
        }
        for protector in protectors {
            if self.unit_is_alive(protector) {
                self.set_in_combat_with_zone(protector);
            }
        }
        if let Some(s) = self.tendris_warpwood_state_mut(guid) {
            s.aggro_protector = true;
        }
        self.do_script_text(TENDRIS_SAY_AGGRO, guid, None, -1);
    }

