    /// `boss_tendris_warpwoodAI::UpdateAI` (cpp 89-127). Same `ManageTimer`
    /// fold note as `immol_thar_update`.
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn tendris_warpwood_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        if self.bot_casting_spell(guid).is_some() {
            return;
        }
        // Trample (cpp 94-95).
        let trample_due = {
            let hoist56 = self.rng.urand(9000, 14_000);
            let Some(s) = self.tendris_warpwood_state_mut(guid) else {
                return;
            };
            if s.trample_timer_ms < diff_ms {
                s.trample_timer_ms = hoist56;
                true
            } else {
                s.trample_timer_ms -= diff_ms;
                false
            }
        };
        if trample_due {
            let _ = self.do_cast_spell_if_can(guid, TENDRIS_SPELL_TRAMPLE, CastTarget::SelfCast);
        }
        // Uppercut (cpp 97-98).
        let uppercut_due = {
            let hoist55 = self.rng.urand(12_000, 15_000);
            let Some(s) = self.tendris_warpwood_state_mut(guid) else {
                return;
            };
            if s.uppercut_timer_ms < diff_ms {
                s.uppercut_timer_ms = hoist55;
                true
            } else {
                s.uppercut_timer_ms -= diff_ms;
                false
            }
        };
        if uppercut_due {
            let _ =
                self.do_cast_spell_if_can(guid, TENDRIS_SPELL_UPPERCUT, CastTarget::Unit(victim));
        }
        // Grasping Vines (cpp 100-101).
        let vines_due = {
            let hoist54 = self.rng.urand(17_000, 22_000);
            let Some(s) = self.tendris_warpwood_state_mut(guid) else {
                return;
            };
            if s.grasping_vines_timer_ms < diff_ms {
                s.grasping_vines_timer_ms = hoist54;
                true
            } else {
                s.grasping_vines_timer_ms -= diff_ms;
                false
            }
        };
        if vines_due {
            let _ =
                self.do_cast_spell_if_can(guid, TENDRIS_SPELL_GRASPING_VINES, CastTarget::SelfCast);
        }
        // Enrage below 30% (cpp 103-104): aura-latched triggered cast.
        if self.creature_health_percent(guid) < 30.0
            && !self.unit_has_aura(guid, TENDRIS_SPELL_ENRAGE)
        {
            let _ = self.cast_spell(
                guid,
                TENDRIS_SPELL_ENRAGE,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
        // Victim pull + root (cpp 107-123): only past 7.0, and the timer
        // re-arms only on a pull.
        let invocation_due = {
            let Some(s) = self.tendris_warpwood_state_mut(guid) else {
                return;
            };
            if s.invocation_timer_ms < diff_ms {
                true
            } else {
                s.invocation_timer_ms -= diff_ms;
                false
            }
        };
        if invocation_due {
            let far = match (self.unit_position(guid), self.unit_position(victim)) {
                (Some(a), Some(b)) => crate::visibility::dist3d(a, b) > 7.0,
                _ => false,
            };
            if far {
                let me = self.unit_position(guid).unwrap_or_default();
                let facing = self.object_position(victim).map_or(0.0, |p| p.o);
                let at = Position::new(me.x, me.y, me.z + 1.0, facing);
                self.send_spell_go_simple(guid, TENDRIS_SPELL_GO_VISUAL, victim, 0);
                if victim.is_player() {
                    self.teleport_player_in_map(victim, at);
                } else {
                    self.teleport_creature_in_map(victim, at);
                }
                let hoist53 = self.rng.urand(10_000, 15_000);
                if let Some(s) = self.tendris_warpwood_state_mut(guid) {
                    s.invocation_timer_ms = hoist53;
                }
                let _ = self.do_cast_spell_if_can(
                    guid,
                    TENDRIS_SPELL_ENCHEVETREMENT,
                    CastTarget::Unit(victim),
                );
            }
        }
    }

