    /// `boss_zevrimAI::UpdateAI` (cpp 40-66). Neither spell uses the
    /// victim (self-cast pain, random-target sacrifice).
    fn zevrim_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        if self.bot_casting_spell(guid).is_some() {
            return;
        }
        // Intensive Pain (cpp 45-51): unconditional re-arm.
        let pain_due = {
            let Some(s) = self.zevrim_state_mut(guid) else {
                return;
            };
            if s.intense_pain_timer_ms < diff_ms {
                true
            } else {
                s.intense_pain_timer_ms -= diff_ms;
                false
            }
        };
        if pain_due {
            let _ =
                self.do_cast_spell_if_can(guid, ZEVRIM_SPELL_INTENSIVE_PAIN, CastTarget::SelfCast);
            let hoist52 = self.rng.urand(20_000, 26_000);
            if let Some(s) = self.zevrim_state_mut(guid) {
                s.intense_pain_timer_ms = hoist52;
            }
        }
        // Sacrifice (cpp 53-63): random non-pet target; the timer only
        // re-arms when such a target is picked.
        let sacrifice_due = {
            let Some(s) = self.zevrim_state_mut(guid) else {
                return;
            };
            if s.sacrifice_timer_ms < diff_ms {
                true
            } else {
                s.sacrifice_timer_ms -= diff_ms;
                false
            }
        };
        if sacrifice_due {
            let target = self
                .select_attacking_target(guid, 0, 0, ZEVRIM_SELECT_FLAG_NO_TOTEM)
                .filter(|t| !self.is_pet(*t));
            if let Some(target) = target {
                let _ = self.do_cast_spell_if_can(
                    guid,
                    ZEVRIM_SPELL_SACRIFICE,
                    CastTarget::Unit(target),
                );
                let hoist51 = self.rng.urand(15_000, 18_000);
                if let Some(s) = self.zevrim_state_mut(guid) {
                    s.sacrifice_timer_ms = hoist51;
                }
            }
        }
    }

