    /// `npc_reste_manaAI::UpdateAI` (cpp 595-622). Each due branch returns
    /// early (cpp 607, 616), skipping the later spells that tick.
    fn reste_mana_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        if self.bot_casting_spell(guid).is_some() {
            return;
        }
        // Blink (cpp 603-610): fork casts on the victim, then returns.
        if let Some(s) = self.reste_mana_state_mut(guid) {
            if s.blink_timer_ms < diff_ms {
                let _ =
                    self.do_cast_spell_if_can(guid, RESTE_SPELL_BLINK, CastTarget::Unit(victim));
                if let Some(s) = self.reste_mana_state_mut(guid) {
                    s.blink_timer_ms = 6000;
                }
                return;
            }
            s.blink_timer_ms -= diff_ms;
        } else {
            return;
        }
        // Chain Lightning (cpp 612-619).
        if let Some(s) = self.reste_mana_state_mut(guid) {
            if s.chain_lightning_timer_ms < diff_ms {
                let _ = self.do_cast_spell_if_can(
                    guid,
                    RESTE_SPELL_CHAINLIGHTNING,
                    CastTarget::Unit(victim),
                );
                if let Some(s) = self.reste_mana_state_mut(guid) {
                    s.chain_lightning_timer_ms = 6000;
                }
                return;
            }
            s.chain_lightning_timer_ms -= diff_ms;
        }
    }

