    /// `npc_residual_montruosityAI::UpdateFormationSpeed` (cpp 722-759).
    /// OOC walk-speed shaping against nearby same-entry adds.
    fn residual_montruosity_formation_speed(&mut self, guid: ObjectGuid) {
        let mut newspeed = 1.79;
        if self.unit_victim(guid).is_none() {
            // Distances below are 2D center distances.
            let me = self.unit_position(guid).unwrap_or_default();
            let mut closest_before = 45.0;
            // NEEDS-MAP-HELPER: `closest_behind` needs the `HasInArc`
            // bucket split (cpp 738-747); it reads "far" until then, so
            // only the slow-down arm below can fire.
            let closest_behind = 45.0;
            for (g, c) in &self.creatures {
                if *g == guid || c.info.entry != RESIDUAL_NPC_MONTRUOSITY {
                    continue;
                }
                if let Some(p) = self.object_position(*g) {
                    let dx = p.x - me.x;
                    let dy = p.y - me.y;
                    let distance = (dx * dx + dy * dy).sqrt();
                    if distance < 45.0 && distance < closest_before {
                        closest_before = distance;
                    }
                }
            }
            if closest_before > 36.0 && closest_behind < 32.0 {
                newspeed = 2.20;
            } else if closest_before < 32.0 && closest_behind > 36.0 {
                newspeed = 1.00;
            }
        }
        self.set_speed_rate(guid, mangos_entities::unit::MOVE_WALK, newspeed);
    }

    /// `npc_residual_montruosityAI::UpdateAI` (cpp 761-792). The OOC
    /// formation-speed work runs before the drive (cpp 764-768).
    fn residual_montruosity_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // OOC formation shaping (no victim yet).
        if self.unit_victim(guid).is_none() && self.get_hostile_target(guid).is_none() {
            self.residual_montruosity_formation_speed(guid);
            return;
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        if self.bot_casting_spell(guid).is_some() {
            return;
        }
        // Arcane Bolt (cpp 773-780): due branch returns early.
        if let Some(s) = self.residual_montruosity_state_mut(guid) {
            if s.arcane_bolt_timer_ms < diff_ms {
                let _ = self.do_cast_spell_if_can(
                    guid,
                    RESIDUAL_SPELL_ARCANEBOLT,
                    CastTarget::Unit(victim),
                );
                let hoist43 = self.rng.urand(2400, 3800);
                if let Some(s) = self.residual_montruosity_state_mut(guid) {
                    s.arcane_bolt_timer_ms = hoist43;
                }
                return;
            }
            s.arcane_bolt_timer_ms -= diff_ms;
        } else {
            return;
        }
        // Arcane Blast (cpp 782-789).
        if let Some(s) = self.residual_montruosity_state_mut(guid) {
            if s.arcane_blast_timer_ms < diff_ms {
                let _ = self.do_cast_spell_if_can(
                    guid,
                    RESIDUAL_SPELL_ARCANEBLAST,
                    CastTarget::SelfCast,
                );
                let hoist42 = self.rng.urand(3800, 5200);
                if let Some(s) = self.residual_montruosity_state_mut(guid) {
                    s.arcane_blast_timer_ms = hoist42;
                }
                return;
            }
            s.arcane_blast_timer_ms -= diff_ms;
        }
    }

