    /// `npc_mizzle_the_craftyAI` ctor + `Reset` (cpp 835-847). The fork ctor
    /// walks home and says the first line once at spawn; the fork `Reset`
    /// itself is empty.
    fn mizzle_the_crafty_reset(&mut self, guid: ObjectGuid) {
        let spawned = self
            .mizzle_the_crafty_state_mut(guid)
            .is_some_and(|s| s.spawned);
        if spawned {
            return;
        }
        // `SetHomePosition` (cpp 838): direct field write (BFD precedent).
        if let Some(c) = self.creatures.get_mut(&guid) {
            c.home_position =
                Position::new(MIZZLE_HOME_X, MIZZLE_HOME_Y, MIZZLE_HOME_Z, MIZZLE_HOME_O);
        }
        // `MoveTargetedHome` (cpp 839): evade/home motion is base-handled.
        self.do_script_text(MIZZLE_SAY_KILL_KING_1, guid, None, -1);
        if let Some(s) = self.mizzle_the_crafty_state_mut(guid) {
            s.spawned = true;
        }
    }

    /// `npc_mizzle_the_craftyAI::JustReachedHome` (cpp 849-857).
    fn mizzle_the_crafty_just_reached_home(&mut self, guid: ObjectGuid) {
        let done = self
            .mizzle_the_crafty_state_mut(guid)
            .is_some_and(|s| s.just_reached_home);
        if done {
            return;
        }
        self.do_script_text(MIZZLE_SAY_KILL_KING_2, guid, None, -1);
        let flags = self.object_get_field(guid, offsets::UNIT_NPC_FLAGS);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_NPC_FLAGS),
            flags | MIZZLE_UNIT_NPC_FLAG_GOSSIP,
        );
        if let Some(s) = self.mizzle_the_crafty_state_mut(guid) {
            s.just_reached_home = true;
        }
    }

