    /// `npc_knot_thimblejackAI::MovementInform` (cpp 897-944). The fork
    /// filters non-point motion; the dispatcher only carries the point id.
    fn knot_thimblejack_movement_inform(&mut self, guid: ObjectGuid, point_id: u32) {
        let next: Option<(u32, f32, f32, f32)> = match point_id {
            1 => Some((2, 470.2253, 542.596, -25.3631)),
            2 => Some((3, 465.367, 542.8436, -23.9119)),
            3 => Some((4, 453.3466, 544.0044, -23.9005)),
            4 => Some((5, 435.0555, 542.5039, -18.3959)),
            5 => Some((6, 412.7007, 537.0092, -18.3433)),
            6 => Some((7, 401.0763, 524.25, -12.7877)),
            7 => Some((8, 390.5408, 502.8305, -12.6759)),
            8 => Some((9, 386.1123, 483.01, -7.2322)),
            9 => Some((10, 385.9635, 442.6064, -7.1936)),
            10 => Some((11, 385.5317, 416.6193, -1.7035)),
            11 => Some((12, 385.3559, 375.9404, -1.623)),
            12 => Some((13, 385.6203, 350.4671, 3.825)),
            _ => None,
        };
        if let Some((id, x, y, z)) = next {
            self.creature_move_point(guid, id, Position::new(x, y, z, 0.0), 0, 0.0, 0.0);
        } else if point_id == 13 {
            // NEEDS-MAP-HELPER: `ForcedDespawn(5000)` delay (cpp 941);
            // immediate below (precedent: collapse to immediate).
            self.despawn_creature_now(guid, 0);
        }
    }

