    /// `GordokBruteAI::Reset` (cpp 1036-1044). The equipment id is captured
    /// from the live creature on first reset (fork ctor save, cpp 1025).
    fn gordok_brute_reset(&mut self, guid: ObjectGuid) {
        let current = self.creatures.get(&guid).map_or(0, |c| c.info.equipment_id);
        if let Some(s) = self.gordok_brute_state_mut(guid) {
            if s.equipment_id == 0 {
                s.equipment_id = current;
            }
            s.backhand_timer_ms = 2000;
            s.uppercut_timer_ms = 0;
            s.bruising_blow_timer_ms = 6000;
            s.pummel_timer_ms = 5000;
            s.enrage = false;
        }
        let equip = self
            .gordok_brute_state_mut(guid)
            .map_or(0, |s| s.equipment_id);
        self.creature_load_equipment(guid, equip);
    }

