    /// `GordokBruteAI::UpdateAI` (cpp 1067-1123).
    fn gordok_brute_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Bruising Blow above 30% (cpp 1073-1080): without the health gate
        // the timer neither re-arms nor ticks down.
        let blow_due = {
            let Some(s) = self.gordok_brute_state_mut(guid) else {
                return;
            };
            if s.bruising_blow_timer_ms < diff_ms {
                true
            } else {
                s.bruising_blow_timer_ms -= diff_ms;
                false
            }
        };
        if blow_due && self.creature_health_percent(guid) > 30.0 {
            let hoist41 = self.rng.urand(3000, 8000);
            if self.do_cast_spell_if_can(guid, BRUTE_SPELL_BRUISING_BLOW, CastTarget::Unit(victim))
                && let Some(s) = self.gordok_brute_state_mut(guid)
            {
                s.bruising_blow_timer_ms = hoist41;
            }
        }
        // Pummel: same health gate plus a victim-casting gate (cpp 1082-1089).
        let pummel_due = {
            let Some(s) = self.gordok_brute_state_mut(guid) else {
                return;
            };
            if s.pummel_timer_ms < diff_ms {
                true
            } else {
                s.pummel_timer_ms -= diff_ms;
                false
            }
        };
        let hoist40 = self.rng.urand(8000, 10_000);
        if pummel_due
            && self.creature_health_percent(guid) > 30.0
            && self.bot_casting_spell(victim).is_some()
            && self.do_cast_spell_if_can(guid, BRUTE_SPELL_PUMMEL, CastTarget::Unit(victim))
            && let Some(s) = self.gordok_brute_state_mut(guid)
        {
            s.pummel_timer_ms = hoist40;
        }
        // Enrage below 30% (cpp 1092-1101): stow the club (untriggered
        // cast); the emote line is a literal.
        if self.creature_health_percent(guid) < 30.0 {
            let enraged = self.gordok_brute_state_mut(guid).is_some_and(|s| s.enrage);
            if !enraged {
                // NEEDS-MAP-HELPER: `MonsterTextEmote` literal (cpp 1094-1097).
                self.creature_load_equipment(guid, 0);
                // Unconditional `CastSpell(..., false)` (cpp 1099): the
                // latch below does not depend on the cast result.
                let _ = self.do_cast_spell_if_can(guid, BRUTE_SPELL_ENRAGE, CastTarget::SelfCast);
                if let Some(s) = self.gordok_brute_state_mut(guid) {
                    s.enrage = true;
                }
            }
        }
        // Backhand while enraged below 30% (cpp 1103-1112).
        if self.creature_health_percent(guid) < 30.0 {
            let enraged = self.gordok_brute_state_mut(guid).is_some_and(|s| s.enrage);
            if enraged {
                let backhand_due = {
                    let Some(s) = self.gordok_brute_state_mut(guid) else {
                        return;
                    };
                    if s.backhand_timer_ms < diff_ms {
                        true
                    } else {
                        s.backhand_timer_ms -= diff_ms;
                        false
                    }
                };
                let hoist39 = self.rng.urand(5000, 9000);
                if backhand_due
                    && self.do_cast_spell_if_can(
                        guid,
                        BRUTE_SPELL_BACK_HAND,
                        CastTarget::Unit(victim),
                    )
                    && let Some(s) = self.gordok_brute_state_mut(guid)
                {
                    s.backhand_timer_ms = hoist39;
                }
            }
        }
        // Uppercut (cpp 1114-1120).
        let uppercut_due = {
            let Some(s) = self.gordok_brute_state_mut(guid) else {
                return;
            };
            if s.uppercut_timer_ms < diff_ms {
                true
            } else {
                s.uppercut_timer_ms -= diff_ms;
                false
            }
        };
        let hoist38 = self.rng.urand(6000, 10_000);
        if uppercut_due
            && self.do_cast_spell_if_can(guid, BRUTE_SPELL_UPPERCUT, CastTarget::Unit(victim))
            && let Some(s) = self.gordok_brute_state_mut(guid)
        {
            s.uppercut_timer_ms = hoist38;
        }
    }

