    /// `boss_guardsAI::UpdateAI` (cpp 1200-1274). The Slip'kik combat-bug
    /// timer (cpp 1203-1216) runs before the drive.
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn guards_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let bug_due = {
            let Some(s) = self.guards_state_mut(guid) else {
                return;
            };
            if s.combat_bug_timer_ms == 0 {
                false
            } else if s.combat_bug_timer_ms <= diff_ms {
                s.combat_bug_timer_ms = 0;
                true
            } else {
                s.combat_bug_timer_ms -= diff_ms;
                false
            }
        };
        if bug_due && self.ai_in_combat(guid) && self.unit_has_aura(guid, GUARDS_SPELL_ICE_LOCK) {
            // NEEDS-MAP-HELPER: `CombatStop(true)` + `DeleteThreatList`
            // (cpp 1209-1210).
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Shield Charge (cpp 1222-1232): farthest player in line of sight.
        let charge_due = {
            let Some(s) = self.guards_state_mut(guid) else {
                return;
            };
            if s.shield_charge_timer_ms < diff_ms {
                true
            } else {
                s.shield_charge_timer_ms -= diff_ms;
                false
            }
        };
        if charge_due {
            // The fork spell filter (cpp 1224) is threat-list-only data to
            // the selector, so it is dropped here.
            let target = self.select_attacking_target(guid, 4, 0, GUARDS_SELECT_FLAG_PLAYER_IN_LOS);
            if let Some(target) = target {
                let hoist37 = self.rng.urand(12_000, 16_000);
                let is_slipkik = self.object_entry(guid) == Some(DM_NPC_GUARD_SLIPKIK);
                if self.do_cast_spell_if_can(
                    guid,
                    GUARDS_SPELL_SHIELD_CHARGE,
                    CastTarget::Unit(target),
                ) && let Some(s) = self.guards_state_mut(guid)
                {
                    s.shield_charge_timer_ms = hoist37;
                    if is_slipkik {
                        s.combat_bug_timer_ms = 3000;
                    }
                }
            }
        }
        // Shield Bash: only while the victim is casting, and the timer
        // neither re-arms nor ticks down otherwise (cpp 1235-1244).
        let bash_due = {
            let Some(s) = self.guards_state_mut(guid) else {
                return;
            };
            if s.shield_bash_timer_ms < diff_ms {
                true
            } else {
                s.shield_bash_timer_ms -= diff_ms;
                false
            }
        };
        if bash_due && self.bot_casting_spell(victim).is_some() {
            let hoist36 = self.rng.urand(10_000, 15_000);
            if self.do_cast_spell_if_can(guid, GUARDS_SPELL_SHIELD_BASH, CastTarget::Unit(victim))
                && let Some(s) = self.guards_state_mut(guid)
            {
                s.shield_bash_timer_ms = hoist36;
            }
        }
        // Strike (cpp 1247-1253).
        let strike_due = {
            let Some(s) = self.guards_state_mut(guid) else {
                return;
            };
            if s.strike_timer_ms < diff_ms {
                true
            } else {
                s.strike_timer_ms -= diff_ms;
                false
            }
        };
        let hoist35 = self.rng.urand(10_000, 15_000);
        if strike_due
            && self.do_cast_spell_if_can(guid, GUARDS_SPELL_STRIKE, CastTarget::Unit(victim))
            && let Some(s) = self.guards_state_mut(guid)
        {
            s.strike_timer_ms = hoist35;
        }
        // Knock Away (cpp 1256-1262).
        let knock_due = {
            let Some(s) = self.guards_state_mut(guid) else {
                return;
            };
            if s.knock_away_timer_ms < diff_ms {
                true
            } else {
                s.knock_away_timer_ms -= diff_ms;
                false
            }
        };
        let hoist34 = self.rng.urand(20_000, 30_000);
        if knock_due
            && self.do_cast_spell_if_can(guid, GUARDS_SPELL_KNOCK_AWAY, CastTarget::Unit(victim))
            && let Some(s) = self.guards_state_mut(guid)
        {
            s.knock_away_timer_ms = hoist34;
        }
        // Enrage below 50% (cpp 1265-1271): unlatched cast, emote, call out.
        if self.creature_health_percent(guid) < 50.0 {
            let used = self.guards_state_mut(guid).is_some_and(|s| s.enrage_used);
            if !used {
                let _ = self.do_cast_spell_if_can(guid, GUARDS_SPELL_ENRAGE, CastTarget::SelfCast);
                self.do_script_text(GUARDS_EMOTE_ENRAGE, guid, None, -1);
                self.call_assistance(guid, 50.0);
                if let Some(s) = self.guards_state_mut(guid) {
                    s.enrage_used = true;
                }
            }
        }
    }

