    /// `boss_kromcrushAI::MovementInform` (cpp 1367-1398). The fork filters
    /// non-point motion; the dispatcher only carries the point id.
    fn kromcrush_movement_inform(&mut self, guid: ObjectGuid, point_id: u32) {
        // `MOVE_PATHFINDING` (`MotionMaster.h`); same bit as
        // `PHALANX_MOVE_PATHFINDING`, restated per-script.
        const KROM_MOVE_PATHFINDING: u32 = 0x001;
        match point_id {
            0 => self.creature_move_point(
                guid,
                1,
                Position::new(536.947, 535.784, 27.917, 0.0),
                KROM_MOVE_PATHFINDING,
                0.0,
                0.0,
            ),
            1 => self.creature_move_point(
                guid,
                2,
                Position::new(533.410, 591.445, -4.755, 0.0),
                KROM_MOVE_PATHFINDING,
                0.0,
                0.0,
            ),
            2 => self.creature_move_point(
                guid,
                3,
                Position::new(538.760, 540.026, -25.403, 0.0),
                KROM_MOVE_PATHFINDING,
                0.0,
                0.0,
            ),
            3 => self.creature_move_point(
                guid,
                4,
                Position::new(386.963, 515.853, -12.788, 0.0),
                KROM_MOVE_PATHFINDING,
                0.0,
                0.0,
            ),
            4 => self.creature_move_point(
                guid,
                5,
                Position::new(383.887, 258.610, 11.440, 0.0),
                KROM_MOVE_PATHFINDING,
                0.0,
                0.0,
            ),
            5 => {
                self.do_script_text(KROM_SAY_FIND_FURGUS, guid, None, -1);
                self.stop_moving(guid);
                self.relocate_unit(guid, Position::new(383.887, 258.610, 11.440, 0.0));
                let flags = self.object_get_field(guid, offsets::UNIT_FIELD_FLAGS);
                let _ = self.object_set_field(
                    guid,
                    u32::from(offsets::UNIT_FIELD_FLAGS),
                    flags & !(KROM_UNIT_FLAG_SPAWNING | KROM_UNIT_FLAG_NOT_SELECTABLE),
                );
            }
            _ => {}
        }
    }

