    /// `boss_kromcrushAI::CallReavers` (cpp 1427-1442).
    fn kromcrush_call_reavers(&mut self, guid: ObjectGuid) {
        self.handle_emote_command(guid, KROM_EMOTE_ONESHOT_ROAR);
        let near = match self.unit_position(guid) {
            Some(p) => {
                let dx = p.x - 495.395;
                let dy = p.y - 482.309;
                let dz = p.z - 29.4627;
                dx * dx + dy * dy + dz * dz <= 75.0 * 75.0
            }
            _ => false,
        };
        let (x, y, z, o) = if near {
            (495.395, 482.309, 29.4627, 6.267)
        } else {
            (633.437, 482.309, 29.4653, 3.198)
        };
        for _ in 0..2 {
            let _ = self.summon_creature(
                KROM_NPC_GORDOK_REAVER,
                Position::new(x, y, z, o),
                guid,
                KROM_TEMPSUMMON_TIMED_OR_CORPSE,
                300_000,
            );
        }
    }

    /// `boss_kromcrushAI::UpdateAI` (cpp 1444-1484).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn kromcrush_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Mortal Cleave (cpp 1450-1456).
        let cleave_due = {
            let Some(s) = self.kromcrush_state_mut(guid) else {
                return;
            };
            if s.mortal_cleave_timer_ms < diff_ms {
                true
            } else {
                s.mortal_cleave_timer_ms -= diff_ms;
                false
            }
        };
        let hoist33 = self.rng.urand(15_000, 20_000);
        if cleave_due
            && self.do_cast_spell_if_can(guid, KROM_SPELL_MORTAL_CLEAVE, CastTarget::Unit(victim))
            && let Some(s) = self.kromcrush_state_mut(guid)
        {
            s.mortal_cleave_timer_ms = hoist33;
        }
        // Intimidating Shout (cpp 1459-1465).
        let shout_due = {
            let Some(s) = self.kromcrush_state_mut(guid) else {
                return;
            };
            if s.intimidating_shout_timer_ms < diff_ms {
                true
            } else {
                s.intimidating_shout_timer_ms -= diff_ms;
                false
            }
        };
        let hoist32 = self.rng.urand(30_000, 35_000);
        if shout_due
            && self.do_cast_spell_if_can(
                guid,
                KROM_SPELL_INTIMIDATING_SHOUT,
                CastTarget::Unit(victim),
            )
            && let Some(s) = self.kromcrush_state_mut(guid)
        {
            s.intimidating_shout_timer_ms = hoist32;
        }
        // Retaliation below 25% (cpp 1468-1473).
        if self.creature_health_percent(guid) < 25.0 {
            let used = self
                .kromcrush_state_mut(guid)
                .is_some_and(|s| s.retaliation_used);
            if !used {
                let _ =
                    self.do_cast_spell_if_can(guid, KROM_SPELL_RETALIATION, CastTarget::SelfCast);
                self.do_script_text(KROM_EMOTE_RETALIATION, guid, None, -1);
                if let Some(s) = self.kromcrush_state_mut(guid) {
                    s.retaliation_used = true;
                }
            }
        }
        // Call Reavers below 50% (cpp 1476-1481).
        if self.creature_health_percent(guid) < 50.0 {
            let called = self
                .kromcrush_state_mut(guid)
                .is_some_and(|s| s.call_reavers);
            if !called {
                self.do_script_text(KROM_SAY_CALL_HELP, guid, None, -1);
                self.kromcrush_call_reavers(guid);
                if let Some(s) = self.kromcrush_state_mut(guid) {
                    s.call_reavers = true;
                }
            }
        }
    }

