    /// `boss_prince_tortheldrinAI::Reset` (cpp 1566-1575), including the
    /// triggered Thrash aura.
    fn prince_tortheldrin_reset(&mut self, guid: ObjectGuid) {
        let blast = self.rng.urand(15_000, 20_000);
        let counter = self.rng.urand(10_000, 20_000);
        let summon = self.rng.urand(0, 3000);
        let whirlwind = self.rng.urand(14_000, 22_000);
        if let Some(s) = self.prince_tortheldrin_state_mut(guid) {
            s.arcane_blast_timer_ms = blast;
            s.counterspell_timer_ms = counter;
            s.summon_timer_ms = summon;
            s.whirlwind_timer_ms = whirlwind;
        }
        // `CF_TRIGGERED | CF_AURA_NOT_PRESENT` Thrash (cpp 1574).
        if !self
            .aura_holders(guid)
            .iter()
            .any(|h| h.spell_id == TORTHELDRIN_SPELL_THRASH)
        {
            let _ = self.cast_spell(
                guid,
                TORTHELDRIN_SPELL_THRASH,
                CastTarget::SelfCast,
                CastOptions {
                    triggered: true,
                    skip_known: true,
                    ..Default::default()
                },
            );
        }
    }

    /// `boss_prince_tortheldrinAI::UpdateAI` (cpp 1577-1642).
    fn prince_tortheldrin_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Summon (cpp 1583-1589).
        let summon_due = {
            let Some(s) = self.prince_tortheldrin_state_mut(guid) else {
                return;
            };
            if s.summon_timer_ms < diff_ms {
                true
            } else {
                s.summon_timer_ms -= diff_ms;
                false
            }
        };
        let hoist31 = self.rng.urand(13_000, 20_000);
        if summon_due
            && self.do_cast_spell_if_can(guid, TORTHELDRIN_SPELL_SUMMON, CastTarget::Unit(victim))
            && let Some(s) = self.prince_tortheldrin_state_mut(guid)
        {
            s.summon_timer_ms = hoist31;
        }
        // Whirlwind, only with a melee attacker in 7.0 (cpp 1592-1612).
        let whirlwind_due = {
            let Some(s) = self.prince_tortheldrin_state_mut(guid) else {
                return;
            };
            if s.whirlwind_timer_ms < diff_ms {
                true
            } else {
                s.whirlwind_timer_ms -= diff_ms;
                false
            }
        };
        if whirlwind_due {
            // NEEDS-MAP-HELPER: `GetAttackers` in-7.0 gate + cast + re-arm
            // (cpp 1594-1609); the timer above still counts down but the due
            // branch has no live cast.
            let _ = TORTHELDRIN_SPELL_WHIRLWIND;
        }
        // Arcane Blast (cpp 1615-1624): threat wipe on success.
        let blast_due = {
            let Some(s) = self.prince_tortheldrin_state_mut(guid) else {
                return;
            };
            if s.arcane_blast_timer_ms < diff_ms {
                true
            } else {
                s.arcane_blast_timer_ms -= diff_ms;
                false
            }
        };
        if blast_due
            && self.do_cast_spell_if_can(
                guid,
                TORTHELDRIN_SPELL_ARCANE_BLAST,
                CastTarget::Unit(victim),
            )
        {
            // NEEDS-MAP-HELPER: `DoResetThreat()` (cpp 1619).
            let hoist30 = self.rng.urand(10_000, 15_000);
            if let Some(s) = self.prince_tortheldrin_state_mut(guid) {
                s.arcane_blast_timer_ms = hoist30;
            }
        }
        // Counterspell (cpp 1627-1639): random mana user, only mid-cast.
        let counter_due = {
            let Some(s) = self.prince_tortheldrin_state_mut(guid) else {
                return;
            };
            if s.counterspell_timer_ms < diff_ms {
                true
            } else {
                s.counterspell_timer_ms -= diff_ms;
                false
            }
        };
        if counter_due {
            let target =
                self.select_attacking_target(guid, 0, 0, TORTHELDRIN_SELECT_FLAG_PLAYER_MANA);
            if let Some(target) = target {
                let hoist29 = self.rng.urand(25_000, 30_000);
                if self.bot_casting_spell(target).is_some()
                    && self.do_cast_spell_if_can(
                        guid,
                        TORTHELDRIN_SPELL_COUNTERSPELL,
                        CastTarget::Unit(target),
                    )
                    && let Some(s) = self.prince_tortheldrin_state_mut(guid)
                {
                    s.counterspell_timer_ms = hoist29;
                }
            }
        }
    }

