    /// `boss_alzzin_the_wildshaperAI::Reset` (cpp 1710-1730). The thorns
    /// cast result is inverted into the re-cast flag (cpp 1729).
    fn alzzin_the_wildshaper_reset(&mut self, guid: ObjectGuid) {
        let ooc = self.rng.urand(30_000, 45_000);
        let thorns = self.rng.urand(1000, 3000);
        let disarm = self.rng.urand(5000, 10_000);
        let enervate = self.rng.urand(5000, 10_000);
        let knock = self.rng.urand(6000, 11_000);
        let mangle = self.rng.urand(3000, 7000);
        let bite = self.rng.urand(5000, 10_000);
        let regen = self.rng.urand(5000, 8000);
        let wither = self.rng.urand(2000, 5000);
        let phase = self.rng.urand(12_000, 15_000);
        if let Some(s) = self.alzzin_the_wildshaper_state_mut(guid) {
            s.ooc_phase = 0;
            s.ooc_timer_ms = ooc;
            s.thorns_timer_ms = thorns;
            s.disarm_timer_ms = disarm;
            s.enervate_timer_ms = enervate;
            s.knock_away_timer_ms = knock;
            s.mangle_timer_ms = mangle;
            s.vicious_bite_timer_ms = bite;
            s.wild_regeneration_timer_ms = regen;
            s.wither_timer_ms = wither;
            s.phase_timer_ms = phase;
            s.ch_phase = 0;
            s.evade_timer_ms = 3000;
            s.summoned = false;
        }
        let thorns_ok = self.do_cast_spell_if_can(guid, ALZZIN_SPELL_THORNS, CastTarget::SelfCast);
        if let Some(s) = self.alzzin_the_wildshaper_state_mut(guid) {
            s.cast_thorns = !thorns_ok;
        }
    }

    /// `boss_alzzin_the_wildshaperAI::SummonAdds` (cpp 1732-1741).
    fn alzzin_summon_adds(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        for coord in ALZZIN_MINION_COORDS {
            if let Some(add) = self.summon_creature(
                ALZZIN_NPC_MINION,
                Position::new(coord[0], coord[1], coord[2], coord[3]),
                guid,
                ALZZIN_TEMPSUMMON_TIMED_OR_DEAD,
                20_000,
            ) {
                self.attack_start(add, victim);
            }
        }
    }

    /// `boss_alzzin_the_wildshaperAI::ChangeForm` (cpp 1743-1770).
    fn alzzin_change_form(&mut self, guid: ObjectGuid) {
        let ch_phase = self
            .alzzin_the_wildshaper_state_mut(guid)
            .map_or(0, |s| s.ch_phase);
        let mask = ALZZIN_PHASE_MASK[ch_phase as usize % ALZZIN_PHASE_MASK.len()];
        let new_phase = if self.roll_chance_i(50) {
            mask[0]
        } else {
            mask[1]
        };
        match new_phase {
            0 => {
                self.cancel_aura(guid, ALZZIN_SPELL_DIRE_WOLF_FORM);
                self.cancel_aura(guid, ALZZIN_SPELL_TREE_FORM);
            }
            1 => {
                let _ = self.do_cast_spell_if_can(
                    guid,
                    ALZZIN_SPELL_DIRE_WOLF_FORM,
                    CastTarget::SelfCast,
                );
                self.cancel_aura(guid, ALZZIN_SPELL_TREE_FORM);
            }
            _ => {
                let _ =
                    self.do_cast_spell_if_can(guid, ALZZIN_SPELL_TREE_FORM, CastTarget::SelfCast);
                self.cancel_aura(guid, ALZZIN_SPELL_DIRE_WOLF_FORM);
            }
        }
        if let Some(s) = self.alzzin_the_wildshaper_state_mut(guid) {
            s.ch_phase = new_phase;
        }
    }

