    /// `npc_alzzins_minionAI::MoveInLineOfSight` (cpp 1977-1984): aggro
    /// players in 30.0 with line of sight while idle.
    fn alzzins_minion_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        if self.ai_in_combat(guid) {
            return;
        }
        if !who.is_player() {
            return;
        }
        let near = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                let dz = a.z - b.z;
                dx * dx + dy * dy + dz * dz <= 30.0 * 30.0
            }
            _ => false,
        };
        // NEEDS-MAP-HELPER: `IsTargetableBy` + `IsWithinLOSInMap` (cpp 1981).
        if near {
            // `AttackedBy(pWho)` (cpp 1982): no attacked-by helper; the
            // nearest equivalent is entering combat on the newcomer.
            self.enter_combat(guid, who);
        }
    }

