    /// `boss_ferraAI::MoveInLineOfSight` (cpp 2018-2029): 80.0 aggro that
    /// never pulls through the floor (victim at most 10.0 below).
    fn ferra_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        if self.ai_in_combat(guid) {
            return;
        }
        if !who.is_player() {
            return;
        }
        // NEEDS-MAP-HELPER: `IsWithinLOSInMap` + `IsTargetableBy` (cpp 2022).
        let pull = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                let dz = a.z - b.z;
                dx * dx + dy * dy + dz * dz <= 80.0 * 80.0 && (a.z - b.z) < 10.0
            }
            _ => false,
        };
        if pull {
            self.attack_start(guid, who);
        }
    }

