    /// `boss_magister_kalendrisAI::UpdateAI` (cpp 2102-2173).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    #[allow(clippy::similar_names)]
    fn magister_kalendris_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Shadow Word: Pain (cpp 2109-2115): `CF_AURA_NOT_PRESENT`.
        let pain_due = {
            let Some(s) = self.magister_kalendris_state_mut(guid) else {
                return;
            };
            if s.shadow_word_pain_timer_ms < diff_ms {
                true
            } else {
                s.shadow_word_pain_timer_ms -= diff_ms;
                false
            }
        };
        if pain_due {
            let present = self
                .aura_holders(victim)
                .iter()
                .any(|h| h.spell_id == KALENDRIS_SPELL_SHADOW_WORD_PAIN);
            let hoist15 = self.rng.urand(9000, 11_000);
            if !present
                && self.do_cast_spell_if_can(
                    guid,
                    KALENDRIS_SPELL_SHADOW_WORD_PAIN,
                    CastTarget::Unit(victim),
                )
                && let Some(s) = self.magister_kalendris_state_mut(guid)
            {
                s.shadow_word_pain_timer_ms = hoist15;
            }
        }
        // Mind Flay (cpp 2118-2124).
        let flay_due = {
            let Some(s) = self.magister_kalendris_state_mut(guid) else {
                return;
            };
            if s.mind_flay_timer_ms < diff_ms {
                true
            } else {
                s.mind_flay_timer_ms -= diff_ms;
                false
            }
        };
        let hoist14 = self.rng.urand(18_000, 23_000);
        if flay_due
            && self.do_cast_spell_if_can(guid, KALENDRIS_SPELL_MIND_FLAY, CastTarget::Unit(victim))
            && let Some(s) = self.magister_kalendris_state_mut(guid)
        {
            s.mind_flay_timer_ms = hoist14;
        }
        // Mind Blast (cpp 2127-2133): melee-scaled re-arm.
        let blast_due = {
            let Some(s) = self.magister_kalendris_state_mut(guid) else {
                return;
            };
            if s.mind_blast_timer_ms < diff_ms {
                true
            } else {
                s.mind_blast_timer_ms -= diff_ms;
                false
            }
        };
        if blast_due {
            let in_melee = self
                .magister_kalendris_state_mut(guid)
                .is_some_and(|s| s.in_melee);
            let hoist103a = self.rng.urand(7000, 10_000);
            let hoist103b = self.rng.urand(2000, 3000);
            if self.do_cast_spell_if_can(guid, KALENDRIS_SPELL_MIND_BLAST, CastTarget::Unit(victim))
                && let Some(s) = self.magister_kalendris_state_mut(guid)
            {
                s.mind_blast_timer_ms = if in_melee { hoist103a } else { hoist103b };
            }
        }
        // Dominate Mind (cpp 2136-2142): random player past top aggro.
        let dominate_due = {
            let Some(s) = self.magister_kalendris_state_mut(guid) else {
                return;
            };
            if s.dominate_mind_timer_ms < diff_ms {
                true
            } else {
                s.dominate_mind_timer_ms -= diff_ms;
                false
            }
        };
        if dominate_due {
            let target = self.select_attacking_target(guid, 0, 1, KALENDRIS_SELECT_FLAG_PLAYER);
            if let Some(target) = target {
                let hoist13 = self.rng.urand(25_000, 35_000);
                if self.do_cast_spell_if_can(
                    guid,
                    KALENDRIS_SPELL_DOMINATE_MIND,
                    CastTarget::Unit(target),
                ) && let Some(s) = self.magister_kalendris_state_mut(guid)
                {
                    s.dominate_mind_timer_ms = hoist13;
                }
            }
        }
        // Shadowform below 50% (cpp 2145-2149).
        if self.creature_health_percent(guid) < 50.0 {
            let used = self
                .magister_kalendris_state_mut(guid)
                .is_some_and(|s| s.shadowform_used);
            if !used
                && self.do_cast_spell_if_can(guid, KALENDRIS_SPELL_SHADOWFORM, CastTarget::SelfCast)
                && let Some(s) = self.magister_kalendris_state_mut(guid)
            {
                s.shadowform_used = true;
            }
        }
        // Melee/range dance (cpp 2151-2170): same fold-out as
        // `chorush_melee_dance` (LOS + mana gates unresolved).
        let in_melee = self
            .magister_kalendris_state_mut(guid)
            .is_some_and(|s| s.in_melee);
        let combat_movement = self.ai.get(&guid).is_some_and(|ai| ai.combat_movement);
        let dist2d = match (self.unit_position(guid), self.unit_position(victim)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                (dx * dx + dy * dy).sqrt()
            }
            _ => 0.0,
        };
        if !combat_movement {
            if !in_melee && (dist2d < 5.0 || dist2d > 30.0) {
                if let Some(ai) = self.ai.get_mut(&guid) {
                    ai.combat_movement = true;
                }
                self.creature_move_chase(guid, victim, 0.0, 0.0);
                if let Some(s) = self.magister_kalendris_state_mut(guid) {
                    s.in_melee = true;
                }
            }
        } else if in_melee && (5.0..=30.0).contains(&dist2d) {
            if let Some(ai) = self.ai.get_mut(&guid) {
                ai.combat_movement = false;
            }
            self.stop_moving(guid);
            if let Some(s) = self.magister_kalendris_state_mut(guid) {
                s.in_melee = false;
            }
        }
    }

