    /// `npc_captured_sprite_darterAI::EnterEvadeMode` pre-base (cpp 669-680).
    /// The fork never calls the base evade; the dispatcher still runs base
    /// evade + reset after this hook.
    fn captured_sprite_darter_enter_evade(&mut self, guid: ObjectGuid) {
        self.remove_all_auras(guid);
        // NEEDS-MAP-HELPER: `DeleteThreatList` + `CombatStop(true)` (cpp
        // 672-673) and the chase-only `MotionMaster::Clear` (cpp 678-679).
        if let Some(s) = self.captured_sprite_darter_state_mut(guid) {
            s.move_point = s.move_point.saturating_sub(1);
        }
    }

    /// `npc_captured_sprite_darterAI::JustDied` (cpp 683-694). The kindal
    /// `SpriteDied` callback targets the unported `FollowerAI` escort.
    fn captured_sprite_darter_just_died(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: kindal `SpriteDied()` cross-AI call (cpp
        // 684-691); `m_uiKindalGUID` is only written by the unported kindal
        // `BeginEvent`.
        // NEEDS-MAP-HELPER: `ForcedDespawn(10s)` delay (cpp 693);
        // immediate below (precedent: collapse to immediate).
        self.despawn_creature_now(guid, 0);
    }

    /// `npc_captured_sprite_darterAI::UpdateAI` (cpp 696-758). The OOC arm
    /// holds both the cage-gate start and the run chain (cpp 699-748); the
    /// mana-burn arm only runs in combat.
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn captured_sprite_darter_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            // Both guids stay empty until the unported kindal `BeginEvent`
            // writes them (cpp 701).
            let (event_start, run, kindal, gate) = self
                .captured_sprite_darter_state_mut(guid)
                .map_or((false, false, ObjectGuid::EMPTY, ObjectGuid::EMPTY), |s| {
                    (s.event_start, s.run, s.kindal_guid, s.gate_guid)
                });
            if kindal.is_empty() || gate.is_empty() {
                return;
            }
            if event_start && !run && self.go_state(gate) == GO_STATE_ACTIVE {
                let due = {
                    let Some(s) = self.captured_sprite_darter_state_mut(guid) else {
                        return;
                    };
                    if s.run_start_timer_ms < diff_ms {
                        true
                    } else {
                        s.run_start_timer_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    // NEEDS-MAP-HELPER: `SetFactionTemporary(
                    // FACTION_ESCORTEE_SPRITE=10, TEMPFACTION_RESTORE_RESPAWN)`
                    // (cpp 711).
                    if let Some(s) = self.captured_sprite_darter_state_mut(guid) {
                        s.run = true;
                    }
                }
            }
            // Run chain (cpp 721-748). The fork only re-issues while not on
            // point motion; that filter folds out here (unresolved), so the
            // current leg re-issues every OOC tick until arrival advances it.
            let running = self
                .captured_sprite_darter_state_mut(guid)
                .is_some_and(|s| s.run);
            if running {
                let (path, point) = self
                    .captured_sprite_darter_state_mut(guid)
                    .map_or((0, 0), |s| (s.run_path, s.move_point));
                let legs = SPRITE_RUN_PATHS[path as usize % SPRITE_RUN_PATHS.len()];
                match point {
                    0 => {
                        let leg = SPRITE_MOVE_POINTS[legs[0] as usize % SPRITE_MOVE_POINTS.len()];
                        self.creature_move_point(
                            guid,
                            0,
                            Position::new(leg[0], leg[1], leg[2], 0.0),
                            crate::motion::MOVE_PATHFINDING,
                            0.0,
                            0.0,
                        );
                        if let Some(s) = self.captured_sprite_darter_state_mut(guid) {
                            s.move_point = 1;
                        }
                    }
                    1 => {
                        let leg = SPRITE_MOVE_POINTS[legs[1] as usize % SPRITE_MOVE_POINTS.len()];
                        self.creature_move_point(
                            guid,
                            1,
                            Position::new(leg[0], leg[1], leg[2], 0.0),
                            crate::motion::MOVE_PATHFINDING,
                            0.0,
                            0.0,
                        );
                        if let Some(s) = self.captured_sprite_darter_state_mut(guid) {
                            s.move_point = 2;
                        }
                    }
                    _ => {
                        // NEEDS-MAP-HELPER: kindal `SpriteSaved()` cross-AI
                        // call (cpp 741-742).
                        // `ForcedDespawn()` (cpp 744): normal respawn path.
                        self.despawn_creature_now(guid, 0);
                    }
                }
            }
            return;
        };
        // Mana Burn against mana users (cpp 751-758).
        // NEEDS-MAP-HELPER: `GetPowerType() == POWER_MANA` gate (cpp 751).
        let burn_due = {
            let Some(s) = self.captured_sprite_darter_state_mut(guid) else {
                return;
            };
            if s.mana_burn_timer_ms < diff_ms {
                true
            } else {
                s.mana_burn_timer_ms -= diff_ms;
                false
            }
        };
        let hoist6 = self.rng.urand(7000, 10_000);
        if burn_due
            && self.do_cast_spell_if_can(guid, SPRITE_SPELL_MANA_BURN, CastTarget::Unit(victim))
            && let Some(s) = self.captured_sprite_darter_state_mut(guid)
        {
            s.mana_burn_timer_ms = hoist6;
        }
    }

