    /// `npc_weegli_blastfuseAI::UpdateAI` (cpp 283-347).
    fn weegli_blastfuse_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Full-heal pass once the pyramid falls (cpp 285-307, OOC first).
        let regen = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::WeegliBlastfuse(s)) if s.regen),
        );
        if !regen
            && self.zf_get_data(ZF_EVENT_PYRAMID) == Some(ZF_PYRAMID_KILLED_ALL_TROLLS)
            && let Some(s) = self.weegli_blastfuse_state_mut(guid)
        {
            s.regen = true;
        }
        // NEEDS-MAP-HELPER: `SetHealthPercent(100.0f)` on Oro, Murta,
        // Bly, Raven and self (cpp 289-306): no health-percent write
        // helper on `Map` (creature guids come from
        // `zf_get_data64(ZF_ENTRY_ORO/MURTA/BLY/RAVEN)`).
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // While the pyramid stands, drag the crew onto our victim
        // (cpp 314-327): `unit_victim` none-ness stands in for the fork
        // `!SelectHostileTarget() || !GetVictim()` screen.
        if self.zf_get_data(ZF_EVENT_PYRAMID) != Some(ZF_PYRAMID_KILLED_ALL_TROLLS) {
            for entry in [ZF_ENTRY_ORO, ZF_ENTRY_MURTA, ZF_ENTRY_BLY] {
                if let Some(ally) = self.zf_get_data64(entry)
                    && self.unit_victim(ally).is_none()
                {
                    self.attack_start(ally, victim);
                }
            }
        }
        // Bomb (cpp 329-335, fork `<` semantics kept).
        let bomb_due = {
            let Some(s) = self.weegli_blastfuse_state_mut(guid) else {
                return;
            };
            if s.bomb_timer_ms < diff_ms {
                true
            } else {
                s.bomb_timer_ms -= diff_ms;
                false
            }
        };
        if bomb_due {
            self.do_cast_spell_if_can(guid, WEEGLI_SPELL_BOMB, CastTarget::Unit(victim));
            if let Some(s) = self.weegli_blastfuse_state_mut(guid) {
                s.bomb_timer_ms = 10_000;
            }
        }
        // Shoot-vs-melee (cpp 337-346): no `IsAttackReady` helper, so range
        // decides here (see unresolved NOTE-3).
        if self.can_reach_melee(guid, victim) {
            self.unit_set_byte(guid, offsets::UNIT_FIELD_BYTES_2, 0, SHEATH_MELEE);
        } else {
            self.do_cast_spell_if_can(guid, WEEGLI_SPELL_SHOOT, CastTarget::Unit(victim));
            self.unit_set_byte(guid, offsets::UNIT_FIELD_BYTES_2, 0, WEEGLI_SHEATH_RANGED);
        }
    }

    /// `npc_weegli_blastfuseAI::MovementInform` (cpp 349-399).
    #[allow(clippy::too_many_lines)] // fork MovementInform transcription
    fn weegli_blastfuse_movement_inform(&mut self, guid: ObjectGuid, point_id: u32) {
        // `PYRAMID_CAGES_OPEN` reuses the GO-lane `CAGE_` const: the ZF
        // instance lane omits it (go_troll_cage sets it).
        let phase = self.zf_get_data(ZF_EVENT_PYRAMID);
        if phase == Some(CAGE_PYRAMID_CAGES_OPEN) {
            // Inner `id == 1` gate only (cpp 355): no fallthrough to the
            // `else` arm when the phase matches but the point does not.
            if point_id == 1 {
                self.zf_set_data(ZF_EVENT_PYRAMID, ZF_PYRAMID_ARRIVED_AT_STAIR);
                self.do_script_text(WEEGLI_SAY_OHNO, guid, None, -1);
                // NEEDS-MAP-HELPER: `SetCombatStartPosition` (cpp 359).
                self.set_walk(guid, false);
                self.creature_move_point(
                    guid,
                    2,
                    Position::new(1883.27, 1268.72, 41.73, 0.0),
                    0,
                    0.0,
                    0.0,
                );
            }
        } else if phase == Some(ZF_PYRAMID_WAVE_1) && point_id == 2 {
            self.creature_move_point(
                guid,
                3,
                Position::new(1888.55, 1272.19, 41.67, 0.0),
                0,
                0.0,
                0.0,
            );
            // NEEDS-MAP-HELPER: `SetCombatStartPosition` + `SetHomePosition`
            // (cpp 367-368).
            self.set_walk(guid, true);
        } else {
            let destroying = self.ai.get(&guid).is_some_and(|ai| {
                matches!(&ai.script, Some(CreatureScriptAi::WeegliBlastfuse(s)) if s.destroying_door)
            });
            if destroying {
                // NEEDS-MAP-HELPER: `SummonGameObject(144065, 1856.314209,
                // ...)` charge (cpp 375): no GO-summon helper, so
                // `explosiveGUID` has no lane field (see unresolved).
                if let Some(s) = self.weegli_blastfuse_state_mut(guid) {
                    s.destroying_door = false;
                }
                self.weegli_blastfuse_run_after_explosion_1(guid);
            }
            let run_away = self.ai.get(&guid).is_some_and(
                |ai| matches!(&ai.script, Some(CreatureScriptAi::WeegliBlastfuse(s)) if s.run_away),
            );
            if run_away && point_id == 1 {
                // NEEDS-MAP-HELPER: barrel `SetSpellId` + `UseDoorOrButton`
                // (cpp 384-385); `DoUseDoorOrButton(EndDoor)` (cpp 388).
                let end_door = self.zf_get_data64(ZF_GO_END_DOOR);
                let _ = end_door;
                self.zf_set_data(ZF_EVENT_END_DOOR, DONE);
                if let Some(chief) = self.zf_get_data64(ZF_ENTRY_UKORZ) {
                    self.do_script_text(WEEGLI_SAY_CHIEF_DOOR, chief, None, -1);
                }
                self.weegli_blastfuse_run_after_explosion_2(guid);
                if let Some(s) = self.weegli_blastfuse_state_mut(guid) {
                    s.run_away = false;
                }
            }
            let disappear = self.ai.get(&guid).is_some_and(|ai| {
                matches!(&ai.script, Some(CreatureScriptAi::WeegliBlastfuse(s)) if s.disappear)
            });
            if disappear && point_id == 2 {
                self.despawn_creature_now(guid, 0);
            }
        }
    }

