    /// `EvolvingEctoplasmAI::SpellHit` (cpp 633-666): the fork schools the
    /// hitting spell; the school comes from the spell store (existing
    /// `SpellStore::get` API, no new helper).
    fn evolving_ectoplasm_spell_hit(
        &mut self,
        guid: ObjectGuid,
        _caster: ObjectGuid,
        spell_id: u32,
    ) {
        let immune = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::EvolvingEctoplasm(s)) if s.is_immune),
        );
        if immune {
            return;
        }
        let school = self.stores.spells.get(spell_id).map(|entry| entry.school);
        // `CF_TRIGGERED | CF_AURA_NOT_PRESENT` (cpp 639-662): threaded by
        // the integrator (naxx convention).
        let (transform, immune_spell) = match school {
            Some(s) if s == mangos_spells::defines::school::FROST => {
                (ECTO_SPELL_TRANSFORM_BLUE, ECTO_SPELL_IMMUNE_FROST)
            }
            Some(s) if s == mangos_spells::defines::school::FIRE => {
                (ECTO_SPELL_TRANSFORM_RED, ECTO_SPELL_IMMUNE_FIRE)
            }
            Some(s) if s == mangos_spells::defines::school::NATURE => {
                (ECTO_SPELL_TRANSFORM_GREEN, ECTO_SPELL_IMMUNE_NATURE)
            }
            Some(s) if s == mangos_spells::defines::school::SHADOW => {
                (ECTO_SPELL_TRANSFORM_BLACK, ECTO_SPELL_IMMUNE_SHADOW)
            }
            _ => return,
        };
        self.do_cast_spell_if_can(guid, transform, CastTarget::SelfCast);
        self.do_cast_spell_if_can(guid, immune_spell, CastTarget::SelfCast);
        if let Some(s) = self.evolving_ectoplasm_state_mut(guid) {
            s.immune_timer_ms = 10_000;
            s.is_immune = true;
        }
    }

    /// `EvolvingEctoplasmAI::UpdateAI` (cpp 668-689, fork `<` semantics kept).
    fn evolving_ectoplasm_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let expired = {
            let Some(s) = self.evolving_ectoplasm_state_mut(guid) else {
                return;
            };
            if s.immune_timer_ms < diff_ms {
                true
            } else {
                s.immune_timer_ms -= diff_ms;
                false
            }
        };
        if expired {
            self.remove_auras_due_to_spell(guid, ECTO_SPELL_TRANSFORM_RED);
            self.remove_auras_due_to_spell(guid, ECTO_SPELL_TRANSFORM_BLUE);
            self.remove_auras_due_to_spell(guid, ECTO_SPELL_TRANSFORM_GREEN);
            self.remove_auras_due_to_spell(guid, ECTO_SPELL_TRANSFORM_BLACK);
            self.remove_auras_due_to_spell(guid, ECTO_SPELL_IMMUNE_SHADOW);
            self.remove_auras_due_to_spell(guid, ECTO_SPELL_IMMUNE_FROST);
            self.remove_auras_due_to_spell(guid, ECTO_SPELL_IMMUNE_FIRE);
            self.remove_auras_due_to_spell(guid, ECTO_SPELL_IMMUNE_NATURE);
            if let Some(s) = self.evolving_ectoplasm_state_mut(guid) {
                s.is_immune = false;
            }
        }
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
    }

