    /// `npc_enraged_foulwealdAI::HitBanner` (`ashenvale.cpp:571-583`).
    fn enraged_foulweald_hit_banner(&mut self, guid: ObjectGuid) -> bool {
        let banner = self.nearest_gameobject_with_entry(guid, FOULWEALD_GO_KARANG_BANNER, 1.5);
        let Some(banner) = banner else {
            return false;
        };
        // NEEDS-MAP-HELPER: position-target `CastSpell(x, y, z,
        // SPELL_DESTROY_KARANG_S_BANNER_1, false)` (cpp 577).
        self.do_script_text(FOULWEALD_SAY_ATTACK_BANNER, guid, None, -1);
        if let Some(s) = self.enraged_foulweald_state_mut(guid) {
            s.timer_ms = 10_000;
        }
        let _ = banner;
        true
    }

    /// `npc_enraged_foulwealdAI::AttackStart` (`ashenvale.cpp:564-569`).
    /// Its presence replaces the drive chase sync: channeled casts block
    /// the fork `ScriptedAI::AttackStart`.
    fn enraged_foulweald_attack_start(&mut self, guid: ObjectGuid, victim: ObjectGuid) {
        // Fork gates on `GetCurrentSpell(CURRENT_CHANNELED_SPELL)`; the port
        // uses the active-cast check (cpp 566).
        if self.bot_casting_spell(guid).is_some() {
            return;
        }
        self.attack_start(guid, victim);
    }

    /// `npc_enraged_foulwealdAI::UpdateAI` (`ashenvale.cpp:585-610`).
    fn enraged_foulweald_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // OOC banner work runs before the drive (fork 590-608).
        if self.bot_casting_spell(guid).is_some() {
            return;
        }
        let has_victim = self.get_hostile_target(guid).is_some();
        if !has_victim {
            let due = {
                let Some(s) = self.enraged_foulweald_state_mut(guid) else {
                    return;
                };
                if s.timer_ms < diff_ms {
                    true
                } else {
                    s.timer_ms -= diff_ms;
                    false
                }
            };
            if due && !self.enraged_foulweald_hit_banner(guid) {
                let banner =
                    self.nearest_gameobject_with_entry(guid, FOULWEALD_GO_KARANG_BANNER, 30.0);
                if let Some(banner) = banner {
                    // NEEDS-MAP-HELPER: `GetContactPoint(banner,
                    // CONTACT_DISTANCE)` offset (cpp 599).
                    let dest = self.object_position(banner).unwrap_or_default();
                    self.creature_move_point(guid, 2, dest, 0, 0.0, 0.0);
                    if let Some(s) = self.enraged_foulweald_state_mut(guid) {
                        s.timer_ms = 10_000;
                    }
                }
            }
            return;
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let _ = victim;
    }

