    /// `mob_mawsAI::Reset` (`azshara.cpp:173-190`).
    fn maws_reset(&mut self, guid: ObjectGuid) {
        let rampage = self.rng.urand(20_000, 120_000);
        let frenzy = 25_000;
        if let Some(s) = self.maws_state_mut(guid) {
            s.phase_two = false;
            s.in_combat = false;
            s.leave_combat_timer_ms = 30_000;
            s.rampage_timer_ms = rampage;
            s.rampage_timer_max_ms = 120_000;
            s.frenzy_timer_ms = frenzy;
            s.frenzy_timer_max_ms = 25_000;
            s.dark_water_timer_ms = 15_000;
        }
        // NEEDS-MAP-HELPER: `RemoveAllAuras` / `DeleteThreatList` /
        // `CombatStop(true)` / `SetLootRecipient(nullptr)` (cpp 177-180),
        // `SetWalk(faction == FACTION_MONSTER)` (faction read, cpp 188),
        // then `MovePoint(LastWayPoint, ...)` below.
        let waypoint = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Maws(s)) => Some(s.last_waypoint),
                _ => None,
            })
            .unwrap_or(2);
        let (x, y, z) = MAWS_RONDE
            .get(waypoint as usize)
            .copied()
            .unwrap_or(MAWS_RONDE[2]);
        self.creature_move_point(guid, waypoint, Position::new(x, y, z, 0.0), 0, 0.0, 0.0);
    }

    /// `mob_mawsAI::MovementInform` (`azshara.cpp:85-101`).
    fn maws_movement_inform(&mut self, guid: ObjectGuid, point_id: u32) {
        let in_combat = self
            .ai
            .get(&guid)
            .is_some_and(|ai| matches!(&ai.script, Some(CreatureScriptAi::Maws(s)) if s.in_combat));
        if !in_combat {
            if point_id < 14 {
                let next = point_id + 1;
                if let Some(&(x, y, z)) = MAWS_RONDE.get(next as usize) {
                    self.creature_move_point(guid, next, Position::new(x, y, z, 0.0), 0, 0.0, 0.0);
                }
            } else if point_id == 14 {
                // NEEDS-MAP-HELPER: `GetFactionTemplateId() == FACTION_MONSTER`
                // gate + `SetFactionTemporary(FACTION_MONSTER, ...)` (cpp 93).
                if let Some(&(x, y, z)) = MAWS_RONDE.get(1) {
                    self.creature_move_point(guid, 1, Position::new(x, y, z, 0.0), 0, 0.0, 0.0);
                }
            }
        }
        if point_id > 0 && point_id < 15 {
            if let Some(s) = self.maws_state_mut(guid) {
                s.last_waypoint = point_id;
            }
        }
    }

