    /// `mob_mawsAI::UpdateAI` (`azshara.cpp:103-160`).
    #[allow(clippy::too_many_lines)]
    fn maws_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let in_combat = self
            .ai
            .get(&guid)
            .is_some_and(|ai| matches!(&ai.script, Some(CreatureScriptAi::Maws(s)) if s.in_combat));
        if in_combat {
            // Fork combat arm (cpp 107-156): leave-combat expiry resets.
            let expired = {
                let hoist1 = self.get_hostile_target(guid).is_none();
                let Some(s) = self.maws_state_mut(guid) else {
                    return;
                };
                let no_target = hoist1;
                if no_target || s.leave_combat_timer_ms < diff_ms {
                    s.in_combat = false;
                    true
                } else {
                    false
                }
            };
            if expired {
                self.maws_reset(guid);
                return;
            }
            let victim = self.get_hostile_target(guid);
            let Some(victim) = victim else {
                return;
            };
            // Phase-two gate at 20% (cpp 115-123).
            if !self.ai.get(&guid).is_some_and(
                |ai| matches!(&ai.script, Some(CreatureScriptAi::Maws(s)) if s.phase_two),
            ) && self.creature_health_percent(guid) < 20.0
            {
                let (ramp_max, fren_max) = (12_000, 15_000);
                if let Some(s) = self.maws_state_mut(guid) {
                    s.phase_two = true;
                    s.rampage_timer_max_ms = ramp_max;
                    s.frenzy_timer_max_ms = fren_max;
                    if ramp_max < s.rampage_timer_ms {
                        s.rampage_timer_ms = ramp_max;
                    }
                    if fren_max < s.frenzy_timer_ms {
                        s.frenzy_timer_ms = fren_max;
                    }
                }
            }
            let rampage_due = {
                let Some(s) = self.maws_state_mut(guid) else {
                    return;
                };
                if s.rampage_timer_ms < diff_ms {
                    true
                } else {
                    s.rampage_timer_ms -= diff_ms;
                    false
                }
            };
            if rampage_due {
                // Fork rearms unconditionally (cpp 125-132).
                let cast =
                    self.do_cast_spell_if_can(guid, MAWS_SPELL_RAMPAGE, CastTarget::Unit(victim));
                let _ = cast;
                let next = self.rng.urand(20_000, 120_000);
                if let Some(s) = self.maws_state_mut(guid) {
                    let phase_two = s.phase_two;
                    s.rampage_timer_ms = if phase_two {
                        s.rampage_timer_max_ms
                    } else {
                        next
                    };
                    if !phase_two {
                        s.rampage_timer_max_ms = next;
                    }
                }
            }
            let frenzy_due = {
                let Some(s) = self.maws_state_mut(guid) else {
                    return;
                };
                if s.frenzy_timer_ms < diff_ms {
                    true
                } else {
                    s.frenzy_timer_ms -= diff_ms;
                    false
                }
            };
            if frenzy_due {
                // Fork rearms unconditionally (cpp 133-139).
                let cast = self.do_cast_spell_if_can(guid, MAWS_SPELL_FRENZY, CastTarget::SelfCast);
                let _ = cast;
                if let Some(s) = self.maws_state_mut(guid) {
                    s.frenzy_timer_ms = s.frenzy_timer_max_ms;
                }
            }
            let phase_two = self.ai.get(&guid).is_some_and(
                |ai| matches!(&ai.script, Some(CreatureScriptAi::Maws(s)) if s.phase_two),
            );
            if phase_two {
                let dark_due = {
                    let Some(s) = self.maws_state_mut(guid) else {
                        return;
                    };
                    if s.dark_water_timer_ms < diff_ms {
                        true
                    } else {
                        s.dark_water_timer_ms -= diff_ms;
                        false
                    }
                };
                if dark_due {
                    // Fork rearms unconditionally (cpp 143-149).
                    let cast = self.do_cast_spell_if_can(
                        guid,
                        MAWS_SPELL_DARK_WATER,
                        CastTarget::SelfCast,
                    );
                    let _ = cast;
                    if let Some(s) = self.maws_state_mut(guid) {
                        s.dark_water_timer_ms = 15_000;
                    }
                }
            }
            // NEEDS-MAP-HELPER: `IDLE_MOTION_TYPE` gate for `MoveChase`
            // (cpp 152-153); the drive below keeps the chase synced.
            if let Some(s) = self.maws_state_mut(guid) {
                s.leave_combat_timer_ms = s.leave_combat_timer_ms.saturating_sub(diff_ms);
            }
            let Some(victim) = self.script_combat_drive(guid, true) else {
                return;
            };
            let _ = victim;
        } else if self.get_hostile_target(guid).is_some() {
            if let Some(s) = self.maws_state_mut(guid) {
                s.in_combat = true;
            }
        }
    }

