    /// `LazyPeonAI::SpellHit` (`durotar.cpp:73-83`).
    fn lazy_peon_spell_hit(&mut self, guid: ObjectGuid, caster: ObjectGuid, spell_id: u32) {
        if spell_id != LAZY_PEON_SPELL_AWAKEN_PEON {
            return;
        }
        if self.object_entry(guid) != Some(LAZY_PEON_ENTRY) {
            return;
        }
        if !self.bot_has_aura(guid, LAZY_PEON_SPELL_BUFF_SLEEP) {
            return;
        }
        if let Some(s) = self.lazy_peon_state_mut(guid) {
            s.player_guid = caster;
            s.state = LAZY_PEON_STATE_WAKEUP;
            s.timer_before_moving_to_lumberpile_ms = 0;
        }
    }

    /// `LazyPeonAI::UpdateAI` (`durotar.cpp:85-148`): state machine, no
    /// combat head.
    fn lazy_peon_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let state = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::LazyPeon(s)) => Some(s.state),
                _ => None,
            })
            .unwrap_or(LAZY_PEON_STATE_SLEEPING);
        match state {
            LAZY_PEON_STATE_SLEEPING => {
                if !self.bot_has_aura(guid, LAZY_PEON_SPELL_BUFF_SLEEP) {
                    self.do_cast_spell_if_can(
                        guid,
                        LAZY_PEON_SPELL_BUFF_SLEEP,
                        CastTarget::SelfCast,
                    );
                }
            }
            LAZY_PEON_STATE_WORKING => {
                let due = {
                    let Some(s) = self.lazy_peon_state_mut(guid) else {
                        return;
                    };
                    if s.timer_before_sleep_ms < diff_ms {
                        true
                    } else {
                        s.timer_before_sleep_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    // NEEDS-MAP-HELPER: `HandleEmoteState(0)` (cpp 97).
                    // NEEDS-MAP-HELPER: `GetHomePosition` (cpp 98-99).
                    let home = self.unit_position(guid).unwrap_or_default();
                    self.creature_move_point(guid, 1, home, 0, 0.0, 0.0);
                    if let Some(s) = self.lazy_peon_state_mut(guid) {
                        s.state = LAZY_PEON_STATE_MOVING_BACK;
                    }
                }
            }
            LAZY_PEON_STATE_WAKEUP => {
                let due = {
                    let Some(s) = self.lazy_peon_state_mut(guid) else {
                        return;
                    };
                    if s.timer_before_working_ms < diff_ms {
                        true
                    } else {
                        s.timer_before_working_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    self.cancel_aura(guid, LAZY_PEON_SPELL_BUFF_SLEEP);
                    if let Some(s) = self.lazy_peon_state_mut(guid) {
                        // START_MOVING_TO_LUMBERPILE = 1 (cpp 44).
                        s.state = 1;
                        s.timer_before_moving_to_lumberpile_ms = 2000;
                        s.timer_before_working_ms = 3000;
                    }
                }
            }
            // START_MOVING_TO_LUMBERPILE = 1 (cpp 44), distinct from the
            // WAKEUP arm above.
            1 => {
                let due = {
                    let Some(s) = self.lazy_peon_state_mut(guid) else {
                        return;
                    };
                    if s.timer_before_moving_to_lumberpile_ms < diff_ms {
                        true
                    } else {
                        s.timer_before_moving_to_lumberpile_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    if self
                        .nearest_gameobject_with_entry(guid, LAZY_PEON_GO_LUMBERPILE, 20.0)
                        .is_some()
                    {
                        // NEEDS-MAP-HELPER: `GetContactPoint(lumberPile,
                        // CONTACT_DISTANCE + 0.2)` (cpp 130); walk there with
                        // `MOVE_PATHFINDING`.
                        self.set_walk(guid, true);
                    }
                    if let Some(s) = self.lazy_peon_state_mut(guid) {
                        s.timer_before_moving_to_lumberpile_ms = 2000;
                    }
                    let player = self
                        .lazy_peon_state_mut(guid)
                        .map_or(ObjectGuid::EMPTY, |s| s.player_guid);
                    if self.players.contains_key(&player) {
                        self.do_script_text(LAZY_PEON_SAY_SPELL_HIT, guid, Some(player), -1);
                    }
                    if let Some(s) = self.lazy_peon_state_mut(guid) {
                        // STATE_MOVING_TO_LUMBERPILE = 2 (cpp 45).
                        s.state = 2;
                    }
                }
            }
            _ => {}
        }
    }

    /// `LazyPeonAI::MovementInform` (`durotar.cpp:150-169`).
    fn lazy_peon_movement_inform(&mut self, guid: ObjectGuid, point_id: u32) {
        // Fork gates on `POINT_MOTION_TYPE` + id 1 (cpp 152).
        if point_id != 1 {
            return;
        }
        let state = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::LazyPeon(s)) => Some(s.state),
                _ => None,
            })
            .unwrap_or(LAZY_PEON_STATE_SLEEPING);
        // STATE_MOVING_TO_LUMBERPILE = 2 (cpp 45).
        if state == 2 {
            if self
                .nearest_gameobject_with_entry(guid, LAZY_PEON_GO_LUMBERPILE, 20.0)
                .is_some()
            {
                // NEEDS-MAP-HELPER: `SetFacingToObject` + `HandleEmoteState(
                // EMOTE_WORKING)` (cpp 159-160).
            }
            if let Some(s) = self.lazy_peon_state_mut(guid) {
                s.state = LAZY_PEON_STATE_WORKING;
                s.timer_before_sleep_ms = 120_000;
            }
        } else {
            // STATE_MOVING_BACK arm (cpp 163-167).
            if let Some(s) = self.lazy_peon_state_mut(guid) {
                s.state = LAZY_PEON_STATE_SLEEPING;
            }
            self.do_cast_spell_if_can(guid, LAZY_PEON_SPELL_BUFF_SLEEP, CastTarget::SelfCast);
        }
    }

