    /// `npc_piznikAI::UpdateAI` (`stonetalon_mountains.cpp:92-127`).
    #[allow(clippy::too_many_lines)]
    fn piznik_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Fork head: combat arm is melee-only; the event machine runs OOC
        // (cpp 94-96). `get_hostile_target` is the read-only check.
        if self.get_hostile_target(guid).is_some() {
            return;
        }
        let (in_event, phase) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Piznik(s)) => Some((s.in_event, s.event_phase)),
                _ => None,
            })
            .unwrap_or((false, PIZNIK_PHASE_INIT));
        if !in_event {
            return;
        }
        // NEEDS-MAP-HELPER: `GetOrientation()` for the summon `o` below
        // (cpp uses fixed orientations; transcribed literally).
        if phase == PIZNIK_PHASE_INIT {
            self.summon_creature(
                PIZNIK_NPC_AMBUSHER_A,
                Position::new(935.693, -262.078_9, -2.155_2, 0.5),
                guid,
                PIZNIK_TEMPSUMMON_TIMED_OR_CORPSE,
                120_000,
            );
            self.summon_creature(
                PIZNIK_NPC_AMBUSHER_B,
                Position::new(931.673_5, -261.396_7, -2.020_3, 6.5),
                guid,
                PIZNIK_TEMPSUMMON_TIMED_OR_CORPSE,
                120_000,
            );
            if let Some(s) = self.piznik_state_mut(guid) {
                s.event_phase = PIZNIK_PHASE_SECOND_WAVE;
            }
        }
        let timer = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Piznik(s)) => Some(s.event_timer_ms),
                _ => None,
            })
            .unwrap_or(0);
        if timer > 60_000 && phase == PIZNIK_PHASE_SECOND_WAVE {
            self.summon_creature(
                PIZNIK_NPC_AMBUSHER_A,
                Position::new(935.693, -262.078_9, -2.155_2, 0.5),
                guid,
                PIZNIK_TEMPSUMMON_TIMED_OR_CORPSE,
                120_000,
            );
            self.summon_creature(
                PIZNIK_NPC_AMBUSHER_B,
                Position::new(931.673_5, -261.396_7, -2.020_3, 6.5),
                guid,
                PIZNIK_TEMPSUMMON_TIMED_OR_CORPSE,
                120_000,
            );
            self.summon_creature(
                PIZNIK_NPC_AMBUSHER_A,
                Position::new(930.421_6, -266.460_3, -1.668_9, 0.5),
                guid,
                PIZNIK_TEMPSUMMON_TIMED_OR_CORPSE,
                120_000,
            );
            if let Some(s) = self.piznik_state_mut(guid) {
                s.event_phase = PIZNIK_PHASE_THIRD_WAVE;
            }
        }
        if timer > 120_000 && phase == PIZNIK_PHASE_THIRD_WAVE {
            self.summon_creature(
                PIZNIK_NPC_AMBUSHER_A,
                Position::new(935.693, -262.078_9, -2.155_2, 0.5),
                guid,
                PIZNIK_TEMPSUMMON_TIMED_OR_CORPSE,
                120_000,
            );
            self.summon_creature(
                PIZNIK_NPC_AMBUSHER_B,
                Position::new(931.673_5, -261.396_7, -2.020_3, 6.5),
                guid,
                PIZNIK_TEMPSUMMON_TIMED_OR_CORPSE,
                120_000,
            );
            self.summon_creature(
                PIZNIK_NPC_AMBUSHER_C,
                Position::new(930.421_6, -266.460_3, -1.668_9, 0.5),
                guid,
                PIZNIK_TEMPSUMMON_TIMED_OR_CORPSE,
                120_000,
            );
            if let Some(s) = self.piznik_state_mut(guid) {
                s.event_phase = PIZNIK_PHASE_END;
            }
        }
        if timer > 180_000 && phase == PIZNIK_PHASE_END {
            // NEEDS-MAP-HELPER: `GetPlayer(pGuid)` + `GroupEventHappens(
            // QUEST_GERENOS_ORDERS, ...)` (cpp 120-121), `RemoveFlag(
            // UNIT_FIELD_FLAGS, UNIT_FLAG_PVP)` + `RestoreFaction` (cpp
            // 123-124).
            if let Some(s) = self.piznik_state_mut(guid) {
                s.in_event = false;
            }
        }
        if let Some(s) = self.piznik_state_mut(guid) {
            s.event_timer_ms = s.event_timer_ms.wrapping_add(diff_ms);
        }
    }

