    /// `npc_murkdeepAI::Reset` (`darkshore.cpp:958-966`).
    fn murkdeep_reset(&mut self, guid: ObjectGuid) {
        let sunder = self.rng.urand(0, 5);
        let net = self.rng.urand(0, 20);
        if let Some(s) = self.murkdeep_state_mut(guid) {
            s.event_phase = 0;
            s.event_state = false;
            s.has_fled = false;
            s.sunder_armor_timer_ms = sunder;
            s.net_timer_ms = net;
        }
    }

    /// `npc_murkdeepAI::BeginEvent` (`darkshore.cpp:968-982`): areatrigger
    /// glue (`at_murloc_camp`, cpp 1134-1158).
    pub(crate) fn murkdeep_begin_event(&mut self, guid: ObjectGuid, player: ObjectGuid) {
        if let Some(s) = self.murkdeep_state_mut(guid) {
            s.event_phase = 1;
            s.event_timer_ms = 1000;
            s.event_state = true;
            s.player_guid = player;
        }
        let bonfire = self.nearest_gameobject_with_entry(
            guid,
            MURKDEEP_GO_BONFIRE,
            self.config.visibility_distance,
        );
        if let Some(bonfire) = bonfire {
            if let Some(s) = self.murkdeep_state_mut(guid) {
                s.bonfire_guid = bonfire;
            }
        }
    }

    /// `npc_murkdeepAI::GetPlayer` (`darkshore.cpp:1000-1014`).
    fn murkdeep_get_player(&self, guid: ObjectGuid) -> Option<ObjectGuid> {
        let (player, bonfire) = self.ai.get(&guid).and_then(|ai| match &ai.script {
            Some(CreatureScriptAi::Murkdeep(s)) => Some((s.player_guid, s.bonfire_guid)),
            _ => None,
        })?;
        if !self.players.contains_key(&player) {
            return None;
        }
        if !self.gameobjects.contains_key(&bonfire) {
            return None;
        }
        // `player->IsInRange(bonfire, 0.0, 50.0)` (cpp 1010).
        let (Some(pp), Some(bp)) = (self.object_position(player), self.object_position(bonfire))
        else {
            return None;
        };
        let dx = pp.x - bp.x;
        let dy = pp.y - bp.y;
        if dx * dx + dy * dy > 50.0 * 50.0 {
            return None;
        }
        if !self.unit_is_alive(player) {
            return None;
        }
        Some(player)
    }

    /// `npc_murkdeepAI::JustSummoned` (`darkshore.cpp:984-998`).
    fn murkdeep_just_summoned(&mut self, guid: ObjectGuid, summoned: ObjectGuid) {
        if let Some(player) = self.murkdeep_get_player(guid) {
            self.enter_combat(summoned, player);
        } else {
            self.despawn_creature_now(summoned, 0);
            // NEEDS-MAP-HELPER: `RemoveCorpse` (cpp 995).
            if let Some(s) = self.murkdeep_state_mut(guid) {
                s.event_state = false;
            }
        }
    }

    /// `npc_murkdeepAI::DoSummon` (`darkshore.cpp:1016-1032`).
    #[allow(clippy::needless_range_loop)]
    fn murkdeep_do_summon(&mut self, guid: ObjectGuid) {
        let phase = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Murkdeep(s)) => Some(s.event_phase),
                _ => None,
            })
            .unwrap_or(0);
        // Fork summons at the murkdeep's own orientation (cpp 1022-1029).
        let o = self.unit_position(guid).map_or(0.0, |p| p.o);
        let kind = FOULWEALD_TEMPSUMMON_TIMED_OR_DEAD;
        // 10 * MINUTE * IN_MILLISECONDS = 600_000.
        match phase {
            1 => {
                for point in MURKDEEP_SUMMON_POINTS {
                    self.summon_creature(
                        MURKDEEP_NPC_COATRUNNER,
                        Position::new(point.0, point.1, point.2, o),
                        guid,
                        kind,
                        600_000,
                    );
                }
            }
            2 => {
                for i in 0..2 {
                    let point = MURKDEEP_SUMMON_POINTS[i];
                    self.summon_creature(
                        MURKDEEP_NPC_WARRIOR,
                        Position::new(point.0, point.1, point.2, o),
                        guid,
                        kind,
                        600_000,
                    );
                }
            }
            3 => {
                let point = MURKDEEP_SUMMON_POINTS[1];
                self.summon_creature(
                    MURKDEEP_NPC_HUNTER,
                    Position::new(point.0, point.1, point.2, o),
                    guid,
                    kind,
                    600_000,
                );
            }
            _ => {}
        }
    }

    /// `npc_murkdeepAI::DoAttack` (`darkshore.cpp:1034-1060`).
    fn murkdeep_do_attack(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let sunder_due = {
            let Some(s) = self.murkdeep_state_mut(guid) else {
                return;
            };
            if s.sunder_armor_timer_ms < diff_ms {
                true
            } else {
                s.sunder_armor_timer_ms -= diff_ms;
                false
            }
        };
        if sunder_due {
            let victim = self.unit_victim(guid);
            // NEEDS-MAP-HELPER: `GetSpellAuraHolder(SPELL_SUNDER_ARMOR)`
            // stack < 5 gate (cpp 1039); `bot_has_aura` is bool-only.
            let has = victim.is_some_and(|v| self.bot_has_aura(v, MURKDEEP_SPELL_SUNDER_ARMOR));
            if has {
                if let Some(s) = self.murkdeep_state_mut(guid) {
                    s.sunder_armor_timer_ms = 5000;
                }
            } else if let Some(victim) = victim {
                if self.do_cast_spell_if_can(
                    guid,
                    MURKDEEP_SPELL_SUNDER_ARMOR,
                    CastTarget::Unit(victim),
                ) {
                    let next = self.rng.urand(5000, 9000);
                    if let Some(s) = self.murkdeep_state_mut(guid) {
                        s.sunder_armor_timer_ms = next;
                    }
                }
            }
        }
        let net_due = {
            let Some(s) = self.murkdeep_state_mut(guid) else {
                return;
            };
            if s.net_timer_ms < diff_ms {
                true
            } else {
                s.net_timer_ms -= diff_ms;
                false
            }
        };
        if net_due {
            let victim = self.unit_victim(guid);
            if let Some(victim) = victim {
                if self.do_cast_spell_if_can(guid, MURKDEEP_SPELL_NET, CastTarget::Unit(victim)) {
                    let next = self.rng.urand(9000, 15_000);
                    if let Some(s) = self.murkdeep_state_mut(guid) {
                        s.net_timer_ms = next;
                    }
                }
            }
        }
    }

    /// `npc_murkdeepAI::UpdateAI` (`darkshore.cpp:1062-1129`).
    fn murkdeep_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if self.get_hostile_target(guid).is_none() {
            // NEEDS-MAP-HELPER: `GetVisibility() == VISIBILITY_OFF` gate
            // (cpp 1066, 1096-1098); visibility has no helper.
            let (phase, event_state) = self
                .ai
                .get(&guid)
                .and_then(|ai| match &ai.script {
                    Some(CreatureScriptAi::Murkdeep(s)) => Some((s.event_phase, s.event_state)),
                    _ => None,
                })
                .unwrap_or((0, false));
            if phase == 0 && event_state {
                self.despawn_creature_now(guid, 0);
                // NEEDS-MAP-HELPER: `RemoveCorpse` (cpp 1068).
                return;
            }
            if phase != 0 {
                if !event_state {
                    self.despawn_creature_now(guid, 0);
                    // NEEDS-MAP-HELPER: `RemoveCorpse` (cpp 1077).
                    return;
                }
                let due = {
                    let Some(s) = self.murkdeep_state_mut(guid) else {
                        return;
                    };
                    if s.event_timer_ms < diff_ms {
                        true
                    } else {
                        s.event_timer_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    match phase {
                        1 | 2 => {
                            self.murkdeep_do_summon(guid);
                            if let Some(s) = self.murkdeep_state_mut(guid) {
                                s.event_timer_ms = 30_000;
                                s.event_phase += 1;
                            }
                        }
                        3 => {
                            self.murkdeep_do_summon(guid);
                            // NEEDS-MAP-HELPER: `RemoveFlag(UNIT_FIELD_FLAGS,
                            // UNIT_FLAG_IMMUNE_TO_NPC |
                            // UNIT_FLAG_IMMUNE_TO_PLAYER)` + visibility ON
                            // (cpp 1096-1098).
                            if let Some(player) = self.murkdeep_get_player(guid) {
                                self.attack_start(guid, player);
                            } else {
                                self.despawn_creature_now(guid, 0);
                                // NEEDS-MAP-HELPER: `RemoveCorpse` (cpp 1108).
                            }
                            if let Some(s) = self.murkdeep_state_mut(guid) {
                                s.event_phase = 0;
                            }
                        }
                        _ => {}
                    }
                }
            }
            return;
        }
        if !self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Murkdeep(s)) if s.has_fled),
        ) && self.creature_health_percent(guid) < 15.0
        {
            if let Some(s) = self.murkdeep_state_mut(guid) {
                s.has_fled = true;
            }
            self.do_flee(guid, false);
            return;
        }
        self.murkdeep_do_attack(guid, diff_ms);
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let _ = victim;
    }

