    /// `npc_magrami_spetreAI::turnGreen` (`desolace.cpp:409-415`).
    fn magrami_spetre_turn_green(&mut self, guid: ObjectGuid) {
        self.cancel_aura(guid, MAGRAMI_SPELL_BLUE_AURA);
        self.apply_aura_by_id(guid, MAGRAMI_SPELL_GREEN_AURA, guid);
        // NEEDS-MAP-HELPER: `SetFactionTemplateId(FACTION_ENNEMY)` (cpp 413).
        if let Some(s) = self.magrami_spectre_state_mut(guid) {
            s.is_green = true;
        }
    }

