    /// `npc_archmage_tervoshAI::UpdateAI` (`dustwallow_marsh.cpp:85-179`):
    /// event machine, else base (no-op here).
    #[allow(clippy::too_many_lines)]
    fn tervosh_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let (started, phase) = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::ArchmageTervosh(s)) => {
                    Some((s.event_started, s.event_phase))
                }
                _ => None,
            })
            .unwrap_or((false, TERVOSH_PHASE_ARRIVE));
        if !started {
            return;
        }
        match phase {
            TERVOSH_PHASE_PREPARE_TO_ARRIVE => {
                let due = {
                    let Some(s) = self.tervosh_state_mut(guid) else {
                        return;
                    };
                    if s.next_phase_delay_timer_ms < diff_ms {
                        true
                    } else {
                        s.next_phase_delay_timer_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    // NEEDS-MAP-HELPER: `SetVisibility(VISIBILITY_ON)` (cpp 95).
                    if let Some(s) = self.tervosh_state_mut(guid) {
                        s.next_phase_delay_timer_ms = 1000;
                        s.event_phase = TERVOSH_PHASE_ARRIVE;
                    }
                }
            }
            TERVOSH_PHASE_ARRIVE => {
                let due = {
                    let Some(s) = self.tervosh_state_mut(guid) else {
                        return;
                    };
                    if s.next_phase_delay_timer_ms < diff_ms {
                        true
                    } else {
                        s.next_phase_delay_timer_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    self.do_cast_spell_if_can(
                        guid,
                        TERVOSH_SPELL_TELEPORT_VISUAL_1,
                        CastTarget::SelfCast,
                    );
                    if let Some(s) = self.tervosh_state_mut(guid) {
                        s.next_phase_delay_timer_ms = 2000;
                        s.event_phase = TERVOSH_PHASE_GUARDS_SALUTE;
                    }
                }
            }
            TERVOSH_PHASE_GUARDS_SALUTE => {
                let due = {
                    let Some(s) = self.tervosh_state_mut(guid) else {
                        return;
                    };
                    if s.next_phase_delay_timer_ms < diff_ms {
                        true
                    } else {
                        s.next_phase_delay_timer_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    // Guards within 10 yd face Tervosh and salute (cpp 125-139).
                    let me = self.unit_position(guid).unwrap_or_default();
                    let guards: Vec<ObjectGuid> = self
                        .creatures
                        .iter()
                        .filter(|(_, c)| c.info.entry == TERVOSH_NPC_SENTRY_POINT_GUARD)
                        .filter_map(|(g, _)| {
                            self.object_position(*g).map(|p| {
                                let dx = p.x - me.x;
                                let dy = p.y - me.y;
                                (*g, dx * dx + dy * dy)
                            })
                        })
                        .filter(|(_, d)| *d <= 10.0 * 10.0)
                        .map(|(g, _)| g)
                        .filter(|g| self.unit_is_alive(*g))
                        .collect();
                    for guard in guards {
                        // NEEDS-MAP-HELPER: `IsInCombat` gate + `StopMoving` +
                        // `SetFacingToObject` (cpp 131-135).
                        self.handle_emote_command(guard, TERVOSH_EMOTE_SALUTE);
                    }
                    if let Some(s) = self.tervosh_state_mut(guid) {
                        s.event_phase = TERVOSH_PHASE_WAITING;
                    }
                }
            }
            TERVOSH_PHASE_WAITING => {
                let due = {
                    let Some(s) = self.tervosh_state_mut(guid) else {
                        return;
                    };
                    if s.despawn_delay_timer_ms < diff_ms {
                        true
                    } else {
                        s.despawn_delay_timer_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    self.do_cast_spell_if_can(
                        guid,
                        TERVOSH_SPELL_TELEPORT_VISUAL_2,
                        CastTarget::SelfCast,
                    );
                    if let Some(s) = self.tervosh_state_mut(guid) {
                        s.next_phase_delay_timer_ms = 2000;
                        s.event_phase = TERVOSH_PHASE_TELEPORT_BACK;
                    }
                }
            }
            TERVOSH_PHASE_TELEPORT_BACK => {
                let due = {
                    let Some(s) = self.tervosh_state_mut(guid) else {
                        return;
                    };
                    if s.next_phase_delay_timer_ms < diff_ms {
                        true
                    } else {
                        s.next_phase_delay_timer_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    // `static_cast<TemporarySummon*>(m_creature)->UnSummon()`
                    // (cpp 170).
                    self.despawn_creature_now(guid, 0);
                }
            }
            _ => {}
        }
    }

