    /// `npc_lady_jaina_proudmooreAI::UpdateAI` (`dustwallow_marsh.cpp:299-364`).
    fn jaina_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Extra `IsNonMeleeSpellCasted` gate (cpp 301).
        if self.bot_casting_spell(guid).is_some() {
            return;
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let special_due = {
            let Some(s) = self.jaina_state_mut(guid) else {
                return;
            };
            if s.special_timer_ms < diff_ms {
                true
            } else {
                s.special_timer_ms -= diff_ms;
                false
            }
        };
        if special_due {
            // Water-elemental arm gated by guardian count (no helper):
            // teleport arm transcribed, elemental arm NEEDS (cpp 306-309).
            if self.do_cast_spell_if_can(guid, JAINA_SPELL_TELEPORT, CastTarget::Unit(victim)) {
                // NEEDS-MAP-HELPER: `GetDistance2d(-4018.1, -4524.24) > 40`
                // gate + `_removeAttacker` / `modifyThreatPercent(-101)`
                // (cpp 317-323); threat re-percent exists as
                // `modify_threat_percent_of`.
                let next = self.rng.urand(10_000, 30_000);
                if let Some(s) = self.jaina_state_mut(guid) {
                    s.special_timer_ms = next;
                }
            }
        }
        let spell_due = {
            let Some(s) = self.jaina_state_mut(guid) else {
                return;
            };
            if s.spell_timer_ms < diff_ms {
                true
            } else {
                s.spell_timer_ms -= diff_ms;
                false
            }
        };
        if spell_due {
            match self.rng.urand(0, 4) {
                0 | 1 => {
                    if self.do_cast_spell_if_can(
                        guid,
                        JAINA_SPELL_FIREBALL,
                        CastTarget::Unit(victim),
                    ) {
                        let next = self.rng.urand(3000, 10_000);
                        if let Some(s) = self.jaina_state_mut(guid) {
                            s.spell_timer_ms = next;
                        }
                    }
                }
                2 | 3 => {
                    if self.do_cast_spell_if_can(
                        guid,
                        JAINA_SPELL_FIREBLAST,
                        CastTarget::Unit(victim),
                    ) {
                        let next = self.rng.urand(3000, 10_000);
                        if let Some(s) = self.jaina_state_mut(guid) {
                            s.spell_timer_ms = next;
                        }
                    }
                }
                _ => {
                    // `SelectRandomUnfriendlyTarget(nullptr, 25.0)` (cpp 351).
                    if let Some(target) = self.select_random_hostile(guid) {
                        if self.do_cast_spell_if_can(
                            guid,
                            JAINA_SPELL_BLIZZARD,
                            CastTarget::Unit(target),
                        ) {
                            let next = self.rng.urand(1000, 3000);
                            if let Some(s) = self.jaina_state_mut(guid) {
                                s.spell_timer_ms = next;
                            }
                        }
                    }
                }
            }
        }
    }

