    /// `npc_emberstrifeAI::Reset` (`dustwallow_marsh.cpp:610-616`).
    fn emberstrife_reset(&mut self, guid: ObjectGuid) {
        let cleave = self.rng.urand(6000, 8000);
        let breath = self.rng.urand(8000, 12_000);
        if let Some(s) = self.emberstrife_state_mut(guid) {
            s.cleave_timer_ms = cleave;
            s.frenzy_timer_ms = 0;
            s.flame_breath_timer_ms = breath;
            s.weakened = false;
        }
    }

    /// `npc_emberstrifeAI::UpdateAI` (`dustwallow_marsh.cpp:618-664`).
    fn emberstrife_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let weakened = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Emberstrife(s)) if s.weakened),
        );
        if !weakened && self.creature_health_percent(guid) < 11.0 {
            if let Some(s) = self.emberstrife_state_mut(guid) {
                s.weakened = true;
            }
            self.do_script_text(EMBERSTRIFE_EMOTE_WEAKENED, guid, None, -1);
        }
        let cleave_due = {
            let Some(s) = self.emberstrife_state_mut(guid) else {
                return;
            };
            if s.cleave_timer_ms < diff_ms {
                true
            } else {
                s.cleave_timer_ms -= diff_ms;
                false
            }
        };
        if cleave_due
            && self.do_cast_spell_if_can(guid, EMBERSTRIFE_SPELL_CLEAVE, CastTarget::Unit(victim))
        {
            let next = self.rng.urand(6000, 8000);
            if let Some(s) = self.emberstrife_state_mut(guid) {
                s.cleave_timer_ms = next;
            }
        }
        let breath_due = {
            let Some(s) = self.emberstrife_state_mut(guid) else {
                return;
            };
            if s.flame_breath_timer_ms < diff_ms {
                true
            } else {
                s.flame_breath_timer_ms -= diff_ms;
                false
            }
        };
        if breath_due
            && self.do_cast_spell_if_can(
                guid,
                EMBERSTRIFE_SPELL_FLAME_BREATH,
                CastTarget::Unit(victim),
            )
        {
            let next = self.rng.urand(8000, 12_000);
            if let Some(s) = self.emberstrife_state_mut(guid) {
                s.flame_breath_timer_ms = next;
            }
        }
        // Frenzy below 60% (cpp 649-661); 2 * MINUTE * IN_MILLISECONDS +
        // 500 = 120_500.
        if self.creature_health_percent(guid) < 60.0 {
            let frenzy_due = {
                let Some(s) = self.emberstrife_state_mut(guid) else {
                    return;
                };
                if s.frenzy_timer_ms < diff_ms {
                    true
                } else {
                    s.frenzy_timer_ms -= diff_ms;
                    false
                }
            };
            if frenzy_due
                && self.do_cast_spell_if_can(guid, EMBERSTRIFE_SPELL_FRENZY, CastTarget::SelfCast)
            {
                self.do_script_text(EMBERSTRIFE_EMOTE_FRENZY_KILL, guid, None, -1);
                if let Some(s) = self.emberstrife_state_mut(guid) {
                    s.frenzy_timer_ms = 120_500;
                }
            }
        }
    }

