    /// `npc_colossusAI::Reset` (`silithus.cpp:543-548`).
    fn colossus_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.colossus_state_mut(guid) {
            s.first_smash = true;
            s.colossal_smash_timer_ms = 60_000;
            s.colossal_smash_emote_timer_ms = 0;
        }
        // Ctor yell-by-entry (cpp 519-537): said once.
        let said = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Colossus(s)) if s.intro_said),
        );
        if !said {
            let entry = self.object_entry(guid);
            let text = if entry == Some(COLOSSUS_NPC_ASHI) {
                Some(COLOSSUS_TEXT_ASHI)
            } else if entry == Some(COLOSSUS_NPC_REGAL) {
                Some(COLOSSUS_TEXT_REGAL)
            } else if entry == Some(COLOSSUS_NPC_ZORA) {
                Some(COLOSSUS_TEXT_ZORA)
            } else {
                None
            };
            if let Some(text) = text {
                self.do_script_text(text, guid, None, -1);
            }
            if let Some(s) = self.colossus_state_mut(guid) {
                s.intro_said = true;
            }
        }
    }

