    /// `npc_colossusAI::UpdateAI` (`silithus.cpp:563-591`).
    fn colossus_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let smash_due = {
            let Some(s) = self.colossus_state_mut(guid) else {
                return;
            };
            if s.colossal_smash_timer_ms < diff_ms {
                true
            } else {
                s.colossal_smash_timer_ms -= diff_ms;
                false
            }
        };
        if smash_due
            && self.do_cast_spell_if_can(guid, COLOSSUS_SPELL_COLOSSAL_SMASH, CastTarget::SelfCast)
        {
            // NEEDS-MAP-HELPER: `MonsterTextEmote` literals (cpp 572/584).
            if let Some(s) = self.colossus_state_mut(guid) {
                s.colossal_smash_timer_ms = if s.first_smash { 10_000 } else { 60_000 };
                s.colossal_smash_emote_timer_ms = 5000;
                s.first_smash = !s.first_smash;
            }
        }
        let emote_due = {
            let Some(s) = self.colossus_state_mut(guid) else {
                return;
            };
            if s.colossal_smash_emote_timer_ms != 0 && s.colossal_smash_emote_timer_ms < diff_ms {
                s.colossal_smash_emote_timer_ms = 0;
                true
            } else {
                if let Some(s) = self.colossus_state_mut(guid) {
                    s.colossal_smash_emote_timer_ms =
                        s.colossal_smash_emote_timer_ms.saturating_sub(diff_ms);
                }
                false
            }
        };
        if emote_due {
            // NEEDS-MAP-HELPER: `MonsterTextEmote` (cpp 584).
        }
        let _ = victim;
    }

