    /// `npc_Geologist_LarksbaneAI::UpdateAI` (`silithus.cpp:892-901`).
    fn larksbane_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let action = self.larksbane_state_mut(guid).map_or(0, |s| s.curr_action);
        if action == 0 {
            return;
        }
        let due = {
            let Some(s) = self.larksbane_state_mut(guid) else {
                return;
            };
            if s.next_action_timer_ms < diff_ms {
                true
            } else {
                s.next_action_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            self.larksbane_do_action(guid);
        }
    }

