    /// `npc_Emissary_RomankhanAI::SpellHitTarget` (`silithus.cpp:963-984`).
    fn romankhan_spell_hit_target(&mut self, guid: ObjectGuid, target: ObjectGuid, spell_id: u32) {
        if !target.is_player() {
            return;
        }
        if spell_id != ROMANKHAN_SPELL_WILT
            && spell_id != ROMANKHAN_SPELL_SUFFERING_OF_SANITY
            && spell_id != ROMANKHAN_SPELL_SYSTEM_SHOCK
        {
            return;
        }
        if let Some(s) = self.romankhan_state_mut(guid) {
            if s.player_guids.contains(&target) {
                return;
            }
            if let Some(slot) = s.player_guids.iter_mut().find(|g| g.is_empty()) {
                *slot = target;
            }
            s.need_check = true;
        }
    }

    /// `npc_Emissary_RomankhanAI::UpdateAI` (`silithus.cpp:986-1063`).
    #[allow(clippy::too_many_lines)]
    fn romankhan_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let _ = victim;
        let shock_due = {
            let Some(s) = self.romankhan_state_mut(guid) else {
                return;
            };
            if s.shock_timer_ms < diff_ms {
                true
            } else {
                s.shock_timer_ms -= diff_ms;
                false
            }
        };
        if shock_due {
            // `SelectAttackingTarget(ATTACKING_TARGET_RANDOM, 0)` (cpp 993).
            if let Some(target) =
                self.select_attacking_target(guid, 0, 0, ROMANKHAN_SELECT_FLAG_NO_TOTEM)
            {
                if target.is_player() {
                    if self.do_cast_spell_if_can(
                        guid,
                        ROMANKHAN_SPELL_SYSTEM_SHOCK,
                        CastTarget::Unit(target),
                    ) {
                        let next = self.rng.urand(6000, 10_000);
                        if let Some(s) = self.romankhan_state_mut(guid) {
                            s.shock_timer_ms = next;
                        }
                    }
                } else if let Some(s) = self.romankhan_state_mut(guid) {
                    s.shock_timer_ms = 1000;
                }
            }
        }
        let wilt_due = {
            let Some(s) = self.romankhan_state_mut(guid) else {
                return;
            };
            if s.wilt_timer_ms < diff_ms {
                true
            } else {
                s.wilt_timer_ms -= diff_ms;
                false
            }
        };
        if wilt_due {
            if let Some(s) = self.romankhan_state_mut(guid) {
                s.player_guids.fill(ObjectGuid::EMPTY);
            }
            if self.do_cast_spell_if_can(guid, ROMANKHAN_SPELL_WILT, CastTarget::SelfCast) {
                let next = self.rng.urand(3000, 5000);
                if let Some(s) = self.romankhan_state_mut(guid) {
                    s.wilt_timer_ms = next;
                }
            }
        }
        // Mana-gated sanity cast (cpp 1017-1030): mana percent and
        // `SetPower` have no helper (see unresolved).
        let sanity_due = {
            let Some(s) = self.romankhan_state_mut(guid) else {
                return;
            };
            if s.sanity_timer_ms < diff_ms {
                true
            } else {
                s.sanity_timer_ms -= diff_ms;
                false
            }
        };
        if sanity_due {
            // NEEDS-MAP-HELPER: `GetManaPercent() == 100.0` gate (cpp 1017).
            if let Some(s) = self.romankhan_state_mut(guid) {
                s.player_guids.fill(ObjectGuid::EMPTY);
            }
            if self.do_cast_spell_if_can(
                guid,
                ROMANKHAN_SPELL_SUFFERING_OF_SANITY,
                CastTarget::SelfCast,
            ) {
                if let Some(s) = self.romankhan_state_mut(guid) {
                    s.sanity_timer_ms = 1000;
                }
            }
        }
        if !self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::EmissaryRomankhan(s)) if s.need_check),
        ) {
            return;
        }
        let check_due = {
            let Some(s) = self.romankhan_state_mut(guid) else {
                return;
            };
            if s.check_player_timer_ms < diff_ms {
                true
            } else {
                s.check_player_timer_ms -= diff_ms;
                false
            }
        };
        if !check_due {
            return;
        }
        let tracked: Vec<ObjectGuid> = self
            .romankhan_state_mut(guid)
            .map(|s| s.player_guids.to_vec())
            .unwrap_or_default();
        for tracked_guid in tracked {
            if tracked_guid.is_empty() {
                continue;
            }
            // NEEDS-MAP-HELPER: `GetMap()->GetUnit(guid)` cross-map lookup
            // (cpp 1044); player lookup below approximates it.
            if !self.players.contains_key(&tracked_guid) {
                continue;
            }
            self.enter_combat(tracked_guid, guid);
            if !self.unit_is_alive(tracked_guid) {
                // NEEDS-MAP-HELPER: +2% mana per death (cpp 1052).
                if let Some(s) = self.romankhan_state_mut(guid) {
                    if let Some(slot) = s.player_guids.iter_mut().find(|g| **g == tracked_guid) {
                        *slot = ObjectGuid::EMPTY;
                    }
                }
            }
        }
        if let Some(s) = self.romankhan_state_mut(guid) {
            s.need_check = false;
            s.check_player_timer_ms = 1000;
        }
    }

