    fn hunter_killer_state_mut(
        &mut self,
        guid: ObjectGuid,
    ) -> Option<&mut HiveRegalHunterKillerAi> {
        self.ai.get_mut(&guid).and_then(|ai| match &mut ai.script {
            Some(CreatureScriptAi::HiveRegalHunterKiller(s)) => Some(s),
            _ => None,
        })
    }

    /// `mob_HiveRegal_HunterKillerAI::Reset` (`silithus.cpp:2329-2340`).
    fn hunter_killer_reset(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: `GetOrientation()` + `MovePoint(WAYPOINT_ID + 1,
        // ...)` initial move (cpp 2331-2337).
        if let Some(s) = self.hunter_killer_state_mut(guid) {
            s.thunderclap_timer_ms = 17_000;
            s.fear_timer_ms = 0;
            s.charge_timer_ms = 0;
            s.cleave_timer_ms = 0;
            s.move_timer_ms = 0;
            s.waypoint = 0;
            s.reached_camp = false;
        }
    }

    /// `mob_HiveRegal_HunterKillerAI::UpdateAI` (`silithus.cpp:2342-2411`).
    #[allow(clippy::too_many_lines)]
    fn hunter_killer_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let reached = self
            .hunter_killer_state_mut(guid)
            .is_some_and(|s| s.reached_camp);
        // Camp walk (cpp 2344-2361): distance / walk speed per waypoint.
        if !reached {
            let move_due = {
                let Some(s) = self.hunter_killer_state_mut(guid) else {
                    return;
                };
                if s.move_timer_ms <= diff_ms {
                    true
                } else {
                    s.move_timer_ms -= diff_ms;
                    false
                }
            };
            if move_due {
                let waypoint = self.hunter_killer_state_mut(guid).map_or(0, |s| s.waypoint);
                if waypoint > 14 {
                    let krug = self.nearest_creature_with_entry(guid, HUNTERKILLER_NPC_KRUG, 50.0);
                    if let Some(krug) = krug {
                        self.attack_start(guid, krug);
                    }
                    // NEEDS-MAP-HELPER: `SetHomePosition` + `MoveHome`
                    // (cpp 2350-2351).
                    if let Some(s) = self.hunter_killer_state_mut(guid) {
                        s.reached_camp = true;
                    }
                } else if waypoint != 0 {
                    // NEEDS-MAP-HELPER: `GetSpeed(MOVE_WALK)` read for
                    // `moveTimer = dist / speed * 1000` (cpp 2355-2358).
                    if let Some(next) = HUNTERKILLER_WAYPOINTS.get(waypoint as usize + 1) {
                        self.creature_move_point(
                            guid,
                            0,
                            Position::new(next.0, next.1, next.2, 0.0),
                            0,
                            0.0,
                            0.0,
                        );
                    }
                    if let Some(s) = self.hunter_killer_state_mut(guid) {
                        s.waypoint = s.waypoint.wrapping_add(1);
                    }
                }
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Victim-in-range gate for the spell arms (cpp 2363-2366).
        let in_range = match (self.unit_position(guid), self.unit_position(victim)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy <= 6.0 * 6.0
            }
            _ => false,
        };
        if !in_range {
            return;
        }
        let thunder_due = {
            let Some(s) = self.hunter_killer_state_mut(guid) else {
                return;
            };
            if s.thunderclap_timer_ms <= diff_ms {
                true
            } else {
                s.thunderclap_timer_ms -= diff_ms;
                false
            }
        };
        if thunder_due
            && self.do_cast_spell_if_can(guid, HUNTERKILLER_SPELL_THUNDERCLAP, CastTarget::SelfCast)
        {
            let next = self.rng.urand(17_000, 20_000);
            if let Some(s) = self.hunter_killer_state_mut(guid) {
                s.thunderclap_timer_ms = next;
            }
        }
        let charge_due = {
            let Some(s) = self.hunter_killer_state_mut(guid) else {
                return;
            };
            if s.charge_timer_ms <= diff_ms {
                true
            } else {
                s.charge_timer_ms -= diff_ms;
                false
            }
        };
        if charge_due {
            // `GetVictimInRangePlayerOnly(30, true)` (cpp 2384): iterate
            // threat list for in-range players.
            let target = self
                .threat_targets_sorted(guid)
                .into_iter()
                .filter(|t| t.is_player() && self.unit_is_alive(*t))
                .find(
                    |t| match (self.unit_position(guid), self.unit_position(*t)) {
                        (Some(a), Some(b)) => {
                            let dx = a.x - b.x;
                            let dy = a.y - b.y;
                            dx * dx + dy * dy <= 25.0 * 25.0
                        }
                        _ => false,
                    },
                );
            if let Some(target) = target {
                if self.do_cast_spell_if_can(
                    guid,
                    HUNTERKILLER_SPELL_CHARGE,
                    CastTarget::Unit(target),
                ) {
                    if let Some(s) = self.hunter_killer_state_mut(guid) {
                        s.charge_timer_ms = 7000;
                    }
                }
            }
        }
        let cleave_due = {
            let Some(s) = self.hunter_killer_state_mut(guid) else {
                return;
            };
            if s.cleave_timer_ms <= diff_ms {
                true
            } else {
                s.cleave_timer_ms -= diff_ms;
                false
            }
        };
        if cleave_due
            && self.do_cast_spell_if_can(guid, HUNTERKILLER_SPELL_CLEAVE, CastTarget::Unit(victim))
        {
            if let Some(s) = self.hunter_killer_state_mut(guid) {
                s.cleave_timer_ms = 7000;
            }
        }
        let fear_due = {
            let Some(s) = self.hunter_killer_state_mut(guid) else {
                return;
            };
            if s.fear_timer_ms <= diff_ms {
                true
            } else {
                s.fear_timer_ms -= diff_ms;
                false
            }
        };
        if fear_due
            && self.do_cast_spell_if_can(guid, HUNTERKILLER_SPELL_FEAR, CastTarget::SelfCast)
        {
            let next = self.rng.urand(8000, 20_000);
            if let Some(s) = self.hunter_killer_state_mut(guid) {
                s.fear_timer_ms = next;
            }
        }
    }

