    /// `npc_Krug_SkullSplitAI::UpdateAI` (`silithus.cpp:2619-2678`).
    #[allow(clippy::too_many_lines)]
    fn krug_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let (status, already_moved) = self
            .krug_state_mut(guid)
            .map_or((KRUG_EVENT_NOT_STARTED, true), |s| {
                (s.event_status, s.already_moved)
            });
        // Reset-timer arm (cpp 2622-2633).
        let reset_due = {
            let Some(s) = self.krug_state_mut(guid) else {
                return;
            };
            if s.event_reset_timer_ms < diff_ms {
                true
            } else {
                s.event_reset_timer_ms -= diff_ms;
                false
            }
        };
        if reset_due {
            if status == KRUG_EVENT_STARTED || status == KRUG_EVENT_COMPLETE {
                self.krug_reset_event(guid);
                return;
            } else if let Some(s) = self.krug_state_mut(guid) {
                s.event_reset_timer_ms = 120_000;
            }
        }
        if status == KRUG_EVENT_NOT_STARTED {
            return;
        }
        if already_moved {
            if let Some(s) = self.krug_state_mut(guid) {
                s.move_timer_ms = 10_000;
                s.already_moved = false;
            }
            if status == KRUG_EVENT_COMPLETE {
                self.krug_reset_other_npc_positions(guid);
            } else {
                // Move Merok/Shai to spawn positions (cpp 2645-2657).
                let (merok, shai) = self
                    .krug_state_mut(guid)
                    .map_or((ObjectGuid::EMPTY, ObjectGuid::EMPTY), |s| {
                        (s.merok_guid, s.shai_guid)
                    });
                if self.creatures.contains_key(&merok) {
                    let d = KRUG_MEROK_SPAWN;
                    self.creature_move_point(
                        merok,
                        0,
                        Position::new(d.0, d.1, d.2, 0.0),
                        0,
                        0.0,
                        0.0,
                    );
                }
                if self.creatures.contains_key(&shai) {
                    let d = KRUG_SHAI_SPAWN;
                    self.creature_move_point(
                        shai,
                        0,
                        Position::new(d.0, d.1, d.2, 0.0),
                        0,
                        0.0,
                        0.0,
                    );
                }
            }
        }
        let doing = self.krug_state_mut(guid).is_some_and(|s| s.doing_speech);
        if !doing {
            return;
        }
        let grunt_due = {
            let Some(s) = self.krug_state_mut(guid) else {
                return;
            };
            if s.grunt_speech_timer_ms < diff_ms {
                true
            } else {
                s.grunt_speech_timer_ms -= diff_ms;
                false
            }
        };
        if grunt_due {
            // Grunt scan (cpp 2664-2672): alive grunts within 30 yd say line 7.
            let me = self.unit_position(guid).unwrap_or_default();
            let grunts: Vec<ObjectGuid> = self
                .creatures
                .iter()
                .filter(|(_, c)| c.info.entry == HUNTERKILLER_NPC_GRUNT)
                .filter_map(|(g, _)| {
                    self.object_position(*g).map(|p| {
                        let dx = p.x - me.x;
                        let dy = p.y - me.y;
                        (*g, dx * dx + dy * dy)
                    })
                })
                .filter(|(_, d)| *d <= 30.0 * 30.0)
                .map(|(g, _)| g)
                .filter(|g| self.unit_is_alive(*g))
                .collect();
            for grunt in grunts {
                self.do_script_text(HUNTERKILLER_SAY_LINE_7, grunt, None, -1);
            }
            if let Some(s) = self.krug_state_mut(guid) {
                s.grunt_speech = false;
                s.speech_num = s.speech_num.wrapping_add(1);
                s.speech_timer_ms = 4000;
            }
        }
        let speech_due = {
            let Some(s) = self.krug_state_mut(guid) else {
                return;
            };
            if s.speech_timer_ms < diff_ms {
                true
            } else {
                s.speech_timer_ms -= diff_ms;
                false
            }
        };
        if speech_due && self.krug_state_mut(guid).is_some_and(|s| s.grunt_speech) {
            let num = self.krug_state_mut(guid).map_or(0, |s| s.speech_num);
            let text = match num {
                1 => Some(HUNTERKILLER_SAY_LINE_1),
                2 => Some(HUNTERKILLER_SAY_LINE_2),
                3 => Some(HUNTERKILLER_SAY_LINE_3),
                4 => Some(HUNTERKILLER_SAY_LINE_4),
                5 => Some(HUNTERKILLER_SAY_LINE_5),
                6 => Some(HUNTERKILLER_SAY_LINE_6),
                7 => Some(HUNTERKILLER_SAY_LINE_7),
                8 => Some(HUNTERKILLER_SAY_LINE_8),
                9 => Some(HUNTERKILLER_SAY_LINE_9),
                _ => None,
            };
            if let Some(text) = text {
                self.do_script_text(text, guid, None, -1);
                if num == 9 {
                    // NEEDS-MAP-HELPER: hunters `CastSpell(HK, THUNDERCLAP)`
                    // (cpp 2604-2605 bowdlerized): the hunter-killer cast
                    // below approximates `DoCastSpellIfCan`.
                    let hk = self
                        .krug_state_mut(guid)
                        .map_or(ObjectGuid::EMPTY, |s| s.hunter_killer_guid);
                    if self.creatures.contains_key(&hk) {
                        self.do_cast_spell_if_can(
                            hk,
                            HUNTERKILLER_SPELL_THUNDERCLAP,
                            CastTarget::SelfCast,
                        );
                    }
                    if let Some(s) = self.krug_state_mut(guid) {
                        s.doing_speech = false;
                    }
                }
            }
            if let Some(s) = self.krug_state_mut(guid) {
                s.grunt_speech = true;
                s.grunt_speech_timer_ms = 15_000;
            }
        }
    }

