    /// `npc_MerokAI::UpdateAI` (`silithus.cpp:2741-2764`).
    fn merok_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if self.get_hostile_target(guid).is_none() {
            return;
        }
        // `IsNonMeleeSpellCasted` gate (cpp 2744).
        if self.bot_casting_spell(guid).is_some() {
            return;
        }
        let due = {
            let Some(s) = self.merok_state_mut(guid) else {
                return;
            };
            if s.healing_wave_ms < diff_ms {
                true
            } else {
                s.healing_wave_ms -= diff_ms;
                false
            }
        };
        if due && self.do_cast_spell_if_can(guid, MEROK_SPELL_HEALING_WAVE, CastTarget::SelfCast) {
            // `FindLowestHpFriendlyUnit(60.0, 1)` retargets onto an ally
            // (cpp 2749): heal the lowest-HP friendly unit in 60 yd.
            if let Some(target) = self.lowest_hp_friendly(guid, 60.0, 1, None) {
                let _ = self.do_cast_spell_if_can(
                    guid,
                    MEROK_SPELL_HEALING_WAVE,
                    CastTarget::Unit(target),
                );
            }
            let next = self.rng.urand(15_000, 25_000);
            if let Some(s) = self.merok_state_mut(guid) {
                s.healing_wave_ms = next;
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let _ = victim;
    }

