    /// `mob_captured_felwood_oozeAI::UpdateAI` (`ungoro_crater.cpp:365-393`):
    /// OOC merge machine, no combat head.
    fn ooze_primal_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let (initial, merged) = self
            .ooze_primal_state_mut(guid)
            .map_or((0, true), |s| (s.initial_timer_ms, s.merge_done));
        if initial != 0 && !merged {
            let due = {
                let Some(s) = self.ooze_primal_state_mut(guid) else {
                    return;
                };
                if s.initial_timer_ms < diff_ms {
                    true
                } else {
                    s.initial_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                if self
                    .nearest_creature_with_entry(guid, OOZE_PRIMAL_NPC_PRIMAL_OOZE, 10.0)
                    .is_none()
                {
                    // NEEDS-MAP-HELPER: `MoveFollow(pPrimal, PET_FOLLOW_DIST,
                    // PET_FOLLOW_ANGLE)` (cpp 377).
                }
                if let Some(s) = self.ooze_primal_state_mut(guid) {
                    s.initial_timer_ms = 0;
                }
            }
        }
        let due = {
            let Some(s) = self.ooze_primal_state_mut(guid) else {
                return;
            };
            if s.initial_timer_ms < diff_ms {
                true
            } else {
                s.initial_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            if let Some(primal) =
                self.nearest_creature_with_entry(guid, OOZE_PRIMAL_NPC_PRIMAL_OOZE, 10.0)
            {
                // `GetDistance2d(pPrimal) <= PET_FOLLOW_DIST` merge (cpp 385).
                let close = match (self.unit_position(guid), self.unit_position(primal)) {
                    (Some(a), Some(b)) => {
                        let dx = a.x - b.x;
                        let dy = a.y - b.y;
                        dx * dx + dy * dy <= 2.0 * 2.0
                    }
                    _ => false,
                };
                if close {
                    self.do_cast_spell_if_can(
                        guid,
                        OOZE_PRIMAL_SPELL_MERGING,
                        CastTarget::SelfCast,
                    );
                    // NEEDS-MAP-HELPER: `DespawnOrUnsummon(5000)` timed arm
                    // (cpp 389).
                    self.despawn_creature_now(guid, 0);
                }
            }
        }
    }

