    /// `npc_simone_the_inconspicuousAI::UpdateAI` (`ungoro_crater.cpp:804-815`).
    fn inconspicuous_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let transform = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::SimoneInconspicuous(s)) if s.transform)
        });
        if !transform {
            return;
        }
        let emote_due = {
            let Some(s) = self.inconspicuous_state_mut(guid) else {
                return;
            };
            if s.transform_emote_timer_ms == 0 {
                false
            } else if s.transform_emote_timer_ms <= diff_ms {
                s.transform_emote_timer_ms = 0;
                true
            } else {
                s.transform_emote_timer_ms -= diff_ms;
                false
            }
        };
        if emote_due {
            self.handle_emote_command(guid, INCONSPICUOUS_EMOTE_SHOUT);
        }
        let due = {
            let Some(s) = self.inconspicuous_state_mut(guid) else {
                return;
            };
            if s.transform_timer_ms < diff_ms {
                true
            } else {
                s.transform_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            if let Some(s) = self.inconspicuous_state_mut(guid) {
                s.transform = false;
            }
            self.inconspicuous_transform(guid);
        }
    }

