    /// `npc_artoriusAI::Reset` (`winterspring.cpp:75-105`).
    fn artorius_reset(&mut self, guid: ObjectGuid) {
        let entry = self.object_entry(guid);
        if entry == Some(ARTORIUS_NPC_AMIABLE) {
            if let Some(s) = self.artorius_state_mut(guid) {
                s.transform_timer_ms = 10_000;
                s.transform_emote_timer_ms = 5000;
                s.transform = false;
                s.despawn_timer_ms = 0;
            }
        } else if entry == Some(ARTORIUS_NPC_DOOMBRINGER) {
            let frenzy = self.rng.urand(5000, 8000);
            if let Some(s) = self.artorius_state_mut(guid) {
                s.hunter_guid = ObjectGuid::EMPTY;
                s.demonic_doom_timer_ms = 7500;
                s.demonic_frenzy_timer_ms = frenzy;
                // 20 * MINUTE * IN_MILLISECONDS = 1_200_000.
                if s.despawn_timer_ms == 0 {
                    s.despawn_timer_ms = 1_200_000;
                }
            }
        }
        // NEEDS-MAP-HELPER: `SetUInt32Value(UNIT_NPC_FLAGS,
        // UNIT_NPC_FLAG_GOSSIP)` on the amiable arm (cpp 89).
    }

    /// `npc_artoriusAI::Transform` (`winterspring.cpp:107-115`).
    fn artorius_transform(&mut self, guid: ObjectGuid) {
        self.handle_emote_command(guid, ARTORIUS_EMOTE_ROAR);
        // NEEDS-MAP-HELPER: `UpdateEntry(NPC_ARTORIUS_THE_DOOMBRINGER)` (cpp
        // 110) + `SetHomePosition` + `SetDefaultMovementType(IDLE)` +
        // `GetMotionMaster()->Initialize()` (cpp 111-113).
        self.artorius_reset(guid);
    }

