    /// `npc_artoriusAI::Aggro` (`winterspring.cpp:127-135`).
    fn artorius_aggro(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        // NEEDS-MAP-HELPER: `pWho->GetClass() == CLASS_HUNTER` via
        // `NEFARIAN_CLASS_HUNTER` (cpp 129).
        let hunter = self
            .artorius_state_mut(guid)
            .map_or(ObjectGuid::EMPTY, |s| s.hunter_guid);
        if who.is_player() && (hunter.is_empty() || hunter == who) {
            if let Some(s) = self.artorius_state_mut(guid) {
                s.hunter_guid = who;
            }
        } else {
            self.artorius_demon_despawn(guid, true);
        }
    }

