    /// `npc_artoriusAI::DemonDespawn` (`winterspring.cpp:151-181`).
    fn artorius_demon_despawn(&mut self, guid: ObjectGuid, triggered: bool) {
        // NEEDS-MAP-HELPER: `SetHomePosition` + `SetRespawnDelay/Time(15 *
        // MINUTE)` + `SaveRespawnTime` (cpp 153-156).
        if triggered {
            if let Some(cleaner) = self.summon_creature(
                SOLENOR_NPC_THE_CLEANER,
                self.unit_position(guid).unwrap_or_default(),
                guid,
                FOULWEALD_TEMPSUMMON_TIMED_OR_DEAD,
                1_200_000,
            ) {
                // Threat-list transfer (cpp 163-177).
                for victim in self.threat_targets_sorted(guid) {
                    if self.unit_is_alive(victim) {
                        self.enter_combat(cleaner, victim);
                        self.add_threat(cleaner, victim, 100.0);
                        self.attack_start(cleaner, victim);
                    }
                }
            }
        }
        self.despawn_creature_now(guid, 0);
    }

    /// `npc_artoriusAI::SpellHit` (`winterspring.cpp:183-190`).
    fn artorius_spell_hit(&mut self, guid: ObjectGuid, _caster: ObjectGuid, spell_id: u32) {
        if spell_id != ARTORIUS_SPELL_SERPENT_STING_R8
            && spell_id != ARTORIUS_SPELL_SERPENT_STING_R9
        {
            return;
        }
        // `DoCastSpellIfCan(me, SPELL_STINGING_TRAUMA, CF_TRIGGERED)` (cpp 187).
        let _ = self.cast_spell(
            guid,
            ARTORIUS_SPELL_STINGING_TRAUMA,
            CastTarget::SelfCast,
            CastOptions {
                triggered: true,
                skip_known: true,
                ..Default::default()
            },
        );
        self.do_script_text(ARTORIUS_EMOTE_POISON, guid, None, -1);
    }

    /// `npc_artoriusAI::UpdateAI` (`winterspring.cpp:192-255`).
    #[allow(clippy::too_many_lines)]
    fn artorius_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let transform = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Artorius(s)) if s.transform),
        );
        if transform {
            let emote_due = {
                let Some(s) = self.artorius_state_mut(guid) else {
                    return;
                };
                if s.transform_emote_timer_ms == 0 {
                    false
                } else if s.transform_emote_timer_ms <= diff_ms {
                    s.transform_emote_timer_ms = 0;
                    true
                } else {
                    s.transform_emote_timer_ms -= diff_ms;
                    false
                }
            };
            if emote_due {
                self.handle_emote_command(guid, ARTORIUS_EMOTE_ROAR);
            }
            let due = {
                let Some(s) = self.artorius_state_mut(guid) else {
                    return;
                };
                if s.transform_timer_ms < diff_ms {
                    true
                } else {
                    s.transform_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                if let Some(s) = self.artorius_state_mut(guid) {
                    s.transform = false;
                }
                self.artorius_transform(guid);
            }
        }
        let despawn = self
            .artorius_state_mut(guid)
            .map_or(0, |s| s.despawn_timer_ms);
        if despawn != 0 {
            if despawn <= diff_ms {
                if self.unit_is_alive(guid) && !self.ai_in_combat(guid) {
                    self.artorius_demon_despawn(guid, false);
                }
            } else if let Some(s) = self.artorius_state_mut(guid) {
                s.despawn_timer_ms -= diff_ms;
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Multi-threat despawn (cpp 232-233).
        if self.threat_targets_sorted(guid).len() > 1 {
            self.artorius_demon_despawn(guid, true);
            return;
        }
        let frenzy_due = {
            let Some(s) = self.artorius_state_mut(guid) else {
                return;
            };
            if s.demonic_frenzy_timer_ms < diff_ms {
                true
            } else {
                s.demonic_frenzy_timer_ms -= diff_ms;
                false
            }
        };
        if frenzy_due
            && self.do_cast_spell_if_can(guid, ARTORIUS_SPELL_DEMONIC_FRENZY, CastTarget::SelfCast)
        {
            let next = self.rng.urand(15_000, 20_000);
            if let Some(s) = self.artorius_state_mut(guid) {
                s.demonic_frenzy_timer_ms = next;
            }
        }
        let doom_due = {
            let Some(s) = self.artorius_state_mut(guid) else {
                return;
            };
            if s.demonic_doom_timer_ms < diff_ms {
                true
            } else {
                s.demonic_doom_timer_ms -= diff_ms;
                false
            }
        };
        if doom_due {
            // Rearmed unconditionally (cpp 245); cast gated on 25 yd (cpp 248).
            if let Some(s) = self.artorius_state_mut(guid) {
                s.demonic_doom_timer_ms = 7500;
            }
            let close = match (self.unit_position(guid), self.unit_position(victim)) {
                (Some(a), Some(b)) => {
                    let dx = a.x - b.x;
                    let dy = a.y - b.y;
                    dx * dx + dy * dy <= 25.0 * 25.0
                }
                _ => false,
            };
            if close {
                self.do_cast_spell_if_can(
                    guid,
                    ARTORIUS_SPELL_DEMONIC_DOOM,
                    CastTarget::Unit(victim),
                );
            }
        }
    }

