    /// `npc_sarilus_foulborneAI::Reset` (`the_barrens.cpp:639-643`).
    fn sarilus_reset(&mut self, guid: ObjectGuid) {
        let elementals = self.rng.urand(7000, 12_000);
        let frostbolt = self.rng.urand(5000, 8000);
        if let Some(s) = self.sarilus_state_mut(guid) {
            s.elementals_timer_ms = elementals;
            s.frostbolt_timer_ms = frostbolt;
        }
    }

    /// `npc_sarilus_foulborneAI::JustSummoned` (`the_barrens.cpp:645-653`).
    fn sarilus_just_summoned(&mut self, guid: ObjectGuid, summoned: ObjectGuid) {
        // `DoCastSpellIfCan(pSummoned, SPELL_ELEMENTALS_PASSIVE, true)` (cpp
        // 647): triggered self-aura on the elemental + victim redirect.
        let _ = self.cast_spell(
            summoned,
            SARILUS_SPELL_ELEMENTALS_PASSIVE,
            CastTarget::SelfCast,
            CastOptions {
                triggered: true,
                skip_known: true,
                ..Default::default()
            },
        );
        if let Some(victim) = self.unit_victim(guid) {
            self.attack_start(summoned, victim);
        }
    }

    /// `npc_sarilus_foulborneAI::UpdateAI` (`the_barrens.cpp:655-679`).
    fn sarilus_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let frost_due = {
            let Some(s) = self.sarilus_state_mut(guid) else {
                return;
            };
            if s.frostbolt_timer_ms < diff_ms {
                true
            } else {
                s.frostbolt_timer_ms -= diff_ms;
                false
            }
        };
        if frost_due
            && self.do_cast_spell_if_can(guid, SARILUS_SPELL_FROSTBOLT, CastTarget::Unit(victim))
        {
            let next = self.rng.urand(5000, 8000);
            if let Some(s) = self.sarilus_state_mut(guid) {
                s.frostbolt_timer_ms = next;
            }
        }
        let elem_due = {
            let Some(s) = self.sarilus_state_mut(guid) else {
                return;
            };
            if s.elementals_timer_ms < diff_ms {
                true
            } else {
                s.elementals_timer_ms -= diff_ms;
                false
            }
        };
        if elem_due {
            // `DoSpawnCreature(NPC_SARILUS_ELEMENTAL, ..., 4 * MINUTE *
            // IN_MILLISECONDS)` (cpp 672): 240_000 ms.
            let pos = self.unit_position(guid).unwrap_or_default();
            self.summon_creature(
                SARILUS_NPC_ELEMENTAL,
                Position::new(pos.x, pos.y, pos.z, pos.o),
                guid,
                FOULWEALD_TEMPSUMMON_TIMED_OR_DEAD,
                240_000,
            );
            if let Some(s) = self.sarilus_state_mut(guid) {
                s.elementals_timer_ms = 30_000;
            }
        }
    }

