    /// `npc_plucky_johnsonAI::Reset` (`thousand_needles.cpp:213-224`).
    fn plucky_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.plucky_state_mut(guid) {
            s.reset_timer_ms = 120_000;
        }
        // NEEDS-MAP-HELPER: `GetFactionTemplateId()` read vs `m_uiNormFaction`
        // + `SetFactionTemplateId(m_uiNormFaction)` (cpp 217-218).
        // `RemoveFlag(UNIT_NPC_FLAGS, UNIT_NPC_FLAG_GOSSIP)` (cpp 220-221).
        let flags = self.object_get_field(guid, offsets::UNIT_NPC_FLAGS);
        let _ = self.object_set_field(
            guid,
            u32::from(offsets::UNIT_NPC_FLAGS),
            flags & !PLUCKY_UNIT_NPC_FLAG_GOSSIP,
        );
        self.do_cast_spell_if_can(guid, PLUCKY_SPELL_CHICKEN, CastTarget::SelfCast);
    }

    /// `npc_plucky_johnsonAI::ReceiveEmote` (`thousand_needles.cpp:226-250`).
    /// NO-DISPATCHER-YET.
    #[allow(dead_code)] // NO-DISPATCHER-YET (step-3 remainder)
    fn plucky_receive_emote(&mut self, guid: ObjectGuid, _player: ObjectGuid, emote: u32) {
        // Gossip flag read (cpp 240).
        let has_gossip =
            self.object_get_field(guid, offsets::UNIT_NPC_FLAGS) & PLUCKY_UNIT_NPC_FLAG_GOSSIP != 0;
        // NEEDS-MAP-HELPER: `pPlayer->GetQuestStatus(QUEST_SCOOP) ==
        // QUEST_STATUS_INCOMPLETE` gate for the beckon arm (cpp 228) +
        // `SetFactionTemplateId(FACTION_FRIENDLY)` + `SetFlag(UNIT_NPC_FLAGS,
        // UNIT_NPC_FLAG_GOSSIP)` (cpp 232-233/244-245).
        if emote == PLUCKY_TEXTEMOTE_BECKON && !has_gossip {
            self.do_cast_spell_if_can(guid, PLUCKY_SPELL_HUMAN, CastTarget::SelfCast);
            return;
        }
        if emote == PLUCKY_TEXTEMOTE_CHICKEN && !has_gossip {
            self.do_cast_spell_if_can(guid, PLUCKY_SPELL_HUMAN, CastTarget::SelfCast);
            self.handle_emote_command(guid, PLUCKY_EMOTE_WAVE);
        }
    }

    /// `npc_plucky_johnsonAI::UpdateAI` (`thousand_needles.cpp:252-266`).
    fn plucky_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Reset arm (cpp 254-262): `normFaction` / `RemoveFlag` need faction
        // + flag helpers; the timer below is transcribed.
        let due = {
            let Some(s) = self.plucky_state_mut(guid) else {
                return;
            };
            if s.reset_timer_ms < diff_ms {
                true
            } else {
                s.reset_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: `SetFactionTemplateId(m_uiNormFaction)` +
            // `RemoveFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_SPAWNING)` (cpp 258-259).
            if let Some(s) = self.plucky_state_mut(guid) {
                s.reset_timer_ms = 120_000;
            }
            self.enter_evade_mode(guid);
        }
    }

