    /// `npc_grenka_bloodscreechAI::UpdateAI` (`thousand_needles.cpp:385-428`).
    fn grenka_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let (wave, fled) = self
            .grenka_state_mut(guid)
            .map_or((0, true), |s| (s.wave, s.has_fled));
        if fled {
            return;
        }
        let due = {
            let Some(s) = self.grenka_state_mut(guid) else {
                return;
            };
            if s.timer_ms < diff_ms {
                true
            } else {
                s.timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // Waves 0-2 only; case 2 sets no timer (fork falls through with
            // the expired timer, cpp 402-414).
            match wave {
                0 => {
                    self.grenka_do_summon(guid, 0);
                    if let Some(s) = self.grenka_state_mut(guid) {
                        s.timer_ms = 15_000;
                        s.wave = 1;
                    }
                }
                1 => {
                    self.grenka_do_summon(guid, 1);
                    self.grenka_do_summon(guid, 2);
                    if let Some(s) = self.grenka_state_mut(guid) {
                        s.timer_ms = 15_000;
                        s.wave = 2;
                    }
                }
                2 => {
                    self.grenka_do_summon(guid, 3);
                    // NEEDS-MAP-HELPER: `RemoveFlag(UNIT_FIELD_FLAGS,
                    // UNIT_FLAG_SPAWNING | UNIT_FLAG_PACIFIED |
                    // UNIT_FLAG_IMMUNE_TO_NPC)` + `SetVisibility(
                    // VISIBILITY_ON)` (cpp 405-406).
                    let player = self
                        .grenka_state_mut(guid)
                        .map_or(ObjectGuid::EMPTY, |s| s.player_guid);
                    if self.players.contains_key(&player) {
                        self.attack_start(guid, player);
                    }
                    if let Some(s) = self.grenka_state_mut(guid) {
                        s.wave = 3;
                    }
                }
                _ => {}
            }
        }
        // `ScriptedAI::UpdateAI(uiDiff)` combat arm (cpp 420).
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Flee at 15% with a victim (cpp 422-427).
        if !fled && self.creature_health_percent(guid) < 15.0 {
            if let Some(s) = self.grenka_state_mut(guid) {
                s.has_fled = true;
            }
            self.do_flee(guid, false);
        }
    }

    /// `npc_colossusAI::JustDied` (`silithus.cpp:593-623`).
