    /// `npc_spirit_guideAI::Reset` (empty) + ctor `uiTimerRez = 0`.
    fn spirit_guide_reset(&mut self, guid: ObjectGuid) {
        if let Some(s) = self.spirit_guide_state_mut(guid) {
            s.rez_timer_ms = 0;
        }
    }

    /// `npc_spirit_guideAI::UpdateAI` (battleground.cpp 62-73). No hostile
    /// check in the fork (runs out of combat).
    fn spirit_guide_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let due = {
            let Some(s) = self.spirit_guide_state_mut(guid) else {
                return;
            };
            if s.rez_timer_ms < diff_ms {
                true
            } else {
                s.rez_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: fork `InterruptNonMeleeSpells(true)`; no
            // interrupt helper found.
            // Fork casts are triggered/non-triggered `CastSpell` (not
            // `DoCastSpellIfCan`); triggered-ness is not modeled here.
            self.do_cast_spell_if_can(guid, SPIRIT_GUIDE_SPELL_HEAL, CastTarget::SelfCast);
            self.do_cast_spell_if_can(guid, SPIRIT_GUIDE_SPELL_HEAL_CHANNEL, CastTarget::SelfCast);
            if let Some(s) = self.spirit_guide_state_mut(guid) {
                s.rez_timer_ms = 30_000;
            }
        }
    }

