    /// `npc_spirit_guideAI::CorpseRemoved` (battleground.cpp 75-94).
    /// NO-DISPATCHER-YET (unlisted virtual; see NOTE-1).
    #[allow(dead_code)] // wired by the corpse-remove path (no dispatcher yet)
    fn spirit_guide_corpse_removed(&mut self, guid: ObjectGuid) {
        let Some(me) = self.unit_position(guid) else {
            return;
        };
        // NEEDS-MAP-HELPER: fork repops dead players within 20.0 carrying the
        // waiting aura (`RepopAtGraveyard`); no player aura/repop helpers found.
        let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
        for player in players {
            if self.unit_is_alive(player) {
                continue;
            }
            if let Some(pp) = self.object_position(player) {
                let dx = pp.x - me.x;
                let dy = pp.y - me.y;
                if dx * dx + dy * dy <= 20.0 * 20.0 {
                    let _ = SPIRIT_GUIDE_SPELL_WAITING_TO_RESURRECT;
                }
            }
        }
    }

    /// `npc_spirit_guideAI::GetData` (battleground.cpp 60).
    /// NO-DISPATCHER-YET (unlisted virtual; BG code reads `uiTimerRez`).
    #[allow(dead_code)] // read by the battleground code (no dispatcher yet)
    fn spirit_guide_get_data(&self, guid: ObjectGuid) -> u32 {
        self.ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::SpiritGuide(s)) => Some(s.rez_timer_ms),
                _ => None,
            })
            .unwrap_or(0)
    }

    /// `npc_etendardAI::UpdateAI` (battleground.cpp 154-165). `NullCreatureAI`:
    /// no hostile check, one-shot setup.
    fn etendard_update(&mut self, guid: ObjectGuid, _diff_ms: u32) {
        let spell = self
            .ai
            .get(&guid)
            .and_then(|ai| match &ai.script {
                Some(CreatureScriptAi::Etendard(s)) => Some(s.auto_repeat_spell),
                _ => None,
            })
            .unwrap_or(0);
        let spawned = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Etendard(s)) if s.spawned),
        );
        if !spawned {
            // NEEDS-MAP-HELPER: fork `SetFlag(UNIT_FIELD_FLAGS,
            // UNIT_FLAG_IMMUNE_TO_NPC)` + `SetDefaultMovementType(IDLE)`; no
            // unit-flag/movement-type helpers found.
            self.do_cast_spell_if_can(guid, ETENDARD_SPELL_SPAWN_EFFECT, CastTarget::SelfCast);
            if spell != 0 {
                self.do_cast_spell_if_can(guid, spell, CastTarget::SelfCast);
            }
            if let Some(s) = self.etendard_state_mut(guid) {
                s.spawned = true;
            }
        }
    }

