    /// `npc_VanndarAI::MoveInLineOfSight` (142-149): 23.0 aggro radius.
    fn vanndar_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        if self.unit_victim(guid).is_some() {
            return;
        }
        let near = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy < 23.0 * 23.0
            }
            _ => false,
        };
        // NEEDS-MAP-HELPER: fork `IsHostileTo` faction check.
        if near {
            self.attack_start(guid, who);
        }
    }

    /// `npc_VanndarAI::UpdateAI` (151-255).
    #[allow(clippy::too_many_lines)]
    fn vanndar_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Leash runs BEFORE the drive in the fork (153-162).
        // NEEDS-MAP-HELPER: fork gates this on `GetMapId() == MAP_ALTERAC_VALLEY`
        // (30); no map-id helper found, distance check kept unconditional.
        let out = match self.unit_position(guid) {
            Some(p) => {
                let dx = p.x - 722.4;
                let dy = p.y - (-11.0);
                dx * dx + dy * dy > 35.0 * 35.0
            }
            None => false,
        };
        if out {
            // NEEDS-MAP-HELPER: fork `CombatStop()` (threat-list wipe without
            // evade reset); reviewer to confirm `enter_evade_mode` suffices.
            let max = self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXHEALTH);
            self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_HEALTH), max);
            if let Some(u) = self.unit_base_mut(guid) {
                u.clear_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
            }
            if let Some(s) = self.vanndar_state_mut(guid) {
                s.leashed = true;
            }
            self.enter_evade_mode(guid);
            return;
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Global cooldown (167-176): `IsNonMeleeSpellCasted` -> active-cast check.
        let is_casting = self.bot_casting_spell(guid).is_some();
        if let Some(s) = self.vanndar_state_mut(guid) {
            if s.global_cd_ms > diff_ms {
                s.global_cd_ms -= diff_ms;
            } else if is_casting {
                s.global_cd_ms = 1;
            } else {
                s.global_cd_ms = 0;
            }
        }
        let avatar_due = {
            let Some(s) = self.vanndar_state_mut(guid) else {
                return;
            };
            if s.avatar_timer_ms < diff_ms {
                true
            } else {
                s.avatar_timer_ms -= diff_ms;
                false
            }
        };
        if avatar_due {
            let gcd = self.vanndar_state_mut(guid).map_or(1, |s| s.global_cd_ms);
            if gcd == 0
                && self.do_cast_spell_if_can(guid, VANNDAR_SPELL_AVATAR, CastTarget::SelfCast)
            {
                let next = self.rng.urand(20_000, 30_000);
                if let Some(s) = self.vanndar_state_mut(guid) {
                    s.avatar_timer_ms = next;
                    s.global_cd_ms = 1000;
                }
            }
        }
        let storm_due = {
            let Some(s) = self.vanndar_state_mut(guid) else {
                return;
            };
            if s.stormbolt_timer_ms < diff_ms {
                true
            } else {
                s.stormbolt_timer_ms -= diff_ms;
                false
            }
        };
        if storm_due {
            let gcd = self.vanndar_state_mut(guid).map_or(1, |s| s.global_cd_ms);
            if gcd == 0
                && self.do_cast_spell_if_can(
                    guid,
                    VANNDAR_SPELL_STORMBOLT,
                    CastTarget::Unit(victim),
                )
            {
                let next = self.rng.urand(8000, 10_000);
                if let Some(s) = self.vanndar_state_mut(guid) {
                    s.stormbolt_timer_ms = next;
                    s.global_cd_ms = 1000;
                }
            }
        }
        let thunder_due = {
            let Some(s) = self.vanndar_state_mut(guid) else {
                return;
            };
            if s.thunderclap_timer_ms < diff_ms {
                true
            } else {
                s.thunderclap_timer_ms -= diff_ms;
                false
            }
        };
        if thunder_due {
            let gcd = self.vanndar_state_mut(guid).map_or(1, |s| s.global_cd_ms);
            if gcd == 0
                && self.do_cast_spell_if_can(guid, VANNDAR_SPELL_THUNDERCLAP, CastTarget::SelfCast)
            {
                let next = self.rng.urand(5000, 8000);
                if let Some(s) = self.vanndar_state_mut(guid) {
                    s.thunderclap_timer_ms = next;
                    s.global_cd_ms = 1000;
                }
            }
        }
        // Health-percent fight texts (223-251).
        for (threshold, flag) in [
            (80.0_f32, 1),
            (60.0_f32, 2),
            (40.0_f32, 3),
            (20.0_f32, 4),
            (5.0_f32, 5),
        ] {
            let pending = self.ai.get(&guid).is_some_and(|ai| match &ai.script {
                Some(CreatureScriptAi::Vanndar(s)) => match flag {
                    1 => s.combat1,
                    2 => s.combat2,
                    3 => s.combat3,
                    4 => s.combat4,
                    _ => s.combat5,
                },
                _ => false,
            });
            if pending && self.creature_health_percent(guid) < threshold {
                let text = self.vanndar_fight_text();
                self.do_script_text(text, guid, None, -1);
                if let Some(s) = self.vanndar_state_mut(guid) {
                    match flag {
                        1 => s.combat1 = false,
                        2 => s.combat2 = false,
                        3 => s.combat3 = false,
                        4 => s.combat4 = false,
                        _ => s.combat5 = false,
                    }
                }
            }
        }
        // NEEDS-MAP-HELPER: fork `AggroLinkedMobsIfNeeded()` (linked entries
        // 13333 + 14762-14769 inherit the threat list); no threat-list-copy helper.
    }

