    /// `npc_DrekTharAI::UpdateAI` (404-527).
    #[allow(clippy::too_many_lines)]
    fn drekthar_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Leash runs BEFORE the timers/drive in the fork (406-417).
        // NEEDS-MAP-HELPER: fork gates on map 30 (Alterac Valley); kept unconditional.
        let out = match self.unit_position(guid) {
            Some(p) => {
                let dx = p.x - (-1_370.9);
                let dy = p.y - (-219.8);
                dx * dx + dy * dy > 33.0 * 33.0
            }
            None => false,
        };
        if out {
            // NEEDS-MAP-HELPER: fork `CombatStop()`; reviewer to confirm evade suffices.
            let max = self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXHEALTH);
            self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_HEALTH), max);
            if let Some(u) = self.unit_base_mut(guid) {
                u.clear_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
            }
            if let Some(s) = self.drekthar_state_mut(guid) {
                s.leashed = true;
            }
            self.enter_evade_mode(guid);
            return;
        }
        // Whirlwind-active countdown ticks before the drive (419-422).
        if let Some(s) = self.drekthar_state_mut(guid) {
            if s.whirlwind_active_ms < diff_ms {
                s.whirlwind_active_ms = 0;
            } else {
                s.whirlwind_active_ms -= diff_ms;
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let is_casting = self.bot_casting_spell(guid).is_some();
        if let Some(s) = self.drekthar_state_mut(guid) {
            if s.global_cd_ms > diff_ms {
                s.global_cd_ms -= diff_ms;
            } else if is_casting {
                s.global_cd_ms = 1;
            } else {
                s.global_cd_ms = 0;
            }
        }
        // Root mirrors whirlwind-active (438-447; ROOT does not gate Rust motion
        // yet, so the cast also `stop_moving`s like the herod whirlwind arm).
        let whirling = self
            .drekthar_state_mut(guid)
            .map_or(0, |s| s.whirlwind_active_ms)
            != 0;
        if whirling {
            if let Some(u) = self.unit_base_mut(guid) {
                u.add_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
            }
            self.stop_moving(guid);
        } else if let Some(u) = self.unit_base_mut(guid) {
            u.clear_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
        }
        let whirl_due = {
            let Some(s) = self.drekthar_state_mut(guid) else {
                return;
            };
            if s.whirlwind_timer_ms < diff_ms {
                true
            } else {
                s.whirlwind_timer_ms -= diff_ms;
                false
            }
        };
        if whirl_due {
            let gcd = self.drekthar_state_mut(guid).map_or(1, |s| s.global_cd_ms);
            if gcd == 0
                && self.do_cast_spell_if_can(guid, DREKTHAR_SPELL_WHIRLWIND, CastTarget::SelfCast)
            {
                let next = self.rng.urand(12_000, 16_000);
                if let Some(s) = self.drekthar_state_mut(guid) {
                    s.whirlwind_timer_ms = next;
                    s.whirlwind_active_ms = 2000;
                    s.global_cd_ms = 2000;
                }
            }
        }
        let knock_due = {
            let Some(s) = self.drekthar_state_mut(guid) else {
                return;
            };
            if s.knockdown_timer_ms < diff_ms {
                true
            } else {
                s.knockdown_timer_ms -= diff_ms;
                false
            }
        };
        if knock_due {
            let gcd = self.drekthar_state_mut(guid).map_or(1, |s| s.global_cd_ms);
            if gcd == 0
                && self.do_cast_spell_if_can(
                    guid,
                    DREKTHAR_SPELL_KNOCKDOWN,
                    CastTarget::Unit(victim),
                )
            {
                let next = self.rng.urand(16_000, 24_000);
                if let Some(s) = self.drekthar_state_mut(guid) {
                    s.knockdown_timer_ms = next;
                    s.global_cd_ms = 1000;
                }
            }
        }
        let frenzy_due = {
            let Some(s) = self.drekthar_state_mut(guid) else {
                return;
            };
            if s.frenzy_timer_ms < diff_ms {
                true
            } else {
                s.frenzy_timer_ms -= diff_ms;
                false
            }
        };
        if frenzy_due {
            let gcd = self.drekthar_state_mut(guid).map_or(1, |s| s.global_cd_ms);
            if gcd == 0
                && self.creature_health_percent(guid) <= 30.0
                && self.do_cast_spell_if_can(guid, DREKTHAR_SPELL_FRENZY, CastTarget::SelfCast)
            {
                if let Some(s) = self.drekthar_state_mut(guid) {
                    s.frenzy_timer_ms = 120_000;
                    s.global_cd_ms = 1000;
                }
            }
        }
        for (threshold, flag) in [
            (80.0_f32, 1),
            (60.0_f32, 2),
            (40.0_f32, 3),
            (20.0_f32, 4),
            (5.0_f32, 5),
        ] {
            let pending = self.ai.get(&guid).is_some_and(|ai| match &ai.script {
                Some(CreatureScriptAi::Drekthar(s)) => match flag {
                    1 => s.combat1,
                    2 => s.combat2,
                    3 => s.combat3,
                    4 => s.combat4,
                    _ => s.combat5,
                },
                _ => false,
            });
            if pending && self.creature_health_percent(guid) < threshold {
                let text = self.drekthar_fight_text();
                self.do_script_text(text, guid, None, -1);
                if let Some(s) = self.drekthar_state_mut(guid) {
                    match flag {
                        1 => s.combat1 = false,
                        2 => s.combat2 = false,
                        3 => s.combat3 = false,
                        4 => s.combat4 = false,
                        _ => s.combat5 = false,
                    }
                }
            }
        }
        // NEEDS-MAP-HELPER: fork `AggroLinkedMobsIfNeeded()` (linked entries
        // 12121, 12122 + 14772-14777); no threat-list-copy helper.
    }

    /// `npc_BalindaAI::Reset` (576-591).
    fn balinda_reset(&mut self, guid: ObjectGuid) {
        let said = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Balinda(s)) if s.reset_said),
        );
        if said {
            self.do_script_text(BALINDA_SAY_RESET, guid, None, -1);
        }
        if let Some(s) = self.balinda_state_mut(guid) {
            s.global_cd_ms = 0;
            s.fireball_timer_ms = 0;
            s.frostbolt_timer_ms = 0;
            s.cone_timer_ms = 1500;
            s.arcane_explo_timer_ms = 2000;
            s.polymorph_timer_ms = 1750;
            s.reset_said = true;
            s.say_half = true;
            s.say_aggro = true;
        }
        if let Some(u) = self.unit_base_mut(guid) {
            u.clear_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
        }
    }

    /// `npc_BalindaAI::MoveInLineOfSight` (593-600): 28.0 aggro radius.
    fn balinda_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        if self.unit_victim(guid).is_some() {
            return;
        }
        // Fork `IsHostileTo` (faction reaction): entry 11949 is
        // the Stormpike captain; for players that is Horde-team
        // only. The drive only feeds players (fork also fires
        // for other units).
        if self
            .player(who)
            .is_none_or(|p| p.team != mangos_entities::unit::Team::Horde)
        {
            return;
        }
        let near = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                let dz = a.z - b.z;
                dx * dx + dy * dy + dz * dz < 28.0 * 28.0
            }
            _ => false,
        };
        if near {
            self.attack_start(guid, who);
        }
    }

