    /// `npc_WarMasterAI::MoveInLineOfSight` (1020-1031): charge on pull.
    fn war_master_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        if self.unit_victim(guid).is_some() {
            return;
        }
        let near = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy < 22.0 * 22.0
            }
            _ => false,
        };
        // NEEDS-MAP-HELPER: fork `IsValidAttackTarget` check.
        if near {
            self.attack_start(guid, who);
            if self.do_cast_spell_if_can(guid, WARMASTER_SPELL_CHARGE, CastTarget::Unit(who)) {
                if let Some(s) = self.war_master_state_mut(guid) {
                    s.charge_timer_ms = 12_000;
                }
            }
        }
    }

