    /// `npc_WarMasterAI::UpdateAI` (1035-1158).
    #[allow(clippy::too_many_lines)]
    fn war_master_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Respawned-after-kill cleanup runs before everything (1037-1046).
        let killed = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::WarMaster(s)) if s.is_killed),
        );
        if killed {
            // NEEDS-MAP-HELPER: fork `DeleteLater()` (despawn without corpse);
            // no delete-later helper found.
            self.despawn_creature_now(guid, 0);
            return;
        }
        if let Some(s) = self.war_master_state_mut(guid) {
            if s.whirlwind_active_ms < diff_ms {
                s.whirlwind_active_ms = 0;
            } else {
                s.whirlwind_active_ms -= diff_ms;
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let is_casting = self.bot_casting_spell(guid).is_some();
        if let Some(s) = self.war_master_state_mut(guid) {
            if s.global_cd_ms > diff_ms {
                s.global_cd_ms -= diff_ms;
            } else if is_casting {
                s.global_cd_ms = 1;
            } else {
                s.global_cd_ms = 0;
            }
        }
        // Fork uses the unguarded add/clear pair here (1066-1069).
        let whirling = self
            .war_master_state_mut(guid)
            .map_or(0, |s| s.whirlwind_active_ms)
            != 0;
        if whirling {
            if let Some(u) = self.unit_base_mut(guid) {
                u.add_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
            }
            self.stop_moving(guid);
        } else if let Some(u) = self.unit_base_mut(guid) {
            u.clear_unit_state(mangos_entities::unit::UNIT_STATE_ROOT);
        }
        // Whirlwind double-tap (1071-1090).
        let whirl_due = {
            let Some(s) = self.war_master_state_mut(guid) else {
                return;
            };
            if s.whirlwind_timer_ms < diff_ms {
                true
            } else {
                s.whirlwind_timer_ms -= diff_ms;
                false
            }
        };
        if whirl_due {
            let gcd = self
                .war_master_state_mut(guid)
                .map_or(1, |s| s.global_cd_ms);
            if gcd == 0
                && self.do_cast_spell_if_can(guid, WARMASTER_SPELL_WHIRLWIND, CastTarget::SelfCast)
            {
                let active = self
                    .war_master_state_mut(guid)
                    .map_or(1, |s| s.whirlwind_active_ms);
                if active < diff_ms {
                    if let Some(s) = self.war_master_state_mut(guid) {
                        s.whirlwind_active_ms = 4000;
                        s.whirlwind_timer_ms = 2000;
                    }
                } else {
                    let next = self.rng.urand(11_000, 13_000);
                    if let Some(s) = self.war_master_state_mut(guid) {
                        s.whirlwind_timer_ms = next;
                    }
                }
                if let Some(s) = self.war_master_state_mut(guid) {
                    s.global_cd_ms = 2000;
                }
            }
        }
        // Enrage at <=30% (1092-1105; reuses TIMMY_SPELL_ENRAGE, NOTE-12).
        let enrage_due = {
            let Some(s) = self.war_master_state_mut(guid) else {
                return;
            };
            if s.enrage_timer_ms < diff_ms {
                true
            } else {
                s.enrage_timer_ms -= diff_ms;
                false
            }
        };
        if enrage_due {
            let gcd = self
                .war_master_state_mut(guid)
                .map_or(1, |s| s.global_cd_ms);
            if gcd == 0
                && self.creature_health_percent(guid) <= 30.0
                && self.do_cast_spell_if_can(guid, TIMMY_SPELL_ENRAGE, CastTarget::SelfCast)
            {
                if let Some(s) = self.war_master_state_mut(guid) {
                    s.enrage_timer_ms = 120_000;
                    s.global_cd_ms = 1000;
                }
            }
        }
        // Charge at 8..25 (1107-1125).
        let charge_due = {
            let Some(s) = self.war_master_state_mut(guid) else {
                return;
            };
            if s.charge_timer_ms < diff_ms {
                true
            } else {
                s.charge_timer_ms -= diff_ms;
                false
            }
        };
        if charge_due {
            let gcd = self
                .war_master_state_mut(guid)
                .map_or(1, |s| s.global_cd_ms);
            if gcd == 0 {
                // NEEDS-MAP-HELPER: fork `GetVictimInRange(8.0, 25.0)`; no
                // victim-in-range-band helper found, victim used directly.
                if self.do_cast_spell_if_can(guid, WARMASTER_SPELL_CHARGE, CastTarget::Unit(victim))
                {
                    let next = self.rng.urand(12_000, 18_000);
                    if let Some(s) = self.war_master_state_mut(guid) {
                        s.charge_timer_ms = next;
                        s.global_cd_ms = 250;
                    }
                } else if let Some(s) = self.war_master_state_mut(guid) {
                    // Fork retries in 5..10s when no victim is in the band.
                    s.charge_timer_ms = 5000;
                }
            }
        }
        // Cleave (1127-1140).
        let cleave_due = {
            let Some(s) = self.war_master_state_mut(guid) else {
                return;
            };
            if s.cleave_timer_ms < diff_ms {
                true
            } else {
                s.cleave_timer_ms -= diff_ms;
                false
            }
        };
        if cleave_due {
            let gcd = self
                .war_master_state_mut(guid)
                .map_or(1, |s| s.global_cd_ms);
            if gcd == 0
                && self.do_cast_spell_if_can(guid, WARMASTER_SPELL_CLEAVE, CastTarget::SelfCast)
            {
                let next = self.rng.urand(8000, 10_000);
                if let Some(s) = self.war_master_state_mut(guid) {
                    s.cleave_timer_ms = next;
                    s.global_cd_ms = 1000;
                }
            }
        }
        // Demoralizing shout (1142-1155).
        let shout_due = {
            let Some(s) = self.war_master_state_mut(guid) else {
                return;
            };
            if s.shout_timer_ms < diff_ms {
                true
            } else {
                s.shout_timer_ms -= diff_ms;
                false
            }
        };
        if shout_due {
            let gcd = self
                .war_master_state_mut(guid)
                .map_or(1, |s| s.global_cd_ms);
            if gcd == 0
                && self.do_cast_spell_if_can(
                    guid,
                    WARMASTER_SPELL_DEMORALSHOUT,
                    CastTarget::SelfCast,
                )
            {
                let next = self.rng.urand(14_000, 20_000);
                if let Some(s) = self.war_master_state_mut(guid) {
                    s.shout_timer_ms = next;
                    s.global_cd_ms = 1000;
                }
            }
        }
    }

