    /// `npc_AlteracBowmanAI::UpdateAI` (1203-1232).
    fn bowman_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Range-watch evade runs before the drive (1205-1215).
        // NEEDS-MAP-HELPER: fork `IsInEvadeMode` read; approximated with
        // victim absence (the same arm also fires when targetless).
        let victim = self.unit_victim(guid);
        let in_range = match (
            self.unit_position(guid),
            victim.and_then(|v| self.unit_position(v)),
        ) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy < 80.0 * 80.0
            }
            _ => false,
        };
        if victim.is_none() || !in_range {
            let expired = {
                let Some(s) = self.bowman_state_mut(guid) else {
                    return;
                };
                if s.reset_timer_ms < diff_ms {
                    true
                } else {
                    s.reset_timer_ms -= diff_ms;
                    false
                }
            };
            if expired {
                if let Some(s) = self.bowman_state_mut(guid) {
                    s.reset_timer_ms = 3000;
                }
                self.enter_evade_mode(guid);
                return;
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let shoot_due = {
            let Some(s) = self.bowman_state_mut(guid) else {
                return;
            };
            if s.shoot_timer_ms < diff_ms {
                true
            } else {
                s.shoot_timer_ms -= diff_ms;
                false
            }
        };
        if shoot_due
            && !self.can_reach_melee(guid, victim)
            && self.do_cast_spell_if_can(guid, BOWMAN_SPELL_SHOOT, CastTarget::Unit(victim))
        {
            if let Some(s) = self.bowman_state_mut(guid) {
                s.shoot_timer_ms = 1700;
            }
        }
    }

