    /// `FrostwolfShamanAI::UpdateAI` (4439-4472).
    fn frostwolf_shaman_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let shock_due = {
            let Some(s) = self.frostwolf_shaman_state_mut(guid) else {
                return;
            };
            if s.frost_shock_timer_ms < diff_ms {
                true
            } else {
                s.frost_shock_timer_ms -= diff_ms;
                false
            }
        };
        if shock_due
            && self.do_cast_spell_if_can(guid, AV_SPELL_FROST_SHOCK, CastTarget::Unit(victim))
        {
            let next = self.rng.urand(5000, 6000);
            if let Some(s) = self.frostwolf_shaman_state_mut(guid) {
                s.frost_shock_timer_ms = next;
            }
        }
        let heal_due = {
            let Some(s) = self.frostwolf_shaman_state_mut(guid) else {
                return;
            };
            if s.healing_wave_timer_ms < diff_ms {
                true
            } else {
                s.healing_wave_timer_ms -= diff_ms;
                false
            }
        };
        if heal_due && self.creature_health_percent(guid) < 70.0 {
            // Fork is a raw `CastSpell` (always re-cast, no CAST_OK gate).
            self.do_cast_spell_if_can(guid, AV_SPELL_HEALING_WAVE, CastTarget::SelfCast);
            if let Some(s) = self.frostwolf_shaman_state_mut(guid) {
                s.healing_wave_timer_ms = 7000;
            }
        }
        let shield_due = {
            let Some(s) = self.frostwolf_shaman_state_mut(guid) else {
                return;
            };
            if s.lightning_shield_timer_ms < diff_ms {
                true
            } else {
                s.lightning_shield_timer_ms -= diff_ms;
                false
            }
        };
        // NEEDS-MAP-HELPER: fork also gates on `!HasAura(LIGHTNING_SHIELD)`;
        // no has-aura helper found, timer-only here.
        if shield_due {
            self.do_cast_spell_if_can(guid, AV_SPELL_LIGHTNING_SHIELD, CastTarget::SelfCast);
            let next = self.rng.urand(9000, 11_000);
            if let Some(s) = self.frostwolf_shaman_state_mut(guid) {
                s.lightning_shield_timer_ms = next;
            }
        }
    }

