    /// `MineNPC_AI::UpdateAI` (4614-4681).
    fn av_mine_npc_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Flash bomb vs shapeshifted players/pets within 35 (4624-4656).
        let flash_due = {
            let Some(s) = self.av_mine_npc_state_mut(guid) else {
                return;
            };
            if s.flash_bomb_timer_ms < diff_ms {
                true
            } else {
                s.flash_bomb_timer_ms -= diff_ms;
                false
            }
        };
        if flash_due {
            // NEEDS-MAP-HELPER: fork scans players for `IsNoWeaponShapeShift`
            // and their pets within 35.0; no shapeshift/pet helpers found.
            if let Some(s) = self.av_mine_npc_state_mut(guid) {
                s.bomb_launched = false;
            }
            let _ = victim;
        }
        // Bomb on a random target (4658-4669; `ATTACKING_TARGET_RANDOM` = 0).
        let launched = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::AvMineNpc(s)) if s.bomb_launched),
        );
        if !launched {
            let bomb_due = {
                let Some(s) = self.av_mine_npc_state_mut(guid) else {
                    return;
                };
                if s.bomb_timer_ms < diff_ms {
                    true
                } else {
                    s.bomb_timer_ms -= diff_ms;
                    false
                }
            };
            if bomb_due && self.select_attacking_target(guid, 0, 0, 0).is_some() {
                // Fork casts on the victim even when the random target differs.
                if self.do_cast_spell_if_can(guid, AVMINE_SPELL_BOMB, CastTarget::Unit(victim)) {
                    if let Some(s) = self.av_mine_npc_state_mut(guid) {
                        s.bomb_timer_ms = 7500;
                        s.bomb_launched = true;
                    }
                }
            }
        }
        // Landmine at feet (4671-4678).
        let mine_due = {
            let Some(s) = self.av_mine_npc_state_mut(guid) else {
                return;
            };
            if s.landmine_timer_ms < diff_ms {
                true
            } else {
                s.landmine_timer_ms -= diff_ms;
                false
            }
        };
        if mine_due {
            self.do_cast_spell_if_can(guid, AVMINE_SPELL_LANDMINE, CastTarget::SelfCast);
            if let Some(s) = self.av_mine_npc_state_mut(guid) {
                s.landmine_timer_ms = 9000;
            }
        }
    }

