    /// `npc_av_trigger_for_questAI::Reset` (4867) + `MoveInLineOfSight` (4868-4873).
    /// STATELESS (no state struct; no accessor).
    fn av_trigger_quest_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        let near = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy <= 10.0 * 10.0
            }
            _ => false,
        };
        // NEEDS-MAP-HELPER: fork `IsPlayer()` + `KilledMonsterCredit(entry)`;
        // no credit helper found.
        let _ = near;
    }

