    /// `npc_training_dummyAI::UpdateAI` (1121-1154).
    fn training_dummy_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        if !self.ai_in_combat(guid) {
            return;
        }
        let due = {
            let Some(s) = self.training_dummy_state_mut(guid) else {
                return;
            };
            if s.combat_timer_ms <= diff_ms {
                true
            } else {
                s.combat_timer_ms -= diff_ms;
                false
            }
        };
        if !due {
            return;
        }
        // NEEDS-MAP-HELPER: fork prunes attackers older than 10s (`GetUnit` +
        // wall clock), wipes their threat (`modifyThreatPercent(-101)`) and
        // evades on an empty threat list; no clock/threat helpers found, so
        // only the re-arm below is kept.
        // NEEDS-MAP-HELPER: fork `EnterEvadeMode()` when the threat list is
        // empty; approximated with victim absence.
        if self.unit_victim(guid).is_none() {
            self.enter_evade_mode(guid);
        }
        if let Some(s) = self.training_dummy_state_mut(guid) {
            s.combat_timer_ms = 15_000;
        }
    }

    /// `npc_summon_debugAI::Reset` (1174-1184) + `JustDied` (1187).
    fn summon_debug_reset(&mut self, guid: ObjectGuid) {
        let summons = self
            .summon_debug_state_mut(guid)
            .map(|s| std::mem::take(&mut s.summons))
            .unwrap_or_default();
        for summon in summons {
            // NEEDS-MAP-HELPER: fork `TemporarySummon::UnSummon()`; approximated
            // with an immediate despawn.
            self.despawn_creature_now(summon, 0);
        }
        if let Some(s) = self.summon_debug_state_mut(guid) {
            s.summon_count = 0;
        }
    }

    fn summon_debug_just_died(&mut self, guid: ObjectGuid) {
        self.summon_debug_reset(guid);
    }

    /// `npc_summon_debugAI::UpdateAI` (1189-1198).
    fn summon_debug_update(&mut self, guid: ObjectGuid, _diff_ms: u32) {
        if self.unit_victim(guid).is_none() {
            return;
        }
        let full = self
            .summon_debug_state_mut(guid)
            .is_some_and(|s| s.summon_count >= 200);
        if full {
            return;
        }
        if let Some(pos) = self.unit_position(guid) {
            let created = self.summon_creature(
                SUMMON_DEBUG_NPC_ENTRY,
                Position::new(pos.x, pos.y, pos.z, 0.0),
                guid,
                SUMMON_DEBUG_TEMPSUMMON_MANUAL,
                0,
            );
            if let Some(s) = self.summon_debug_state_mut(guid) {
                s.summon_count += 1;
                if let Some(created) = created {
                    s.summons.push(created);
                }
            }
        }
    }

