    /// `npc_spirit_shadeAI::UpdateAI` (`boss_lethon.cpp`). `EnterCombat`/
    /// `AttackedBy`/`AttackStart`/`EnterEvadeMode` are empty in the fork
    /// (dropped except the `attack_start` chase-sync note: the shade never
    /// attacks, so no override is emitted).
    fn spirit_shade_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let pending = self.spirit_shade_state_mut(guid).map_or(0, |s| s.delay_ms);
        if pending == 0 {
            return;
        }
        if pending > diff_ms {
            if let Some(s) = self.spirit_shade_state_mut(guid) {
                s.delay_ms -= diff_ms;
            }
            return;
        }
        if let Some(s) = self.spirit_shade_state_mut(guid) {
            s.delay_ms = 0;
        }
        // NEEDS-MAP-HELPER: fork `SetVisibility(VISIBILITY_ON)`; none found.
        let lethon = self
            .spirit_shade_state_mut(guid)
            .and_then(|s| s.lethon_guid)
            .filter(|l| self.creatures.contains_key(l));
        match lethon {
            Some(lethon) => {
                let near = match (self.unit_position(guid), self.unit_position(lethon)) {
                    (Some(a), Some(b)) => {
                        let dx = a.x - b.x;
                        let dy = a.y - b.y;
                        dx * dx + dy * dy <= 5.0 * 5.0
                    }
                    _ => false,
                };
                if near {
                    self.do_cast_spell_if_can(
                        guid,
                        LETHON_SPELL_DARK_OFFERING,
                        CastTarget::Unit(lethon),
                    );
                } else {
                    // NEEDS-MAP-HELPER: fork `MoveFollow(lethon, 0, 0)`; none found.
                }
            }
            None => self.despawn_creature_now(guid, 0),
        }
    }

