    /// Distance helper for the fork `IsInRange(victim, 0.0, range)` gates.
    fn invader_victim_within(&mut self, guid: ObjectGuid, victim: ObjectGuid, range: f32) -> bool {
        match (self.unit_position(guid), self.unit_position(victim)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy <= range * range
            }
            _ => false,
        }
    }

    /// `npc_invaderAI::UpdateAI` (190-284; note `<` semantics throughout).
    #[allow(clippy::too_many_lines)]
    fn invader_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let index = self.invader_state_mut(guid).map_or(99, |s| s.event_index);
        match index {
            INVADER_EVENT_FIRE => {
                let due = {
                    let Some(s) = self.invader_state_mut(guid) else {
                        return;
                    };
                    if s.shield_timer_ms < diff_ms {
                        true
                    } else {
                        s.shield_timer_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    // `CF_AURA_NOT_PRESENT`; not modeled (NOTE-8).
                    self.do_cast_spell_if_can(
                        guid,
                        INVADER_SPELL_FIRE_SHIELD,
                        CastTarget::SelfCast,
                    );
                    let next = self.rng.urand(6000, 8000);
                    if let Some(s) = self.invader_state_mut(guid) {
                        s.shield_timer_ms = next;
                    }
                }
                let due = {
                    let Some(s) = self.invader_state_mut(guid) else {
                        return;
                    };
                    if s.blast_wave_timer_ms < diff_ms {
                        true
                    } else {
                        s.blast_wave_timer_ms -= diff_ms;
                        false
                    }
                };
                if due
                    && self.invader_victim_within(guid, victim, 10.0)
                    && self.do_cast_spell_if_can(
                        guid,
                        INVADER_SPELL_BLAST_WAVE,
                        CastTarget::SelfCast,
                    )
                {
                    let next = self.rng.urand(13_000, 18_000);
                    if let Some(s) = self.invader_state_mut(guid) {
                        s.blast_wave_timer_ms = next;
                    }
                }
            }
            INVADER_EVENT_AIR => {
                let due = {
                    let Some(s) = self.invader_state_mut(guid) else {
                        return;
                    };
                    if s.shield_timer_ms < diff_ms {
                        true
                    } else {
                        s.shield_timer_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    self.do_cast_spell_if_can(
                        guid,
                        INVADER_SPELL_LIGHTN_SHIELD,
                        CastTarget::SelfCast,
                    );
                    let next = self.rng.urand(10_000, 12_000);
                    if let Some(s) = self.invader_state_mut(guid) {
                        s.shield_timer_ms = next;
                    }
                }
                let due = {
                    let Some(s) = self.invader_state_mut(guid) else {
                        return;
                    };
                    if s.whirlwind_timer_ms < diff_ms {
                        true
                    } else {
                        s.whirlwind_timer_ms -= diff_ms;
                        false
                    }
                };
                if due
                    && self.invader_victim_within(guid, victim, 8.0)
                    && self.do_cast_spell_if_can(
                        guid,
                        INVADER_SPELL_WHIRLWIND,
                        CastTarget::SelfCast,
                    )
                {
                    let next = self.rng.urand(9000, 12_000);
                    if let Some(s) = self.invader_state_mut(guid) {
                        s.whirlwind_timer_ms = next;
                    }
                }
            }
            INVADER_EVENT_EARTH => {
                let due = {
                    let Some(s) = self.invader_state_mut(guid) else {
                        return;
                    };
                    if s.knockdown_timer_ms < diff_ms {
                        true
                    } else {
                        s.knockdown_timer_ms -= diff_ms;
                        false
                    }
                };
                if due
                    && self.invader_victim_within(guid, victim, 5.0)
                    && self.do_cast_spell_if_can(
                        guid,
                        INVADER_SPELL_KNOCKDOWN,
                        CastTarget::Unit(victim),
                    )
                {
                    let next = self.rng.urand(11_000, 15_000);
                    if let Some(s) = self.invader_state_mut(guid) {
                        s.knockdown_timer_ms = next;
                    }
                }
                let due = {
                    let Some(s) = self.invader_state_mut(guid) else {
                        return;
                    };
                    if s.shock_timer_ms < diff_ms {
                        true
                    } else {
                        s.shock_timer_ms -= diff_ms;
                        false
                    }
                };
                if due
                    && self.do_cast_spell_if_can(
                        guid,
                        INVADER_SPELL_EARTH_SHOCK,
                        CastTarget::Unit(victim),
                    )
                {
                    let next = self.rng.urand(9000, 13_000);
                    if let Some(s) = self.invader_state_mut(guid) {
                        s.shock_timer_ms = next;
                    }
                }
            }
            _ => {
                let due = {
                    let Some(s) = self.invader_state_mut(guid) else {
                        return;
                    };
                    if s.chilled_timer_ms < diff_ms {
                        true
                    } else {
                        s.chilled_timer_ms -= diff_ms;
                        false
                    }
                };
                if due
                    && self.invader_victim_within(guid, victim, 5.0)
                    && self.do_cast_spell_if_can(
                        guid,
                        INVADER_SPELL_CHILLED,
                        CastTarget::Unit(victim),
                    )
                {
                    let next = self.rng.urand(5000, 8000);
                    if let Some(s) = self.invader_state_mut(guid) {
                        s.chilled_timer_ms = next;
                    }
                }
                let due = {
                    let Some(s) = self.invader_state_mut(guid) else {
                        return;
                    };
                    if s.shock_timer_ms < diff_ms {
                        true
                    } else {
                        s.shock_timer_ms -= diff_ms;
                        false
                    }
                };
                if due
                    && self.do_cast_spell_if_can(
                        guid,
                        INVADER_SPELL_FROST_SHOCK,
                        CastTarget::Unit(victim),
                    )
                {
                    let next = self.rng.urand(8000, 15_000);
                    if let Some(s) = self.invader_state_mut(guid) {
                        s.shock_timer_ms = next;
                    }
                }
            }
        }
    }

