    /// `npc_j_eevee_dreadsteedAI::MovementInform` (50-72).
    fn jeevee_dreadsteed_movement_inform(&mut self, guid: ObjectGuid, point_id: u32) {
        // NEEDS-MAP-HELPER: fork `SetFacingTo(aJeeveeDreadsteedLocations
        // [currentPoint].m_fO)` per arm; no facing helper found.
        match point_id {
            1..=3 => {
                if let Some(s) = self.jeevee_dreadsteed_state_mut(guid) {
                    s.waypoint_reached = true;
                }
                self.do_cast_spell_if_can(guid, JEEVEE_SPELL_SUMMONS_OBJECT, CastTarget::SelfCast);
            }
            4 => {
                if let Some(s) = self.jeevee_dreadsteed_state_mut(guid) {
                    s.waypoint_reached = true;
                }
                let player = self
                    .jeevee_dreadsteed_state_mut(guid)
                    .and_then(|s| s.player_guid);
                self.do_script_text(JEEVEE_SAY_DREADSTEED_4, guid, player, -1);
                // `CF_TRIGGERED`; not modeled (NOTE-8).
                self.do_cast_spell_if_can(guid, JEEVEE_SPELL_TELEPORT, CastTarget::SelfCast);
            }
            _ => {}
        }
    }

    /// `npc_j_eevee_dreadsteedAI::UpdateAI` (73-109): waypoint machine runs
    /// targetless (trainee pattern, OOC work first), combat is melee-only.
    fn jeevee_dreadsteed_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            let reached = self.ai.get(&guid).is_some_and(|ai| {
                matches!(&ai.script, Some(CreatureScriptAi::JeeveeDreadsteed(s)) if s.waypoint_reached)
            });
            if reached {
                let due = {
                    let Some(s) = self.jeevee_dreadsteed_state_mut(guid) else {
                        return;
                    };
                    if s.wait_timer_ms < diff_ms {
                        true
                    } else {
                        s.wait_timer_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    let point = self
                        .jeevee_dreadsteed_state_mut(guid)
                        .map_or(4, |s| s.current_point);
                    if point < 4 {
                        match point {
                            0 => self.do_script_text(JEEVEE_SAY_DREADSTEED_1, guid, None, -1),
                            1 => self.do_script_text(JEEVEE_SAY_DREADSTEED_2, guid, None, -1),
                            _ => self.do_script_text(JEEVEE_SAY_DREADSTEED_3, guid, None, -1),
                        }
                        let next = point + 1;
                        if let Some((x, y, z, _o, wait)) = Self::jeevee_dreadsteed_point(next) {
                            // NEEDS-MAP-HELPER: fork `MovePoint` generates a path
                            // (`..., true`); the path flag is not modeled.
                            self.creature_move_point(
                                guid,
                                u32::from(next),
                                Position::new(x, y, z, 0.0),
                                0,
                                0.0,
                                0.0,
                            );
                            if let Some(s) = self.jeevee_dreadsteed_state_mut(guid) {
                                s.current_point = next;
                                s.wait_timer_ms = wait;
                            }
                        }
                    } else {
                        self.despawn_creature_now(guid, 0);
                    }
                    if let Some(s) = self.jeevee_dreadsteed_state_mut(guid) {
                        s.waypoint_reached = false;
                    }
                }
            }
            return;
        };
    }

