    /// `npc_j_eevee_scholomanceAI::UpdateAI` (185-251).
    #[allow(clippy::match_same_arms)]
    fn jeevee_scholomance_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            let active = self.ai.get(&guid).is_some_and(|ai| {
                matches!(&ai.script, Some(CreatureScriptAi::JeeveeScholomance(s)) if s.waypoint_reached || s.finished)
            });
            if active {
                let due = {
                    let Some(s) = self.jeevee_scholomance_state_mut(guid) else {
                        return;
                    };
                    if s.wait_timer_ms < diff_ms {
                        true
                    } else {
                        s.wait_timer_ms -= diff_ms;
                        false
                    }
                };
                if due {
                    let point = self
                        .jeevee_scholomance_state_mut(guid)
                        .map_or(13, |s| s.current_point);
                    if point < 13 {
                        match point {
                            0 => self.do_script_text(JEEVEE_SAY_SCHOLOMANCE_1, guid, None, -1),
                            3 => self.do_script_text(JEEVEE_SAY_SCHOLOMANCE_2, guid, None, -1),
                            8 => {
                                self.do_script_text(JEEVEE_SAY_SCHOLOMANCE_3, guid, None, -1);
                                // NEEDS-MAP-HELPER: fork `SetWalk(false)`; none found.
                            }
                            11 => {
                                // NEEDS-MAP-HELPER: fork `SetWalk(true)`; none found.
                            }
                            12 => {
                                self.do_script_text(JEEVEE_SAY_SCHOLOMANCE_4, guid, None, -1);
                                // NEEDS-MAP-HELPER: fork `KilledMonsterCredit(14500)`
                                // for the summoner (`player_guid` below); none found.
                                let _summoner = self
                                    .jeevee_scholomance_state_mut(guid)
                                    .and_then(|s| s.player_guid);
                            }
                            _ => {}
                        }
                        let next = point + 1;
                        if let Some((x, y, z, _o, wait)) = Self::jeevee_scholomance_point(next) {
                            self.creature_move_point(
                                guid,
                                u32::from(next),
                                Position::new(x, y, z, 0.0),
                                0,
                                0.0,
                                0.0,
                            );
                            if let Some(s) = self.jeevee_scholomance_state_mut(guid) {
                                s.current_point = next;
                                s.wait_timer_ms = wait;
                            }
                        }
                    } else {
                        self.despawn_creature_now(guid, 0);
                    }
                    if let Some(s) = self.jeevee_scholomance_state_mut(guid) {
                        s.waypoint_reached = false;
                    }
                } else {
                    // Attack-emote repeats while waiting at points 2/7/12 (235-245).
                    let point = self
                        .jeevee_scholomance_state_mut(guid)
                        .map_or(0, |s| s.current_point);
                    if point == 2 || point == 7 || point == 12 {
                        // NEEDS-MAP-HELPER: fork `HandleEmote(ATTACKUNARMED)` repeat.
                        if let Some(s) = self.jeevee_scholomance_state_mut(guid) {
                            if s.attack_repeat_timer_ms < diff_ms {
                                s.attack_repeat_timer_ms = 1000;
                            } else {
                                s.attack_repeat_timer_ms -= diff_ms;
                            }
                        }
                    }
                }
            }
            return;
        };
    }

