    /// `npc_doctorAI::UpdateAI` (442-496; the tail `ScriptedAI::UpdateAI` is the
    /// no-target default, so no drive is emitted).
    fn doctor_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let player = self.doctor_state_mut(guid).and_then(|s| s.player_guid);
        let Some(player) = player else { return };
        let count = self.doctor_state_mut(guid).map_or(0, |s| s.summon_count);
        if count >= 21 {
            self.doctor_end_event(guid, true);
            return;
        }
        // NEEDS-MAP-HELPER: fork requires the player within
        // `DEFAULT_VISIBILITY_DISTANCE`; no visibility helper found, assumed near.
        let due = {
            let Some(s) = self.doctor_state_mut(guid) else {
                return;
            };
            if s.summon_timer_ms < diff_ms {
                true
            } else {
                s.summon_timer_ms -= diff_ms;
                false
            }
        };
        if !due {
            return;
        }
        let alliance = self.doctor_state_mut(guid).is_some_and(|s| s.is_alliance);
        if let Some(bunk) = self.doctor_free_bunk(guid) {
            // NEEDS-MAP-HELPER: fork picks `AllianceSoldierId/HordeSoldierId
            // [urand(0, 2)]` (12938/12936/12937 or 12923/12924/12925); entry
            // table kept inline.
            let roll = self.rng.urand(0, 2);
            let entry = if alliance {
                match roll {
                    0 => 12_938,
                    1 => 12_936,
                    _ => 12_937,
                }
            } else {
                match roll {
                    0 => 12_923,
                    1 => 12_924,
                    _ => 12_925,
                }
            };
            if let Some((x, y, z, o)) = Self::doctor_bunk(alliance, bunk) {
                let created = self.summon_creature(
                    entry,
                    Position::new(x, y, z, o),
                    guid,
                    TRIAGE_TEMPSUMMON_TIMED_OR_CORPSE,
                    5000,
                );
                if let Some(patient) = created {
                    // NEEDS-MAP-HELPER: fork `SetFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_PVP)`;
                    // none found.
                    if let Some(s) = self.patient_state_mut(patient) {
                        s.doctor_guid = Some(guid);
                    }
                    if let Some(s) = self.doctor_state_mut(guid) {
                        s.patient_guids.push(patient);
                        s.summon_count += 1;
                    }
                }
            }
        }
        if let Some(s) = self.doctor_state_mut(guid) {
            s.summon_timer_ms = 10_000;
        }
        let _ = player;
    }

