    /// `npc_injured_patientAI::SpellHit` (267-317; triage spell 20804).
    fn patient_spell_hit(&mut self, guid: ObjectGuid, caster: ObjectGuid, spell_id: u32) {
        if spell_id != TRIAGE_SPELL_TRIAGE || !self.unit_is_alive(guid) {
            return;
        }
        // NEEDS-MAP-HELPER: fork gates on caster `TYPEID_PLAYER` + triage quest
        // (6622/6624) `QUEST_STATUS_INCOMPLETE`; no player/quest helpers found.
        if let Some(doctor) = self.patient_state_mut(guid).and_then(|s| s.doctor_guid) {
            self.doctor_patient_saved(doctor, guid, caster);
        }
        // NEEDS-MAP-HELPER: fork flag/stand/walk writes + `MovePoint(0, run-to)`
        // + `DoScriptText(SAY_DOC1/2/3 by urand(0, 2))`; none found. Text roll kept:
        match self.rng.urand(0, 2) {
            0 => self.do_script_text(TRIAGE_SAY_DOC1, guid, None, -1),
            1 => self.do_script_text(TRIAGE_SAY_DOC2, guid, None, -1),
            _ => self.do_script_text(TRIAGE_SAY_DOC3, guid, None, -1),
        }
        if let Some(s) = self.patient_state_mut(guid) {
            s.is_saved = true;
        }
        // NEEDS-MAP-HELPER: fork run-to `A_RUNTOX/Y/Z` (-3742.96, -4531.52, 11.91)
        // or `H_RUNTOX/Y/Z` (-1016.44, -3508.48, 62.96) by entry; no entry helper.
    }

    /// `npc_injured_patientAI::UpdateAI` (319-345): bleed-out clock.
    #[allow(clippy::cast_precision_loss)] // `counter as f32` threshold math
    fn patient_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let saved = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::InjuredPatient(s)) if s.is_saved),
        );
        if saved {
            return;
        }
        // 5% of max per second (`0.05 * diff`); health field read/write pattern.
        let max = self.unit_value_u32(guid, offsets::UNIT_FIELD_MAXHEALTH);
        let cur = self.unit_value_u32(guid, offsets::UNIT_FIELD_HEALTH);
        let lose = ((max as f32) * 0.05 * (diff_ms as f32) / 1000.0) as u32;
        if self.unit_is_alive(guid) && cur > 1 + lose {
            self.object_set_field(guid, u32::from(offsets::UNIT_FIELD_HEALTH), cur - lose);
        }
        if self.unit_is_alive(guid) && cur <= 1 + lose {
            // NEEDS-MAP-HELPER: fork flag writes + `SetDeathState(JUST_DIED)` +
            // `UNIT_DYNFLAG_DEAD`; no death-state/dynflag helpers found.
            if let Some(doctor) = self.patient_state_mut(guid).and_then(|s| s.doctor_guid) {
                self.doctor_patient_died(doctor, guid);
            }
        }
    }

