    /// `npc_tonk_mineAI::MoveInLineOfSight` (534-544): steam-tonk proximity fuse.
    fn tonk_mine_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        let armed = self
            .ai
            .get(&guid)
            .is_some_and(|ai| matches!(&ai.script, Some(CreatureScriptAi::TonkMine(s)) if s.armed));
        if !armed {
            return;
        }
        // NEEDS-MAP-HELPER: fork gates on `pWho->GetEntry() == 15328`; no entry
        // helper found, range-only here.
        let near = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy < 2.0 * 2.0
            }
            _ => false,
        };
        if near {
            self.do_cast_spell_if_can(guid, TONK_SPELL_MINE_DETONATE, CastTarget::Unit(who));
            self.despawn_creature_now(guid, 0);
        }
    }

