    /// `npc_pats_firework_guyAI::IsUsable` for a known entry.
    #[allow(dead_code)] // wired by the bind step once the entry is known (NOTE-4)
    fn firework_is_usable(&mut self, guid: ObjectGuid, entry: u32) {
        for (i, known) in FIREWORK_ENTRIES.iter().enumerate() {
            if *known == entry {
                if let Some(s) = self.firework_state_mut(guid) {
                    s.exists = true;
                    s.is_lucky = entry == FIREWORK_NPC_ELUNE;
                    s.index = i as u8;
                }
                break;
            }
        }
    }

    /// `npc_pats_firework_guyAI::UpdateAI` (1023-1139; `diff` unused).
    fn firework_update(&mut self, guid: ObjectGuid, _diff_ms: u32) {
        let (exists, done, index, lucky) =
            self.ai
                .get(&guid)
                .map_or((false, true, 0, false), |ai| match &ai.script {
                    Some(CreatureScriptAi::FireworkGuy(s)) => {
                        (s.exists, s.done, s.index, s.is_lucky)
                    }
                    _ => (false, true, 0, false),
                });
        if !exists || done {
            return;
        }
        let index = (index as usize).min(24);
        let Some(pos) = self.unit_position(guid) else {
            return;
        };
        // NEEDS-MAP-HELPER: fork `NearTeleportTo` hops (large vs small cluster
        // tables) + triggered `CastSpell`s; teleports have no helper, casts are
        // kept in fork order.
        if FIREWORK_LARGE[index] {
            // Large-cluster hop table (teleports dropped).
        } else {
            // Small/single hop table (teleports dropped).
        }
        if FIREWORK_CLUSTER[index] {
            for spell in FIREWORK_SPELLS[index] {
                self.do_cast_spell_if_can(guid, spell, CastTarget::SelfCast);
            }
        } else {
            self.do_cast_spell_if_can(guid, FIREWORK_SPELLS[index][0], CastTarget::SelfCast);
        }
        // NEEDS-MAP-HELPER: fork lunar-fortune 3s delayed event
        // (`m_Events.AddLambdaEventAtOffset`), summoner `KilledMonsterCredit`
        // (cluster? 15894 : 15893), and `boss_omenAI::OnFireworkLaunch` on the
        // omen launcher; none found.
        let _ = (pos, lucky, FIREWORK_NPC_CREDIT, FIREWORK_NPC_CLUSTER_CREDIT);
        if let Some(s) = self.firework_state_mut(guid) {
            s.done = true;
        }
    }

