    /// Entry-gated aura mapping (1315-1335): dummy 2673 / advanced 2674 / master
    /// 12426 pick the spawn + passive pair.
    fn target_dummy_bind(&mut self, guid: ObjectGuid, entry: u32) {
        let (spawn, passive) = match entry {
            DUMMY_ENTRY_ADVANCED => (
                DUMMY_SPELL_ADVANCED_SPAWN_EFFECT,
                DUMMY_SPELL_ADVANCED_PASSIVE,
            ),
            DUMMY_ENTRY_MASTER => (DUMMY_SPELL_SPAWN_EFFECT, DUMMY_SPELL_MASTER_PASSIVE),
            _ => (DUMMY_SPELL_SPAWN_EFFECT, DUMMY_SPELL_PASSIVE),
        };
        if let Some(s) = self.target_dummy_state_mut(guid) {
            s.spawn_effect = spawn;
            s.passive_spell = passive;
        }
    }

    /// `npc_target_dummyAI::Reset` (1337; combat-movement flag) + ctor NOTE-4/5.
    /// NOTE: the ctor aura casts run here on every reset (not just bind); the
    /// re-cast is idempotent and keeps the bind-time setup in one place.
    fn target_dummy_reset(&mut self, guid: ObjectGuid) {
        if let Some(entry) = self.object_entry(guid) {
            self.target_dummy_bind(guid, entry);
        }
        if let Some(ai) = self.ai.get_mut(&guid) {
            ai.combat_movement = false;
        }
        // Ctor aura setup folded here (entry-gated values read from state).
        let (spawn, passive) = self
            .target_dummy_state_mut(guid)
            .map_or((0, 0), |s| (s.spawn_effect, s.passive_spell));
        if spawn != 0 {
            self.do_cast_spell_if_can(guid, spawn, CastTarget::SelfCast);
        }
        if passive != 0 {
            self.apply_aura_by_id(guid, passive, guid);
        }
    }

