    fn shahram_despawn(&mut self, guid: ObjectGuid) {
        // NEEDS-MAP-HELPER: fork `ToPet()->Unsummon(PET_SAVE_AS_DELETED)`; no pet
        // helper found, immediate despawn approximated.
        self.despawn_creature_now(guid, 0);
    }

    /// `npc_shahramAI::UpdatePetAI` (1408-1467; pet base first, NOTE-9) folded
    /// with `UpdateAI` (1470-1478; the 10s hard cap runs first).
    fn shahram_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let expired = {
            let Some(s) = self.shahram_state_mut(guid) else {
                return;
            };
            if s.despawn_timer_ms > diff_ms {
                s.despawn_timer_ms -= diff_ms;
                false
            } else {
                true
            }
        };
        if expired {
            self.shahram_despawn(guid);
            return;
        }
        let active = {
            let Some(s) = self.shahram_state_mut(guid) else {
                return;
            };
            s.combat_despawn_timer_ms > diff_ms
        };
        if active {
            let debuffed = self.ai.get(&guid).is_some_and(
                |ai| matches!(&ai.script, Some(CreatureScriptAi::Shahram(s)) if s.cast_debuff),
            );
            let buffed = self.ai.get(&guid).is_some_and(
                |ai| matches!(&ai.script, Some(CreatureScriptAi::Shahram(s)) if s.cast_buff),
            );
            let mut spell = 0;
            if !debuffed {
                spell = match self.rng.urand(0, 2) {
                    0 => SHAHRAM_SPELL_CURSE,
                    1 => SHAHRAM_SPELL_FLAMES,
                    _ => SHAHRAM_SPELL_MIGHT,
                };
                // Fork nulls the pick when no victim is in 10.0.
                let in_range = match (
                    self.unit_position(guid),
                    self.unit_victim(guid).and_then(|v| self.unit_position(v)),
                ) {
                    (Some(a), Some(b)) => {
                        let dx = a.x - b.x;
                        let dy = a.y - b.y;
                        dx * dx + dy * dy <= 10.0 * 10.0
                    }
                    _ => false,
                };
                if !in_range {
                    spell = 0;
                }
            } else if !buffed {
                spell = match self.rng.urand(0, 3) {
                    0 => SHAHRAM_SPELL_BLESSING,
                    1 => SHAHRAM_SPELL_FIST,
                    _ => SHAHRAM_SPELL_WILL,
                };
            }
            if spell != 0 && self.do_cast_spell_if_can(guid, spell, CastTarget::SelfCast) {
                if let Some(s) = self.shahram_state_mut(guid) {
                    if s.cast_debuff {
                        s.cast_buff = true;
                    } else {
                        s.cast_debuff = true;
                    }
                }
            }
            if let Some(s) = self.shahram_state_mut(guid) {
                s.combat_despawn_timer_ms -= diff_ms;
            }
        } else {
            self.shahram_despawn(guid);
        }
    }

