    /// `MoveInLineOfSight` (1521-1528): hostile within 5.0 trips the fuse.
    fn land_mine_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        let (armed, detonation, despawn) =
            self.ai
                .get(&guid)
                .map_or((false, true, true), |ai| match &ai.script {
                    Some(CreatureScriptAi::GoblinLandMine(s)) => (s.armed, s.detonation, s.despawn),
                    _ => (false, true, true),
                });
        if !armed || detonation || despawn {
            return;
        }
        let near = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy < 5.0 * 5.0
            }
            _ => false,
        };
        // NEEDS-MAP-HELPER: fork `IsHostileTo(m_creature)`; none found.
        if near {
            if let Some(s) = self.land_mine_state_mut(guid) {
                s.detonation = true;
            }
        }
    }

    /// `npc_goblin_land_mineAI::UpdateAI` (1530-1584).
    fn land_mine_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Self-despawn clock (1533-1541).
        let despawn = self.land_mine_state_mut(guid).is_none_or(|s| s.despawn);
        if !despawn {
            let due = {
                let Some(s) = self.land_mine_state_mut(guid) else {
                    return;
                };
                if s.despawn_timer_ms < diff_ms {
                    true
                } else {
                    s.despawn_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                if let Some(s) = self.land_mine_state_mut(guid) {
                    s.despawn = true;
                }
            }
        }
        // Arming clock (1543-1554); returns early while unarmed.
        let armed = self.land_mine_state_mut(guid).is_some_and(|s| s.armed);
        if !armed {
            let due = {
                let Some(s) = self.land_mine_state_mut(guid) else {
                    return;
                };
                if s.arm_timer_ms < diff_ms {
                    true
                } else {
                    s.arm_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                if let Some(s) = self.land_mine_state_mut(guid) {
                    s.armed = true;
                }
            }
            return;
        }
        // Detonation arm (1556-1569).
        let (detonation, despawn) =
            self.ai
                .get(&guid)
                .map_or((false, true), |ai| match &ai.script {
                    Some(CreatureScriptAi::GoblinLandMine(s)) => (s.detonation, s.despawn),
                    _ => (false, true),
                });
        if detonation && !despawn {
            // NEEDS-MAP-HELPER: fork `DoStartNoMovement(victim)`; none found.
            let due = {
                let Some(s) = self.land_mine_state_mut(guid) else {
                    return;
                };
                if s.detonation_timer_ms < diff_ms {
                    true
                } else {
                    s.detonation_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                // Fork is a raw `CastSpell` (no CAST_OK gate).
                self.do_cast_spell_if_can(guid, GLM_SPELL_DETONATION, CastTarget::SelfCast);
                if let Some(s) = self.land_mine_state_mut(guid) {
                    s.despawn = true;
                    s.despawn_timer_ms = 500;
                    s.detonation = false;
                }
            }
        }
        // Despawn arm (1571-1583).
        let despawn = self.land_mine_state_mut(guid).is_some_and(|s| s.despawn);
        if despawn {
            let due = {
                let Some(s) = self.land_mine_state_mut(guid) else {
                    return;
                };
                if s.despawn_timer_ms < diff_ms {
                    true
                } else {
                    s.despawn_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                // NEEDS-MAP-HELPER: fork `GetOwner()->RemoveGuardian` +
                // `RemoveFromWorld()` (no corpse); owner/guardian helpers missing.
                self.despawn_creature_now(guid, 0);
            }
        }
    }

