    /// `SpellHit` (1631-1660): salve turns the critter.
    fn sickly_spell_hit(&mut self, guid: ObjectGuid, caster: ObjectGuid, spell_id: u32) {
        if spell_id != SICKLY_SPELL_APPLY_SALVE {
            // NEEDS-MAP-HELPER: base `CritterAI::SpellHit`; critter base NOTE-9.
            return;
        }
        let hit = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::SicklyCritter(s)) if s.is_hit),
        );
        if hit {
            return;
        }
        // NEEDS-MAP-HELPER: fork `ToPlayer()` + entry gate (12298/12296) +
        // `GetTeam()`; no player/entry helpers found. Records the cure.
        if let Some(s) = self.sickly_state_mut(guid) {
            s.player_guid = Some(caster);
            s.team = 0;
            s.modify = true;
            s.is_hit = true;
        }
        // NEEDS-MAP-HELPER: fork `MoveFleeing(player)` + `ForcedDespawn(10_000)`;
        // none found (despawn approximated, flee dropped).
        self.despawn_creature_now(guid, 10);
    }

    /// `npc_sickly_critterAI::UpdateAI` (1662-1691; critter base NOTE-9).
    fn sickly_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let modify = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::SicklyCritter(s)) if s.modify),
        );
        if modify {
            let due = {
                let Some(s) = self.sickly_state_mut(guid) else {
                    return;
                };
                if s.timer_ms < diff_ms {
                    true
                } else {
                    s.timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                // NEEDS-MAP-HELPER: fork `SetEntry`/`SetDisplayId` by team +
                // `RewardPlayerAndGroupAtCast(player)`; no entry/display/quest
                // helpers found. The cured form below keeps consts + fields live.
                let (team, player) = self
                    .sickly_state_mut(guid)
                    .map_or((0, None), |s| (s.team, s.player_guid));
                let cured_entry = if team == 0 {
                    SICKLY_NPC_CURED_DEER
                } else {
                    SICKLY_NPC_CURED_GAZELLE
                };
                let cured_model = if team == 0 {
                    SICKLY_MODEL_CURED_DEER
                } else {
                    SICKLY_MODEL_CURED_GAZELLE
                };
                let _ = (cured_entry, cured_model, player);
                self.cancel_aura(guid, SICKLY_SPELL_AURA);
                if let Some(s) = self.sickly_state_mut(guid) {
                    s.modify = false;
                }
            }
        }
    }

