    /// Zone-yell text picker for the Mouth (`PickRandomValue` of 4).
    fn mouth_random_yell(&mut self) -> i32 {
        match self.rng.urand(0, 3) {
            0 => SI_BCT_MOUTH_RANDOM_1,
            1 => SI_BCT_MOUTH_RANDOM_2,
            2 => SI_BCT_MOUTH_RANDOM_3,
            _ => SI_BCT_MOUTH_RANDOM_4,
        }
    }

    /// `MouthAI::Reset` (empty; ctor schedules the yell -> reset, NOTE-4).
    fn mouth_reset(&mut self, guid: ObjectGuid) {
        let next = self.rng.urand(150_000, 3_600_000);
        if let Some(s) = self.mouth_state_mut(guid) {
            s.yell_timer_ms = next;
        }
    }

    /// `MouthAI::OnScriptEventHappened` (295-312): zone-start/stop fanfare.
    /// NO-DISPATCHER-YET (unlisted virtual; see NOTE-1).
    #[allow(dead_code)] // wired by the world-script event bus (no dispatcher yet)
    fn mouth_on_script_event(&mut self, guid: ObjectGuid, event: u32) {
        // NEEDS-MAP-HELPER: fork `ChangeZoneEventStatus` + `SetWeather` (storm on
        // start, rain off on stop); none found.
        match event {
            SI_EVENT_MOUTH_ZONE_START => {
                let text = if self.rng.urand(0, 1) == 0 {
                    SI_BCT_MOUTH_SPAWN_1
                } else {
                    SI_BCT_MOUTH_SPAWN_2
                };
                self.do_script_text(text, guid, None, SI_CHAT_ZONE_YELL);
            }
            SI_EVENT_MOUTH_ZONE_STOP => {
                let text = match self.rng.urand(0, 2) {
                    0 => SI_BCT_MOUTH_DESPAWN_1,
                    1 => SI_BCT_MOUTH_DESPAWN_2,
                    _ => SI_BCT_MOUTH_DESPAWN_3,
                };
                self.do_script_text(text, guid, None, SI_CHAT_ZONE_YELL);
                self.despawn_creature_now(guid, 0);
            }
            _ => {}
        }
    }

    /// `MouthAI::UpdateAI` (314-330): the single `EVENT_MOUTH_OF_KELTHUZAD_YELL`
    /// (id 6) timer.
    fn mouth_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let due = {
            let Some(s) = self.mouth_state_mut(guid) else {
                return;
            };
            if s.yell_timer_ms < diff_ms {
                true
            } else {
                s.yell_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            let text = self.mouth_random_yell();
            self.do_script_text(text, guid, None, SI_CHAT_ZONE_YELL);
            let next = self.rng.urand(150_000, 3_600_000);
            if let Some(s) = self.mouth_state_mut(guid) {
                s.yell_timer_ms = next;
            }
        }
    }

