    /// `NecropolisHealthAI::SpellHit` (373-390).
    fn necropolis_health_spell_hit(
        &mut self,
        guid: ObjectGuid,
        _caster: ObjectGuid,
        spell_id: u32,
    ) {
        match spell_id {
            SI_SPELL_COMMUNIQUE_CAMP_TO_RELAY_DEATH => {
                self.do_cast_spell_if_can(guid, SI_SPELL_ZAP_NECROPOLIS, CastTarget::SelfCast);
            }
            SI_SPELL_ZAP_NECROPOLIS => {
                // NEEDS-MAP-HELPER: fork `DealDamage(self, 666)`; approximated with
                // the zap counter only (7th zap kills via `ZAP_CRYSTAL_CORPSE`).
                if let Some(s) = self.necropolis_health_state_mut(guid) {
                    s.zapped += 1;
                }
                let zapped = self
                    .necropolis_health_state_mut(guid)
                    .map_or(0, |s| s.zapped);
                if zapped >= 7 {
                    self.do_cast_spell_if_can(
                        guid,
                        SI_SPELL_ZAP_CRYSTAL_CORPSE,
                        CastTarget::SelfCast,
                    );
                }
            }
            _ => {}
        }
    }

    /// `NecropolisHealthAI::JustDied` (392-417).
    fn necropolis_health_just_died(&mut self, guid: ObjectGuid) {
        // Nearest necropolis gets the despawner communique (`GetClosestCreature
        // WithEntry`; `find_creature_by_entry` is not nearest, so scan inline).
        let me = self.unit_position(guid).unwrap_or_default();
        let necropolis = self
            .creatures
            .values()
            .filter(|c| c.info.entry == SI_NPC_NECROPOLIS && c.unit.is_alive())
            .map(|c| {
                let p = c.unit.world.position();
                let dx = p.x - me.x;
                let dy = p.y - me.y;
                (c.unit.guid(), dx * dx + dy * dy)
            })
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .map(|(g, _)| g);
        if let Some(necropolis) = necropolis {
            self.do_cast_spell_if_can(guid, SI_SPELL_DESPAWNER_OTHER, CastTarget::Unit(necropolis));
        }
        // NEEDS-MAP-HELPER: fork decrements the zone `VAR_Z_*` saved variable by
        // zone id (1421/1377/3428/139/3429/28 -> VAR_Z_EPL/WPL/DUSKWOOD/etc.);
        // no zone/saved-var helpers found.
    }

