    /// `NecroticShard::SpellHit` (575-638).
    #[allow(clippy::match_same_arms)]
    fn necrotic_shard_spell_hit(&mut self, guid: ObjectGuid, caster: ObjectGuid, spell_id: u32) {
        match spell_id {
            SI_SPELL_ZAP_CRYSTAL_CORPSE => {
                // NEEDS-MAP-HELPER: fork `DealDamage(self, maxhealth / 4)`;
                // damage dropped.
            }
            SI_SPELL_COMMUNIQUE_RELAY_TO_CAMP => {
                self.do_cast_spell_if_can(
                    guid,
                    SI_SPELL_CAMP_RECEIVES_COMMUNIQUE,
                    CastTarget::SelfCast,
                );
            }
            SI_SPELL_CHOOSE_CAMP_TYPE => {
                let pick = match self.rng.urand(0, 2) {
                    0 => SI_SPELL_CAMP_GHOUL_SKELETON,
                    1 => SI_SPELL_CAMP_GHOST_GHOUL,
                    _ => SI_SPELL_CAMP_GHOST_SKELETON,
                };
                if let Some(s) = self.necrotic_shard_state_mut(guid) {
                    s.camp_type = pick;
                }
                self.do_cast_spell_if_can(guid, pick, CastTarget::SelfCast);
            }
            SI_SPELL_CAMP_RECEIVES_COMMUNIQUE => {
                // NEEDS-MAP-HELPER: fork gates on `!GetCampType` + own entry
                // (NECROTIC_SHARD); no aura/entry helpers found, arm kept.
                // NEEDS-MAP-HELPER: fork `GetFindersAmount()`; count stays 0.
                self.do_cast_spell_if_can(guid, SI_SPELL_CHOOSE_CAMP_TYPE, CastTarget::SelfCast);
                if let Some(s) = self.necrotic_shard_state_mut(guid) {
                    s.spawner_small_timer_ms = 0;
                    s.spawner_small_on = true;
                }
            }
            SI_SPELL_FIND_CAMP_TYPE => {
                // NEEDS-MAP-HELPER: fork returns when `m_finders < HasMinion(self,
                // 60)`; no minion-scan helper found, trap arm kept unconditional.
                // The finder (caster) lays the camp trap by the shard's aura.
                let camp = self
                    .necrotic_shard_state_mut(guid)
                    .map_or(0, |s| s.camp_type);
                let trap = match camp {
                    SI_SPELL_CAMP_GHOST_SKELETON => SI_SPELL_SUMMON_MINION_GHOST_SKELETON,
                    SI_SPELL_CAMP_GHOST_GHOUL => SI_SPELL_SUMMON_MINION_GHOST_GHOUL,
                    SI_SPELL_CAMP_GHOUL_SKELETON => SI_SPELL_SUMMON_MINION_GHOUL_SKELETON,
                    _ => 0,
                };
                if trap != 0 {
                    self.do_cast_spell_if_can(caster, trap, CastTarget::Unit(caster));
                }
            }
            SI_SPELL_ZAP_NECROPOLIS => {
                // NEEDS-MAP-HELPER: fork `DealDamage(self, 1332)`; damage dropped.
                self.do_cast_spell_if_can(guid, SI_SPELL_ZAP_CRYSTAL_CORPSE, CastTarget::SelfCast);
            }
            SI_SPELL_CREATE_SUMMONER_SHIELD => {
                self.do_cast_spell_if_can(
                    guid,
                    SI_SPELL_COMMUNIQUE_CAMP_TO_RELAY,
                    CastTarget::SelfCast,
                );
            }
            _ => {}
        }
    }

