    /// `NecroticShard::JustDied` (621-649), entry-switched.
    /// NEEDS-MAP-HELPER: fork switches on own entry (16136 normal vs 16172
    /// damaged); no entry helper found. The normal arm runs below; set
    /// `damaged = true` at bind for the damaged arm once the helper lands.
    fn necrotic_shard_just_died(&mut self, guid: ObjectGuid) {
        let damaged = false;
        if damaged {
            // Damaged arm: buff players, death-bolt the nearest relay (200),
            // then cultist/doodad cleanup.
            self.do_cast_spell_if_can(guid, SI_SPELL_SOUL_REVIVAL, CastTarget::SelfCast);
            let me = self.unit_position(guid).unwrap_or_default();
            let relay = self
                .creatures
                .values()
                .filter(|c| c.info.entry == SI_NPC_NECROPOLIS_RELAY && c.unit.is_alive())
                .map(|c| {
                    let p = c.unit.world.position();
                    let dx = p.x - me.x;
                    let dy = p.y - me.y;
                    (c.unit.guid(), dx * dx + dy * dy)
                })
                .filter(|(_, d)| *d <= 200.0 * 200.0)
                .min_by(|a, b| a.1.total_cmp(&b.1))
                .map(|(g, _)| g);
            if let Some(relay) = relay {
                self.do_cast_spell_if_can(
                    guid,
                    SI_SPELL_COMMUNIQUE_CAMP_TO_RELAY_DEATH,
                    CastTarget::Unit(relay),
                );
            }
            // NEEDS-MAP-HELPER: fork `DespawnCultists()` + `DespawnEventDoodads()`;
            // none found.
        } else {
            // Normal arm: summon the damaged shard at self, hand it the camp
            // type (or `CHOOSE_CAMP_TYPE` when none), then self `RemoveFromWorld`.
            if let Some(pos) = self.unit_position(guid) {
                let created = self.summon_creature(
                    SI_NPC_DAMAGED_SHARD,
                    Position::new(pos.x, pos.y, pos.z, pos.o),
                    guid,
                    SI_TEMPSUMMON_TIMED_OR_DEAD,
                    0,
                );
                if let Some(shard) = created {
                    let camp = self
                        .necrotic_shard_state_mut(guid)
                        .map_or(0, |s| s.camp_type);
                    if camp != 0 {
                        self.do_cast_spell_if_can(shard, camp, CastTarget::Unit(shard));
                    } else {
                        self.do_cast_spell_if_can(
                            shard,
                            SI_SPELL_CHOOSE_CAMP_TYPE,
                            CastTarget::Unit(shard),
                        );
                    }
                    self.despawn_creature_now(guid, 0);
                }
            }
        }
        // Cracked-crystal death rattle (both arms in the fork header flow).
        self.do_cast_spell_if_can(guid, SI_SPELL_CRACKED_CRYSTAL, CastTarget::SelfCast);
    }

    /// `NecroticShard::UpdateAI` (706-723): the two spawner events.
    fn necrotic_shard_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let small_on = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::NecroticShard(s)) if s.spawner_small_on)
        });
        if small_on {
            let due = {
                let Some(s) = self.necrotic_shard_state_mut(guid) else {
                    return;
                };
                if s.spawner_small_timer_ms < diff_ms {
                    true
                } else {
                    s.spawner_small_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                // NEEDS-MAP-HELPER: fork `FindNearestFinders()` (FINDER sorted by
                // distance), each finder casts `FIND_CAMP_TYPE` + `SetRespawnDelay
                // (FINDER_RESPAWN_TIME)` + `DisappearAndDie()`; finder iteration
                // and respawn-delay writes missing.
                if let Some(s) = self.necrotic_shard_state_mut(guid) {
                    s.spawner_small_timer_ms = 1500;
                }
            }
        }
        let buttress_on = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::NecroticShard(s)) if s.spawner_buttress_on)
        });
        if buttress_on {
            let due = {
                let Some(s) = self.necrotic_shard_state_mut(guid) else {
                    return;
                };
                if s.spawner_buttress_timer_ms < diff_ms {
                    true
                } else {
                    s.spawner_buttress_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                // NEEDS-MAP-HELPER: fork `SetFullHealth()` + `DespawnShadows()`
                // + `SummonCultists()` (4 engineers on a 3.5 circle +
                // `OnScriptEventHappened(7166)`); none found.
                if let Some(s) = self.necrotic_shard_state_mut(guid) {
                    s.spawner_buttress_timer_ms = 3000;
                }
            }
        }
    }

    /// `MinionspawnerAI::Reset` (empty; ctor schedules 2000 -> `new()`).
    #[allow(clippy::unused_self)]
    fn minion_spawner_reset(&mut self, _guid: ObjectGuid) {}

    /// `MinionspawnerAI::SelectRandomUncommonMinionEntry` (739-757) +
    /// `UpdateAI` (759-777).
    fn minion_spawner_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let on = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::MinionSpawner(s)) if s.summon_on),
        );
        if !on {
            return;
        }
        let due = {
            let Some(s) = self.minion_spawner_state_mut(guid) else {
                return;
            };
            if s.summon_timer_ms <= diff_ms {
                true
            } else {
                s.summon_timer_ms -= diff_ms;
                false
            }
        };
        if !due {
            return;
        }
        // NEEDS-MAP-HELPER: fork gates on spawner entry (16306/16336/16338) and
        // `UncommonMinionspawner()` (1/217 roll + no rares within 150); no entry
        // helper found. Rare/common pick kept as a 1/217 roll.
        let rare = self.rng.urand(0, 216) == 0;
        let entry = if rare {
            match self.rng.urand(0, 4) {
                0 => SI_NPC_GHOUL_BERSERKER,
                1 => SI_NPC_SPECTRAL_SOLDIER,
                2 => SI_NPC_SKELETAL_SHOCKTROOPER,
                3 => SI_NPC_LUMBERING_HORROR,
                _ => SI_NPC_BONE_WITCH,
            }
        } else {
            SI_NPC_SPIRIT_OF_DAMNED
        };
        if let Some(pos) = self.unit_position(guid) {
            let created = self.summon_creature(
                entry,
                Position::new(pos.x, pos.y, pos.z, pos.o),
                guid,
                SI_TEMPSUMMON_TIMED_OR_DEAD,
                3_600_000,
            );
            if let Some(minion) = created {
                // NEEDS-MAP-HELPER: fork `SetWanderDistance(10)` + `SendSpellGo`;
                // none found.
                self.do_cast_spell_if_can(minion, SI_SPELL_MINION_SPAWN_IN, CastTarget::SelfCast);
            }
        }
        if let Some(s) = self.minion_spawner_state_mut(guid) {
            s.summon_timer_ms = 60_000;
        }
    }

