    /// `npc_cultist_engineer::JustDied` (797-812).
    fn cultist_engineer_just_died(&mut self, guid: ObjectGuid) {
        // Nearest damaged shard hears the death communique.
        let me = self.unit_position(guid).unwrap_or_default();
        let shard = self
            .creatures
            .values()
            .filter(|c| c.info.entry == SI_NPC_DAMAGED_SHARD && c.unit.is_alive())
            .map(|c| {
                let p = c.unit.world.position();
                let dx = p.x - me.x;
                let dy = p.y - me.y;
                (c.unit.guid(), dx * dx + dy * dy)
            })
            .filter(|(_, d)| *d <= 15.0 * 15.0)
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .map(|(g, _)| g);
        if let Some(shard) = shard {
            self.do_cast_spell_if_can(guid, SI_SPELL_DAMAGE_CRYSTAL, CastTarget::Unit(shard));
            self.cancel_aura(shard, SI_SPELL_BUTTRESS_CHANNEL);
            // NEEDS-MAP-HELPER: fork resets the shard channeling spell id
            // (`SetChannelingSpellId(0)`); none found.
        }
        // NEEDS-MAP-HELPER: fork deletes the nearest `SUMMONER_SHIELD` GO within
        // `CONTACT_DISTANCE`; no GO-delete helper found.
    }

    /// `npc_cultist_engineer::OnScriptEventHappened` (824-855): the fork takes
    /// `(uiEvent, uiData, pInvoker)`; `uiData`/`pInvoker` have no hook params
    /// (dispatcher gap, NOTE-1). Shadow arm requires `uiEvent == 7166 &&
    /// uiData == 0` with a player invoker.
    /// NO-DISPATCHER-YET (unlisted virtual; see NOTE-1).
    #[allow(dead_code)] // wired by the shard summon path (no dispatcher yet)
    fn cultist_engineer_on_script_event(&mut self, guid: ObjectGuid, event: u32) {
        match event {
            7166 => {
                // NEEDS-MAP-HELPER: fork `pPlayer->SummonCreature(SHADOW_OF_DOOM)`
                // at the engineer (TIMED_OR_DEAD 3_600_000) + `IMMUNE_TO_PLAYER`
                // flag + facing + shadow `OnScriptEventHappened(NPC_SHADOW_OF_DOOM,
                // 0, player)` + `DestroyItemCount(NECROTIC_RUNE 22484, 8)` +
                // player `SendSpellGo(SUMMON_BOSS)`; summoner-owned summon kept.
                if let Some(pos) = self.unit_position(guid) {
                    self.summon_creature(
                        SI_NPC_SHADOW_OF_DOOM,
                        Position::new(pos.x, pos.y, pos.z, pos.o),
                        guid,
                        SI_TEMPSUMMON_TIMED_OR_DEAD,
                        3_600_000,
                    );
                }
                // NEEDS-MAP-HELPER: fork `DestroyItemCount(NECROTIC_RUNE 22484, 8)`
                // on the invoker + player `SendSpellGo(SUMMON_BOSS)`; none found.
                self.do_cast_spell_if_can(guid, SI_SPELL_QUIET_SUICIDE, CastTarget::SelfCast);
            }
            SI_NPC_CULTIST_ENGINEER => {
                // NEEDS-MAP-HELPER: fork `SetCorpseDelay(10)` + nearest-GO shield
                // pick; none found. Records the channeling arm.
                self.do_cast_spell_if_can(
                    guid,
                    SI_SPELL_CREATE_SUMMONER_SHIELD,
                    CastTarget::SelfCast,
                );
                self.do_cast_spell_if_can(guid, SI_SPELL_MINION_SPAWN_IN, CastTarget::SelfCast);
                if let Some(s) = self.cultist_engineer_state_mut(guid) {
                    s.channeling_timer_ms = 1000;
                    s.channeling_on = true;
                }
            }
            _ => {}
        }
    }

    /// `npc_cultist_engineer::UpdateAI` (790-822): the CHANNELING event (5).
    fn cultist_engineer_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let on = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::CultistEngineer(s)) if s.channeling_on)
        });
        if !on {
            return;
        }
        let due = {
            let Some(s) = self.cultist_engineer_state_mut(guid) else {
                return;
            };
            if s.channeling_timer_ms <= diff_ms {
                true
            } else {
                s.channeling_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // Channel the nearest damaged shard within 15 (790-801).
            let me = self.unit_position(guid).unwrap_or_default();
            let shard = self
                .creatures
                .values()
                .filter(|c| c.info.entry == SI_NPC_DAMAGED_SHARD && c.unit.is_alive())
                .map(|c| {
                    let p = c.unit.world.position();
                    let dx = p.x - me.x;
                    let dy = p.y - me.y;
                    (c.unit.guid(), dx * dx + dy * dy)
                })
                .filter(|(_, d)| *d <= 15.0 * 15.0)
                .min_by(|a, b| a.1.total_cmp(&b.1))
                .map(|(g, _)| g);
            if let Some(shard) = shard {
                // NEEDS-MAP-HELPER: fork `UNIT_CHANNEL_SPELL` /
                // `UNIT_CHANNEL_OBJECT` field writes (both sides); none found.
                self.apply_aura_by_id(shard, SI_SPELL_BUTTRESS_CHANNEL, shard);
            }
            if let Some(s) = self.cultist_engineer_state_mut(guid) {
                s.channeling_timer_ms = 1000;
            }
        }
    }

