    /// `ScourgeMinion::UpdateAI` (958-986).
    #[allow(clippy::too_many_lines)]
    fn scourge_minion_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // DOOM_START_ATTACK (5000): drop immunity, summoner joins in.
        let start_on = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::ScourgeMinion(s)) if s.start_attack_on)
        });
        if start_on {
            let due = {
                let Some(s) = self.scourge_minion_state_mut(guid) else {
                    return;
                };
                if s.start_attack_timer_ms <= diff_ms {
                    true
                } else {
                    s.start_attack_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                // NEEDS-MAP-HELPER: fork clears `IMMUNE_TO_PLAYER` + the summoner
                // `SetInCombatWithZone()`; no unit-flag helper found.
                self.set_in_combat_with_zone(guid);
                if let Some(s) = self.scourge_minion_state_mut(guid) {
                    s.start_attack_on = false;
                }
            }
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        // Scourge strike: charmer/owner-player (or player) victims die outright.
        // NEEDS-MAP-HELPER: fork `IsCharmerOrOwnerPlayerOrPlayerItself` +
        // `IsValidAttackTarget`; none found, cast kept on the victim.
        let _ = self.do_cast_spell_if_can(guid, SI_SPELL_SCOURGE_STRIKE, CastTarget::Unit(victim));
        // Mindflay / fear rot (<=).
        let mind_on = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::ScourgeMinion(s)) if s.mindflay_on),
        );
        if mind_on {
            let due = {
                let Some(s) = self.scourge_minion_state_mut(guid) else {
                    return;
                };
                if s.mindflay_timer_ms <= diff_ms {
                    true
                } else {
                    s.mindflay_timer_ms -= diff_ms;
                    false
                }
            };
            if due && self.do_cast_spell_if_can(guid, SI_SPELL_MINDFLAY, CastTarget::Unit(victim)) {
                if let Some(s) = self.scourge_minion_state_mut(guid) {
                    s.mindflay_timer_ms = 10_000;
                }
            }
        }
        let fear_on = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::ScourgeMinion(s)) if s.fear_on),
        );
        if fear_on {
            let due = {
                let Some(s) = self.scourge_minion_state_mut(guid) else {
                    return;
                };
                if s.fear_timer_ms <= diff_ms {
                    true
                } else {
                    s.fear_timer_ms -= diff_ms;
                    false
                }
            };
            if due && self.do_cast_spell_if_can(guid, SI_SPELL_FEAR, CastTarget::Unit(victim)) {
                if let Some(s) = self.scourge_minion_state_mut(guid) {
                    s.fear_timer_ms = 15_000;
                }
            }
        }
        // Flameshocker touch + idle despawn (<=).
        let touch_on = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::ScourgeMinion(s)) if s.touch_on),
        );
        if touch_on {
            let due = {
                let Some(s) = self.scourge_minion_state_mut(guid) else {
                    return;
                };
                if s.touch_timer_ms <= diff_ms {
                    true
                } else {
                    s.touch_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                if let Some(target) = self.select_attacking_target(guid, 0, 0, 0x200) {
                    // Fork is triggered + `PickRandomValue(TOUCH, TOUCH2)` (NOTE-8).
                    let touch = if self.rng.urand(0, 1) == 0 {
                        SI_SPELL_FLAMESHOCKERS_TOUCH
                    } else {
                        SI_SPELL_FLAMESHOCKERS_TOUCH2
                    };
                    self.do_cast_spell_if_can(guid, touch, CastTarget::Unit(target));
                }
                if let Some(s) = self.scourge_minion_state_mut(guid) {
                    s.touch_timer_ms = 1000;
                }
            }
            let despawn_on = self.ai.get(&guid).is_some_and(|ai| {
                matches!(&ai.script, Some(CreatureScriptAi::ScourgeMinion(s)) if s.flameshocker_despawn_on)
            });
            if despawn_on {
                let due = {
                    let Some(s) = self.scourge_minion_state_mut(guid) else {
                        return;
                    };
                    if s.flameshocker_despawn_timer_ms <= diff_ms {
                        true
                    } else {
                        s.flameshocker_despawn_timer_ms -= diff_ms;
                        false
                    }
                };
                if due && !self.ai_in_combat(guid) {
                    self.do_cast_spell_if_can(guid, SI_SPELL_DESPAWNER_SELF, CastTarget::SelfCast);
                    if let Some(s) = self.scourge_minion_state_mut(guid) {
                        s.flameshocker_despawn_on = false;
                    }
                }
            }
        }
    }

    /// Pallid-horror random yell picker (`PickRandomValue` of 8).
    fn pallid_random_yell(&mut self) -> i32 {
        match self.rng.urand(0, 7) {
            0 => SI_BCT_PALLID_YELL1,
            1 => SI_BCT_PALLID_YELL2,
            2 => SI_BCT_PALLID_YELL3,
            3 => SI_BCT_PALLID_YELL4,
            4 => SI_BCT_PALLID_YELL5,
            5 => SI_BCT_PALLID_YELL6,
            6 => SI_BCT_PALLID_YELL7,
            _ => SI_BCT_PALLID_YELL8,
        }
    }

