    /// `PallidHorrorAI::JustDied` (1208-1251).
    fn pallid_horror_just_died(&mut self, guid: ObjectGuid) {
        // Zone warlord answers the death (nearest of Bolvar/Sylvanas, no range cap).
        let me = self.unit_position(guid).unwrap_or_default();
        let warlord = self
            .creatures
            .values()
            .filter(|c| {
                (c.info.entry == SI_NPC_BOLVAR || c.info.entry == SI_NPC_SYLVANAS)
                    && c.unit.is_alive()
            })
            .map(|c| {
                let p = c.unit.world.position();
                let dx = p.x - me.x;
                let dy = p.y - me.y;
                (c.unit.guid(), c.info.entry, dx * dx + dy * dy)
            })
            .min_by(|a, b| a.2.total_cmp(&b.2));
        if let Some((warlord, entry, _)) = warlord {
            let text = if entry == SI_NPC_BOLVAR {
                SI_BCT_BOLVAR_2
            } else {
                SI_BCT_SYLVANAS_1
            };
            self.do_script_text(text, warlord, None, SI_CHAT_ZONE_YELL);
        }
        // NEEDS-MAP-HELPER: fork `DoKillUnit` on every flameshocker in
        // `m_lFlameshockers`; no damage helper found, despawn approximated.
        let flames = self
            .pallid_horror_state_mut(guid)
            .map(|s| std::mem::take(&mut s.flameshockers))
            .unwrap_or_default();
        for flame in flames {
            self.despawn_creature_now(flame, 0);
        }
        // NEEDS-MAP-HELPER: fork picks the FAINT (28699, Undercity) vs CRACKED
        // summon spell by `GetZoneId() == ZONEID_UNDERCITY` + sets the zone-time
        // saved var; no zone/saved-var helpers found.
        let undercity = false;
        let crystal = if undercity {
            28_699
        } else {
            SI_SPELL_CRACKED_CRYSTAL
        };
        self.do_cast_spell_if_can(guid, crystal, CastTarget::SelfCast);
        self.cancel_aura(guid, SI_SPELL_AURA_OF_FEAR);
    }

