    /// `PallidHorrorAI::UpdateAI` (1285-1288 + events 1291-1357).
    fn pallid_horror_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let yell_due = {
            let Some(s) = self.pallid_horror_state_mut(guid) else {
                return;
            };
            if s.yell_timer_ms <= diff_ms {
                true
            } else {
                s.yell_timer_ms -= diff_ms;
                false
            }
        };
        if yell_due {
            let text = self.pallid_random_yell();
            self.do_script_text(text, guid, None, SI_CHAT_ZONE_YELL);
            if let Some(s) = self.pallid_horror_state_mut(guid) {
                s.yell_timer_ms = 30_000;
            }
        }
        let damage_due = {
            let Some(s) = self.pallid_horror_state_mut(guid) else {
                return;
            };
            if s.damage_timer_ms <= diff_ms {
                true
            } else {
                s.damage_timer_ms -= diff_ms;
                false
            }
        };
        if damage_due {
            if let Some(victim) = self.unit_victim(guid) {
                // Fork is triggered vs guards; not modeled (NOTE-8).
                self.do_cast_spell_if_can(
                    guid,
                    SI_SPELL_DAMAGE_VS_GUARDS,
                    CastTarget::Unit(victim),
                );
            }
            if let Some(s) = self.pallid_horror_state_mut(guid) {
                s.damage_timer_ms = 1000;
            }
        }
        let summon_due = {
            let Some(s) = self.pallid_horror_state_mut(guid) else {
                return;
            };
            if s.summon_timer_ms <= diff_ms {
                true
            } else {
                s.summon_timer_ms -= diff_ms;
                false
            }
        };
        if summon_due {
            // NEEDS-MAP-HELPER: fork `SelectRandomFlameshockerSpawnTarget`
            // (guard/boss or victim position) + `GetNearPoint` + summon +
            // `OnScriptEventHappened(40)` on the spawn; none found. Records the
            // re-arm only.
            if let Some(s) = self.pallid_horror_state_mut(guid) {
                s.summon_timer_ms = 30_000;
            }
        }
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
    }

