    /// `npc_AQwar_collectorAI::UpdateAI` (549-556): 60s progress tick.
    fn aq_collector_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let due = {
            let Some(s) = self.aq_collector_state_mut(guid) else {
                return;
            };
            if s.update_timer_ms < diff_ms {
                true
            } else {
                s.update_timer_ms -= diff_ms;
                false
            }
        };
        if !due {
            return;
        }
        self.aq_collector_gathering(guid);
        if self.aq_collector_objective_done(guid) {
            self.aq_collector_remove_questgiver(guid);
        }
        if let Some(s) = self.aq_collector_state_mut(guid) {
            s.update_timer_ms = 60_000;
        }
    }

    /// Zone-gated whisper strength (`world_event_wareffort.cpp` 684-697).
    #[allow(dead_code)] // wired by the bind step once the zone is known (NOTE-4)
    #[allow(clippy::match_same_arms)]
    fn resonating_whisper_for_zone(zone: u32) -> u32 {
        match zone {
            WE_ZONE_BARRENS => RESON_SPELL_WHISPER_0,
            WE_ZONE_THOUSAND_NEEDLES => RESON_SPELL_WHISPER_1,
            WE_ZONE_DESOLACE => RESON_SPELL_WHISPER_2,
            WE_ZONE_FERALAS | WE_ZONE_TANARIS | WE_ZONE_UN_GORO => RESON_SPELL_WHISPER_3,
            WE_ZONE_SILITHUS => RESON_SPELL_WHISPER_4,
            _ => RESON_SPELL_WHISPER_4,
        }
    }

    /// `npc_resonating_CrystalAI::Reset` (713-720; combat-movement flag).
    fn resonating_reset(&mut self, guid: ObjectGuid) {
        if let Some(ai) = self.ai.get_mut(&guid) {
            ai.combat_movement = false;
        }
        if let Some(s) = self.resonating_state_mut(guid) {
            s.player_detected = false;
            s.check_timer_ms = 2000;
            s.whisperings_timer_ms = 1000;
        }
    }

    /// `npc_resonating_CrystalAI::MoveInLineOfSight` (722-733): 55.0 tripwire.
    fn resonating_move_in_line_of_sight(&mut self, guid: ObjectGuid, who: ObjectGuid) {
        // NEEDS-MAP-HELPER: fork `IsPlayer()` + `!IsGameMaster()`; player-kind
        // helpers missing, proximity-only here.
        let near = match (self.unit_position(guid), self.unit_position(who)) {
            (Some(a), Some(b)) => {
                let dx = a.x - b.x;
                let dy = a.y - b.y;
                dx * dx + dy * dy <= 55.0 * 55.0
            }
            _ => false,
        };
        if self.players.contains_key(&who) && self.unit_is_alive(who) {
            if let Some(s) = self.resonating_state_mut(guid) {
                s.player_detected = near;
            }
        }
    }

    /// `npc_resonating_CrystalAI::MoreThanOnePlayerNear` (735-751).
    fn resonating_many_players(&mut self, guid: ObjectGuid) -> bool {
        let Some(me) = self.unit_position(guid) else {
            return false;
        };
        // NEEDS-MAP-HELPER: fork `IsGameMaster()` filter; none found.
        let mut count = 0;
        for player in self.players.keys().copied().collect::<Vec<_>>() {
            if !self.unit_is_alive(player) {
                continue;
            }
            if let Some(pp) = self.object_position(player) {
                let dx = pp.x - me.x;
                let dy = pp.y - me.y;
                if dx * dx + dy * dy <= 55.0 * 55.0 {
                    count += 1;
                    if count > 1 {
                        return true;
                    }
                }
            }
        }
        false
    }

    /// `npc_resonating_CrystalAI::AggroAllPlayerNear` (753-767).
    fn resonating_aggro_all_near(&mut self, guid: ObjectGuid) {
        let Some(me) = self.unit_position(guid) else {
            return;
        };
        let players: Vec<ObjectGuid> = self.players.keys().copied().collect();
        for player in players {
            if !self.unit_is_alive(player) {
                continue;
            }
            if let Some(pp) = self.object_position(player) {
                let dx = pp.x - me.x;
                let dy = pp.y - me.y;
                if dx * dx + dy * dy <= 55.0 * 55.0 {
                    self.enter_combat(guid, player);
                }
            }
        }
    }

    /// `npc_resonating_CrystalAI::UpdateAI` (769-816).
    fn resonating_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let detected = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::ResonatingCrystal(s)) if s.player_detected)
        });
        if detected {
            let due = {
                let Some(s) = self.resonating_state_mut(guid) else {
                    return;
                };
                if s.check_timer_ms < diff_ms {
                    true
                } else {
                    s.check_timer_ms -= diff_ms;
                    false
                }
            };
            if due {
                if self.resonating_many_players(guid) {
                    self.resonating_aggro_all_near(guid);
                } else {
                    // NEEDS-MAP-HELPER: fork `EnterEvadeMode()`; base evade resets
                    // via the dispatcher after the pre-base hook (none here).
                    self.enter_evade_mode(guid);
                }
                if let Some(s) = self.resonating_state_mut(guid) {
                    s.check_timer_ms = 2000;
                }
            }
        }
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let due = {
            let Some(s) = self.resonating_state_mut(guid) else {
                return;
            };
            if s.whisperings_timer_ms < diff_ms {
                true
            } else {
                s.whisperings_timer_ms -= diff_ms;
                false
            }
        };
        if due {
            // NEEDS-MAP-HELPER: fork skips targets charmed by the crystal
            // (`GetCharmGuid`) via `SELECT_FLAG_POLYMORPHED`; none found.
            if let Some(target) = self.select_random_hostile(guid) {
                let whisper = self
                    .resonating_state_mut(guid)
                    .map_or(RESON_SPELL_WHISPER_4, |s| s.whisper_spell);
                self.do_cast_spell_if_can(guid, whisper, CastTarget::Unit(target));
            }
            if let Some(s) = self.resonating_state_mut(guid) {
                s.whisperings_timer_ms = 20_000;
            }
        }
    }

