    /// `npc_infantrymanAI::JustDied` (874-893): respawn seat (followers) +
    /// unconditional Saurfang vengeance.
    fn infantryman_just_died(&mut self, guid: ObjectGuid) {
        let following = self.ai.get(&guid).is_some_and(|ai| {
            matches!(
                &ai.script,
                Some(
                    CreatureScriptAi::IronforgeInfantry(s)
                    | CreatureScriptAi::OrgrimmarInfantry(s)
                    | CreatureScriptAi::OrgrimmarRifleman(s)
                    | CreatureScriptAi::Priestess(s),
                ) if s.following_saurfang
            )
        });
        if following {
            // NEEDS-MAP-HELPER: fork `SetRespawnNearSaurfang()` (home re-math from
            // `saurfang_dist`/`saurfang_angle` + `saurfang_guid`); none found.
            // Fields read so the wiring stays live.
            let (_dist, _angle, _saurfang) = self
                .infantryman_state_mut(guid)
                .map_or((0.0, 0.0, None), |s| {
                    (s.saurfang_dist, s.saurfang_angle, s.saurfang_guid)
                });
        }
        // Vengeance: nearest SAURFANG (14720) within 30, in combat, without the
        // spell takes emote + one random say + the buff (texts target the dead).
        let me = self.unit_position(guid).unwrap_or_default();
        let saurfang = self
            .creatures
            .values()
            .filter(|c| c.info.entry == WE_NPC_SAURFANG && c.unit.is_alive())
            .map(|c| {
                let p = c.unit.world.position();
                let dx = p.x - me.x;
                let dy = p.y - me.y;
                (c.unit.guid(), dx * dx + dy * dy)
            })
            .filter(|(_, d)| *d <= 30.0 * 30.0)
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .map(|(g, _)| g);
        if let Some(saurfang) = saurfang {
            if self.unit_victim(saurfang).is_some() {
                // NEEDS-MAP-HELPER: fork `HasAura(SF_VENGEANCE)`; none found.
                self.do_script_text(
                    WE_BCT_SAURFANG_FRIENDLY_DIED_EMOTE,
                    saurfang,
                    Some(guid),
                    -1,
                );
                let say = if self.rng.urand(0, 1) == 0 {
                    WE_BCT_SAURFANG_FRIENDLY_DIED_SAY1
                } else {
                    WE_BCT_SAURFANG_FRIENDLY_DIED_SAY2
                };
                self.do_script_text(say, saurfang, Some(guid), -1);
                self.do_cast_spell_if_can(saurfang, WE_SPELL_SF_VENGEANCE, CastTarget::SelfCast);
            }
        }
    }

