    /// `npc_infantrymanAI::MoveToWaveBattlePosition` (960-1010).
    fn infantryman_move_to_wave(&mut self, guid: ObjectGuid) {
        let kind = self.infantryman_state_mut(guid).map_or(0, |s| s.kind);
        // NEEDS-MAP-HELPER: fork home-position march math
        // (`SetHomePosition`/`MoveTargetedHome`/`MovePoint` by wave side); none
        // found. Origin + clockwise read so the wiring stays live.
        let _origin = InfantrymanAi::origin(kind);
        let clockwise = self
            .infantryman_state_mut(guid)
            .is_some_and(|s| s.clockwise);
        let _ = clockwise;
        if kind == 3 {
            // Priestess line-up: origin + align/10 * index (1111-1136).
            let index = self
                .infantryman_state_mut(guid)
                .map_or(0, |s| s.priest_index);
            let ax = (WE_PRIESTESS_EX - WE_PRIESTESS_OX) / 10.0 * f32::from(index);
            let ay = (WE_PRIESTESS_EY - WE_PRIESTESS_OY) / 10.0 * f32::from(index);
            let az = (WE_PRIESTESS_EZ - WE_PRIESTESS_OZ) / 10.0 * f32::from(index);
            let _ = (
                WE_PRIESTESS_OX + ax,
                WE_PRIESTESS_OY + ay,
                WE_PRIESTESS_OZ + az,
            );
        }
        if let Some(s) = self.infantryman_state_mut(guid) {
            s.moved_into_position = true;
        }
    }

