    /// `npc_infantrymanAI::UpdateAI` (905-940): event-gated march + base combat.
    fn infantryman_update(&mut self, guid: ObjectGuid, _diff_ms: u32) {
        // NEEDS-MAP-HELPER: fork gates on `EVENT_WAR_EFFORT_CH_ATTACK` (59) /
        // `FINALBATTLE` (61); no game-event helper found, arms run unconditionally.
        let _ = (WE_EVENT_CH_ATTACK, WE_EVENT_FINALBATTLE);
        let moved = self.ai.get(&guid).is_some_and(|ai| {
            matches!(
                &ai.script,
                Some(
                    CreatureScriptAi::IronforgeInfantry(s)
                    | CreatureScriptAi::OrgrimmarInfantry(s)
                    | CreatureScriptAi::OrgrimmarRifleman(s)
                    | CreatureScriptAi::Priestess(s),
                ) if s.moved_into_position
            )
        });
        if !moved {
            self.infantryman_move_to_wave(guid);
        }
        // Final-battle arm latches `following` then follows every tick.
        if let Some(s) = self.infantryman_state_mut(guid) {
            s.following_saurfang = true;
        }
        self.infantryman_follow_saurfang(guid);
        let Some(_victim) = self.script_combat_drive(guid, true) else {
            return;
        };
    }

