    /// 1339-1417 movement + combat).
    #[allow(clippy::too_many_lines)] // fork UpdateAI transcription
    fn saurfang_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        // Speech machine (1303-1337).
        let in_speech = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Saurfang(s)) if s.in_speech),
        );
        if in_speech {
            let due = {
                let Some(s) = self.saurfang_state_mut(guid) else {
                    return;
                };
                if s.speech_delay_ms < diff_ms {
                    true
                } else {
                    s.speech_delay_ms -= diff_ms;
                    false
                }
            };
            if due {
                let step = self.saurfang_state_mut(guid).map_or(99, |s| s.speech_step);
                // NEEDS-MAP-HELPER: fork `BroadcastTextToZone`; kept as
                // `do_script_text` zone yell (reviewer to confirm routing).
                self.do_script_text(
                    Self::saurfang_speech_text(step),
                    guid,
                    None,
                    SI_CHAT_ZONE_YELL,
                );
                let done = step >= 13;
                if let Some(s) = self.saurfang_state_mut(guid) {
                    s.speech_step += 1;
                    s.speech_delay_ms = 8000;
                    if done {
                        s.in_speech = false;
                    }
                }
            }
        }
        // NEEDS-MAP-HELPER: fork `EVENT_GATES` / final-battle / cenarion-warn
        // game-event gates (`DoScriptText(FINAL_BATTLE)`, `SetImmuneToPlayer`,
        // `MoveToWaveBattlePosition`); none found. Fields read to stay live.
        let (_warn, _final) = self
            .saurfang_state_mut(guid)
            .map_or((false, false), |s| (s.cenarion_warn, s.final_battle));
        // Gate march (1235-1254 region): chain `MovePoint`s while unpaused.
        let marching = self.ai.get(&guid).is_some_and(|ai| {
            matches!(&ai.script, Some(CreatureScriptAi::Saurfang(s)) if s.moving_to_gate && s.move_point_reached && !s.movement_paused)
        });
        if marching {
            let point = self.saurfang_state_mut(guid).map_or(99, |s| s.move_point);
            if let Some((x, y, z)) = Self::saurfang_gate_point(point) {
                // NEEDS-MAP-HELPER: fork `SetWalk(true)`; none found.
                self.creature_move_point(guid, point, Position::new(x, y, z, 0.0), 0, 0.0, 0.0);
                if let Some(s) = self.saurfang_state_mut(guid) {
                    s.move_point_reached = false;
                    if point < 11 {
                        s.move_point = point + 1;
                    } else {
                        // NEEDS-MAP-HELPER: fork `SetHomePosition` + walk off +
                        // `MoveTargetedHome`; arrival only recorded here.
                        s.moving_to_gate = false;
                    }
                }
            }
        }
        // Combat rot (1339+; drive + melee; fork `ScriptedAI::UpdateAI` tail).
        let last_wave = self.ai.get(&guid).is_some_and(
            |ai| matches!(&ai.script, Some(CreatureScriptAi::Saurfang(s)) if s.last_wave),
        );
        if !last_wave {
            return;
        }
        let Some(victim) = self.script_combat_drive(guid, true) else {
            return;
        };
        let strike_due = {
            let Some(s) = self.saurfang_state_mut(guid) else {
                return;
            };
            if s.mortal_strike_timer_ms < diff_ms {
                true
            } else {
                s.mortal_strike_timer_ms -= diff_ms;
                false
            }
        };
        if strike_due
            && self.do_cast_spell_if_can(guid, WE_SPELL_SF_MORTAL_STRIKE, CastTarget::Unit(victim))
        {
            let next = self.rng.urand(2000, 4000);
            if let Some(s) = self.saurfang_state_mut(guid) {
                s.mortal_strike_timer_ms = next;
            }
        }
        let roar_due = {
            let Some(s) = self.saurfang_state_mut(guid) else {
                return;
            };
            if s.roar_timer_ms < diff_ms {
                true
            } else {
                s.roar_timer_ms -= diff_ms;
                false
            }
        };
        if roar_due
            && self.do_cast_spell_if_can(guid, WE_SPELL_SF_TERRIFYING_ROAR, CastTarget::SelfCast)
        {
            let next = self.rng.urand(7000, 16_000);
            if let Some(s) = self.saurfang_state_mut(guid) {
                s.roar_timer_ms = next;
            }
        }
        let charge_due = {
            let Some(s) = self.saurfang_state_mut(guid) else {
                return;
            };
            if s.charge_timer_ms < diff_ms {
                true
            } else {
                s.charge_timer_ms -= diff_ms;
                false
            }
        };
        if charge_due {
            // NEEDS-MAP-HELPER: fork `GetVictimInRange(8, 25)` + `IsValidAttackTarget`;
            // victim used directly.
            if self.do_cast_spell_if_can(guid, WE_SPELL_SF_CHARGE, CastTarget::Unit(victim)) {
                let next = self.rng.urand(6000, 10_000);
                if let Some(s) = self.saurfang_state_mut(guid) {
                    s.charge_timer_ms = next;
                }
            }
        }
        let cleave_due = {
            let Some(s) = self.saurfang_state_mut(guid) else {
                return;
            };
            if s.cleave_timer_ms < diff_ms {
                true
            } else {
                s.cleave_timer_ms -= diff_ms;
                false
            }
        };
        if cleave_due
            && self.do_cast_spell_if_can(guid, WE_SPELL_SF_CLEAVE, CastTarget::Unit(victim))
        {
            let next = self.rng.urand(4000, 8000);
            if let Some(s) = self.saurfang_state_mut(guid) {
                s.cleave_timer_ms = next;
            }
        }
    }

    /// `npc_aqwar_cenarionhold_attackAI::Reset` (empty) + `UpdateAI` (1458-1502).
    #[allow(clippy::unused_self)]
    fn cenarion_reset(&mut self, _guid: ObjectGuid) {}

    #[allow(clippy::cast_precision_loss)]
    fn cenarion_update(&mut self, guid: ObjectGuid, diff_ms: u32) {
        let due = {
            let Some(s) = self.cenarion_state_mut(guid) else {
                return;
            };
            if s.time_until_wave_ms < diff_ms {
                true
            } else {
                s.time_until_wave_ms -= diff_ms;
                false
            }
        };
        if !due {
            return;
        }
        let (wave, max) = self
            .cenarion_state_mut(guid)
            .map_or((99, 0), |s| (s.wave_count, s.max_wave_count));
        if wave > max {
            return;
        }
        // NEEDS-MAP-HELPER: fork checks `BATTLE_HAS_BEGUN` + target-zone player
        // presence; none found, waves run unconditionally.
        let Some(me) = self.unit_position(guid) else {
            return;
        };
        for _ in 0..10 {
            // Fork entry: `urand(0, 5) ? ANUBISATH : DESTROYER`.
            let entry = if self.rng.urand(0, 5) != 0 {
                WE_NPC_COLOSSAL_ANUBISATH
            } else {
                WE_NPC_QIRAJI_DESTROYER
            };
            // NEEDS-MAP-HELPER: fork `irand(-70, 70)/10` jitter + ground-height
            // (`GetHeight`) + `MovePoint` home + `MoveTargetedHome`; jitter via
            // `spell_rng`, height/home dropped.
            let jx = self.spell_rng().irand(-70, 70) as f32 / 10.0;
            let jy = self.spell_rng().irand(-70, 70) as f32 / 10.0;
            let created = self.summon_creature(
                entry,
                Position::new(me.x + jx, me.y + jy, me.z, 0.0),
                guid,
                WE_TEMPSUMMON_CORPSE_TIMED,
                240_000,
            );
            let _ = created;
        }
        let text = WE_BCT_QIRAJI_SUMMONED[(self.rng.urand(0, 3)) as usize];
        self.do_script_text(text, guid, None, -1);
        if let Some(s) = self.cenarion_state_mut(guid) {
            s.wave_count += 1;
            s.time_until_wave_ms = 60_000;
            if s.wave_count > s.max_wave_count {
                // NEEDS-MAP-HELPER: fork writes `m_lastWave` on the saurfang AI;
                // cross-AI write needs the Saurfang accessor (integrator, NOTE-1).
            }
        }
    }

    // ---- totems ----

    /// `TotemGlebeAI::SpellHit` (totems.cpp 13-20). STATELESS (`TotemAI` base,
    /// NOTE-9): foreign auras are stripped.
    fn totem_glebe_spell_hit(&mut self, guid: ObjectGuid, _caster: ObjectGuid, spell_id: u32) {
        if spell_id != GLEBE_SPELL_BUFF_PASSIVE && spell_id != GLEBE_SPELL_BUFF {
            self.cancel_aura(guid, spell_id);
            self.cancel_aura(guid, GLEBE_SPELL_BUFF);
        }
    }
